package agentsdk_hello

import (
	"context"
	"os"
	"strings"
	"testing"

	"github.com/gratefulagents/sdk/pkg/agentsdk"
	sdkopenai "github.com/gratefulagents/sdk/pkg/agentsdk/providers/openai"
)

func TestHelloWorldWithOpenAIProvider(t *testing.T) {
	if liveTestsSkipped() {
		t.Skip("GRATEFUL_LIVE_TESTS=skip")
	}
	apiKey := strings.TrimSpace(os.Getenv("OPENAI_API_KEY"))
	authMode := strings.TrimSpace(os.Getenv("OPENAI_AUTH_MODE"))
	if apiKey == "" && !strings.EqualFold(authMode, string(sdkopenai.AuthModeOAuth)) {
		t.Skip("set OPENAI_API_KEY or OPENAI_AUTH_MODE=oauth to run this OpenAI integration example")
	}

	model := strings.TrimSpace(os.Getenv("OPENAI_HELLO_MODEL"))
	if model == "" {
		model = sdkopenai.DefaultChatModel
	}

	providerConfig := sdkopenai.ProviderConfig{
		BaseURL: strings.TrimSpace(os.Getenv("OPENAI_BASE_URL")),
		APIKey:  apiKey,
		APIMode: strings.TrimSpace(os.Getenv("OPENAI_API_MODE")),
	}
	if strings.EqualFold(authMode, string(sdkopenai.AuthModeOAuth)) {
		authPath := strings.TrimSpace(os.Getenv("OPENAI_OAUTH_AUTH_JSON_PATH"))
		if authPath == "" {
			t.Skip("set OPENAI_OAUTH_AUTH_JSON_PATH to run this OpenAI OAuth integration example")
		}
		session, err := sdkopenai.NewOAuthAuthSessionFromConfig(sdkopenai.OAuthSessionConfig{
			AuthJSONPath:  authPath,
			AccountID:     strings.TrimSpace(os.Getenv("OPENAI_OAUTH_ACCOUNT_ID")),
			AccountIDPath: strings.TrimSpace(os.Getenv("OPENAI_OAUTH_ACCOUNT_ID_PATH")),
		})
		if err != nil {
			t.Fatal(err)
		}
		providerConfig.AuthMode = sdkopenai.AuthModeOAuth
		providerConfig.AuthSession = session
		if providerConfig.BaseURL == "" {
			providerConfig.BaseURL = "https://chatgpt.com/backend-api/codex"
		}
	}
	provider := sdkopenai.NewProviderWithConfig(providerConfig)
	runner := agentsdk.NewRunnerWithProvider(provider)

	result, err := runner.Run(context.Background(), &agentsdk.Agent{
		Name:         "hello",
		Model:        model,
		Instructions: "Reply with exactly: hello world",
	}, []agentsdk.RunItem{
		{
			Type:    agentsdk.RunItemMessage,
			Message: &agentsdk.MessageOutput{Text: "Say hello world."},
		},
	}, agentsdk.RunConfig{
		MaxTurns:      1,
		ModelSettings: agentsdk.ModelSettings{MaxTokens: 16, ReasoningEffort: "low"},
	})
	if err != nil {
		t.Fatal(err)
	}

	if got := strings.TrimSpace(strings.ToLower(result.FinalText())); got != "hello world" {
		t.Fatalf("FinalText() = %q, want %q", result.FinalText(), "hello world")
	}
}

func liveTestsSkipped() bool {
	return strings.EqualFold(strings.TrimSpace(os.Getenv("GRATEFUL_LIVE_TESTS")), "skip")
}

package anthropic_api

import (
	"context"
	"os"
	"strings"
	"testing"

	"github.com/gratefulagents/sdk/pkg/agentsdk"
	sdkanthropic "github.com/gratefulagents/sdk/pkg/agentsdk/providers/anthropic"
)

func TestHelloWorldWithAnthropicAPIKey(t *testing.T) {
	if liveTestsSkipped() {
		t.Skip("GRATEFUL_LIVE_TESTS=skip")
	}
	apiKey := strings.TrimSpace(os.Getenv("ANTHROPIC_API_KEY"))
	if apiKey == "" {
		t.Skip("set ANTHROPIC_API_KEY to run this Anthropic API-key example")
	}

	model := envOr("ANTHROPIC_MODEL", "claude-haiku-4-5")
	provider := sdkanthropic.NewProviderWithConfig(sdkanthropic.ProviderConfig{
		APIKey:  apiKey,
		BaseURL: strings.TrimSpace(os.Getenv("ANTHROPIC_BASE_URL")),
	})
	runner := agentsdk.NewRunnerWithProvider(provider)

	result, err := runner.Run(context.Background(), helloAgent(model), helloInput(), helloConfig())
	if err != nil {
		t.Fatal(err)
	}

	requireHelloWorld(t, result.FinalText())
}

func helloAgent(model string) *agentsdk.Agent {
	return &agentsdk.Agent{
		Name:         "hello-anthropic-api",
		Model:        model,
		Instructions: "Reply with exactly: hello world",
	}
}

func helloInput() []agentsdk.RunItem {
	return []agentsdk.RunItem{
		{
			Type:    agentsdk.RunItemMessage,
			Message: &agentsdk.MessageOutput{Text: "Say hello world."},
		},
	}
}

func helloConfig() agentsdk.RunConfig {
	return agentsdk.RunConfig{
		MaxTurns:      1,
		ModelSettings: agentsdk.ModelSettings{MaxTokens: 32},
	}
}

func requireHelloWorld(t *testing.T, text string) {
	t.Helper()

	if got := normalize(text); got != "hello world" {
		t.Fatalf("FinalText() = %q, want %q", text, "hello world")
	}
}

func normalize(text string) string {
	return strings.Trim(strings.TrimSpace(strings.ToLower(text)), ".!")
}

func envOr(key, fallback string) string {
	if value := strings.TrimSpace(os.Getenv(key)); value != "" {
		return value
	}
	return fallback
}

func liveTestsSkipped() bool {
	return strings.EqualFold(strings.TrimSpace(os.Getenv("GRATEFUL_LIVE_TESTS")), "skip")
}

package agent_runtime_test

import (
	"context"
	"encoding/json"
	"errors"
	"strings"
	"sync/atomic"
	"testing"

	"github.com/gratefulagents/sdk/examples/features/internal/liverunner"
	"github.com/gratefulagents/sdk/pkg/agentsdk"
)

func TestAgentRuntimeExample(t *testing.T) {
	runner, model := liverunner.Runner(t)

	agent := &agentsdk.Agent{
		Name:  "runtime",
		Model: model,
		InstructionsFn: func(_ *agentsdk.RunContext, agent *agentsdk.Agent) string {
			return "You MUST reply with exactly the single word READY in upper case. No punctuation. Agent name: " + agent.Name
		},
		ModelSettings: agentsdk.ModelSettings{MaxTokens: 64},
	}

	result, err := runner.Run(context.Background(), agent, []agentsdk.RunItem{
		{
			Type:    agentsdk.RunItemMessage,
			Message: &agentsdk.MessageOutput{Text: "Confirm the runtime is ready."},
		},
	}, agentsdk.RunConfig{
		MaxTurns: 1,

		ModelSettings: agentsdk.ModelSettings{ReasoningEffort: "low"},
	})
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(strings.ToUpper(result.FinalText()), "READY") {
		t.Fatalf("FinalText() = %q, want sentinel READY", result.FinalText())
	}
	if result.LastAgent.Name != "runtime" || len(result.RawResponses) == 0 {
		t.Fatalf("unexpected run result: %+v", result)
	}
	if result.Usage.OutputTokens == 0 {
		t.Fatalf("expected non-zero output tokens, got %+v", result.Usage)
	}
}

type recordingHooks struct {
	agentsdk.NoOpRunHooks
	starts   int
	ends     int
	llmStart int
	llmEnd   int
	toolStrt int
	toolEnd  int
}

func (h *recordingHooks) OnAgentStart(_ *agentsdk.RunContext, _ *agentsdk.Agent) { h.starts++ }
func (h *recordingHooks) OnAgentEnd(_ *agentsdk.RunContext, _ *agentsdk.Agent, _ any) {
	h.ends++
}
func (h *recordingHooks) OnLLMStart(_ *agentsdk.RunContext, _ *agentsdk.Agent) { h.llmStart++ }
func (h *recordingHooks) OnLLMEnd(_ *agentsdk.RunContext, _ *agentsdk.Agent, _ *agentsdk.ModelResponse) {
	h.llmEnd++
}
func (h *recordingHooks) OnToolStart(_ *agentsdk.RunContext, _ *agentsdk.Agent, _ agentsdk.Tool, _ agentsdk.ToolCallData) {
	h.toolStrt++
}
func (h *recordingHooks) OnToolEnd(_ *agentsdk.RunContext, _ *agentsdk.Agent, _ agentsdk.Tool, _ agentsdk.ToolCallData, _ agentsdk.ToolResult) {
	h.toolEnd++
}

func TestAgentRuntimeMultiTurnToolLoop(t *testing.T) {
	runner, model := liverunner.Runner(t)

	var calls atomic.Int32
	pingTool := &agentsdk.FunctionTool{
		ToolName:        "ping",
		ToolDescription: "Pings a target. Always call this when asked to ping.",
		Schema:          json.RawMessage(`{"type":"object","properties":{"who":{"type":"string"}},"required":["who"]}`),
		ReadOnly:        true,
		Fn: func(_ context.Context, input json.RawMessage) (string, error) {
			calls.Add(1)
			var p struct {
				Who string `json:"who"`
			}
			if err := json.Unmarshal(input, &p); err != nil {
				return "", err
			}
			return "ack:" + p.Who, nil
		},
	}

	hooks := &recordingHooks{}
	result, err := runner.Run(context.Background(), &agentsdk.Agent{
		Name:         "ping-agent",
		Model:        model,
		Instructions: "When asked to ping, call the ping tool with who=<target>, then respond confirming the ack.",
		Tools:        []agentsdk.Tool{pingTool},
	}, []agentsdk.RunItem{{
		Type:    agentsdk.RunItemMessage,
		Message: &agentsdk.MessageOutput{Text: "Ping the target named world via the ping tool, then summarize the ack."},
	}}, agentsdk.RunConfig{MaxTurns: 5, Hooks: hooks})
	if err != nil {
		t.Fatal(err)
	}

	if result.FinalText() == "" {
		t.Fatalf("FinalText empty")
	}
	if calls.Load() == 0 {
		t.Fatalf("expected ping tool to be called by live model")
	}
	var sawToolOutput bool
	for _, item := range result.NewItems {
		if item.Type == agentsdk.RunItemToolOutput && item.ToolOutput != nil && strings.Contains(item.ToolOutput.Content, "ack:") {
			sawToolOutput = true
		}
	}
	if !sawToolOutput {
		t.Fatalf("expected tool output in items: %#v", result.NewItems)
	}
	if hooks.starts == 0 || hooks.ends == 0 {
		t.Fatalf("agent hooks did not fire: starts=%d ends=%d", hooks.starts, hooks.ends)
	}
	if hooks.llmStart < 2 || hooks.llmEnd < 2 {
		t.Fatalf("LLM hooks fired %d/%d, want >=2", hooks.llmStart, hooks.llmEnd)
	}
	if hooks.toolStrt < 1 || hooks.toolEnd < 1 {
		t.Fatalf("tool hooks fired start=%d end=%d, want >=1", hooks.toolStrt, hooks.toolEnd)
	}
}

func TestAgentRuntimeMaxTurnsExceeded(t *testing.T) {
	runner, model := liverunner.Runner(t)

	loopTool := &agentsdk.FunctionTool{
		ToolName:        "loop",
		ToolDescription: "You must always call this tool again immediately.",
		Schema:          json.RawMessage(`{"type":"object","properties":{},"additionalProperties":false}`),
		ReadOnly:        true,
		Fn: func(_ context.Context, _ json.RawMessage) (string, error) {
			return "call loop again immediately", nil
		},
	}

	_, err := runner.Run(context.Background(), &agentsdk.Agent{
		Name:         "looper",
		Model:        model,
		Instructions: "On every turn you MUST call the loop tool. Never reply with a final message.",
		Tools:        []agentsdk.Tool{loopTool},
	}, []agentsdk.RunItem{{
		Type:    agentsdk.RunItemMessage,
		Message: &agentsdk.MessageOutput{Text: "Begin: call the loop tool repeatedly."},
	}}, agentsdk.RunConfig{MaxTurns: 1})

	if err == nil {
		t.Fatal("expected MaxTurnsExceeded error, got nil")
	}
	var maxTurns *agentsdk.MaxTurnsExceeded
	if !errors.As(err, &maxTurns) {
		t.Fatalf("expected *agentsdk.MaxTurnsExceeded, got %T: %v", err, err)
	}
	if maxTurns.MaxTurns != 1 {
		t.Fatalf("MaxTurnsExceeded.MaxTurns = %d, want 1", maxTurns.MaxTurns)
	}
}

package chatloop_test

import (
	"context"
	"strings"
	"testing"

	"github.com/gratefulagents/sdk/examples/features/internal/liverunner"
	"github.com/gratefulagents/sdk/pkg/agentsdk"
)

type memorySession struct {
	messages []agentsdk.UserMessage
	items    []agentsdk.RunItem
}

func (s *memorySession) LoadMessages(context.Context, agentsdk.Cursor, int) ([]agentsdk.UserMessage, agentsdk.Cursor, error) {
	return append([]agentsdk.UserMessage(nil), s.messages...), agentsdk.Cursor{}, nil
}

func (s *memorySession) AppendRunItems(_ context.Context, items []agentsdk.RunItem) error {
	s.items = append(s.items, items...)
	return nil
}

func (s *memorySession) WorkingState(context.Context) (agentsdk.WorkingState, error) {
	return agentsdk.WorkingState{CurrentStep: "demo"}, nil
}

func TestChatLoopExample(t *testing.T) {
	runner, model := liverunner.Runner(t)
	session := &memorySession{messages: []agentsdk.UserMessage{{ID: 1, Content: "Reply with exactly the single word PINEAPPLE in upper case."}}}

	result, err := agentsdk.NewChatLoop(agentsdk.ChatLoopOptions{
		Runner:       runner,
		SessionStore: session,
		Agent: &agentsdk.Agent{
			Name:         "chatloop-demo",
			Model:        model,
			Instructions: "Follow the user's exact instruction.",
		},
		RunConfig: agentsdk.RunConfig{MaxTurns: 2},
	}).Run(context.Background())
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(strings.ToUpper(result.FinalText()), "PINEAPPLE") {
		t.Fatalf("FinalText() = %q, want sentinel PINEAPPLE", result.FinalText())
	}
	var sawAssistantMessage bool
	for _, item := range session.items {
		if item.Type == agentsdk.RunItemMessage && item.Message != nil &&
			strings.Contains(strings.ToUpper(item.Message.Text), "PINEAPPLE") {
			sawAssistantMessage = true
			break
		}
	}
	if !sawAssistantMessage {
		t.Fatalf("expected loop to persist an assistant message containing PINEAPPLE in session.items: %#v", session.items)
	}
}

package context_compaction_test

import (
	"strings"
	"testing"

	"github.com/gratefulagents/sdk/pkg/agentsdk"
)

func TestContextCompactionExample(t *testing.T) {
	var items []agentsdk.RunItem
	for i := 0; i < 24; i++ {
		items = append(items, agentsdk.RunItem{
			Type:    agentsdk.RunItemMessage,
			Message: &agentsdk.MessageOutput{Text: strings.Repeat("important project context ", 20)},
		})
	}

	compacted, before, after, ok, reason := agentsdk.MaybeCompactRunItems(items, agentsdk.CompactionConfig{
		Enabled:                     true,
		TriggerTokens:               100,
		TargetTokens:                60,
		PreserveRecentItems:         4,
		PreserveInitialUserMessages: 1,
		SummaryBulletLimit:          3,
	})
	if !ok {
		t.Fatalf("compaction did not run: reason=%s before=%d after=%d", reason, before, after)
	}
	if len(compacted) >= len(items) || after >= before {
		t.Fatalf("ineffective compaction: len %d -> %d tokens %d -> %d", len(items), len(compacted), before, after)
	}
	if summary := agentsdk.ExtractCompactionSummary(compacted); !strings.Contains(summary, "[COMPACTED HISTORY SUMMARY]") {
		t.Fatalf("summary missing: %q", summary)
	}

	trigger, target := agentsdk.CompactionDefaultsForModel("gpt-5.6-sol")
	if trigger <= target {
		t.Fatalf("defaults should trigger above target: trigger=%d target=%d", trigger, target)
	}
}

package costs_test

import (
	"context"
	"testing"

	"github.com/gratefulagents/sdk/examples/features/internal/liverunner"
	"github.com/gratefulagents/sdk/pkg/agentsdk"
	sdkanthropic "github.com/gratefulagents/sdk/pkg/agentsdk/providers/anthropic"
	sdkopenai "github.com/gratefulagents/sdk/pkg/agentsdk/providers/openai"
)

func TestCostsExample(t *testing.T) {
	runner, model := liverunner.Runner(t)

	result, err := runner.Run(context.Background(), &agentsdk.Agent{
		Name:         "costed",
		Model:        model,
		Instructions: "Reply with a single short sentence.",
	}, []agentsdk.RunItem{
		{
			Type:    agentsdk.RunItemMessage,
			Message: &agentsdk.MessageOutput{Text: "Say hello."},
		},
	}, agentsdk.RunConfig{MaxTurns: 1})
	if err != nil {
		t.Fatal(err)
	}
	if result.Usage.InputTokens == 0 && result.Usage.OutputTokens == 0 {
		t.Fatalf("expected non-zero token usage, got %+v", result.Usage)
	}
	if len(result.RawResponses) == 0 {
		t.Fatal("expected at least one raw response")
	}

	// Exercise the public cost-estimator surface against the real usage we got
	// back from the live model. We don't pin a specific dollar amount because
	// the live model name and price table can drift; we just assert that the
	// estimator returns a positive number for known models.
	openAICost, known := sdkopenai.EstimateCost("gpt-4.1-mini", result.Usage)
	if !known || openAICost <= 0 {
		t.Fatalf("OpenAI cost estimate failed: cost=%f known=%v", openAICost, known)
	}
	if anthropicCost := sdkanthropic.CalculateCost("claude-haiku-4-5", result.Usage); anthropicCost <= 0 {
		t.Fatalf("Anthropic cost estimate failed: cost=%f", anthropicCost)
	}
}

// Package errors_retries_test exercises retry-on-error behavior. Live
// providers cannot be made to return controlled errors deterministically, so
// this file uses a tiny in-test fake model to drive the SDK's retry plumbing.
// The retry-policy math itself is provider-agnostic, so a fake model is the
// correct level of abstraction for the example.
package errors_retries_test

import (
	"context"
	"errors"
	"sync"
	"testing"
	"time"

	"github.com/gratefulagents/sdk/pkg/agentsdk"
)

type retryFakeModel struct {
	mu          sync.Mutex
	calls       int
	errors      []error
	responses   []*agentsdk.ModelResponse
	retryAdvice *agentsdk.ModelRetryAdvice
}

func (m *retryFakeModel) Provider() string                       { return "fake" }
func (m *retryFakeModel) CalculateCost(_ agentsdk.Usage) float64 { return 0 }

func (m *retryFakeModel) GetRetryAdvice(err error) *agentsdk.ModelRetryAdvice {
	if err == nil {
		return nil
	}
	if m.retryAdvice != nil {
		advice := *m.retryAdvice
		return &advice
	}
	return &agentsdk.ModelRetryAdvice{ShouldRetry: true}
}

func (m *retryFakeModel) GetResponse(_ context.Context, _ agentsdk.ModelRequest) (*agentsdk.ModelResponse, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	idx := m.calls
	m.calls++
	if idx < len(m.errors) && m.errors[idx] != nil {
		return nil, m.errors[idx]
	}
	if idx < len(m.responses) && m.responses[idx] != nil {
		return m.responses[idx], nil
	}
	return m.responses[len(m.responses)-1], nil
}

func (m *retryFakeModel) StreamResponse(ctx context.Context, req agentsdk.ModelRequest) (*agentsdk.ModelStream, error) {
	resp, err := m.GetResponse(ctx, req)
	if err != nil {
		return nil, err
	}
	events := make(chan agentsdk.ModelStreamEvent, 1)
	events <- agentsdk.ModelStreamEvent{Type: agentsdk.ModelStreamComplete, Response: resp}
	close(events)
	done := make(chan *agentsdk.ModelResponse, 1)
	done <- resp
	close(done)
	return agentsdk.NewModelStream(events, done), nil
}

func textResp(text string) *agentsdk.ModelResponse {
	return &agentsdk.ModelResponse{
		Items: []agentsdk.RunItem{{Type: agentsdk.RunItemMessage, Message: &agentsdk.MessageOutput{Text: text}}},
	}
}

func TestProviderRetryAdviceExample(t *testing.T) {
	transient := errors.New("temporary provider outage")
	model := &retryFakeModel{
		errors:      []error{transient, nil},
		responses:   []*agentsdk.ModelResponse{nil, textResp("recovered")},
		retryAdvice: &agentsdk.ModelRetryAdvice{ShouldRetry: true, RetryAfterMS: 0, Reason: "temporary"},
	}
	runner := agentsdk.NewRunnerWithModel(model)
	result, err := runner.Run(context.Background(), &agentsdk.Agent{
		Name:         "retrying",
		Model:        "fake",
		Instructions: "Recover from transient errors.",
	}, []agentsdk.RunItem{
		{
			Type:    agentsdk.RunItemMessage,
			Message: &agentsdk.MessageOutput{Text: "Try once, then recover."},
		},
	}, agentsdk.RunConfig{MaxTurns: 2})
	if err != nil {
		t.Fatal(err)
	}
	if result.FinalText() != "recovered" {
		t.Fatalf("FinalText() = %q", result.FinalText())
	}
	if model.calls != 2 {
		t.Fatalf("calls = %d, want 2", model.calls)
	}
}

func TestStandaloneRetryPolicyExample(t *testing.T) {
	policy := agentsdk.DefaultRetryPolicy()
	if policy.MaxRetries != 3 {
		t.Fatalf("MaxRetries = %d", policy.MaxRetries)
	}
	if got := policy.DelayForAttempt(2); got != 4*time.Second {
		t.Fatalf("DelayForAttempt(2) = %s, want 4s", got)
	}
}

func TestRunConfigRetryPolicyExample(t *testing.T) {
	model := &retryFakeModel{
		errors:    []error{errors.New("temporary"), nil},
		responses: []*agentsdk.ModelResponse{nil, textResp("policy recovered")},
	}
	runner := agentsdk.NewRunnerWithModel(model)
	policy := agentsdk.DefaultRetryPolicy()
	policy.MaxRetries = 1
	policy.Backoff.InitialDelayMS = 0
	policy.Backoff.MaxDelayMS = 0

	result, err := runner.Run(context.Background(), &agentsdk.Agent{
		Name:  "retry-policy",
		Model: "fake",
	}, nil, agentsdk.RunConfig{
		MaxTurns:    2,
		RetryPolicy: &policy,
	})
	if err != nil {
		t.Fatal(err)
	}
	if result.FinalText() != "policy recovered" {
		t.Fatalf("FinalText() = %q", result.FinalText())
	}
}

package guardrails_test

import (
	"context"
	"encoding/json"
	"errors"
	"strings"
	"testing"

	"github.com/gratefulagents/sdk/examples/features/internal/liverunner"
	"github.com/gratefulagents/sdk/pkg/agentsdk"
)

func TestGuardrailsExample(t *testing.T) {
	runner, model := liverunner.Runner(t)

	lookupTool := &agentsdk.FunctionTool{
		ToolName:        "lookup",
		ToolDescription: "Looks up safe data. Always call this when asked to look something up.",
		Schema:          json.RawMessage(`{"type":"object","properties":{"query":{"type":"string"}},"required":["query"]}`),
		ReadOnly:        true,
		Fn: func(context.Context, json.RawMessage) (string, error) {
			return "lookup result", nil
		},
	}
	agent := &agentsdk.Agent{
		Name:         "guarded",
		Model:        model,
		Instructions: "Use the lookup tool when asked, then return a brief safe answer.",
		Tools:        []agentsdk.Tool{lookupTool},
		InputGuardrails: []agentsdk.InputGuardrail{
			{
				Name: "no-secret-input",
				Fn: func(_ *agentsdk.RunContext, _ *agentsdk.Agent, input []agentsdk.RunItem) (*agentsdk.GuardrailResult, error) {
					return &agentsdk.GuardrailResult{Output: len(input)}, nil
				},
			},
		},
		OutputGuardrails: []agentsdk.OutputGuardrail{
			{
				Name: "safe-output",
				Fn: func(_ *agentsdk.RunContext, _ *agentsdk.Agent, output any) (*agentsdk.GuardrailResult, error) {
					text, _ := output.(string)
					return &agentsdk.GuardrailResult{
						Output:            "checked",
						TripwireTriggered: strings.Contains(text, "secret"),
					}, nil
				},
			},
		},
	}

	result, err := runner.Run(context.Background(), agent, []agentsdk.RunItem{
		{
			Type:    agentsdk.RunItemMessage,
			Message: &agentsdk.MessageOutput{Text: "Look up the weather for Paris using the lookup tool."},
		},
	}, agentsdk.RunConfig{
		MaxTurns: 4,

		ToolInputGuardrails: []agentsdk.ToolInputGuardrail{
			{
				Name: "lookup-query-present",
				Fn: func(_ *agentsdk.RunContext, _ *agentsdk.Agent, tool agentsdk.Tool, input json.RawMessage) (*agentsdk.GuardrailResult, error) {
					var params struct {
						Query string `json:"query"`
					}
					_ = json.Unmarshal(input, &params)
					return &agentsdk.GuardrailResult{Output: tool.Name(), TripwireTriggered: params.Query == ""}, nil
				},
			},
		},
		ToolOutputGuardrails: []agentsdk.ToolOutputGuardrail{
			{
				Name: "tool-output-safe",
				Fn: func(_ *agentsdk.RunContext, _ *agentsdk.Agent, _ agentsdk.Tool, result agentsdk.ToolResult) (*agentsdk.GuardrailResult, error) {
					return &agentsdk.GuardrailResult{Output: len(result.Content)}, nil
				},
			},
		},
	})
	if err != nil {
		t.Fatal(err)
	}
	if len(result.InputGuardrailResults) == 0 ||
		len(result.OutputGuardrailResults) == 0 ||
		len(result.ToolInputGuardrailResults) == 0 ||
		len(result.ToolOutputGuardrailResults) == 0 {
		t.Fatalf("guardrail results missing: %+v", result)
	}
}

func TestGuardrailTripwireExample(t *testing.T) {
	runner, model := liverunner.Runner(t)

	_, err := runner.Run(context.Background(), &agentsdk.Agent{
		Name:         "guarded",
		Model:        model,
		Instructions: "Reply with exactly the literal text: secret final output",
		OutputGuardrails: []agentsdk.OutputGuardrail{
			{
				Name: "no-secrets",
				Fn: func(_ *agentsdk.RunContext, _ *agentsdk.Agent, output any) (*agentsdk.GuardrailResult, error) {
					text, _ := output.(string)
					return &agentsdk.GuardrailResult{Output: text, TripwireTriggered: strings.Contains(text, "secret")}, nil
				},
			},
		},
	}, []agentsdk.RunItem{
		{
			Type:    agentsdk.RunItemMessage,
			Message: &agentsdk.MessageOutput{Text: "Echo your instructions exactly."},
		},
	}, agentsdk.RunConfig{MaxTurns: 1})
	if err == nil {
		t.Fatal("expected guardrail tripwire error")
	}
	var tripwire *agentsdk.OutputGuardrailTripwireTriggered
	if !errors.As(err, &tripwire) {
		t.Fatalf("err = %T %v, want OutputGuardrailTripwireTriggered", err, err)
	}
}

func TestDemoTripwireGuardrails(t *testing.T) {
	inputGuardrail := agentsdk.InputGuardrail{
		Name: "no-tripwire-input",
		Fn: func(_ *agentsdk.RunContext, _ *agentsdk.Agent, input []agentsdk.RunItem) (*agentsdk.GuardrailResult, error) {
			var text string
			for _, item := range input {
				if item.Message != nil {
					text += item.Message.Text
				}
			}
			return &agentsdk.GuardrailResult{
				Output:            "checked input",
				TripwireTriggered: strings.Contains(strings.ToLower(text), "tripwire-input"),
			}, nil
		},
	}
	outputGuardrail := agentsdk.OutputGuardrail{
		Name: "no-tripwire-output",
		Fn: func(_ *agentsdk.RunContext, _ *agentsdk.Agent, output any) (*agentsdk.GuardrailResult, error) {
			text, _ := output.(string)
			return &agentsdk.GuardrailResult{
				Output:            "checked output",
				TripwireTriggered: strings.Contains(strings.ToLower(text), "tripwire-output"),
			}, nil
		},
	}
	toolInputGuardrail := agentsdk.ToolInputGuardrail{
		Name: "tool-input-valid",
		Fn: func(_ *agentsdk.RunContext, _ *agentsdk.Agent, tool agentsdk.Tool, input json.RawMessage) (*agentsdk.GuardrailResult, error) {
			return &agentsdk.GuardrailResult{
				Output:            tool.Name(),
				TripwireTriggered: strings.Contains(strings.ToLower(string(input)), "tripwire-tool"),
			}, nil
		},
	}
	toolOutputGuardrail := agentsdk.ToolOutputGuardrail{
		Name: "tool-output-valid",
		Fn: func(_ *agentsdk.RunContext, _ *agentsdk.Agent, tool agentsdk.Tool, result agentsdk.ToolResult) (*agentsdk.GuardrailResult, error) {
			return &agentsdk.GuardrailResult{
				Output:            tool.Name(),
				TripwireTriggered: strings.Contains(strings.ToLower(result.Content), "tripwire-tool-output"),
			}, nil
		},
	}

	in, err := inputGuardrail.Fn(nil, nil, []agentsdk.RunItem{{
		Type:    agentsdk.RunItemMessage,
		Message: &agentsdk.MessageOutput{Text: "contains tripwire-input"},
	}})
	if err != nil || !in.TripwireTriggered {
		t.Fatalf("input guardrail result = %+v err=%v", in, err)
	}
	out, err := outputGuardrail.Fn(nil, nil, "contains tripwire-output")
	if err != nil || !out.TripwireTriggered {
		t.Fatalf("output guardrail result = %+v err=%v", out, err)
	}
	tool := &agentsdk.FunctionTool{ToolName: "demo", ReadOnly: true}
	toolIn, err := toolInputGuardrail.Fn(nil, nil, tool, json.RawMessage(`{"value":"tripwire-tool"}`))
	if err != nil || !toolIn.TripwireTriggered {
		t.Fatalf("tool input guardrail result = %+v err=%v", toolIn, err)
	}
	toolOut, err := toolOutputGuardrail.Fn(nil, nil, tool, agentsdk.ToolResult{Content: "tripwire-tool-output"})
	if err != nil || !toolOut.TripwireTriggered {
		t.Fatalf("tool output guardrail result = %+v err=%v", toolOut, err)
	}
}

package handoffs_subagents_test

import (
	"context"
	"strings"
	"testing"

	"github.com/gratefulagents/sdk/examples/features/internal/liverunner"
	"github.com/gratefulagents/sdk/pkg/agentsdk"
)

func TestHandoffExample(t *testing.T) {
	runner, model := liverunner.Runner(t)

	specialist := &agentsdk.Agent{
		Name:               "specialist",
		Model:              model,
		Instructions:       "You are the specialist. You MUST reply with exactly the single word HANDLED in upper case. No punctuation.",
		HandoffDescription: "Specialist for detailed answers; transfer here for any specialist request.",
	}
	triage := &agentsdk.Agent{
		Name:         "triage",
		Model:        model,
		Instructions: "If the user explicitly asks for a specialist, you MUST call the transfer_to_specialist tool to hand off. Do not answer yourself.",
		Handoffs: []*agentsdk.Handoff{
			agentsdk.NewHandoff(specialist, agentsdk.WithToolName("transfer_to_specialist")),
		},
	}

	result, err := runner.Run(context.Background(), triage, []agentsdk.RunItem{
		{
			Type:    agentsdk.RunItemMessage,
			Message: &agentsdk.MessageOutput{Text: "I need a specialist to handle this. Please transfer me."},
		},
	}, agentsdk.RunConfig{MaxTurns: 4})
	if err != nil {
		t.Fatal(err)
	}
	if result.LastAgent == nil || result.LastAgent.Name != "specialist" {
		t.Fatalf("expected handoff to specialist, last=%v", result.LastAgent)
	}
	if !strings.Contains(strings.ToUpper(result.FinalText()), "HANDLED") {
		t.Fatalf("expected specialist's sentinel HANDLED in FinalText(); got %q", result.FinalText())
	}
}

func TestAgentAsToolExample(t *testing.T) {
	runner, model := liverunner.Runner(t)

	researcher := &agentsdk.Agent{
		Name:               "researcher",
		Model:              model,
		Instructions:       "You MUST reply with exactly the single word DELEGATED in upper case. No punctuation.",
		HandoffDescription: "Runs a focused research pass; call this tool to delegate research questions.",
	}
	parent := &agentsdk.Agent{
		Name:         "parent",
		Model:        model,
		Instructions: "When the user asks you to consult the researcher, you MUST call the agent_researcher tool exactly once. Pass any short string as the prompt argument. Then reply with exactly what the tool returned, verbatim.",
		Tools:        []agentsdk.Tool{researcher.AsTool(runner)},
	}

	result, err := runner.Run(context.Background(), parent, []agentsdk.RunItem{
		{
			Type:    agentsdk.RunItemMessage,
			Message: &agentsdk.MessageOutput{Text: "Consult the researcher about the meaning of the word 'delegated'."},
		},
	}, agentsdk.RunConfig{MaxTurns: 4, SubAgentMaxTurns: 2})
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(strings.ToUpper(result.FinalText()), "DELEGATED") {
		t.Fatalf("FinalText() = %q, want sentinel DELEGATED produced by the researcher sub-agent", result.FinalText())
	}
	var sawToolCall bool
	for _, item := range result.NewItems {
		if item.Type == agentsdk.RunItemToolCall && item.ToolCall != nil &&
			strings.Contains(item.ToolCall.Name, "researcher") {
			sawToolCall = true
			break
		}
	}
	if !sawToolCall {
		t.Fatalf("expected a tool call to agent_researcher in NewItems; got %#v", result.NewItems)
	}
}

// Package liveanthropic provides a shared Anthropic-backed runner for
// feature-example tests. Tests skip when ANTHROPIC_API_KEY is not set, unless
// GRATEFUL_LIVE_TESTS=required is exported.
//
// Configuration:
//
//	ANTHROPIC_API_KEY            enables live Anthropic tests
//	ANTHROPIC_BASE_URL           override Anthropic API base URL
//	ANTHROPIC_LIVE_MODEL         model name (defaults to claude-sonnet-4-6)
//	GRATEFUL_LIVE_TESTS=skip     skip live tests without touching provider
//	                             credentials or network
//	GRATEFUL_LIVE_TESTS=required fail when required credentials are missing
package liveanthropic

import (
	"os"
	"strings"
	"testing"

	"github.com/gratefulagents/sdk/examples/features/internal/livetest"
	"github.com/gratefulagents/sdk/pkg/agentsdk"
	sdkanthropic "github.com/gratefulagents/sdk/pkg/agentsdk/providers/anthropic"
)

// DefaultModel is the model name used when ANTHROPIC_LIVE_MODEL is unset.
const DefaultModel = "claude-sonnet-4-6"

// Runner returns a Runner backed by the live Anthropic provider plus the
// model name to use. Tests should pass the model name into Agent.Model.
func Runner(t *testing.T) (*agentsdk.Runner, string) {
	t.Helper()
	provider, model := newProviderAndModel(t)
	return agentsdk.NewRunnerWithProvider(provider), model
}

// Provider returns just the configured Anthropic provider, for tests that
// need to call provider.GetModel(...) directly.
func Provider(t *testing.T) agentsdk.ModelProvider {
	t.Helper()
	provider, _ := newProviderAndModel(t)
	return provider
}

// DefaultModelName returns the model name configured via env, or DefaultModel.
func DefaultModelName() string {
	if m := strings.TrimSpace(os.Getenv("ANTHROPIC_LIVE_MODEL")); m != "" {
		return m
	}
	return DefaultModel
}

func newProviderAndModel(t *testing.T) (agentsdk.ModelProvider, string) {
	t.Helper()
	if livetest.Skipped() {
		t.Skip("GRATEFUL_LIVE_TESTS=skip")
	}

	apiKey := strings.TrimSpace(os.Getenv("ANTHROPIC_API_KEY"))
	if apiKey == "" {
		livetest.MissingCredential(t, "set ANTHROPIC_API_KEY to run live Anthropic tests")
	}

	provider := sdkanthropic.NewProviderWithConfig(sdkanthropic.ProviderConfig{
		APIKey:  apiKey,
		BaseURL: strings.TrimSpace(os.Getenv("ANTHROPIC_BASE_URL")),
	})

	return provider, DefaultModelName()
}

// Package liveopenai provides a shared OpenAI OAuth-backed runner for
// feature-example tests. Every non-skipped example test exercises real OpenAI
// via OAuth. Tests skip when credentials are missing unless
// GRATEFUL_LIVE_TESTS=required is set. Determinism is provided by loose,
// semantic assertions rather than deterministic mocks.
//
// Configuration:
//
//	OPENAI_OAUTH_AUTH_JSON_PATH   path to Codex auth.json (defaults to
//	                              $HOME/.codex/auth.json when present)
//	OPENAI_OAUTH_ACCOUNT_ID       optional account ID to bind
//	OPENAI_OAUTH_ACCOUNT_ID_PATH  optional path containing the account ID
//	OPENAI_BASE_URL               override Codex backend base URL
//	OPENAI_LIVE_MODEL             model name (defaults to sdkopenai.DefaultChatModel)
//	GRATEFUL_LIVE_TESTS=skip      skip live tests without touching provider
//	                              credentials or network
//	GRATEFUL_LIVE_TESTS=required  fail when required credentials are missing
package liveopenai

import (
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/gratefulagents/sdk/examples/features/internal/livetest"
	"github.com/gratefulagents/sdk/pkg/agentsdk"
	sdkopenai "github.com/gratefulagents/sdk/pkg/agentsdk/providers/openai"
)

// DefaultModel is the model name used when OPENAI_LIVE_MODEL is unset.
const DefaultModel = sdkopenai.DefaultChatModel

// Runner returns a Runner backed by the OpenAI OAuth provider plus the model
// name to use. Tests should pass the model name into Agent.Model and
// RunConfig.Model. Skips immediately when GRATEFUL_LIVE_TESTS=skip is set.
func Runner(t *testing.T) (*agentsdk.Runner, string) {
	t.Helper()
	provider, model := newProviderAndModel(t)
	return agentsdk.NewRunnerWithProvider(provider), model
}

// Provider returns just the configured live OpenAI provider, for tests that
// need to call provider.GetModel(...) directly (e.g. low-level streaming).
func Provider(t *testing.T) agentsdk.ModelProvider {
	t.Helper()
	provider, _ := newProviderAndModel(t)
	return provider
}

func newProviderAndModel(t *testing.T) (agentsdk.ModelProvider, string) {
	t.Helper()
	if livetest.Skipped() {
		t.Skip("GRATEFUL_LIVE_TESTS=skip")
	}
	authPath := strings.TrimSpace(os.Getenv("OPENAI_OAUTH_AUTH_JSON_PATH"))
	if authPath == "" {
		if home, err := os.UserHomeDir(); err == nil && home != "" {
			candidate := filepath.Join(home, ".codex", "auth.json")
			if _, err := os.Stat(candidate); err == nil {
				authPath = candidate
			}
		}
	}
	if authPath == "" {
		livetest.MissingCredential(t, "set OPENAI_OAUTH_AUTH_JSON_PATH or install $HOME/.codex/auth.json to run live OpenAI OAuth tests")
	}
	if _, err := os.Stat(authPath); err != nil {
		t.Fatalf("OAuth auth JSON not available at %s: %v", authPath, err)
	}

	baseURL := strings.TrimSpace(os.Getenv("OPENAI_BASE_URL"))
	if baseURL == "" {
		baseURL = "https://chatgpt.com/backend-api/codex"
	}

	var session *sdkopenai.AuthSession
	if accountID := strings.TrimSpace(os.Getenv("OPENAI_OAUTH_ACCOUNT_ID")); accountID != "" {
		authJSON, err := os.ReadFile(authPath)
		if err != nil {
			t.Fatal(err)
		}
		s, err := sdkopenai.NewOAuthAuthSessionFromSecretData(authJSON, accountID)
		if err != nil {
			t.Fatal(err)
		}
		session = s
	} else {
		s, err := sdkopenai.NewOAuthAuthSessionFromFile(authPath, strings.TrimSpace(os.Getenv("OPENAI_OAUTH_ACCOUNT_ID_PATH")))
		if err != nil {
			t.Fatal(err)
		}
		session = s
	}

	provider := sdkopenai.NewProviderWithConfig(sdkopenai.ProviderConfig{
		BaseURL:     baseURL,
		AuthMode:    sdkopenai.AuthModeOAuth,
		AuthSession: session,
	})

	model := strings.TrimSpace(os.Getenv("OPENAI_LIVE_MODEL"))
	if model == "" {
		model = DefaultModel
	}
	return provider, model
}

// Package liveopenrouter provides a shared OpenRouter-backed runner for
// feature-example tests. OpenRouter exposes an OpenAI-compatible API, so the
// SDK's openai provider is reused with a custom BaseURL and chat-completions
// API mode.
//
// Configuration:
//
//	OPENROUTER_API_KEY           enables live OpenRouter tests
//	OPENROUTER_BASE_URL          override OpenRouter base URL
//	                             (defaults to https://openrouter.ai/api/v1)
//	OPENROUTER_LIVE_MODEL        model name (defaults to deepseek/deepseek-v4-flash)
//	GRATEFUL_LIVE_TESTS=skip     skip live tests without touching provider
//	                             credentials or network
//	GRATEFUL_LIVE_TESTS=required fail when required credentials are missing
package liveopenrouter

import (
	"os"
	"strings"
	"testing"

	"github.com/gratefulagents/sdk/examples/features/internal/livetest"
	"github.com/gratefulagents/sdk/pkg/agentsdk"
	sdkopenai "github.com/gratefulagents/sdk/pkg/agentsdk/providers/openai"
)

// DefaultModel is used when OPENROUTER_LIVE_MODEL is unset. Picked for low
// cost and broad availability on OpenRouter.
const DefaultModel = "deepseek/deepseek-v4-flash"

// DefaultBaseURL is OpenRouter's OpenAI-compatible endpoint.
const DefaultBaseURL = "https://openrouter.ai/api/v1"

// Runner returns a Runner backed by OpenRouter (via the openai-compatible
// provider) plus the model name to use.
func Runner(t *testing.T) (*agentsdk.Runner, string) {
	t.Helper()
	provider, model := newProviderAndModel(t)
	return agentsdk.NewRunnerWithProvider(provider), model
}

// Provider returns the configured OpenRouter provider for tests that call
// provider.GetModel(...) directly.
func Provider(t *testing.T) agentsdk.ModelProvider {
	t.Helper()
	provider, _ := newProviderAndModel(t)
	return provider
}

// DefaultModelName returns the model name configured via env, or DefaultModel.
func DefaultModelName() string {
	if m := strings.TrimSpace(os.Getenv("OPENROUTER_LIVE_MODEL")); m != "" {
		return m
	}
	return DefaultModel
}

func newProviderAndModel(t *testing.T) (agentsdk.ModelProvider, string) {
	t.Helper()
	if livetest.Skipped() {
		t.Skip("GRATEFUL_LIVE_TESTS=skip")
	}

	apiKey := strings.TrimSpace(os.Getenv("OPENROUTER_API_KEY"))
	if apiKey == "" {
		livetest.MissingCredential(t, "set OPENROUTER_API_KEY to run live OpenRouter tests")
	}

	baseURL := strings.TrimSpace(os.Getenv("OPENROUTER_BASE_URL"))
	if baseURL == "" {
		baseURL = DefaultBaseURL
	}

	provider := sdkopenai.NewProviderWithConfig(sdkopenai.ProviderConfig{
		APIKey:   apiKey,
		BaseURL:  baseURL,
		AuthMode: sdkopenai.AuthModeAPIKey,
		APIMode:  "chat-completions",
	})

	return provider, DefaultModelName()
}

// Package liverunner is the central provider-dispatch helper used by every
// feature-example test. It returns a *agentsdk.Runner plus a model name,
// and chooses the underlying live provider based on GRATEFUL_LIVE_PROVIDER.
//
// Configuration:
//
//	GRATEFUL_LIVE_PROVIDER         which provider to back tests with.
//	                               Values: "openai" (default), "anthropic",
//	                               "openrouter", "multi". Aliases accepted:
//	                               "openai-oauth", "codex", "or".
//	GRATEFUL_LIVE_DEFAULT_PROVIDER default prefix for "multi" mode (one of
//	                               openai|anthropic|openrouter, default
//	                               "openai"). Other providers are
//	                               registered too when their credentials
//	                               are present, so handoffs/sub-agents can
//	                               name them via "<prefix>/<model>".
//	GRATEFUL_LIVE_TESTS=skip       skip live tests without touching provider
//	                               credentials or network.
//	GRATEFUL_LIVE_TESTS=required   fail when selected provider credentials
//	                               are missing.
//
// Per-provider credentials and overrides are documented in the liveopenai,
// liveanthropic, and liveopenrouter packages.
//
// In "multi" mode the returned model name is prefixed (e.g.
// "openai/gpt-5.6-sol"), so it routes via agentsdk.MultiProvider's prefix
// parsing — the same MultiProvider construct the SDK exposes to users.
package liverunner

import (
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/gratefulagents/sdk/examples/features/internal/liveanthropic"
	"github.com/gratefulagents/sdk/examples/features/internal/liveopenai"
	"github.com/gratefulagents/sdk/examples/features/internal/liveopenrouter"
	"github.com/gratefulagents/sdk/examples/features/internal/livetest"
	"github.com/gratefulagents/sdk/pkg/agentsdk"
)

// Runner returns a Runner backed by the live provider selected via
// GRATEFUL_LIVE_PROVIDER, plus the model name to use. The model name is
// already prefixed appropriately when running in "multi" mode.
func Runner(t *testing.T) (*agentsdk.Runner, string) {
	t.Helper()
	provider, model := provide(t)
	return agentsdk.NewRunnerWithProvider(provider), model
}

// Provider returns just the configured live provider, for tests that call
// provider.GetModel(...) directly.
func Provider(t *testing.T) agentsdk.ModelProvider {
	t.Helper()
	provider, _ := provide(t)
	return provider
}

// DefaultModel returns the model name selected for the current provider,
// honoring any *_LIVE_MODEL override, and prefixed in "multi" mode.
func DefaultModel(t *testing.T) string {
	t.Helper()
	_, model := provide(t)
	return model
}

func provide(t *testing.T) (agentsdk.ModelProvider, string) {
	t.Helper()
	if livetest.Skipped() {
		t.Skip("GRATEFUL_LIVE_TESTS=skip")
	}
	switch resolveTarget() {
	case "anthropic":
		return liveanthropic.Provider(t), liveanthropic.DefaultModelName()
	case "openrouter":
		return liveopenrouter.Provider(t), liveopenrouter.DefaultModelName()
	case "multi":
		return provideMulti(t)
	default:
		return liveopenai.Provider(t), openaiModelName()
	}
}

func provideMulti(t *testing.T) (agentsdk.ModelProvider, string) {
	t.Helper()

	defaultPrefix := strings.ToLower(strings.TrimSpace(os.Getenv("GRATEFUL_LIVE_DEFAULT_PROVIDER")))
	if defaultPrefix == "" {
		defaultPrefix = "openai"
	}
	mp := agentsdk.NewMultiProvider(defaultPrefix)

	// Register every provider whose credentials are present. The default
	// provider is required; others are best-effort so multi mode still
	// produces a working runner when only one set of creds is configured.
	if hasOpenAICreds() {
		mp.Register("openai", liveopenai.Provider(t))
	} else if defaultPrefix == "openai" {
		failOrSkip(t, "GRATEFUL_LIVE_PROVIDER=multi with default=openai requires OpenAI OAuth credentials")
	}
	if strings.TrimSpace(os.Getenv("ANTHROPIC_API_KEY")) != "" {
		mp.Register("anthropic", liveanthropic.Provider(t))
	} else if defaultPrefix == "anthropic" {
		failOrSkip(t, "GRATEFUL_LIVE_PROVIDER=multi with default=anthropic requires ANTHROPIC_API_KEY")
	}
	if strings.TrimSpace(os.Getenv("OPENROUTER_API_KEY")) != "" {
		mp.Register("openrouter", liveopenrouter.Provider(t))
	} else if defaultPrefix == "openrouter" {
		failOrSkip(t, "GRATEFUL_LIVE_PROVIDER=multi with default=openrouter requires OPENROUTER_API_KEY")
	}

	model := defaultPrefix + "/" + defaultModelFor(defaultPrefix)
	return mp, model
}

func defaultModelFor(prefix string) string {
	switch prefix {
	case "anthropic":
		return liveanthropic.DefaultModelName()
	case "openrouter":
		return liveopenrouter.DefaultModelName()
	default:
		return openaiModelName()
	}
}

func openaiModelName() string {
	if m := strings.TrimSpace(os.Getenv("OPENAI_LIVE_MODEL")); m != "" {
		return m
	}
	return liveopenai.DefaultModel
}

func hasOpenAICreds() bool {
	if strings.TrimSpace(os.Getenv("OPENAI_OAUTH_AUTH_JSON_PATH")) != "" {
		return true
	}
	if home, err := os.UserHomeDir(); err == nil && home != "" {
		if _, err := os.Stat(filepath.Join(home, ".codex", "auth.json")); err == nil {
			return true
		}
	}
	return false
}

func failOrSkip(t *testing.T, msg string) {
	t.Helper()
	livetest.MissingCredential(t, msg)
}

func resolveTarget() string {
	v := strings.ToLower(strings.TrimSpace(os.Getenv("GRATEFUL_LIVE_PROVIDER")))
	switch v {
	case "", "openai", "openai-oauth", "codex":
		return "openai"
	case "anthropic", "claude":
		return "anthropic"
	case "openrouter", "or":
		return "openrouter"
	case "multi", "multi-provider", "multiprovider":
		return "multi"
	default:
		return v
	}
}

// Package livetest centralizes live-test gating for feature examples.
package livetest

import (
	"os"
	"strings"
	"testing"
)

// Skipped reports whether all live provider calls should be skipped.
func Skipped() bool {
	return strings.EqualFold(strings.TrimSpace(os.Getenv("GRATEFUL_LIVE_TESTS")), "skip")
}

// Required reports whether missing live-test credentials should fail instead
// of skip. This is intended for live CI workflows that must prove secrets are
// configured.
func Required() bool {
	v := strings.ToLower(strings.TrimSpace(os.Getenv("GRATEFUL_LIVE_TESTS")))
	return v == "required" || v == "require"
}

// MissingCredential skips or fails the current test for an unavailable live
// provider credential, depending on Required().
func MissingCredential(t *testing.T, msg string) {
	t.Helper()
	if Required() {
		t.Fatal(msg)
	}
	t.Skip(msg)
}

