// TestMCPConfigSnapshotAndSanitizeExample exercises the real public MCP API:
// LoadConfigSnapshot pins the file's content hash; VerifyUnchanged refuses a
// silent reload if the file has been mutated mid-run; SanitizeMCPDisplay
// strips control characters from server-supplied display text.
func TestMCPConfigSnapshotAndSanitizeExample(t *testing.T) {
	dir := t.TempDir()
	cfgPath := filepath.Join(dir, sdkmcp.ConfigFileName)

	cfg := sdkmcp.Config{
		MCPServers: map[string]sdkmcp.ServerConfig{
			"echo": {
				Type:    "stdio",
				Command: "/bin/sh",
				Args:    []string{"-c", "echo test"},
			},
		},
	}
	cfgBytes, err := json.MarshalIndent(cfg, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(cfgPath, cfgBytes, 0o600); err != nil {
		t.Fatal(err)
	}

	snap, err := sdkmcp.LoadConfigSnapshot(cfgPath)
	if err != nil {
		t.Fatalf("LoadConfigSnapshot: %v", err)
	}
	if len(snap.ContentSHA256) == 0 {
		t.Fatal("expected non-empty content hash on a present .mcp.json")
	}
	if _, ok := snap.Config.MCPServers["echo"]; !ok {
		t.Fatalf("snapshot missing echo server: %+v", snap.Config)
	}
	if snap.AbsPath == "" || !filepath.IsAbs(snap.AbsPath) {
		t.Fatalf("AbsPath = %q, want absolute path", snap.AbsPath)
	}

	// Snapshot is honoured: unchanged file passes verification.
	if err := snap.VerifyUnchanged(); err != nil {
		t.Fatalf("VerifyUnchanged on unchanged file: %v", err)
	}

	// Mutate the on-disk file and verify the snapshot refuses the reload.
	mutated := append(cfgBytes, []byte("\n// trailing edit\n")...)
	if err := os.WriteFile(cfgPath, mutated, 0o600); err != nil {
		t.Fatal(err)
	}
	if err := snap.VerifyUnchanged(); err == nil {
		t.Fatal("VerifyUnchanged on mutated file: expected error, got nil")
	} else if !strings.Contains(err.Error(), "modified") {
		t.Fatalf("VerifyUnchanged error = %q, want to mention modification", err.Error())
	}

	// LoadConfig is the lower-level public entry; round-trip should still parse
	// the (mutated, but JSON-valid bytes were written first as a comment which
	// breaks JSON — so use the original bytes).
	if err := os.WriteFile(cfgPath, cfgBytes, 0o600); err != nil {
		t.Fatal(err)
	}
	parsed, exists, err := sdkmcp.LoadConfig(cfgPath)
	if err != nil || !exists {
		t.Fatalf("LoadConfig: err=%v exists=%v", err, exists)
	}
	if parsed.MCPServers["echo"].Command != "/bin/sh" {
		t.Fatalf("LoadConfig round-trip lost data: %+v", parsed)
	}

	// SanitizeMCPDisplay must strip control chars / ANSI escapes and prepend
	// a provenance tag so approval UIs can't be tricked by server-supplied
	// text. \x1b[31m is an ANSI red escape; \x07 is BEL; \x00 is NUL.
	out := sdkmcp.SanitizeMCPDisplay("evil-server", "click \x1b[31mHERE\x1b[0m\x07 to win\x00")
	if !strings.HasPrefix(out, "[from MCP server: evil-server]") {
		t.Fatalf("missing provenance tag: %q", out)
	}
	for _, bad := range []string{"\x1b", "\x07", "\x00"} {
		if strings.Contains(out, bad) {
			t.Fatalf("sanitized output still contains control char %q: %q", bad, out)
		}
	}
	if !strings.Contains(out, "click") || !strings.Contains(out, "HERE") || !strings.Contains(out, "to win") {
		t.Fatalf("sanitized output dropped legitimate text: %q", out)
	}

	// Provenance tag should also sanitize the server name itself.
	out2 := sdkmcp.SanitizeMCPDisplay("evil\x1bname", "ok")
	if strings.Contains(out2, "\x1b") {
		t.Fatalf("server name not sanitized in tag: %q", out2)
	}
}

package memory_test

import (
	"context"
	"encoding/json"
	"strings"
	"sync"
	"testing"

	"github.com/google/uuid"

	sdkmemory "github.com/gratefulagents/sdk/pkg/agentsdk/memory"
	sdktools "github.com/gratefulagents/sdk/pkg/agentsdk/tools"
)

type auditingStore struct {
	inner sdkmemory.Store
	mu    sync.Mutex

	stores   int
	searches int
}

func newAuditingStore() *auditingStore {
	return &auditingStore{inner: sdkmemory.NewInMemoryStore()}
}

func (s *auditingStore) Store(ctx context.Context, namespace, content string, tags []string, sourceRun string, metadata json.RawMessage) (*sdkmemory.Memory, error) {
	s.mu.Lock()
	s.stores++
	s.mu.Unlock()

	return s.inner.Store(ctx, namespace, content, tags, sourceRun, metadata)
}

func (s *auditingStore) Search(ctx context.Context, namespace, query string, tags []string, limit int) ([]sdkmemory.Memory, error) {
	s.mu.Lock()
	s.searches++
	s.mu.Unlock()

	return s.inner.Search(ctx, namespace, query, tags, limit)
}

func (s *auditingStore) List(ctx context.Context, namespace string, tags []string, limit int) ([]sdkmemory.Memory, error) {
	return s.inner.List(ctx, namespace, tags, limit)
}

func (s *auditingStore) Delete(ctx context.Context, namespace string, id uuid.UUID) error {
	return s.inner.Delete(ctx, namespace, id)
}

func (s *auditingStore) calls() (stores int, searches int) {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.stores, s.searches
}

func TestCustomStoreCanBackMemoryToolExample(t *testing.T) {
	ctx := context.Background()
	store := newAuditingStore()

	registry := sdktools.NewRegistry(
		t.TempDir(),
		sdktools.WithMemoryStore(store, "team-a", "run-001", "https://example.test/repo"),
	)
	tool := registry.Get("Memory")
	if tool == nil {
		t.Fatalf("registry missing Memory tool; names=%v", registry.Names())
	}

	stored, err := tool.Execute(ctx, json.RawMessage(`{
		"action": "store",
		"content": "deploys require a green smoke test",
		"tags": ["deploy"]
	}`), "")
	if err != nil || stored.IsError {
		t.Fatalf("store result=%+v err=%v", stored, err)
	}

	var payload sdkmemory.Memory
	if err := json.Unmarshal([]byte(stored.Content), &payload); err != nil {
		t.Fatalf("stored payload=%q err=%v", stored.Content, err)
	}
	if payload.Namespace != "team-a" || payload.SourceRun != "run-001" {
		t.Fatalf("stored memory = %+v, want namespace/source run from tool config", payload)
	}
	if !strings.Contains(string(payload.Metadata), "https://example.test/repo") {
		t.Fatalf("metadata = %s, want repo URL", payload.Metadata)
	}

	found, err := tool.Execute(ctx, json.RawMessage(`{
		"action": "search",
		"content": "smoke test",
		"tags": ["deploy"],
		"limit": 1
	}`), "")
	if err != nil || found.IsError {
		t.Fatalf("search result=%+v err=%v", found, err)
	}
	if !strings.Contains(found.Content, payload.ID.String()) {
		t.Fatalf("search output=%q, want stored memory id %s", found.Content, payload.ID)
	}

	stores, searches := store.calls()
	if stores != 1 || searches != 1 {
		t.Fatalf("custom store calls = store:%d search:%d, want 1/1", stores, searches)
	}
}

package memory_test

import (
	"context"
	"encoding/json"
	"testing"

	"github.com/gratefulagents/sdk/pkg/agentsdk/memory"
)

func TestInMemoryStoreSemanticsExample(t *testing.T) {
	ctx := context.Background()
	store := memory.NewInMemoryStore()

	first, err := store.Store(ctx, "team-a", "remember to renew SSL certs in November",
		[]string{"ops", "tls"}, "run-001", json.RawMessage(`{"kind":"reminder"}`))
	if err != nil {
		t.Fatalf("store: %v", err)
	}
	if first.ID.String() == "" {
		t.Fatalf("expected non-empty UUID")
	}

	if _, err := store.Store(ctx, "team-a", "deploy guide is in /runbooks/deploy.md",
		[]string{"ops"}, "run-002", nil); err != nil {
		t.Fatalf("store2: %v", err)
	}
	if _, err := store.Store(ctx, "team-b", "do not include this in team-a results",
		[]string{"ops"}, "run-003", nil); err != nil {
		t.Fatalf("store3: %v", err)
	}

	teamA, err := store.List(ctx, "team-a", nil, 10)
	if err != nil {
		t.Fatalf("list: %v", err)
	}
	if len(teamA) != 2 {
		t.Fatalf("team-a list = %d, want 2 (namespace isolation broken)", len(teamA))
	}

	tagged, err := store.List(ctx, "team-a", []string{"tls"}, 10)
	if err != nil {
		t.Fatalf("list tagged: %v", err)
	}
	if len(tagged) != 1 || tagged[0].ID != first.ID {
		t.Fatalf("tag filter = %#v, want only the SSL reminder", tagged)
	}

	if err := store.Delete(ctx, "team-a", first.ID); err != nil {
		t.Fatalf("delete: %v", err)
	}
	after, _ := store.List(ctx, "team-a", nil, 10)
	if len(after) != 1 {
		t.Fatalf("after delete = %d, want 1", len(after))
	}
}

func TestNoopEmbedderIsDeterministicExample(t *testing.T) {
	emb := &memory.NoopEmbedder{}
	a, err := emb.Embed(context.Background(), "hello world")
	if err != nil {
		t.Fatalf("embed: %v", err)
	}
	b, _ := emb.Embed(context.Background(), "hello world")
	if len(a) == 0 || len(a) != len(b) {
		t.Fatalf("len mismatch: %d vs %d", len(a), len(b))
	}
	for i := range a {
		if a[i] != b[i] {
			t.Fatalf("non-deterministic embedding at %d: %f vs %f", i, a[i], b[i])
		}
	}
}

# Postgres / pgvector Memory Store

The SDK memory tool accepts any implementation of `memory.Store`. This example
shows a Postgres store that uses pgvector for semantic search. It lives in docs
instead of a default Go test because it requires an application database, the
pgvector extension, and the `pgx` driver.

Install the application dependency in your app, not in the SDK:

```sh
go get github.com/jackc/pgx/v5
```

## Schema

The vector dimension must match your embedder. The SDK's default
`memory.NewOpenAIEmbedder(..., "", "")` model is `text-embedding-3-small`,
which returns 1536 dimensions.

```sql
CREATE EXTENSION IF NOT EXISTS vector;

CREATE TABLE IF NOT EXISTS agent_memories (
  id uuid PRIMARY KEY,
  namespace text NOT NULL,
  content text NOT NULL,
  tags text[] NOT NULL DEFAULT '{}',
  source_run text NOT NULL DEFAULT '',
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  embedding vector(1536) NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS agent_memories_namespace_created_idx
  ON agent_memories (namespace, created_at DESC);

CREATE INDEX IF NOT EXISTS agent_memories_tags_idx
  ON agent_memories USING gin (tags);

CREATE INDEX IF NOT EXISTS agent_memories_embedding_idx
  ON agent_memories USING hnsw (embedding vector_cosine_ops);
```

## Store Implementation

```go
package memorypostgres

import (
	"context"
	"encoding/json"
	"fmt"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/gratefulagents/sdk/pkg/agentsdk/memory"
)

type PostgresStore struct {
	db       *pgxpool.Pool
	embedder memory.Embedder
}

func NewPostgresStore(db *pgxpool.Pool, embedder memory.Embedder) *PostgresStore {
	return &PostgresStore{db: db, embedder: embedder}
}

func (s *PostgresStore) Store(ctx context.Context, namespace, content string, tags []string, sourceRun string, metadata json.RawMessage) (*memory.Memory, error) {
	if s == nil || s.db == nil {
		return nil, fmt.Errorf("postgres memory store is not configured")
	}
	if s.embedder == nil {
		return nil, fmt.Errorf("embedder is required")
	}
	if namespace == "" {
		return nil, fmt.Errorf("namespace is required")
	}
	if content == "" {
		return nil, fmt.Errorf("content is required")
	}
	if tags == nil {
		tags = []string{}
	}
	if metadata == nil {
		metadata = json.RawMessage(`{}`)
	}

	vector, err := s.embedder.Embed(ctx, content)
	if err != nil {
		return nil, fmt.Errorf("embed memory content: %w", err)
	}

	row := s.db.QueryRow(ctx, `
		INSERT INTO agent_memories (id, namespace, content, tags, source_run, metadata, embedding)
		VALUES ($1, $2, $3, $4::text[], $5, $6::jsonb, $7::vector)
		RETURNING id, namespace, content, tags, source_run, metadata, 0::double precision, created_at
	`, uuid.New(), namespace, content, tags, sourceRun, string(metadata), memory.VectorLiteral(vector))

	return scanMemory(row)
}

func (s *PostgresStore) Search(ctx context.Context, namespace, query string, tags []string, limit int) ([]memory.Memory, error) {
	if s == nil || s.db == nil {
		return nil, fmt.Errorf("postgres memory store is not configured")
	}
	if s.embedder == nil {
		return nil, fmt.Errorf("embedder is required")
	}
	if namespace == "" {
		return nil, fmt.Errorf("namespace is required")
	}
	if query == "" {
		return nil, fmt.Errorf("query is required")
	}
	if limit <= 0 {
		limit = 10
	}

	vector, err := s.embedder.Embed(ctx, query)
	if err != nil {
		return nil, fmt.Errorf("embed memory query: %w", err)
	}

	rows, err := s.db.Query(ctx, `
		SELECT
			id,
			namespace,
			content,
			tags,
			source_run,
			metadata,
			1 - (embedding <=> $4::vector) AS similarity,
			created_at
		FROM agent_memories
		WHERE namespace = $1
		  AND ($2 OR tags && $3::text[])
		ORDER BY embedding <=> $4::vector
		LIMIT $5
	`, namespace, len(tags) == 0, tags, memory.VectorLiteral(vector), limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	return scanMemories(rows)
}

func (s *PostgresStore) List(ctx context.Context, namespace string, tags []string, limit int) ([]memory.Memory, error) {
	if s == nil || s.db == nil {
		return nil, fmt.Errorf("postgres memory store is not configured")
	}
	if namespace == "" {
		return nil, fmt.Errorf("namespace is required")
	}
	if limit <= 0 {
		limit = 50
	}

	rows, err := s.db.Query(ctx, `
		SELECT
			id,
			namespace,
			content,
			tags,
			source_run,
			metadata,
			0::double precision AS similarity,
			created_at
		FROM agent_memories
		WHERE namespace = $1
		  AND ($2 OR tags && $3::text[])
		ORDER BY created_at DESC
		LIMIT $4
	`, namespace, len(tags) == 0, tags, limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	return scanMemories(rows)
}

func (s *PostgresStore) Delete(ctx context.Context, namespace string, id uuid.UUID) error {
	if s == nil || s.db == nil {
		return fmt.Errorf("postgres memory store is not configured")
	}
	if namespace == "" {
		return fmt.Errorf("namespace is required")
	}

	tag, err := s.db.Exec(ctx, `
		DELETE FROM agent_memories
		WHERE namespace = $1 AND id = $2
	`, namespace, id)
	if err != nil {
		return err
	}
	if tag.RowsAffected() == 0 {
		return fmt.Errorf("memory not found")
	}
	return nil
}

type memoryRow interface {
	Scan(dest ...any) error
}

type memoryRows interface {
	Next() bool
	Scan(dest ...any) error
	Err() error
}

func scanMemory(row memoryRow) (*memory.Memory, error) {
	var mem memory.Memory
	if err := row.Scan(
		&mem.ID,
		&mem.Namespace,
		&mem.Content,
		&mem.Tags,
		&mem.SourceRun,
		&mem.Metadata,
		&mem.Similarity,
		&mem.CreatedAt,
	); err != nil {
		return nil, err
	}
	return &mem, nil
}

func scanMemories(rows memoryRows) ([]memory.Memory, error) {
	var memories []memory.Memory
	for rows.Next() {
		mem, err := scanMemory(rows)
		if err != nil {
			return nil, err
		}
		memories = append(memories, *mem)
	}
	return memories, rows.Err()
}
```

## Register The Store

Use the default registry when you build tools yourself:

```go
pool, err := pgxpool.New(ctx, os.Getenv("DATABASE_URL"))
if err != nil {
	return err
}
defer pool.Close()

auth := openai.NewAPIKeyAuthSession(os.Getenv("OPENAI_API_KEY"))
embedder := memory.NewOpenAIEmbedder(auth, "", "")
store := memorypostgres.NewPostgresStore(pool, embedder)

registry := tools.NewRegistry(
	workDir,
	tools.WithMemoryStore(store, "acme/repo", runID, "https://github.com/acme/repo"),
)
agent.Tools = registry.Tools()
```

Use `ExtraTools` when you use `runtime.Builder`, because `runtime.Config` does
not currently have a first-class memory-store field:

```go
memoryTool := memorytool.New(store, "acme/repo", runID, "https://github.com/acme/repo")

bundle, err := runtime.NewBuilder(runtime.Config{
	WorkDir:     workDir,
	EnableTools: true,
	ExtraTools:  []agentsdk.Tool{memoryTool},
}).Build(ctx)
```

## Other Stores

Postgres is not special to the SDK. A Redis, SQLite, Qdrant, Pinecone, or
application-native store uses the same four methods:

```go
type Store interface {
	Store(ctx context.Context, namespace, content string, tags []string, sourceRun string, metadata json.RawMessage) (*memory.Memory, error)
	Search(ctx context.Context, namespace, query string, tags []string, limit int) ([]memory.Memory, error)
	List(ctx context.Context, namespace string, tags []string, limit int) ([]memory.Memory, error)
	Delete(ctx context.Context, namespace string, id uuid.UUID) error
}
```

For production stores, keep namespace isolation mandatory, honor tag filters and
limits, respect `context.Context`, and use an embedder that matches your vector
index dimension.

