		},
	})
	if err != nil {
		t.Fatal(err)
	}

	var delta string
	for event := range stream.Events {
		if event.Type == agentsdk.ModelStreamDelta {
			delta += event.Delta
		}
	}
	if delta == "" {
		t.Fatalf("expected non-empty delta")
	}
	final := stream.Final()
	if final == nil || len(final.Items) == 0 {
