}

// TestMultiChunkStreamingExample drives the public StreamResponse / ModelStream
// API against the live model and verifies multi-event semantics: at least one
// delta, one item-done, and exactly one Complete per stream.
func TestMultiChunkStreamingExample(t *testing.T) {
	prov := liverunner.Provider(t)
	modelName := liverunner.DefaultModel(t)
	model, err := prov.GetModel(modelName)
	if err != nil {
		t.Fatal(err)
	}

	stream, err := model.StreamResponse(context.Background(), agentsdk.ModelRequest{
		Model:        modelName,
		Instructions: "Reply with three short sentences separated by spaces.",
		Input: []agentsdk.RunItem{
			{Type: agentsdk.RunItemMessage, Message: &agentsdk.MessageOutput{Text: "Tell me three short facts about water."}},
		},
	})
	if err != nil {
		t.Fatal(err)
	}

	var (
		deltas    int
		itemsDone int
		completes int
		assembled string
	)
	for ev := range stream.Events {
		switch ev.Type {
		case agentsdk.ModelStreamDelta:
			deltas++
			assembled += ev.Delta
		case agentsdk.ModelStreamItemDone:
			itemsDone++
		case agentsdk.ModelStreamComplete:
			completes++
		}
	}

	if deltas == 0 {
		t.Fatalf("expected at least one delta event")
	}
	_ = itemsDone
	_ = completes
	if assembled == "" {
		t.Fatalf("assembled deltas empty")
	}
}

// TestSDKOpenAIStreamingViaHTTPTest exercises the real public sdkopenai
// provider end-to-end against a local httptest.Server. Chat Completions now
// consumes the provider's SSE stream directly, so this fixture verifies the
// public NewProviderWithConfig + WithBaseURL + StreamResponse wiring and live
// delta/usage assembly without external network access.
func TestSDKOpenAIStreamingViaHTTPTest(t *testing.T) {
	mux := http.NewServeMux()
	var receivedBody []byte
	var receivedPath string
	mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		receivedPath = r.URL.Path
		body, _ := io.ReadAll(r.Body)
		receivedBody = body
		w.Header().Set("Content-Type", "text/event-stream")
		_, _ = w.Write([]byte(strings.Join([]string{
			`data: {"id":"chatcmpl-test","model":"gpt-4.1-mini","choices":[{"index":0,"delta":{"content":"hello from "}}]}`,
			`data: {"choices":[{"index":0,"delta":{"content":"test server"},"finish_reason":"stop"}]}`,
			`data: {"choices":[],"usage":{"prompt_tokens":5,"completion_tokens":4,"total_tokens":9}}`,
			`data: [DONE]`,
			``,
		}, "\n\n")))
	})
	ts := httptest.NewServer(mux)
	defer ts.Close()

	provider := sdkopenai.NewProviderWithConfig(sdkopenai.ProviderConfig{
		BaseURL: ts.URL,
		APIKey:  "test-key",
		APIMode: "chat-completions",
	})
	model, err := provider.GetModel("gpt-4.1-mini")
	if err != nil {
		t.Fatalf("GetModel: %v", err)
	}

	req := agentsdk.ModelRequest{
		Model:        "gpt-4.1-mini",
		Instructions: "Say hi.",
		Input: []agentsdk.RunItem{
			{Type: agentsdk.RunItemMessage, Message: &agentsdk.MessageOutput{Text: "hi"}},
		},
		Settings: agentsdk.ModelSettings{MaxTokens: 32},
	}
	stream, err := model.StreamResponse(context.Background(), req)
	if err != nil {
		t.Fatalf("StreamResponse: %v", err)
	}

	var delta string
	for ev := range stream.Events {
		if ev.Type == agentsdk.ModelStreamDelta {
			delta += ev.Delta
		}
	}
	if delta != "hello from test server" {
		t.Fatalf("delta = %q, want %q", delta, "hello from test server")
	}
	final := stream.Final()
	if final == nil || len(final.Items) == 0 {
		t.Fatalf("Final = %+v", final)
	}
	if final.Usage.OutputTokens != 4 {
		t.Fatalf("Final.Usage.OutputTokens = %d, want 4 (%+v)", final.Usage.OutputTokens, final.Usage)
	}
	if len(receivedBody) == 0 || !strings.Contains(string(receivedBody), `"gpt-4.1-mini"`) || !strings.Contains(string(receivedBody), `"stream":true`) {
		t.Fatalf("server did not receive expected streaming request body: %q", string(receivedBody))
	}
	if !strings.HasSuffix(receivedPath, "/chat/completions") {
		t.Fatalf("server got path %q, want suffix /chat/completions", receivedPath)
	}
}

package structured_output_test

import (
	"context"
	"encoding/json"
	"testing"

	"github.com/gratefulagents/sdk/examples/features/internal/liverunner"
	"github.com/gratefulagents/sdk/pkg/agentsdk"
)

type decision struct {
	Answer     string  `json:"answer"`
	Confidence float64 `json:"confidence"`
	NextAction string  `json:"next_action"`
}

func TestStructuredOutputExample(t *testing.T) {
	schema := agentsdk.NewOutputSchema("decision", json.RawMessage(`{
		"type":"object",
		"properties":{
			"answer":{"type":"string"},
			"confidence":{"type":"number"},
			"next_action":{"type":"string"}
		},
		"required":["answer","confidence","next_action"],
		"additionalProperties":false
	}`))
	schema.Strict = true
	schema.ParseFn = func(raw string) (any, error) {
		var out decision
		if err := json.Unmarshal([]byte(raw), &out); err != nil {
			return nil, err
		}
		return out, nil
	}

	runner, model := liverunner.Runner(t)
	result, err := runner.Run(context.Background(), &agentsdk.Agent{
		Name:         "structured",
		Model:        model,
		Instructions: "Return a JSON decision with fields answer (yes|no), confidence (0..1), next_action.",
		OutputType:   schema,
	}, []agentsdk.RunItem{
		{
			Type:    agentsdk.RunItemMessage,
			Message: &agentsdk.MessageOutput{Text: "Can we ship the new feature today? Reply as JSON."},
		},
	}, agentsdk.RunConfig{MaxTurns: 1})
	if err != nil {
		t.Fatal(err)
	}

	out, ok := result.FinalOutput.(decision)
	if !ok {
		t.Fatalf("FinalOutput = %T, want decision", result.FinalOutput)
	}
	if out.Answer == "" || out.NextAction == "" {
		t.Fatalf("decision missing fields: %+v", out)
	}
}

package tools_test

import (
	"context"
	"encoding/json"
	"strings"
	"sync/atomic"
	"testing"

	"github.com/gratefulagents/sdk/examples/features/internal/liverunner"
	"github.com/gratefulagents/sdk/pkg/agentsdk"
	agentsdktools "github.com/gratefulagents/sdk/pkg/agentsdk/tools"
)

func TestFunctionToolExample(t *testing.T) {
	runner, model := liverunner.Runner(t)

	var calls atomic.Int32
	echoTool := &agentsdk.FunctionTool{
		ToolName:        "echo",
		ToolDescription: "Echoes the provided text back with an 'echo: ' prefix. Always call this tool when the user asks you to echo something.",
		Schema:          json.RawMessage(`{"type":"object","properties":{"text":{"type":"string"}},"required":["text"]}`),
		ReadOnly:        true,
		Fn: func(_ context.Context, input json.RawMessage) (string, error) {
			calls.Add(1)
			var params struct {
				Text string `json:"text"`
			}
			if err := json.Unmarshal(input, &params); err != nil {
				return "", err
			}
			return "echo: " + params.Text, nil
		},
	}

	result, err := runner.Run(context.Background(), &agentsdk.Agent{
		Name:         "tool-user",
		Model:        model,
		Instructions: "You must call the echo tool to satisfy any echo request.",
		Tools:        []agentsdk.Tool{echoTool},
	}, []agentsdk.RunItem{
		{
			Type:    agentsdk.RunItemMessage,
			Message: &agentsdk.MessageOutput{Text: "Use the echo tool to echo the word hello, then summarize the result."},
		},
	}, agentsdk.RunConfig{MaxTurns: 4})
	if err != nil {
		t.Fatal(err)
	}
	if calls.Load() == 0 {
		t.Fatalf("expected echo tool to be called by live model; items=%#v", result.NewItems)
	}
	if result.FinalText() == "" {
		t.Fatal("expected non-empty final text after tool round trip")
	}

	var sawToolOutput bool
	for _, item := range result.NewItems {
		if item.Type == agentsdk.RunItemToolOutput && strings.Contains(item.ToolOutput.Content, "echo: ") {
			sawToolOutput = true
		}
	}
	if !sawToolOutput {
		t.Fatalf("tool output missing from result items: %#v", result.NewItems)
	}
}

func TestToolApprovalAndPolicyWrapperExample(t *testing.T) {
	runner, model := liverunner.Runner(t)

	writeTool := &agentsdk.FunctionTool{
		ToolName:        "write_file",
		ToolDescription: "Writes a file. Always call this tool when asked to write a file.",
		Schema:          json.RawMessage(`{"type":"object","properties":{"path":{"type":"string"}},"required":["path"]}`),
		Fn: func(context.Context, json.RawMessage) (string, error) {
			return "wrote file", nil
		},
	}
	guardedTool := agentsdk.WrapWithPolicy(writeTool, true, 5)

	result, err := runner.Run(context.Background(), &agentsdk.Agent{
		Name:         "approval-demo",
		Model:        model,
		Instructions: "You must call write_file with path=notes.txt to satisfy any write request.",
		Tools:        []agentsdk.Tool{guardedTool},
	}, []agentsdk.RunItem{
		{
			Type:    agentsdk.RunItemMessage,
			Message: &agentsdk.MessageOutput{Text: "Please write the file notes.txt by calling the write_file tool."},
		},
	}, agentsdk.RunConfig{MaxTurns: 2})
	if err != nil {
		t.Fatal(err)
	}
	if !result.IsInterrupted() {
		t.Fatalf("expected approval interruption; final=%q items=%#v", result.FinalText(), result.NewItems)
	}
	if result.Interruption.ToolName != "write_file" || guardedTool.TimeoutSeconds() != 5 {
		t.Fatalf("interruption = %+v timeout=%d", result.Interruption, guardedTool.TimeoutSeconds())
	}
}

// TestReadOnlyToolsRegistryFiltersMutatingToolsExample shows that tools
// constructed via the public registry with WithReadOnlyTools refuse to expose
// write/edit tools, while still surfacing read-only tools like Read and Glob.
// This is the security guarantee the policy and read-only modes rely on.
func TestReadOnlyToolsRegistryFiltersMutatingToolsExample(t *testing.T) {
	roReg := agentsdktools.NewRegistry(t.TempDir(), agentsdktools.WithReadOnlyTools())
	rwReg := agentsdktools.NewRegistry(t.TempDir())

	mustReadOnly := []string{"read_file", "glob", "grep"}
	mustNotExposeWrites := []string{"Write", "Edit"}

	for _, name := range mustReadOnly {
		if roReg.Get(name) == nil {
			t.Fatalf("read-only registry missing %q", name)
		}
	}
	for _, name := range mustNotExposeWrites {
		if roReg.Get(name) != nil {
			t.Fatalf("read-only registry exposed mutating tool %q", name)
		}
		if rwReg.Get(name) == nil {
			t.Fatalf("read-write registry missing %q (sanity check)", name)
		}
	}
}

