import "encoding/json"

// ToolUseBehavior controls what happens after tool calls complete.
type ToolUseBehavior int

const (
	// RunLLMAgain runs the LLM again with the tool results (default).
	RunLLMAgain ToolUseBehavior = iota
	// StopOnFirstTool returns immediately after the first tool result.
	StopOnFirstTool
)

// Agent defines an AI agent with its configuration, tools, and behavior.
type Agent struct {
	Name               string
	Instructions       string                                     // static instructions
	InstructionsFn     func(ctx *RunContext, agent *Agent) string // dynamic instructions (used if set)
	Model              string                                     // model name, resolved to Model impl at runtime
	FallbackModels     []string                                   // ordered cross-provider fallback models for failed model calls
	ModelSettings      ModelSettings
	Tools              []Tool
	MCPServers         []string   // host-provided MCP server names for prompt context
	Handoffs           []*Handoff // in-process agent handoffs
	InputGuardrails    []InputGuardrail
	OutputGuardrails   []OutputGuardrail
	OutputType         *OutputSchema // nil = plain string output
	Hooks              AgentHooks    // per-agent lifecycle hooks
	ToolUseBehavior    ToolUseBehavior
	StopAtTools        *StopAtTools
	ToolsToFinalOutput *ToolsToFinalOutputResult
	HandoffDescription string // description when this agent is a handoff target
}

// GetInstructions resolves the agent's instructions, preferring InstructionsFn if set.
func (a *Agent) GetInstructions(ctx *RunContext) string {
	if a.InstructionsFn != nil {
		return a.InstructionsFn(ctx, a)
	}
	return a.Instructions
}

// GetAllTools returns all tools available to this agent: explicit tools + handoff-generated tools.
func (a *Agent) GetAllTools(ctx *RunContext) []Tool {
	tools := make([]Tool, 0, len(a.Tools)+len(a.Handoffs))
	tools = append(tools, a.Tools...)
	for _, h := range a.Handoffs {
		tools = append(tools, h.ToTool())
	}
	return tools
}

// Clone returns a shallow copy of the agent with optional overrides applied.
func (a *Agent) Clone(opts ...AgentOption) *Agent {
	clone := *a
	for _, opt := range opts {
		opt(&clone)
	}
	return &clone
}

// AgentOption is a functional option for Agent.Clone().
type AgentOption func(*Agent)

// WithName overrides the agent name.
func WithName(name string) AgentOption {
	return func(a *Agent) { a.Name = name }
}

// WithInstructions overrides the agent instructions.
func WithInstructions(instructions string) AgentOption {
	return func(a *Agent) { a.Instructions = instructions }
}

// WithModel overrides the agent model.
func WithModel(model string) AgentOption {
	return func(a *Agent) { a.Model = model }
}

// WithTools overrides the agent tools.
func WithTools(tools ...Tool) AgentOption {
	return func(a *Agent) { a.Tools = tools }
}

// WithHandoffs overrides the agent handoffs.
func WithHandoffs(handoffs ...*Handoff) AgentOption {
	return func(a *Agent) { a.Handoffs = handoffs }
}

// WithOutputType overrides the agent output type.
func WithOutputType(schema *OutputSchema) AgentOption {
	return func(a *Agent) { a.OutputType = schema }
}

// WithStopAtTools configures tool names that stop the run after their results.
func WithStopAtTools(stop *StopAtTools) AgentOption {
	return func(a *Agent) { a.StopAtTools = stop }
}

// WithToolsToFinalOutput configures whether a stopping tool result becomes final output.
func WithToolsToFinalOutput(result *ToolsToFinalOutputResult) AgentOption {
	return func(a *Agent) { a.ToolsToFinalOutput = result }
}

// StopAtTools configures tool names that cause the run to stop when called.
type StopAtTools struct {
	ToolNames []string
}

// Contains checks if the given tool name is in the stop list.
func (s *StopAtTools) Contains(name string) bool {
	for _, n := range s.ToolNames {
		if n == name {
			return true
		}
	}
	return false
}

// ToolsToFinalOutputResult indicates whether tool results should be treated as the final output.
type ToolsToFinalOutputResult struct {
	IsFinalOutput bool
	Output        json.RawMessage
}

package agent

import (
	"context"
	"encoding/json"
	"fmt"
	"strings"

	"github.com/google/uuid"
)

// AsTool returns a Tool that runs this agent as a nested sub-agent.
// When called, the tool input becomes the user message and the agent's
// final text output becomes the tool result. Options can override the tool
// name/description or post-process the sub-agent result before it is returned
// to the parent (custom output extraction).
func (a *Agent) AsTool(runner *Runner, opts ...AsToolOption) Tool {
	t := &agentTool{agent: a, runner: runner}
	for _, opt := range opts {
		opt(t)
	}
	return t
}

// AsToolOption configures an agent-as-tool wrapper produced by Agent.AsTool.
type AsToolOption func(*agentTool)

// WithAsToolName overrides the generated tool name for an agent-as-tool wrapper.
func WithAsToolName(name string) AsToolOption {
	return func(t *agentTool) { t.nameOverride = name }
}

// WithAsToolDescription overrides the tool description for an agent-as-tool wrapper.
func WithAsToolDescription(desc string) AsToolOption {
	return func(t *agentTool) { t.descriptionOverride = desc }
}

// WithAsToolOutputExtractor sets a function that transforms the sub-agent's
// RunResult into the string returned to the parent agent. Use it to return a
// compact, structured, or filtered view of the sub-agent's work instead of its
// raw final text. If the extractor returns an empty string, the wrapper falls
// back to the sub-agent's final text.
func WithAsToolOutputExtractor(fn func(*RunResult) string) AsToolOption {
	return func(t *agentTool) { t.outputExtractor = fn }
}

// agentTool wraps an Agent as a Tool for agent composition.
type agentTool struct {
	agent               *Agent
	runner              *Runner
	nameOverride        string
	descriptionOverride string
	outputExtractor     func(*RunResult) string
}

func (t *agentTool) Name() string {
	if t.nameOverride != "" {
		return t.nameOverride
	}
	return "agent_" + safeAgentToolName(t.agent.Name)
}
func (t *agentTool) Description() string {
	if t.descriptionOverride != "" {
		return t.descriptionOverride
	}
	return t.agent.HandoffDescription
}
func (t *agentTool) IsReadOnly() bool {
	// A sub-agent tool is read-only if all its tools are read-only.
	return t.isReadOnly(map[*Agent]bool{})
}

// isReadOnly walks nested agent-as-tool wrappers with a visited set so
// mutually referencing agents (A includes B.AsTool, B includes A.AsTool)
// cannot recurse forever. An already-visited agent is treated as read-only
// here: its own mutating tools are checked by the frame that first visited it.
func (t *agentTool) isReadOnly(visited map[*Agent]bool) bool {
	if visited[t.agent] {
		return true
	}
	visited[t.agent] = true
	for _, tool := range t.agent.Tools {
		if nested, ok := tool.(*agentTool); ok {
			if !nested.isReadOnly(visited) {
				return false
			}
			continue
		}
		if !tool.IsReadOnly() {
			return false
		}
	}
	return true
}

func safeAgentToolName(name string) string {
	name = strings.TrimSpace(name)
	var b strings.Builder
	lastUnderscore := false
	for _, r := range name {
		ok := (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') || r == '_' || r == '-'
		if ok {
			b.WriteRune(r)
			lastUnderscore = false
			continue
		}
		if !lastUnderscore {
			b.WriteByte('_')
			lastUnderscore = true
		}
	}
	out := strings.Trim(b.String(), "_-")
	if out == "" {
		return "agent"
	}
	return out
}
func (t *agentTool) IsEnabled(ctx *RunContext) bool {
	if ctx == nil {
		return true
	}
	switch NormalizeToolAccessLevel(ctx.ToolAccessLevel) {
	case ToolAccessLevelReadOnly:
		return t.IsReadOnly()
	default:
		return true
	}
}
func (t *agentTool) NeedsApproval() bool { return false }
func (t *agentTool) TimeoutSeconds() int { return 0 }

func (t *agentTool) InputSchema() json.RawMessage {
	return json.RawMessage(`{"type":"object","properties":{"message":{"type":"string","description":"The ONLY context the sub-agent receives. Send a compact task packet: exact task, goal, only the relevant repo context, constraints/acceptance criteria, prior findings this task depends on, and expected output. Avoid unrelated history."}},"required":["message"]}`)
}

func (t *agentTool) Execute(ctx context.Context, input json.RawMessage, workDir string) (ToolResult, error) {
	// Parse the message from the tool input.
	var params struct {
		Message string `json:"message"`
	}
	if err := json.Unmarshal(input, &params); err != nil {
		return ToolResult{Content: fmt.Sprintf("invalid input: %v", err), IsError: true}, nil
	}
	if params.Message == "" {
		return ToolResult{Content: "message is required", IsError: true}, nil
	}

	runConfig := RunConfig{
		MaxTurns:         DefaultSubAgentMaxTurns,
		SubAgentMaxTurns: DefaultSubAgentMaxTurns,
		WorkDir:          workDir,
		Trace:            TraceFromContext(ctx),
		ParentSpanID:     SpanParentIDFromContext(ctx),
		TracingProcessor: TracingProcessorFromContext(ctx),
	}
	// Child tool access defaults to the wrapper's effective access; the parent
	// run's level (inherited below) can only clamp it further, never widen it.
	childToolAccess := ToolAccessLevelFull
	if t.IsReadOnly() {
		childToolAccess = ToolAccessLevelReadOnly
	}
	if nestedCfg, ok := NestedRunConfigFromContext(ctx); ok {
		runConfig.MaxTurns = nestedCfg.MaxTurns
		runConfig.SubAgentMaxTurns = nestedCfg.MaxTurns
		runConfig.CompactionConfig = nestedCfg.CompactionConfig
		runConfig.CompactionRecorder = nestedCfg.CompactionRecorder
		runConfig.CompactionFailureReporter = nestedCfg.CompactionFailureReporter
		runConfig.HandoffHistory = nestedCfg.HandoffHistory
		// Inherit the parent's tool policy and security settings so nested
		// runs cannot bypass approval requirements, tool guardrails,
		// untrusted-output tagging, or output caps that the host configured
		// on the parent run.
		runConfig.ToolPolicy = nestedCfg.ToolPolicy
		runConfig.ToolInputGuardrails = nestedCfg.ToolInputGuardrails
		runConfig.ToolOutputGuardrails = nestedCfg.ToolOutputGuardrails
		runConfig.UntrustedToolOutputs = nestedCfg.UntrustedToolOutputs
		runConfig.MaxToolOutputBytes = nestedCfg.MaxToolOutputBytes
		runConfig.ToolOutputDir = nestedCfg.ToolOutputDir
		// Model calls made by a child must retain the parent's resilience
		// policy; without these, a provider timeout the parent would retry
		// fails the whole sub-agent tool call instead.
		runConfig.RetryPolicy = nestedCfg.RetryPolicy
		runConfig.ModelCallTimeout = nestedCfg.ModelCallTimeout
		if NormalizeToolAccessLevel(nestedCfg.ToolAccessLevel) == ToolAccessLevelReadOnly {
			childToolAccess = ToolAccessLevelReadOnly
		}
	}
	runConfig.ToolAccessLevel = childToolAccess

	// Run through the shared sub-agent engine, inheriting the runner's default
	// hooks so sub-agent tool events appear in the parent's activity log.
	spec := subAgentRunSpec{
		Runner:        t.runner,
		Agent:         t.agent,
		Message:       params.Message,
		ParentCallID:  ParentCallIDFromContext(ctx),
		FallbackHooks: t.runner.DefaultHooks,
		RunConfig:     runConfig,
	}
	if platformHooks, ok := t.runner.DefaultHooks.(*PlatformHooks); ok && platformHooks != nil && (platformHooks.Tracker != nil || platformHooks.EventStream != nil) {
		spec.TaskID = "task_" + uuid.NewString()
		spec.Tracker = platformHooks.Tracker
		spec.EventStream = platformHooks.EventStream
		spec.Turn = platformHooks.Turn
	}

	outcome := runSubAgentOnce(ctx, spec)
	if outcome.Err != nil {
		return ToolResult{Content: outcome.ErrMsg, IsError: true}, nil
	}

	text := outcome.FinalText
	if t.outputExtractor != nil {
		if extracted := t.outputExtractor(outcome.Result); extracted != "" {
			text = extracted
		}
	}
	if text == "" {
		text = "(no output)"
	}
	return ToolResult{Content: text}, nil
}

package agents

import "strings"

// Kind is the governed catalog of built-in agent roles.
type Kind string

const (
	KindExplore          Kind = "explore"
	KindAnalyst          Kind = "analyst"
	KindPlanner          Kind = "planner"
	KindArchitect        Kind = "architect"
	KindDebugger         Kind = "debugger"
	KindExecutor         Kind = "executor"
	KindCritic           Kind = "critic"
	KindSecurityReviewer Kind = "security-reviewer"
	KindDependencyExpert Kind = "dependency-expert"
	KindDesigner         Kind = "designer"
	KindWriter           Kind = "writer"
)

type Definition struct {
	Kind     Kind     `json:"kind"`
	ReadOnly bool     `json:"readOnly"`
	Aliases  []string `json:"aliases,omitempty"`
}

var builtInDefinitions = []Definition{
	{Kind: KindExplore, ReadOnly: true, Aliases: []string{"Explore"}},
	{Kind: KindAnalyst},
	{Kind: KindPlanner, ReadOnly: true, Aliases: []string{"Plan"}},
	{Kind: KindArchitect},
	{Kind: KindDebugger},
	{Kind: KindExecutor, Aliases: []string{"general-purpose"}},
	{Kind: KindCritic},
	{Kind: KindSecurityReviewer, ReadOnly: true},
	{Kind: KindDependencyExpert},
	{Kind: KindDesigner},
	{Kind: KindWriter},
}

func BuiltInKinds() []Kind {
	out := make([]Kind, 0, len(builtInDefinitions))
	for _, def := range builtInDefinitions {
		out = append(out, def.Kind)
	}
	return out
}

func Definitions() []Definition {
	out := make([]Definition, len(builtInDefinitions))
	copy(out, builtInDefinitions)
	return out
}

func ParseKind(v string) (Kind, bool) {
	def, ok := ResolveKind(v)
	if !ok {
		return "", false
	}
	return def.Kind, true
}

func ResolveKind(v string) (Definition, bool) {
	normalized := normalizeKindValue(v)
	if normalized == "" {
		return Definition{}, false
	}
	for _, def := range builtInDefinitions {
		if normalizeKindValue(string(def.Kind)) == normalized {
			return def, true
		}
		for _, alias := range def.Aliases {
			if normalizeKindValue(alias) == normalized {
				return def, true
			}
		}
	}
	return Definition{}, false
}

func IsAllowed(kind Kind, allowed []string) bool {
	if len(allowed) == 0 {
		return true
	}
	for _, candidate := range allowed {
		def, ok := ResolveKind(candidate)
		if ok && def.Kind == kind {
			return true
		}
	}
	return false
}

func normalizeKindValue(v string) string {
	return strings.ToLower(strings.TrimSpace(v))
}

package agents

import "testing"

func TestBuiltInKindsAreStable(t *testing.T) {
	kinds := BuiltInKinds()
	if len(kinds) == 0 {
		t.Fatal("expected built-in kinds")
	}

	for _, kind := range kinds {
		if kind == "" {
			t.Fatal("expected non-empty built-in kind")
		}
	}
}

func TestResolveKindSupportsLegacyAliases(t *testing.T) {
	t.Parallel()

	tests := []struct {
		input string
		want  Kind
	}{
		{"explore", KindExplore},
		{"Explore", KindExplore},
		{"Plan", KindPlanner},
		{"security-reviewer", KindSecurityReviewer},
		{"general-purpose", KindExecutor},
	}

	for _, tt := range tests {
		def, ok := ResolveKind(tt.input)
		if !ok {
			t.Fatalf("ResolveKind(%q) failed", tt.input)
		}
		if def.Kind != tt.want {
			t.Fatalf("ResolveKind(%q) = %q, want %q", tt.input, def.Kind, tt.want)
		}
	}
}

func TestResolveKindUnknown(t *testing.T) {
	t.Parallel()

	if _, ok := ResolveKind("unknown-role"); ok {
		t.Fatal("ResolveKind should reject unknown kinds")
	}
}

func TestIsAllowedResolvesAliases(t *testing.T) {
	t.Parallel()

	if !IsAllowed(KindExecutor, []string{"explore", "general-purpose"}) {
		t.Fatal("expected executor to be allowed by legacy alias")
	}
	if IsAllowed(KindExecutor, []string{"explore", "security-reviewer"}) {
		t.Fatal("did not expect executor to be allowed")
	}
}

