// Reasoning items in the preserved tail must survive provider compaction:
// runItemDedupeKey previously returned "" for RunItemReasoning, so
// appendMissingRecentRunItems silently dropped every reasoning item — on the
// Codex backend that discards the model's encrypted working memory and leaves
// function_calls without their paired rs_ items (run chat-gf-all-aqvafl).
func TestCarryForwardPreservesReasoningItemsInTail(t *testing.T) {
	agentRef := &Agent{Name: "assistant"}
	previous := []RunItem{
		{Type: RunItemMessage, Message: &MessageOutput{Text: "the task"}},
	}
	for i := 0; i < 6; i++ {
		id := fmt.Sprintf("call_%d", i)
		previous = append(previous,
			RunItem{Type: RunItemReasoning, Agent: agentRef, Reasoning: &ReasoningData{ID: fmt.Sprintf("rs_%d", i), EncryptedContent: "enc-" + id}},
			RunItem{Type: RunItemToolCall, Agent: agentRef, ToolCall: &ToolCallData{ID: id, Name: "read_file", Input: json.RawMessage(`{}`)}},
			RunItem{Type: RunItemToolOutput, ToolOutput: &ToolOutputData{CallID: id, Content: "file content"}},
		)
	}
	compacted := []RunItem{
		{Type: RunItemMessage, Message: &MessageOutput{Text: "the task"}},
		{Type: RunItemCompaction, Compaction: &CompactionData{ID: "cmp_1", EncryptedContent: "blob"}},
	}
	got, _ := applyCompactionCarryForward(context.Background(), compacted, previous, RunConfig{
		CompactionConfig: CompactionConfig{Enabled: true, PreserveRecentItems: 6, PreserveInitialUserMessages: 1},
	}, CompactionConfig{Enabled: true, PreserveRecentItems: 6, PreserveInitialUserMessages: 1}, 0)

	var reasoning, calls int
	for _, item := range got {
		switch item.Type {
		case RunItemReasoning:
			reasoning++
		case RunItemToolCall:
			calls++
		}
	}
	if reasoning == 0 {
		t.Fatalf("post-compaction input lost all reasoning items: %+v", got)
	}
	if calls == 0 {
		t.Fatalf("post-compaction input lost the recent tool calls")
	}
}

// A stale carry-forward message from an earlier compaction must not be
// re-inserted as an "initial user message" on the next compaction: the fresh
// carry-forward appended at the end is the only copy allowed to survive.
func TestCarryForwardNotDuplicatedAcrossCompactions(t *testing.T) {
	previous := []RunItem{
		{Type: RunItemMessage, Message: &MessageOutput{Text: "the task"}},
		{Type: RunItemCompaction, Compaction: &CompactionData{ID: "cmp_1", EncryptedContent: "old-blob"}},
		{Type: RunItemMessage, Message: &MessageOutput{Text: "[COMPACTION CARRY-FORWARD]\nstale runtime state from the previous compaction"}},
		{Type: RunItemMessage, Message: &MessageOutput{Text: "later plain user message"}},
	}
	compacted := []RunItem{
		{Type: RunItemMessage, Message: &MessageOutput{Text: "the task"}},
		{Type: RunItemCompaction, Compaction: &CompactionData{ID: "cmp_2", EncryptedContent: "new-blob"}},
	}
	got, carryForward := applyCompactionCarryForward(context.Background(), compacted, previous, RunConfig{
		CompactionConfig:    CompactionConfig{Enabled: true, PreserveRecentItems: 2, PreserveInitialUserMessages: 2},
		WorkingStateContext: "fresh runtime state",
	}, CompactionConfig{Enabled: true, PreserveRecentItems: 2, PreserveInitialUserMessages: 2}, 0)
	if !strings.Contains(carryForward, "fresh runtime state") {
		t.Fatalf("carry-forward = %q, want fresh runtime state", carryForward)
	}
	var carryForwards, stale int
	for _, item := range got {
		if isCompactionCarryForwardItem(item) {
			carryForwards++
			if strings.Contains(item.Message.Text, "stale runtime state") {
				stale++
			}
		}
	}
	if stale != 0 {
		t.Fatalf("stale carry-forward re-inserted after re-compaction: %+v", got)
	}
	if carryForwards != 1 {
		t.Fatalf("carry-forward count = %d, want exactly 1 (the fresh one)", carryForwards)
	}
}

// The preserved tail extends beyond PreserveRecentItems while it fits the
// compaction target: a provider blob compresses the whole history into a few
// KB, and refilling only ~3 tool exchanges left the post-compaction window
// nearly empty while the agent lost its recent working state and restarted
// discovery (run chat-gf-all-aqvafl re-ran greps/reads it had already done).
func TestCarryForwardTailUsesTargetTokenBudget(t *testing.T) {
	agentRef := &Agent{Name: "assistant"}
	previous := []RunItem{
		{Type: RunItemMessage, Message: &MessageOutput{Text: "the task"}},
	}
	const turns = 30
	for i := 0; i < turns; i++ {
		id := fmt.Sprintf("call_%d", i)
		previous = append(previous,
			RunItem{Type: RunItemToolCall, Agent: agentRef, ToolCall: &ToolCallData{ID: id, Name: "read_file", Input: json.RawMessage(`{}`)}},
			RunItem{Type: RunItemToolOutput, ToolOutput: &ToolOutputData{CallID: id, Content: strings.Repeat("x", 4000)}}, // ~1000 tokens each
		)
	}
	compacted := []RunItem{
		{Type: RunItemCompaction, Compaction: &CompactionData{ID: "cmp_1", EncryptedContent: "blob"}},
	}
	cfg := RunConfig{CompactionConfig: CompactionConfig{
		Enabled: true, TriggerTokens: 60_000, TargetTokens: 20_000,
		PreserveRecentItems: 4, PreserveInitialUserMessages: 1,
	}}

	// Large remaining budget: the tail should reach well past 4 items.
	got, _ := applyCompactionCarryForward(context.Background(), compacted, previous, cfg, cfg.CompactionConfig, 0)
	var outputs int
	for _, item := range got {
		if item.Type == RunItemToolOutput {
			outputs++
		}
	}
	if outputs <= 4 {
		t.Fatalf("budgeted tail outputs = %d, want > PreserveRecentItems/2 pairs", outputs)
	}
	if outputs == turns {
		t.Fatalf("tail unexpectedly kept the whole history; budget not applied")
	}

	// Overhead consuming the whole target: fall back to the minimum item count.
	gotMin, _ := applyCompactionCarryForward(context.Background(), compacted, previous, cfg, cfg.CompactionConfig, 60_000)
	outputs = 0
	var callsMin int
	for _, item := range gotMin {
		switch item.Type {
		case RunItemToolOutput:
			outputs++
		case RunItemToolCall:
			callsMin++
		}
	}
	if outputs != 2 || callsMin != 2 {
		t.Fatalf("min tail = %d calls / %d outputs, want 2/2 (PreserveRecentItems=4)", callsMin, outputs)
	}
}

// usageSemanticsCompactorModel lets tests pick the provider usage semantics
// the calibration must normalize against.
type usageSemanticsCompactorModel struct {
	mockCompactorModel
	inclusive bool
}

func (m *usageSemanticsCompactorModel) UsageInputIncludesCacheTokens() bool { return m.inclusive }

func TestUsageContextTokensNormalizesProviderSemantics(t *testing.T) {
	usage := Usage{InputTokens: 1000, CacheReadTokens: 900, CacheCreateTokens: 50}
	inclusive := &usageSemanticsCompactorModel{inclusive: true}
	if got := usageContextTokens(inclusive, usage); got != 1000 {
		t.Fatalf("inclusive semantics = %d, want 1000 (cached tokens are a subset of input)", got)
	}
	additive := &mockCompactorModel{}
	if got := usageContextTokens(additive, usage); got != 1950 {
		t.Fatalf("additive semantics = %d, want 1950 (cache fields add to input)", got)
	}
}

// OpenAI-style usage reports input_tokens INCLUSIVE of cached tokens. Summing
// the cache fields on top (the old calibration formula) double-counted almost
// the whole prompt on warm requests, inflated estimateCalibration, and made
// compaction fire at ~half the model's real window (observed on the Codex
// backend: trigger 244.8K effectively firing at 125K real tokens).
func TestCalibrationDoesNotDoubleCountInclusiveCacheUsage(t *testing.T) {
	bigText := strings.Repeat("word ", 80_000) // ~100K estimated tokens
	model := &usageSemanticsCompactorModel{
		inclusive: true,
		mockCompactorModel: mockCompactorModel{
			mockModel: mockModel{
				responses: []*ModelResponse{
					{
						Items: []RunItem{{Type: RunItemToolCall, ToolCall: &ToolCallData{ID: "call1", Name: "echo", Input: json.RawMessage(`"hi"`)}}},
						// Warm request: nearly the whole prompt is cached.
						// input already includes the cached tokens and matches
						// the prompt-side estimate (~100K items + small tool
						// overhead), so a correct calibration stays ≈1.0.
						Usage: Usage{InputTokens: 101_000, CacheReadTokens: 96_000},
					},
					{Items: []RunItem{{Type: RunItemMessage, Message: &MessageOutput{Text: "done"}}}},
				},
			},
		},
	}
	echoTool := &FunctionTool{
		ToolName: "echo", ToolDescription: "echo",
		Schema: json.RawMessage(`{"type":"object"}`),
		Fn: func(_ context.Context, _ json.RawMessage) (string, error) {
			return strings.Repeat("out ", 2_000), nil
		},
	}
	runner := NewRunnerWithModel(model)
	_, err := runner.Run(context.Background(), &Agent{Name: "test", Tools: []Tool{echoTool}}, []RunItem{
		{Type: RunItemMessage, Message: &MessageOutput{Text: bigText}},
	}, RunConfig{
		MaxTurns: 5,
		// Prompt-side estimate ≈101K (items ~100K + tool overhead) matches
		// actual usage → calibration ≈1.0 and the effective trigger stays at
		// 145K, above the turn-2 estimate. The old double-count made
		// actual≈197K vs estimate≈101K → calibration ≈1.5 → effective
		// trigger ≈97K → spurious provider compaction on the next turn.
		CompactionConfig: CompactionConfig{Enabled: true, TriggerTokens: 145_000, TargetTokens: 70_000},
	})
	if err != nil {
		t.Fatal(err)
	}
	if model.compactCalls != 0 {
		t.Fatalf("compactCalls = %d, want 0 (calibration must not double-count cached tokens)", model.compactCalls)
	}
}

// The estimator can also OVERCOUNT (encrypted reasoning/compaction blobs are
// estimated as text but not billed as such). Calibration must correct
// downward too — a one-sided clamp at 1.0 kept the trigger at the inflated
// estimate scale and compacted at a fraction of the real window.
func TestCalibrationCorrectsOvercountingEstimatorDownward(t *testing.T) {
	bigText := strings.Repeat("word ", 80_000) // ~100K estimated tokens
	model := &usageSemanticsCompactorModel{
		inclusive: true,
		mockCompactorModel: mockCompactorModel{
			mockModel: mockModel{
				responses: []*ModelResponse{
					{
						Items: []RunItem{{Type: RunItemToolCall, ToolCall: &ToolCallData{ID: "call1", Name: "echo", Input: json.RawMessage(`"hi"`)}}},
						// Provider reports ~half the estimator's guess.
						Usage: Usage{InputTokens: 65_000},
					},
					{Items: []RunItem{{Type: RunItemMessage, Message: &MessageOutput{Text: "done"}}}},
				},
			},
		},
	}
	echoTool := &FunctionTool{
		ToolName: "echo", ToolDescription: "echo",
		Schema: json.RawMessage(`{"type":"object"}`),
		Fn: func(_ context.Context, _ json.RawMessage) (string, error) {
			return strings.Repeat("out ", 2_000), nil
		},
	}
	runner := NewRunnerWithModel(model)
	_, err := runner.Run(context.Background(), &Agent{Name: "test", Tools: []Tool{echoTool}}, []RunItem{
		{Type: RunItemMessage, Message: &MessageOutput{Text: bigText}},
	}, RunConfig{
		MaxTurns: 5,
		// Turn-2 raw estimate (≈127K after the tool output) crosses this
		// trigger, but the provider says the real prompt is only ~65K —
		// half the window pressure. Downward calibration (ratio≈0.52 →
		// blended≈0.76) lifts the effective trigger to ≈166K: no compaction.
		// The old one-sided clamp kept calibration at 1.0 and compacted.
		CompactionConfig: CompactionConfig{Enabled: true, TriggerTokens: 126_000, TargetTokens: 63_000},
	})
	if err != nil {
		t.Fatal(err)
	}
	if model.compactCalls != 0 {
		t.Fatalf("compactCalls = %d, want 0 (downward calibration must lift the trigger)", model.compactCalls)
	}
}

// hookCapturingContextTokens records the ContextTokens stamped on responses
// observed via OnLLMEnd — the value host context gauges must consume.
type hookCapturingContextTokens struct {
	NoOpRunHooks
	seen []int64
}

func (h *hookCapturingContextTokens) OnLLMEnd(_ *RunContext, _ *Agent, resp *ModelResponse) {
	if resp != nil {
		h.seen = append(h.seen, resp.ContextTokens)
	}
}

// The response handed to OnLLMEnd carries the provider-normalized context
// size: on OpenAI-style providers (input inclusive of cached tokens) hosts
// summing usage fields read ~2x on warm requests — the platform gauge showed
// 91% while real usage was 46% (run chat-gf-all-xa9h7s).
func TestOnLLMEndReceivesNormalizedContextTokens(t *testing.T) {
	hooks := &hookCapturingContextTokens{}
	inclusive := &usageSemanticsCompactorModel{
		inclusive: true,
		mockCompactorModel: mockCompactorModel{
			mockModel: mockModel{
				responses: []*ModelResponse{
					{
						Items: []RunItem{{Type: RunItemMessage, Message: &MessageOutput{Text: "done"}}},
						// Warm OpenAI-style request: cached tokens are a
						// subset of input, not additive.
						Usage: Usage{InputTokens: 114_000, CacheReadTokens: 110_000},
					},
				},
			},
		},
	}
	runner := NewRunnerWithModel(inclusive)
	if _, err := runner.Run(context.Background(), &Agent{Name: "main"}, []RunItem{
		{Type: RunItemMessage, Message: &MessageOutput{Text: "task"}},
	}, RunConfig{MaxTurns: 3, Hooks: hooks}); err != nil {
		t.Fatal(err)
	}
	if len(hooks.seen) != 1 || hooks.seen[0] != 114_000 {
		t.Fatalf("OnLLMEnd ContextTokens = %v, want [114000] (not 224000 double-counted)", hooks.seen)
	}

	hooks = &hookCapturingContextTokens{}
	additive := &mockCompactorModel{
		mockModel: mockModel{
			responses: []*ModelResponse{
				{
					Items: []RunItem{{Type: RunItemMessage, Message: &MessageOutput{Text: "done"}}},
					Usage: Usage{InputTokens: 4_000, CacheReadTokens: 110_000},
				},
			},
		},
	}
	runner = NewRunnerWithModel(additive)
	if _, err := runner.Run(context.Background(), &Agent{Name: "main"}, []RunItem{
		{Type: RunItemMessage, Message: &MessageOutput{Text: "task"}},
	}, RunConfig{MaxTurns: 3, Hooks: hooks}); err != nil {
		t.Fatal(err)
	}
	if len(hooks.seen) != 1 || hooks.seen[0] != 114_000 {
		t.Fatalf("OnLLMEnd ContextTokens (additive) = %v, want [114000] (input+cache)", hooks.seen)
	}
}

