func summarizeProviderCompactionOutput(id string, items []RunItem) string {
	type outputItem struct {
		Type             string `json:"type"`
		Role             string `json:"role,omitempty"`
		ID               string `json:"id,omitempty"`
		Text             string `json:"text,omitempty"`
		EncryptedContent string `json:"encrypted_content,omitempty"`
		CreatedBy        string `json:"created_by,omitempty"`
	}
	out := struct {
		Type  string       `json:"type"`
		ID    string       `json:"id,omitempty"`
		Items []outputItem `json:"items"`
	}{
		Type: "openai_responses_compaction",
		ID:   id,
	}
	for _, item := range items {
		switch item.Type {
		case RunItemMessage:
			if item.Message == nil {
				continue
			}
			role := "assistant"
			if item.Agent == nil {
				role = "user"
			}
			out.Items = append(out.Items, outputItem{
				Type: "message",
				Role: role,
				Text: item.Message.Text,
			})
		case RunItemCompaction:
			if item.Compaction == nil {
				continue
			}
			out.Items = append(out.Items, outputItem{
				Type:             "compaction",
				ID:               item.Compaction.ID,
				EncryptedContent: item.Compaction.EncryptedContent,
				CreatedBy:        item.Compaction.CreatedBy,
			})
		case RunItemToolCall:
			if item.ToolCall != nil {
				out.Items = append(out.Items, outputItem{Type: "tool_call", ID: item.ToolCall.ID, Text: item.ToolCall.Name})
			}
		case RunItemToolOutput:
			if item.ToolOutput != nil {
				out.Items = append(out.Items, outputItem{Type: "tool_output", ID: item.ToolOutput.CallID, Text: item.ToolOutput.Content})
			}
		case RunItemReasoning:
			if item.Reasoning != nil {
				out.Items = append(out.Items, outputItem{
					Type:             "reasoning",
					ID:               item.Reasoning.ID,
					Text:             item.Reasoning.Text,
					EncryptedContent: item.Reasoning.EncryptedContent,
				})
			}
		}
	}
	data, err := json.MarshalIndent(out, "", "  ")
	if err != nil {
		return "[OPENAI RESPONSES COMPACTION]"
	}
	return "[OPENAI RESPONSES COMPACTION]\n" + string(data)
}

package agent

// Conversation manages the message history for an agent run.
// Unlike the old implementation that stored []anthropic.Message,
// this uses the RunItem-based history format.
type Conversation struct {
	Items []RunItem
}

// NewConversation creates an empty conversation.
func NewConversation() *Conversation {
	return &Conversation{}
}

// NewConversationFromItems creates a conversation with existing items.
func NewConversationFromItems(items []RunItem) *Conversation {
	return &Conversation{Items: items}
}

// Append adds items to the conversation.
func (c *Conversation) Append(items ...RunItem) {
	c.Items = append(c.Items, items...)
}

// LastText returns the text of the last message item.
func (c *Conversation) LastText() string {
	return Items.ExtractLastText(c.Items)
}

// AllText returns all concatenated message text.
func (c *Conversation) AllText() string {
	return Items.ExtractText(c.Items)
}

// ToolCalls returns all tool call data.
func (c *Conversation) ToolCalls() []ToolCallData {
	return Items.ExtractToolCalls(c.Items)
}

// Len returns the number of items.
func (c *Conversation) Len() int {
	return len(c.Items)
}

// Clear removes all items.
func (c *Conversation) Clear() {
	c.Items = nil
}

// Copy returns a deep copy of the conversation.
func (c *Conversation) Copy() *Conversation {
	items := make([]RunItem, len(c.Items))
	copy(items, c.Items)
	return &Conversation{Items: items}
}

package agent

// estimateModelCost returns a provider-aware USD estimate plus whether the
// value should be considered known for display purposes.
func estimateModelCost(model Model, usage Usage) (float64, bool) {
	if model == nil {
		return 0, false
	}
	type costEstimator interface {
		EstimateCost(Usage) (float64, bool)
	}
	if estimator, ok := model.(costEstimator); ok {
		return estimator.EstimateCost(usage)
	}
	return model.CalculateCost(usage), true
}

func estimateRunResultCost(result *RunResult, fallbackModel Model) (float64, bool) {
	if result == nil {
		return 0, false
	}
	if len(result.RawResponses) == 0 {
		return estimateModelCost(fallbackModel, result.Usage)
	}

	var costUSD float64
	costKnown := true
	var responsesUsage Usage
	for _, response := range result.RawResponses {
		costUSD += response.CostUSD
		if !response.CostKnown {
			costKnown = false
		}
		responsesUsage.Add(response.Usage)
	}
	// Compaction calls (provider-side or LLM-summary) add usage to
	// result.Usage without appending to RawResponses; estimate that residual
	// so the summed cost matches the reported usage.
	residual := Usage{
		Requests:          max(result.Usage.Requests-responsesUsage.Requests, 0),
		InputTokens:       max(result.Usage.InputTokens-responsesUsage.InputTokens, 0),
		OutputTokens:      max(result.Usage.OutputTokens-responsesUsage.OutputTokens, 0),
		CacheReadTokens:   max(result.Usage.CacheReadTokens-responsesUsage.CacheReadTokens, 0),
		CacheCreateTokens: max(result.Usage.CacheCreateTokens-responsesUsage.CacheCreateTokens, 0),
	}
	if residual.TotalTokens() > 0 || residual.CacheReadTokens > 0 || residual.CacheCreateTokens > 0 {
		residualCost, residualKnown := estimateModelCost(fallbackModel, residual)
		costUSD += residualCost
		if !residualKnown {
			costKnown = false
		}
	}
	return costUSD, costKnown
}

