	if subagent.AgentName != "worker" || len(subagent.WaitingOn) != 1 || subagent.WaitingOn[0] != "task-parent" || subagent.MessagesReceived != 1 {
		t.Fatalf("unexpected subagent payload: %+v", subagent)
	}
}

