	out := result.FinalHistory[2].ToolOutput
	if out == nil || out.CallID != "call1" || !strings.Contains(out.Content, "echoed:") {
		t.Errorf("expected paired tool output for call1 in FinalHistory, got %+v", result.FinalHistory[2])
	}
}

