func TestResolveRoleModeRouting(t *testing.T) {
	routing := &ModeModelRouting{
		DefaultModel:   "openai/gpt-5.4",
		FallbackModels: []string{"anthropic/claude-sonnet-4-6"},
		ReasoningLevel: string(ReasoningMedium),
		TextVerbosity:  string(TextVerbosityLow),
		RoleOverrides: map[string]ModeRoleModelRouting{
			"architect": {
				Model:          "anthropic/claude-sonnet-4-6",
				FallbackModels: []string{"copilot/gpt-4.1"},
				ReasoningLevel: string(ReasoningHigh),
				TextVerbosity:  string(TextVerbosityHigh),
			},
		},
	}

	architect := ResolveRoleModeRouting("openai/gpt-5.3-codex", "openai", "architect", routing)
	if architect.Model != "anthropic/claude-sonnet-4-6" {
		t.Fatalf("architect model = %q, want anthropic/claude-sonnet-4-6", architect.Model)
	}
	if len(architect.FallbackModels) != 1 || architect.FallbackModels[0] != "copilot/gpt-4.1" {
		t.Fatalf("architect fallbacks = %#v", architect.FallbackModels)
	}
	if architect.ReasoningLevel != "high" || architect.ModelSettings.ThinkingBudget != 8192 {
		t.Fatalf("architect reasoning = %q budget=%d", architect.ReasoningLevel, architect.ModelSettings.ThinkingBudget)
	}
	if architect.TextVerbosity != "high" || architect.ModelSettings.TextVerbosity != "high" {
		t.Fatalf("architect verbosity = %q settings=%q, want high", architect.TextVerbosity, architect.ModelSettings.TextVerbosity)
	}

	planner := ResolveRoleModeRouting("openai/gpt-5.3-codex", "openai", "planner", routing)
	if planner.Model != "openai/gpt-5.4" {
		t.Fatalf("planner model = %q, want openai/gpt-5.4", planner.Model)
	}
	if len(planner.FallbackModels) != 1 || planner.FallbackModels[0] != "anthropic/claude-sonnet-4-6" {
		t.Fatalf("planner fallbacks = %#v", planner.FallbackModels)
	}
	if planner.ReasoningLevel != "medium" || planner.ModelSettings.ThinkingBudget != 4096 {
		t.Fatalf("planner reasoning = %q budget=%d", planner.ReasoningLevel, planner.ModelSettings.ThinkingBudget)
	}
	if planner.TextVerbosity != "low" || planner.ModelSettings.TextVerbosity != "low" {
		t.Fatalf("planner verbosity = %q settings=%q, want low", planner.TextVerbosity, planner.ModelSettings.TextVerbosity)
	}

	noModeReasoning := ResolveRoleModeRouting("openai/gpt-5.3-codex", "openai", "executor", &ModeModelRouting{})
	if noModeReasoning.ReasoningLevel != "" || noModeReasoning.ModelSettings.ThinkingBudget != 0 {
		t.Fatalf("no mode reasoning = %q budget=%d", noModeReasoning.ReasoningLevel, noModeReasoning.ModelSettings.ThinkingBudget)
	}
}

package agent

import "context"

// Model is the provider-agnostic interface for LLM interaction.
// Implementations exist for Anthropic and OpenAI.
type Model interface {
	// GetResponse sends a request and returns a complete response.
	GetResponse(ctx context.Context, req ModelRequest) (*ModelResponse, error)

	// StreamResponse sends a request and returns a streaming response.
	StreamResponse(ctx context.Context, req ModelRequest) (*ModelStream, error)

	// GetRetryAdvice determines whether a failed call should be retried.
	GetRetryAdvice(err error) *ModelRetryAdvice

	// CalculateCost returns the USD cost for the given usage.
	CalculateCost(usage Usage) float64

	// Provider returns the provider name ("anthropic" or "openai").
	Provider() string
}

// ContextCompactor is implemented by models that support provider-native
// context compaction, such as OpenAI Responses compaction.
type ContextCompactor interface {
	SupportsContextCompaction() bool
	CompactContext(ctx context.Context, req ModelRequest) (*CompactionResult, error)
}

// UsageCacheSemantics is implemented by models to declare how their provider
// reports prompt-side usage. OpenAI-style usage reports input_tokens
// INCLUSIVE of cached tokens (cached_tokens is a subset), while
// Anthropic-style usage reports input_tokens EXCLUSIVE of cache reads and
// creations (they are additive fields). Models that do not implement this
// interface are treated as Anthropic-style (additive).
type UsageCacheSemantics interface {
	// UsageInputIncludesCacheTokens returns true when Usage.InputTokens
	// already contains the cache read/creation tokens for the request.
	UsageInputIncludesCacheTokens() bool
}

// usageContextTokens returns the total prompt-side tokens one request
// actually consumed, normalizing provider usage semantics. Summing cache
// fields on top of OpenAI-style input_tokens double-counts the cached prompt
// (nearly the whole context on warm requests) — that inflated the estimator
// calibration and made compaction fire at ~half the real window.
func usageInputIncludesCache(model Model) (bool, bool) {
	semantics, known := model.(UsageCacheSemantics)
	if !known {
		return false, false
	}
	return semantics.UsageInputIncludesCacheTokens(), true
}

func usageContextTokens(model Model, usage Usage) int64 {
	if semantics, ok := model.(UsageCacheSemantics); ok && semantics.UsageInputIncludesCacheTokens() {
		return usage.InputTokens
	}
	return usage.InputTokens + usage.CacheReadTokens + usage.CacheCreateTokens
}

// ModelRequest contains everything needed for a model call.
type ModelRequest struct {
	Model               string
	PromptCacheKey      string
	Instructions        string
	Input               []RunItem
	Tools               []Tool
	Settings            ModelSettings
	OutputSchema        *OutputSchema
	CompactionThreshold int
}

// ModelResponse is the complete response from a model call.
type ModelResponse struct {
	Items     []RunItem
	Usage     Usage
	Raw       any     // provider-specific raw response for debugging
	CostUSD   float64 // estimated cost in USD (set by runner after model returns)
	CostKnown bool    // whether cost estimate is considered reliable
	// EndTurn carries an explicit provider decision about whether this response
	// ends the current user turn. nil means the provider omitted the signal and
	// the runner falls back to its normal response classification; false requests
	// another model step even when the response contains text but no tool call.
	EndTurn *bool
	// ContextTokens is the provider-normalized prompt-side size of this
	// request (set by the runner, see usageContextTokens): the true context
	// pressure regardless of whether the provider reports cache tokens as a
	// subset of input (OpenAI-style) or additive to it (Anthropic-style).
	// Hosts must use this for window gauges instead of summing usage fields.
	ContextTokens int64
}

// CompactionResult is the provider-native compacted context window.
type CompactionResult struct {
	Items   []RunItem
	Usage   Usage
	Raw     any
	Summary string
}

// ToRunItems returns the items from this response.
func (r *ModelResponse) ToRunItems() []RunItem {
	return r.Items
}

// ModelStream provides streaming access to a model response.
type ModelStream struct {
	Events <-chan ModelStreamEvent
	done   chan *ModelResponse
}

func NewModelStream(events <-chan ModelStreamEvent, done chan *ModelResponse) *ModelStream {
	return &ModelStream{Events: events, done: done}
}

// ModelStreamEventType identifies the kind of model stream event.
type ModelStreamEventType int

const (
	ModelStreamDelta          ModelStreamEventType = iota // partial text/tool content
	ModelStreamItemDone                                   // complete item ready
	ModelStreamComplete                                   // stream finished
	ModelStreamError                                      // terminal stream error
	ModelStreamReasoningDelta                             // partial reasoning/thinking content
)

// ModelStreamEvent is a single event from a streaming model call.
type ModelStreamEvent struct {
	Type     ModelStreamEventType
	Delta    string         // for Delta events
	Item     *RunItem       // for ItemDone events
	Response *ModelResponse // for Complete events
	Error    error          // for Error events
}

// Final blocks until the stream completes and returns the full response.
func (s *ModelStream) Final() *ModelResponse {
	return <-s.done
}

package agent

import (
	"errors"
	"strconv"
	"strings"
)

func effectiveFallbackModels(a *Agent, cfg RunConfig) []string {
	if len(cfg.FallbackModels) > 0 {
		return cloneNonEmptyStrings(cfg.FallbackModels)
	}
	if a == nil {
		return nil
	}
	return cloneNonEmptyStrings(a.FallbackModels)
}

func nextFallbackModel(primary, current string, fallbacks []string) (string, bool) {
	chain := fallbackModelChain(primary, fallbacks)
	if len(chain) <= 1 {
		return "", false
	}
	current = strings.TrimSpace(current)
	idx := -1
	for i, model := range chain {
		if sameModelID(model, current) {
			idx = i
			break
		}
	}
	for _, model := range chain[idx+1:] {
		if strings.TrimSpace(model) != "" && !sameModelID(model, current) {
			return model, true
		}
	}
	return "", false
}

func fallbackModelChain(primary string, fallbacks []string) []string {
	chain := make([]string, 0, len(fallbacks)+1)
	seen := map[string]struct{}{}
	appendModel := func(model string) {
		model = strings.TrimSpace(model)
		if model == "" {
			return
		}
		key := strings.ToLower(model)
		if _, ok := seen[key]; ok {
			return
		}
		seen[key] = struct{}{}
		chain = append(chain, model)
	}
	appendModel(primary)
	for _, model := range fallbacks {
		appendModel(model)
	}
	return chain
}

func cloneNonEmptyStrings(values []string) []string {
	out := make([]string, 0, len(values))
	for _, value := range values {
		value = strings.TrimSpace(value)
		if value != "" {
			out = append(out, value)
		}
	}
	return out
}

func shouldFallbackModelCall(err error, advice *ModelRetryAdvice) bool {
	if err == nil || isContextCancellation(err) || isContextLengthExceededError(err) {
		return false
	}
	var behaviorErr *ModelBehaviorError
	if errors.As(err, &behaviorErr) {
		return false
	}
	if streamOutputWasCommitted(err) {
		return false
	}
	if advice == nil || !advice.ShouldRetry {
		return false
	}
	return fallbackReason(advice) != ""
}

func fallbackReason(advice *ModelRetryAdvice) string {
	if advice == nil {
		return ""
	}
	reason := strings.ToLower(strings.TrimSpace(advice.Reason))
	if reason == "" {
		return ""
	}
	if code, err := strconv.Atoi(reason); err == nil {
		switch code {
		case 429:
			return "rate_limit"
		case 402:
			return "quota"
		case 503, 529:
			return "overloaded"
		}
		return ""
	}
	switch {
	case strings.Contains(reason, "rate_limit"), strings.Contains(reason, "too_many_requests"), strings.Contains(reason, "too many requests"):
		return "rate_limit"
	case strings.Contains(reason, "overloaded"):
		return "overloaded"
	case strings.Contains(reason, "quota"), strings.Contains(reason, "billing"), strings.Contains(reason, "subscription"), strings.Contains(reason, "credit"):
		return "quota"
	case strings.Contains(reason, "limit_exceeded"), strings.Contains(reason, "exhausted"):
		return "quota"
	default:
		return ""
	}
}

func sameModelID(a, b string) bool {
	return strings.EqualFold(strings.TrimSpace(a), strings.TrimSpace(b))
}

type streamOutputCommittedError struct {
	cause error
}

func streamOutputWasCommitted(err error) bool {
	var committedErr *streamOutputCommittedError
	return errors.As(err, &committedErr)
}

func (e *streamOutputCommittedError) Error() string {
	if e == nil || e.cause == nil {
		return "model stream failed after output was emitted"
	}
	return e.cause.Error()
}

func (e *streamOutputCommittedError) Unwrap() error {
	if e == nil {
		return nil
	}
	return e.cause
}

package agent

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"strings"
	"testing"
)

type fallbackTestProvider struct {
	models map[string]*fallbackTestModel
	names  []string
}

func (p *fallbackTestProvider) GetModel(name string) (Model, error) {
	p.names = append(p.names, name)
	model := p.models[name]
	if model == nil {
		return nil, errors.New("unknown model " + name)
	}
	return model, nil
}

func (p *fallbackTestProvider) Close() error { return nil }

type fallbackTestModel struct {
	provider     string
	responses    []*ModelResponse
	errors       []error
	retryAdvices []ModelRetryAdvice
	requests     []ModelRequest
	callIdx      int
}

func (m *fallbackTestModel) GetResponse(_ context.Context, req ModelRequest) (*ModelResponse, error) {
	m.requests = append(m.requests, req)
	idx := m.callIdx
	m.callIdx++
	if idx < len(m.errors) && m.errors[idx] != nil {
		return nil, m.errors[idx]
	}
	if idx >= len(m.responses) {
		return nil, errors.New("no response")
	}
	return m.responses[idx], nil
}

func (m *fallbackTestModel) StreamResponse(ctx context.Context, req ModelRequest) (*ModelStream, error) {
	resp, err := m.GetResponse(ctx, req)
	if err != nil {
		return nil, err
	}
	events := make(chan ModelStreamEvent, 1)
	done := make(chan *ModelResponse, 1)
	go func() {
		defer close(events)
		events <- ModelStreamEvent{Type: ModelStreamComplete, Response: resp}
		done <- resp
	}()
	return NewModelStream(events, done), nil
}

func (m *fallbackTestModel) GetRetryAdvice(error) *ModelRetryAdvice {
	idx := m.callIdx - 1
	if idx >= 0 && idx < len(m.retryAdvices) {
		advice := m.retryAdvices[idx]
		return &advice
	}
	return &ModelRetryAdvice{ShouldRetry: false}
}

func (m *fallbackTestModel) CalculateCost(Usage) float64 { return 0 }
func (m *fallbackTestModel) Provider() string            { return m.provider }

func TestRunnerFallsBackAcrossProvidersOnRateLimit(t *testing.T) {
	rateLimitErr := errors.New("subscription limit reached")
	primary := &fallbackTestModel{
		provider:     "openai",
		errors:       []error{rateLimitErr},
		retryAdvices: []ModelRetryAdvice{{ShouldRetry: true, Reason: "429"}},
	}
	fallback := &fallbackTestModel{
		provider: "anthropic",
		responses: []*ModelResponse{{
			Items: []RunItem{{Type: RunItemMessage, Message: &MessageOutput{Text: "done on fallback"}}},
		}},
	}
	provider := &fallbackTestProvider{models: map[string]*fallbackTestModel{
		"openai/gpt-primary":          primary,
		"anthropic/claude-sonnet-4-6": fallback,
	}}
	runner := NewRunnerWithProvider(provider)
	agent := &Agent{
		Name:           "agent",
		Model:          "openai/gpt-primary",
		FallbackModels: []string{"anthropic/claude-sonnet-4-6", "copilot/gpt-4.1"},
	}

	var buf bytes.Buffer
	hooks := NewPlatformHooks(NewProgressTracker(), NewEventStream(&buf))
	result, err := runner.Run(context.Background(), agent, nil, RunConfig{Hooks: hooks})
	if err != nil {
		t.Fatal(err)
	}
	if result.FinalText() != "done on fallback" {
		t.Fatalf("FinalText() = %q", result.FinalText())
	}
	if strings.Join(provider.names, ",") != "openai/gpt-primary,anthropic/claude-sonnet-4-6" {
		t.Fatalf("provider names = %#v", provider.names)
	}
	if got := fallback.requests[0].Model; got != "claude-sonnet-4-6" {
		t.Fatalf("fallback request model = %q, want claude-sonnet-4-6", got)
	}

	attempts := decodeLLMAttempts(t, buf.String())
	if len(attempts) != 4 {
		t.Fatalf("llm attempts = %d, want 4: %+v", len(attempts), attempts)
	}
	if attempts[1].Status != "fallback" || !attempts[1].FallbackPlanned || attempts[1].FallbackFromModel != "openai/gpt-primary" || attempts[1].FallbackToModel != "anthropic/claude-sonnet-4-6" || attempts[1].FallbackReason != "rate_limit" {
		t.Fatalf("fallback event = %+v", attempts[1])
	}
	if attempts[2].RequestedModel != "anthropic/claude-sonnet-4-6" || attempts[2].ResolvedModel != "claude-sonnet-4-6" || attempts[2].Provider != "anthropic" {
		t.Fatalf("fallback start event = %+v", attempts[2])
	}
}

func TestShouldFallbackModelCallDefaultsToRateLimitOnly(t *testing.T) {
	if !shouldFallbackModelCall(errors.New("limited"), &ModelRetryAdvice{ShouldRetry: true, Reason: "429"}) {
		t.Fatal("429 should be fallback eligible")
	}
	if shouldFallbackModelCall(errors.New("server down"), &ModelRetryAdvice{ShouldRetry: true, Reason: "500"}) {
		t.Fatal("500 should stay on the normal retry path by default")
	}
}

func TestShouldFallbackModelCallRejectsCommittedStreamOutput(t *testing.T) {
	err := &streamOutputCommittedError{cause: errors.New("rate limit after delta")}
	if shouldFallbackModelCall(err, &ModelRetryAdvice{ShouldRetry: true, Reason: "429"}) {
		t.Fatal("stream errors after emitted output must not fallback")
	}
}

func decodeLLMAttempts(t *testing.T, data string) []ContentEvent {
	t.Helper()
	var attempts []ContentEvent
	for _, line := range strings.Split(strings.TrimSpace(data), "\n") {
		if strings.TrimSpace(line) == "" {
			continue
		}
		var ev ContentEvent
		if err := json.Unmarshal([]byte(line), &ev); err != nil {
			t.Fatal(err)
		}
		if ev.Type == "llm_attempt" {
			attempts = append(attempts, ev)
		}
	}
	return attempts
}

