// PermissionMode controls the mutability of the runtime tool surface.
type PermissionMode string

const (
	PermissionModeReadOnly         PermissionMode = "read-only"
	PermissionModeWorkspaceWrite   PermissionMode = "workspace-write"
	PermissionModeDangerFullAccess PermissionMode = "danger-full-access"
)

// NormalizePermissionMode resolves the permission mode string to a known value.
// An empty value selects the compatible default (workspace-write); any other
// unrecognized value fails closed to read-only to avoid silently granting write
// access on a misconfiguration or typo.
func NormalizePermissionMode(mode string) PermissionMode {
	switch PermissionMode(strings.TrimSpace(mode)) {
	case PermissionModeReadOnly:
		return PermissionModeReadOnly
	case PermissionModeDangerFullAccess:
		return PermissionModeDangerFullAccess
	case PermissionModeWorkspaceWrite, "":
		return PermissionModeWorkspaceWrite
	default:
		return PermissionModeReadOnly
	}
}

func (m PermissionMode) AllowsWriteTools() bool {
	return NormalizePermissionMode(string(m)) != PermissionModeReadOnly
}

func (m PermissionMode) AllowsMCPTool(readOnlyHint bool) bool {
	if NormalizePermissionMode(string(m)) == PermissionModeReadOnly {
		return readOnlyHint
	}
	return true
}

package policy

import "testing"

func TestNormalizePermissionMode(t *testing.T) {
	tests := []struct {
		input string
		want  PermissionMode
	}{
		{"", PermissionModeWorkspaceWrite},
		{"read-only", PermissionModeReadOnly},
		{"workspace-write", PermissionModeWorkspaceWrite},
		{"danger-full-access", PermissionModeDangerFullAccess},
		{"unexpected", PermissionModeReadOnly},
	}

	for _, tt := range tests {
		if got := NormalizePermissionMode(tt.input); got != tt.want {
			t.Errorf("NormalizePermissionMode(%q) = %q, want %q", tt.input, got, tt.want)
		}
	}
}

func TestPermissionModeAllowsMCPTool(t *testing.T) {
	if PermissionModeReadOnly.AllowsMCPTool(false) {
		t.Fatal("read-only mode should block write-capable MCP tools")
	}
	if !PermissionModeReadOnly.AllowsMCPTool(true) {
		t.Fatal("read-only mode should allow read-only MCP tools")
	}
	if !PermissionModeWorkspaceWrite.AllowsMCPTool(false) {
		t.Fatal("workspace-write should allow MCP tools")
	}
}

package policy

// RuntimePolicy is the resolved runtime surface exposed to an agent session.
type RuntimePolicy struct {
	PermissionMode    PermissionMode
	GitRemoteWrites   GitRemoteWrites
	EnableMCP         bool
	EnableHooks       bool
	EnablePlugins     bool
	AllowedAgentKinds []string
	AllowedSkills     []string
}

// Normalize applies fail-closed defaults. A zero-value policy enables no
// optional runtime features.
func (p RuntimePolicy) Normalize() RuntimePolicy {
	p.PermissionMode = NormalizePermissionMode(string(p.PermissionMode))
	p.GitRemoteWrites = NormalizeGitRemoteWrites(p.GitRemoteWrites)
	return p
}

package policy

// ToolPolicy exposes the tool-specific permissions derived from RuntimePolicy.
type ToolPolicy struct {
	PermissionMode PermissionMode
}

func NewToolPolicy(runtimePolicy RuntimePolicy) ToolPolicy {
	normalized := runtimePolicy.Normalize()
	return ToolPolicy{
		PermissionMode: normalized.PermissionMode,
	}
}

func (p ToolPolicy) AllowsWriteTools() bool {
	return p.PermissionMode.AllowsWriteTools()
}

