		Agent:   &Agent{Name: "child"},
		Message: "go",
		TaskID:  "task-stable-123",
		RunConfig: RunConfig{
			PromptCacheKey:       "parent-key-must-not-leak",
			PromptCacheNamespace: "shared-run",
		},
	})
	want := promptCacheWireKey("shared-run", "task-stable-123")
	if len(model.requests) != 1 || model.requests[0].PromptCacheKey != want {
		t.Fatalf("requests = %+v, want child task prompt cache key %q", model.requests, want)
	}
}

package agent

import (
	"fmt"
	"time"

	agentpolicy "github.com/gratefulagents/sdk/internal/agent/policy"
)

// Record* methods aggregate metrics (cost, tokens) and emit OTel spans.
// Content events are handled by EventStream (event_stream.go).

// RecordSystemInit logs a system initialization event.
func (t *ProgressTracker) RecordSystemInit(model, cwd string, toolsList []string, maxTurns int, mcpServers []string, permissionMode agentpolicy.PermissionMode) {
	t.mu.Lock()
	defer t.mu.Unlock()
	t.currentStep = "starting"
	t.addEventLocked(ProgressEvent{
		Timestamp: time.Now(),
		EventType: "step_change",
		Summary:   "Agent session initialized",
	})
}

// RecordAssistantText logs assistant text content.
func (t *ProgressTracker) RecordAssistantText(text string) {
	if t == nil {
		return
	}
	t.mu.Lock()
	defer t.mu.Unlock()
	t.lastAssistantText = text
	t.lastActivity = Truncate(text, 120)
}

// RecordAssistantThinking logs assistant thinking content.
func (t *ProgressTracker) RecordAssistantThinking(thinking string) {
	if t == nil {
		return
	}
	t.mu.Lock()
	defer t.mu.Unlock()
	t.lastAssistantThinking = thinking
}

// RecordToolUse logs a tool invocation.
func (t *ProgressTracker) RecordToolUse(toolName, inputSummary, toolUseID string, turn int, rawInput string, agentName string, parentCallID string) {
	if t == nil {
		return
	}
	t.mu.Lock()
	t.toolCallCount++
	t.sessionToolCallCount++
	t.lastActivity = fmt.Sprintf("Tool: %s", toolName)
	t.inferStepLocked(toolName, inputSummary)
	parent := t.parent
	t.mu.Unlock()
	// Forward the counter up the tracker chain so run-level tool-call totals
	// include subagent activity. Only the counters propagate: ancestors keep
	// their own lastActivity/step state.
	parent.recordForwardedToolCall()
}

// recordForwardedToolCall bumps tool-call counters for a descendant tracker's
// tool use without touching activity/step-inference state, then continues up
// the parent chain so arbitrarily nested subagent tool calls roll up.
func (t *ProgressTracker) recordForwardedToolCall() {
	if t == nil {
		return
	}
	t.mu.Lock()
	t.toolCallCount++
	t.sessionToolCallCount++
	parent := t.parent
	t.mu.Unlock()
	parent.recordForwardedToolCall()
}

// RecordToolResult logs a tool execution result.
func (t *ProgressTracker) RecordToolResult(toolUseID, toolName, output string, isError bool, durationMS int64, agentName string, parentCallID string) {
	if t == nil {
		return
	}
	t.mu.Lock()
	defer t.mu.Unlock()
	status := "completed"
	if isError {
		status = "failed"
	}
	summary := fmt.Sprintf("Tool %s %s", toolName, status)
	if output != "" {
		summary = fmt.Sprintf("%s: %s", summary, Truncate(output, 120))
	}
	t.lastActivity = summary
	t.addEventLocked(ProgressEvent{
		Timestamp: time.Now(),
		EventType: "tool_result",
		Summary:   summary,
	})
}

// RecordLifecycleEvent logs a normalized lifecycle event.
func (t *ProgressTracker) RecordLifecycleEvent(eventType string, message string) {
	if t == nil {
		return
	}
	t.mu.Lock()
	defer t.mu.Unlock()
	if eventType == "" {
		eventType = "lifecycle"
	}
	if message != "" {
		t.lastActivity = Truncate(message, 120)
	}
	t.addEventLocked(ProgressEvent{
		Timestamp: time.Now(),
		EventType: eventType,
		Summary:   message,
	})
}

// HookEvent captures the context of a hook invocation for recording.
type HookEvent struct {
	ToolName string
	Type     string
}

// HookResult captures the outcome of a hook invocation for recording.
type HookResult struct {
	Decision string
	Reason   string
}

// RecordHookDecision logs the result of dispatching a pre/post-tool hook.
func (t *ProgressTracker) RecordHookDecision(event HookEvent, result HookResult) {
}

// RecordLLMUsage accumulates cost and token counts from a single LLM call
// so the tracker's Snapshot() stays current between session-complete events.
// Child trackers forward every call up the parent chain, so run-level totals
// (cost caps, session metrics) include subagent usage — cache tokens included
// — as it happens, and usage from subagents that later fail or are cancelled
// is never lost. Nested subagents roll up the same way, one level at a time.
func (t *ProgressTracker) RecordLLMUsage(model string, costUSD float64, usage Usage) {
	if t == nil {
		return
	}
	t.mu.Lock()
	t.costUsd += costUSD
	t.sessionCostUsd += costUSD
	t.inputTokens += usage.InputTokens
	t.outputTokens += usage.OutputTokens
	t.cacheReadInputTokens += usage.CacheReadTokens
	t.cacheCreationInputTokens += usage.CacheCreateTokens
	t.updateModelUsageLocked(model, usage.InputTokens, usage.OutputTokens,
		usage.CacheReadTokens, usage.CacheCreateTokens)
	parent := t.parent
	t.mu.Unlock()
	parent.RecordLLMUsage(model, costUSD, usage)
}

// RecordSessionComplete logs session completion with final metrics.
// Note: cost/token accumulation is handled per-call by RecordLLMUsage;
// this method only emits the session_complete event and OTel span.
func (t *ProgressTracker) RecordSessionComplete(model string, costUSD float64, numTurns int, usage Usage, duration time.Duration, stopReason string) {
	t.mu.Lock()
	defer t.mu.Unlock()

	resultEv := ProgressEvent{
		Timestamp: time.Now(),
		EventType: "session_complete",
		Summary:   fmt.Sprintf("Session %d complete: $%.4f, %d turns", t.sessionNumber, costUSD, numTurns),
	}
	t.addEventLocked(resultEv)
	t.pendingEvents = append(t.pendingEvents, resultEv)

	// Emit OTel span for session completion with all metrics.
	if t.tp != nil {
		span := NewSpan("session", t.rootSpanID, SessionSpanData{
			Model:                    model,
			CostUSD:                  costUSD,
			NumTurns:                 numTurns,
			DurationMS:               duration.Milliseconds(),
			InputTokens:              usage.InputTokens,
			OutputTokens:             usage.OutputTokens,
			CacheReadInputTokens:     usage.CacheReadTokens,
			CacheCreationInputTokens: usage.CacheCreateTokens,
			StopReason:               stopReason,
		})
		t.tp.OnSpanStart(span)
		span.Finish()
		t.tp.OnSpanEnd(span)
	}
}

// RecordSubagentStarted logs a subagent launch.
func (t *ProgressTracker) RecordSubagentStarted(taskID, toolUseID, description, subagentType, model, isolation, prompt string) {
	t.mu.Lock()
	defer t.mu.Unlock()
	t.agentCount++
	t.taskAgents[taskID] = AgentMeta{
		SubagentType: subagentType,
		Description:  description,
		Model:        model,
		Isolation:    isolation,
		Prompt:       prompt,
	}
	t.addEventLocked(ProgressEvent{
		Timestamp: time.Now(),
		EventType: "agent_spawn",
		Summary:   fmt.Sprintf("Spawned agent [%s]: %s", subagentType, description),
	})
	// Emit OTel span for subagent start. The span is kept open (stored per
	// task ID) so RecordSubagentCompleted ends this same span and the span's
	// time range covers the subagent's actual lifetime.
	if t.tp != nil {
		span := NewSpan("subagent."+subagentType, t.rootSpanID, SubagentSpanData{
			TaskID:      taskID,
			Type:        subagentType,
			Description: description,
			Model:       model,
			Status:      "initializing",
		})
		t.tp.OnSpanStart(span)
		if t.subagentSpans == nil {
			t.subagentSpans = make(map[string]*Span)
		}
		t.subagentSpans[taskID] = span
	}
}

// RecordSubagentProgress logs subagent progress (metrics only).
func (t *ProgressTracker) RecordSubagentProgress(taskID string, toolCount int32, totalTokens int64, durationMS int64, lastToolName string) {
	t.mu.Lock()
	defer t.mu.Unlock()
	summary := fmt.Sprintf("Subagent %s progress: %d tools, %d tokens", taskID, toolCount, totalTokens)
	if lastToolName != "" {
		summary += fmt.Sprintf(", last tool %s", lastToolName)
	}
	t.lastActivity = summary
	t.addEventLocked(ProgressEvent{
		Timestamp: time.Now(),
		EventType: "subagent_progress",
		Summary:   summary,
	})
}

// RecordSubagentCompleted logs subagent completion.
func (t *ProgressTracker) RecordSubagentCompleted(taskID, status, summary string, costUSD float64, numTurns int, usage Usage, stopReason string, filesRead, filesWritten []string) {
	t.mu.Lock()
	defer t.mu.Unlock()
	meta := t.taskAgents[taskID]
	t.lastActivity = Truncate(summary, 120)
	// Aggregate cost/token accounting is NOT updated here: the child tracker
	// forwards every LLM call and tool use to this tracker live (see
	// RecordLLMUsage / recordForwardedToolCall), so re-adding the subagent's
	// totals at completion would double count. The costUSD/usage parameters
	// only feed the completion span below.
	// Close the lifecycle span opened by RecordSubagentStarted with the full
	// final metrics so its duration reflects the subagent's real runtime.
	if t.tp != nil {
		span := t.subagentSpans[taskID]
		delete(t.subagentSpans, taskID)
		data := SubagentSpanData{
			TaskID:            taskID,
			Type:              meta.SubagentType,
			Description:       meta.Description,
			Model:             meta.Model,
			Status:            status,
			CostUSD:           costUSD,
			NumTurns:          numTurns,
			TotalTokens:       usage.InputTokens + usage.OutputTokens,
			InputTokens:       usage.InputTokens,
			OutputTokens:      usage.OutputTokens,
			CacheReadTokens:   usage.CacheReadTokens,
			CacheCreateTokens: usage.CacheCreateTokens,
			StopReason:        stopReason,
			Isolation:         meta.Isolation,
			Prompt:            meta.Prompt,
			ResultText:        Truncate(summary, 4096),
			FilesRead:         filesRead,
			FilesWritten:      filesWritten,
		}
		if span == nil {
			// No matching start (tracker restarted or processor wired late):
			// emit a point-in-time completion span so the data still lands.
			span = NewSpan("subagent."+meta.SubagentType, t.rootSpanID, data)
			t.tp.OnSpanStart(span)
		}
		data.DurationMS = time.Since(span.StartTime).Milliseconds()
		span.Data = data
		span.Finish()
		t.tp.OnSpanEnd(span)
	}
	if status == "completed" || status == "failed" || status == "stopped" {
		delete(t.taskAgents, taskID)
	}
}

// RecordAPIRetry logs an API retry event.
func (t *ProgressTracker) RecordAPIRetry(errorCode string, retryAfterMS int64, attempt int32, maxRetries int32) {
	t.mu.Lock()
	defer t.mu.Unlock()
	t.apiRetries++
	if t.tp != nil {
		span := NewSpan("api.retry", t.rootSpanID, RetrySpanData{
			ErrorCode:    errorCode,
			RetryAfterMS: retryAfterMS,
			Attempt:      attempt,
			MaxRetries:   maxRetries,
		})
		t.tp.OnSpanStart(span)
		span.Finish()
		t.tp.OnSpanEnd(span)
	}
}

// RecordCompactBoundary logs a context compaction event with token counts.
func (t *ProgressTracker) RecordCompactBoundary(tokensBefore, tokensAfter int, _ string) {
	t.mu.Lock()
	defer t.mu.Unlock()
	if t.tp != nil {
		span := NewSpan("compaction", t.rootSpanID, CompactionSpanData{
			TokensBefore: tokensBefore,
			TokensAfter:  tokensAfter,
		})
		t.tp.OnSpanStart(span)
		span.Finish()
		t.tp.OnSpanEnd(span)
	}
}

package agent

import (
	"context"
	"encoding/json"
	"errors"
	"math"
	"strings"
	"testing"
)

// Subagent usage must roll up into the run-level tracker as it happens:
// cost, input/output tokens, AND cache tokens, through arbitrarily nested
// child trackers. This is what keeps cost-per-run / tokens-per-run metrics
// (and cost-cap enforcement) accurate while subagents are still running.
func TestChildTrackerForwardsLLMUsageToAncestors(t *testing.T) {
	parent := NewProgressTracker()
	parent.SetSession(1, "implementing")
	child := NewChildTracker(parent, "task_child")
	grandchild := NewChildTracker(child, "task_grandchild")

	childUsage := Usage{InputTokens: 100, OutputTokens: 40, CacheReadTokens: 2000, CacheCreateTokens: 300}
	grandchildUsage := Usage{InputTokens: 10, OutputTokens: 4, CacheReadTokens: 500, CacheCreateTokens: 50}

	child.RecordLLMUsage("model-a", 0.25, childUsage)
	grandchild.RecordLLMUsage("model-b", 0.05, grandchildUsage)

	parentSnap := parent.Snapshot()
	if math.Abs(parentSnap.CostUsd-0.30) > 1e-9 {
		t.Errorf("parent CostUsd = %v, want 0.30", parentSnap.CostUsd)
	}
	if parentSnap.InputTokens != 110 || parentSnap.OutputTokens != 44 {
		t.Errorf("parent tokens = %d/%d, want 110/44", parentSnap.InputTokens, parentSnap.OutputTokens)
	}
	if parentSnap.CacheReadInputTokens != 2500 || parentSnap.CacheCreationInputTokens != 350 {
		t.Errorf("parent cache tokens = %d/%d, want 2500/350",
			parentSnap.CacheReadInputTokens, parentSnap.CacheCreationInputTokens)
	}
	if mu, ok := parentSnap.ModelUsage["model-b"]; !ok || mu.InputTokens != 10 {
		t.Errorf("parent ModelUsage[model-b] = %+v (ok=%v), want grandchild usage forwarded", mu, ok)
	}

	// The intermediate child sees its own usage plus the grandchild's,
	// but not vice versa.
	childSnap := child.Snapshot()
	if childSnap.InputTokens != 110 {
		t.Errorf("child InputTokens = %d, want 110", childSnap.InputTokens)
	}
	grandchildSnap := grandchild.Snapshot()
	if grandchildSnap.InputTokens != 10 {
		t.Errorf("grandchild InputTokens = %d, want 10", grandchildSnap.InputTokens)
	}
}

// Tool calls made by subagents count toward the run's tool-call total, but
// must not disturb the parent's own activity/step-inference state.
func TestChildTrackerForwardsToolCallCounts(t *testing.T) {
	parent := NewProgressTracker()
	parent.SetSession(1, "implementing")
	child := NewChildTracker(parent, "task_child")
	grandchild := NewChildTracker(child, "task_grandchild")

	child.RecordToolUse("Edit", "/file.go", "tu_1", 1, `{}`, "", "")
	grandchild.RecordToolUse("Bash", "ls", "tu_2", 1, `{}`, "", "")

	parentSnap := parent.Snapshot()
	if parentSnap.ToolCallCount != 2 {
		t.Errorf("parent ToolCallCount = %d, want 2", parentSnap.ToolCallCount)
	}
	if parentSnap.CurrentStep != "implementing" {
		t.Errorf("parent CurrentStep = %q, want unchanged %q", parentSnap.CurrentStep, "implementing")
	}
	if parentSnap.LastActivity != "" {
		t.Errorf("parent LastActivity = %q, want untouched by forwarded tool calls", parentSnap.LastActivity)
	}
	if child.Snapshot().ToolCallCount != 2 {
		t.Errorf("child ToolCallCount = %d, want 2", child.Snapshot().ToolCallCount)
	}
}

// With live per-call forwarding, RecordSubagentCompleted must not re-add the
// subagent's usage: that would double count every completed subagent.
func TestRecordSubagentCompletedDoesNotDoubleCountForwardedUsage(t *testing.T) {
	parent := NewProgressTracker()
	parent.SetSession(1, "implementing")
	child := NewChildTracker(parent, "task_1")

	usage := Usage{InputTokens: 1000, OutputTokens: 500, CacheReadTokens: 8000, CacheCreateTokens: 200}
	child.RecordLLMUsage("model-a", 0.10, usage)

	parent.RecordSubagentStarted("task_1", "tu_1", "explore", "explore", "model-a", "", "prompt")
	parent.RecordSubagentCompleted("task_1", "completed", "done", 0.10, 3, usage, "end_turn", nil, nil)

	snap := parent.Snapshot()
	if math.Abs(snap.CostUsd-0.10) > 1e-9 {
		t.Errorf("parent CostUsd = %v, want 0.10 (no double count)", snap.CostUsd)
	}
	if snap.InputTokens != 1000 || snap.OutputTokens != 500 {
		t.Errorf("parent tokens = %d/%d, want 1000/500 (no double count)", snap.InputTokens, snap.OutputTokens)
	}
	if snap.CacheReadInputTokens != 8000 || snap.CacheCreationInputTokens != 200 {
		t.Errorf("parent cache tokens = %d/%d, want 8000/200", snap.CacheReadInputTokens, snap.CacheCreationInputTokens)
	}
}

// Compaction model calls (provider-side or LLM-summary) bypass OnLLMEnd and
// add their usage straight to RunResult.Usage. They must still be booked on
// the platform tracker, or run-level totals drift below RunResult.Usage —
// and for subagents (whose completion no longer re-adds RunResult.Usage to
// the parent) the compaction spend would vanish entirely.
func TestCompactionUsageReachesTracker(t *testing.T) {
	model := &mockModel{
		costPerCall: 0.10,
		responses: []*ModelResponse{
			{ // LLM-summary compaction call
				Items: []RunItem{{Type: RunItemMessage, Message: &MessageOutput{Text: "Findings: earlier work summarized."}}},
				Usage: Usage{InputTokens: 500, OutputTokens: 40, CacheReadTokens: 30, CacheCreateTokens: 5},
			},
			{ // the actual turn
				Items: []RunItem{{Type: RunItemMessage, Message: &MessageOutput{Text: "done"}}},
				Usage: Usage{InputTokens: 15, OutputTokens: 8, CacheReadTokens: 2, CacheCreateTokens: 1},
			},
		},
	}
	runner := NewRunnerWithModel(model)
	tracker := NewProgressTracker()
	tracker.SetSession(1, "implementing")
	var buf strings.Builder
	hooks := NewPlatformHooks(tracker, NewEventStream(&buf))

	result, err := runner.Run(context.Background(), &Agent{Name: "test"}, manyCompactableItems(30), RunConfig{
		Hooks:    hooks,
		MaxTurns: 3,
		CompactionConfig: CompactionConfig{
			Enabled: true, TriggerTokens: 100, TargetTokens: 80,
			PreserveRecentItems: 3, PreserveInitialUserMessages: 1,
			SummaryBulletLimit: 4, UseLLMSummary: true,
		},
	})
	if err != nil {
		t.Fatal(err)
	}
	if result.FinalText() != "done" {
		t.Fatalf("final text = %q", result.FinalText())
	}
	if result.Usage.InputTokens != 515 || result.Usage.OutputTokens != 48 {
		t.Fatalf("result usage = %d/%d, want 515/48 (compaction call not counted?)",
			result.Usage.InputTokens, result.Usage.OutputTokens)
	}

	// The tracker must account for everything RunResult.Usage does,
	// including the compaction call that bypasses OnLLMEnd.
	snap := tracker.Snapshot()
	if snap.InputTokens != result.Usage.InputTokens || snap.OutputTokens != result.Usage.OutputTokens {
		t.Errorf("tracker tokens = %d/%d, want %d/%d (RunResult.Usage)",
			snap.InputTokens, snap.OutputTokens, result.Usage.InputTokens, result.Usage.OutputTokens)
	}
	if snap.CacheReadInputTokens != result.Usage.CacheReadTokens || snap.CacheCreationInputTokens != result.Usage.CacheCreateTokens {
		t.Errorf("tracker cache tokens = %d/%d, want %d/%d",
			snap.CacheReadInputTokens, snap.CacheCreationInputTokens,
			result.Usage.CacheReadTokens, result.Usage.CacheCreateTokens)
	}
	if math.Abs(snap.CostUsd-0.20) > 1e-9 {
		t.Errorf("tracker CostUsd = %v, want 0.20 (compaction call + turn)", snap.CostUsd)
	}
}

// A subagent that fails mid-run must still contribute everything it consumed
// before failing: to the run totals (via live forwarding) and to its own
// completion outcome/event (recovered from the child tracker, since partial
// results carry no provider-reported totals).
func TestRunSubAgentOnceFailureKeepsPartialUsage(t *testing.T) {
	echoTool := &FunctionTool{
		ToolName:        "echo",
		ToolDescription: "echoes input",
		Schema:          json.RawMessage(`{"type":"object"}`),
		Fn: func(_ context.Context, input json.RawMessage) (string, error) {
			return "echoed: " + string(input), nil
		},
	}
	model := &mockModel{
		costPerCall: 0.25,
		responses: []*ModelResponse{
			{
				Items: []RunItem{
					{Type: RunItemToolCall, ToolCall: &ToolCallData{
						ID: "call1", Name: "echo", Input: json.RawMessage(`"hello"`),
					}},
				},
				Usage: Usage{InputTokens: 100, OutputTokens: 20, CacheReadTokens: 50, CacheCreateTokens: 10},
			},
		},
		errors: []error{nil, errors.New("model exploded")},
	}
	runner := NewRunnerWithModel(model)
	parentTracker := NewProgressTracker()
	parentTracker.SetSession(1, "implementing")
	var buf strings.Builder
	es := NewEventStream(&buf)

	outcome := runSubAgentOnce(context.Background(), subAgentRunSpec{
		Runner:      runner,
		Agent:       &Agent{Name: "explore", Tools: []Tool{echoTool}},
		Message:     "do the thing",
		TaskID:      "task_fail",
		Tracker:     parentTracker,
		EventStream: es,
		RunConfig:   RunConfig{MaxTurns: 5},
	})

	if outcome.Status != subAgentStatusFailed {
		t.Fatalf("outcome.Status = %q, want failed", outcome.Status)
	}
	if outcome.Tokens != 120 || outcome.ToolCount != 1 {
		t.Errorf("outcome tokens/tools = %d/%d, want 120/1", outcome.Tokens, outcome.ToolCount)
	}
	if math.Abs(outcome.CostUSD-0.25) > 1e-9 || !outcome.CostKnown {
		t.Errorf("outcome cost = %v (known=%v), want 0.25 (known=true)", outcome.CostUSD, outcome.CostKnown)
	}
	if outcome.Usage.CacheReadTokens != 50 || outcome.Usage.CacheCreateTokens != 10 {
		t.Errorf("outcome cache tokens = %d/%d, want 50/10",
			outcome.Usage.CacheReadTokens, outcome.Usage.CacheCreateTokens)
	}

	// Run totals include the failed subagent's spend.
	snap := parentTracker.Snapshot()
	if math.Abs(snap.CostUsd-0.25) > 1e-9 {
		t.Errorf("parent CostUsd = %v, want 0.25", snap.CostUsd)
	}
	if snap.InputTokens != 100 || snap.OutputTokens != 20 {
		t.Errorf("parent tokens = %d/%d, want 100/20", snap.InputTokens, snap.OutputTokens)
	}
	if snap.CacheReadInputTokens != 50 || snap.CacheCreationInputTokens != 10 {
		t.Errorf("parent cache tokens = %d/%d, want 50/10", snap.CacheReadInputTokens, snap.CacheCreationInputTokens)
	}
	if snap.ToolCallCount != 1 {
		t.Errorf("parent ToolCallCount = %d, want 1", snap.ToolCallCount)
	}

	// The completion event reports the partial usage instead of zeros.
	var completed *ContentEvent
	for _, line := range strings.Split(strings.TrimSpace(buf.String()), "\n") {
		var ev ContentEvent
		if err := json.Unmarshal([]byte(line), &ev); err != nil {
			t.Fatalf("unmarshal event: %v", err)
		}
		if ev.Type == "subagent_status" && ev.Status == "failed" {
			completed = &ev
			break
		}
	}
	if completed == nil {
		t.Fatal("no failed subagent_status event emitted")
	}
	if completed.SubagentTokens != 120 || completed.SubagentToolCount != 1 {
		t.Errorf("event tokens/tools = %d/%d, want 120/1", completed.SubagentTokens, completed.SubagentToolCount)
	}
	if math.Abs(completed.SubagentCostUsd-0.25) > 1e-9 || !completed.SubagentCostKnown {
		t.Errorf("event cost = %v (known=%v), want 0.25 (known=true)", completed.SubagentCostUsd, completed.SubagentCostKnown)
	}
}

package agent

import (
	"sync"
	"testing"
	"time"
)

// spanRecordingProcessor records span lifecycle events for assertions.
type spanRecordingProcessor struct {
	mu      sync.Mutex
	started []*Span
	ended   []*Span
}

func (p *spanRecordingProcessor) OnTraceStart(*Trace) {}
func (p *spanRecordingProcessor) OnTraceEnd(*Trace)   {}
func (p *spanRecordingProcessor) OnSpanStart(s *Span) {
	p.mu.Lock()
	defer p.mu.Unlock()
	p.started = append(p.started, s)
}
func (p *spanRecordingProcessor) OnSpanEnd(s *Span) {
	p.mu.Lock()
	defer p.mu.Unlock()
	p.ended = append(p.ended, s)
}
func (p *spanRecordingProcessor) Flush() {}

// RecordSubagentStarted + RecordSubagentCompleted must open and close ONE
// span whose time range covers the subagent's real lifetime and whose final
// data carries the completion metrics.
func TestSubagentSpanPairing(t *testing.T) {
	tp := &spanRecordingProcessor{}
	tracker := NewProgressTracker(WithTracingProcessor(tp))
	tracker.SetRootSpanID("root-1")

	tracker.RecordSubagentStarted("task-1", "tu-1", "explore the repo", "explore", "model-a", "shared", "prompt")
	time.Sleep(2 * time.Millisecond)
	tracker.RecordSubagentCompleted("task-1", "completed", "found it", 0.5, 3,
		Usage{InputTokens: 10, OutputTokens: 5}, "end_turn", []string{"a.go"}, nil)

	if len(tp.started) != 1 || len(tp.ended) != 1 {
		t.Fatalf("expected exactly one started and one ended span, got %d started, %d ended", len(tp.started), len(tp.ended))
	}
	if tp.started[0].ID != tp.ended[0].ID {
		t.Fatalf("start/end must be the same span: %s vs %s", tp.started[0].ID, tp.ended[0].ID)
	}
	span := tp.ended[0]
	if span.ParentID != "root-1" {
		t.Errorf("ParentID = %q, want root-1", span.ParentID)
	}
	if span.EndTime.IsZero() {
		t.Error("span must be finished")
	}
	data, ok := span.Data.(SubagentSpanData)
	if !ok {
		t.Fatalf("span data type = %T, want SubagentSpanData", span.Data)
	}
	if data.Status != "completed" {
		t.Errorf("Status = %q, want completed", data.Status)
	}
	if data.DurationMS <= 0 {
		t.Errorf("DurationMS = %d, want > 0 (real lifetime, not an instant span)", data.DurationMS)
	}
	if data.CostUSD != 0.5 || data.InputTokens != 10 || data.OutputTokens != 5 || data.TotalTokens != 15 {
		t.Errorf("final metrics not carried: %+v", data)
	}
	// Tracker must not leak the open-span entry.
	tracker.mu.Lock()
	leaked := len(tracker.subagentSpans)
	tracker.mu.Unlock()
	if leaked != 0 {
		t.Errorf("subagentSpans leaked %d entries", leaked)
	}
}

// A completion without a matching start (tracker restarted, processor wired
// late) must still emit a start/end pair so the completion data lands.
func TestSubagentCompletedWithoutStartFallsBack(t *testing.T) {
	tp := &spanRecordingProcessor{}
	tracker := NewProgressTracker(WithTracingProcessor(tp))

	tracker.RecordSubagentCompleted("task-x", "failed", "boom", 0, 1, Usage{}, "error", nil, nil)

	if len(tp.started) != 1 || len(tp.ended) != 1 {
		t.Fatalf("expected fallback start+end pair, got %d started, %d ended", len(tp.started), len(tp.ended))
	}
	if tp.started[0].ID != tp.ended[0].ID {
		t.Fatal("fallback start/end must be the same span")
	}
	data, ok := tp.ended[0].Data.(SubagentSpanData)
	if !ok {
		t.Fatalf("span data type = %T, want SubagentSpanData", tp.ended[0].Data)
	}
	if data.Status != "failed" {
		t.Errorf("Status = %q, want failed", data.Status)
	}
}

package agent

import (
	"math"
	"time"
)

// RetryPolicy configures automatic retry behavior for model calls.
type RetryPolicy struct {
	MaxRetries int
	Backoff    RetryBackoffSettings
}

// RetryBackoffSettings controls exponential backoff.
type RetryBackoffSettings struct {
	InitialDelayMS int
	MaxDelayMS     int
	Multiplier     float64
}

// DefaultRetryPolicy returns a sensible default retry policy.
func DefaultRetryPolicy() RetryPolicy {
	return RetryPolicy{
		MaxRetries: 3,
		Backoff: RetryBackoffSettings{
			InitialDelayMS: 1000,
			MaxDelayMS:     30000,
			Multiplier:     2.0,
		},
	}
}

// DelayForAttempt calculates the backoff delay for a given retry attempt (0-indexed).
// Partially-populated policies are normalized: an unset Multiplier or
// MaxDelayMS would otherwise collapse every later delay to 0 ms and hot-loop
// retries against a failing provider. An explicit InitialDelayMS <= 0 keeps
// meaning "retry immediately".
func (p *RetryPolicy) DelayForAttempt(attempt int) time.Duration {
	initial := p.Backoff.InitialDelayMS
	if initial <= 0 {
		return 0
	}
	if attempt <= 0 {
		return time.Duration(initial) * time.Millisecond
	}
	multiplier := p.Backoff.Multiplier
	if multiplier < 1 {
		multiplier = 2.0
	}
	maxDelayMS := p.Backoff.MaxDelayMS
	if maxDelayMS <= 0 {
		maxDelayMS = 30000
	}
	delay := float64(initial) * math.Pow(multiplier, float64(attempt))
	if delay > float64(maxDelayMS) {
		delay = float64(maxDelayMS)
	}
	return time.Duration(delay) * time.Millisecond
}

// maxAdviceRetriesPerTurn bounds provider-advised retries (advice.ShouldRetry)
// for a single turn, counting all failed attempts of that turn. Without a
// bound, a persistently rate-limited provider would be retried until MaxTurns,
// burning the whole turn budget on one request.
const maxAdviceRetriesPerTurn = 10

// adviceRetryDelay returns the backoff floor for a provider-advised retry that
// carries no provider-directed delay. It follows the run's retry policy curve
// (attempt is 1-indexed) so advised retries after the policy budget keep
// growing instead of hammering with zero delay.
func adviceRetryDelay(policy *RetryPolicy, attempt int) time.Duration {
	p := DefaultRetryPolicy()
	if policy != nil && policy.Backoff.InitialDelayMS > 0 {
		p = *policy
	}
	if attempt < 1 {
		attempt = 1
	}
	return p.DelayForAttempt(attempt - 1)
}

package agent

import (
	"context"
	"errors"
	"strings"
	"sync"
	"time"

	"github.com/gratefulagents/sdk/internal/modelactivity"
)

// DefaultModelCallTimeout is the default model stream inactivity budget.
// Five minutes matches Codex CLI's default stream idle timeout. The timer is
// reset whenever a provider stream event arrives, so a healthy generation may
// run longer than five minutes while a silent connection remains bounded.
const DefaultModelCallTimeout = 5 * time.Minute

var (
	errModelStreamIdleTimeout = errors.New("model response stream idle timeout")
	errImmediateInput         = errors.New("immediate input arrived")
)

// effectiveModelCallTimeout resolves the model stream inactivity timeout:
// 0 uses DefaultModelCallTimeout; a negative value disables the timeout.
func effectiveModelCallTimeout(d time.Duration) time.Duration {
	if d < 0 {
		return 0
	}
	if d == 0 {
		return DefaultModelCallTimeout
	}
	return d
}

// modelCallContext derives a hard deadline for provider operations that do not
// expose streaming progress, such as context compaction. Normal generation
// uses modelCallIdleContext instead.
func modelCallContext(ctx context.Context, timeout time.Duration) (context.Context, context.CancelFunc) {
	if to := effectiveModelCallTimeout(timeout); to > 0 {
		return context.WithTimeout(ctx, to)
	}
	return ctx, func() {}
}

// immediateInputContext cancels an uncommitted model request when input arrives.
// A committed stream cannot be safely replayed, so its signal is consumed and
// the queued input remains available to the poller at the next boundary.
func immediateInputContext(parent context.Context, signal ImmediateInputSignal, interrupt func() bool) (context.Context, context.CancelFunc) {
	if signal == nil {
		return parent, func() {}
	}
	ctx, cancelCause := context.WithCancelCause(parent)
	done := make(chan struct{})
	go func() {
		defer close(done)
		select {
		case <-ctx.Done():
		case <-signal:
			if interrupt == nil || interrupt() {
				cancelCause(errImmediateInput)
			}
		}
	}()
	return ctx, func() {
		cancelCause(context.Canceled)
		<-done
	}
}

// modelCallIdleContext derives a context cancelled after timeout elapses with
// no model stream activity. activity resets the idle timer. Callers classify
// the winner atomically through context.Cause before invoking cancel.
func modelCallIdleContext(parent context.Context, timeout time.Duration) (
	ctx context.Context,
	activity func(),
	cancel context.CancelFunc,
) {
	to := effectiveModelCallTimeout(timeout)
	if to <= 0 {
		ctx, cancel := context.WithCancel(parent)
		return ctx, func() {}, cancel
	}

	callCtx, cancelCause := context.WithCancelCause(parent)
	var stateMu sync.Mutex
	lastActivity := time.Now()
	stopped := false
	var timer *time.Timer
	var checkIdle func()
	checkIdle = func() {
		stateMu.Lock()
		if stopped || callCtx.Err() != nil {
			stopped = true
			stateMu.Unlock()
			return
		}
		if remaining := to - time.Since(lastActivity); remaining > 0 {
			timer.Reset(remaining)
			stateMu.Unlock()
			return
		}
		stopped = true
		stateMu.Unlock()
		cancelCause(errModelStreamIdleTimeout)
	}
	timer = time.AfterFunc(to, checkIdle)

	touch := func() {
		stateMu.Lock()
		defer stateMu.Unlock()
		if stopped || callCtx.Err() != nil {
			return
		}
		lastActivity = time.Now()
		timer.Reset(to)
	}
	stop := func() {
		stateMu.Lock()
		if stopped {
			stateMu.Unlock()
			return
		}
		stopped = true
		timer.Stop()
		stateMu.Unlock()
		cancelCause(context.Canceled)
	}
	return modelactivity.WithSink(callCtx, touch), touch, stop
}

// ImmediateInputPoller injects user messages at runner interruptible boundaries.
// Returned items should usually be user message RunItems (Agent == nil).
type ImmediateInputPoller func(context.Context) ([]RunItem, error)

// ImmediateInputSignal optionally wakes an in-flight, still-uncommitted model
// request when immediate input arrives. The runner cancels that attempt and
// polls the new input before issuing its replacement request. Once a model has
// emitted visible output, steering waits for the next normal boundary instead.
type ImmediateInputSignal <-chan struct{}

// ImmediateInputFinalizer atomically closes immediate-input admission if no
// input is pending, or returns pending items while leaving admission open so
// the runner can continue. It is called immediately before a final return.
type ImmediateInputFinalizer func(context.Context) ([]RunItem, error)

// CompactionModelResolver resolves model-specific compaction thresholds for a
// (possibly provider-prefixed) model name. It returns tuned trigger/target
// token thresholds — typically derived from authoritative provider metadata
// (the /models endpoint), falling back to CompactionDefaultsForModel. ok=false
// means "use the configured defaults unchanged".
//
// The runner consults this once per turn against the model actually being used,
// so a sub-agent running a different model than its parent compacts at its own
// model's context window instead of inheriting the parent's thresholds.
// Implementations must be safe for concurrent use and should cache results.
type CompactionModelResolver func(ctx context.Context, model string) (triggerTokens, targetTokens int, ok bool)

// CompactionConfig controls proactive context compaction.
type CompactionConfig struct {
	Enabled                     bool
	TriggerTokens               int
	TargetTokens                int
	PreserveRecentItems         int
	PreserveInitialUserMessages int
	SummaryBulletLimit          int
	// UseLLMSummary asks the active model to write the compaction summary
	// (findings, decisions, state, pending work) instead of the mechanical
	// tool/file digest. Falls back to the deterministic summary whenever the
	// model call fails or produces an unusable result.
	UseLLMSummary bool
}

// DefaultCompactionConfig returns a conservative default policy for long-running sessions.
func DefaultCompactionConfig() CompactionConfig {
	return CompactionConfig{
		Enabled:                     true,
		TriggerTokens:               180000,
		TargetTokens:                100000,
		PreserveRecentItems:         12,
		PreserveInitialUserMessages: 2,
		SummaryBulletLimit:          4,
		UseLLMSummary:               true,
	}
}

// CompactionDefaultsForModel returns tuned compaction thresholds based on the
// model's context window. Trigger fires when ~10% of context remains (90% used).
// Target compacts down to ~50% of context window.
//
// This is the STATIC fallback used only when authoritative provider metadata
// (the /models endpoint) is unavailable for the model. It deliberately errs
// toward SMALLER windows for unknown/small variants: over-compaction merely
// wastes a little context, but under-compaction lets a run blow past the real
// limit and hang (see the gpt-5.3-codex-spark freeze). Small fast variants
// (-spark/-nano/-mini/-lite/-flash) are therefore capped conservatively even
// though some of them advertise larger windows; provider metadata overrides
// these when present.
func CompactionDefaultsForModel(model string) (triggerTokens, targetTokens int) {
	_, unprefixed := ParseModelPrefix(model)
	m := strings.ToLower(strings.TrimSpace(unprefixed))
	switch {
	// Small/fast variants (e.g. gpt-5.3-codex-spark, *-nano, *-mini, *-lite,
	// *-flash): assume a ~128K context and compact conservatively. Checked
	// FIRST so e.g. "gpt-5.3-codex-spark" does not fall through to the
	// "gpt-5.3-codex" 1M branch below.
	case strings.Contains(m, "spark"),
		strings.Contains(m, "nano"),
		strings.Contains(m, "mini"),
		strings.Contains(m, "lite"),
		strings.Contains(m, "flash"):
		return 110000, 60000
	// GPT-6 (Astra) on the ChatGPT Codex backend advertises a 272K
	// context_window (872K max_context_window); the OpenAI API exposes ~1M.
	// Trigger at 90% / target 50% of the 272K window; provider metadata or
	// models.dev overrides this conservative static fallback when available.
	case strings.HasPrefix(m, "gpt-6"):
		return 244800, 136000
	// GPT-5.6 on the ChatGPT Codex backend advertises 372K context. The OpenAI
	// API can expose larger windows; provider metadata or models.dev overrides
	// this conservative static fallback when available.
	case strings.HasPrefix(m, "gpt-5.6"):
		return 334800, 186000
	// GPT-5.x / codex (non-spark) on Copilot/OpenAI are ~400K context (not the
	// ~1M once assumed): trigger ~360K (90%), target ~200K (50%). Providers
	// that genuinely expose ~1M are corrected upward by provider metadata.
	case strings.HasPrefix(m, "gpt-5.5"):
		return 360000, 200000
	case strings.HasPrefix(m, "gpt-5.4"):
		return 360000, 200000
	case strings.HasPrefix(m, "gpt-5.3-codex"):
		return 360000, 200000
	case strings.HasPrefix(m, "gpt-5.2-codex"):
		return 360000, 200000
	case strings.HasPrefix(m, "gpt-5.2"), strings.HasPrefix(m, "gpt-5.1"):
		return 360000, 200000
	// Claude Fable 5: 1M context on Copilot and Anthropic (models.dev).
	// Provider /models limits under-report this deployment (claims a 200K
	// prompt cap while 1M-context requests succeed), so the models.dev
	// resolver is authoritative; this static fallback matches it.
	case strings.Contains(m, "fable"):
		return 900000, 500000
	// Claude Opus 4: 200K context → trigger at 180K, target 100K
	case strings.Contains(m, "opus-4"):
		return 180000, 100000
	// Claude Sonnet 4: 200K context → trigger at 180K, target 100K
	case strings.Contains(m, "sonnet-4"):
		return 180000, 100000
	// Claude Haiku: 200K context → trigger at 180K, target 100K
	case strings.Contains(m, "haiku"):
		return 180000, 100000
	default:
		return 180000, 100000
	}
}

func (c CompactionConfig) normalized() CompactionConfig {
	if c.TriggerTokens <= 0 {
		c.TriggerTokens = 180000
	}
	if c.TargetTokens <= 0 {
		c.TargetTokens = maxInt(1, c.TriggerTokens/2)
	}
	if c.TargetTokens >= c.TriggerTokens {
		c.TargetTokens = maxInt(1, c.TriggerTokens/2)
	}
	if c.PreserveRecentItems <= 0 {
		c.PreserveRecentItems = 12
	}
	if c.PreserveInitialUserMessages <= 0 {
		c.PreserveInitialUserMessages = 2
	}
	if c.SummaryBulletLimit <= 0 {
		c.SummaryBulletLimit = 4
	}
	return c
}

// HandoffHistoryConfig controls how much history is forwarded across handoffs.
type HandoffHistoryConfig struct {
	Enabled             bool
	MaxTokens           int
	TargetTokens        int
	PreserveRecentItems int
	SummaryBulletLimit  int
}

func (c HandoffHistoryConfig) normalized() HandoffHistoryConfig {
	if c.MaxTokens <= 0 {
		c.MaxTokens = 6000
	}
	if c.TargetTokens <= 0 {
		c.TargetTokens = c.MaxTokens / 2
	}
	if c.TargetTokens >= c.MaxTokens {
		c.TargetTokens = c.MaxTokens / 2
	}
	if c.PreserveRecentItems <= 0 {
		c.PreserveRecentItems = 8
	}
	if c.SummaryBulletLimit <= 0 {
		c.SummaryBulletLimit = 4
	}
	return c
}

// RunConfig configures a single run of the Runner.
type RunConfig struct {
	// Durable optionally enables fail-closed, versioned checkpoints at model,
	// tool, approval, handoff, child, pause, and completion boundaries. Nil
	// retains the historical in-process execution path with no store required.
	Durable          *DurableRunConfig
	MaxTurns         int           // default 100
	SubAgentMaxTurns int           // default 50 for nested specialist runs
	Hooks            RunHooks      // run-level lifecycle hooks
	ModelSettings    ModelSettings // override agent's model settings
	ModelOverride    string        // override agent's model name
	FallbackModels   []string      // ordered cross-provider fallback models for failed model calls
	// PromptCacheKey is the logical identity grouped into a provider prompt cache.
	// The runner hashes it with PromptCacheNamespace before sending it to a provider.
	PromptCacheKey string
	// PromptCacheNamespace deliberately shares logical prompt cache keys across
	// separate runs. Empty scopes keys to the shared trace ID; callers should set
	// the same non-secret value only when cross-run cache reuse is intended.
	PromptCacheNamespace string
	// ToolOutputDir is the caller-managed parent directory for private, per-run
	// tool-output spill directories. Spills beneath an explicit directory remain
	// available after the run so persisted history can reuse their paths; the
	// caller owns directory cleanup. Empty uses the OS temporary directory and
	// removes spills when the run returns. Spills are disabled for read-only runs.
	ToolOutputDir      string
	toolOutputSpillDir string
	// TracingDisabled suppresses the spans the runner itself emits
	// (generation, function, handoff, trace lifecycle) for this run. It does
	// NOT affect spans emitted by a ProgressTracker wired via
	// SetTracingProcessor (session, subagent, retry, compaction) — the host
	// owns that processor and controls it directly.
	TracingDisabled  bool
	TracingProcessor TracingProcessor // export spans to external systems

	// Trace, if set, is used instead of creating a new trace per Run().
	// This allows multiple Run() calls (e.g. across phases) to share a single
	// OTel trace so all spans appear in one waterfall.
	Trace *Trace

	// ParentSpanID is the span under which runner-created spans (generation,
	// function, handoff) are nested. Typically set to the current phase span ID.
	// Falls back to Trace.ID if empty.
	ParentSpanID string

	ImmediateInputPoller      ImmediateInputPoller
	ImmediateInputSignal      ImmediateInputSignal
	ImmediateInputFinalizer   ImmediateInputFinalizer
	CompactionConfig          CompactionConfig
	CompactionModelResolver   CompactionModelResolver
	CompactionRecorder        func(tokensBefore, tokensAfter int, summary string)
	CompactionFailureReporter func(scope, reason string, tokensBefore, tokensAfter int)
	CompactionCarryForward    func(ctx context.Context) string
	HandoffHistory            HandoffHistoryConfig

	// Tool guardrails — per-tool-call validation (distinct from agent-level guardrails).
	ToolInputGuardrails  []ToolInputGuardrail
	ToolOutputGuardrails []ToolOutputGuardrail

	// WorkDir is the working directory for tool execution (bash cwd, path resolution).
	// Typically set to the cloned repo directory so all tools operate inside the repo.
	WorkDir string

	// ErrorHandler is called when the run encounters an error. If set, the handler
	// decides whether to retry, abort, or continue. If nil, errors abort immediately.
	ErrorHandler RunErrorHandler

	// RetryPolicy optionally retries model-call errors. Provider retry advice
	// and ErrorHandler still run; this policy is an SDK-level fallback.
	RetryPolicy *RetryPolicy

	// AdditionalInstructions are appended to the agent instructions for this run.
	AdditionalInstructions string
	// ModeInstructions is a deprecated alias for AdditionalInstructions.
	// It is retained so operator-era callers keep working.
	ModeInstructions string

	WorkingStateContext string           // durable working-state summary appended to compaction carry-forward
	ToolAccessLevel     ToolAccessLevel  // controls tool access tier (full/read-only)
	ActionAuthorizer    ActionAuthorizer // optional provider-neutral action authorization hook
	// AllowedMutatingTools lists exact tool names that may remain available when
	// ToolAccessLevel is read-only. The tools keep their mutating classification,
	// so approval and execution-serialization policies still apply. This is a
	// host-controlled exception and is not inherited by nested sub-agent runs.
	AllowedMutatingTools   []string
	ToolPolicy             *ToolPolicy // optional approval and timeout policy applied to tools
	MaxConcurrentSubAgents int         // 0 = unlimited
	ForceFinalSummaryTurn  bool        // reserve the final turn for a no-tool summary instead of hard-failing

	// RequireCompletionConfirmation bounces the model's first final answer
	// back with a verification prompt; only a second consecutive final answer
	// ends the run. Any tool call or handoff in between resets the
	// confirmation. Prevents premature completion on long autonomous tasks
	// (Terminus 2 double-confirm pattern).
	RequireCompletionConfirmation bool

	// ConsecutiveToolErrorLimit escalates when this many consecutive tool
	// turns produce only errors: the runner injects a corrective note telling
	// the model to change approach or report the blocker (the 12-factor
	// three-strike rule). 0 uses DefaultConsecutiveToolErrorLimit; negative
	// disables escalation.
	ConsecutiveToolErrorLimit int

	// StopGate is a deterministic finalization gate. When set, it runs on
	// every candidate final answer; returning ok=false blocks finalization
	// and feeds the feedback back to the model. After StopGateMaxBlocks
	// consecutive blocks (default DefaultStopGateMaxBlocks) the gate is
	// bypassed so a broken gate cannot loop forever (Claude Code stop-hook
	// pattern). Consecutive-block tracking resets when the model makes
	// progress with tools.
	StopGate func(ctx context.Context, finalText string) (ok bool, feedback string)
	// StopGateMaxBlocks caps consecutive StopGate blocks. 0 = default.
	StopGateMaxBlocks int

	// FinalAnswerVerifier, when set, reviews the candidate final answer once
	// per run (after StopGate passes). Non-empty feedback is injected and the
	// run continues instead of finalizing — typically wired to a read-only
	// critic sub-agent that tries to refute the result (adversarial
	// verification). Errors from the verifier are logged and ignored.
	FinalAnswerVerifier func(ctx context.Context, finalText string) (feedback string, err error)

	// MaxToolOutputBytes caps the tool result content fed back to the model as
	// next-turn input. Oversized outputs are middle-truncated (head and tail
	// preserved) so conclusions survive. Hooks, traces, and the event stream
	// still receive the raw output. 0 uses DefaultMaxToolOutputBytes; negative
	// disables the cap.
	MaxToolOutputBytes int

	// Debug enables verbose logging (full instructions, tool I/O, conversation items).
	Debug bool

	// UntrustedToolOutputs controls whether tool result content is wrapped with
	// "BEGIN UNTRUSTED TOOL OUTPUT … END UNTRUSTED TOOL OUTPUT" delimiters before
	// it becomes part of the next model turn's input. This mitigates prompt-
	// injection attacks where tool output (e.g. a fetched web page) attempts to
	// override the agent's instructions in subsequent turns.
	//
	// Semantics: nil (zero value) defaults to true (wrap) — secure by default.
	// Set to a pointer to false to opt out (e.g. for trusted in-process tools
	// where wrapping would interfere with downstream formatting). See
	// docs/security.md.
	UntrustedToolOutputs *bool

	// ModelCallTimeout is the maximum inactivity interval for a model response
	// stream. Every provider stream event resets the timer, so healthy generations
	// may run longer than this duration. Initial request stalls and silent streams
	// are cancelled and flow through the normal retry/fallback policy. Provider
	// operations without observable progress, including native compaction, retain
	// this value as a hard deadline. 0 uses DefaultModelCallTimeout; negative
	// disables both safeguards.
	ModelCallTimeout time.Duration
}

// ShouldTagUntrustedToolOutputs reports whether tool outputs should be tagged
// as untrusted before being fed back to the model. Defaults to true.
func (c *RunConfig) ShouldTagUntrustedToolOutputs() bool {
	if c.UntrustedToolOutputs == nil {
		return true
	}
	return *c.UntrustedToolOutputs
}

// ToolPolicy holds host-supplied approval and timeout settings.
type ToolPolicy struct {
	// ApprovalRequired indicates non-read-only tools need approval.
	ApprovalRequired bool
	// DefaultTimeout in seconds for all tool calls (0 = no timeout).
	DefaultTimeout int
}

// DefaultMaxTurns is used when RunConfig.MaxTurns is 0.
const DefaultMaxTurns = 100

// DefaultSubAgentMaxTurns is used when RunConfig.SubAgentMaxTurns is 0.
const DefaultSubAgentMaxTurns = 50

// DefaultMaxToolOutputBytes caps model-facing tool output when
// RunConfig.MaxToolOutputBytes is 0. 16 KB bounds the context cost of a
// single pathological tool call while preserving enough head and tail output
// for the model to diagnose failures.
const DefaultMaxToolOutputBytes = 16 * 1024

// DefaultConsecutiveToolErrorLimit is the consecutive all-error tool-turn
// threshold that triggers a corrective escalation note.
const DefaultConsecutiveToolErrorLimit = 3

// DefaultStopGateMaxBlocks caps consecutive StopGate blocks before the gate
// is bypassed.
const DefaultStopGateMaxBlocks = 8

// EffectiveConsecutiveToolErrorLimit returns the escalation threshold, or 0
// when escalation is disabled.
func (c *RunConfig) EffectiveConsecutiveToolErrorLimit() int {
	if c.ConsecutiveToolErrorLimit < 0 {
		return 0
	}
	if c.ConsecutiveToolErrorLimit == 0 {
		return DefaultConsecutiveToolErrorLimit
	}
	return c.ConsecutiveToolErrorLimit
}

// EffectiveStopGateMaxBlocks returns the consecutive-block cap for StopGate.
func (c *RunConfig) EffectiveStopGateMaxBlocks() int {
	if c.StopGateMaxBlocks > 0 {
		return c.StopGateMaxBlocks
	}
	return DefaultStopGateMaxBlocks
}

// EffectiveMaxTurns returns MaxTurns or DefaultMaxTurns if unset.
func (c *RunConfig) EffectiveMaxTurns() int {
	if c.MaxTurns > 0 {
		return c.MaxTurns
	}
	return DefaultMaxTurns
}

// EffectiveMaxToolOutputBytes returns the model-facing tool output cap.
// Returns 0 when the cap is disabled (negative configuration).
func (c *RunConfig) EffectiveMaxToolOutputBytes() int {
	if c.MaxToolOutputBytes < 0 {
		return 0
	}
	if c.MaxToolOutputBytes == 0 {
		return DefaultMaxToolOutputBytes
	}
	return c.MaxToolOutputBytes
}

// EffectiveSubAgentMaxTurns returns SubAgentMaxTurns or DefaultSubAgentMaxTurns if unset.
func (c *RunConfig) EffectiveSubAgentMaxTurns() int {
	if c.SubAgentMaxTurns > 0 {
		return c.SubAgentMaxTurns
	}
	return DefaultSubAgentMaxTurns
}

// IsReadOnly returns true if the tool access level restricts to read-only tools.
func (c *RunConfig) IsReadOnly() bool {
	return NormalizeToolAccessLevel(c.ToolAccessLevel) == ToolAccessLevelReadOnly
}

package agent

import "testing"

func TestCompactionDefaultsForModel(t *testing.T) {
	tests := []struct {
		model       string
		wantTrigger int
		wantTarget  int
	}{
		{"gpt-6-astra", 244800, 136000},
		{"openai/gpt-6-astra", 244800, 136000},
		{"gpt-5.6", 334800, 186000},
		{"gpt-5.6-sol", 334800, 186000},
		{"openai/gpt-5.6-terra", 334800, 186000},
		{"gpt-5.6-luna", 334800, 186000},
		{"gpt-5.5", 360000, 200000},
		{"openai/gpt-5.5", 360000, 200000},
		{"gpt-5.4", 360000, 200000},
		{"openai/gpt-5.4", 360000, 200000},
		// Small/fast variants are capped conservatively (~128K-class) so the
		// static fallback never lets a smaller model blow past its real context
		// window — the gpt-5.3-codex-spark freeze. Provider /models metadata
		// overrides these when available.
		{"gpt-5.4-mini", 110000, 60000},
		{"openai/gpt-5.4-mini", 110000, 60000},
		{"gpt-5.4-nano", 110000, 60000},
		{"gpt-5.3-codex", 360000, 200000},
		{"gpt-5.3-codex-spark", 110000, 60000},
		{"gpt-5.2-codex", 360000, 200000},
		{"gpt-5.2", 360000, 200000},
		{"gpt-5.1", 360000, 200000},
		{"claude-opus-4-6", 180000, 100000},
		{"anthropic/claude-opus-4-6", 180000, 100000},
		{"claude-sonnet-4-6", 180000, 100000},
		{"claude-haiku-4-5", 180000, 100000},
		{"unknown-model", 180000, 100000},
		{"", 180000, 100000},
	}
	for _, tt := range tests {
		t.Run(tt.model, func(t *testing.T) {
			trigger, target := CompactionDefaultsForModel(tt.model)
			if trigger != tt.wantTrigger || target != tt.wantTarget {
				t.Errorf("CompactionDefaultsForModel(%q) = (%d, %d), want (%d, %d)",
					tt.model, trigger, target, tt.wantTrigger, tt.wantTarget)
			}
		})
	}
}

