const compactionCarryForwardPrefix = "[COMPACTION CARRY-FORWARD]"

// completionConfirmationPrompt bounces the first final answer back to the
// model when RunConfig.RequireCompletionConfirmation is set. Terminus 2 uses
// the same double-confirm pattern to prevent premature task completion.
const completionConfirmationPrompt = `[SYSTEM] Before this answer is accepted as final: verify your work now.
- Re-read the original task and confirm every requirement is satisfied.
- If there are runnable checks (tests, builds, linters, the command the task asks about), run them and confirm they pass.
- Confirm any files or artifacts the task requires actually exist with the expected content.
If anything is unverified or incomplete, continue working instead of finalizing.
If you are certain the task is complete, provide your final answer again.`

// untrustedToolOutputBegin/End delimit tool result content fed back to the
// model on subsequent turns. See RunConfig.UntrustedToolOutputs and
// docs/security.md.
const (
	untrustedToolOutputBegin = "BEGIN UNTRUSTED TOOL OUTPUT"
	untrustedToolOutputEnd   = "END UNTRUSTED TOOL OUTPUT"
)

// maxRetryAfterMS caps any caller- or provider-supplied retry delay so a
// single misbehaving advice value can't stall the run for hours. See finding M1.
const maxRetryAfterMS = int64(5 * 60 * 1000) // 5 minutes

// fallbackPrimaryReprobeTurns is the number of successful model calls on an
// active fallback model after which the runner retries the primary model, so
// a transient failure (rate limit, quota blip) does not permanently downgrade
// a long run. A still-failing primary costs one failed attempt before the
// fallback re-engages.
const fallbackPrimaryReprobeTurns = 3

// capRetryAfterMS returns the retry delay clamped to maxRetryAfterMS. It logs
// when capping is applied so operators can detect runaway advice values.
func capRetryAfterMS(requestedMS int64) int64 {
	if requestedMS <= maxRetryAfterMS {
		return requestedMS
	}
	log.Printf("[runner] capping retry_after_ms %d → %d (5m max)", requestedMS, maxRetryAfterMS)
	return maxRetryAfterMS
}

// wrapToolOutputContent applies the untrusted-tool-output delimiters around
// raw tool result content. Idempotent: already-wrapped content is returned
// unchanged so repeated next-turn appends don't double-wrap.
func wrapToolOutputContent(content string) string {
	if strings.Contains(content, untrustedToolOutputBegin) {
		return content
	}
	return untrustedToolOutputBegin + "\n" + content + "\n" + untrustedToolOutputEnd
}

// wrapToolOutputsForInput returns a copy of items with RunItemToolOutput
// content wrapped in untrusted-output delimiters. Used when splicing tool
// results into the next turn's input. Non-tool-output items pass through.
func wrapToolOutputsForInput(items []RunItem) []RunItem {
	out := make([]RunItem, len(items))
	for i, item := range items {
		out[i] = item
		if item.Type == RunItemToolOutput && item.ToolOutput != nil {
			cloned := *item.ToolOutput
			cloned.Content = wrapToolOutputContent(cloned.Content)
			out[i].ToolOutput = &cloned
		}
	}
	return out
}

// isSubAgentTool reports whether tool t is a wrapped Agent acting as a tool.
// Used by the runner's concurrency semaphore so its decision is based on type
// rather than name prefix (finding M2).
func isSubAgentTool(t Tool) bool {
	for {
		switch v := t.(type) {
		case *agentTool:
			return true
		case *policyToolWrapper:
			t = v.inner
			continue
		default:
			return false
		}
	}
}

// unwrapPolicyTool strips policy wrappers so type-based capability probes
// (the sub-agent join/poll interfaces below) see the inner tool. Without
// this, a ToolPolicy timeout would silently disable the sub-agent final-join
// safety net, mirroring the isSubAgentTool unwrap above.
func unwrapPolicyTool(t Tool) Tool {
	for {
		w, ok := t.(*policyToolWrapper)
		if !ok {
			return t
		}
		t = w.inner
	}
}

// controlFlowToolNames is the explicit allowlist of control-flow tool names
// (finding M3). These tools manage run lifecycle / user interaction and are
// always allowed regardless of tool access level.
var controlFlowToolNames = map[string]struct{}{
	"finish":               {},
	"AskUserQuestion":      {},
	"present_plan":         {},
	"save_plan":            {},
	"get_plan":             {},
	"RequestMCPBreakGlass": {},
	"subagent":             {},
	"subagent_status":      {},
	"subagent_wait":        {},
	"subagent_control":     {},
}

type subAgentFinalJoinProvider interface {
	JoinSubAgentResults(context.Context) ([]RunItem, error)
}

type subAgentFinalJoinStateProvider interface {
	HasPendingSubAgentFinalJoin() bool
}

// subAgentResultPoller exposes a non-blocking drain of terminal, undelivered
// managed sub-agent results. The runner polls it at every turn boundary so the
// parent can incorporate early results while slower siblings keep running,
// instead of receiving everything in one batch at final-join.
type subAgentResultPoller interface {
	PollSubAgentResults() []RunItem
}

// subAgentSchedulerCheckpointer is implemented by the managed sub-agent tool
// so the runner can persist and restore child task records alongside the
// parent's durable checkpoint without the host wiring the scheduler by hand.
type subAgentSchedulerCheckpointer interface {
	SubAgentSchedulerCheckpoint() SubAgentSchedulerCheckpoint
	RestoreSubAgentSchedulerCheckpoint(SubAgentSchedulerCheckpoint) error
	HasSubAgentTasks() bool
}

func findSubAgentSchedulerCheckpointer(tools []Tool) subAgentSchedulerCheckpointer {
	for _, tool := range tools {
		if cp, ok := tool.(subAgentSchedulerCheckpointer); ok {
			return cp
		}
	}
	return nil
}

// wireDurableChildren connects a durable run to the attached sub-agent
// scheduler: child records ride along in every parent checkpoint, and a
// resumed checkpoint that carries child records restores them into an empty
// scheduler. Hosts that already restored the scheduler themselves (non-empty
// registry) or provided their own Children callback are left untouched.
func wireDurableChildren(cfg *DurableRunConfig, tools []Tool) error {
	if cfg == nil {
		return nil
	}
	checkpointer := findSubAgentSchedulerCheckpointer(tools)
	if checkpointer != nil && cfg.Children == nil {
		cfg.Children = checkpointer.SubAgentSchedulerCheckpoint
	}
	resume := cfg.Resume
	if resume == nil || resume.Children == nil || len(resume.Children.Records) == 0 {
		return nil
	}
	if checkpointer == nil {
		// Terminal records carry nothing that can still act; dropping them
		// loses only re-readable results. Active records represent in-flight
		// work with possibly unresolved external effects and must never be
		// discarded silently.
		active := 0
		for _, record := range resume.Children.Records {
			if !record.Task.IsTerminal() {
				active++
			}
		}
		if active > 0 {
			return fmt.Errorf("restore durable checkpoint: %d active child task record(s) but no sub-agent scheduler tool is attached", active)
		}
		return nil
	}
	if checkpointer.HasSubAgentTasks() {
		return nil
	}
	if err := checkpointer.RestoreSubAgentSchedulerCheckpoint(*resume.Children); err != nil {
		return fmt.Errorf("restore durable checkpoint: children: %w", err)
	}
	return nil
}

// checkDuplicateToolNames returns an error if any two tools share a name
// (finding M4). Duplicate registrations cause non-deterministic dispatch and
// can be exploited to shadow safe tools with malicious ones.
func checkDuplicateToolNames(tools []Tool) error {
	seen := make(map[string]struct{}, len(tools))
	for _, t := range tools {
		if t == nil {
			continue
		}
		name := t.Name()
		if _, dup := seen[name]; dup {
			return &AgentError{Message: fmt.Sprintf("duplicate tool registration: %q", name)}
		}
		seen[name] = struct{}{}
	}
	return nil
}

// Runner executes agents. It holds the Model implementation and orchestrates the run loop.
type Runner struct {
	model    Model
	provider ModelProvider // optional; when set, resolves model per-call
	// DefaultHooks are applied to sub-agent runs that don't specify their own hooks.
	// This ensures nested agent tool calls (e.g. agent_explore → Grep) appear in the
	// activity log alongside the parent's events.
	DefaultHooks RunHooks
}

// NewRunner creates a Runner for the given provider ("anthropic" or "openai").
func NewRunner(provider string) (*Runner, error) {
	return nil, fmt.Errorf("default provider %q is not wired in agent core; use NewRunnerWithProvider or sdk providers.NewRunner", provider)
}

// NewRunnerWithProvider creates a Runner backed by the given ModelProvider.
// The provider resolves model names to Model implementations on each call.
func NewRunnerWithProvider(provider ModelProvider) *Runner {
	return &Runner{provider: provider}
}

// NewRunnerWithModel creates a Runner with an existing Model implementation.
func NewRunnerWithModel(model Model) *Runner {
	return &Runner{model: model}
}

// CalculateCost returns the USD cost estimate for the given usage.
// Safe to call regardless of how the runner was constructed.
func (r *Runner) CalculateCost(usage Usage) float64 {
	if r.model != nil {
		return r.model.CalculateCost(usage)
	}
	return 0
}

// Run executes an agent with the given input and returns the result.
// It runs the agent loop: LLM call → process response → tools/handoff/final → repeat.
//
// Partial results: when the run ends early with the conversation still
// intact — the turn budget runs out (MaxTurnsExceeded), the context is
// cancelled mid-run (host pause/shutdown, run deadline), or the turn fails
// after at least one completed turn (model/API error past retries and
// fallbacks, guardrail trip) — Run returns the accumulated run state
// alongside the non-nil error (io.Reader-style partial-result semantics).
// FinalHistory on that partial result is the replay-safe post-fold
// transcript of every completed turn, so hosts can persist it and continue
// the session in a follow-up run instead of losing the accumulated context.
func (r *Runner) Run(ctx context.Context, agent *Agent, input []RunItem, cfg RunConfig) (*RunResult, error) {
	if r == nil {
		return nil, fmt.Errorf("runner is nil")
	}
	if agent == nil {
		return nil, fmt.Errorf("agent is nil")
	}
	return r.run(ctx, agent, input, cfg, nil)
}

// ExecuteApprovedTool resumes a previously interrupted approval request using
// the same runner preparation path as ordinary tool execution. The tool has
// already been approved by the host, so this method executes the matching tool
// directly while still applying access adapters, IsEnabled filtering, policy
// timeouts, hooks, tracing, and tool input/output guardrails.
//
// Tracing: pass the originating run's cfg.Trace (and ParentSpanID) so the
// approved tool's span joins that run's waterfall; when cfg.Trace is nil a
// fresh single-call trace is created for this execution.
func (r *Runner) ExecuteApprovedTool(ctx context.Context, agent *Agent, call ToolCallData, cfg RunConfig) (RunItem, []ToolGuardrailResult, []ToolGuardrailResult, bool, error) {
	if r == nil {
		return RunItem{}, nil, nil, false, fmt.Errorf("runner is nil")
	}
	if agent == nil {
		return RunItem{}, nil, nil, false, fmt.Errorf("agent is nil")
	}
	cfg.ToolAccessLevel = NormalizeToolAccessLevel(cfg.ToolAccessLevel)
	cleanupToolOutput := prepareToolOutputSpill(&cfg)
	defer cleanupToolOutput()

	runCtx := newRunContext(ctx, cfg)
	runCtx.ToolAccessLevel = cfg.ToolAccessLevel

	tp := cfg.TracingProcessor
	if tp == nil || cfg.TracingDisabled {
		tp = NoOpTracingProcessor{}
	}
	trace := cfg.Trace
	ownTrace := trace == nil
	if ownTrace {
		trace = NewTrace(agent.Name)
		tp.OnTraceStart(trace)
		defer func() {
			trace.Finish()
			tp.OnTraceEnd(trace)
		}()
	}
	spanParent := cfg.ParentSpanID
	if spanParent == "" {
		spanParent = trace.ID
	}
	runCtx.TracingProcessor = tp
	runCtx.Trace = trace
	runCtx.SpanParentID = spanParent

	tools := prepareToolsForRun(agent.GetAllTools(runCtx), cfg, runCtx)
	var tool Tool
	for _, candidate := range tools {
		if candidate.Name() == call.Name {
			tool = candidate
			break
		}
	}
	if tool == nil {
		return RunItem{
			Type: RunItemToolOutput, Agent: agent,
			ToolOutput: &ToolOutputData{CallID: call.ID, Content: fmt.Sprintf("tool %q is no longer available", call.Name), IsError: true},
		}, nil, nil, false, nil
	}

	var durableSequence uint64
	var durableHistory []RunItem
	if cfg.Durable != nil {
		cfg.Durable.normalize()
		if cfg.Durable.Resume != nil {
			durableSequence = cfg.Durable.Resume.Sequence
			var restoreErr error
			durableHistory, restoreErr = RestoreRunItems(cfg.Durable.Resume.History, func(name string) *Agent {
				if name == agent.Name {
					return agent
				}
				return nil
			})
			if restoreErr != nil {
				return RunItem{}, nil, nil, false, fmt.Errorf("restore approval checkpoint: %w", restoreErr)
			}
		}
		durableHistory = append(durableHistory, RunItem{Type: RunItemToolApproval, Agent: agent, ToolApproval: &ToolApprovalData{ToolName: call.Name, Input: cloneRaw(call.Input), CallID: call.ID, Approved: true}})
		if err := emitDurableCheckpoint(ctx, cfg.Durable, &durableSequence, DurableBoundaryToolPrepared, agent, durableHistory, nil, runCtx.Usage); err != nil {
			return RunItem{}, nil, nil, false, fmt.Errorf("persist approved tool preparation: %w", err)
		}
	}
	result := r.executeSingleTool(ctx, runCtx, agent, tool, call, cfg)
	if result.guardrailErr == nil && cfg.Durable != nil {
		durableHistory = append(durableHistory, result.item)
		if err := emitDurableCheckpoint(ctx, cfg.Durable, &durableSequence, DurableBoundaryToolCompleted, agent, durableHistory, nil, runCtx.Usage); err != nil {
			return RunItem{}, result.inputGuardrails, result.outputGuardrails, result.shouldPause, fmt.Errorf("persist approved tool completion: %w", err)
		}
	}
	return result.item, result.inputGuardrails, result.outputGuardrails, result.shouldPause, result.guardrailErr
}

func (r *Runner) run(ctx context.Context, agent *Agent, input []RunItem, cfg RunConfig, streamEvents chan<- StreamEvent) (result *RunResult, err error) {
	if r == nil {
		return nil, fmt.Errorf("runner is nil")
	}
	if agent == nil {
		return nil, fmt.Errorf("agent is nil")
	}
	cfg.ToolAccessLevel = NormalizeToolAccessLevel(cfg.ToolAccessLevel)
	runCtx := newRunContext(ctx, cfg)
	runCtx.ToolAccessLevel = cfg.ToolAccessLevel
	currentAgent := agent
	currentInput := make([]RunItem, len(input))

	if dupErr := checkDuplicateToolNames(currentAgent.GetAllTools(runCtx)); dupErr != nil {
		return nil, dupErr
	}

	// Initialize tracing.
	tp := cfg.TracingProcessor
	if tp == nil || cfg.TracingDisabled {
		tp = NoOpTracingProcessor{}
	}
	// Use a shared trace if the caller provided one (multi-phase runs share a
	// single OTel trace). Otherwise create a per-Run trace.
	trace := cfg.Trace
	ownTrace := trace == nil
	if ownTrace {
		trace = NewTrace(currentAgent.Name)
		tp.OnTraceStart(trace)
	}
	// Resolve parent span for runner-created spans: explicit > trace root.
	spanParent := cfg.ParentSpanID
	if spanParent == "" {
		spanParent = trace.ID
	}
	runCtx.TracingProcessor = tp
	runCtx.Trace = trace
	runCtx.SpanParentID = spanParent
	logicalCacheKey := strings.TrimSpace(cfg.PromptCacheKey)
	if logicalCacheKey == "" {
		logicalCacheKey = TaskIDFromContext(ctx)
		if logicalCacheKey == "" {
			logicalCacheKey = "run"
		}
	}
	cacheNamespace := strings.TrimSpace(cfg.PromptCacheNamespace)
	if cacheNamespace == "" {
		cacheNamespace = trace.ID
	}
	cfg.PromptCacheKey = promptCacheWireKey(cacheNamespace, logicalCacheKey)
	cleanupToolOutput := prepareToolOutputSpill(&cfg)
	defer cleanupToolOutput()
	defer func() {
		if ownTrace {
			trace.Finish()
			tp.OnTraceEnd(trace)
		}
	}()
	// Panic-safety net: a panic between a span's start and its normal end
	// (model call, hooks, guardrails) must not leak a started-but-never-ended
	// span — un-ended spans are never exported and leak processor state. This
	// runs before the trace-end defer above (LIFO).
	var openGenSpan, openHandoffSpan *Span
	defer func() {
		for _, s := range []*Span{openGenSpan, openHandoffSpan} {
			if s != nil {
				if s.EndTime.IsZero() {
					s.Finish()
				}
				tp.OnSpanEnd(s)
			}
		}
	}()

	// Initialize logger.
	logLevel := LogLevelNormal
	if cfg.Debug {
		logLevel = LogLevelDebug
	}
	al := NewAgentLogger(logLevel)

	copy(currentInput, input)
	var durableSequence uint64
	if cfg.Durable != nil {
		cfg.Durable.normalize()
		if err := wireDurableChildren(cfg.Durable, agent.GetAllTools(runCtx)); err != nil {
			return nil, err
		}
		if resume := cfg.Durable.Resume; resume != nil {
			if resume.SchemaVersion != DurableCheckpointSchemaVersion {
				return nil, fmt.Errorf("unsupported durable checkpoint schema %d", resume.SchemaVersion)
			}
			runCtx.Usage = resume.Usage
			restored, restoreErr := RestoreRunItems(resume.History, func(name string) *Agent { return findRunAgent(agent, name) })
			if restoreErr != nil {
				return nil, fmt.Errorf("restore durable checkpoint: %w", restoreErr)
			}
			currentInput = restored
			durableSequence = resume.Sequence
			if resumedAgent := findRunAgent(agent, resume.AgentName); resumedAgent != nil {
				currentAgent = resumedAgent
			} else if resume.AgentName != "" {
				return nil, fmt.Errorf("restore durable checkpoint: agent %q is not registered", resume.AgentName)
			}
			if resume.Boundary == DurableBoundaryRunCompleted {
				return &RunResult{
					FinalOutput:  Items.ExtractLastText(restored),
					LastAgent:    currentAgent,
					Usage:        resume.Usage,
					FinalHistory: append([]RunItem(nil), restored...),
				}, nil
			}
			// A model-completed or approval-pending snapshot can contain an
			// unresolved external effect. It is inspectable and reconcilable, but
			// must never be blindly replayed as a fresh model request.
			if resume.Boundary == DurableBoundaryModelCompleted || resume.Boundary == DurableBoundaryApprovalPending || resume.Boundary == DurableBoundaryToolPrepared {
				return nil, fmt.Errorf("durable checkpoint at %s requires effect reconciliation before resume", resume.Boundary)
			}
		}
	}

	var allItems []RunItem
	var allResponses []ModelResponse
	var llmAttempt int32
	// turnRetryAttempt counts consecutive failed model calls since the last
	// successful response. RetryPolicy budgets retries per failing call site,
	// so the counter resets on success; using the cumulative llmAttempt here
	// would exhaust the retry budget after MaxRetries successful turns.
	var turnRetryAttempt int
	activeFallbackModels := map[*Agent]string{}
	// fallbackSuccessTurns counts successful model calls while a fallback is
	// active; after fallbackPrimaryReprobeTurns the fallback is cleared so the
	// next turn re-probes the primary model instead of staying downgraded for
	// the rest of the run after a transient blip.
	fallbackSuccessTurns := map[*Agent]int{}
	var allToolInputResults []ToolGuardrailResult
	var allToolOutputResults []ToolGuardrailResult
	var allActionAuditRecords []ActionAuditRecord
	// pendingCompletion implements double-confirm completion: the first final
	// answer triggers a verification turn, only a second consecutive final
	// answer ends the run (Terminus 2 anti-premature-exit pattern).
	pendingCompletion := false
	// consecutiveToolErrorTurns counts tool turns where every executed tool
	// returned an error; escalation fires at the configured limit.
	consecutiveToolErrorTurns := 0
	toolErrorEscalated := false
	// estimateCalibration corrects the token estimator against the actual
	// input tokens reported by provider usage (provider-normalized, see
	// usageContextTokens). Undercounting (~25% on Claude histories) delays
	// compaction past the real context limit; overcounting (encrypted
	// reasoning/compaction blobs estimated as text) fires it at a fraction
	// of the window. Dividing thresholds by this ratio makes the trigger
	// fire at true window pressure in both directions.
	estimateCalibration := 1.0
	// stopGateBlocks counts consecutive StopGate blocks; the gate is bypassed
	// once the cap is hit so a broken gate cannot loop forever.
	stopGateBlocks := 0
	verifierRan := false

	maxTurns := cfg.EffectiveMaxTurns()

	// finalizeImmediateInput atomically closes input admission, or folds any
	// steering accepted before that point into history and asks the caller to
	// continue instead of returning a terminal result.
	finalizeImmediateInput := func() (bool, error) {
		if cfg.ImmediateInputFinalizer == nil {
			return false, nil
		}
		items, err := cfg.ImmediateInputFinalizer(ctx)
		if err != nil {
			return false, err
		}
		if len(items) == 0 {
			return false, nil
		}
		currentInput = append(currentInput, items...)
		allItems = append(allItems, items...)
		emitRunItems(ctx, streamEvents, items)
		pendingCompletion = false
		return true, nil
	}

	var inputGuardrailResults []InputGuardrailResult
	if len(currentAgent.InputGuardrails) > 0 {
		var err error
		inputGuardrailResults, err = runInputGuardrails(runCtx, currentAgent, currentInput)
		if err != nil {
			return nil, err
		}
	}
	if err := emitDurableCheckpoint(ctx, cfg.Durable, &durableSequence, DurableBoundaryRunStarted, currentAgent, currentInput, nil, runCtx.Usage); err != nil {
		return nil, fmt.Errorf("persist run-start checkpoint: %w", err)
	}

	// A run that ends early with the conversation still intact — context
	// cancellation (host shutdown: pod deletion on pause/wake, SIGTERM, run
	// deadline), a model/API failure after retries and fallbacks, or a
	// guardrail trip — must not discard the conversation accumulated so far:
	// the exact failure the max-turns branch below already guards against.
	// The turn loop surfaces these errors from many return sites (top-of-loop
	// check, model call, retry waits, sub-agent joins), so a single deferred
	// hook hands the accumulated run state back alongside the error for all
	// of them: hosts can persist the transcript and continue the session in a
	// follow-up run instead of losing it. currentInput is the post-fold
	// history of every completed turn — replay-safe, no unpaired tool_use.
	// Errors raised before anything accumulated keep the nil result.
	defer func() {
		if err == nil {
			return
		}
		if ctx.Err() != nil {
			checkpointCtx, checkpointCancel := context.WithTimeout(context.WithoutCancel(ctx), 5*time.Second)
			if checkpointErr := emitDurableCheckpoint(checkpointCtx, cfg.Durable, &durableSequence, DurableBoundaryRunCancelled, currentAgent, currentInput, nil, runCtx.Usage); checkpointErr != nil {
				err = fmt.Errorf("%w (persist cancellation checkpoint: %v)", err, checkpointErr)
			}
			checkpointCancel()
		}
		if result != nil {
			return
		}
		if ctx.Err() == nil && len(allItems) == 0 {
			return
		}
		result = &RunResult{
			LastAgent:                  currentAgent,
			NewItems:                   allItems,
			RawResponses:               allResponses,
			InputGuardrailResults:      inputGuardrailResults,
			ToolInputGuardrailResults:  allToolInputResults,
			ToolOutputGuardrailResults: allToolOutputResults,
			ActionAuditRecords:         append([]ActionAuditRecord(nil), allActionAuditRecords...),
			Usage:                      runCtx.Usage,
			FinalHistory:               append([]RunItem(nil), currentInput...),
		}
	}()

	for turn := 0; ; turn++ {
		if turn >= maxTurns {
			tools := prepareToolsForRun(currentAgent.GetAllTools(runCtx), cfg, runCtx)
			if hasPendingSubAgentFinalJoin(tools) {
				joinItems, joinErr := collectSubAgentFinalJoinItems(ctx, tools)
				if joinErr != nil {
					return nil, joinErr
				}
				if len(joinItems) > 0 {
					currentInput = append(currentInput, joinItems...)
					allItems = append(allItems, joinItems...)
					emitRunItems(ctx, streamEvents, joinItems)
					maxTurns = turn + 2
					continue
				}
			}
			if continued, finalizeErr := finalizeImmediateInput(); finalizeErr != nil {
				return nil, finalizeErr
			} else if continued {
				maxTurns = turn + 1
				// The finalizer already drained the queue; skip the normal poll below.
			} else {
				// The budget is exhausted, but the conversation must not be
				// lost with it: hand the accumulated run state back alongside
				// the error (both as the result and on the error itself) so
				// hosts can persist the transcript and continue in a follow-up
				// run. currentInput is the post-fold history of every completed
				// turn — replay-safe, no unpaired tool_use.
				partial := &RunResult{
					LastAgent:                  currentAgent,
					NewItems:                   allItems,
					RawResponses:               allResponses,
					InputGuardrailResults:      inputGuardrailResults,
					ToolInputGuardrailResults:  allToolInputResults,
					ToolOutputGuardrailResults: allToolOutputResults,
					ActionAuditRecords:         append([]ActionAuditRecord(nil), allActionAuditRecords...),
					Usage:                      runCtx.Usage,
					FinalHistory:               append([]RunItem(nil), currentInput...),
				}
				return partial, &MaxTurnsExceeded{MaxTurns: maxTurns, PartialResult: partial}
			}
		}

		select {
		case <-ctx.Done():
			return nil, ctx.Err()
		default:
		}

		if cfg.ImmediateInputPoller != nil {
			immediateItems, err := cfg.ImmediateInputPoller(ctx)
			if err != nil {
				log.Printf("[runner] WARN: immediate input poll failed: %v", err)
			} else if len(immediateItems) > 0 {
				currentInput = append(currentInput, immediateItems...)
				allItems = append(allItems, immediateItems...)
				emitRunItems(ctx, streamEvents, immediateItems)
				// Steering interrupts a completion-confirmation bounce the
				// same way finalizeImmediateInput does.
				pendingCompletion = false
			}
		}

		// Build model request.
		instructions := buildRunInstructions(currentAgent.GetInstructions(runCtx), currentAgent, cfg)
		tools := prepareToolsForRun(currentAgent.GetAllTools(runCtx), cfg, runCtx)
		if dupErr := checkDuplicateToolNames(tools); dupErr != nil {
			return nil, dupErr
		}
		// Incremental delivery: inject terminal managed sub-agent results as
		// soon as they are available so the parent can act on fast tasks while
		// slower siblings keep running, instead of receiving everything at
		// final-join.
		if pollItems := pollSubAgentResultItems(tools); len(pollItems) > 0 {
			currentInput = append(currentInput, pollItems...)
			allItems = append(allItems, pollItems...)
			emitRunItems(ctx, streamEvents, pollItems)
		}
		pendingSubAgentJoin := hasPendingSubAgentFinalJoin(tools)
		if cfg.ForceFinalSummaryTurn && turn == maxTurns-1 && !pendingSubAgentJoin {
			instructions = instructions + "\n\n" + finalSummaryTurnDirective
			tools = nil
		}
		settings := currentAgent.ModelSettings.Merge(cfg.ModelSettings)

		// Resolve model name.
		primaryModelName := currentAgent.Model
		if cfg.ModelOverride != "" {
			primaryModelName = cfg.ModelOverride
		}
		requestedModelName := primaryModelName
		if fallbackModel := strings.TrimSpace(activeFallbackModels[currentAgent]); fallbackModel != "" {
			requestedModelName = fallbackModel
		}
		modelName := requestedModelName

		// Resolve model via provider if available (per-call resolution).
		activeModel := r.model
		if r.provider != nil {
			resolved, resolveErr := r.provider.GetModel(requestedModelName)
			if resolveErr != nil {
				return nil, &AgentError{Message: fmt.Sprintf("resolve model %q", requestedModelName), Cause: resolveErr}
			}
			activeModel = resolved
			// Strip the provider routing prefix (e.g. "openai/gpt-5.4" →
			// "gpt-5.4") so the bare model name is sent in API requests.
			// Model IDs that legitimately contain "/" (e.g. OpenRouter's
			// "anthropic/claude-...") are preserved.
			modelName = resolveRequestModelName(r.provider, activeModel, requestedModelName)
		}
		if activeModel == nil {
			return nil, &AgentError{Message: "no model configured: set agent.Model, cfg.ModelOverride, or use NewRunnerWithProvider"}
		}

		// Resolve compaction thresholds for the model actually being used this
		// turn. Sub-agents (and active fallback models) run different models
		// than the parent, so a fixed parent-derived threshold would either
		// over-compact or — far worse — never fire before a smaller model's
		// real context limit, letting the run blow past it and hang (the
		// gpt-5.3-codex-spark freeze). The resolver consults authoritative
		// provider metadata with a static fallback and is cached, so calling it
		// each turn is cheap.
		compactionCfg := cfg.CompactionConfig
		if cfg.CompactionModelResolver != nil && compactionCfg.Enabled {
			if trigger, target, ok := cfg.CompactionModelResolver(ctx, requestedModelName); ok && trigger > 0 {
				compactionCfg.TriggerTokens = trigger
				compactionCfg.TargetTokens = target
			}
		}
		// providerCompactionCfg keeps the UNCALIBRATED thresholds for the
		// provider-facing context_management compact_threshold: the provider
		// compares that value against REAL token counts, so dividing it by the
		// local estimator calibration (below) would tell the provider to
		// auto-compact far below the model's actual window (up to 2.5x early),
		// causing chronic server-side over-compaction.
		providerCompactionCfg := compactionCfg
		if compactionCfg.Enabled && estimateCalibration != 1.0 {
			normalized := compactionCfg.normalized()
			compactionCfg.TriggerTokens = maxInt(1, int(float64(normalized.TriggerTokens)/estimateCalibration))
			compactionCfg.TargetTokens = maxInt(1, int(float64(normalized.TargetTokens)/estimateCalibration))
		}

		requestOverheadTokens := estimateModelRequestOverheadTokens(instructions, tools, settings)
		// Post-provider-compaction steady state: while the plaintext that
		// accumulated after the newest provider compaction blob stays below
		// the trigger, skip BOTH provider and local compaction this turn.
		// Neither can help — the blob's (capped) estimate is what keeps the
		// total above the trigger, re-compacting it buys nothing, and the
		// local planner must not run either: falling through to it would
		// spend an LLM-summary call per turn on negligible growth.
		if !compactionCfg.Enabled || !shouldDeferCompactionForBlobGrowth(currentInput, compactionCfg, requestOverheadTokens) {
			compactRequest := ModelRequest{
				Model:          modelName,
				PromptCacheKey: cfg.PromptCacheKey,
				Instructions:   instructions,
				Input:          currentInput,
				Tools:          tools,
				Settings:       settings,
				OutputSchema:   currentAgent.OutputType,
			}
			compactCtx, compactCancel := modelCallContext(ctx, cfg.ModelCallTimeout)
			compactResult, before, after, ok, compactErr := compactRunItemsWithModelAPI(compactCtx, activeModel, compactRequest, requestOverheadTokens, compactionCfg, false)
			compactCancel()
			if ok {
				var carryForward string
				currentInput, carryForward = applyCompactionCarryForward(ctx, compactResult.Items, currentInput, cfg, compactionCfg, requestOverheadTokens)
				if guardErr := guardCompactionCarryForward(runCtx, currentAgent, carryForward); guardErr != nil {
					return nil, guardErr
				}
				after = estimateRunItemsTokens(currentInput) + requestOverheadTokens
				runCtx.Usage.Add(compactResult.Usage)
				recordOutOfBandUsage(cfg.Hooks, activeModel, modelName, compactResult.Usage)
				if cfg.CompactionRecorder != nil {
					cfg.CompactionRecorder(before, after, appendCompactionSummaryCarryForward(compactResult.Summary, carryForward))
				}
			} else {
				if compactErr != nil {
					log.Printf("[runner] WARN: provider compaction failed; falling back to local compaction: %v", compactErr)
				}
				if plan, before, ok, reason := PlanRunItemsCompactionForRequest(currentInput, compactionCfg, requestOverheadTokens); ok {
					compactedItems := plan.Items
					if compactionCfg.UseLLMSummary {
						rebuilt, usage, llmOK := applyLLMSummaryToPlan(ctx, activeModel, modelName, plan, cfg.ModelCallTimeout)
						runCtx.Usage.Add(usage)
						recordOutOfBandUsage(cfg.Hooks, activeModel, modelName, usage)
						if llmOK {
							compactedItems = rebuilt
						}
					}
					var carryForward string
					currentInput, carryForward = applyCompactionCarryForward(ctx, compactedItems, currentInput, cfg, compactionCfg, requestOverheadTokens)
					if guardErr := guardCompactionCarryForward(runCtx, currentAgent, carryForward); guardErr != nil {
						return nil, guardErr
					}
					after := estimateRunItemsTokens(currentInput) + requestOverheadTokens
					if cfg.CompactionRecorder != nil {
						cfg.CompactionRecorder(before, after, appendCompactionSummaryCarryForward(ExtractCompactionSummary(currentInput), carryForward))
					}
				} else if cfg.CompactionFailureReporter != nil && reason != "disabled" && reason != "below-threshold" {
					if compactErr != nil {
						reason = fmt.Sprintf("provider-compaction-failed: %v; local-compaction: %s", compactErr, reason)
					}
					cfg.CompactionFailureReporter("run", reason, before, after)
				}
			}
		}

		// --- Structured turn logging ---
		{
			var toolNames []string
			for _, t := range tools {
				toolNames = append(toolNames, t.Name())
			}
			var handoffNames []string
			for _, h := range currentAgent.Handoffs {
				handoffNames = append(handoffNames, h.ToolName)
			}
			al.Turn(turn, currentAgent.Name, currentAgent.Model)
			al.Tools(toolNames, handoffNames, cfg.ToolAccessLevel)
			al.Instructions(instructions)
			al.InputItems(currentInput)
			al.TurnEnd(turn)
		}

		// Fire hooks.
		fireRunHook(cfg.Hooks, func(h RunHooks) { h.OnAgentStart(runCtx, currentAgent) })
		fireAgentHook(currentAgent.Hooks, func(h AgentHooks) { h.OnStart(runCtx, currentAgent) })
		fireRunHook(cfg.Hooks, func(h RunHooks) { h.OnLLMStart(runCtx, currentAgent) })

		llmAttempt++
		modelIdentity := NormalizeModelIdentity(requestedModelName, activeModel.Provider())
		parentCallID := ParentCallIDFromContext(runCtx.Context())
		taskID := TaskIDFromContext(runCtx.Context())
		llmScope := "top_level"
		if taskID != "" || parentCallID != "" {
			llmScope = "subagent"
		}
		if taskID == "" && parentCallID != "" {
			// Legacy fallback for nested runs that only threaded the parent tool call ID.
			taskID = parentCallID
		}

		// The request input is exactly the accumulated conversation: plan
		// state, when a host tracks one, lives in durable history like any
		// other context (per-request transient re-injection was removed — it
		// made the model re-orient and re-narrate every turn).
		requestInput := currentInput

		modelRequest := ModelRequest{
			Model:               modelName,
			PromptCacheKey:      cfg.PromptCacheKey,
			Instructions:        instructions,
			Input:               requestInput,
			Tools:               tools,
			Settings:            settings,
			OutputSchema:        currentAgent.OutputType,
			CompactionThreshold: modelCompactionThreshold(activeModel, providerCompactionCfg),
		}
		requestSnapshot := BuildLLMRequestSnapshot(currentAgent.Name, modelRequest)
		genData := &GenerationSpanData{
			RequestedModel:               modelIdentity.Raw,
			ResolvedModel:                modelName,
			ModelProvider:                modelIdentity.Provider,
			ModelCanonical:               modelIdentity.Canonical,
			AttemptNumber:                llmAttempt,
			Turn:                         int32(turn + 1),
			Scope:                        llmScope,
			TaskID:                       taskID,
			ToolCount:                    int32(len(tools)),
			InputItemCount:               int32(len(currentInput)),
			InstructionsLength:           int32(len(instructions)),
			InputTokenEstimate:           int32(requestSnapshot.InputTokenEstimate),
			RequestOverheadTokenEstimate: int32(requestSnapshot.RequestOverheadTokenEstimate),
			TotalRequestTokenEstimate:    int32(requestSnapshot.TotalTokenEstimate),
			Request:                      requestSnapshot,
		}
		genSpan := NewSpan("generation", spanParent, genData)
		attemptID := genSpan.ID
		attemptEvent := func(status string) ContentEvent {
			return ContentEvent{
				ToolUseID:      attemptID,
				LLMAttempt:     llmAttempt,
				LLMScope:       llmScope,
				AttemptNumber:  llmAttempt,
				AttemptStatus:  status,
				Scope:          llmScope,
				RequestedModel: modelIdentity.Raw,
				ResolvedModel:  modelName,
				CanonicalModel: modelIdentity.Canonical,
				Provider:       modelIdentity.Provider,
				AgentName:      currentAgent.Name,
				TaskID:         taskID,
				Status:         status,
				Model:          modelIdentity.Canonical,
				Turn:           int32(turn + 1),
			}
		}
		if err := emitDurableCheckpoint(ctx, cfg.Durable, &durableSequence, DurableBoundaryModelPrepared, currentAgent, currentInput, nil, runCtx.Usage); err != nil {
			return nil, fmt.Errorf("persist model-prepared checkpoint: %w", err)
		}
		emitLLMAttemptEvent(cfg.Hooks, attemptEvent("started"))
		tp.OnSpanStart(genSpan)
		openGenSpan = genSpan

		// Bound inactivity rather than total generation time. Each provider stream
		// event resets the timer, matching Codex CLI semantics while still bounding
		// initial request stalls and silent connections.
		llmStartedAt := time.Now()
		callCtx, callActivity, callCancel := modelCallIdleContext(ctx, cfg.ModelCallTimeout)
		// Surface reasoning text live while the (blocking) model call is in
		// flight: transports that stream internally feed a coalescing emitter
		// which writes assistant_thinking_delta events keyed by attemptID.
		// The streamed-run path already forwards reasoning deltas through its
		// own event channel, so the sink is only installed for blocking runs.
		var commitment modelOutputCommitment
		callCtx, immediateCancel := immediateInputContext(callCtx, cfg.ImmediateInputSignal, commitment.interrupt)
		var thinkingDeltas *thinkingDeltaEmitter
		if platformHooks := findPlatformHooks(cfg.Hooks); platformHooks != nil {
			platformHooks.setLLMAttemptID(attemptID)
			if streamEvents == nil && platformHooks.EventStream != nil {
				thinkingDeltas = newThinkingDeltaEmitter(platformHooks.EventStream, attemptID, currentAgent.Name)
				callCtx = modeldelta.WithReasoningSink(callCtx, func(chunk string) {
					if chunk == "" {
						return
					}
					if !commitment.markVisible() && !commitment.visible() {
						return
					}
					thinkingDeltas.Chunk(chunk)
					commitment.providerReasoning.Store(true)
				})
			}
		}
		resp, err := r.callModel(callCtx, activeModel, modelRequest, streamEvents, callActivity, &commitment)
		supersededResp := resp
		resp, err = settleImmediateInput(immediateCancel, &commitment, resp, err)
		// context.Cause records the atomic first cancellation winner, avoiding a
		// race that could relabel parent cancellation as stream inactivity.
		callCause := context.Cause(callCtx)
		perCallTimeout := err != nil && errors.Is(callCause, errModelStreamIdleTimeout)
		immediateInputArrived := err != nil && (errors.Is(callCause, errImmediateInput) || errors.Is(err, errImmediateInput))
		callCancel()
		if thinkingDeltas != nil {
			thinkingDeltas.Flush()
		}
		// An idle timeout is a transient provider hang, not a user cancellation:
		// expose deadline semantics to the existing retry/fallback policy while
		// preserving whether user-visible stream output was already committed.
		if perCallTimeout {
			timeoutErr := fmt.Errorf("model response stream idle for %s: %w", effectiveModelCallTimeout(cfg.ModelCallTimeout), context.DeadlineExceeded)
			if streamOutputWasCommitted(err) {
				err = &streamOutputCommittedError{cause: timeoutErr}
			} else {
				err = timeoutErr
			}
		}

		if err != nil {
			turnRetryAttempt++
			advice := activeModel.GetRetryAdvice(err)
			genData.LatencyMS = time.Since(llmStartedAt).Milliseconds()
			genData.Error = err.Error()
			genData.FailureKind = generationFailureKind(err, advice)
			genData.Status = "failed"
			genSpan.Data = genData
			// Capture the attempt's end time now, but export the span only at
			// the decision points below: exporting here would freeze
			// retry_scheduled/retry_after_ms/fallback_* at their zero values
			// before the retry/fallback decision is made.
			genSpan.Finish()
			exportGenSpan := func() {
				tp.OnSpanEnd(genSpan)
				openGenSpan = nil
				trace.AddSpan(genSpan)
			}

			if immediateInputArrived && commitment.state.Load() == modelOutputInterrupted {
				// Steering supersedes this attempt rather than failing the run. Do not
				// charge it against the turn or retry budgets: the next iteration polls
				// and appends the queued input before issuing the replacement request.
				// The provider still billed a completed-but-discarded response, so its
				// usage is booked before the response is dropped.
				if supersededResp != nil && supersededResp.Usage != (Usage{}) {
					runCtx.Usage.Add(supersededResp.Usage)
					recordOutOfBandUsage(cfg.Hooks, activeModel, modelName, supersededResp.Usage)
				}
				genData.Status = "interrupted"
				genSpan.Data = genData
				exportGenSpan()
				emitLLMAttemptEvent(cfg.Hooks, attemptEvent("interrupted"))
				turnRetryAttempt--
				turn--
				continue
			}

			if isContextCancellation(err) && !perCallTimeout {
				exportGenSpan()
				ev := attemptFailureEvent(attemptEvent("failed"), genData)
				emitLLMAttemptEvent(cfg.Hooks, ev)
				return nil, err
			}

			// Provider rejected encrypted context items (compaction blobs /
			// encrypted reasoning are bound to the producing provider, backend
			// and model; they go stale on model switches, cross-provider
			// fallback, or long-lived session resume). Strip the undecryptable
			// items and retry instead of bricking the session: the preserved
			// plaintext (initial user messages, recent items, carry-forward)
			// keeps the run on task.
			if isEncryptedContentError(err) {
				if stripped, removed := stripUndecryptableEncryptedItems(currentInput); removed > 0 {
					log.Printf("[runner] WARN: provider rejected encrypted context items; stripped %d and retrying: %v", removed, err)
					currentInput = stripped
					ev := attemptFailureEvent(attemptEvent("retrying"), genData)
					ev.RetryPlanned = true
					emitLLMAttemptEvent(cfg.Hooks, ev)
					exportGenSpan()
					continue
				}
			}

			if isContextLengthExceededError(err) {
				forcedRequest := ModelRequest{
					Model:          modelName,
					PromptCacheKey: cfg.PromptCacheKey,
					Instructions:   instructions,
					Input:          currentInput,
					Tools:          tools,
					Settings:       settings,
					OutputSchema:   currentAgent.OutputType,
				}
				forcedCompactCtx, forcedCompactCancel := modelCallContext(ctx, cfg.ModelCallTimeout)
				compactResult, before, after, ok, compactErr := compactRunItemsWithModelAPI(forcedCompactCtx, activeModel, forcedRequest, requestOverheadTokens, compactionCfg, true)
				forcedCompactCancel()
				if ok {
					var carryForward string
					currentInput, carryForward = applyCompactionCarryForward(ctx, compactResult.Items, currentInput, cfg, compactionCfg, requestOverheadTokens)
					if guardErr := guardCompactionCarryForward(runCtx, currentAgent, carryForward); guardErr != nil {
						return nil, guardErr
					}
					after = estimateRunItemsTokens(currentInput) + requestOverheadTokens
					runCtx.Usage.Add(compactResult.Usage)
					recordOutOfBandUsage(cfg.Hooks, activeModel, modelName, compactResult.Usage)
					if cfg.CompactionRecorder != nil {
						cfg.CompactionRecorder(before, after, appendCompactionSummaryCarryForward(compactResult.Summary, carryForward))
					}
					ev := attemptFailureEvent(attemptEvent("retrying"), genData)
					ev.RetryPlanned = true
					emitLLMAttemptEvent(cfg.Hooks, ev)
					exportGenSpan()
					continue
				} else if compactErr != nil {
					log.Printf("[runner] WARN: provider compaction after context error failed; falling back to local compaction: %v", compactErr)
				}

				forcedCfg := compactionCfg.normalized()
				beforeEstimate := estimateRunItemsTokens(currentInput)
				forcedCfg.TriggerTokens = 1
				forcedCfg.TargetTokens = minInt(forcedCfg.TargetTokens, maxInt(1, beforeEstimate/2))
				if plan, before, ok, reason := planRunItemsCompaction(currentInput, forcedCfg); ok {
					compactedItems := plan.Items
					if forcedCfg.UseLLMSummary {
						rebuilt, usage, llmOK := applyLLMSummaryToPlan(ctx, activeModel, modelName, plan, cfg.ModelCallTimeout)
						runCtx.Usage.Add(usage)
						recordOutOfBandUsage(cfg.Hooks, activeModel, modelName, usage)
						if llmOK {
							compactedItems = rebuilt
						}
					}
					var carryForward string
					currentInput, carryForward = applyCompactionCarryForward(ctx, compactedItems, currentInput, cfg, compactionCfg, requestOverheadTokens)
					if guardErr := guardCompactionCarryForward(runCtx, currentAgent, carryForward); guardErr != nil {
						return nil, guardErr
					}
					after := estimateRunItemsTokens(currentInput)
					if cfg.CompactionRecorder != nil {
						cfg.CompactionRecorder(before, after, appendCompactionSummaryCarryForward(ExtractCompactionSummary(currentInput), carryForward))
					}
					ev := attemptFailureEvent(attemptEvent("retrying"), genData)
					ev.RetryPlanned = true
					emitLLMAttemptEvent(cfg.Hooks, ev)
					exportGenSpan()
					continue
				} else if cfg.CompactionFailureReporter != nil && reason != "disabled" && reason != "below-threshold" {
					cfg.CompactionFailureReporter("run", reason, before, after)
				}
			}

			if r.provider != nil && shouldFallbackModelCall(err, advice) {
				if fallbackModel, ok := nextFallbackModel(primaryModelName, requestedModelName, effectiveFallbackModels(currentAgent, cfg)); ok {
					activeFallbackModels[currentAgent] = fallbackModel
					fallbackSuccessTurns[currentAgent] = 0
					reason := fallbackReason(advice)
					if reason == "" {
						reason = genData.FailureKind
					}
					genData.FallbackScheduled = true
					genData.FallbackFromModel = requestedModelName
					genData.FallbackToModel = fallbackModel
					genData.FallbackReason = reason
					genData.Status = "fallback"
					genSpan.Data = genData
					ev := attemptFailureEvent(attemptEvent("fallback"), genData)
					ev.RetryPlanned = true
					ev.FallbackPlanned = true
					ev.FallbackFromModel = requestedModelName
					ev.FallbackToModel = fallbackModel
					ev.FallbackReason = reason
					emitLLMAttemptEvent(cfg.Hooks, ev)
					exportGenSpan()
					continue
				}
			}

			// Consult error handler only before any user-visible stream output.
			// Retrying or continuing after commitment would duplicate that output.
			if cfg.ErrorHandler != nil && !streamOutputWasCommitted(err) {
				decision := cfg.ErrorHandler(RunErrorData{Error: err, Agent: currentAgent, Turn: turn})
				switch decision.Action {
				case ErrorActionRetry:
					genData.Status = "retrying"
					genSpan.Data = genData
					ev := attemptFailureEvent(attemptEvent("retrying"), genData)
					ev.RetryPlanned = true
					emitLLMAttemptEvent(cfg.Hooks, ev)
					exportGenSpan()
					continue
				case ErrorActionContinue:
					log.Printf("[runner] error handler chose continue on turn %d: %v", turn, err)
					ev := attemptFailureEvent(attemptEvent("failed"), genData)
					emitLLMAttemptEvent(cfg.Hooks, ev)
					exportGenSpan()
					continue
				case ErrorActionAbort:
					ev := attemptFailureEvent(attemptEvent("failed"), genData)
					emitLLMAttemptEvent(cfg.Hooks, ev)
					exportGenSpan()
					return nil, &AgentError{Message: fmt.Sprintf("model call failed on turn %d", turn), Cause: err}
				}
			}

			if !streamOutputWasCommitted(err) && shouldRetryWithPolicy(cfg.RetryPolicy, turnRetryAttempt) && !retryPolicyBlockedByAdvice(advice) {
				delay := cfg.RetryPolicy.DelayForAttempt(turnRetryAttempt - 1)
				// A provider-directed delay (e.g. 429 Retry-After) is on the
				// provider's clock: never retry sooner than it asked for.
				if advice != nil && advice.RetryAfterMS > delay.Milliseconds() {
					delay = time.Duration(advice.RetryAfterMS) * time.Millisecond
				}
				cappedMS := capRetryAfterMS(delay.Milliseconds())
				delay = time.Duration(cappedMS) * time.Millisecond
				genData.RetryScheduled = true
				genData.RetryAfterMS = cappedMS
				genData.Status = "retrying"
				genSpan.Data = genData
				ev := attemptFailureEvent(attemptEvent("retrying"), genData)
				ev.RetryPlanned = true
				ev.RetryAfterMs = genData.RetryAfterMS
				emitLLMAttemptEvent(cfg.Hooks, ev)
				exportGenSpan()
				select {
				case <-ctx.Done():
					return nil, ctx.Err()
				case <-time.After(delay):
				}
				continue
			}

			if !streamOutputWasCommitted(err) && advice != nil && advice.ShouldRetry && turnRetryAttempt <= maxAdviceRetriesPerTurn {
				cappedMS := capRetryAfterMS(int64(advice.RetryAfterMS))
				if cappedMS <= 0 {
					// The provider asked for a retry without saying when (e.g.
					// a 429 with no Retry-After/reset headers). Never retry
					// immediately: rate limits recover on the provider's
					// clock, and a zero delay hammers the API in a tight loop.
					cappedMS = capRetryAfterMS(adviceRetryDelay(cfg.RetryPolicy, turnRetryAttempt).Milliseconds())
				}
				genData.RetryScheduled = true
				genData.RetryAfterMS = cappedMS
				genData.Status = "retrying"
				genSpan.Data = genData
				ev := attemptFailureEvent(attemptEvent("retrying"), genData)
				ev.RetryPlanned = true
				ev.RetryAfterMs = genData.RetryAfterMS
				emitLLMAttemptEvent(cfg.Hooks, ev)
				exportGenSpan()
				select {
				case <-ctx.Done():
					return nil, ctx.Err()
				case <-time.After(time.Duration(cappedMS) * time.Millisecond):
				}
				continue // retry this turn
			}
			ev := attemptFailureEvent(attemptEvent("failed"), genData)
			emitLLMAttemptEvent(cfg.Hooks, ev)
			exportGenSpan()
			return nil, &AgentError{Message: fmt.Sprintf("model call failed on turn %d", turn), Cause: err}
		}

		costUSD, costKnown := estimateModelCost(activeModel, resp.Usage)
		turnRetryAttempt = 0
		if activeFallbackModels[currentAgent] != "" {
			fallbackSuccessTurns[currentAgent]++
			if fallbackSuccessTurns[currentAgent] >= fallbackPrimaryReprobeTurns {
				log.Printf("[runner] fallback model %q stable for %d turns; re-probing primary %q", requestedModelName, fallbackSuccessTurns[currentAgent], primaryModelName)
				delete(activeFallbackModels, currentAgent)
				delete(fallbackSuccessTurns, currentAgent)
			}
		}
		resp.CostUSD = costUSD
		resp.CostKnown = costKnown
		genData.PromptTokens = int64(resp.Usage.InputTokens)
		genData.CompletionTokens = int64(resp.Usage.OutputTokens)
		genData.CacheReadTokens = int64(resp.Usage.CacheReadTokens)
		genData.CacheCreateTokens = int64(resp.Usage.CacheCreateTokens)
		genData.InputTokensIncludeCache, genData.InputTokensIncludeCacheKnown = usageInputIncludesCache(activeModel)
		genData.TotalTokens = resp.Usage.TotalTokens()
		genData.CostUSD = costUSD
		genData.CostKnown = costKnown
		genData.LatencyMS = time.Since(llmStartedAt).Milliseconds()
		genData.UsageAvailable = true
		genData.OutputItemCount = int32(len(resp.Items))
		genData.Response = BuildLLMResponseSnapshot(resp)
		genData.Success = true
		genData.Status = "completed"
		genSpan.Data = genData
		genSpan.Finish()
		tp.OnSpanEnd(genSpan)
		openGenSpan = nil
		trace.AddSpan(genSpan)
		ev := attemptEvent("completed")
		ev.UsageAvailable = true
		ev.HasPromptTokens = true
		ev.HasCompletionTokens = true
		ev.HasTotalTokens = true
		ev.InputTokens = genData.PromptTokens
		ev.OutputTokens = genData.CompletionTokens
		ev.CacheReadInputTokens = resp.Usage.CacheReadTokens
		ev.CacheCreationInputTokens = resp.Usage.CacheCreateTokens
		ev.InputTokensIncludeCache = genData.InputTokensIncludeCache
		ev.InputTokensIncludeCacheKnown = genData.InputTokensIncludeCacheKnown
		ev.TotalTokens = genData.TotalTokens
		ev.CostUsd = genData.CostUSD
		ev.CostKnown = genData.CostKnown
		ev.AttemptLatencyMs = genData.LatencyMS
		emitLLMAttemptEvent(cfg.Hooks, ev)

		// Stamp the provider-normalized context size before hooks observe the
		// response: host gauges summing usage fields double-count the cached
		// prompt on OpenAI-style providers (input_tokens already include
		// cached tokens), reading ~2x real window pressure on warm requests.
		resp.ContextTokens = usageContextTokens(activeModel, resp.Usage)

		fireRunHook(cfg.Hooks, func(h RunHooks) { h.OnLLMEnd(runCtx, currentAgent, resp) })

		// Track usage.
		runCtx.Usage.Add(resp.Usage)
		allResponses = append(allResponses, *resp)

		// Calibrate the token estimator against the actual context consumed
		// for this request (provider-normalized: OpenAI-style input_tokens
		// already include cached tokens; Anthropic-style cache fields are
		// additive). The correction applies in BOTH directions: the estimator
		// undercounts some histories (~25% on Claude) and overcounts others
		// (encrypted reasoning/compaction blobs are counted as text but not
		// billed as such), so a one-sided clamp let overcounting histories
		// compact at half the real window.
		if actual := resp.ContextTokens; actual > 0 {
			// resp.ContextTokens is prompt-side only: it can never include the
			// output reserve or the safety buffer baked into
			// requestOverheadTokens. Leaving them in the denominator biases
			// the ratio low, and since the trigger is DIVIDED by the
			// calibration, that systematically delays compaction past the
			// headroom the trigger was designed to keep.
			promptOverheadTokens := requestOverheadTokens - outputReserveTokens(settings) - requestSafetyBufferTokens
			if promptOverheadTokens < 0 {
				promptOverheadTokens = 0
			}
			if sentEstimate := estimateRunItemsTokens(requestInput) + promptOverheadTokens; sentEstimate > 0 {
				ratio := float64(actual) / float64(sentEstimate)
				blended := 0.5*estimateCalibration + 0.5*ratio
				estimateCalibration = math.Max(0.5, math.Min(2.5, blended))
			}
		}

		// Process response items.
		newItems := resp.ToRunItems()
		for i := range newItems {
			newItems[i].Agent = currentAgent
		}
		stampCompactionItemOrigin(newItems, activeModel)
		allItems = append(allItems, newItems...)
		emitRunItems(ctx, streamEvents, newItems)
		responseCompactionSummary, responseHasCompaction := providerCompactionSummaryFromItems(newItems)
		responseCompactionRecorded := false
		recordAndPruneResponseCompaction := func(items []RunItem) []RunItem {
			if !responseHasCompaction || responseCompactionRecorded {
				return items
			}
			pruned, prunedOK := pruneBeforeLatestProviderCompaction(items)
			if !prunedOK {
				return items
			}
			before := requestSnapshot.TotalTokenEstimate
			var carryForward string
			pruned, carryForward = applyCompactionCarryForward(ctx, pruned, items, cfg, compactionCfg, requestOverheadTokens)
			after := estimateRunItemsTokens(pruned) + requestOverheadTokens
			if cfg.CompactionRecorder != nil {
				cfg.CompactionRecorder(before, after, appendCompactionSummaryCarryForward(responseCompactionSummary, carryForward))
			}
			responseCompactionRecorded = true
			return pruned
		}

		modelHistory := append(append([]RunItem(nil), currentInput...), newItems...)
		if err := emitDurableCheckpoint(ctx, cfg.Durable, &durableSequence, DurableBoundaryModelCompleted, currentAgent, modelHistory, nil, runCtx.Usage); err != nil {
			return nil, fmt.Errorf("persist model-completed checkpoint: %w", err)
		}

		// Classify the response.
		step := classifyResponse(newItems, currentAgent, runCtx)

		switch s := step.(type) {
		case *finalOutputStep:
			// Match Codex CLI's Responses loop: a completed text-only response requests
			// another sample only when the backend explicitly sends end_turn=false.
			// Message phase is descriptive and does not independently control the loop.
			// Tool calls are classified separately below and always receive a follow-up,
			// so end_turn=true cannot cancel tool-driven continuation.
			if resp.EndTurn != nil && !*resp.EndTurn {
				pendingCompletion = false
				stopGateBlocks = 0
				currentInput = append(currentInput, newItems...)
				currentInput = recordAndPruneResponseCompaction(currentInput)
				continue
			}

			joinItems, joinErr := collectSubAgentFinalJoinItems(ctx, tools)
			if joinErr != nil {
				return nil, joinErr
			}
			if len(joinItems) > 0 {
				currentInput = append(currentInput, newItems...)
				currentInput = append(currentInput, joinItems...)
				currentInput = recordAndPruneResponseCompaction(currentInput)
				allItems = append(allItems, joinItems...)
				emitRunItems(ctx, streamEvents, joinItems)
				if turn >= maxTurns-1 {
					maxTurns++
				}
				continue
			}

			// Double-confirm completion: bounce the first final answer back
			// with a verification prompt. Tool availability (len(tools) > 0)
			// guards the forced no-tool final summary turn, where bouncing
			// would be pointless.
			if cfg.RequireCompletionConfirmation && !pendingCompletion && len(tools) > 0 {
				pendingCompletion = true
				confirmItem := RunItem{
					Type:    RunItemMessage,
					Message: &MessageOutput{Text: completionConfirmationPrompt},
				}
				currentInput = append(currentInput, newItems...)
				currentInput = append(currentInput, confirmItem)
				currentInput = recordAndPruneResponseCompaction(currentInput)
				allItems = append(allItems, confirmItem)
				emitRunItems(ctx, streamEvents, []RunItem{confirmItem})
				if turn >= maxTurns-1 {
					maxTurns++
				}
				continue
			}

			// Deterministic stop gate: block finalization with feedback until
			// the gate passes or the consecutive-block cap is hit.
			if cfg.StopGate != nil && len(tools) > 0 && stopGateBlocks < cfg.EffectiveStopGateMaxBlocks() {
				if ok, feedback := cfg.StopGate(ctx, finalOutputText(s.output)); !ok {
					stopGateBlocks++
					if strings.TrimSpace(feedback) == "" {
						feedback = "the finalization check failed; continue working until it passes"
					}
					gateItem := RunItem{
						Type:    RunItemMessage,
						Message: &MessageOutput{Text: "[SYSTEM] Final answer blocked by the completion gate (" + strconv.Itoa(stopGateBlocks) + "/" + strconv.Itoa(cfg.EffectiveStopGateMaxBlocks()) + "):\n" + feedback},
					}
					currentInput = append(currentInput, newItems...)
					currentInput = append(currentInput, gateItem)
					currentInput = recordAndPruneResponseCompaction(currentInput)
					allItems = append(allItems, gateItem)
					emitRunItems(ctx, streamEvents, []RunItem{gateItem})
					if turn >= maxTurns-1 {
						maxTurns++
					}
					continue
				}
				stopGateBlocks = 0
			}

			// Adversarial verification: give a critic one chance to refute
			// the candidate final answer.
			if cfg.FinalAnswerVerifier != nil && !verifierRan && len(tools) > 0 {
				verifierRan = true
				feedback, vErr := cfg.FinalAnswerVerifier(ctx, finalOutputText(s.output))
				if vErr != nil {
					log.Printf("[runner] WARN: final answer verifier failed: %v", vErr)
				} else if strings.TrimSpace(feedback) != "" {
					verifyItem := RunItem{
						Type:    RunItemMessage,
						Message: &MessageOutput{Text: "[SYSTEM] An independent reviewer examined your answer before finalization and raised these points. Address the valid ones (with tools if needed), then provide your final answer again:\n" + feedback},
					}
					currentInput = append(currentInput, newItems...)
					currentInput = append(currentInput, verifyItem)
					currentInput = recordAndPruneResponseCompaction(currentInput)
					allItems = append(allItems, verifyItem)
					emitRunItems(ctx, streamEvents, []RunItem{verifyItem})
					pendingCompletion = false
					if turn >= maxTurns-1 {
						maxTurns++
					}
					continue
				}
			}

			// Close immediate-input admission atomically with a final queue check.
			// Steering accepted before this point wins and gets another turn;
			// steering racing after it receives a clear finalizing error.
			if cfg.ImmediateInputFinalizer != nil {
				currentInput = append(currentInput, newItems...)
				if continued, finalizeErr := finalizeImmediateInput(); finalizeErr != nil {
					return nil, finalizeErr
				} else if continued {
					currentInput = recordAndPruneResponseCompaction(currentInput)
					if turn >= maxTurns-1 {
						maxTurns++
					}
					continue
				}
				currentInput = currentInput[:len(currentInput)-len(newItems)]
			}

			// Record compaction stats and keep the pruned transcript: when
			// the final response itself carries a provider compaction item,
			// FinalHistory must reflect the post-compaction state — replaying
			// the unpruned transcript would resend the compacted history.
			finalHistory := recordAndPruneResponseCompaction(append(append([]RunItem(nil), currentInput...), newItems...))

			// Run output guardrails.
			var outputGuardrailResults []OutputGuardrailResult
			if len(currentAgent.OutputGuardrails) > 0 {
				outputGuardrailResults, err = runOutputGuardrails(runCtx, currentAgent, s.output)
				if err != nil {
					return nil, err
				}
			}

			fireAgentHook(currentAgent.Hooks, func(h AgentHooks) { h.OnEnd(runCtx, currentAgent, s.output) })
			fireRunHook(cfg.Hooks, func(h RunHooks) { h.OnAgentEnd(runCtx, currentAgent, s.output) })
			if err := emitDurableCheckpoint(ctx, cfg.Durable, &durableSequence, DurableBoundaryRunCompleted, currentAgent, finalHistory, nil, runCtx.Usage); err != nil {
				return nil, fmt.Errorf("persist run-completed checkpoint: %w", err)
			}

			return &RunResult{
				FinalOutput:                s.output,
				LastAgent:                  currentAgent,
				NewItems:                   allItems,
				RawResponses:               allResponses,
				InputGuardrailResults:      inputGuardrailResults,
				OutputGuardrailResults:     outputGuardrailResults,
				ToolInputGuardrailResults:  allToolInputResults,
				ToolOutputGuardrailResults: allToolOutputResults,
				ActionAuditRecords:         append([]ActionAuditRecord(nil), allActionAuditRecords...),
				Usage:                      runCtx.Usage,
				// The final-output branch returns before this turn's newItems
				// are folded into currentInput, so the continuation state is
				// currentInput + newItems — pruned when the final response
				// carried a provider compaction item.
				FinalHistory: finalHistory,
			}, nil

		case *handoffStep:
			handoffSpan := NewSpan("handoff", spanParent, &HandoffSpanData{FromAgent: currentAgent.Name, ToAgent: s.target.Name})
			tp.OnSpanStart(handoffSpan)
			openHandoffSpan = handoffSpan

			fireAgentHook(currentAgent.Hooks, func(h AgentHooks) { h.OnHandoff(runCtx, currentAgent, s.target) })
			fireRunHook(cfg.Hooks, func(h RunHooks) { h.OnHandoff(runCtx, currentAgent, s.target) })

			if s.handoff.OnHandoff != nil {
				input := handoffCallInput(newItems, s.handoff.ToolName)
				if s.handoff.InputType != nil && len(input) > 0 {
					if _, vErr := s.handoff.InputType.Validate(string(input)); vErr != nil {
						log.Printf("[runner] WARN: handoff %q input failed schema validation: %v", s.handoff.ToolName, vErr)
					}
				}
				s.handoff.OnHandoff(runCtx, input)
			}

			handoffOutputs := handoffToolOutputs(newItems, s.handoff, currentAgent, s.target)
			if len(handoffOutputs) > 0 {
				allItems = append(allItems, handoffOutputs...)
				emitRunItems(ctx, streamEvents, handoffOutputs)
			}

			nextInput := append([]RunItem(nil), currentInput...)
			// Both branches must see the current turn's items: the assistant
			// message + handoff tool call and the synthesized handoff outputs
			// are part of the history handed to the target agent, whether or
			// not a filter is applied.
			nextInput = append(nextInput, newItems...)
			nextInput = append(nextInput, handoffOutputs...)
			if s.handoff.InputFilter != nil {
				nextInput = s.handoff.InputFilter(nextInput, allItems)
			}
			nextInput = recordAndPruneResponseCompaction(nextInput)
			if compacted, before, after, ok, reason := MaybeCompactHandoffInput(nextInput, cfg.HandoffHistory); ok {
				var carryForward string
				nextInput, carryForward = applyCompactionCarryForward(ctx, compacted, nextInput, cfg, compactionCfg, requestOverheadTokens)
				after = estimateRunItemsTokens(nextInput)
				if cfg.CompactionRecorder != nil {
					cfg.CompactionRecorder(before, after, appendCompactionSummaryCarryForward(ExtractCompactionSummary(compacted), carryForward))
				}
			} else if cfg.CompactionFailureReporter != nil && reason != "disabled" && reason != "below-threshold" {
				cfg.CompactionFailureReporter("handoff", reason, before, after)
			}
			currentInput = nextInput
			currentAgent = s.target
			pendingCompletion = false
			if err := emitDurableCheckpoint(ctx, cfg.Durable, &durableSequence, DurableBoundaryHandoffCompleted, currentAgent, currentInput, nil, runCtx.Usage); err != nil {
				return nil, fmt.Errorf("persist handoff checkpoint: %w", err)
			}

			handoffSpan.Finish()
			tp.OnSpanEnd(handoffSpan)
			openHandoffSpan = nil
			trace.AddSpan(handoffSpan)

		case *toolCallStep:
			pendingCompletion = false
			stopGateBlocks = 0
			preparedHistory := append(append([]RunItem(nil), currentInput...), newItems...)
			if err := emitDurableCheckpoint(ctx, cfg.Durable, &durableSequence, DurableBoundaryToolPrepared, currentAgent, preparedHistory, nil, runCtx.Usage); err != nil {
				return nil, fmt.Errorf("persist tool-prepared checkpoint: %w", err)
			}
			// The subagent tool can explicitly opt in to completed parent history.
			// Do not include newItems: they contain the current assistant's tool
			// calls without their outputs and would form invalid inherited input.
			parentHistory := cloneParentRunItems(currentInput)
			toolCtx := WithParentRunItems(ctx, parentHistory)
			toolResults, toolInResults, toolOutResults, actionAudits, toolShouldPause, toolGuardErr := r.executeTools(toolCtx, runCtx, currentAgent, tools, s.toolCalls, cfg)
			if toolGuardErr != nil {
				return nil, toolGuardErr
			}
			allToolInputResults = append(allToolInputResults, toolInResults...)
			allToolOutputResults = append(allToolOutputResults, toolOutResults...)
			allActionAuditRecords = append(allActionAuditRecords, actionAudits...)
			allItems = append(allItems, toolResults...)
			emitRunItems(ctx, streamEvents, toolResults)
			currentInput = append(currentInput, newItems...)
			// H3: wrap tool outputs as untrusted before they become next-turn
			// model input. Original toolResults retained in allItems untouched
			// so traces and final results show the raw payload.
			nextTurnToolResults := toolResults
			if cfg.ShouldTagUntrustedToolOutputs() {
				nextTurnToolResults = wrapToolOutputsForInput(toolResults)
			}
			currentInput = append(currentInput, nextTurnToolResults...)
			currentInput = recordAndPruneResponseCompaction(currentInput)
			if err := emitDurableCheckpoint(ctx, cfg.Durable, &durableSequence, DurableBoundaryToolCompleted, currentAgent, currentInput, nil, runCtx.Usage); err != nil {
				return nil, fmt.Errorf("persist tool-completed checkpoint: %w", err)
			}

			// Three-strike escalation: when several consecutive tool turns
			// produce only errors, inject a corrective note instead of letting
			// the model keep grinding on a failing approach.
			if limit := cfg.EffectiveConsecutiveToolErrorLimit(); limit > 0 {
				outputs, errored := 0, 0
				for _, tr := range toolResults {
					if tr.Type == RunItemToolOutput && tr.ToolOutput != nil {
						outputs++
						if tr.ToolOutput.IsError {
							errored++
						}
					}
				}
				if outputs > 0 {
					if errored == outputs {
						consecutiveToolErrorTurns++
					} else {
						consecutiveToolErrorTurns = 0
						toolErrorEscalated = false
					}
					if consecutiveToolErrorTurns >= limit && !toolErrorEscalated {
						toolErrorEscalated = true
						escalation := RunItem{
							Type: RunItemMessage,
							Message: &MessageOutput{Text: fmt.Sprintf(
								"[SYSTEM] Your last %d tool turns all failed. Stop repeating the same approach. Re-read the error messages above carefully, then either: (1) try a fundamentally different approach or tool, (2) inspect the environment to understand why the calls fail, or (3) if the task is genuinely blocked, report the blocker and what you tried instead of retrying.",
								consecutiveToolErrorTurns)},
						}
						currentInput = append(currentInput, escalation)
						allItems = append(allItems, escalation)
						emitRunItems(ctx, streamEvents, []RunItem{escalation})
					}
				}
			}

			// Check for tool approval interruptions. Parallel tool calls can
			// require several approvals in one turn; surface all of them so
			// the host can resolve each pending call — leaving any unresolved
			// produces an unpaired tool_use the provider rejects next turn.
			var interruptions []*Interruption
			for _, tr := range toolResults {
				if tr.Type == RunItemToolApproval {
					interruption := &Interruption{
						ToolName:   tr.ToolApproval.ToolName,
						ToolInput:  tr.ToolApproval.Input,
						ToolCallID: tr.ToolApproval.CallID,
					}
					if tr.ToolApproval.ToolName == "subagent" {
						interruption.ParentContext = SnapshotRunItems(parentHistory)
					}
					interruptions = append(interruptions, interruption)
				}
			}
			if len(interruptions) > 0 {
				if err := emitDurableCheckpoint(ctx, cfg.Durable, &durableSequence, DurableBoundaryApprovalPending, currentAgent, currentInput, interruptions, runCtx.Usage); err != nil {
					return nil, fmt.Errorf("persist approval checkpoint: %w", err)
				}
				return &RunResult{
					LastAgent:                  currentAgent,
					NewItems:                   allItems,
					RawResponses:               allResponses,
					ToolInputGuardrailResults:  allToolInputResults,
					ToolOutputGuardrailResults: allToolOutputResults,
					ActionAuditRecords:         append([]ActionAuditRecord(nil), allActionAuditRecords...),
					Usage:                      runCtx.Usage,
					Interruption:               interruptions[0],
					Interruptions:              interruptions,
					// currentInput already includes this turn's newItems and
					// tool results; pending approvals are still unresolved.
					FinalHistory: append([]RunItem(nil), currentInput...),
				}, nil
			}

			if currentAgent.ToolUseBehavior == StopOnFirstTool || shouldStopAtTools(currentAgent, s.toolCalls) {
				if continued, finalizeErr := finalizeImmediateInput(); finalizeErr != nil {
					return nil, finalizeErr
				} else if continued {
					if turn >= maxTurns-1 {
						maxTurns++
					}
					continue
				}
				finalOutput := finalOutputFromToolResults(currentAgent, toolResults)
				var outputGuardrailResults []OutputGuardrailResult
				if len(currentAgent.OutputGuardrails) > 0 {
					var err error
					outputGuardrailResults, err = runOutputGuardrails(runCtx, currentAgent, finalOutput)
					if err != nil {
						return nil, err
					}
				}
				if err := emitDurableCheckpoint(ctx, cfg.Durable, &durableSequence, DurableBoundaryRunCompleted, currentAgent, currentInput, nil, runCtx.Usage); err != nil {
					return nil, fmt.Errorf("persist tool-result completion checkpoint: %w", err)
				}
				return &RunResult{
					FinalOutput:                finalOutput,
					LastAgent:                  currentAgent,
					NewItems:                   allItems,
					RawResponses:               allResponses,
					ToolInputGuardrailResults:  allToolInputResults,
					ToolOutputGuardrailResults: allToolOutputResults,
					ActionAuditRecords:         append([]ActionAuditRecord(nil), allActionAuditRecords...),
					OutputGuardrailResults:     outputGuardrailResults,
					Usage:                      runCtx.Usage,
					// currentInput already includes this turn's newItems and
					// tool results.
					FinalHistory: append([]RunItem(nil), currentInput...),
				}, nil
			}

			// Pause when a tool explicitly requests it or when the LLM called
			// a pause tool like present_plan or AskUserQuestion.
			shouldPause := toolShouldPause
			if !shouldPause {
				for _, tc := range s.toolCalls {
					if isPauseTool(tc.Name) {
						shouldPause = true
						break
					}
				}
			}
			if shouldPause {
				if err := emitDurableCheckpoint(ctx, cfg.Durable, &durableSequence, DurableBoundaryPaused, currentAgent, currentInput, nil, runCtx.Usage); err != nil {
					return nil, fmt.Errorf("persist pause checkpoint: %w", err)
				}
				return &RunResult{
					LastAgent:                  currentAgent,
					NewItems:                   allItems,
					RawResponses:               allResponses,
					ToolInputGuardrailResults:  allToolInputResults,
					ToolOutputGuardrailResults: allToolOutputResults,
					ActionAuditRecords:         append([]ActionAuditRecord(nil), allActionAuditRecords...),
					Usage:                      runCtx.Usage,
					// currentInput already includes this turn's newItems and
					// tool results (pause tools produce paired outputs).
					FinalHistory: append([]RunItem(nil), currentInput...),
				}, nil
			}
		}
	}

}

// RunStreamed executes an agent with streaming, returning events via a channel.
func (r *Runner) RunStreamed(ctx context.Context, agent *Agent, input []RunItem, cfg RunConfig) *StreamedRunResult {
	events := make(chan StreamEvent, 64)
	done := make(chan *RunResult, 1)
	streamed := &StreamedRunResult{Events: events, done: done}
	if r == nil {
		streamed.setErr(fmt.Errorf("runner is nil"))
		close(events)
		done <- &RunResult{LastAgent: agent, Usage: Usage{}}
		close(done)
		return streamed
	}
	if agent == nil {
		streamed.setErr(fmt.Errorf("agent is nil"))
		close(events)
		done <- &RunResult{Usage: Usage{}}
		close(done)
		return streamed
	}

	go func() {
		defer close(done)
		var unsubscribe func()
		var contentForwardDone chan struct{}
		// forwardStop unblocks the content forwarder after the run finishes:
		// consumers that only wait on FinalResult stop draining Events, so a
		// send guarded only by ctx.Done() would block the forwarder — and the
		// join below — forever, leaking both goroutines and never closing
		// Events.
		forwardStop := make(chan struct{})
		if es := streamedRunEventStream(r, cfg); es != nil {
			contentEvents, unsub := es.Subscribe(256)
			unsubscribe = unsub
			contentForwardDone = make(chan struct{})
			go func() {
				defer close(contentForwardDone)
				for ev := range contentEvents {
					if !emitContentStreamEvent(ctx, events, ev, forwardStop) {
						return
					}
				}
			}()
		}
		defer func() {
			if unsubscribe != nil {
				unsubscribe()
			}
			close(forwardStop)
			if contentForwardDone != nil {
				<-contentForwardDone
			}
			close(events)
		}()
		defer func() {
			if rec := recover(); rec != nil {
				streamed.setErr(fmt.Errorf("streamed run panicked: %v", rec))
				done <- &RunResult{LastAgent: agent, Usage: Usage{}}
			}
		}()
		result, err := r.run(ctx, agent, input, cfg, events)
		if err != nil {
			streamed.setErr(err)
			// A budget-exhausted run still hands back its accumulated
			// state (partial result): forward it so streamed consumers can
			// persist the conversation instead of losing it.
			if result != nil {
				done <- result
				return
			}
			done <- &RunResult{LastAgent: agent, Usage: Usage{}}
			return
		}
		done <- result
	}()

	return streamed
}

func streamedRunEventStream(r *Runner, cfg RunConfig) *EventStream {
	if platformHooks, ok := cfg.Hooks.(*PlatformHooks); ok && platformHooks != nil && platformHooks.EventStream != nil {
		return platformHooks.EventStream
	}
	if r != nil {
		if platformHooks, ok := r.DefaultHooks.(*PlatformHooks); ok && platformHooks != nil && platformHooks.EventStream != nil {
			return platformHooks.EventStream
		}
	}
	return nil
}

func emitContentStreamEvent(ctx context.Context, events chan<- StreamEvent, ev ContentEvent, stop <-chan struct{}) bool {
	content := ev
	streamEvent := StreamEvent{
		Type:    StreamEventContent,
		Content: &content,
		Name:    ev.Type,
	}
	if subagent, ok := SubAgentStreamEventFromContentEvent(ev); ok {
		streamEvent.Type = StreamEventSubAgent
		streamEvent.SubAgent = subagent
	}
	select {
	case events <- streamEvent:
		return true
	case <-ctx.Done():
		return false
	case <-stop:
		// The run is over; make a last non-blocking attempt so an active
		// consumer still sees the event, then give up instead of blocking.
		select {
		case events <- streamEvent:
			return true
		default:
			return false
		}
	}
}

const (
	modelOutputUncommitted int32 = iota
	modelOutputVisible
	modelOutputInterrupted
)

type modelOutputCommitment struct {
	state             atomic.Int32
	providerReasoning atomic.Bool
}

func (c *modelOutputCommitment) markVisible() bool {
	return c != nil && c.state.CompareAndSwap(modelOutputUncommitted, modelOutputVisible)
}

func (c *modelOutputCommitment) interrupt() bool {
	return c != nil && c.state.CompareAndSwap(modelOutputUncommitted, modelOutputInterrupted)
}

func (c *modelOutputCommitment) visible() bool {
	return c != nil && c.state.Load() == modelOutputVisible
}

func (c *modelOutputCommitment) wrap(err error) error {
	if c.visible() {
		return &streamOutputCommittedError{cause: err}
	}
	return err
}

// settleImmediateInput closes and joins the per-attempt listener before reading
// its commitment state. That ordering makes the read authoritative: no late
// steering goroutine can flip an already accepted response afterward.
func settleImmediateInput(stop context.CancelFunc, commitment *modelOutputCommitment, resp *ModelResponse, err error) (*ModelResponse, error) {
	if stop != nil {
		stop()
	}
	if commitment != nil && commitment.state.Load() == modelOutputInterrupted {
		return nil, errImmediateInput
	}
	return resp, err
}

func (r *Runner) callModel(ctx context.Context, model Model, req ModelRequest, streamEvents chan<- StreamEvent, activity func(), commitment *modelOutputCommitment) (*ModelResponse, error) {
	// Consume the public streaming interface for both Run and RunStreamed so
	// built-in and third-party models get identical activity-reset semantics.
	stream, err := model.StreamResponse(ctx, req)
	if err != nil {
		return nil, commitment.wrap(err)
	}
	reasoningAlreadyEmitted := commitment != nil && commitment.providerReasoning.Load()
	// modelFedReasoningSink tracks whether this loop itself fed the context
	// sink; the sink sets providerReasoning, so re-checks below must ignore
	// the flag once we caused it ourselves.
	modelFedReasoningSink := false
	if activity != nil {
		activity() // response headers / stream establishment are progress
	}

	var streamedResp *ModelResponse
	contextFailure := func() error {
		if commitment != nil && commitment.state.Load() == modelOutputInterrupted {
			return errImmediateInput
		}
		return commitment.wrap(ctx.Err())
	}
	for {
		var ev ModelStreamEvent
		var ok bool
		select {
		case <-ctx.Done():
			return nil, contextFailure()
		case ev, ok = <-stream.Events:
			if !ok {
				// Preserve ModelStream's existing contract: Final is authoritative
				// when present, even if a Complete event carried an earlier snapshot.
				select {
				case <-ctx.Done():
					return nil, contextFailure()
				case finalResp, doneOpen := <-stream.done:
					if doneOpen && finalResp != nil {
						streamedResp = finalResp
					}
					if streamedResp == nil {
						streamedResp = &ModelResponse{}
					}
					return streamedResp, nil
				}
			}
		}

		if activity != nil {
			activity()
		}
		switch ev.Type {
		case ModelStreamDelta:
			if streamEvents != nil {
				if !commitment.markVisible() && !commitment.visible() {
					return nil, contextFailure()
				}
				select {
				case streamEvents <- StreamEvent{Type: StreamEventRawResponse, Name: "model.delta", Delta: ev.Delta}:
				case <-ctx.Done():
					return nil, contextFailure()
				}
			}
		case ModelStreamReasoningDelta:
			// Re-check the dedup flag per event: a transport that feeds the
			// context sink internally sets providerReasoning only after the
			// stream starts, so the snapshot alone would let both paths run
			// and duplicate thinking deltas for this attempt.
			if !reasoningAlreadyEmitted && !modelFedReasoningSink && commitment != nil && commitment.providerReasoning.Load() {
				reasoningAlreadyEmitted = true
			}
			hasReasoningOutput := (!reasoningAlreadyEmitted && modeldelta.ReasoningSinkFromContext(ctx) != nil && ev.Delta != "") || streamEvents != nil
			if hasReasoningOutput && !commitment.markVisible() && !commitment.visible() {
				return nil, contextFailure()
			}
			if !reasoningAlreadyEmitted {
				if sink := modeldelta.ReasoningSinkFromContext(ctx); sink != nil && ev.Delta != "" {
					sink(ev.Delta)
					modelFedReasoningSink = true
				}
			}
			if streamEvents != nil {
				select {
				case streamEvents <- StreamEvent{Type: StreamEventRawResponse, Name: "model.reasoning_delta", Delta: ev.Delta}:
				case <-ctx.Done():
					return nil, contextFailure()
				}
			}
		case ModelStreamComplete:
			streamedResp = ev.Response
		case ModelStreamError:
			if ev.Error != nil {
				return nil, commitment.wrap(ev.Error)
			}
			return nil, commitment.wrap(fmt.Errorf("model stream failed"))
		}
	}
}

// emitRunItems forwards run items to the stream without ever blocking past
// context cancellation. StreamedRunResult consumers may stop draining Events
// (e.g. callers that only wait on FinalResult); an unguarded send would then
// block this run goroutine forever once the channel buffer fills.
func emitRunItems(ctx context.Context, events chan<- StreamEvent, items []RunItem) {
	if events == nil {
		return
	}
	for i := range items {
		item := items[i]
		select {
		case events <- StreamEvent{Type: StreamEventRunItem, Item: &item}:
		case <-ctx.Done():
			return
		}
	}
}

func collectSubAgentFinalJoinItems(ctx context.Context, tools []Tool) ([]RunItem, error) {
	var joined []RunItem
	for _, tool := range tools {
		provider, ok := unwrapPolicyTool(tool).(subAgentFinalJoinProvider)
		if !ok {
			continue
		}
		items, err := provider.JoinSubAgentResults(ctx)
		if err != nil {
			return nil, err
		}
		joined = append(joined, items...)
	}
	return joined, nil
}

// pollSubAgentResultItems drains already-terminal managed sub-agent results
// without blocking on still-active tasks.
func pollSubAgentResultItems(tools []Tool) []RunItem {
	var items []RunItem
	for _, tool := range tools {
		poller, ok := unwrapPolicyTool(tool).(subAgentResultPoller)
		if !ok {
			continue
		}
		items = append(items, poller.PollSubAgentResults()...)
	}
	return items
}

func hasPendingSubAgentFinalJoin(tools []Tool) bool {
	for _, tool := range tools {
		provider, ok := unwrapPolicyTool(tool).(subAgentFinalJoinStateProvider)
		if !ok {
			continue
		}
		if provider.HasPendingSubAgentFinalJoin() {
			return true
		}
	}
	return false
}

// --- internal step types ---

type responseStep interface{ step() }

type finalOutputStep struct {
	output any
}

func (*finalOutputStep) step() {}

type handoffStep struct {
	handoff *Handoff
	target  *Agent
}

func (*handoffStep) step() {}

type toolCallStep struct {
	toolCalls []ToolCallData
}

func (*toolCallStep) step() {}

// finalOutputText renders a candidate final output as text for StopGate and
// FinalAnswerVerifier callbacks.
func finalOutputText(output any) string {
	switch v := output.(type) {
	case nil:
		return ""
	case string:
		return v
	default:
		b, err := json.Marshal(v)
		if err != nil {
			return fmt.Sprintf("%v", v)
		}
		return string(b)
	}
}

// classifyResponse determines what the model wants to do: final output, handoff, or tool calls.
func classifyResponse(items []RunItem, agent *Agent, runCtx *RunContext) responseStep {
	var toolCalls []ToolCallData
	var hasText bool
	var lastText string

	for _, item := range items {
		switch item.Type {
		case RunItemToolCall:
			if item.ToolCall != nil {
				for _, h := range agent.Handoffs {
					if h.ToolName != item.ToolCall.Name {
						continue
					}
					// A disabled handoff must not be triggerable: the model can
					// re-emit a handoff tool name it saw earlier in history even
					// though filterByAccess hid the tool from this request. Fall
					// through to normal tool handling (unknown tool -> error
					// output) instead of transferring.
					if h.IsEnabledFn != nil && !h.IsEnabledFn(runCtx) {
						continue
					}
					return &handoffStep{handoff: h, target: h.Agent}
				}
				toolCalls = append(toolCalls, *item.ToolCall)
			}
		case RunItemMessage:
			if item.Message != nil && item.Message.Text != "" {
				hasText = true
				lastText = item.Message.Text
			}
		}
	}

	if len(toolCalls) > 0 {
		return &toolCallStep{toolCalls: toolCalls}
	}

	var output any = lastText
	if hasText && agent.OutputType != nil {
		parsed, err := agent.OutputType.Validate(lastText)
		if err != nil {
			log.Printf("[runner] WARN: output schema validation failed for agent %q: %v", agent.Name, err)
		} else {
			output = parsed
		}
	}
	return &finalOutputStep{output: output}
}

// handoffCallInput returns the raw JSON arguments the model supplied for the
// handoff tool call matching toolName, or nil if none is present.
func handoffCallInput(items []RunItem, toolName string) json.RawMessage {
	for _, item := range items {
		if item.Type == RunItemToolCall && item.ToolCall != nil && item.ToolCall.Name == toolName {
			return item.ToolCall.Input
		}
	}
	return nil
}

// handoffToolOutputs synthesizes tool outputs for every tool call in the
// response that triggered a handoff. The triggered handoff call gets a
// transfer acknowledgement; any sibling calls (parallel tool calls or a
// second handoff in the same turn) are never executed, so they get an
// explanatory output instead — an unpaired tool_use in the next request is
// rejected by provider APIs.
func handoffToolOutputs(items []RunItem, handoff *Handoff, fromAgent, toAgent *Agent) []RunItem {
	if handoff == nil || toAgent == nil {
		return nil
	}
	var outputs []RunItem
	handled := false
	for _, item := range items {
		if item.Type != RunItemToolCall || item.ToolCall == nil {
			continue
		}
		content := fmt.Sprintf("Handing off to %s", toAgent.Name)
		isError := false
		if item.ToolCall.Name != handoff.ToolName || handled {
			content = fmt.Sprintf("not executed: the conversation was handed off to %s in this turn", toAgent.Name)
			isError = true
		} else {
			handled = true
		}
		outputs = append(outputs, RunItem{
			Type:  RunItemToolOutput,
			Agent: fromAgent,
			ToolOutput: &ToolOutputData{
				CallID:  item.ToolCall.ID,
				Content: content,
				IsError: isError,
			},
		})
	}
	return outputs
}

// toolCallResult holds the output of a single parallel tool execution.
type toolCallResult struct {
	item             RunItem
	inputGuardrails  []ToolGuardrailResult
	outputGuardrails []ToolGuardrailResult
	guardrailErr     error
	shouldPause      bool // Propagated from ToolResult.ShouldPause (e.g. a host pause tool).
}

// executeTools runs all tool calls in parallel and returns the results as RunItems.
// Order is preserved: results[i] corresponds to calls[i].
// tools must be the turn's prepared tool slice (the exact list the model was
// shown) so execution cannot diverge from what was offered.
// Matches the OpenAI Agents SDK's _FunctionToolBatchExecutor pattern.
func (r *Runner) executeTools(ctx context.Context, runCtx *RunContext, agent *Agent, tools []Tool, calls []ToolCallData, cfg RunConfig) ([]RunItem, []ToolGuardrailResult, []ToolGuardrailResult, []ActionAuditRecord, bool, error) {
	toolMap := make(map[string]Tool, len(tools))
	for _, t := range tools {
		name := t.Name()
		if _, exists := toolMap[name]; exists {
			// Reject duplicate tool registrations (finding M4) instead of
			// silently last-write-wins, which can mask hostile shadowing.
			return nil, nil, nil, nil, false, &AgentError{Message: fmt.Sprintf("duplicate tool registration: %q", name)}
		}
		toolMap[name] = t
	}

	// Pre-allocate order-preserving slots.
	slots := make([]toolCallResult, len(calls))

	// Partition: resolve synchronous results (unknown tool, needs approval) vs async execution.
	type asyncWork struct {
		idx  int
		call ToolCallData
		tool Tool
	}
	var work []asyncWork
	var actionAudits []ActionAuditRecord

	for i, call := range calls {
		t, ok := toolMap[call.Name]
		if !ok {
			slots[i] = toolCallResult{item: RunItem{
				Type: RunItemToolOutput, Agent: agent,
				ToolOutput: &ToolOutputData{CallID: call.ID, Content: fmt.Sprintf("unknown tool: %s", call.Name), IsError: true},
			}}
			continue
		}
		if cfg.ActionAuthorizer != nil {
			request := ActionRequest{
				ToolName:   call.Name,
				Input:      append(json.RawMessage(nil), call.Input...),
				WorkDir:    cfg.WorkDir,
				ReadOnly:   t.IsReadOnly(),
				Provenance: "model-tool-call",
			}
			authorization, authErr := cfg.ActionAuthorizer.Authorize(ctx, request)
			authorization = NormalizeActionAuthorization(authorization, authErr)
			audit := ActionAuditRecord{Request: request, Authorization: authorization}
			if authErr != nil {
				audit.Error = authErr.Error()
			}
			actionAudits = append(actionAudits, audit)
			switch authorization.Decision {
			case ActionDecisionDeny:
				reason := strings.TrimSpace(authorization.Reason)
				if reason == "" {
					reason = "the action is not permitted by policy"
				}
				slots[i] = toolCallResult{item: RunItem{
					Type: RunItemToolOutput, Agent: agent,
					ToolOutput: &ToolOutputData{CallID: call.ID, Content: "Action denied: " + reason + ". Respect this boundary and find a safer approach; do not route around it.", IsError: true},
				}}
				continue
			case ActionDecisionAsk:
				slots[i] = toolCallResult{item: RunItem{
					Type: RunItemToolApproval, Agent: agent,
					ToolApproval: &ToolApprovalData{ToolName: call.Name, Input: call.Input, CallID: call.ID},
				}}
				continue
			}
		}
		if t.NeedsApproval() {
			slots[i] = toolCallResult{item: RunItem{
				Type: RunItemToolApproval, Agent: agent,
				ToolApproval: &ToolApprovalData{ToolName: call.Name, Input: call.Input, CallID: call.ID},
			}}
			continue
		}
		work = append(work, asyncWork{idx: i, call: call, tool: t})
	}

	// Execute tools in parallel, with optional concurrency limit for sub-agent tools.
	maxSubAgents := cfg.MaxConcurrentSubAgents
	if len(work) > 1 {
		log.Printf("[runner] executing %d tool calls in parallel: %v", len(work), func() []string {
			names := make([]string, len(work))
			for i, w := range work {
				names[i] = w.call.Name
			}
			return names
		}())
	}

	var wg sync.WaitGroup
	// Build a semaphore for sub-agent concurrency if configured.
	var sem chan struct{}
	if maxSubAgents > 0 {
		sem = make(chan struct{}, maxSubAgents)
	}
	// Turn-scoped read/write lock (codex parallel-execution pattern):
	// parallel-safe tools (read-only and control-flow/sub-agent tools) share a
	// read lock and run concurrently; mutating tools (Edit, Write, Bash, …)
	// take the write lock and run exclusively. This prevents two concurrent
	// tool calls from editing the same file or racing a shell command against
	// an in-flight edit, while keeping read fan-out and parallel delegation fast.
	var mutationLock sync.RWMutex
	wg.Add(len(work))
	for _, w := range work {
		go func(w asyncWork) {
			defer wg.Done()
			defer func() {
				if rec := recover(); rec != nil {
					slots[w.idx] = toolCallResult{
						item: RunItem{
							Type:  RunItemToolOutput,
							Agent: agent,
							ToolOutput: &ToolOutputData{
								CallID:  w.call.ID,
								Content: fmt.Sprintf("tool %q panicked: %v", w.call.Name, rec),
								IsError: true,
							},
						},
					}
				}
			}()
			// Apply semaphore only for sub-agent tools (Agent.AsTool wrappers),
			// detected by Go type rather than name prefix (finding M2).
			isSubAgent := isSubAgentTool(w.tool)
			if sem != nil && isSubAgent {
				sem <- struct{}{}
				defer func() { <-sem }()
			}
			if isParallelSafeTool(w.tool) {
				mutationLock.RLock()
				defer mutationLock.RUnlock()
			} else {
				mutationLock.Lock()
				defer mutationLock.Unlock()
			}
			slots[w.idx] = r.executeSingleTool(ctx, runCtx, agent, w.tool, w.call, cfg)
		}(w)
	}
	wg.Wait()

	// Collect results in order.
	var results []RunItem
	var allInputGuardrails []ToolGuardrailResult
	var allOutputGuardrails []ToolGuardrailResult
	shouldPause := false

	for _, slot := range slots {
		results = append(results, slot.item)
		allInputGuardrails = append(allInputGuardrails, slot.inputGuardrails...)
		allOutputGuardrails = append(allOutputGuardrails, slot.outputGuardrails...)
		if slot.shouldPause {
			shouldPause = true
		}
		if slot.guardrailErr != nil {
			return results, allInputGuardrails, allOutputGuardrails, actionAudits, shouldPause, slot.guardrailErr
		}
	}

	return results, allInputGuardrails, allOutputGuardrails, actionAudits, shouldPause, nil
}

// executeSingleTool runs one tool call with guardrails and hooks. Thread-safe.
func (r *Runner) executeSingleTool(ctx context.Context, runCtx *RunContext, agent *Agent, t Tool, call ToolCallData, cfg RunConfig) toolCallResult {
	var res toolCallResult

	// Tool input guardrails.
	if len(cfg.ToolInputGuardrails) > 0 {
		inputResults, guardrailErr := runToolInputGuardrails(runCtx, agent, t, call.Input, cfg.ToolInputGuardrails)
		res.inputGuardrails = inputResults
		if guardrailErr != nil {
			if !isToolGuardrailTripwire(guardrailErr) {
				res.guardrailErr = guardrailErr
			}
			res.item = RunItem{Type: RunItemToolOutput, Agent: agent,
				ToolOutput: &ToolOutputData{CallID: call.ID, Content: guardrailErr.Error(), IsError: true}}
			return res
		}
	}

	// Create a per-tool-call RunContext with the call ID so hooks can record it.
	toolRunCtx := *runCtx
	toolRunCtx.ctx = WithToolCallID(runCtx.ctx, call.ID)

	fireRunHook(cfg.Hooks, func(h RunHooks) { h.OnToolStart(&toolRunCtx, agent, t, call) })
	fireAgentHook(agent.Hooks, func(h AgentHooks) { h.OnToolStart(&toolRunCtx, agent, t, call) })

	// Trace: function span wraps the tool execution.
	funcSpan := NewSpan("function", runCtx.SpanParentID, &FunctionSpanData{ToolName: call.Name, Input: string(call.Input)})
	if runCtx.TracingProcessor != nil {
		runCtx.TracingProcessor.OnSpanStart(funcSpan)
	}
	// End exactly once; the defer covers panics in guardrails/hooks so a
	// started span is never leaked un-ended (un-ended spans never export).
	funcSpanEnded := false
	endFuncSpan := func() {
		if funcSpanEnded {
			return
		}
		funcSpanEnded = true
		funcSpan.Finish()
		if runCtx.TracingProcessor != nil {
			runCtx.TracingProcessor.OnSpanEnd(funcSpan)
		}
		if runCtx.Trace != nil {
			runCtx.Trace.AddSpan(funcSpan)
		}
	}
	defer endFuncSpan()

	var result ToolResult
	var err error
	// Inject call ID and tracing context so nested agent runs can stitch their
	// spans under this tool invocation instead of starting a disconnected trace.
	execCtx := WithParentCallID(ctx, call.ID)
	if cfg.Durable != nil {
		cfg.Durable.normalize()
		execCtx = WithDurableIdempotencyKey(execCtx, DurableIdempotencyKey(cfg.Durable.RunID, call.ID))
	}
	execCtx = WithTraceContext(execCtx, runCtx.Trace, runCtx.TracingProcessor, funcSpan.ID)
	execCtx = WithNestedRunConfig(execCtx, cfg)
	timeout := t.TimeoutSeconds()
	if timeout > 0 {
		toolCtx, cancel := context.WithTimeout(execCtx, time.Duration(timeout)*time.Second)
		result, err = safeExecuteTool(t, toolCtx, call.Input, runCtx.WorkDir)
		cancel()
		// Attribute the deadline to the per-tool budget only when the parent
		// context is still alive; otherwise the run-level deadline (or an
		// idle-model cancellation) expired and blaming the tool would record
		// a false "tool timed out" in model-facing history.
		if toolCtx.Err() == context.DeadlineExceeded && execCtx.Err() == nil {
			preserver, preserves := t.(ToolTimeoutResultPreserver)
			preserveResult := preserves && preserver.PreserveResultOnTimeout() && err == nil && !result.IsError
			if !preserveResult {
				err = &ToolTimeoutError{ToolName: call.Name, Timeout: time.Duration(timeout) * time.Second}
			}
		}
	} else {
		result, err = safeExecuteTool(t, execCtx, call.Input, runCtx.WorkDir)
	}

	if err != nil {
		result = ToolResult{Content: err.Error(), IsError: true}
	}

	// Tool output guardrails.
	var outputGuardrailErr error
	if len(cfg.ToolOutputGuardrails) > 0 {
		guardedResult, outputResults, guardrailErr := runToolOutputGuardrails(runCtx, agent, t, result, cfg.ToolOutputGuardrails)
		res.outputGuardrails = outputResults
		if guardrailErr != nil {
			outputGuardrailErr = guardrailErr
			if !isToolGuardrailTripwire(guardrailErr) {
				res.guardrailErr = guardrailErr
			}
			result = ToolResult{Content: guardrailErr.Error(), IsError: true}
		} else {
			result = guardedResult
		}
	}

	// Finish function span after output guardrails so blocked content is not
	// exported as the tool output in tracing.
	funcSpan.Data = &FunctionSpanData{ToolName: call.Name, Input: string(call.Input), Output: result.Content, IsError: result.IsError}
	endFuncSpan()

	fireRunHook(cfg.Hooks, func(h RunHooks) { h.OnToolEnd(&toolRunCtx, agent, t, call, result) })
	fireAgentHook(agent.Hooks, func(h AgentHooks) { h.OnToolEnd(&toolRunCtx, agent, t, call, result) })
	if errorHook, ok := cfg.Hooks.(ToolEndErrorHook); ok {
		if err := errorHook.OnToolEndError(&toolRunCtx, agent, t, call, result); err != nil {
			res.guardrailErr = fmt.Errorf("post-tool hook failed: %w", err)
			result = ToolResult{Content: res.guardrailErr.Error(), IsError: true}
		}
	}

	// Cap the model-facing output. Hooks, traces, and the event stream above
	// received the raw content; only the conversation item is truncated so one
	// oversized tool result cannot flood the context window. Reserve space for
	// the untrusted-output delimiters that are added when constructing the next
	// model request, so the final serialized content still respects the cap.
	content := result.Content
	if maxBytes := cfg.EffectiveMaxToolOutputBytes(); maxBytes > 0 {
		contentBudget := maxBytes
		if cfg.ShouldTagUntrustedToolOutputs() {
			contentBudget -= len(wrapToolOutputContent(""))
			if contentBudget < 0 {
				contentBudget = 0
			}
		}
		if len(content) > contentBudget {
			if spillPath, ok := spillToolOutput(cfg, result.Content); ok {
				hint := fmt.Sprintf("\n[full output saved to %s]", spillPath)
				if len(hint) < contentBudget {
					content = truncateMiddleBytes(content, contentBudget-len(hint)) + hint
				} else {
					content = truncateMiddleBytes(content, contentBudget)
				}
			} else {
				content = truncateMiddleBytes(content, contentBudget)
			}
		}
	}

	res.item = RunItem{
		Type: RunItemToolOutput, Agent: agent,
		ToolOutput: &ToolOutputData{CallID: call.ID, Content: content, IsError: result.IsError, Images: result.Images},
	}
	if outputGuardrailErr != nil {
		return res
	}
	res.shouldPause = result.ShouldPause
	return res
}

func promptCacheWireKey(namespace, logical string) string {
	sum := sha256.Sum256([]byte(namespace + "\x00" + logical))
	return hex.EncodeToString(sum[:])
}

// prepareToolOutputSpill creates an isolated per-run spill directory outside
// the working tree. Explicit parents are caller-managed and retained across
// runs; default OS-temporary spills are removed on return. It fails closed when
// either path cannot be resolved or the selected parent is beneath WorkDir.
func prepareToolOutputSpill(cfg *RunConfig) func() {
	if cfg == nil || cfg.IsReadOnly() {
		return func() {}
	}
	spillParent := strings.TrimSpace(cfg.ToolOutputDir)
	callerManaged := spillParent != ""
	if !callerManaged {
		spillParent = os.TempDir()
	}
	resolvedParent, err := resolveExistingDir(spillParent)
	if err != nil {
		return func() {}
	}
	if workDir := strings.TrimSpace(cfg.WorkDir); workDir != "" {
		resolvedWorkDir, err := resolveExistingDir(workDir)
		if err != nil || pathWithin(resolvedWorkDir, resolvedParent) {
			return func() {}
		}
	}
	spillDir, err := os.MkdirTemp(resolvedParent, ".gratefulagents-tool-output-")
	if err != nil {
		return func() {}
	}
	cfg.toolOutputSpillDir = spillDir
	return func() {
		if !callerManaged {
			_ = os.RemoveAll(spillDir)
		}
		cfg.toolOutputSpillDir = ""
	}
}

func resolveExistingDir(path string) (string, error) {
	absolute, err := filepath.Abs(path)
	if err != nil {
		return "", err
	}
	return filepath.EvalSymlinks(absolute)
}

func pathWithin(parent, candidate string) bool {
	relative, err := filepath.Rel(parent, candidate)
	return err == nil && (relative == "." || (relative != ".." && !strings.HasPrefix(relative, ".."+string(filepath.Separator))))
}

func spillToolOutput(cfg RunConfig, output string) (string, bool) {
	if cfg.IsReadOnly() || cfg.toolOutputSpillDir == "" {
		return "", false
	}
	var random [16]byte
	if _, err := rand.Read(random[:]); err != nil {
		return "", false
	}
	path := filepath.Join(cfg.toolOutputSpillDir, hex.EncodeToString(random[:])+".txt")
	file, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
	if err != nil {
		return "", false
	}
	if _, err = file.WriteString(output); err != nil {
		_ = file.Close()
		_ = os.Remove(path)
		return "", false
	}
	if err = file.Close(); err != nil {
		_ = os.Remove(path)
		return "", false
	}
	return path, true
}

func isToolGuardrailTripwire(err error) bool {
	var inputTripwire *ToolInputGuardrailTripwireTriggered
	if errors.As(err, &inputTripwire) {
		return true
	}
	var outputTripwire *ToolOutputGuardrailTripwireTriggered
	return errors.As(err, &outputTripwire)
}

// isParallelSafeTool reports whether a tool may run concurrently with other
// tool calls in the same turn. Read-only tools cannot mutate shared state, and
// control-flow/sub-agent tools manage their own isolation (sub-agent tasks are
// instructed to own disjoint files), so both classes share a read lock.
// Everything else (Edit, Write, Bash, custom mutating tools) runs exclusively.
func isParallelSafeTool(t Tool) bool {
	if t == nil {
		return true
	}
	return t.IsReadOnly() || isControlFlowToolInstance(t)
}

// isControlFlowTool returns true for tools that manage run lifecycle or user interaction.
// These are always allowed regardless of tool access level.
func isControlFlowTool(name string) bool {
	if _, ok := controlFlowToolNames[name]; ok {
		return true
	}
	// agent_* sub-agent invocation tools are dynamic (one per registered Agent)
	// and remain control-flow. Detected by exact prefix on the canonical
	// agent tool naming convention from agent_tool.go.
	if strings.HasPrefix(name, "agent_") {
		return true
	}
	return false
}

// isControlFlowToolInstance reports whether this concrete tool is a runner
// control-flow primitive. Name-only checks are intentionally not enough for
// agent_* tools: otherwise an arbitrary mutating FunctionTool named
// "agent_delete_everything" would bypass read-only filtering and approval.
func isControlFlowToolInstance(t Tool) bool {
	if t == nil {
		return false
	}
	if _, ok := controlFlowToolNames[t.Name()]; ok {
		return true
	}
	return isSubAgentTool(t)
}

// isPauseTool returns true for tools that require the runner to stop immediately
// so the agent loop can pause and await user input. Without this, the AI can
// call present_plan and finish in the same turn, bypassing the pause.
func isPauseTool(name string) bool {
	return name == "present_plan" || name == "AskUserQuestion"
}

// filterByAccess filters tools according to the ToolAccessLevel tier:
//   - "full" (or empty) → all tools
//   - "read-only" → read-only tools + control-flow tools + exact-name host exceptions
//
// Explicitly allowed mutating tools are not adapted to read-only variants and
// retain IsReadOnly=false. This keeps approval and execution serialization
// intact while allowing a read-only workspace run to emit narrowly scoped
// control-plane output such as a pull-request review.
func filterByAccess(tools []Tool, level ToolAccessLevel, ctx *RunContext, allowedMutatingTools []string) []Tool {
	level = NormalizeToolAccessLevel(level)
	allowed := make(map[string]struct{}, len(allowedMutatingTools))
	for _, name := range allowedMutatingTools {
		if name != "" {
			allowed[name] = struct{}{}
		}
	}

	var filtered []Tool
	for _, t := range tools {
		if t == nil {
			continue
		}
		_, mutatingAllowed := allowed[t.Name()]
		mutatingAllowed = level == ToolAccessLevelReadOnly && mutatingAllowed && !t.IsReadOnly()
		if !mutatingAllowed {
			t = adaptToolForAccess(t, level)
		}
		if t == nil || !t.IsEnabled(ctx) {
			continue
		}
		if level == ToolAccessLevelReadOnly && !t.IsReadOnly() && !isControlFlowToolInstance(t) && !mutatingAllowed {
			continue
		}
		filtered = append(filtered, t)
	}
	return filtered
}

func prepareToolsForRun(tools []Tool, cfg RunConfig, ctx *RunContext) []Tool {
	return applyToolPolicy(filterByAccess(tools, cfg.ToolAccessLevel, ctx, cfg.AllowedMutatingTools), cfg.ToolPolicy)
}

func applyToolPolicy(tools []Tool, policy *ToolPolicy) []Tool {
	if policy == nil || (!policy.ApprovalRequired && policy.DefaultTimeout <= 0) {
		return tools
	}
	out := make([]Tool, 0, len(tools))
	for _, t := range tools {
		approval := policy.ApprovalRequired && !t.IsReadOnly() && !isControlFlowToolInstance(t)
		out = append(out, WrapWithPolicy(t, approval, policy.DefaultTimeout))
	}
	return out
}

func adaptToolForAccess(t Tool, level ToolAccessLevel) Tool {
	if adapter, ok := t.(ToolAccessAdapter); ok {
		if adapted := adapter.ToolForAccess(level); adapted != nil {
			return adapted
		}
	}
	return t
}

func buildRunInstructions(base string, agent *Agent, cfg RunConfig) string {
	var parts []string
	if strings.TrimSpace(base) != "" {
		parts = append(parts, base)
	}
	if extra := strings.TrimSpace(cfg.AdditionalInstructions); extra != "" {
		parts = append(parts, extra)
	} else if legacy := strings.TrimSpace(cfg.ModeInstructions); legacy != "" {
		parts = append(parts, legacy)
	}
	if schemaContext := buildOutputSchemaPromptContext(agent.OutputType); schemaContext != "" {
		parts = append(parts, schemaContext)
	}
	if mcp := buildMCPPromptContext(agent.MCPServers); mcp != "" {
		parts = append(parts, mcp)
	}
	return strings.Join(parts, "\n\n---\n\n")
}

func buildOutputSchemaPromptContext(schema *OutputSchema) string {
	if schema == nil {
		return ""
	}
	name := strings.TrimSpace(schema.Name)
	if name == "" {
		name = "final_output"
	}
	var b strings.Builder
	b.WriteString("<structured_output>\n")
	b.WriteString("When producing a final answer, return JSON only.")
	b.WriteString("\nOutput schema name: ")
	b.WriteString(name)
	if schema.Strict {
		b.WriteString("\nStrict mode: do not include prose, markdown fences, or fields outside the schema.")
	}
	if len(schema.Schema) > 0 {
		b.WriteString("\nJSON schema:\n")
		b.WriteString(string(schema.Schema))
	}
	b.WriteString("\n</structured_output>")
	return b.String()
}

func shouldRetryWithPolicy(policy *RetryPolicy, attempt int) bool {
	if policy == nil || policy.MaxRetries <= 0 {
		return false
	}
	return attempt <= policy.MaxRetries
}

func retryPolicyBlockedByAdvice(advice *ModelRetryAdvice) bool {
	return advice != nil && !advice.ShouldRetry && strings.TrimSpace(advice.Reason) != ""
}

// resolveRequestModelName returns the model name to place in API requests
// after provider routing. Prefix-aware providers (e.g. MultiProvider) decide
// themselves whether the prefix was consumed for routing; for plain providers
// the prefix is stripped only when it names the provider itself, so model IDs
// that contain "/" as part of the ID (e.g. OpenRouter "vendor/model") pass
// through unchanged.
func resolveRequestModelName(provider ModelProvider, model Model, name string) string {
	if normalizer, ok := provider.(ModelNameNormalizer); ok {
		return normalizer.NormalizeModelName(name)
	}
	prefix, bare := ParseModelPrefix(name)
	if prefix == "" || bare == "" {
		return name
	}
	if model != nil && strings.EqualFold(strings.TrimSpace(prefix), strings.TrimSpace(model.Provider())) {
		return bare
	}
	return name
}

func isContextCancellation(err error) bool {
	return errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded)
}

func shouldStopAtTools(agent *Agent, calls []ToolCallData) bool {
	if agent.StopAtTools == nil {
		return false
	}
	for _, call := range calls {
		if agent.StopAtTools.Contains(call.Name) {
			return true
		}
	}
	return false
}

func finalOutputFromToolResults(agent *Agent, results []RunItem) any {
	if agent.ToolsToFinalOutput == nil || !agent.ToolsToFinalOutput.IsFinalOutput {
		return nil
	}
	if len(agent.ToolsToFinalOutput.Output) > 0 {
		return agent.ToolsToFinalOutput.Output
	}
	for _, item := range results {
		if item.Type == RunItemToolOutput && item.ToolOutput != nil {
			return item.ToolOutput.Content
		}
	}
	return nil
}

// safeExecuteTool invokes Tool.Execute with panic recovery. A panicking tool
// is converted to a normal error result so it cannot crash the host process.
func safeExecuteTool(t Tool, ctx context.Context, input json.RawMessage, workDir string) (result ToolResult, err error) {
	defer func() {
		if rec := recover(); rec != nil {
			err = fmt.Errorf("tool %q panicked: %v", t.Name(), rec)
		}
	}()
	return t.Execute(ctx, input, workDir)
}

// fireRunHook safely calls a RunHooks callback if hooks is non-nil.
// A panic in user-supplied hooks is recovered so it cannot crash the host.
func fireRunHook(hooks RunHooks, fn func(RunHooks)) {
	if hooks == nil {
		return
	}
	defer func() {
		if rec := recover(); rec != nil {
			log.Printf("[runner] WARN: run hook panicked (recovered): %v", rec)
		}
	}()
	fn(hooks)
}

func emitLLMAttemptEvent(hooks RunHooks, event ContentEvent) {
	platformHooks := findPlatformHooks(hooks)
	if platformHooks == nil || platformHooks.EventStream == nil {
		return
	}
	platformHooks.EventStream.EmitLLMAttempt(event)
}

// recordOutOfBandUsage books model usage that bypasses OnLLMEnd — history
// compaction calls (provider-side compaction or LLM-summary calls) and
// steering-superseded responses — on the platform tracker. Without this the
// usage would reach RunResult.Usage but never the run-level tracker totals
// (cost caps, session metrics) — and for subagent runs, whose completion no
// longer re-adds RunResult.Usage to the parent tracker, it would be lost
// entirely.
func recordOutOfBandUsage(hooks RunHooks, model Model, modelName string, usage Usage) {
	if usage == (Usage{}) {
		return
	}
	platformHooks := findPlatformHooks(hooks)
	if platformHooks == nil || platformHooks.Tracker == nil {
		return
	}
	costUSD, _ := estimateModelCost(model, usage)
	platformHooks.Tracker.RecordLLMUsage(modelName, costUSD, usage)
}

// findPlatformHooks locates a *PlatformHooks inside hooks, unwrapping
// composite hooks (hosts commonly wrap PlatformHooks with extra observers,
// e.g. trace writers) so llm_attempt events still reach the event stream.
func findPlatformHooks(hooks RunHooks) *PlatformHooks {
	switch h := hooks.(type) {
	case *PlatformHooks:
		return h
	case interface{ Unwrap() []RunHooks }:
		for _, inner := range h.Unwrap() {
			if found := findPlatformHooks(inner); found != nil {
				return found
			}
		}
	}
	return nil
}

func attemptFailureEvent(event ContentEvent, data *GenerationSpanData) ContentEvent {
	event.AttemptLatencyMs = data.LatencyMS
	event.FailureKind = data.FailureKind
	event.Reason = data.FailureKind
	event.FallbackPlanned = data.FallbackScheduled
	event.FallbackFromModel = data.FallbackFromModel
	event.FallbackToModel = data.FallbackToModel
	event.FallbackReason = data.FallbackReason
	if data.FailureKind != "" {
		event.Message = data.FailureKind
	}
	if data.Error != "" {
		event.IsError = true
		event.Output = TruncateBytes(data.Error, eventStreamMaxToolBytes)
	}
	return event
}

func modelCompactionThreshold(model Model, cfg CompactionConfig) int {
	compactor, ok := model.(ContextCompactor)
	if !ok || !compactor.SupportsContextCompaction() {
		return 0
	}
	cfg = cfg.normalized()
	if !cfg.Enabled {
		return 0
	}
	return cfg.TriggerTokens
}

func compactRunItemsWithModelAPI(ctx context.Context, model Model, req ModelRequest, requestOverheadTokens int, cfg CompactionConfig, force bool) (*CompactionResult, int, int, bool, error) {
	cfg = cfg.normalized()
	if !cfg.Enabled || len(req.Input) == 0 {
		return nil, 0, 0, false, nil
	}
	if requestOverheadTokens < 0 {
		requestOverheadTokens = 0
	}
	before := estimateRunItemsTokens(req.Input) + requestOverheadTokens
	if !force && before <= cfg.TriggerTokens {
		return nil, before, before, false, nil
	}
	compactor, ok := model.(ContextCompactor)
	if !ok || !compactor.SupportsContextCompaction() {
		return nil, before, before, false, nil
	}
	result, err := compactor.CompactContext(ctx, req)
	if err != nil {
		return nil, before, before, false, err
	}
	if result == nil || len(result.Items) == 0 {
		return nil, before, before, false, errors.New("provider returned empty compaction output")
	}
	stampCompactionItemOrigin(result.Items, model)
	after := estimateRunItemsTokens(result.Items) + requestOverheadTokens
	return result, before, after, true, nil
}

// shouldDeferCompactionForBlobGrowth reports whether the pre-request
// compaction pass (provider AND local) should be skipped entirely this turn:
// once a provider compaction item anchors the history, only the plaintext
// conversation that accumulated AFTER it can justify another compaction. The
// blob's own (estimated) size must not re-trigger — its true cost is
// provider-side, re-compacting it buys nothing, and letting the local planner
// run instead would burn an LLM-summary call per turn while risking the blob
// itself (the only copy of the provider-compacted history) being summarized
// away. The forced overflow-recovery path bypasses this deliberately.
func shouldDeferCompactionForBlobGrowth(items []RunItem, cfg CompactionConfig, requestOverheadTokens int) bool {
	latest := latestProviderCompactionIndex(items)
	if latest < 0 {
		return false
	}
	if requestOverheadTokens < 0 {
		requestOverheadTokens = 0
	}
	growth := estimateRunItemsTokens(items[latest+1:]) + requestOverheadTokens
	return growth <= cfg.normalized().TriggerTokens
}

// stampCompactionItemOrigin records the producing provider on compaction items
// that arrive without a created_by marker. Encrypted compaction blobs are only
// decryptable by the provider (and backend) that produced them; the origin
// stamp lets request builders skip known-foreign blobs instead of sending
// undecryptable payloads after a cross-provider model fallback or switch.
func stampCompactionItemOrigin(items []RunItem, model Model) {
	if model == nil {
		return
	}
	provider := strings.TrimSpace(model.Provider())
	if provider == "" {
		return
	}
	for i := range items {
		if items[i].Type != RunItemCompaction || items[i].Compaction == nil {
			continue
		}
		if strings.TrimSpace(items[i].Compaction.CreatedBy) == "" {
			items[i].Compaction.CreatedBy = provider
		}
	}
}

func providerCompactionSummaryFromItems(items []RunItem) (string, bool) {
	var compacted []RunItem
	for _, item := range items {
		if item.Type == RunItemCompaction && item.Compaction != nil && strings.TrimSpace(item.Compaction.EncryptedContent) != "" {
			compacted = append(compacted, item)
		}
	}
	if len(compacted) == 0 {
		return "", false
	}
	return summarizeProviderCompactionOutput("", compacted), true
}

func applyCompactionCarryForward(ctx context.Context, compacted, previous []RunItem, cfg RunConfig, compactionCfg CompactionConfig, requestOverheadTokens int) ([]RunItem, string) {
	carryForward := buildCompactionCarryForward(ctx, cfg)
	out := make([]RunItem, 0, len(compacted)+1)
	for _, item := range compacted {
		if isCompactionCarryForwardItem(item) {
			continue
		}
		out = append(out, item)
	}
	if !hasLocalCompactionSummary(out) {
		// Provider compaction (no local summary): the provider's output is
		// typically just an opaque encrypted blob. Mirror the local path's
		// PreserveInitialUserMessages guarantee so the original task prompt
		// survives in plaintext — if the blob is ever dropped, undecryptable,
		// or under-summarized, the agent must still know what it was asked to
		// do instead of restarting cold.
		normalizedCfg := compactionCfg.normalized()
		out = insertMissingInitialUserMessages(out, previous, normalizedCfg.PreserveInitialUserMessages)
		// Preserve as much verbatim recent history as the compaction target
		// allows, not just a fixed item count: a provider blob replaces the
		// history with a few-KB opaque summary, so a count-based tail (12
		// items ≈ 3 tool exchanges once reasoning items are included) left the
		// post-compaction window ~90% empty while the agent lost its recent
		// working state and restarted discovery.
		if requestOverheadTokens < 0 {
			requestOverheadTokens = 0
		}
		tailBudget := normalizedCfg.TargetTokens - requestOverheadTokens - estimateRunItemsTokens(out)
		out = appendMissingRecentRunItems(out, previous, normalizedCfg.PreserveRecentItems, tailBudget)
	}
	out = repairToolPairsForModelInput(out, previous)
	if carryForward == "" {
		return out, ""
	}
	out = append(out, RunItem{
		Type: RunItemMessage,
		Message: &MessageOutput{
			Text: carryForward,
		},
	})
	return out, carryForward
}

// insertMissingInitialUserMessages re-inserts the first `limit` plain user
// messages from the pre-compaction history (the original task framing) right
// after the newest provider compaction item, unless they already survived.
// They are placed after the blob — not before it — so subsequent
// prune-before-latest-compaction passes cannot delete them again.
func insertMissingInitialUserMessages(items, previous []RunItem, limit int) []RunItem {
	if limit <= 0 || len(previous) == 0 {
		return items
	}
	seen := make(map[string]struct{}, len(items))
	for _, item := range items {
		if key := runItemDedupeKey(item); key != "" {
			seen[key] = struct{}{}
		}
	}
	var initial []RunItem
	for _, idx := range selectInitialUserMessageIndices(previous, limit) {
		item := previous[idx]
		key := runItemDedupeKey(item)
		if key == "" {
			continue
		}
		if _, ok := seen[key]; ok {
			continue
		}
		seen[key] = struct{}{}
		initial = append(initial, item)
	}
	if len(initial) == 0 {
		return items
	}
	insertAt := 0
	if latest := latestProviderCompactionIndex(items); latest >= 0 {
		insertAt = latest + 1
	}
	out := make([]RunItem, 0, len(items)+len(initial))
	out = append(out, items[:insertAt]...)
	out = append(out, initial...)
	out = append(out, items[insertAt:]...)
	return out
}

// guardCompactionCarryForward re-runs the agent's input guardrails on a
// carry-forward payload introduced after compaction. Mitigates finding H7:
// without this, malicious content (e.g. a tool-supplied working-state summary)
// could survive compaction and reach the model unchecked. A nil/empty
// carryForward is a no-op.
func guardCompactionCarryForward(runCtx *RunContext, agent *Agent, carryForward string) error {
	if carryForward == "" || len(agent.InputGuardrails) == 0 {
		return nil
	}
	probe := []RunItem{{Type: RunItemMessage, Message: &MessageOutput{Text: carryForward}}}
	_, err := runInputGuardrails(runCtx, agent, probe)
	return err
}

func buildCompactionCarryForward(ctx context.Context, cfg RunConfig) string {
	var sections []string
	dynamicAdded := false
	if cfg.CompactionCarryForward != nil {
		if dynamic := strings.TrimSpace(cfg.CompactionCarryForward(ctx)); dynamic != "" {
			sections = append(sections, dynamic)
			dynamicAdded = true
		}
	}
	if !dynamicAdded {
		if cfg.WorkingStateContext != "" {
			sections = append(sections, cfg.WorkingStateContext)
		}
	}
	sections = dedupeCompactionCarryForwardSections(sections)
	if len(sections) == 0 {
		return ""
	}
	return compactionCarryForwardPrefix + "\nThis live runtime state was injected after context compaction. Treat it as current and higher priority than older compacted history.\n\n" + strings.Join(sections, "\n\n")
}

func appendCompactionSummaryCarryForward(summary, carryForward string) string {
	summary = strings.TrimSpace(summary)
	carryForward = strings.TrimSpace(carryForward)
	if carryForward == "" {
		return summary
	}
	if summary == "" {
		return carryForward
	}
	return summary + "\n\n" + carryForward
}

func isCompactionCarryForwardItem(item RunItem) bool {
	return item.Type == RunItemMessage && item.Message != nil && strings.HasPrefix(strings.TrimSpace(item.Message.Text), compactionCarryForwardPrefix)
}

func hasLocalCompactionSummary(items []RunItem) bool {
	for _, item := range items {
		if item.Type == RunItemMessage && item.Message != nil && item.Agent != nil && item.Agent.Name == "context-summary" && strings.HasPrefix(strings.TrimSpace(item.Message.Text), "[COMPACTED HISTORY SUMMARY]") {
			return true
		}
	}
	return false
}

// appendMissingRecentRunItems re-appends the tail of the pre-compaction
// history that isn't already present. The window always covers at least
// `minItems` items and extends further back while the (estimated) token total
// stays within `budgetTokens`, so the post-compaction request actually uses
// the target-token headroom for verbatim recent context instead of leaving it
// empty. A budgetTokens <= 0 degrades to the fixed minItems window.
func appendMissingRecentRunItems(items, previous []RunItem, minItems, budgetTokens int) []RunItem {
	if minItems <= 0 && budgetTokens <= 0 {
		return items
	}
	if len(previous) == 0 {
		return items
	}
	minPairIdx := 0
	floor := 0
	if latest := latestProviderCompactionIndex(previous); latest >= 0 {
		floor = latest + 1
		minPairIdx = latest + 1
	}
	// Walk backward from the end, accumulating estimated tokens. Include an
	// item while the count guarantee is unmet or it still fits the budget.
	start := len(previous)
	count := 0
	tokens := 0
	for idx := len(previous) - 1; idx >= floor; idx-- {
		if isCompactionCarryForwardItem(previous[idx]) {
			continue
		}
		cost := estimateRunItemsTokens(previous[idx : idx+1])
		if count >= minItems && tokens+cost > budgetTokens {
			break
		}
		start = idx
		count++
		tokens += cost
	}
	if start >= len(previous) {
		return items
	}
	protected := make(map[int]struct{}, len(previous)-start)
	for idx := start; idx < len(previous); idx++ {
		protected[idx] = struct{}{}
	}
	ensureToolPairIntegrityAfter(previous, protected, minPairIdx)

	out := append([]RunItem(nil), items...)
	seen := make(map[string]struct{}, len(out))
	for _, item := range out {
		if key := runItemDedupeKey(item); key != "" {
			seen[key] = struct{}{}
		}
	}
	for idx, item := range previous {
		if _, ok := protected[idx]; !ok {
			continue
		}
		if isCompactionCarryForwardItem(item) {
			continue
		}
		key := runItemDedupeKey(item)
		if key == "" {
			continue
		}
		if _, ok := seen[key]; ok {
			continue
		}
		seen[key] = struct{}{}
		out = append(out, item)
	}
	return out
}

func repairToolPairsForModelInput(items, reference []RunItem) []RunItem {
	if len(items) == 0 {
		return items
	}
	refCalls := map[string]RunItem{}
	refOutputs := map[string]RunItem{}
	indexToolPairReferences(refCalls, refOutputs, reference)
	indexToolPairReferences(refCalls, refOutputs, items)

	// In-flight tool calls have no output ANYWHERE yet but will get one later
	// this run (approval-pending interruptions, host histories persisted
	// mid-turn). Dropping them here would orphan the eventual tool_output.
	pendingApprovalIDs := map[string]struct{}{}
	for _, list := range [][]RunItem{reference, items} {
		for _, item := range list {
			if item.Type == RunItemToolApproval && item.ToolApproval != nil && item.ToolApproval.CallID != "" {
				pendingApprovalIDs[item.ToolApproval.CallID] = struct{}{}
			}
		}
	}
	lastOutputIdx := -1
	for idx, item := range items {
		if item.Type == RunItemToolOutput && item.ToolOutput != nil {
			lastOutputIdx = idx
		}
	}

	currentCalls := map[string]struct{}{}
	currentOutputs := map[string]struct{}{}
	for _, item := range items {
		switch item.Type {
		case RunItemToolCall:
			if item.ToolCall != nil && item.ToolCall.ID != "" {
				currentCalls[item.ToolCall.ID] = struct{}{}
			}
		case RunItemToolOutput:
			if item.ToolOutput != nil && item.ToolOutput.CallID != "" {
				currentOutputs[item.ToolOutput.CallID] = struct{}{}
			}
		}
	}

	out := make([]RunItem, 0, len(items))
	emittedCalls := map[string]struct{}{}
	emittedOutputs := map[string]struct{}{}
	for idx, item := range items {
		switch item.Type {
		case RunItemToolCall:
			if item.ToolCall == nil || item.ToolCall.ID == "" {
				continue
			}
			id := item.ToolCall.ID
			if _, already := emittedCalls[id]; already {
				continue
			}
			if _, paired := currentOutputs[id]; !paired {
				if _, ok := refOutputs[id]; !ok {
					// Keep calls awaiting approval and calls in the trailing
					// (not-yet-executed) region: their outputs arrive later.
					_, pendingApproval := pendingApprovalIDs[id]
					if !pendingApproval && idx <= lastOutputIdx {
						continue
					}
				}
			}
			out = append(out, item)
			emittedCalls[id] = struct{}{}
			if _, paired := currentOutputs[id]; !paired {
				if ref, ok := refOutputs[id]; ok {
					out = append(out, cloneRunItem(ref))
					emittedOutputs[id] = struct{}{}
				}
			}
		case RunItemToolOutput:
			if item.ToolOutput == nil || item.ToolOutput.CallID == "" {
				continue
			}
			id := item.ToolOutput.CallID
			if _, already := emittedOutputs[id]; already {
				continue
			}
			if _, callAlreadyEmitted := emittedCalls[id]; !callAlreadyEmitted {
				if ref, ok := refCalls[id]; ok {
					out = append(out, cloneRunItem(ref))
					emittedCalls[id] = struct{}{}
				} else if _, paired := currentCalls[id]; !paired {
					continue
				}
			}
			out = append(out, item)
			emittedOutputs[id] = struct{}{}
		default:
			out = append(out, item)
		}
	}
	return out
}

func indexToolPairReferences(calls, outputs map[string]RunItem, items []RunItem) {
	for _, item := range items {
		switch item.Type {
		case RunItemToolCall:
			if item.ToolCall != nil && item.ToolCall.ID != "" {
				calls[item.ToolCall.ID] = item
			}
		case RunItemToolOutput:
			if item.ToolOutput != nil && item.ToolOutput.CallID != "" {
				outputs[item.ToolOutput.CallID] = item
			}
		}
	}
}

func latestProviderCompactionIndex(items []RunItem) int {
	latest := -1
	for i, item := range items {
		if item.Type == RunItemCompaction && item.Compaction != nil && strings.TrimSpace(item.Compaction.EncryptedContent) != "" {
			latest = i
		}
	}
	return latest
}

func runItemDedupeKey(item RunItem) string {
	switch item.Type {
	case RunItemMessage:
		if item.Message == nil {
			return ""
		}
		role := "user"
		if item.Agent != nil {
			role = "assistant:" + item.Agent.Name
		}
		return fmt.Sprintf("message:%s:%s", role, item.Message.Text)
	case RunItemToolCall:
		if item.ToolCall == nil {
			return ""
		}
		return fmt.Sprintf("tool_call:%s:%s:%s", item.ToolCall.ID, item.ToolCall.Name, string(item.ToolCall.Input))
	case RunItemToolOutput:
		if item.ToolOutput == nil {
			return ""
		}
		return fmt.Sprintf("tool_output:%s:%t:%s", item.ToolOutput.CallID, item.ToolOutput.IsError, item.ToolOutput.Content)
	case RunItemHandoffCall:
		if item.HandoffCall == nil {
			return ""
		}
		return fmt.Sprintf("handoff_call:%s:%s", item.HandoffCall.FromAgent, item.HandoffCall.ToAgent)
	case RunItemHandoffOutput:
		if item.HandoffOutput == nil {
			return ""
		}
		return fmt.Sprintf("handoff_output:%s:%s", item.HandoffOutput.FromAgent, item.HandoffOutput.ToAgent)
	case RunItemToolApproval:
		if item.ToolApproval == nil {
			return ""
		}
		return fmt.Sprintf("tool_approval:%s:%s:%t:%s", item.ToolApproval.CallID, item.ToolApproval.ToolName, item.ToolApproval.Approved, string(item.ToolApproval.Input))
	case RunItemCompaction:
		if item.Compaction == nil {
			return ""
		}
		return fmt.Sprintf("compaction:%s:%s", item.Compaction.ID, item.Compaction.EncryptedContent)
	case RunItemReasoning:
		if item.Reasoning == nil {
			return ""
		}
		return fmt.Sprintf("reasoning:%s:%s:%s:%s", item.Reasoning.ID, item.Reasoning.Text, item.Reasoning.EncryptedContent, item.Reasoning.RedactedData)
	default:
		return ""
	}
}

func dedupeCompactionCarryForwardSections(sections []string) []string {
	seen := map[string]struct{}{}
	out := make([]string, 0, len(sections))
	for _, section := range sections {
		section = strings.TrimSpace(section)
		if section == "" {
			continue
		}
		if _, ok := seen[section]; ok {
			continue
		}
		seen[section] = struct{}{}
		out = append(out, section)
	}
	return out
}

func pruneBeforeLatestProviderCompaction(items []RunItem) ([]RunItem, bool) {
	latest := -1
	for i, item := range items {
		if item.Type == RunItemCompaction && item.Compaction != nil && strings.TrimSpace(item.Compaction.EncryptedContent) != "" {
			latest = i
		}
	}
	if latest < 0 {
		return items, false
	}
	if latest == 0 {
		return items, true
	}
	out := append([]RunItem(nil), items[latest:]...)
	return out, true
}

func generationFailureKind(err error, advice *ModelRetryAdvice) string {
	if advice != nil {
		if reason := strings.TrimSpace(advice.Reason); reason != "" {
			return reason
		}
	}
	if isContextLengthExceededError(err) {
		return "context_length_exceeded"
	}
	switch {
	case errors.Is(err, context.Canceled):
		return "context_canceled"
	case errors.Is(err, context.DeadlineExceeded):
		return "deadline_exceeded"
	}
	var modelBehaviorErr *ModelBehaviorError
	if errors.As(err, &modelBehaviorErr) {
		return "model_behavior"
	}
	var agentErr *AgentError
	if errors.As(err, &agentErr) && agentErr.Cause != nil {
		return generationFailureKind(agentErr.Cause, nil)
	}
	return "error"
}

func isContextLengthExceededError(err error) bool {
	if err == nil {
		return false
	}
	msg := strings.ToLower(err.Error())
	return strings.Contains(msg, "context_length_exceeded") ||
		strings.Contains(msg, "exceeds the context window")
}

// isEncryptedContentError detects provider rejections of encrypted context
// items (compaction blobs, encrypted reasoning). OpenAI reports these as 400s
// with code "invalid_encrypted_content" and messages like "The encrypted
// content ... could not be verified. Reason: Encrypted content could not be
// decrypted or parsed."
func isEncryptedContentError(err error) bool {
	if err == nil {
		return false
	}
	msg := strings.ToLower(err.Error())
	if strings.Contains(msg, "invalid_encrypted_content") {
		return true
	}
	if !strings.Contains(msg, "encrypted content") && !strings.Contains(msg, "encrypted_content") {
		return false
	}
	return strings.Contains(msg, "could not be decrypted") ||
		strings.Contains(msg, "could not be verified") ||
		strings.Contains(msg, "could not be parsed") ||
		strings.Contains(msg, "decrypted or parsed") ||
		// Oversized blob rejections (server caps encrypted_content at 10MiB);
		// the request can never succeed while the blob stays in the input.
		strings.Contains(msg, "string too long")
}

// stripUndecryptableEncryptedItems removes provider-encrypted payloads the
// active model rejected: compaction items with encrypted blobs are dropped
// outright, and reasoning items lose their encrypted content (the whole item
// is dropped when nothing readable remains). Items are cloned before
// modification — history slices share the underlying data pointers.
func stripUndecryptableEncryptedItems(items []RunItem) ([]RunItem, int) {
	out := make([]RunItem, 0, len(items))
	removed := 0
	for _, item := range items {
		switch item.Type {
		case RunItemCompaction:
			if item.Compaction != nil && strings.TrimSpace(item.Compaction.EncryptedContent) != "" {
				removed++
				continue
			}
		case RunItemReasoning:
			if item.Reasoning != nil && strings.TrimSpace(item.Reasoning.EncryptedContent) != "" {
				removed++
				if strings.TrimSpace(item.Reasoning.Text) == "" && strings.TrimSpace(item.Reasoning.RedactedData) == "" {
					continue
				}
				reasoning := *item.Reasoning
				reasoning.EncryptedContent = ""
				item.Reasoning = &reasoning
			}
		}
		out = append(out, item)
	}
	return out, removed
}

// fireAgentHook safely calls an AgentHooks callback if hooks is non-nil.
// A panic in user-supplied hooks is recovered so it cannot crash the host.
func fireAgentHook(hooks AgentHooks, fn func(AgentHooks)) {
	if hooks == nil {
		return
	}
	defer func() {
		if rec := recover(); rec != nil {
			log.Printf("[runner] WARN: agent hook panicked (recovered): %v", rec)
		}
	}()
	fn(hooks)
}

// runInputGuardrails runs all input guardrails and returns results.
func runInputGuardrails(ctx *RunContext, agent *Agent, input []RunItem) ([]InputGuardrailResult, error) {
	results := make([]InputGuardrailResult, 0, len(agent.InputGuardrails))
	for _, g := range agent.InputGuardrails {
		gr, err := callInputGuardrail(g, ctx, agent, input)
		if err != nil {
			return nil, &AgentError{Message: fmt.Sprintf("input guardrail %q failed", g.Name), Cause: err}
		}
		if gr == nil {
			gr = &GuardrailResult{}
		}
		results = append(results, InputGuardrailResult{
			GuardrailName:     g.Name,
			Output:            gr.Output,
			TripwireTriggered: gr.TripwireTriggered,
		})
		if gr.TripwireTriggered {
			return results, &InputGuardrailTripwireTriggered{GuardrailName: g.Name, Result: *gr}
		}
	}
	return results, nil
}

// callInputGuardrail invokes a guardrail Fn with panic recovery so a buggy
// host guardrail cannot bring the runner down — the panic is converted into
// an error and the run aborts cleanly.
func callInputGuardrail(g InputGuardrail, ctx *RunContext, agent *Agent, input []RunItem) (gr *GuardrailResult, err error) {
	defer func() {
		if rec := recover(); rec != nil {
			err = fmt.Errorf("panic: %v", rec)
		}
	}()
	return g.Fn(ctx, agent, input)
}

// runOutputGuardrails runs all output guardrails and returns results.
func runOutputGuardrails(ctx *RunContext, agent *Agent, output any) ([]OutputGuardrailResult, error) {
	results := make([]OutputGuardrailResult, 0, len(agent.OutputGuardrails))
	for _, g := range agent.OutputGuardrails {
