	if err != nil {
		t.Fatal(err)
	}
	if result.FinalText() != "parent done" {
		t.Fatalf("FinalText() = %q, want parent done", result.FinalText())
	}
	mu.Lock()
	defer mu.Unlock()
	if seen["child_tool"] == 0 {
		t.Fatalf("tool input guardrail did not run for nested child tool call; seen=%v", seen)
	}
}

