		commitment.interrupt()
		close(listenerDone)
	}
	resp := &ModelResponse{Items: []RunItem{{Type: RunItemMessage, Message: &MessageOutput{Text: "stale"}}}}

	gotResp, err := settleImmediateInput(stop, &commitment, resp, nil)
