func TestRunnerToolInputGuardrailTripwireReturnsToolErrorAndContinues(t *testing.T) {
	model := &mockModel{
		responses: []*ModelResponse{
			{
				Items: []RunItem{
					{Type: RunItemToolCall, ToolCall: &ToolCallData{
