func TestPartialProgressTail(t *testing.T) {
	if got := partialProgressTail(nil); got != "" {
		t.Errorf("nil result should give empty tail, got %q", got)
	}
	result := &RunResult{NewItems: []RunItem{
		{Type: RunItemMessage, Message: &MessageOutput{Text: "first finding"}},
		{Type: RunItemToolCall, ToolCall: &ToolCallData{ID: "c1", Name: "echo"}},
		{Type: RunItemToolOutput, ToolOutput: &ToolOutputData{CallID: "c1", Content: "ok"}},
		{Type: RunItemMessage, Message: &MessageOutput{Text: "latest finding: root cause in loop.go"}},
		{Type: RunItemMessage, Message: &MessageOutput{Text: "[SYSTEM] internal notice"}},
	}}
	if got := partialProgressTail(result); got != "latest finding: root cause in loop.go" {
		t.Errorf("expected last non-system assistant text, got %q", got)
	}
	empty := &RunResult{NewItems: []RunItem{
		{Type: RunItemToolCall, ToolCall: &ToolCallData{ID: "c1", Name: "echo"}},
	}}
	if got := partialProgressTail(empty); got != "" {
		t.Errorf("no assistant text should give empty tail, got %q", got)
	}
}

// A child that fails on a model/API error (not just budget exhaustion) hands
// back its accumulated run state; the outcome must surface the findings
// gathered before the failure so the parent never receives a bare error for
// minutes of completed work.
func TestRunSubAgentOnceModelFailureSurfacesPartialProgress(t *testing.T) {
	echoTool := &FunctionTool{
		ToolName:        "echo",
		ToolDescription: "echoes input",
		Schema:          json.RawMessage(`{"type":"object"}`),
		Fn: func(_ context.Context, _ json.RawMessage) (string, error) {
			return "ok", nil
		},
	}
	model := &mockModel{
		responses: []*ModelResponse{
			{Items: []RunItem{
				{Type: RunItemMessage, Message: &MessageOutput{Text: "researched 12 sources; key insight: durable task records"}},
				{Type: RunItemToolCall, ToolCall: &ToolCallData{ID: "c1", Name: "echo", Input: json.RawMessage(`"x"`)}},
			}},
		},
		errors: []error{nil, errors.New("model call exceeded per-attempt timeout")},
	}
	outcome := runSubAgentOnce(context.Background(), subAgentRunSpec{
		Runner:    NewRunnerWithModel(model),
		Agent:     &Agent{Name: "researcher", Tools: []Tool{echoTool}},
		Message:   "research the beat",
		TaskID:    "task_partial",
		RunConfig: RunConfig{MaxTurns: 5},
	})
	if outcome.Status != subAgentStatusFailed {
		t.Fatalf("outcome.Status = %q, want failed", outcome.Status)
	}
	if !strings.Contains(outcome.ErrMsg, "Partial progress before the run ended:") ||
		!strings.Contains(outcome.ErrMsg, "researched 12 sources") {
		t.Fatalf("ErrMsg lost the partial findings: %q", outcome.ErrMsg)
	}
}

package agent

import (
	"strings"
	"sync"
	"time"
)

const (
	// thinkingDeltaFlushInterval bounds how often coalesced reasoning chunks
	// are emitted. 500ms matches the platform's live-watch poll cadence, so a
	// finer granularity would be invisible while inflating the event log.
	thinkingDeltaFlushInterval = 500 * time.Millisecond
	// thinkingDeltaFlushBytes caps how much reasoning text is buffered before
	// an early flush, bounding memory and per-event payload size.
	thinkingDeltaFlushBytes = 4096
)

// thinkingDeltaEmitter coalesces streamed model reasoning text into periodic
// assistant_thinking_delta events so live consumers can render reasoning as
// it happens without one event per token. ToolUseID carries the llm attempt
// id, linking the chunk stream to its llm_attempt events and to the final
// assistant_thinking event that supersedes it (same id, complete text).
type thinkingDeltaEmitter struct {
	es        *EventStream
	attemptID string
	agentName string
	now       func() time.Time // test seam

	mu        sync.Mutex
	buf       strings.Builder
	lastFlush time.Time
}

func newThinkingDeltaEmitter(es *EventStream, attemptID, agentName string) *thinkingDeltaEmitter {
	return &thinkingDeltaEmitter{es: es, attemptID: attemptID, agentName: agentName, now: time.Now}
}

// Chunk buffers a reasoning text chunk, flushing when the flush interval has
// elapsed or the buffer is large. The first chunk flushes immediately (zero
// lastFlush) so the UI flips to live reasoning without waiting a full period.
// Race-free under concurrent use, but flush emission order is only guaranteed
// when callers serialize; transports deliver chunks sequentially.
func (e *thinkingDeltaEmitter) Chunk(text string) {
	if text == "" {
		return
	}
	e.mu.Lock()
	e.buf.WriteString(text)
	var flushText string
	if e.now().Sub(e.lastFlush) >= thinkingDeltaFlushInterval || e.buf.Len() >= thinkingDeltaFlushBytes {
		flushText = e.buf.String()
		e.buf.Reset()
		e.lastFlush = e.now()
	}
	e.mu.Unlock()
	if flushText != "" {
		e.es.EmitThinkingDelta(flushText, e.agentName, e.attemptID)
	}
}

// Flush emits any buffered residue. Called once after the model call returns
// so the tail of the reasoning stream is not lost to the flush interval.
func (e *thinkingDeltaEmitter) Flush() {
	e.mu.Lock()
	flushText := e.buf.String()
	e.buf.Reset()
	e.lastFlush = e.now()
	e.mu.Unlock()
	if flushText != "" {
		e.es.EmitThinkingDelta(flushText, e.agentName, e.attemptID)
	}
}

package agent

import (
	"bytes"
	"context"
	"encoding/json"
	"strings"
	"testing"
	"time"

	"github.com/gratefulagents/sdk/internal/modeldelta"
)

func decodeContentEvents(t *testing.T, buf *bytes.Buffer) []ContentEvent {
	t.Helper()
	var events []ContentEvent
	for _, line := range strings.Split(strings.TrimSpace(buf.String()), "\n") {
		if line == "" {
			continue
		}
		var ev ContentEvent
		if err := json.Unmarshal([]byte(line), &ev); err != nil {
			t.Fatalf("unmarshal event line %q: %v", line, err)
		}
		events = append(events, ev)
	}
	return events
}

func eventsOfType(events []ContentEvent, typ string) []ContentEvent {
	var out []ContentEvent
	for _, ev := range events {
		if ev.Type == typ {
			out = append(out, ev)
		}
	}
	return out
}

func TestThinkingDeltaEmitterCoalesces(t *testing.T) {
	var buf bytes.Buffer
	es := NewEventStream(&buf)
	now := time.Unix(1000, 0)
	e := newThinkingDeltaEmitter(es, "attempt-1", "worker")
	e.now = func() time.Time { return now }

	// First chunk flushes immediately (zero lastFlush) so the UI flips to
	// live reasoning without waiting a full interval.
	e.Chunk("first ")
	// Within the flush interval: buffered, not emitted.
	now = now.Add(100 * time.Millisecond)
	e.Chunk("second ")
	now = now.Add(100 * time.Millisecond)
	e.Chunk("third ")
	// Interval elapsed: buffered chunks flush together.
	now = now.Add(thinkingDeltaFlushInterval)
	e.Chunk("fourth ")
	// Residue after the model call returns.
	e.Chunk("tail")
	e.Flush()
	// Empty flush emits nothing.
	e.Flush()
	// Empty chunks are ignored.
	e.Chunk("")

	deltas := eventsOfType(decodeContentEvents(t, &buf), "assistant_thinking_delta")
	if len(deltas) != 3 {
		t.Fatalf("delta events = %d, want 3", len(deltas))
	}
	wantMessages := []string{"first ", "second third fourth ", "tail"}
	for i, want := range wantMessages {
		if deltas[i].Message != want {
			t.Errorf("delta[%d].Message = %q, want %q", i, deltas[i].Message, want)
		}
		if deltas[i].ToolUseID != "attempt-1" {
			t.Errorf("delta[%d].ToolUseID = %q, want attempt-1", i, deltas[i].ToolUseID)
		}
		if deltas[i].AgentName != "worker" {
			t.Errorf("delta[%d].AgentName = %q, want worker", i, deltas[i].AgentName)
		}
	}
}

func TestThinkingDeltaEmitterFlushesOnSize(t *testing.T) {
	var buf bytes.Buffer
	es := NewEventStream(&buf)
	now := time.Unix(1000, 0)
	e := newThinkingDeltaEmitter(es, "attempt-1", "worker")
	e.now = func() time.Time { return now }

	e.Chunk("warmup") // immediate first flush, resets the timer
	big := strings.Repeat("x", thinkingDeltaFlushBytes)
	e.Chunk(big) // exceeds the size cap inside the interval

	deltas := eventsOfType(decodeContentEvents(t, &buf), "assistant_thinking_delta")
	if len(deltas) != 2 {
		t.Fatalf("delta events = %d, want 2", len(deltas))
	}
	if deltas[1].Message != big {
		t.Errorf("size-triggered flush lost text: got %d bytes, want %d", len(deltas[1].Message), len(big))
	}
}

// reasoningSinkModel simulates a transport that streams reasoning internally
// during a blocking GetResponse, feeding any installed context sink.
type reasoningSinkModel struct {
	*mockModel
	chunks []string
}

func (m *reasoningSinkModel) GetResponse(ctx context.Context, req ModelRequest) (*ModelResponse, error) {
	if sink := modeldelta.ReasoningSinkFromContext(ctx); sink != nil {
		for _, c := range m.chunks {
			sink(c)
		}
	}
	return m.mockModel.GetResponse(ctx, req)
}

func (m *reasoningSinkModel) StreamResponse(ctx context.Context, req ModelRequest) (*ModelStream, error) {
	resp, err := m.mockModel.GetResponse(ctx, req)
	if err != nil {
		return nil, err
	}
	events := make(chan ModelStreamEvent, len(m.chunks)+1)
	done := make(chan *ModelResponse, 1)
	for _, chunk := range m.chunks {
		events <- ModelStreamEvent{Type: ModelStreamReasoningDelta, Delta: chunk}
	}
	events <- ModelStreamEvent{Type: ModelStreamComplete, Response: resp}
	close(events)
	done <- resp
	return NewModelStream(events, done), nil
}

func TestRunnerStreamsThinkingDeltasToEventStream(t *testing.T) {
	model := &reasoningSinkModel{
		mockModel: &mockModel{
			responses: []*ModelResponse{{
				Items: []RunItem{
					{Type: RunItemReasoning, Reasoning: &ReasoningData{Text: "let me think about this"}},
					{Type: RunItemMessage, Message: &MessageOutput{Text: "done"}},
				},
			}},
		},
		chunks: []string{"let me think", " about this"},
	}
	runner := NewRunnerWithModel(model)
	var buf bytes.Buffer
	hooks := NewPlatformHooks(NewProgressTracker(), NewEventStream(&buf))

	result, err := runner.Run(context.Background(), &Agent{Name: "worker"}, nil, RunConfig{
		Hooks:    hooks,
		MaxTurns: 2,
	})
	if err != nil {
		t.Fatal(err)
	}
	if result.FinalText() != "done" {
		t.Fatalf("FinalText() = %q, want done", result.FinalText())
	}

	events := decodeContentEvents(t, &buf)
	attempts := eventsOfType(events, "llm_attempt")
	if len(attempts) == 0 || attempts[0].ToolUseID == "" {
		t.Fatalf("expected llm_attempt events with a ToolUseID, got %+v", attempts)
	}
	attemptID := attempts[0].ToolUseID

	deltas := eventsOfType(events, "assistant_thinking_delta")
	if len(deltas) == 0 {
		t.Fatal("expected assistant_thinking_delta events, got none")
	}
	var streamed strings.Builder
	for _, d := range deltas {
		streamed.WriteString(d.Message)
		if d.ToolUseID != attemptID {
			t.Errorf("delta ToolUseID = %q, want llm attempt id %q", d.ToolUseID, attemptID)
		}
		if d.AgentName != "worker" {
			t.Errorf("delta AgentName = %q, want worker", d.AgentName)
		}
	}
	if streamed.String() != "let me think about this" {
		t.Errorf("streamed text = %q, want full reasoning", streamed.String())
	}

	finals := eventsOfType(events, "assistant_thinking")
	if len(finals) != 1 {
		t.Fatalf("assistant_thinking events = %d, want 1", len(finals))
	}
	if finals[0].Message != "let me think about this" {
		t.Errorf("final Message = %q", finals[0].Message)
	}
	if finals[0].ToolUseID != attemptID {
		t.Errorf("final ToolUseID = %q, want llm attempt id %q so consumers can supersede the delta stream", finals[0].ToolUseID, attemptID)
	}
}

func TestRunStreamedDoesNotEmitThinkingDeltaEvents(t *testing.T) {
	// The streamed-run path surfaces reasoning through its own event channel;
	// the JSONL event stream must not receive duplicate delta events there.
	model := &reasoningSinkModel{
		mockModel: &mockModel{
			responses: []*ModelResponse{{
				Items: []RunItem{{Type: RunItemMessage, Message: &MessageOutput{Text: "done"}}},
			}},
		},
		chunks: []string{"hidden reasoning"},
	}
	runner := NewRunnerWithModel(model)
	var buf bytes.Buffer
	hooks := NewPlatformHooks(NewProgressTracker(), NewEventStream(&buf))

	streamed := runner.RunStreamed(context.Background(), &Agent{Name: "worker"}, nil, RunConfig{
		Hooks:    hooks,
		MaxTurns: 2,
	})
	for range streamed.Events {
	}
	if err := streamed.Err(); err != nil {
		t.Fatal(err)
	}
	if deltas := eventsOfType(decodeContentEvents(t, &buf), "assistant_thinking_delta"); len(deltas) != 0 {
		t.Fatalf("streamed run emitted %d assistant_thinking_delta events, want 0", len(deltas))
	}
}

package agent

import (
	"context"
	"encoding/json"
)

// Tool is the interface for all tools available to agents.
type Tool interface {
	Name() string
	Description() string
	InputSchema() json.RawMessage
	Execute(ctx context.Context, input json.RawMessage, workDir string) (ToolResult, error)
	IsReadOnly() bool
	IsEnabled(ctx *RunContext) bool
	NeedsApproval() bool
	TimeoutSeconds() int
}

// ToolTimeoutResultPreserver is implemented by context-aware tools that turn
// their own deadline into a complete, model-safe result. The runner normally
// replaces any result produced at the tool-policy deadline with
// ToolTimeoutError; this opt-in lets managed wait tools return a non-fatal
// progress snapshot instead. The result is preserved only when Execute returns
// no error and a non-error ToolResult.
type ToolTimeoutResultPreserver interface {
	PreserveResultOnTimeout() bool
}

// ToolAccessAdapter lets a host application provide a safer tool
// implementation for a specific access level.
type ToolAccessAdapter interface {
	ToolForAccess(level ToolAccessLevel) Tool
}

// GitRemoteWriteTool identifies tools that can mutate a Git remote. Registries
// and runtime builders use this capability to remove such tools when the host
// disables Git remote writes.
type GitRemoteWriteTool interface {
	WritesGitRemote() bool
}

// MutatingToolEnabled reports whether a mutating tool may be considered
// enabled for the run's access context. The runner's exact-name filter remains
// the authorization boundary; this helper lets access-aware IsEnabled methods
// recognize the same host-trusted exception instead of rejecting it early.
func MutatingToolEnabled(ctx *RunContext, toolName string) bool {
	if ctx == nil || NormalizeToolAccessLevel(ctx.ToolAccessLevel) != ToolAccessLevelReadOnly {
		return true
	}
	for _, allowed := range ctx.Config.AllowedMutatingTools {
		if allowed != "" && allowed == toolName {
			return true
		}
	}
	return false
}

// ToolResult is the outcome of a tool execution.
type ToolResult struct {
	Content     string
	Images      []ImageAttachment
	IsError     bool
	ShouldPause bool // When true, the runner breaks so the outer loop can handle the event.
}

// FunctionTool is a convenience tool built from a plain function.
type FunctionTool struct {
	ToolName        string
	ToolDescription string
	Schema          json.RawMessage
	Fn              func(ctx context.Context, input json.RawMessage) (string, error)
	ReadOnly        bool
	Approval        bool
	Timeout         int
}

func (t *FunctionTool) Name() string                 { return t.ToolName }
func (t *FunctionTool) Description() string          { return t.ToolDescription }
func (t *FunctionTool) InputSchema() json.RawMessage { return t.Schema }
func (t *FunctionTool) IsReadOnly() bool             { return t.ReadOnly }
func (t *FunctionTool) IsEnabled(ctx *RunContext) bool {
	return t.ReadOnly || MutatingToolEnabled(ctx, t.Name())
}
func (t *FunctionTool) NeedsApproval() bool { return t.Approval }
func (t *FunctionTool) TimeoutSeconds() int { return t.Timeout }

func (t *FunctionTool) Execute(ctx context.Context, input json.RawMessage, _ string) (ToolResult, error) {
	result, err := t.Fn(ctx, input)
	if err != nil {
		return ToolResult{Content: err.Error(), IsError: true}, nil
	}
	return ToolResult{Content: result}, nil
}

// policyToolWrapper adds host-supplied approval and timeout behavior to a tool.
type policyToolWrapper struct {
	inner    Tool
	approval bool
	timeout  int
}

// WrapWithPolicy wraps a tool with approval and timeout settings.
// If neither policy applies, it returns the original tool unchanged.
//
// Approval semantics: when approval=true, NeedsApproval() returns true even
// for tools whose own implementation hardcodes NeedsApproval()=false (notably
// the signal tools in pkg/agentsdk/tools/signal/*: finish, plan, present_plan,
// question). The wrapper's approval flag is therefore an *override*
// — hosts that opt these tools into approval gating via tool policy will see
// approval prompts despite the inner tool's default. The reverse is not true:
// approval=false leaves the inner tool's NeedsApproval() decision intact.
func WrapWithPolicy(t Tool, approval bool, timeout int) Tool {
	if !approval && timeout == 0 {
		return t
	}
	return &policyToolWrapper{inner: t, approval: approval, timeout: timeout}
}

func (w *policyToolWrapper) Name() string                 { return w.inner.Name() }
func (w *policyToolWrapper) Description() string          { return w.inner.Description() }
func (w *policyToolWrapper) InputSchema() json.RawMessage { return w.inner.InputSchema() }
func (w *policyToolWrapper) Execute(ctx context.Context, input json.RawMessage, workDir string) (ToolResult, error) {
	return w.inner.Execute(ctx, input, workDir)
}
func (w *policyToolWrapper) IsReadOnly() bool               { return w.inner.IsReadOnly() }
func (w *policyToolWrapper) IsEnabled(ctx *RunContext) bool { return w.inner.IsEnabled(ctx) }

func (w *policyToolWrapper) NeedsApproval() bool {
	if w.approval {
		return true
	}
	return w.inner.NeedsApproval()
}

func (w *policyToolWrapper) TimeoutSeconds() int {
	if w.timeout > 0 {
		return w.timeout
	}
	return w.inner.TimeoutSeconds()
}

func (w *policyToolWrapper) PreserveResultOnTimeout() bool {
	preserver, ok := w.inner.(ToolTimeoutResultPreserver)
	return ok && preserver.PreserveResultOnTimeout()
}

// ToolForAccess delegates to the inner tool's ToolAccessAdapter (if any) and
// re-wraps the adapted tool with the same approval/timeout policy. Without
// this delegation, hosts that supply a safer tool implementation per access
// level (e.g. a read-only Bash) would be silently bypassed once the policy
// wrapper was applied. See finding M10.
func (w *policyToolWrapper) ToolForAccess(level ToolAccessLevel) Tool {
	adapter, ok := w.inner.(ToolAccessAdapter)
	if !ok {
		return w
	}
	adapted := adapter.ToolForAccess(level)
	if adapted == nil {
		return nil
	}
	return &policyToolWrapper{inner: adapted, approval: w.approval, timeout: w.timeout}
}

