	}
	cfg := RunConfig{WorkDir: outside, ToolOutputDir: link}
	cleanup := prepareToolOutputSpill(&cfg)
	defer cleanup()
	if cfg.toolOutputSpillDir != "" {
		t.Fatalf("spill dir = %q, want disabled for symlink into workspace", cfg.toolOutputSpillDir)
	}
}

