		{
			name:     "unknown fable variant falls back to fable family, not sonnet",
			model:    "claude-fable-latest",
			usage:    Usage{InputTokens: 1_000_000},
			wantCost: 10.0,
		},
		{
			name:  "sonnet 5 uses the permanent $2/$10 tier",
			model: "claude-sonnet-5",
			usage: Usage{
				InputTokens:              1_000_000,
				OutputTokens:             1_000_000,
				CacheReadInputTokens:     1_000_000,
				CacheCreationInputTokens: 1_000_000,
			},
			// 2 + 10 + 0.20 + 2.50
			wantCost: 14.70,
		},
		{
			name:     "dated sonnet 5 does not fall back to sonnet 4.6 rates",
			model:    "anthropic/claude-sonnet-5-20260815",
			usage:    Usage{InputTokens: 1_000_000},
			wantCost: 2.0,
		},
		{
			name:     "sonnet 4.5 still resolves via the sonnet 4.6 family rate",
			model:    "claude-sonnet-4-5-20250929",
			usage:    Usage{InputTokens: 1_000_000},
			wantCost: 3.0,
		},
		{
			name:  "mythos 5.1 matches fable 5.1 pricing",
			model: "claude-mythos-5-1",
			usage: Usage{InputTokens: 1_000_000, CacheReadInputTokens: 1_000_000},
			// 10 + 0.25
			wantCost: 10.25,
		},
		{
			name:  "mythos 5 keeps the 0.1x cache-read rate",
			model: "claude-mythos-5",
			usage: Usage{InputTokens: 1_000_000, CacheReadInputTokens: 1_000_000},
			// 10 + 1.0
			wantCost: 11.0,
		},
		{
			name:     "unknown mythos variant falls back to mythos family",
			model:    "claude-mythos-latest",
			usage:    Usage{OutputTokens: 1_000_000},
			wantCost: 50.0,
		},
		{
			name:     "opus 5 resolves via the opus $5/$25 family rate",
			model:    "claude-opus-5",
			usage:    Usage{InputTokens: 1_000_000, OutputTokens: 1_000_000},
			wantCost: 30.0,
		},
		{
			name:     "opus 4.1 uses the legacy $15/$75 tier",
			model:    "claude-opus-4-1-20250805",
			usage:    Usage{InputTokens: 1_000_000, OutputTokens: 1_000_000},
			wantCost: 90.0,
		},
		{
			name:  "opus 4 uses the legacy $15/$75 tier including cache rates",
			model: "claude-opus-4-20250514",
			usage: Usage{
				CacheReadInputTokens:     1_000_000,
				CacheCreationInputTokens: 1_000_000,
			},
			// 1.50 + 18.75
			wantCost: 20.25,
		},
		{
			name:     "haiku 3.5 legacy version-first id",
			model:    "claude-3-5-haiku-20241022",
			usage:    Usage{InputTokens: 1_000_000, OutputTokens: 1_000_000},
			wantCost: 4.80,
		},
		{
			name:     "haiku 3.5 canonical id",
			model:    "claude-haiku-3-5",
			usage:    Usage{InputTokens: 1_000_000, OutputTokens: 1_000_000},
			wantCost: 4.80,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := CalculateCost(tt.model, tt.usage)
			if math.Abs(got-tt.wantCost) > 1e-9 {
				t.Errorf("CalculateCost(%s, %+v) = %f, want %f", tt.model, tt.usage, got, tt.wantCost)
			}
		})
	}
}

package anthropic

import (
	"encoding/json"
	"strings"

	sdk "github.com/anthropics/anthropic-sdk-go"
	"github.com/anthropics/anthropic-sdk-go/option"
	"github.com/anthropics/anthropic-sdk-go/packages/param"
)

// CreateMessageRequest for POST /v1/messages.
type CreateMessageRequest struct {
	Model         string           `json:"model"`
	MaxTokens     int              `json:"max_tokens"`
	Messages      []Message        `json:"messages"`
	System        []SystemBlock    `json:"system,omitempty"`
	Tools         []ToolDefinition `json:"tools,omitempty"`
	Stream        bool             `json:"stream"`
	Metadata      *Metadata        `json:"metadata,omitempty"`
	Thinking      *ThinkingConfig  `json:"thinking,omitempty"`
	TextVerbosity string           `json:"text_verbosity,omitempty"`
	ToolChoice    *ToolChoice      `json:"tool_choice,omitempty"`
	Betas         []string         `json:"-"` // Converted to SDK beta headers
	OutputSchema  *OutputSchema    `json:"-"`

	// OutputEffort maps to the Messages API output_config.effort field
	// ("low", "medium", "high", "xhigh", "max"). Used with adaptive thinking on
	// gateways (e.g. GitHub Copilot's /v1/messages shim) that control reasoning
	// via effort rather than a fixed token budget. Empty leaves it unset.
	OutputEffort string `json:"-"`

	// OpenRouter chat-completions shim only: reasoning effort label
	// ("none", "minimal", "low", "medium", "high", "xhigh", "max"). "none" disables
	// reasoning entirely. Empty leaves the provider/model default. Carried into
	// the chat body's "reasoning" field; ignored on the native Anthropic path.
	ReasoningEffort string `json:"-"`

	// OpenAI Responses shim only.
	PromptCacheKey      string `json:"-"`
	CompactionThreshold int    `json:"-"`
}

// Metadata for the API request.
type Metadata struct {
	UserID string `json:"user_id,omitempty"`
}

// OutputSchema carries host SDK structured-output settings into providers that
// support native response-format enforcement.
type OutputSchema struct {
	Name   string          `json:"name"`
	Schema json.RawMessage `json:"schema"`
	Strict bool            `json:"strict"`
}

// ThinkingConfig enables extended thinking.
type ThinkingConfig struct {
	Type         string `json:"type"`                    // "enabled" | "adaptive" | "disabled"
	BudgetTokens int    `json:"budget_tokens,omitempty"` // for "enabled"
	Display      string `json:"display,omitempty"`       // for "adaptive": "summarized" | "omitted"
}

// OutputEffort values map to the Messages API output_config.effort field.
// The supported subset is model-specific: some Claude models (e.g.
// claude-sonnet-4.6) accept only [low medium high max] and reject "xhigh".
// Host reasoning therefore maps its top tier to "max" rather than "xhigh"; see
// mapReasoningEffortToAnthropic.
const (
	OutputEffortLow    = "low"
	OutputEffortMedium = "medium"
	OutputEffortHigh   = "high"
	OutputEffortXHigh  = "xhigh"
	OutputEffortMax    = "max"
)

// ToolChoice controls tool selection behavior.
type ToolChoice struct {
	Type string `json:"type"`           // "auto", "any", "tool"
	Name string `json:"name,omitempty"` // only for type "tool"
}

// toSDKParams converts our request to SDK BetaMessageNewParams + request options for betas.
func toSDKParams(r *CreateMessageRequest) (sdk.BetaMessageNewParams, []option.RequestOption) {
	params := sdk.BetaMessageNewParams{
		Model:     sdk.Model(r.Model),
		MaxTokens: int64(r.MaxTokens),
	}

	// Convert messages.
	for _, msg := range r.Messages {
		sdkMsg := sdk.BetaMessageParam{
			Role: sdk.BetaMessageParamRole(msg.Role),
		}
		for _, block := range msg.Content {
			sdkMsg.Content = append(sdkMsg.Content, toSDKContentBlock(block))
		}
		params.Messages = append(params.Messages, sdkMsg)
	}

	// Convert system prompt.
	for _, sys := range r.System {
		tb := sdk.BetaTextBlockParam{
			Text: sys.Text,
		}
		if sys.CacheControl != nil {
			tb.CacheControl = sdk.BetaCacheControlEphemeralParam{
				Type: "ephemeral",
			}
		}
		params.System = append(params.System, tb)
	}

	// Convert tools.
	for _, tool := range r.Tools {
		var props map[string]interface{}
		_ = json.Unmarshal(tool.InputSchema, &props)

		var required []string
		if rawRequired, ok := props["required"].([]interface{}); ok {
			for _, item := range rawRequired {
				if name, ok := item.(string); ok {
					required = append(required, name)
				}
			}
		}

		// A tool schema with no properties (e.g. `{"type":"object"}`) must
		// still send input_schema: BetaToolParam tags the field omitzero, so a
		// zero-value BetaToolInputSchemaParam would drop input_schema entirely
		// and the API rejects the request with
		// "tools.N.custom.input_schema: Field required".
		properties := props["properties"]
		if properties == nil {
			properties = map[string]interface{}{}
		}

		params.Tools = append(params.Tools, sdk.BetaToolUnionParam{
			OfTool: &sdk.BetaToolParam{
				Name:        tool.Name,
				Description: sdk.String(tool.Description),
				InputSchema: sdk.BetaToolInputSchemaParam{
					Properties: properties,
					Required:   required,
				},
				CacheControl: toolCacheControl(tool.CacheControl),
			},
		})
	}

	// Convert tool choice.
	if r.ToolChoice != nil {
		switch r.ToolChoice.Type {
		case "auto":
			params.ToolChoice = sdk.BetaToolChoiceUnionParam{OfAuto: &sdk.BetaToolChoiceAutoParam{}}
		case "any":
			params.ToolChoice = sdk.BetaToolChoiceUnionParam{OfAny: &sdk.BetaToolChoiceAnyParam{}}
		case "tool":
			params.ToolChoice = sdk.BetaToolChoiceParamOfTool(r.ToolChoice.Name)
		case "none":
			params.ToolChoice = sdk.BetaToolChoiceUnionParam{OfNone: &sdk.BetaToolChoiceNoneParam{}}
		}
	}

	// Convert request metadata.
	if r.Metadata != nil && r.Metadata.UserID != "" {
		params.Metadata = sdk.BetaMetadataParam{UserID: sdk.String(r.Metadata.UserID)}
	}

	// Convert thinking config.
	if r.Thinking != nil {
		switch r.Thinking.Type {
		case "enabled":
			params.Thinking = sdk.BetaThinkingConfigParamUnion{
				OfEnabled: &sdk.BetaThinkingConfigEnabledParam{
					BudgetTokens: int64(r.Thinking.BudgetTokens),
				},
			}
		case "adaptive":
			adaptive := &sdk.BetaThinkingConfigAdaptiveParam{}
			if r.Thinking.Display != "" {
				adaptive.Display = sdk.BetaThinkingConfigAdaptiveDisplay(r.Thinking.Display)
			}
			params.Thinking = sdk.BetaThinkingConfigParamUnion{OfAdaptive: adaptive}
		case "disabled":
			params.Thinking = sdk.BetaThinkingConfigParamUnion{
				OfDisabled: &sdk.BetaThinkingConfigDisabledParam{},
			}
		}
	}

	// Convert output effort (output_config.effort), used with adaptive thinking.
	if r.OutputEffort != "" {
		params.OutputConfig = sdk.BetaOutputConfigParam{
			Effort: sdk.BetaOutputConfigEffort(r.OutputEffort),
		}
	}

	// Convert structured-output schema to the native output_format field so the
	// API enforces schema-constrained JSON.
	if r.OutputSchema != nil && len(r.OutputSchema.Schema) > 0 {
		params.OutputFormat = sdk.BetaJSONOutputFormatParam{
			Schema: json.RawMessage(r.OutputSchema.Schema),
		}
	}

	// Convert betas to SDK AnthropicBeta values.
	for _, b := range r.Betas {
		params.Betas = append(params.Betas, sdk.AnthropicBeta(b))
	}

	return params, nil
}

// toolCacheControl converts an optional cache-control marker to the SDK param.
func toolCacheControl(cc *CacheControl) sdk.BetaCacheControlEphemeralParam {
	if cc == nil {
		return sdk.BetaCacheControlEphemeralParam{}
	}
	return sdk.BetaCacheControlEphemeralParam{Type: "ephemeral"}
}

// toSDKContentBlock converts our ContentBlock to SDK's BetaContentBlockParamUnion.
func toSDKContentBlock(block ContentBlock) sdk.BetaContentBlockParamUnion {
	switch block.Type {
	case "text":
		b := sdk.BetaTextBlockParam{
			Text: block.Text,
		}
		if block.CacheControl != nil {
			b.CacheControl = sdk.BetaCacheControlEphemeralParam{
				Type: "ephemeral",
			}
		}
		return sdk.BetaContentBlockParamUnion{OfText: &b}
	case "tool_use":
		var input interface{}
		if block.Input != nil {
			_ = json.Unmarshal(block.Input, &input)
		}
		return sdk.BetaContentBlockParamUnion{
			OfToolUse: &sdk.BetaToolUseBlockParam{
				ID:    block.ID,
				Name:  block.Name,
				Input: input,
			},
		}
	case "tool_result":
		result := &sdk.BetaToolResultBlockParam{
			ToolUseID: block.ToolUseID,
			IsError:   sdk.Bool(block.IsError),
		}
		if block.Content != "" {
			result.Content = []sdk.BetaToolResultBlockParamContentUnion{
				{OfText: &sdk.BetaTextBlockParam{Text: block.Content}},
			}
		}
		for _, image := range block.ResultImages {
			result.Content = append(result.Content, sdk.BetaToolResultBlockParamContentUnion{
				OfImage: toSDKContentBlock(NewImageBlock(image.MediaType, image.Data)).OfImage,
			})
		}
		if block.CacheControl != nil {
			result.CacheControl = sdk.BetaCacheControlEphemeralParam{Type: "ephemeral"}
		}
		return sdk.BetaContentBlockParamUnion{OfToolResult: result}
	case "thinking":
		return sdk.BetaContentBlockParamUnion{
			OfThinking: &sdk.BetaThinkingBlockParam{
				Signature: block.Signature,
				Thinking:  block.Thinking,
			},
		}
	case "redacted_thinking":
		return sdk.BetaContentBlockParamUnion{
			OfRedactedThinking: &sdk.BetaRedactedThinkingBlockParam{
				Data: block.Data,
			},
		}
	case "image":
		if block.Source == nil {
			return sdk.BetaContentBlockParamUnion{OfText: &sdk.BetaTextBlockParam{Text: ""}}
		}
		img := &sdk.BetaImageBlockParam{
			Source: sdk.BetaImageBlockParamSourceUnion{
				OfBase64: &sdk.BetaBase64ImageSourceParam{
					Data:      block.Source.Data,
					MediaType: sdk.BetaBase64ImageSourceMediaType(block.Source.MediaType),
				},
			},
		}
		if block.CacheControl != nil {
			img.CacheControl = sdk.BetaCacheControlEphemeralParam{Type: "ephemeral"}
		}
		return sdk.BetaContentBlockParamUnion{OfImage: img}
	case "document":
		if block.Source == nil {
			return sdk.BetaContentBlockParamUnion{OfText: &sdk.BetaTextBlockParam{Text: ""}}
		}
		doc := &sdk.BetaRequestDocumentBlockParam{
			Source: sdk.BetaRequestDocumentBlockSourceUnionParam{
				OfBase64: &sdk.BetaBase64PDFSourceParam{Data: block.Source.Data},
			},
		}
		if block.CacheControl != nil {
			doc.CacheControl = sdk.BetaCacheControlEphemeralParam{Type: "ephemeral"}
		}
		return sdk.BetaContentBlockParamUnion{OfDocument: doc}
	case "compaction":
		// Round-trip server compaction blocks verbatim. Content carries the
		// summary; the API requires null (not "") when no summary is present.
		compaction := &sdk.BetaCompactionBlockParam{
			EncryptedContent: sdk.String(block.EncryptedContent),
		}
		if block.Content != "" {
			compaction.Content = sdk.String(block.Content)
		} else {
			compaction.Content = param.Null[string]()
		}
		return sdk.BetaContentBlockParamUnion{OfCompaction: compaction}
	default:
		return sdk.BetaContentBlockParamUnion{
			OfText: &sdk.BetaTextBlockParam{Text: block.Text},
		}
	}
}

// CreateMessageResponse from the API (non-streaming and assembled from stream).
type CreateMessageResponse struct {
	ID         string         `json:"id"`
	Type       string         `json:"type"` // "message"
	Role       Role           `json:"role"`
	Content    []ContentBlock `json:"content"`
	Model      string         `json:"model"`
	StopReason StopReason     `json:"stop_reason"`
	Usage      Usage          `json:"usage"`
	// EndTurn preserves the optional OpenAI Responses backend signal while this
	// provider-neutral shim translates through Anthropic-shaped events.
	EndTurn *bool `json:"end_turn,omitempty"`
}

// StreamEventType identifies the type of a streaming SSE event.
type StreamEventType string

const (
	EventMessageStart      StreamEventType = "message_start"
	EventContentBlockStart StreamEventType = "content_block_start"
	EventContentBlockDelta StreamEventType = "content_block_delta"
	EventContentBlockStop  StreamEventType = "content_block_stop"
	EventMessageDelta      StreamEventType = "message_delta"
	EventMessageStop       StreamEventType = "message_stop"
	EventPing              StreamEventType = "ping"
	EventError             StreamEventType = "error"
)

// StreamEvent is a parsed streaming event.
type StreamEvent struct {
	Type StreamEventType `json:"type"`

	// message_start
	Message *CreateMessageResponse `json:"message,omitempty"`

	// content_block_start
	Index        int           `json:"index,omitempty"`
	ContentBlock *ContentBlock `json:"content_block,omitempty"`

	// content_block_delta and message_delta
	Delta *DeltaBlock `json:"delta,omitempty"`

	// message_delta: final usage
	Usage *Usage `json:"usage,omitempty"`

	// error
	Error *APIError `json:"error,omitempty"`
}

// DeltaBlock holds incremental content in a streaming delta event.
type DeltaBlock struct {
	Type             string `json:"type"`
	Text             string `json:"text,omitempty"`
	Thinking         string `json:"thinking,omitempty"`
	Signature        string `json:"signature,omitempty"`
	PartialJSON      string `json:"partial_json,omitempty"`
	Content          string `json:"content,omitempty"` // compaction_delta summary content
	EncryptedContent string `json:"encrypted_content,omitempty"`
	StopReason       string `json:"stop_reason,omitempty"`
	EndTurn          *bool  `json:"end_turn,omitempty"`
	Usage            *Usage `json:"usage,omitempty"`
}

// APIError from the API.
type APIError struct {
	Type    string `json:"type"`
	Message string `json:"message"`
}

// Beta header constants matching Claude Code's beta system.
const (
	BetaClaudeCode        = "claude-code-20250219"
	BetaInterleavedThink  = "interleaved-thinking-2025-05-14"
	BetaPromptCacheScope  = "prompt-caching-scope-2026-01-05"
	BetaContextManagement = "context-management-2025-06-27"
)

// ClaudeCodeIdentity is the exact first system block Claude Code sends.
// Anthropic's OAuth (Claude subscription) endpoints expect requests shaped
// like Claude Code, and this identity line is the load-bearing part of that
// shape (see pi-anthropic-oauth and opencode, which prepend the same text).
const ClaudeCodeIdentity = "You are Claude Code, Anthropic's official CLI for Claude."

// ModelBetas returns the beta headers for a given model.
func ModelBetas(model string) []string {
	betas := []string{BetaClaudeCode}

	if !isClaude3Model(model) {
		betas = append(betas, BetaInterleavedThink)
	}

	betas = append(betas, BetaContextManagement)
	betas = append(betas, BetaPromptCacheScope)

	return betas
}

func isClaude3Model(model string) bool {
	return strings.Contains(model, "claude-3-")
}

package anthropic

import (
	"encoding/json"
	"errors"
	"io"
)

// CollectResponse reads all streaming events and assembles a complete CreateMessageResponse.
// This is a convenience method used by the old SSE reader path.
func (r *StreamReader) CollectResponse() (*CreateMessageResponse, error) {
	assembler := NewStreamAssembler()

	for {
		event, err := r.Next()
		if err != nil {
			// Only a clean io.EOF ends the stream successfully. A mid-stream
			// failure (e.g. io.ErrUnexpectedEOF from a dropped connection)
			// must surface as an error, not a silently truncated response.
			if errors.Is(err, io.EOF) {
				break
			}
			return nil, err
		}

		assembler.Add(event)
	}

	return assembler.Response(), nil
}

// StreamAssembler incrementally rebuilds a CreateMessageResponse from stream
// events. Providers use it when they need to forward deltas live and still
// return a complete final ModelResponse.
type StreamAssembler struct {
	resp          CreateMessageResponse
	currentBlocks []ContentBlock
	builders      map[int]*blockAssembler
}

func NewStreamAssembler() *StreamAssembler {
	return &StreamAssembler{builders: make(map[int]*blockAssembler)}
}

func (a *StreamAssembler) Add(event StreamEvent) {
	if a == nil {
		return
	}
	if a.builders == nil {
		a.builders = make(map[int]*blockAssembler)
	}
	switch event.Type {
	case EventMessageStart:
		if event.Message != nil {
			a.resp.ID = event.Message.ID
			a.resp.Model = event.Message.Model
			a.resp.Role = event.Message.Role
			a.resp.Usage = event.Message.Usage
		}

	case EventContentBlockStart:
		if event.ContentBlock != nil {
			a.builders[event.Index] = &blockAssembler{
				blockType:        event.ContentBlock.Type,
				id:               event.ContentBlock.ID,
				name:             event.ContentBlock.Name,
				phase:            event.ContentBlock.Phase,
				signature:        event.ContentBlock.Signature,
				data:             event.ContentBlock.Data,
				content:          event.ContentBlock.Content,
				createdBy:        event.ContentBlock.CreatedBy,
				encryptedContent: event.ContentBlock.EncryptedContent,
			}
		}

	case EventContentBlockDelta:
		if b := a.builders[event.Index]; event.Delta != nil && b != nil {
			switch event.Delta.Type {
			case "text_delta":
				b.text += event.Delta.Text
			case "thinking_delta":
				b.thinking += event.Delta.Thinking
			case "signature_delta":
				b.signature += event.Delta.Signature
			case "reasoning_encrypted_content":
				b.encryptedContent = event.Delta.EncryptedContent
			case "input_json_delta":
				b.inputJSON += event.Delta.PartialJSON
			case "compaction_delta":
				b.content += event.Delta.Content
				if event.Delta.EncryptedContent != "" {
					b.encryptedContent = event.Delta.EncryptedContent
				}
			case "compaction_encrypted_content":
				b.encryptedContent = event.Delta.EncryptedContent
			}
		}

	case EventContentBlockStop:
		// A stop only applies to a still-open builder at that index; a
		// duplicated stop is ignored instead of appending the block twice.
		if b := a.builders[event.Index]; b != nil {
			a.currentBlocks = append(a.currentBlocks, b.build())
			delete(a.builders, event.Index)
		}

	case EventMessageDelta:
		if event.Delta != nil {
			if event.Delta.StopReason != "" {
				a.resp.StopReason = StopReason(event.Delta.StopReason)
			}
			if event.Delta.EndTurn != nil {
				endTurn := *event.Delta.EndTurn
				a.resp.EndTurn = &endTurn
			}
		}
		// message_delta usage is authoritative when present, but some backends
		// (and shims) only populate output_tokens there. Never let a zero field
		// clobber a non-zero value captured from message_start.
		if event.Usage != nil {
			if event.Usage.InputTokens != 0 {
				a.resp.Usage.InputTokens = event.Usage.InputTokens
			}
			if event.Usage.OutputTokens != 0 {
				a.resp.Usage.OutputTokens = event.Usage.OutputTokens
			}
			if event.Usage.CacheReadInputTokens != 0 {
				a.resp.Usage.CacheReadInputTokens = event.Usage.CacheReadInputTokens
			}
			if event.Usage.CacheCreationInputTokens != 0 {
				a.resp.Usage.CacheCreationInputTokens = event.Usage.CacheCreationInputTokens
			}
		}

	case EventMessageStop:
		// done
	}
}

func (a *StreamAssembler) Response() *CreateMessageResponse {
	if a == nil {
		return &CreateMessageResponse{}
	}
	resp := a.resp
	resp.Content = append([]ContentBlock(nil), a.currentBlocks...)
	return &resp
}

// blockAssembler accumulates streaming deltas for a single content block.
type blockAssembler struct {
	blockType        string
	id               string
	name             string
	phase            string
	text             string
	thinking         string
	signature        string
	data             string
	content          string
	createdBy        string
	encryptedContent string
	inputJSON        string
}

func (b *blockAssembler) build() ContentBlock {
	switch b.blockType {
	case "text":
		block := NewTextBlock(b.text)
		block.Phase = b.phase
		return block
	case "thinking":
		block := NewThinkingBlock(b.thinking)
		block.ID = b.id
		block.Signature = b.signature
		block.EncryptedContent = b.encryptedContent
		return block
	case "redacted_thinking":
		block := NewRedactedThinkingBlock(b.data)
		block.ID = b.id
		block.EncryptedContent = b.encryptedContent
		return block
	case "compaction":
		block := NewCompactionBlock(b.id, b.encryptedContent, b.createdBy)
		block.Content = b.content
		return block
	case "tool_use":
		var input json.RawMessage
		if b.inputJSON != "" {
			input = json.RawMessage(b.inputJSON)
		} else {
			input = json.RawMessage("{}")
		}
		return NewToolUseBlock(b.id, b.name, input)
	default:
		return NewTextBlock(b.text)
	}
}

package anthropic

import (
	"strconv"
	"strings"
)

// Claude exposes two mutually incompatible extended-thinking request shapes,
// split by model generation:
//
//   - thinking.type=enabled + budget_tokens: the classic shape, implemented by
//     the 4.5-and-older generations (claude-haiku-4.5, claude-sonnet-4.5,
//     claude-opus-4.5, claude-sonnet-4, claude-3-x). Effort-only models reject
//     it (live 400: `"thinking.type.enabled" is not supported for this model.
//     Use "thinking.type.adaptive" and "output_config.effort" ...`).
//   - thinking.type=adaptive + output_config.effort: the effort-first shape
//     introduced with the 4.6 generation (claude-sonnet-4.6, claude-opus-4.6+,
//     claude-sonnet-5, claude-fable-5). Older models reject or ignore it —
//     notably GitHub Copilot's /v1/messages shim returns no thinking blocks at
//     all for adaptive requests against the 4.5 family, silently disabling
//     visible reasoning.
//
// The split below mirrors the models.dev reasoning_options catalog for the
// "anthropic" and "github-copilot" providers (and opencode's per-model
// adaptive-thinking gating). Callers that guess wrong self-heal via the
// thinking-shape 400 retry in the providers layer.

// ModelSupportsAdaptiveThinking reports whether a Claude model accepts
// thinking.type=adaptive + output_config.effort: the fable family and every
// sonnet/opus/haiku generation from 4.6 upward.
func ModelSupportsAdaptiveThinking(model string) bool {
	family, major, minor, ok := claudeThinkingGeneration(model)
	if !ok {
		return false
	}
	if family == "fable" {
		return true
	}
	return major > 4 || (major == 4 && minor >= 6)
}

// ModelRequiresAdaptiveThinking reports whether a Claude model accepts ONLY
// the adaptive shape on the first-party Messages API, i.e. rejects
// thinking.type=enabled + budget_tokens: the fable family, opus 4.7+, and any
// generation 5 model. (claude-sonnet-4.6 and claude-opus-4.6 still accept
// budget_tokens on api.anthropic.com, so they are not in this set.)
func ModelRequiresAdaptiveThinking(model string) bool {
	family, major, minor, ok := claudeThinkingGeneration(model)
	if !ok {
		return false
	}
	if family == "fable" {
		return true
	}
	if major >= 5 {
		return true
	}
	return family == "opus" && major == 4 && minor >= 7
}

// claudeThinkingGeneration parses a Claude model identifier into its family
// and version. It tolerates the dotted (claude-sonnet-4.6), dashed
// (claude-sonnet-4-6), dated (claude-sonnet-4-5-20250929), and legacy
// version-first (claude-3-7-sonnet) naming forms; date stamps (>= 1000) are
// not version segments. ok is false for non-Claude models.
func claudeThinkingGeneration(model string) (family string, major, minor int, ok bool) {
	normalized := strings.ToLower(strings.TrimSpace(model))
	if idx := strings.LastIndex(normalized, "/"); idx >= 0 {
		normalized = normalized[idx+1:]
	}
	if !strings.Contains(normalized, "claude") {
		return "", 0, 0, false
	}

	versionSeen := false
	for _, token := range strings.Split(normalized, "-") {
		switch token {
		case "fable", "sonnet", "opus", "haiku":
			if family == "" {
				family = token
			}
			continue
		}
		if versionSeen && minor > 0 {
			continue
		}
		// A token is a version segment when it is numeric ("4", "5") or
		// dotted-numeric ("4.6"); 4+ digit numbers are date stamps.
		for _, part := range strings.SplitN(token, ".", 2) {
			n, err := strconv.Atoi(part)
			if err != nil || n >= 1000 {
				break
			}
			if !versionSeen {
				major = n
				versionSeen = true
			} else if minor == 0 {
				minor = n
			}
		}
	}
	if family == "" && !versionSeen {
		return "", 0, 0, false
	}
	return family, major, minor, true
}

package anthropic

import "testing"

// TestModelThinkingShapeCapabilities pins the per-generation thinking-shape
// split mirrored from the models.dev reasoning_options catalogs: the 4.5
// generation and older only implement enabled+budget_tokens, 4.6+/fable/5.x
// implement adaptive+output_config.effort, and only the effort-only models
// (fable, opus 4.7+, generation 5) reject enabled on the first-party API.
func TestModelThinkingShapeCapabilities(t *testing.T) {
	cases := []struct {
		model    string
		supports bool // ModelSupportsAdaptiveThinking
		requires bool // ModelRequiresAdaptiveThinking
	}{
		// Budget-only generation (Copilot's /v1/messages shim returns no
		// thinking blocks for adaptive requests against these).
		{"claude-haiku-4.5", false, false},
		{"claude-haiku-4-5", false, false},
		{"claude-haiku-4-5-20251001", false, false},
		{"claude-sonnet-4.5", false, false},
		{"claude-sonnet-4-5-20250929", false, false},
		{"claude-opus-4.5", false, false},
		{"claude-opus-4-5-20251101", false, false},
		{"claude-sonnet-4", false, false},
		{"claude-sonnet-4-20250514", false, false},
		{"claude-opus-4-1", false, false},
		{"claude-3-7-sonnet", false, false},
		{"claude-3-5-haiku-20241022", false, false},

		// Adaptive-capable, budget still accepted on api.anthropic.com.
		{"claude-sonnet-4.6", true, false},
		{"claude-sonnet-4-6", true, false},
		{"claude-opus-4.6", true, false},
		{"claude-opus-4-6", true, false},

		// Effort-only models: adaptive everywhere.
		{"claude-opus-4.7", true, true},
		{"claude-opus-4-7", true, true},
		{"claude-opus-4.8", true, true},
		{"claude-sonnet-5", true, true},
		{"claude-fable-5", true, true},
		{"claude-fable-5-20260601", true, true},

		// Prefixed model IDs are tolerated.
		{"copilot/claude-sonnet-4.5", false, false},
		{"anthropic/claude-fable-5", true, true},

		// Non-Claude models never match.
		{"gpt-5.2", false, false},
		{"gemini-3-pro", false, false},
		{"", false, false},
	}
	for _, tc := range cases {
		if got := ModelSupportsAdaptiveThinking(tc.model); got != tc.supports {
			t.Errorf("ModelSupportsAdaptiveThinking(%q) = %v, want %v", tc.model, got, tc.supports)
		}
		if got := ModelRequiresAdaptiveThinking(tc.model); got != tc.requires {
			t.Errorf("ModelRequiresAdaptiveThinking(%q) = %v, want %v", tc.model, got, tc.requires)
		}
	}
}

