import (
	"encoding/json"
	"testing"
)

// A tool whose schema has no properties (e.g. `{"type":"object"}`) must still
// serialize an input_schema object. The anthropic-sdk-go BetaToolParam tags
// input_schema with omitzero, so a zero-value BetaToolInputSchemaParam is
// dropped from the wire request and the API rejects it with
// "tools.N.custom.input_schema: Field required".
func TestToSDKParamsAlwaysSendsToolInputSchema(t *testing.T) {
	req := &CreateMessageRequest{
		Model:     "claude-sonnet-5",
		MaxTokens: 100,
		Messages:  []Message{{Role: RoleUser, Content: []ContentBlock{NewTextBlock("hi")}}},
		Tools: []ToolDefinition{
			{Name: "get_fleet_runs", Description: "list runs", InputSchema: json.RawMessage(`{"type":"object"}`)},
			{Name: "no_schema", Description: "degenerate"},
			{Name: "with_props", Description: "normal", InputSchema: json.RawMessage(`{"type":"object","properties":{"id":{"type":"string"}},"required":["id"]}`)},
		},
	}
	params, _ := toSDKParams(req)
	raw, err := params.MarshalJSON()
	if err != nil {
		t.Fatal(err)
	}
	var body struct {
		Tools []map[string]any `json:"tools"`
	}
	if err := json.Unmarshal(raw, &body); err != nil {
		t.Fatal(err)
	}
	if len(body.Tools) != 3 {
		t.Fatalf("tools = %d, want 3: %s", len(body.Tools), raw)
	}
	for i, tool := range body.Tools {
		schema, ok := tool["input_schema"].(map[string]any)
		if !ok {
			t.Fatalf("tools.%d (%v) input_schema missing or not an object: %s", i, tool["name"], raw)
		}
		if schema["type"] != "object" {
			t.Fatalf("tools.%d input_schema.type = %v, want object", i, schema["type"])
		}
		if _, ok := schema["properties"].(map[string]any); !ok {
			t.Fatalf("tools.%d input_schema.properties missing: %s", i, raw)
		}
	}
	if req, _ := body.Tools[2]["input_schema"].(map[string]any)["required"].([]any); len(req) != 1 {
		t.Fatalf("tools.2 required lost: %s", raw)
	}
}

package anthropic

import "encoding/json"

// Role for messages.
type Role string

const (
	RoleUser      Role = "user"
	RoleAssistant Role = "assistant"
)

// Message in a conversation.
type Message struct {
	Role    Role           `json:"role"`
	Content []ContentBlock `json:"content"`
}

// ContentBlock is a union type for message content.
// The Type field determines which other fields are relevant.
type ContentBlock struct {
	Type string `json:"type"`

	// TextBlock fields (type="text").
	Text  string `json:"text,omitempty"`
	Phase string `json:"phase,omitempty"`

	// ThinkingBlock fields (type="thinking").
	Thinking         string `json:"thinking,omitempty"`
	Signature        string `json:"signature,omitempty"`
	Data             string `json:"data,omitempty"`
	EncryptedContent string `json:"encrypted_content,omitempty"`

	// ToolUseBlock fields (type="tool_use").
	ID        string          `json:"id,omitempty"`
	Name      string          `json:"name,omitempty"`
	CreatedBy string          `json:"created_by,omitempty"`
	Input     json.RawMessage `json:"input,omitempty"`

	// ToolResultBlock fields (type="tool_result").
	ResultImages []ImageSource `json:"result_images,omitempty"`
	ToolUseID    string        `json:"tool_use_id,omitempty"`
	Content      string        `json:"content,omitempty"` // tool_result text / compaction summary
	IsError      bool          `json:"is_error,omitempty"`

	// ImageBlock fields (type="image").
	Source *ImageSource `json:"source,omitempty"`
	Detail string       `json:"detail,omitempty"`

	// CacheControl for prompt caching.
	CacheControl *CacheControl `json:"cache_control,omitempty"`
}

// ImageSource is a base64-encoded image payload for an image content block.
type ImageSource struct {
	Type      string `json:"type"` // "base64"
	MediaType string `json:"media_type"`
	Data      string `json:"data"`
}

// NewTextBlock creates a text content block.
func NewTextBlock(text string) ContentBlock {
	return ContentBlock{Type: "text", Text: text}
}

// NewThinkingBlock creates a thinking content block.
func NewThinkingBlock(thinking string) ContentBlock {
	return ContentBlock{Type: "thinking", Thinking: thinking}
}

// NewRedactedThinkingBlock creates a redacted_thinking content block.
func NewRedactedThinkingBlock(data string) ContentBlock {
	return ContentBlock{Type: "redacted_thinking", Data: data}
}

// NewCompactionBlock creates an opaque provider compaction content block.
func NewCompactionBlock(id, encryptedContent, createdBy string) ContentBlock {
	return ContentBlock{Type: "compaction", ID: id, EncryptedContent: encryptedContent, CreatedBy: createdBy}
}

// ForeignCompactionSummaryHeader prefixes the plaintext assistant message a
// request builder substitutes for an encrypted compaction blob produced by a
// different provider (undecryptable here, and the only remnant of the history
// pruned behind it). Shared by the anthropic and openai providers so the
// down-converted marker is identical across a provider switch.
const ForeignCompactionSummaryHeader = "[CONTEXT SUMMARY carried over from an earlier context compaction by a different model provider]\n"

// NewToolUseBlock creates a tool_use content block.
func NewToolUseBlock(id, name string, input json.RawMessage) ContentBlock {
	return ContentBlock{Type: "tool_use", ID: id, Name: name, Input: input}
}

// NewToolResultBlock creates a tool_result content block.
func NewToolResultBlock(toolUseID, content string, isError bool) ContentBlock {
	return ContentBlock{Type: "tool_result", ToolUseID: toolUseID, Content: content, IsError: isError}
}

// NewImageBlock creates an image content block from base64-encoded data.
func NewImageBlock(mediaType, base64Data string) ContentBlock {
	return ContentBlock{Type: "image", Source: &ImageSource{Type: "base64", MediaType: mediaType, Data: base64Data}}
}

// NewDocumentBlock creates a document content block (e.g. application/pdf)
// from base64-encoded data.
func NewDocumentBlock(mediaType, base64Data string) ContentBlock {
	return ContentBlock{Type: "document", Source: &ImageSource{Type: "base64", MediaType: mediaType, Data: base64Data}}
}

// CacheControl for prompt caching.
type CacheControl struct {
	Type string `json:"type"` // "ephemeral"
}

// Usage tracks token counts from the API.
type Usage struct {
	InputTokens              int64 `json:"input_tokens"`
	OutputTokens             int64 `json:"output_tokens"`
	CacheReadInputTokens     int64 `json:"cache_read_input_tokens,omitempty"`
	CacheCreationInputTokens int64 `json:"cache_creation_input_tokens,omitempty"`
}

// ToolDefinition for the API request.
type ToolDefinition struct {
	Name        string          `json:"name"`
	Description string          `json:"description"`
	InputSchema json.RawMessage `json:"input_schema"`
	// CacheControl marks a prompt-cache breakpoint after this tool. Set on the
	// last tool so the whole tool prefix is cached.
	CacheControl *CacheControl `json:"cache_control,omitempty"`
}

// SystemBlock for system prompt segments.
type SystemBlock struct {
	Type         string        `json:"type"` // "text"
	Text         string        `json:"text"`
	CacheControl *CacheControl `json:"cache_control,omitempty"`
}

// StopReason from the API response.
type StopReason string

const (
	StopReasonEndTurn   StopReason = "end_turn"
	StopReasonToolUse   StopReason = "tool_use"
	StopReasonMaxTokens StopReason = "max_tokens"
)

// Package modelactivity carries an optional per-call model stream activity
// callback through context. Transports that consume provider streams internally
// use it to report progress even when individual stream events are not exposed
// to the agent runner.
package modelactivity

import (
	"context"
	"io"
	"net/http"
)

type sinkKey struct{}

// Sink is called whenever a provider response stream makes progress.
// Implementations must be safe for concurrent use and must return quickly.
type Sink func()

// WithSink returns a context that reports model stream activity to sink.
func WithSink(ctx context.Context, sink Sink) context.Context {
	if sink == nil {
		return ctx
	}
	return context.WithValue(ctx, sinkKey{}, sink)
}

// Notify reports model stream activity to the sink installed on ctx, if any.
func Notify(ctx context.Context) {
	if ctx == nil {
		return
	}
	if sink, ok := ctx.Value(sinkKey{}).(Sink); ok && sink != nil {
		sink()
	}
}

// WrapTransport reports activity whenever bytes arrive from a provider HTTP
// response. Observing the body at this boundary includes SSE events that a
// provider SDK may intentionally discard, such as heartbeat pings.
func WrapTransport(base http.RoundTripper) http.RoundTripper {
	if base == nil {
		base = http.DefaultTransport
	}
	return activityRoundTripper{base: base}
}

type activityRoundTripper struct {
	base http.RoundTripper
}

func (t activityRoundTripper) RoundTrip(req *http.Request) (*http.Response, error) {
	resp, err := t.base.RoundTrip(req)
	if err != nil || resp == nil || resp.Body == nil {
		return resp, err
	}
	resp.Body = &activityReadCloser{ReadCloser: resp.Body, ctx: req.Context()}
	return resp, nil
}

type activityReadCloser struct {
	io.ReadCloser
	ctx context.Context
}

func (r *activityReadCloser) Read(p []byte) (int, error) {
	n, err := r.ReadCloser.Read(p)
	if n > 0 {
		Notify(r.ctx)
	}
	return n, err
}

package modelactivity

import (
	"context"
	"io"
	"net/http"
	"testing"
)

type roundTripFunc func(*http.Request) (*http.Response, error)

func (f roundTripFunc) RoundTrip(req *http.Request) (*http.Response, error) {
	return f(req)
}

type chunkReadCloser struct {
	chunks [][]byte
}

func (r *chunkReadCloser) Read(p []byte) (int, error) {
	if len(r.chunks) == 0 {
		return 0, io.EOF
	}
	n := copy(p, r.chunks[0])
	r.chunks = r.chunks[1:]
	return n, nil
}

func (*chunkReadCloser) Close() error { return nil }

func TestWrapTransportReportsEveryResponseBodyRead(t *testing.T) {
	activityCount := 0
	ctx := WithSink(context.Background(), func() { activityCount++ })
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, "https://example.test/stream", nil)
	if err != nil {
		t.Fatal(err)
	}
	body := &chunkReadCloser{chunks: [][]byte{
		[]byte("event: message_start\ndata: {}\n\n"),
		[]byte("event: ping\ndata: {}\n\n"),
		[]byte("event: input_json_delta\ndata: {}\n\n"),
	}}
	transport := WrapTransport(roundTripFunc(func(*http.Request) (*http.Response, error) {
		return &http.Response{StatusCode: http.StatusOK, Body: body}, nil
	}))

	resp, err := transport.RoundTrip(req)
	if err != nil {
		t.Fatal(err)
	}
	defer resp.Body.Close()
	if _, err := io.ReadAll(resp.Body); err != nil {
		t.Fatal(err)
	}
	if activityCount != 3 {
		t.Fatalf("activity count = %d, want one notification for each of 3 provider chunks", activityCount)
	}
}

// Package modeldelta carries an optional per-call sink for streamed model
// reasoning text through context. Transports that already consume streaming
// HTTP responses inside blocking calls (GetResponse) can surface reasoning
// deltas live to the host without changing their public signatures.
//
// It is a leaf package so that internal/agent (which installs sinks) and the
// provider transports internal/anthropic and internal/openai (which invoke
// them) can all import it without cycles.
package modeldelta

import "context"

// ReasoningSink receives incremental reasoning text chunks in stream order.
// Implementations must be cheap and non-blocking: they are called inline from
// the goroutine that consumes the model's HTTP stream. Chunks may be re-sent
// from the start if the transport retries a failed request mid-stream;
// consumers reconcile via the final complete reasoning text.
type ReasoningSink func(text string)

type ctxKey struct{}

// WithReasoningSink returns a context that delivers streamed reasoning text
// chunks to sink during model calls made with this context.
func WithReasoningSink(ctx context.Context, sink ReasoningSink) context.Context {
	if sink == nil {
		return ctx
	}
	return context.WithValue(ctx, ctxKey{}, sink)
}

// ReasoningSinkFromContext extracts the reasoning sink installed by
// WithReasoningSink, or nil when the call has no live reasoning consumer.
func ReasoningSinkFromContext(ctx context.Context) ReasoningSink {
	if ctx == nil {
		return nil
	}
	sink, _ := ctx.Value(ctxKey{}).(ReasoningSink)
	return sink
}

