		resp := &http.Response{StatusCode: http.StatusBadRequest, Header: make(http.Header)}
		maybeNormalizeCodexCompactResponse(req, resp, oauthSession)
		if got := resp.Header.Get("Content-Type"); got != "" {
			t.Fatalf("error Content-Type = %q, want empty", got)
		}
	})
}

func TestAuthRoundTripperNormalizesCodexCompactResponse(t *testing.T) {
	session, err := NewOAuthAuthSessionFromSecretData([]byte(`{
		"tokens":{"access_token":"oauth-access","refresh_token":"oauth-refresh","account_id":"acct-1"},
		"last_refresh":"2099-01-01T00:00:00Z"
	}`), "")
	if err != nil {
		t.Fatalf("NewOAuthAuthSessionFromSecretData() error = %v", err)
	}

	rt := &authRoundTripper{
		session: session,
		base: roundTripFunc(func(req *http.Request) (*http.Response, error) {
			if got := req.URL.Query().Get("client_version"); got != DefaultCodexClientVersion {
				t.Fatalf("client_version = %q, want %q", got, DefaultCodexClientVersion)
			}
			if got := req.Header.Get("Authorization"); got != "Bearer oauth-access" {
				t.Fatalf("Authorization = %q, want OAuth bearer", got)
			}
			return &http.Response{
				StatusCode: http.StatusOK,
				Header:     make(http.Header),
				Body:       io.NopCloser(strings.NewReader(`{"id":"resp_compact","output":[]}`)),
				Request:    req,
			}, nil
		}),
	}
	req, err := http.NewRequest(http.MethodPost, "https://chatgpt.com/backend-api/codex/responses/compact", strings.NewReader(`{"model":"gpt-5.5","input":[]}`))
	if err != nil {
		t.Fatalf("NewRequest() error = %v", err)
	}
	resp, err := rt.RoundTrip(req)
	if err != nil {
		t.Fatalf("RoundTrip() error = %v", err)
	}
	defer func() { _ = resp.Body.Close() }()
	if got := resp.Header.Get("Content-Type"); got != "application/json" {
		t.Fatalf("Content-Type = %q, want application/json", got)
	}
}

func TestCollectSSEToJSON(t *testing.T) {
	t.Run("extracts response.completed from SSE stream", func(t *testing.T) {
		sseBody := strings.Join([]string{
			`data: {"type":"response.created","response":{"id":"resp_123","status":"in_progress"}}`,
			"",
			`data: {"type":"response.output_item.added","output_index":0}`,
			"",
			`data: {"type":"response.completed","response":{"id":"resp_123","status":"completed","output":[{"type":"message","content":[{"type":"output_text","text":"Hello"}]}]}}`,
			"",
			"data: [DONE]",
			"",
		}, "\n")

		var activityCount atomic.Int32
		activityCtx := modelactivity.WithSink(context.Background(), func() { activityCount.Add(1) })
		request, err := http.NewRequestWithContext(activityCtx, http.MethodPost, "https://chatgpt.com/backend-api/codex/responses", nil)
		if err != nil {
			t.Fatal(err)
		}
		resp := &http.Response{
			Status:     "200 OK",
			StatusCode: http.StatusOK,
			Proto:      "HTTP/1.1",
			ProtoMajor: 1,
			ProtoMinor: 1,
			Header:     http.Header{"Content-Type": []string{"text/event-stream"}},
			Body:       io.NopCloser(strings.NewReader(sseBody)),
			Request:    request,
		}

		result, err := collectSSEToJSON(resp)
		if err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
		body, _ := io.ReadAll(result.Body)
		if result.StatusCode != 200 {
			t.Errorf("expected 200, got %d", result.StatusCode)
		}
		if activityCount.Load() == 0 {
			t.Fatal("SSE collection did not report model stream activity")
		}
		if result.Header.Get("Content-Type") != "application/json" {
			t.Errorf("expected application/json, got %s", result.Header.Get("Content-Type"))
		}
		var parsed map[string]any
		if err := json.Unmarshal(body, &parsed); err != nil {
			t.Fatalf("response body is not valid JSON: %s", string(body))
		}
		if parsed["id"] != "resp_123" {
			t.Errorf("expected id=resp_123, got %v", parsed["id"])
		}
		if parsed["status"] != "completed" {
			t.Errorf("expected status=completed, got %v", parsed["status"])
		}
	})

	t.Run("forced stream attaches request before reporting activity", func(t *testing.T) {
		var activityCount atomic.Int32
		ctx := modelactivity.WithSink(context.Background(), func() { activityCount.Add(1) })
		req, err := http.NewRequestWithContext(ctx, http.MethodPost, "https://chatgpt.com/backend-api/codex/responses", nil)
		if err != nil {
			t.Fatal(err)
		}
		resp := &http.Response{
			StatusCode: http.StatusOK,
			Header:     http.Header{"Content-Type": []string{"text/event-stream"}},
			Body: io.NopCloser(strings.NewReader(
				"data: {\"type\":\"response.completed\",\"response\":{\"id\":\"resp_activity\",\"status\":\"completed\",\"output\":[]}}\n\ndata: [DONE]\n\n",
			)),
			Request: nil,
		}
		result, err := maybeFinalizeCodexResponse(req, resp, true, nil)
		if err != nil {
			t.Fatalf("maybeFinalizeCodexResponse() error = %v", err)
		}
		defer result.Body.Close()
		if activityCount.Load() == 0 {
			t.Fatal("forced SSE collection did not report request-scoped model activity")
		}
		if result.Request != req {
			t.Fatal("forced SSE response did not retain the originating request")
		}
	})

	t.Run("falls back to latest response when no response.completed event", func(t *testing.T) {
		sseBody := "data: {\"type\":\"response.created\",\"response\":{\"id\":\"resp_123\"}}\n\ndata: [DONE]\n\n"
		resp := &http.Response{
			StatusCode: http.StatusOK,
			Header:     http.Header{"Content-Type": []string{"text/event-stream"}},
			Body:       io.NopCloser(strings.NewReader(sseBody)),
		}
		synth, err := collectSSEToJSON(resp)
		if err != nil {
			t.Fatalf("expected fallback to latest response, got error: %v", err)
		}
		body, _ := io.ReadAll(synth.Body)
		if !strings.Contains(string(body), "resp_123") {
			t.Fatalf("expected fallback response to contain resp_123, got: %s", body)
		}
	})

	t.Run("reconstructs message output from SSE deltas when completed output is empty", func(t *testing.T) {
		sseBody := strings.Join([]string{
			`data: {"type":"response.created","response":{"id":"resp_delta","status":"in_progress"}}`,
			"",
			`data: {"type":"response.output_item.added","output_index":0,"item":{"type":"message","id":"msg_1","role":"assistant","status":"in_progress"}}`,
			"",
			`data: {"type":"response.content_part.added","output_index":0,"content_index":0,"part":{"type":"output_text"}}`,
			"",
			`data: {"type":"response.output_text.delta","output_index":0,"content_index":0,"delta":"hello "}`,
			"",
			`data: {"type":"response.output_text.delta","output_index":0,"content_index":0,"delta":"world"}`,
			"",
			`data: {"type":"response.output_text.done","output_index":0,"content_index":0}`,
			"",
			`data: {"type":"response.completed","response":{"id":"resp_delta","status":"completed","output":[]}}`,
			"",
			"data: [DONE]",
			"",
		}, "\n")
		resp := &http.Response{
			StatusCode: http.StatusOK,
			Header:     http.Header{"Content-Type": []string{"text/event-stream"}},
			Body:       io.NopCloser(strings.NewReader(sseBody)),
		}

		synth, err := collectSSEToJSON(resp)
		if err != nil {
			t.Fatalf("collectSSEToJSON() error = %v", err)
		}
		body, _ := io.ReadAll(synth.Body)
		var parsed struct {
			Output []struct {
				Type    string `json:"type"`
				Content []struct {
					Type string `json:"type"`
					Text string `json:"text"`
				} `json:"content"`
			} `json:"output"`
		}
		if err := json.Unmarshal(body, &parsed); err != nil {
			t.Fatalf("response body is not valid JSON: %s", string(body))
		}
		if len(parsed.Output) != 1 || parsed.Output[0].Type != "message" {
			t.Fatalf("output = %+v, want one message", parsed.Output)
		}
		if len(parsed.Output[0].Content) != 1 || parsed.Output[0].Content[0].Text != "hello world" {
			t.Fatalf("message content = %+v, want hello world", parsed.Output[0].Content)
		}
	})

	t.Run("reconstructs reasoning summary from SSE deltas when completed output is empty", func(t *testing.T) {
		sseBody := strings.Join([]string{
			`data: {"type":"response.created","response":{"id":"resp_reasoning","status":"in_progress"}}`,
			"",
			`data: {"type":"response.output_item.added","output_index":0,"item":{"type":"reasoning","id":"rs_1","status":"in_progress"}}`,
			"",
			`data: {"type":"response.reasoning_summary_text.delta","output_index":0,"summary_index":0,"delta":"Analyzing "}`,
			"",
			`data: {"type":"response.reasoning_summary_text.delta","output_index":0,"summary_index":0,"delta":"the request."}`,
			"",
			`data: {"type":"response.reasoning_summary_text.done","output_index":0,"summary_index":0,"text":"Analyzing the request."}`,
			"",
			`data: {"type":"response.output_item.done","output_index":0,"item":{"type":"reasoning","id":"rs_1","status":"completed","encrypted_content":"enc_1"}}`,
			"",
			`data: {"type":"response.completed","response":{"id":"resp_reasoning","status":"completed","output":[]}}`,
			"",
			"data: [DONE]",
			"",
		}, "\n")
		resp := &http.Response{
			StatusCode: http.StatusOK,
			Header:     http.Header{"Content-Type": []string{"text/event-stream"}},
			Body:       io.NopCloser(strings.NewReader(sseBody)),
		}

		synth, err := collectSSEToJSON(resp)
		if err != nil {
			t.Fatalf("collectSSEToJSON() error = %v", err)
		}
		body, _ := io.ReadAll(synth.Body)
		var parsed struct {
			Output []struct {
				Type             string `json:"type"`
				ID               string `json:"id"`
				EncryptedContent string `json:"encrypted_content"`
				Summary          []struct {
					Type string `json:"type"`
					Text string `json:"text"`
				} `json:"summary"`
			} `json:"output"`
		}
		if err := json.Unmarshal(body, &parsed); err != nil {
			t.Fatalf("response body is not valid JSON: %s", string(body))
		}
		if len(parsed.Output) != 1 || parsed.Output[0].Type != "reasoning" {
			t.Fatalf("output = %+v, want one reasoning item", parsed.Output)
		}
		reasoning := parsed.Output[0]
		if reasoning.ID != "rs_1" || reasoning.EncryptedContent != "enc_1" {
			t.Fatalf("reasoning metadata = id:%q encrypted:%q", reasoning.ID, reasoning.EncryptedContent)
		}
		if len(reasoning.Summary) != 1 || reasoning.Summary[0].Type != "summary_text" || reasoning.Summary[0].Text != "Analyzing the request." {
			t.Fatalf("reasoning summary = %+v, want reconstructed summary text", reasoning.Summary)
		}

		var sdkResponse responses.Response
		if err := json.Unmarshal(body, &sdkResponse); err != nil {
			t.Fatalf("unmarshal synthetic OpenAI response: %v", err)
		}
		message, err := toAnthropicResponseFromResponses(&sdkResponse)
		if err != nil {
			t.Fatalf("convert synthetic OpenAI response: %v", err)
		}
		if len(message.Content) != 1 || message.Content[0].Type != "thinking" || message.Content[0].Thinking != "Analyzing the request." {
			t.Fatalf("converted content = %+v, want reconstructed thinking block", message.Content)
		}
	})

	t.Run("preserves compaction output when completed output is empty", func(t *testing.T) {
		sseBody := strings.Join([]string{
			`data: {"type":"response.created","response":{"id":"resp_compaction","status":"in_progress"}}`,
			"",
