// hostFromURL extracts the host component of a URL, returning "" on parse error.
func hostFromURL(raw string) string {
	u, err := url.Parse(strings.TrimSpace(raw))
	if err != nil {
		return ""
	}
	return u.Host
}

// chatCompletionChunk is a single Server-Sent Event payload from a streaming
// chat-completions response.
type chatCompletionChunk struct {
	ID      string            `json:"id"`
	Model   string            `json:"model"`
	Choices []chatChunkChoice `json:"choices"`
	Usage   *chatUsage        `json:"usage"`
	Error   *chatAPIError     `json:"error"`
}

type chatChunkChoice struct {
	Index        int            `json:"index"`
	Delta        chatChunkDelta `json:"delta"`
	FinishReason string         `json:"finish_reason"`
	Error        *chatAPIError  `json:"error,omitempty"`
}

type chatChunkDelta struct {
	Role      string              `json:"role"`
	Content   string              `json:"content"`
	Refusal   string              `json:"refusal"`
	ToolCalls []chatChunkToolCall `json:"tool_calls"`

	// OpenRouter reasoning fields. reasoning_content is a compatibility alias;
	// reasoning_details carries provider-native blocks that must be preserved.
	Reasoning        string            `json:"reasoning"`
	ReasoningContent string            `json:"reasoning_content"`
	ReasoningDetails []json.RawMessage `json:"reasoning_details"`

	// Copilot-specific reasoning fields.
	ReasoningText   string `json:"reasoning_text"`
	ReasoningOpaque string `json:"reasoning_opaque"`
}

type chatChunkToolCall struct {
	Index    int                 `json:"index"`
	ID       string              `json:"id"`
	Type     string              `json:"type"`
	Function chatChunkToolCallFn `json:"function"`
}

type chatChunkToolCallFn struct {
	Name      string `json:"name"`
	Arguments string `json:"arguments"`
}

// createChatStream issues a streaming chat-completions request and returns a
// reader that translates the SSE chunks into Anthropic-style stream events. It
// acquires the concurrency semaphore around request setup, so it must only be
// called by paths that do not already hold it (e.g. CreateMessageStream).
// Copilot exposes plaintext reasoning only on this path (message.reasoning_text);
// the /v1/messages shim returns signature-only thinking.
func (c *Client) createChatStream(ctx context.Context, req anthropic.CreateMessageRequest) (messageStream, error) {
	// Acquire the concurrency semaphore for the request setup, mirroring the
	// Responses streaming path. It is released once the reader is constructed.
	select {
	case c.sem <- struct{}{}:
	case <-ctx.Done():
		return nil, ctx.Err()
	}
	defer func() { <-c.sem }()
	return c.sendChatStream(ctx, req)
}

// sendChatStream builds and issues the streaming chat-completions request
// without touching the concurrency semaphore. Callers that already hold the
// semaphore — CreateMessage's doWithRetry, via createViaChatCompletions —
// reuse this path to buffer the streamed response, so re-acquiring the
// semaphore here would deadlock once in-flight requests reach the limit.
func (c *Client) sendChatStream(ctx context.Context, req anthropic.CreateMessageRequest) (messageStream, error) {
	chatReq, err := toChatRequest(req)
	if err != nil {
		return nil, err
	}
	chatReq.Models = withModelFallbacks(chatReq.Model, c.modelFallbacks)
	chatReq.Stream = true
	chatReq.StreamOptions = &chatStreamOptions{IncludeUsage: true}
	// Copilot uses the flat reasoning_effort field (not the nested OpenRouter
	// "reasoning" object) and only then returns reasoning_text.
	if isGitHubCopilotHost(hostFromURL(c.completionsURL)) {
		if effort := strings.TrimSpace(req.ReasoningEffort); effort != "" {
			chatReq.ReasoningEffort = effort
		}
		// Copilot does not accept OpenRouter's nested reasoning control, including
		// max_tokens from a budget-only request; it only supports reasoning_effort.
		chatReq.Reasoning = nil
		// Copilot rejects OpenRouter's plaintext/structured reasoning fields.
		for i := range chatReq.Messages {
			chatReq.Messages[i].Reasoning = ""
			chatReq.Messages[i].ReasoningContent = ""
			chatReq.Messages[i].ReasoningDetails = nil
		}
	}

	data, err := json.Marshal(chatReq)
	if err != nil {
		return nil, fmt.Errorf("marshal chat stream request: %w", err)
	}
	httpReq, err := http.NewRequestWithContext(ctx, http.MethodPost, c.completionsURL, bytes.NewReader(data))
	if err != nil {
		return nil, err
	}
	httpReq.Header.Set("Content-Type", "application/json")
	httpReq.Header.Set("Accept", "text/event-stream")

	resp, err := c.httpClient.Do(httpReq)
	if err != nil {
		return nil, fmt.Errorf("http do: %w", err)
	}
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		raw, _ := io.ReadAll(io.LimitReader(resp.Body, maxProviderResponseBytes))
		resp.Body.Close()
		return nil, parseHTTPError(resp, raw, "chat_completions", c.completionsURL)
	}

	log.Printf("[openai] using api=chat_completions_stream url=%s", c.completionsURL)
	return newChatStreamReader(resp), nil
}

// chatStreamReader translates a streaming chat-completions SSE body into
// Anthropic-style StreamEvents, satisfying the messageStream interface.
//
// The downstream assembler (internal/anthropic.StreamAssembler) appends every
// delta and stop to the most recently started block builder, so blocks MUST be
// emitted strictly sequentially: at most one block is open at a time. Reasoning
// and text are streamed live under that invariant; tool calls are buffered by
// index and emitted as complete, sequential blocks in finalize().
type chatStreamReader struct {
	resp    *http.Response
	scanner *bufio.Scanner
	buf     []anthropic.StreamEvent

	messageStartSent bool
	messageStopSent  bool
	streamID         string
	streamModel      string

	nextIndex int

	openKind         int // chatBlockNone | chatBlockReasoning | chatBlockText
	openIndex        int
	reasoningOpaque  string
	reasoningDetails []json.RawMessage

	toolOrder []int
	toolAccs  map[int]*chatStreamToolAcc

	finishReason string
	usage        *chatUsage
}

const (
	chatBlockNone = iota
	chatBlockReasoning
	chatBlockText
)

type chatStreamToolAcc struct {
	id   string
	name string
	args strings.Builder
}

func newChatStreamReader(resp *http.Response) *chatStreamReader {
	scanner := bufio.NewScanner(resp.Body)
	scanner.Buffer(make([]byte, 0, 64*1024), maxProviderResponseBytes)
	return &chatStreamReader{
		resp:     resp,
		scanner:  scanner,
		toolAccs: make(map[int]*chatStreamToolAcc),
	}
}

func (r *chatStreamReader) Next() (anthropic.StreamEvent, error) {
	for {
		if len(r.buf) > 0 {
			ev := r.buf[0]
			r.buf = r.buf[1:]
			return ev, nil
		}
		if r.messageStopSent {
			return anthropic.StreamEvent{}, io.EOF
		}

		line, ok := r.readData()
		if !ok {
			// Surface read errors (truncated stream, oversized token) instead of
			// silently finalizing a partial response as if it succeeded.
			if err := r.scanner.Err(); err != nil {
				return anthropic.StreamEvent{}, fmt.Errorf("read chat stream: %w", err)
			}
			// Clean EOF without an explicit [DONE]; finalize gracefully.
			r.finalize()
			continue
		}
		if line == "[DONE]" {
			r.finalize()
			continue
		}

		var chunk chatCompletionChunk
		if err := json.Unmarshal([]byte(line), &chunk); err != nil {
			return anthropic.StreamEvent{}, fmt.Errorf("decode chat stream event: %w", err)
		}
		if chunk.Error != nil {
			return anthropic.StreamEvent{}, &RequestError{
				StatusCode: chatErrorStatus(chunk.Error, http.StatusBadRequest),
				Body:       chatErrorBody(chunk.Error),
				API:        "chat_completions_stream",
			}
		}
		if len(chunk.Choices) > 0 {
			choice := chunk.Choices[0]
			if choice.Error != nil {
				return anthropic.StreamEvent{}, &RequestError{
					StatusCode: chatErrorStatus(choice.Error, http.StatusBadGateway),
					Body:       chatErrorBody(choice.Error),
					API:        "chat_completions_stream",
				}
			}
			if strings.EqualFold(strings.TrimSpace(choice.FinishReason), "error") {
				return anthropic.StreamEvent{}, &RequestError{
					StatusCode: http.StatusBadGateway,
					Body:       "chat completion stream finished with an error",
					API:        "chat_completions_stream",
				}
			}
		}
		r.translateChunk(chunk)
	}
}

// readData returns the JSON payload of the next "data:" SSE line, or ok=false
// when the underlying stream is exhausted.
func (r *chatStreamReader) readData() (string, bool) {
	for r.scanner.Scan() {
		line := strings.TrimSpace(r.scanner.Text())
		if line == "" || !strings.HasPrefix(line, "data:") {
			continue
		}
		return strings.TrimSpace(strings.TrimPrefix(line, "data:")), true
	}
	return "", false
}

func (r *chatStreamReader) Close() error {
	if r.resp != nil && r.resp.Body != nil {
		return r.resp.Body.Close()
	}
	return nil
}

func (r *chatStreamReader) emit(ev anthropic.StreamEvent) {
	r.buf = append(r.buf, ev)
}

func (r *chatStreamReader) ensureMessageStart() {
	if r.messageStartSent {
		return
	}
	r.messageStartSent = true
	r.emit(anthropic.StreamEvent{
		Type: anthropic.EventMessageStart,
		Message: &anthropic.CreateMessageResponse{
			ID:    r.streamID,
			Model: r.streamModel,
			Role:  anthropic.RoleAssistant,
		},
	})
}

func reasoningTextFromDetails(details []json.RawMessage) string {
	var out strings.Builder
	for _, raw := range details {
		var detail struct {
			Text    string `json:"text"`
			Summary string `json:"summary"`
		}
		if json.Unmarshal(raw, &detail) != nil {
			continue
		}
		if detail.Text != "" {
			out.WriteString(detail.Text)
		} else if detail.Summary != "" {
			out.WriteString(detail.Summary)
		}
	}
	return out.String()
}

func (r *chatStreamReader) translateChunk(chunk chatCompletionChunk) {
	if chunk.ID != "" {
		r.streamID = chunk.ID
	}
	if chunk.Model != "" {
		r.streamModel = chunk.Model
	}
	if chunk.Usage != nil {
		r.usage = chunk.Usage
	}
	if len(chunk.Choices) == 0 {
		return
	}
	r.ensureMessageStart()

	choice := chunk.Choices[0]
	delta := choice.Delta

	if delta.ReasoningOpaque != "" {
		r.reasoningOpaque = delta.ReasoningOpaque
	}
	if len(delta.ReasoningDetails) > 0 {
		r.reasoningDetails = append(r.reasoningDetails, delta.ReasoningDetails...)
	}

	reasoningText := firstNonEmptyString(delta.Reasoning, delta.ReasoningContent, delta.ReasoningText)
	if reasoningText == "" {
		reasoningText = reasoningTextFromDetails(delta.ReasoningDetails)
	}
	if reasoningText != "" || len(delta.ReasoningDetails) > 0 {
		if r.openKind != chatBlockReasoning {
			r.startBlock(chatBlockReasoning, anthropic.ContentBlock{Type: "thinking"})
		}
		if reasoningText != "" {
			r.emit(anthropic.StreamEvent{
				Type:  anthropic.EventContentBlockDelta,
				Index: r.openIndex,
				Delta: &anthropic.DeltaBlock{Type: "thinking_delta", Thinking: reasoningText, Text: reasoningText},
			})
		}
	}

	if delta.Content != "" {
		if r.openKind != chatBlockText {
			r.startBlock(chatBlockText, anthropic.ContentBlock{Type: "text"})
		}
		r.emit(anthropic.StreamEvent{
			Type:  anthropic.EventContentBlockDelta,
			Index: r.openIndex,
			Delta: &anthropic.DeltaBlock{Type: "text_delta", Text: delta.Content},
		})
	}

	// Surface refusal deltas as text so the reason reaches the caller instead
	// of producing an empty (and wrongly retried) response.
	if delta.Refusal != "" {
		if r.openKind != chatBlockText {
			r.startBlock(chatBlockText, anthropic.ContentBlock{Type: "text"})
			r.emit(anthropic.StreamEvent{
				Type:  anthropic.EventContentBlockDelta,
				Index: r.openIndex,
				Delta: &anthropic.DeltaBlock{Type: "text_delta", Text: "The model refused to respond: "},
			})
		}
		r.emit(anthropic.StreamEvent{
			Type:  anthropic.EventContentBlockDelta,
			Index: r.openIndex,
			Delta: &anthropic.DeltaBlock{Type: "text_delta", Text: delta.Refusal},
		})
	}

	// Tool calls are buffered by provider index and only emitted, fully formed
	// and strictly sequential, in finalize(). This keeps the single-open-block
	// invariant even when arguments stream across chunks or arrive after text.
	for _, tc := range delta.ToolCalls {
		acc := r.toolAccs[tc.Index]
		if acc != nil && tc.ID != "" && acc.id != "" && tc.ID != acc.id {
			// Some gateways reuse a provider index for a second tool call.
			// Move the finished accumulator to a synthetic (negative) key so
			// the new call gets a fresh one instead of merging into it.
			synth := -(len(r.toolOrder) + 1)
			r.toolAccs[synth] = acc
			for i := len(r.toolOrder) - 1; i >= 0; i-- {
				if r.toolOrder[i] == tc.Index {
					r.toolOrder[i] = synth
					break
				}
			}
			delete(r.toolAccs, tc.Index)
			acc = nil
		}
		if acc == nil {
			acc = &chatStreamToolAcc{}
			r.toolAccs[tc.Index] = acc
			r.toolOrder = append(r.toolOrder, tc.Index)
		}
		if tc.ID != "" {
			acc.id = tc.ID
		}
		if tc.Function.Name != "" {
			acc.name = tc.Function.Name
		}
		if tc.Function.Arguments != "" {
			acc.args.WriteString(tc.Function.Arguments)
		}
	}

	if choice.FinishReason != "" {
		r.finishReason = choice.FinishReason
	}
}

// startBlock closes any currently open block and opens a new one at the next
// index, preserving the assembler's single-open-block requirement.
func (r *chatStreamReader) startBlock(kind int, block anthropic.ContentBlock) {
	r.closeOpenBlock()
	r.openIndex = r.nextIndex
	r.nextIndex++
	r.openKind = kind
	cb := block
	r.emit(anthropic.StreamEvent{
		Type:         anthropic.EventContentBlockStart,
		Index:        r.openIndex,
		ContentBlock: &cb,
	})
}

// closeOpenBlock emits the stop (and, for reasoning, the signature) for the
// currently open reasoning/text block, if any.
func (r *chatStreamReader) closeOpenBlock() {
	switch r.openKind {
	case chatBlockReasoning:
		signature := r.reasoningOpaque
		if len(r.reasoningDetails) > 0 {
			if raw, err := json.Marshal(r.reasoningDetails); err == nil {
				signature = encodeOpenRouterReasoningDetails(raw)
			}
		}
		if signature != "" {
			r.emit(anthropic.StreamEvent{
				Type:  anthropic.EventContentBlockDelta,
				Index: r.openIndex,
				Delta: &anthropic.DeltaBlock{Type: "signature_delta", Signature: signature},
			})
		}
		// Opaque state belongs to the block being closed; a later reasoning
		// block must carry its own.
		r.reasoningOpaque = ""
		r.reasoningDetails = nil
		r.emit(anthropic.StreamEvent{Type: anthropic.EventContentBlockStop, Index: r.openIndex})
	case chatBlockText:
		r.emit(anthropic.StreamEvent{Type: anthropic.EventContentBlockStop, Index: r.openIndex})
	}
	r.openKind = chatBlockNone
}

func (r *chatStreamReader) finalize() {
	if r.messageStopSent {
		return
	}
	r.ensureMessageStart()
	r.closeOpenBlock()

	for _, idx := range r.toolOrder {
		acc := r.toolAccs[idx]
		if acc == nil {
			continue
		}
		blockIdx := r.nextIndex
		r.nextIndex++
		r.emit(anthropic.StreamEvent{
			Type:  anthropic.EventContentBlockStart,
			Index: blockIdx,
			ContentBlock: &anthropic.ContentBlock{
				Type: "tool_use",
				ID:   acc.id,
				Name: acc.name,
			},
		})
		if args := acc.args.String(); args != "" {
			r.emit(anthropic.StreamEvent{
				Type:  anthropic.EventContentBlockDelta,
				Index: blockIdx,
				Delta: &anthropic.DeltaBlock{Type: "input_json_delta", PartialJSON: args},
			})
		}
		r.emit(anthropic.StreamEvent{Type: anthropic.EventContentBlockStop, Index: blockIdx})
	}

	convertedUsage := chatUsageToAnthropic(r.usage)
	usage := &convertedUsage
	r.emit(anthropic.StreamEvent{
		Type: anthropic.EventMessageDelta,
		Delta: &anthropic.DeltaBlock{
			Type:       "message_delta",
			StopReason: string(chatStopReason(r.finishReason, len(r.toolOrder) > 0)),
		},
		Usage: usage,
	})
	r.emit(anthropic.StreamEvent{Type: anthropic.EventMessageStop})
	r.messageStopSent = true
}

package openai

import (
	"context"
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"strings"
	"testing"

	"github.com/gratefulagents/sdk/internal/anthropic"
)

// drainChatStream feeds an SSE body through the reader and reassembles the
// final Anthropic response, mirroring the production consumer.
func drainChatStream(t *testing.T, sse string) *anthropic.CreateMessageResponse {
	t.Helper()
	reader := newChatStreamReader(&http.Response{Body: io.NopCloser(strings.NewReader(sse))})
	assembler := anthropic.NewStreamAssembler()
	for {
		ev, err := reader.Next()
		if err == io.EOF {
			break
		}
		if err != nil {
			t.Fatalf("Next() error = %v", err)
		}
		assembler.Add(ev)
	}
	return assembler.Response()
}

func TestCopilotStreamDropsBudgetOnlyOpenRouterReasoning(t *testing.T) {
	var body string
	client := &Client{
		completionsURL: "https://api.githubcopilot.com/chat/completions",
		httpClient: &http.Client{Transport: roundTripFunc(func(req *http.Request) (*http.Response, error) {
			raw, _ := io.ReadAll(req.Body)
			body = string(raw)
			return &http.Response{
				StatusCode: http.StatusOK,
				Header:     http.Header{"Content-Type": []string{"text/event-stream"}},
				Body:       io.NopCloser(strings.NewReader("data: [DONE]\n\n")),
			}, nil
		})},
	}
	stream, err := client.sendChatStream(context.Background(), anthropic.CreateMessageRequest{
		Model:     "claude-sonnet-4.6",
		MaxTokens: 4096,
		Thinking:  &anthropic.ThinkingConfig{Type: "enabled", BudgetTokens: 2048},
	})
	if err != nil {
		t.Fatal(err)
	}
	defer stream.Close()
	if strings.Contains(body, `"reasoning":`) {
		t.Fatalf("Copilot request leaked nested OpenRouter reasoning: %s", body)
	}
}

func TestChatStreamReaderReasoningAndText(t *testing.T) {
	sse := strings.Join([]string{
		`data: {"id":"chatcmpl-1","model":"claude-opus-4.8","choices":[{"index":0,"delta":{"role":"assistant"}}]}`,
		`data: {"choices":[{"index":0,"delta":{"reasoning_text":"Let me think"}}]}`,
		`data: {"choices":[{"index":0,"delta":{"reasoning_text":" about it."}}]}`,
		`data: {"choices":[{"index":0,"delta":{"reasoning_opaque":"SIG123","content":"Hello"}}]}`,
		`data: {"choices":[{"index":0,"delta":{"content":" world"}}]}`,
		`data: {"choices":[{"index":0,"delta":{},"finish_reason":"stop"}]}`,
		`data: {"choices":[],"usage":{"prompt_tokens":10,"completion_tokens":5,"total_tokens":15}}`,
		`data: [DONE]`,
		``,
	}, "\n\n")

	resp := drainChatStream(t, sse)

	if len(resp.Content) != 2 {
		t.Fatalf("content blocks = %d, want 2: %+v", len(resp.Content), resp.Content)
	}
	thinking := resp.Content[0]
	if thinking.Type != "thinking" {
		t.Fatalf("block[0].Type = %q, want thinking", thinking.Type)
	}
	if thinking.Thinking != "Let me think about it." {
		t.Fatalf("thinking text = %q", thinking.Thinking)
	}
	if thinking.Signature != "SIG123" {
		t.Fatalf("thinking signature = %q, want SIG123 (reasoning_opaque round-trip)", thinking.Signature)
	}
	text := resp.Content[1]
	if text.Type != "text" || text.Text != "Hello world" {
		t.Fatalf("text block = %+v, want type=text text=%q", text, "Hello world")
	}
	if resp.StopReason != anthropic.StopReasonEndTurn {
		t.Fatalf("stop reason = %q, want end_turn", resp.StopReason)
	}
	if resp.Usage.InputTokens != 10 || resp.Usage.OutputTokens != 5 {
		t.Fatalf("usage = in:%d out:%d, want in:10 out:5", resp.Usage.InputTokens, resp.Usage.OutputTokens)
	}
}

// TestChatStreamReaderNarrationToolCallsQuirk covers the GitHub Copilot quirk
// where a plain narration turn finishes with finish_reason="tool_calls" but
// carries no tool calls. It must be treated as end_turn, not tool_use.
func TestChatStreamReaderNarrationToolCallsQuirk(t *testing.T) {
	sse := strings.Join([]string{
		`data: {"id":"c1","model":"claude-opus-4.8","choices":[{"index":0,"delta":{"content":"Working on it"}}]}`,
		`data: {"choices":[{"index":0,"delta":{},"finish_reason":"tool_calls"}]}`,
		`data: [DONE]`,
		``,
	}, "\n\n")

	resp := drainChatStream(t, sse)

	if resp.StopReason != anthropic.StopReasonEndTurn {
		t.Fatalf("stop reason = %q, want end_turn (narration tool_calls quirk)", resp.StopReason)
	}
	if len(resp.Content) != 1 || resp.Content[0].Type != "text" {
		t.Fatalf("content = %+v, want single text block", resp.Content)
	}
}

func TestChatStreamReaderToolCalls(t *testing.T) {
	sse := strings.Join([]string{
		`data: {"id":"c1","model":"claude-opus-4.8","choices":[{"index":0,"delta":{"tool_calls":[{"index":0,"id":"call_1","type":"function","function":{"name":"foo","arguments":"{\"a\":"}}]}}]}`,
		`data: {"choices":[{"index":0,"delta":{"tool_calls":[{"index":0,"function":{"arguments":"1}"}}]}}]}`,
		`data: {"choices":[{"index":0,"delta":{},"finish_reason":"tool_calls"}]}`,
		`data: [DONE]`,
		``,
	}, "\n\n")

	resp := drainChatStream(t, sse)

	if resp.StopReason != anthropic.StopReasonToolUse {
		t.Fatalf("stop reason = %q, want tool_use", resp.StopReason)
	}
	if len(resp.Content) != 1 {
		t.Fatalf("content blocks = %d, want 1: %+v", len(resp.Content), resp.Content)
	}
	tool := resp.Content[0]
	if tool.Type != "tool_use" || tool.ID != "call_1" || tool.Name != "foo" {
		t.Fatalf("tool block = %+v", tool)
	}
	if string(tool.Input) != `{"a":1}` {
		t.Fatalf("tool input = %q, want %q", string(tool.Input), `{"a":1}`)
	}
}

// TestChatStreamReaderMultipleToolCalls verifies that two streamed tool calls
// are reassembled as two distinct, correctly-attributed tool_use blocks (the
// assembler appends to the last builder, so blocks must be strictly sequential).
func TestChatStreamReaderMultipleToolCalls(t *testing.T) {
	sse := strings.Join([]string{
		`data: {"id":"c1","model":"claude-opus-4.8","choices":[{"index":0,"delta":{"tool_calls":[{"index":0,"id":"call_a","type":"function","function":{"name":"alpha","arguments":"{\"x\":1}"}}]}}]}`,
		`data: {"choices":[{"index":0,"delta":{"tool_calls":[{"index":1,"id":"call_b","type":"function","function":{"name":"beta","arguments":"{\"y\":2}"}}]}}]}`,
		`data: {"choices":[{"index":0,"delta":{},"finish_reason":"tool_calls"}]}`,
		`data: [DONE]`,
		``,
	}, "\n\n")

	resp := drainChatStream(t, sse)

	if len(resp.Content) != 2 {
		t.Fatalf("content blocks = %d, want 2: %+v", len(resp.Content), resp.Content)
	}
	a, b := resp.Content[0], resp.Content[1]
	if a.Type != "tool_use" || a.ID != "call_a" || a.Name != "alpha" || string(a.Input) != `{"x":1}` {
		t.Fatalf("tool[0] = %+v, want call_a/alpha/{\"x\":1}", a)
	}
	if b.Type != "tool_use" || b.ID != "call_b" || b.Name != "beta" || string(b.Input) != `{"y":2}` {
		t.Fatalf("tool[1] = %+v, want call_b/beta/{\"y\":2}", b)
	}
	if resp.StopReason != anthropic.StopReasonToolUse {
		t.Fatalf("stop reason = %q, want tool_use", resp.StopReason)
	}
}

// TestChatStreamReaderReasoningThenTool verifies a reasoning block followed by a
// tool call (no text) yields a thinking block with its signature plus the tool.
func TestChatStreamReaderReasoningThenTool(t *testing.T) {
	sse := strings.Join([]string{
		`data: {"id":"c1","model":"claude-opus-4.8","choices":[{"index":0,"delta":{"reasoning_text":"pick a tool"}}]}`,
		`data: {"choices":[{"index":0,"delta":{"reasoning_opaque":"SIGZ","tool_calls":[{"index":0,"id":"call_1","type":"function","function":{"name":"foo","arguments":"{}"}}]}}]}`,
		`data: {"choices":[{"index":0,"delta":{},"finish_reason":"tool_calls"}]}`,
		`data: [DONE]`,
		``,
	}, "\n\n")

	resp := drainChatStream(t, sse)

	if len(resp.Content) != 2 {
		t.Fatalf("content blocks = %d, want 2 (thinking+tool): %+v", len(resp.Content), resp.Content)
	}
	if resp.Content[0].Type != "thinking" || resp.Content[0].Thinking != "pick a tool" || resp.Content[0].Signature != "SIGZ" {
		t.Fatalf("thinking block = %+v", resp.Content[0])
	}
	if resp.Content[1].Type != "tool_use" || resp.Content[1].Name != "foo" {
		t.Fatalf("tool block = %+v", resp.Content[1])
	}
	if resp.StopReason != anthropic.StopReasonToolUse {
		t.Fatalf("stop reason = %q, want tool_use", resp.StopReason)
	}
}

func TestToAnthropicResponseFromChatReasoning(t *testing.T) {
	resp := chatCompletionResponse{
		ID:    "msg_1",
		Model: "claude-opus-4.8",
		Choices: []chatChoice{{
			Message: chatMessage{
				Role:            "assistant",
				Content:         "done",
				ReasoningText:   "because reasons",
				ReasoningOpaque: "OPAQUE1",
			},
			FinishReason: "stop",
		}},
	}
	out, err := toAnthropicResponseFromChat(resp)
	if err != nil {
		t.Fatal(err)
	}
	if len(out.Content) != 2 {
		t.Fatalf("content = %d, want 2 (thinking+text): %+v", len(out.Content), out.Content)
	}
	if out.Content[0].Type != "thinking" || out.Content[0].Thinking != "because reasons" {
		t.Fatalf("thinking block = %+v", out.Content[0])
	}
	if out.Content[0].Signature != "OPAQUE1" {
		t.Fatalf("signature = %q, want OPAQUE1", out.Content[0].Signature)
	}
	if out.StopReason != anthropic.StopReasonEndTurn {
		t.Fatalf("stop reason = %q, want end_turn", out.StopReason)
	}
}

func TestToChatMessagesRoundTripsReasoning(t *testing.T) {
	req := anthropic.CreateMessageRequest{
		Messages: []anthropic.Message{{
			Role: anthropic.RoleAssistant,
			Content: []anthropic.ContentBlock{
				{Type: "thinking", Thinking: "deep thought", Signature: "SIGabc"},
				anthropic.NewTextBlock("answer"),
			},
		}},
	}
	msgs, err := toChatMessages(req)
	if err != nil {
		t.Fatal(err)
	}
	if len(msgs) != 1 {
		t.Fatalf("messages = %d, want 1", len(msgs))
