}

func sanitizeLogBody(body string) string {
	trimmed := strings.TrimSpace(body)
	var parsed any
	if json.Unmarshal([]byte(trimmed), &parsed) == nil {
		if sanitized, err := json.Marshal(sanitizeLogJSONValue(parsed)); err == nil {
			trimmed = string(sanitized)
		}
	}
	trimmed = strings.Join(strings.Fields(trimmed), " ")
	for _, redactor := range logSecretRedactors {
		trimmed = redactor.ReplaceAllString(trimmed, "${1}[REDACTED]${2}")
	}
	if len(trimmed) > 500 {
		return trimmed[:500] + "...(truncated)"
	}
	return trimmed
}

func sanitizeLogJSONValue(value any) any {
	switch typed := value.(type) {
	case map[string]any:
		out := make(map[string]any, len(typed))
		for key, child := range typed {
			lower := strings.ToLower(key)
			if strings.Contains(lower, "token") || strings.Contains(lower, "secret") || strings.Contains(lower, "password") || strings.Contains(lower, "auth") || strings.Contains(lower, "cookie") || strings.Contains(lower, "key") {
				out[key] = "[REDACTED]"
			} else {
				out[key] = sanitizeLogJSONValue(child)
			}
		}
		return out
	case []any:
		out := make([]any, len(typed))
		for i, child := range typed {
			out[i] = sanitizeLogJSONValue(child)
		}
		return out
	default:
		return value
	}
}

type chatCompletionRequest struct {
	Model          string             `json:"model"`
	Models         []string           `json:"models,omitempty"`
	Messages       []chatMessage      `json:"messages"`
	MaxTokens      int                `json:"max_tokens,omitempty"`
	Tools          []chatToolDef      `json:"tools,omitempty"`
	ResponseFormat any                `json:"response_format,omitempty"`
	Reasoning      any                `json:"reasoning,omitempty"`
	Stream         bool               `json:"stream,omitempty"`
	StreamOptions  *chatStreamOptions `json:"stream_options,omitempty"`
	// ReasoningEffort is GitHub Copilot's flat reasoning control (distinct from
	// the nested OpenRouter "reasoning" object above). Copilot returns plaintext
	// reasoning in message.reasoning_text only when this is sent.
	ReasoningEffort string `json:"reasoning_effort,omitempty"`
}

type chatStreamOptions struct {
	IncludeUsage bool `json:"include_usage,omitempty"`
}

type chatMessage struct {
	Role       string         `json:"role"`
	Content    any            `json:"content,omitempty"`
	ToolCallID string         `json:"tool_call_id,omitempty"`
	ToolCalls  []chatToolCall `json:"tool_calls,omitempty"`
	// Refusal is set by the API on refused responses; never sent in requests.
	Refusal string `json:"refusal,omitempty"`

	// OpenRouter normalizes visible reasoning into Reasoning and returns the
	// provider-native, potentially encrypted blocks in ReasoningDetails. The
	// details must be passed back byte-for-byte on a later tool turn.
	Reasoning        string          `json:"reasoning,omitempty"`
	ReasoningContent string          `json:"reasoning_content,omitempty"`
	ReasoningDetails json.RawMessage `json:"reasoning_details,omitempty"`

	// Copilot-specific reasoning round-trip fields. ReasoningText is only sent
	// back when ReasoningOpaque (the encrypted multi-turn signature) is present.
	ReasoningText   string `json:"reasoning_text,omitempty"`
	ReasoningOpaque string `json:"reasoning_opaque,omitempty"`
}

