const openRouterReasoningDetailsPrefix = "openrouter-reasoning-details:"

// encodeOpenRouterReasoningDetails stores OpenRouter's opaque reasoning_details
// array in the provider-neutral reasoning signature field. Base64 keeps it safe
// across snapshots and lets the next chat request restore the exact JSON.
func encodeOpenRouterReasoningDetails(details json.RawMessage) string {
	if len(details) == 0 || !json.Valid(details) {
		return ""
	}
	return openRouterReasoningDetailsPrefix + base64.RawStdEncoding.EncodeToString(details)
}

func decodeOpenRouterReasoningDetails(signature string) json.RawMessage {
	encoded := strings.TrimPrefix(signature, openRouterReasoningDetailsPrefix)
	if encoded == signature || encoded == "" {
		return nil
	}
	raw, err := base64.RawStdEncoding.DecodeString(encoded)
	if err != nil || !json.Valid(raw) {
		return nil
	}
	return json.RawMessage(raw)
}

func chatErrorStatus(apiErr *chatAPIError, fallback int) int {
	if apiErr == nil || len(apiErr.Code) == 0 {
		return fallback
	}
	var code int
	if json.Unmarshal(apiErr.Code, &code) == nil && code >= 400 && code <= 599 {
		return code
	}
	return fallback
}

func chatErrorBody(apiErr *chatAPIError) string {
	if apiErr == nil {
		return "unknown chat completion error"
	}
	body, err := json.Marshal(apiErr)
	if err == nil {
		return string(body)
	}
	return apiErr.Message
}

// withModelFallbacks builds the OpenRouter-style "models" array for a request.
// It returns nil when no fallbacks are configured so the request body is
// unchanged and only "model" is sent. When fallbacks exist, the primary model is
// placed first, followed by the fallbacks in order, with empty entries and
// duplicates removed so the provider tries each candidate at most once.
func withModelFallbacks(primary string, fallbacks []string) []string {
	if len(fallbacks) == 0 {
		return nil
	}
	ordered := append([]string{primary}, fallbacks...)
	seen := make(map[string]bool, len(ordered))
	out := make([]string, 0, len(ordered))
	for _, m := range ordered {
		m = strings.TrimSpace(m)
		if m == "" || seen[m] {
			continue
		}
		seen[m] = true
		out = append(out, m)
	}
	if len(out) <= 1 {
		return nil
	}
	return out
}

func toChatRequest(req anthropic.CreateMessageRequest) (chatCompletionRequest, error) {
	chatMsgs, err := toChatMessages(req)
	if err != nil {
		return chatCompletionRequest{}, err
	}

	out := chatCompletionRequest{
		Model:     req.Model,
		Messages:  chatMsgs,
		MaxTokens: req.MaxTokens,
	}
	// OpenRouter unifies reasoning control via the request "reasoning" field.
	// Prefer an explicit effort when present; otherwise preserve an explicit
	// token budget. Previously the chat path silently discarded ThinkingBudget.
	if effort := strings.TrimSpace(req.ReasoningEffort); effort != "" {
		out.Reasoning = map[string]any{"effort": effort}
	} else if req.Thinking != nil && req.Thinking.Type == "enabled" && req.Thinking.BudgetTokens > 0 {
		out.Reasoning = map[string]any{"max_tokens": req.Thinking.BudgetTokens}
	}

	if len(req.Tools) > 0 {
		out.Tools = make([]chatToolDef, 0, len(req.Tools))
		for _, t := range req.Tools {
			params, err := normalizedToolSchema(t.Name, t.InputSchema)
			if err != nil {
				return chatCompletionRequest{}, err
			}
			out.Tools = append(out.Tools, chatToolDef{
				Type: "function",
				Function: chatFunction{
					Name:        t.Name,
					Description: t.Description,
					Parameters:  params,
				},
			})
		}
	}
	if req.OutputSchema != nil {
		format, err := chatResponseFormat(req.OutputSchema)
		if err != nil {
			return chatCompletionRequest{}, err
		}
		out.ResponseFormat = format
	}

	return out, nil
}

func toChatMessages(req anthropic.CreateMessageRequest) ([]chatMessage, error) {
	var msgs []chatMessage

	if len(req.System) > 0 {
		var parts []string
		for _, s := range req.System {
			if text := strings.TrimSpace(s.Text); text != "" {
				parts = append(parts, text)
			}
		}
		if len(parts) > 0 {
			msgs = append(msgs, chatMessage{
				Role:    "system",
				Content: strings.Join(parts, "\n\n"),
			})
		}
	}

	for _, m := range req.Messages {
		switch m.Role {
		case anthropic.RoleUser:
			var textParts []string
			var imageParts []map[string]any
			// Tool results are collected separately and emitted before any
			// accumulated user text: strict chat APIs reject "tool" messages
			// that do not immediately follow the assistant "tool_calls" turn.
			var toolMsgs []chatMessage
			// flushUser emits pending text/images as one user message: a plain
			// string when text-only, or multipart content when images exist.
			flushUser := func() {
				if len(textParts) == 0 && len(imageParts) == 0 {
					return
				}
				if len(imageParts) == 0 {
					msgs = append(msgs, chatMessage{
						Role:    "user",
						Content: strings.Join(textParts, "\n"),
					})
				} else {
					parts := make([]map[string]any, 0, len(imageParts)+1)
					if len(textParts) > 0 {
						parts = append(parts, map[string]any{"type": "text", "text": strings.Join(textParts, "\n")})
					}
					parts = append(parts, imageParts...)
					msgs = append(msgs, chatMessage{Role: "user", Content: parts})
				}
				textParts = nil
				imageParts = nil
			}
			for _, block := range m.Content {
				switch block.Type {
				case "text":
					if strings.TrimSpace(block.Text) != "" {
						textParts = append(textParts, block.Text)
					}
				case "image":
					if block.Source == nil || strings.TrimSpace(block.Source.Data) == "" {
						continue
					}
					mediaType := strings.TrimSpace(block.Source.MediaType)
					if mediaType == "" {
						mediaType = "image/png"
					}
					imageParts = append(imageParts, map[string]any{
						"type": "image_url",
						"image_url": map[string]any{
							"url": fmt.Sprintf("data:%s;base64,%s", mediaType, block.Source.Data),
						},
					})
				case "tool_result":
					content := block.Content
					if content == "" {
						content = "(no output)"
					}
					toolMsgs = append(toolMsgs, chatMessage{
						Role:       "tool",
						ToolCallID: block.ToolUseID,
						Content:    content,
					})
				}
			}
			msgs = append(msgs, toolMsgs...)
			flushUser()

		case anthropic.RoleAssistant:
			var textParts []string
			var toolCalls []chatToolCall
			var reasoningText, reasoningOpaque string
			var reasoningDetails json.RawMessage
			for _, block := range m.Content {
				switch block.Type {
				case "text":
					if strings.TrimSpace(block.Text) != "" {
						textParts = append(textParts, block.Text)
					}
				case "thinking":
					if reasoningText == "" {
						reasoningText = block.Thinking
					}
					if details := decodeOpenRouterReasoningDetails(block.Signature); len(details) > 0 {
						reasoningDetails = details
					} else if reasoningOpaque == "" {
						reasoningOpaque = block.Signature
					}
				case "tool_use":
					args := strings.TrimSpace(string(block.Input))
					if args == "" {
						args = "{}"
					}
					toolCalls = append(toolCalls, chatToolCall{
						ID:   block.ID,
						Type: "function",
						Function: chatFunction{
							Name:      block.Name,
							Arguments: args,
						},
					})
				}
			}

			msg := chatMessage{Role: "assistant"}
			if len(textParts) > 0 {
				msg.Content = strings.Join(textParts, "\n")
			}
			if len(toolCalls) > 0 {
				msg.ToolCalls = toolCalls
			}
			if len(reasoningDetails) > 0 {
				// OpenRouter requires the complete provider-native sequence to be
				// echoed unchanged, especially when continuing after tool use.
				msg.ReasoningDetails = reasoningDetails
			} else if reasoningOpaque != "" {
				// Copilot multi-turn reasoning: only resend reasoning_text alongside
				// its encrypted signature.
				msg.ReasoningOpaque = reasoningOpaque
				msg.ReasoningText = reasoningText
			} else if reasoningText != "" {
				// OpenRouter accepts plaintext reasoning for models that do not emit
				// structured details. Copilot strips this field before sending.
				msg.Reasoning = reasoningText
			}
			if msg.Content == nil && len(msg.ToolCalls) == 0 {
				msg.Content = ""
			}
			msgs = append(msgs, msg)
		}
	}

	return msgs, nil
}

func toAnthropicResponseFromChat(resp chatCompletionResponse) (*anthropic.CreateMessageResponse, error) {
	if len(resp.Choices) == 0 {
		return nil, fmt.Errorf("chat completion returned no choices")
	}

	choice := resp.Choices[0]
	if choice.Error != nil {
		return nil, &RequestError{
			StatusCode: chatErrorStatus(choice.Error, http.StatusBadGateway),
			Body:       chatErrorBody(choice.Error),
			API:        "chat_completions",
		}
	}
	if strings.EqualFold(strings.TrimSpace(choice.FinishReason), "error") {
		return nil, &RequestError{
			StatusCode: http.StatusBadGateway,
			Body:       "chat completion finished with an error",
			API:        "chat_completions",
		}
	}

	out := &anthropic.CreateMessageResponse{
		ID:    resp.ID,
		Type:  "message",
		Role:  anthropic.RoleAssistant,
		Model: resp.Model,
	}
	if resp.Usage != nil {
		out.Usage = chatUsageToAnthropic(resp.Usage)
	}

	// Reasoning first. OpenRouter returns visible text in reasoning (with
	// reasoning_content as a compatibility alias) and opaque provider state in
	// reasoning_details; Copilot uses reasoning_text/reasoning_opaque.
	reasoning := firstNonEmptyString(
		choice.Message.Reasoning,
		choice.Message.ReasoningContent,
		choice.Message.ReasoningText,
	)
	signature := choice.Message.ReasoningOpaque
	if len(choice.Message.ReasoningDetails) > 0 {
		signature = encodeOpenRouterReasoningDetails(choice.Message.ReasoningDetails)
	}
	if strings.TrimSpace(reasoning) != "" || signature != "" {
		block := anthropic.NewThinkingBlock(reasoning)
		block.Signature = signature
		out.Content = append(out.Content, block)
	}

	text := extractTextContent(choice.Message.Content)
	if strings.TrimSpace(text) != "" {
		out.Content = append(out.Content, anthropic.NewTextBlock(text))
	}
	// Surface refusals as text so the caller sees the reason instead of an
	// empty (and wrongly retried) response.
	if refusal := strings.TrimSpace(choice.Message.Refusal); refusal != "" {
		out.Content = append(out.Content, anthropic.NewTextBlock("The model refused to respond: "+refusal))
	}
	for idx, tc := range choice.Message.ToolCalls {
		id := tc.ID
		if id == "" {
			id = fmt.Sprintf("call_%d", idx)
		}
		args := normalizeArguments(tc.Function.Arguments)
		out.Content = append(out.Content, anthropic.NewToolUseBlock(id, tc.Function.Name, args))
	}

	out.StopReason = chatStopReason(choice.FinishReason, len(choice.Message.ToolCalls) > 0)

	return out, nil
}

func firstNonEmptyString(values ...string) string {
	for _, value := range values {
		if strings.TrimSpace(value) != "" {
			return value
		}
	}
	return ""
}

func chatUsageToAnthropic(usage *chatUsage) anthropic.Usage {
	if usage == nil {
		return anthropic.Usage{}
	}
	out := anthropic.Usage{
		InputTokens:  usage.PromptTokens,
		OutputTokens: usage.CompletionTokens,
	}
	if usage.PromptTokensDetails != nil {
		out.CacheReadInputTokens = usage.PromptTokensDetails.CachedTokens
		out.CacheCreationInputTokens = usage.PromptTokensDetails.CacheWriteTokens
	}
	return out
}

func extractTextContent(content any) string {
	switch v := content.(type) {
	case string:
		return v
	case []any:
		var parts []string
		for _, item := range v {
			m, ok := item.(map[string]any)
			if !ok {
				continue
			}
			if t, _ := m["type"].(string); t != "text" {
				continue
			}
			if text, _ := m["text"].(string); text != "" {
				parts = append(parts, text)
			}
		}
		return strings.Join(parts, "\n")
	default:
		return ""
	}
}

// chatStopReason derives the Anthropic stop reason from a chat-completions
// finish_reason and whether the turn actually produced tool calls. GitHub
// Copilot reports finish_reason="tool_calls" on plain narration turns that have
// no tool calls; mapping those to tool_use corrupts the agent loop (it waits for
// tool outputs that never arrive). When no tool calls are present, such turns
// are treated as end_turn. This is what previously forced Claude-on-Copilot onto
// the /v1/messages shim.
//
// finish_reason="length" wins over tool calls: a truncated turn is not a
// complete tool-use turn (its arguments may be cut mid-JSON), and reporting
// tool_use would mask the truncation entirely.
func chatStopReason(reason string, hasToolCalls bool) anthropic.StopReason {
	if reason == "length" {
		return anthropic.StopReasonMaxTokens
	}
	if hasToolCalls {
		return anthropic.StopReasonToolUse
	}
	return anthropic.StopReasonEndTurn
}

func responseToEvents(resp *anthropic.CreateMessageResponse) []anthropic.StreamEvent {
	events := make([]anthropic.StreamEvent, 0, len(resp.Content)*3+3)

	events = append(events, anthropic.StreamEvent{
		Type: anthropic.EventMessageStart,
		Message: &anthropic.CreateMessageResponse{
			ID:    resp.ID,
			Model: resp.Model,
			Role:  anthropic.RoleAssistant,
			Usage: anthropic.Usage{
				InputTokens: resp.Usage.InputTokens,
			},
		},
	})

	for i, block := range resp.Content {
		// Carry all block-start metadata so the downstream assembler can
		// round-trip reasoning IDs, encrypted content, phases, and compaction
		// provenance. Signature is intentionally replayed via signature_delta
		// below rather than duplicated here. Accumulated payloads (text,
		// thinking, tool input) are replayed as deltas.
		start := anthropic.ContentBlock{
			Type:             block.Type,
			ID:               block.ID,
			Name:             block.Name,
			Phase:            block.Phase,
			Data:             block.Data,
			Content:          block.Content,
			CreatedBy:        block.CreatedBy,
			EncryptedContent: block.EncryptedContent,
		}
		events = append(events, anthropic.StreamEvent{
			Type:         anthropic.EventContentBlockStart,
			Index:        i,
			ContentBlock: &start,
		})

		switch block.Type {
		case "text":
			events = append(events, anthropic.StreamEvent{
				Type:  anthropic.EventContentBlockDelta,
				Index: i,
				Delta: &anthropic.DeltaBlock{
					Type: "text_delta",
					Text: block.Text,
				},
			})
		case "thinking":
			events = append(events, anthropic.StreamEvent{
				Type:  anthropic.EventContentBlockDelta,
				Index: i,
				Delta: &anthropic.DeltaBlock{
					Type:     "thinking_delta",
					Thinking: block.Thinking,
					Text:     block.Thinking,
				},
			})
			if block.Signature != "" {
				events = append(events, anthropic.StreamEvent{
					Type:  anthropic.EventContentBlockDelta,
					Index: i,
					Delta: &anthropic.DeltaBlock{
						Type:      "signature_delta",
						Signature: block.Signature,
					},
				})
			}
		case "tool_use":
			events = append(events, anthropic.StreamEvent{
				Type:  anthropic.EventContentBlockDelta,
				Index: i,
				Delta: &anthropic.DeltaBlock{
					Type:        "input_json_delta",
					PartialJSON: string(block.Input),
				},
			})
		}

		events = append(events, anthropic.StreamEvent{
			Type:  anthropic.EventContentBlockStop,
			Index: i,
		})
	}

	events = append(events, anthropic.StreamEvent{
		Type: anthropic.EventMessageDelta,
		Delta: &anthropic.DeltaBlock{
			Type:       "message_delta",
			StopReason: string(resp.StopReason),
			EndTurn:    resp.EndTurn,
		},
		Usage: &anthropic.Usage{
			InputTokens:              resp.Usage.InputTokens,
			OutputTokens:             resp.Usage.OutputTokens,
			CacheReadInputTokens:     resp.Usage.CacheReadInputTokens,
			CacheCreationInputTokens: resp.Usage.CacheCreationInputTokens,
		},
	})

	events = append(events, anthropic.StreamEvent{Type: anthropic.EventMessageStop})
	return events
}

func normalizeArguments(raw string) json.RawMessage {
	args := strings.TrimSpace(raw)
	if args == "" {
		return json.RawMessage("{}")
	}
	if json.Valid([]byte(args)) {
		return json.RawMessage(args)
	}
	return json.RawMessage("{}")
}

