func TestResponseFailedErrorRetryClassification(t *testing.T) {
	tests := []struct {
		name      string
		err       ResponseFailedError
		retryable bool
		nonRetry  string
	}{
		{
			name:      "server error retries",
			err:       ResponseFailedError{Status: "failed", Code: "server_error"},
			retryable: true,
		},
		{
			name:      "overloaded server retries",
			err:       ResponseFailedError{Status: "failed", Code: "server_is_overloaded"},
			retryable: true,
		},
		{
			name:      "unknown incomplete retries",
			err:       ResponseFailedError{Status: "incomplete"},
			retryable: true,
		},
		{
			name:     "content filter incomplete does not retry",
			err:      ResponseFailedError{Status: "incomplete", IncompleteReason: "content_filter"},
			nonRetry: "content_filter",
		},
		{
			name:     "invalid image does not retry",
			err:      ResponseFailedError{Status: "failed", Code: "invalid_image"},
			nonRetry: "invalid_image",
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := tt.err.Retryable(); got != tt.retryable {
				t.Fatalf("Retryable() = %v, want %v", got, tt.retryable)
			}
			if got := tt.err.NonRetryableReason(); got != tt.nonRetry {
				t.Fatalf("NonRetryableReason() = %q, want %q", got, tt.nonRetry)
			}
		})
	}
}

func TestSanitizeLogBodyRedactsSecrets(t *testing.T) {
	bodies := []string{
		`{"diagnostic":"invalid request","access_token":"access-secret","password_hint":"password-secret","nested":{"authorization":"Bearer bearer-secret","cookie_value":"cookie-secret","public_key":"key-secret"},"message":"failed for sk-testsecret"}`,
		`invalid request: refresh_token=refresh-plain client_secret: client-plain authorization=Basic basic-plain cookie="cookie-plain"`,
	}
	for _, body := range bodies {
		got := sanitizeLogBody(body)
		for _, secret := range []string{"access-secret", "password-secret", "bearer-secret", "cookie-secret", "key-secret", "sk-testsecret", "refresh-plain", "client-plain", "basic-plain", "cookie-plain"} {
			if strings.Contains(got, secret) {
				t.Fatalf("sanitizeLogBody leaked %q in %q", secret, got)
			}
		}
		if !strings.Contains(got, "invalid request") {
			t.Fatalf("sanitizeLogBody removed diagnostic from %q", got)
		}
	}
}

