package openai

// Post-provider-compaction wire-shape regression (run chat-gf-all-aqvafl):
// the runner's post-compaction input — [user task msg, compaction blob,
// preserved recent tool exchanges incl. encrypted reasoning, carry-forward] —
// must serialize losslessly into the /responses input array. Guards against
// union-marshaling or item-filtering regressions in toResponseInputItems.

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	anthropic "github.com/gratefulagents/sdk/internal/anthropic"
)

func TestPostCompactionInputSerializesLosslessly(t *testing.T) {
	var captured map[string]any
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		raw, _ := io.ReadAll(r.Body)
		_ = json.Unmarshal(raw, &captured)
		w.Header().Set("Content-Type", "text/event-stream")
		for _, line := range []string{
			`{"type":"response.created","response":{"id":"resp_x","model":"gpt-5.5","usage":{"input_tokens":1}}}`,
			`{"type":"response.content_part.added","output_index":0,"part":{"type":"output_text"}}`,
			`{"type":"response.output_text.delta","output_index":0,"delta":"ok"}`,
			`{"type":"response.output_text.done","output_index":0}`,
			`{"type":"response.completed","response":{"id":"resp_x","model":"gpt-5.5","usage":{"input_tokens":2,"output_tokens":3},"output":[{"type":"message","role":"assistant","content":[{"type":"output_text","text":"ok"}]}]}}`,
		} {
			fmt.Fprintf(w, "data: %s\n\n", line)
		}
		fmt.Fprint(w, "data: [DONE]\n\n")
	}))
	defer server.Close()

	blob := strings.Repeat("gAAAAABqTjbtNHpESmuLhzgebwPRb8js4ITPVs2kgIvD60IA7PX1", 600) // ~31k chars

	msgs := []anthropic.Message{
		// provider compact output: user task msg, then blob
		{Role: anthropic.RoleUser, Content: []anthropic.ContentBlock{anthropic.NewTextBlock("ensure that whenever an agentrun is deleted from any trigger it deletes all the information about the agent run from the db..")}},
		{Role: anthropic.RoleAssistant, Content: []anthropic.ContentBlock{func() anthropic.ContentBlock {
			b := anthropic.NewCompactionBlock("cmp_001", blob, "openai")
			return b
		}()}},
	}
	// 14 preserved recent items: 7 tool_use/tool_result pairs (incl. one reasoning)
	for i := 0; i < 7; i++ {
		callID := fmt.Sprintf("call_recent_%d", i)
		think := anthropic.NewThinkingBlock("")
		think.ID = fmt.Sprintf("rs_recent_%d", i)
		think.EncryptedContent = "enc_reasoning_" + strings.Repeat("x", 200)
		msgs = append(msgs,
			anthropic.Message{Role: anthropic.RoleAssistant, Content: []anthropic.ContentBlock{think}},
			anthropic.Message{Role: anthropic.RoleAssistant, Content: []anthropic.ContentBlock{anthropic.NewToolUseBlock(callID, "read_file", json.RawMessage(`{"path":"internal/store/postgres/collaboration.go"}`))}},
			anthropic.Message{Role: anthropic.RoleUser, Content: []anthropic.ContentBlock{anthropic.NewToolResultBlock(callID, strings.Repeat("line of file content\n", 40), false)}},
		)
	}
	// carry-forward message
	msgs = append(msgs, anthropic.Message{Role: anthropic.RoleUser, Content: []anthropic.ContentBlock{anthropic.NewTextBlock("[COMPACTION CARRY-FORWARD]\nLive AgentRun state: mode=chat step=awaiting-user\n## Durable Working State\nCurrent objective: ...")}})

	req := anthropic.CreateMessageRequest{
		Model:     "gpt-5.5",
		MaxTokens: 8192,
		System:    []anthropic.SystemBlock{{Type: "text", Text: "you are an agent"}},
		Messages:  msgs,
		Thinking:  &anthropic.ThinkingConfig{BudgetTokens: 8192},
		Tools: []anthropic.ToolDefinition{
			{Name: "read_file", Description: "read", InputSchema: json.RawMessage(`{"type":"object","properties":{"path":{"type":"string"}}}`)},
		},
		CompactionThreshold: 200000,
	}

	client := NewClient("sk-test", WithBaseURL(server.URL+"/v1"))
	if _, err := client.CreateMessage(context.Background(), req); err != nil {
		t.Fatalf("CreateMessage: %v", err)
	}

	input, _ := captured["input"].([]any)
	counts := map[string]int{}
	for _, it := range input {
		m := it.(map[string]any)
		ty, _ := m["type"].(string)
		if ty == "" {
			ty = fmt.Sprintf("role=%v(message)", m["role"])
		}
		counts[ty]++
	}

	// expectations from the runner's post-compaction currentInput
	want := map[string]int{
		"compaction":           1,
		"function_call":        7,
		"function_call_output": 7,
		"reasoning":            7,
	}
	for ty, n := range want {
		if counts[ty] != n {
			t.Errorf("wire %s = %d, want %d", ty, counts[ty], n)
		}
	}
	// 2 user text messages (task + carry-forward)
	if got := counts["message"] + counts["role=user(message)"] + counts["role=<nil>(message)"]; got < 2 {
		t.Errorf("wire text messages = %d, want >= 2 (task + carry-forward)", got)
	}
}

package agentsdk

import (
	"bytes"
	"encoding/json"
	"fmt"
	"hash/fnv"
	"strings"
)

const (
	DefaultMaxAutoLoops = 200

	autoTrackerMaxRecentTools  = 10
	autoTrackerMaxRecentErrors = 5

	// Reasoning-heavy models (e.g. claude-fable-5) legitimately produce a few
	// consecutive planning turns with no tool calls before acting; the
	// breaker allows five such turns and the strong warning starts at three.
	defaultCBMaxNoToolTurns   = 5
	cbNoToolWarningTurns      = 3
	defaultCBMaxSameErrors    = 5
	defaultCBMaxRepeatedCycle = 6
)

// AutoTracker tracks autonomous-loop progress for smart continuation and
// circuit breakers.
type AutoTracker struct {
	consecutiveNoToolTurns int
	recentToolCalls        []string
	recentToolSignatures   []string
	recentErrors           []string
	toolCallCount          int
}

// CircuitBreakerResult reports whether an autonomous loop should pause.
type CircuitBreakerResult struct {
	Tripped bool
	Reason  string
}

// Update analyzes the latest runner result items and updates tracker state.
func (t *AutoTracker) Update(newItems []RunItem) {
	if t == nil {
		return
	}
	var turnToolCalls []string
	var turnToolSignatures []string
	var turnErrors []string
	for _, item := range newItems {
		if item.Type == RunItemToolCall && item.ToolCall != nil {
			turnToolCalls = append(turnToolCalls, item.ToolCall.Name)
			turnToolSignatures = append(turnToolSignatures, toolCallSignature(item.ToolCall.Name, item.ToolCall.Input))
		}
		if item.Type == RunItemToolOutput && item.ToolOutput != nil && item.ToolOutput.IsError {
			msg := item.ToolOutput.Content
			if len(msg) > 200 {
				msg = truncateTitle(msg, 200)
			}
			turnErrors = append(turnErrors, msg)
		}
	}

	if len(turnToolCalls) == 0 {
		t.consecutiveNoToolTurns++
	} else {
		t.consecutiveNoToolTurns = 0
	}
	t.toolCallCount += len(turnToolCalls)

	for i, call := range turnToolCalls {
		t.recentToolCalls = append(t.recentToolCalls, call)
		t.recentToolSignatures = append(t.recentToolSignatures, turnToolSignatures[i])
		if len(t.recentToolCalls) > autoTrackerMaxRecentTools {
			t.recentToolCalls = t.recentToolCalls[1:]
			t.recentToolSignatures = t.recentToolSignatures[1:]
		}
	}
	for _, errText := range turnErrors {
		t.recentErrors = append(t.recentErrors, errText)
		if len(t.recentErrors) > autoTrackerMaxRecentErrors {
			t.recentErrors = t.recentErrors[1:]
		}
	}
}

func (t *AutoTracker) ConsecutiveNoToolTurns() int {
	if t == nil {
		return 0
	}
	return t.consecutiveNoToolTurns
}

func (t *AutoTracker) ToolCallCount() int {
	if t == nil {
		return 0
	}
	return t.toolCallCount
}

func (t *AutoTracker) consecutiveSameError() (int, string) {
	if t == nil || len(t.recentErrors) == 0 {
		return 0, ""
	}
	last := t.recentErrors[len(t.recentErrors)-1]
	count := 0
	for i := len(t.recentErrors) - 1; i >= 0; i-- {
		if t.recentErrors[i] == last {
			count++
		} else {
			break
		}
	}
	return count, last
}

// detectRepetitiveCycle reports whether the recent tool calls form a repeating
// cycle of *identical* calls. Calls are compared on an argument-aware signature
// (tool name + input), so ordinary exploration - reading several different
// files, or alternating grep/read across distinct targets - is not mistaken for
// a loop. The returned slice contains the tool names of the detected cycle for
// human-readable reporting, and the count is the number of verified
// consecutive repetitions at the end of the buffer (at least 2 when detected).
func (t *AutoTracker) detectRepetitiveCycle() (bool, []string, int) {
	if t == nil {
		return false, nil, 0
	}
	sigs := t.recentToolSignatures
	names := t.recentToolCalls
	if len(sigs) != len(names) {
		return false, nil, 0
	}
	for cycleLen := 2; cycleLen <= 3; cycleLen++ {
		if len(sigs) < cycleLen*2 {
			continue
		}
		cycle := sigs[len(sigs)-cycleLen:]
		matched := 0
		for i := len(sigs) - 1; i >= 0; i-- {
			offset := len(sigs) - 1 - i
			if sigs[i] != cycle[cycleLen-1-offset%cycleLen] {
				break
			}
			matched++
		}
		repetitions := matched / cycleLen
		if repetitions >= 2 {
			return true, names[len(names)-cycleLen:], repetitions
		}
	}
	return false, nil, 0
}

// toolCallSignature returns a compact, argument-aware identity for a tool call
// so that two calls are considered "the same" only when both the tool name and
// the (whitespace-normalized) input match.
func toolCallSignature(name string, input json.RawMessage) string {
	h := fnv.New64a()
	_, _ = h.Write([]byte(name))
	_, _ = h.Write([]byte{0})
	if len(input) > 0 {
		var buf bytes.Buffer
		if err := json.Compact(&buf, input); err == nil {
			_, _ = h.Write(buf.Bytes())
		} else {
			_, _ = h.Write(input)
		}
	}
	return fmt.Sprintf("%s:%x", name, h.Sum64())
}

// CheckCircuitBreakers reports hard-stop autonomous loop conditions.
func (t *AutoTracker) CheckCircuitBreakers() CircuitBreakerResult {
	if t == nil {
		return CircuitBreakerResult{}
	}
	if t.consecutiveNoToolTurns >= defaultCBMaxNoToolTurns {
		return CircuitBreakerResult{
			Tripped: true,
			Reason:  fmt.Sprintf("Agent stalled - no tool calls in %d consecutive turns", t.consecutiveNoToolTurns),
		}
	}
	errCount, errMsg := t.consecutiveSameError()
	if errCount >= defaultCBMaxSameErrors {
		return CircuitBreakerResult{
			Tripped: true,
			Reason:  fmt.Sprintf("Agent stuck - same error repeated %d times: %s", errCount, truncateTitle(errMsg, 100)),
		}
	}
	if cycling, cycle, repetitions := t.detectRepetitiveCycle(); cycling {
		if repetitions >= defaultCBMaxRepeatedCycle/len(cycle) {
			return CircuitBreakerResult{
				Tripped: true,
				Reason:  fmt.Sprintf("Agent stuck in tool loop - pattern [%s] repeated %d times", strings.Join(cycle, "->"), repetitions),
			}
		}
	}
	return CircuitBreakerResult{}
}

// BuildSmartNudge generates a context-aware autonomous continuation prompt.
func BuildSmartNudge(t *AutoTracker, phase string) string {
	if t == nil {
		t = &AutoTracker{}
	}
	phaseHint := ""
	if phase != "" {
		phaseHint = fmt.Sprintf(" You are in the %s phase.", phase)
	}

	if cycling, cycle, _ := t.detectRepetitiveCycle(); cycling {
		return fmt.Sprintf("[SYSTEM] Detected repetitive tool pattern: [%s]. You appear stuck in a loop. Step back, reassess your approach, and try something fundamentally different. If the current subtask is blocked, skip it and move on to other work.%s",
			strings.Join(cycle, " -> "), autonomousFinishGuidance())
	}

	errCount, errMsg := t.consecutiveSameError()
	if errCount >= 3 {
		return fmt.Sprintf("[SYSTEM] You have hit the same error %d times: \"%s\". Do NOT retry the same approach. Try a fundamentally different strategy, or skip this subtask and move on.%s",
			errCount, truncateTitle(errMsg, 120), autonomousFinishGuidance())
	}

	if t.consecutiveNoToolTurns >= cbNoToolWarningTurns {
		return fmt.Sprintf("[SYSTEM] WARNING: You have produced text without tool calls for %d consecutive turns. In autonomous mode, every turn MUST include at least one tool call. Do NOT output only text.", t.consecutiveNoToolTurns) + autonomousFinishGuidance()
	}
	if t.consecutiveNoToolTurns >= 1 {
		return "[SYSTEM] You produced text without tool calls. In autonomous mode, every turn must include at least one tool call." + autonomousFinishGuidance()
	}
	return fmt.Sprintf("[SYSTEM] Continue.%s %d tool calls so far. Use tools to make progress.%s", phaseHint, t.toolCallCount, autonomousFinishGuidance())
}

func autonomousFinishGuidance() string {
	return " Finish is a hard stop, not a progress report: if you named any backlog item, TODO, follow-up, remaining risk, or next step, call a tool for the top item now. Call finish only when no actionable work remains or a concrete external blocker prevents useful tool progress."
}

// truncateTitle trims s to at most maxLen runes (not bytes) so multi-byte
// UTF-8 characters are never split mid-sequence.
func truncateTitle(s string, maxLen int) string {
	s = strings.TrimSpace(s)
	runes := []rune(s)
	if len(runes) <= maxLen {
		return s
	}
	if maxLen <= 3 {
		return string(runes[:maxLen])
	}
	return string(runes[:maxLen-3]) + "..."
}

package agentsdk

import (
	"encoding/json"
	"strings"
	"testing"
)

func TestAutoTrackerDetectsNoToolStall(t *testing.T) {
	t.Parallel()

	var tracker AutoTracker
	// Reasoning models may legitimately plan without tools for a few turns;
	// the breaker must stay quiet below the threshold and trip at it.
	for i := 0; i < defaultCBMaxNoToolTurns-1; i++ {
		tracker.Update([]RunItem{{Type: RunItemMessage, Message: &MessageOutput{Text: "thinking"}}})
		if cb := tracker.CheckCircuitBreakers(); cb.Tripped {
			t.Fatalf("circuit breaker tripped after %d no-tool turns: %+v", i+1, cb)
		}
	}
	tracker.Update([]RunItem{{Type: RunItemMessage, Message: &MessageOutput{Text: "thinking"}}})
	cb := tracker.CheckCircuitBreakers()
	if !cb.Tripped || !strings.Contains(cb.Reason, "no tool calls") {
		t.Fatalf("circuit breaker = %+v, want no-tool stall", cb)
	}
}

func TestBuildSmartNudgeWarnsOnRepeatedNoToolTurns(t *testing.T) {
	t.Parallel()

	var tracker AutoTracker
	for i := 0; i < cbNoToolWarningTurns; i++ {
		tracker.Update([]RunItem{{Type: RunItemMessage, Message: &MessageOutput{Text: "done soon"}}})
	}

	nudge := BuildSmartNudge(&tracker, "shipping")
	if !strings.Contains(nudge, "WARNING") || !strings.Contains(nudge, "tool calls") {
		t.Fatalf("nudge = %q, want warning", nudge)
	}
	for _, want := range []string{
		"Finish is a hard stop",
		"not a progress report",
		"backlog item",
		"call a tool for the top item",
	} {
		if !strings.Contains(nudge, want) {
			t.Fatalf("nudge = %q, want %q", nudge, want)
		}
	}
}

func TestAutoTrackerDetectsRepeatedToolCycle(t *testing.T) {
	t.Parallel()

	var tracker AutoTracker
	for i := 0; i < 3; i++ {
		tracker.Update([]RunItem{
			{Type: RunItemToolCall, ToolCall: &ToolCallData{Name: "grep"}},
			{Type: RunItemToolCall, ToolCall: &ToolCallData{Name: "bash"}},
		})
	}
	cb := tracker.CheckCircuitBreakers()
	if !cb.Tripped || !strings.Contains(cb.Reason, "tool loop") {
		t.Fatalf("circuit breaker = %+v, want tool-loop breaker", cb)
	}
}

func TestAutoTrackerIgnoresDiverseExploration(t *testing.T) {
	t.Parallel()

	// Reading different files and alternating grep/read_file on distinct targets
	// must not be mistaken for a stuck loop, even though the tool *names* repeat.
	var tracker AutoTracker
	calls := []struct{ name, input string }{
		{"grep", `{"pattern":"funcA"}`},
		{"read_file", `{"path":"a.go"}`},
		{"read_file", `{"path":"b.go"}`},
		{"grep", `{"pattern":"funcB"}`},
		{"read_file", `{"path":"c.go"}`},
		{"grep", `{"pattern":"funcC"}`},
		{"read_file", `{"path":"d.go"}`},
		{"read_file", `{"path":"e.go"}`},
		{"grep", `{"pattern":"funcD"}`},
		{"read_file", `{"path":"f.go"}`},
	}
	for _, c := range calls {
		tracker.Update([]RunItem{{Type: RunItemToolCall, ToolCall: &ToolCallData{Name: c.name, Input: json.RawMessage(c.input)}}})
		if cb := tracker.CheckCircuitBreakers(); cb.Tripped {
			t.Fatalf("circuit breaker tripped on diverse exploration: %s", cb.Reason)
		}
	}
	if nudge := BuildSmartNudge(&tracker, "plan"); strings.Contains(nudge, "stuck in a loop") {
		t.Fatalf("nudge = %q, should not warn about a loop during diverse exploration", nudge)
	}
}

func TestAutoTrackerDetectsIdenticalCallLoop(t *testing.T) {
	t.Parallel()

	// The same tool with the same input repeated is a genuine no-progress loop.
	var tracker AutoTracker
	for i := 0; i < 6; i++ {
		tracker.Update([]RunItem{{Type: RunItemToolCall, ToolCall: &ToolCallData{Name: "read_file", Input: json.RawMessage(`{"path":"same.go"}`)}}})
	}
	cb := tracker.CheckCircuitBreakers()
	if !cb.Tripped || !strings.Contains(cb.Reason, "tool loop") {
		t.Fatalf("circuit breaker = %+v, want tool-loop breaker for identical repeated calls", cb)
	}
}

package agentsdk

import (
	"os/exec"
	"strings"
	"testing"
)

func TestSDKDoesNotDependOnOperatorPackages(t *testing.T) {
	t.Parallel()

	cmd := exec.Command("go", "list", "-deps", "-f", "{{.ImportPath}}", ".")
	out, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("go list SDK deps: %v\n%s", err, out)
	}

	forbidden := []string{
		"github.com/gratefulagents/sdk/api/",
		"github.com/gratefulagents/sdk/internal/controller/",
		"github.com/gratefulagents/sdk/internal/agentplatform",
		"github.com/gratefulagents/sdk/internal/anthropic",
		"github.com/gratefulagents/sdk/internal/openai",
		"github.com/gratefulagents/sdk/internal/store/",
		"github.com/gratefulagents/sdk/internal/tools",
		"github.com/aws/",
		"github.com/anthropics/",
		"github.com/openai/",
		"go.opentelemetry.io/",
		"k8s.io/",
		"sigs.k8s.io/",
	}
	for _, dep := range strings.Fields(string(out)) {
		for _, prefix := range forbidden {
			if strings.HasPrefix(dep, prefix) {
				t.Fatalf("SDK dependency %q crosses forbidden operator boundary %q", dep, prefix)
			}
		}
	}
}

package agentsdk

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"log"
	"regexp"
	"strings"
	"time"

	sdkmode "github.com/gratefulagents/sdk/pkg/agentsdk/mode"
)

// Cursor identifies the host's current position in a session stream.
type Cursor struct {
	MessageID int64  `json:"message_id,omitempty"`
	Token     string `json:"token,omitempty"`
}

// UserMessage is an SDK-native user input loaded from a host session store.
type UserMessage struct {
	ID        int64
	Content   string
	Mode      string
	CreatedAt time.Time
	Images    []ImageAttachment
}

// WorkingState is durable host-maintained context injected into the loop.
type WorkingState struct {
	Goal                  string
	CurrentMode           string
	CurrentStep           string
	LastUserMessage       string
	LastAssistantSummary  string
	RecentTurnSummaries   []string
	HistoryFloorMessageID int64
	LastResponseID        string
	Data                  map[string]any
}

// ToolApprovalRequest is a host-native approval question.
type ToolApprovalRequest struct {
	ToolName string
	Input    []byte
	Reason   string
}

// PermissionMode is the host-level permission mode understood by ChatLoop.
type PermissionMode string

const (
	PermissionModeReadOnly         PermissionMode = "read-only"
	PermissionModeWorkspaceWrite   PermissionMode = "workspace-write"
	PermissionModeDangerFullAccess PermissionMode = "danger-full-access"
)

// MCPServerConfig is the SDK-native shape for one MCP server entry.
type MCPServerConfig struct {
	Type    string            `json:"type,omitempty"`
	Command string            `json:"command,omitempty"`
	Args    []string          `json:"args,omitempty"`
	Env     map[string]string `json:"env,omitempty"`
}

// SessionStore loads user inputs and persists new run items.
type SessionStore interface {
	LoadMessages(ctx context.Context, cursor Cursor, limit int) ([]UserMessage, Cursor, error)
	AppendRunItems(ctx context.Context, items []RunItem) error
	WorkingState(ctx context.Context) (WorkingState, error)
}

// RunStatusSink publishes loop progress to the host platform.
type RunStatusSink interface {
	PublishProgress(ctx context.Context, snapshot ProgressSnapshot) error
	PublishTraceID(ctx context.Context, traceID string) error
	PublishFinalResult(ctx context.Context, result *RunResult) error
}

// ConfigSource supplies dynamic host configuration without leaking platform types.
//
// ChatLoop applies PermissionMode, ModeSnapshot (read-only tool-access clamp
// and turn constraints), GuardrailRules, ModeDirective, and HandoffHistory in
// prepareRun. RoleCatalog is surfaced for hosts that build specialist tools
// (e.g. via BuildSpecialistToolsFromCatalog in a PlatformToolFactory); ChatLoop
// does not consume it directly.
type ConfigSource interface {
	PermissionMode(ctx context.Context) (PermissionMode, error)
	ModeSnapshot(ctx context.Context) (*sdkmode.TemplateSpec, error)
	GuardrailRules(ctx context.Context) ([]GuardrailRule, error)
	RoleCatalog(ctx context.Context) (RoleCatalog, error)
	ModeDirective(ctx context.Context) (string, error)
	HandoffHistory(ctx context.Context) ([]RunItem, error)
}

// TraceStore is the trace persistence surface consumed by ChatLoop.
type TraceStore interface {
	RunDir(ctx context.Context) (string, error)
	AppendCategory(ctx context.Context, category, text string) error
	WriteFile(ctx context.Context, name string, data []byte) error
	Finalize(ctx context.Context, result *RunResult) error
}

// ApprovalGate asks the host whether a tool or MCP break-glass request is allowed.
type ApprovalGate interface {
	ApproveTool(ctx context.Context, request ToolApprovalRequest) (bool, string, error)
}

// PlatformToolFactory injects host/platform-specific tools into the SDK runner.
type PlatformToolFactory interface {
	BuildTools(ctx context.Context, base []Tool) ([]Tool, error)
}

// ChatLoopOptions configures a ChatLoop.
type ChatLoopOptions struct {
	Runner              *Runner
	Agent               *Agent
	SessionStore        SessionStore
	RunStatusSink       RunStatusSink
	ConfigSource        ConfigSource
	TraceStore          TraceStore
	ApprovalGate        ApprovalGate
	PlatformToolFactory PlatformToolFactory
	RunConfig           RunConfig
	Cursor              Cursor
	MessageLimit        int
	MaxResumes          int
}

// ChatLoop is the SDK-owned high-level orchestration primitive.
type ChatLoop struct {
	opts ChatLoopOptions
}

func NewChatLoop(opts ChatLoopOptions) *ChatLoop {
	return &ChatLoop{opts: opts}
}

// Cursor returns the loop's current session-store position. After Run it
// reflects the messages already consumed, so hosts can persist it and later
// loops (or a rebuilt ChatLoop) do not re-feed the same messages.
func (l *ChatLoop) Cursor() Cursor {
	if l == nil {
		return Cursor{}
	}
	return l.opts.Cursor
}

// Run executes a host-backed chat loop.
//
// The loop can resume after SDK tool approvals. Hosts still own their platform
// side effects through SessionStore, ConfigSource, ApprovalGate, RunStatusSink,
// TraceStore, and PlatformToolFactory.
func (l *ChatLoop) Run(ctx context.Context) (*RunResult, error) {
	if l == nil {
		return nil, fmt.Errorf("chat loop is nil")
	}
	if l.opts.Runner == nil {
		return nil, fmt.Errorf("chat loop runner is required")
	}
	if l.opts.Agent == nil {
		return nil, fmt.Errorf("chat loop agent is required")
	}

	agent, runCfg, err := l.prepareRun(ctx)
	if err != nil {
		return nil, err
	}
	inputItems, err := l.loadInputItems(ctx)
	if err != nil {
		return nil, err
	}
	if runCfg.Trace == nil && strings.TrimSpace(runCfg.PromptCacheNamespace) == "" {
		runCfg.PromptCacheNamespace = NewTrace(agent.Name).ID
	}

	history := append([]RunItem(nil), inputItems...)
	var allNewItems []RunItem
	var allResponses []ModelResponse
	var allToolInputResults []ToolGuardrailResult
	var allToolOutputResults []ToolGuardrailResult
	var totalUsage Usage
	maxResumes := l.opts.MaxResumes
	if maxResumes <= 0 {
		maxResumes = 12
	}

	for resumes := 0; ; resumes++ {
		result, err := l.opts.Runner.Run(ctx, &agent, history, runCfg)
		if err != nil {
			return nil, err
		}
		allNewItems = append(allNewItems, result.NewItems...)
		allResponses = append(allResponses, result.RawResponses...)
		allToolInputResults = append(allToolInputResults, result.ToolInputGuardrailResults...)
		allToolOutputResults = append(allToolOutputResults, result.ToolOutputGuardrailResults...)
		totalUsage.Add(result.Usage)
		if len(result.FinalHistory) > 0 {
			// Adopt the runner's post-run conversation state: mid-run
			// compaction rewrites the input items, so replaying
			// history+NewItems would resend the uncompacted transcript.
			history = append([]RunItem(nil), result.FinalHistory...)
		} else {
			history = append(history, result.NewItems...)
		}
		if l.opts.SessionStore != nil {
			if err := l.opts.SessionStore.AppendRunItems(ctx, result.NewItems); err != nil {
				combined := combineLoopResult(result, allNewItems, allResponses, allToolInputResults, allToolOutputResults, totalUsage)
				return combined, fmt.Errorf("append run items: %w", err)
			}
		}

		combined := combineLoopResult(result, allNewItems, allResponses, allToolInputResults, allToolOutputResults, totalUsage)
		if result.IsInterrupted() {
			if l.opts.ApprovalGate == nil {
				// No gate can resolve the pending calls: pair each dangling
				// tool_use with a denied approval and error output so the
				// persisted history stays replayable.
				denied := denyPendingInterruptions(result.AllInterruptions(), "tool call denied: no approval gate configured")
				if len(denied) > 0 {
					allNewItems = append(allNewItems, denied...)
					if l.opts.SessionStore != nil {
						if err := l.opts.SessionStore.AppendRunItems(ctx, denied); err != nil {
							combined = combineLoopResult(result, allNewItems, allResponses, allToolInputResults, allToolOutputResults, totalUsage)
							return combined, fmt.Errorf("append denied approval items: %w", err)
						}
					}
					combined = combineLoopResult(result, allNewItems, allResponses, allToolInputResults, allToolOutputResults, totalUsage)
				}
				return l.finalize(ctx, combined)
			}
			if resumes >= maxResumes {
				return combined, fmt.Errorf("too many chat loop resumes after approval interruption")
			}
			// Resolve every pending approval from the turn: parallel tool
			// calls can trigger several, and each pending tool_use needs a
			// paired output before the next model call.
			var items []RunItem
			var resolveErr error
			var pauseRequested bool
			for _, pending := range result.AllInterruptions() {
				resolved, inputResults, outputResults, shouldPause, err := l.resolveToolApproval(ctx, &agent, runCfg, pending)
				items = append(items, resolved...)
				allToolInputResults = append(allToolInputResults, inputResults...)
				allToolOutputResults = append(allToolOutputResults, outputResults...)
				if shouldPause {
					pauseRequested = true
				}
				if err != nil {
					resolveErr = err
					break
				}
			}
			if len(items) > 0 {
				allNewItems = append(allNewItems, items...)
				history = append(history, items...)
			}
			if len(items) > 0 && l.opts.SessionStore != nil {
				if err := l.opts.SessionStore.AppendRunItems(ctx, items); err != nil {
					combined = combineLoopResult(result, allNewItems, allResponses, allToolInputResults, allToolOutputResults, totalUsage)
					return combined, fmt.Errorf("append approval items: %w", err)
				}
			}
			combined = combineLoopResult(result, allNewItems, allResponses, allToolInputResults, allToolOutputResults, totalUsage)
			if resolveErr != nil {
				return combined, resolveErr
			}
			if pauseRequested {
				// An approved tool requested a pause (ToolResult.ShouldPause);
				// hand control back to the host like the runner's own pause
				// path instead of immediately resuming another model call.
				// The approvals were resolved above, so the interrupted
				// result's pending state must not leak: clear the
				// interruption fields and adopt the loop's history (which
				// includes the resolved approval + tool output items) so
				// hosts neither re-prompt for the same approval nor replay
				// an unpaired tool call.
				combined.Interruption = nil
				combined.Interruptions = nil
				combined.FinalHistory = append([]RunItem(nil), history...)
				return l.finalize(ctx, combined)
			}
			continue
		}

		return l.finalize(ctx, combined)
	}
}

func (l *ChatLoop) prepareRun(ctx context.Context) (Agent, RunConfig, error) {
	agent := *l.opts.Agent
	runCfg := l.opts.RunConfig

	if l.opts.ConfigSource != nil {
		mode, err := l.opts.ConfigSource.PermissionMode(ctx)
		if err != nil {
			return Agent{}, RunConfig{}, fmt.Errorf("load permission mode: %w", err)
		}
		if runCfg.ToolPolicy == nil {
			runCfg.ToolPolicy = toolPolicyFromPermissionMode(mode)
		}
		if runCfg.ToolAccessLevel == "" {
			runCfg.ToolAccessLevel = toolAccessLevelFromPermissionMode(mode)
		}
		if directive, err := l.opts.ConfigSource.ModeDirective(ctx); err != nil {
			return Agent{}, RunConfig{}, fmt.Errorf("load mode directive: %w", err)
		} else if strings.TrimSpace(directive) != "" {
			runCfg.AdditionalInstructions = strings.TrimSpace(runCfg.AdditionalInstructions + "\n\n" + directive)
		}
		if rules, err := l.opts.ConfigSource.GuardrailRules(ctx); err != nil {
			return Agent{}, RunConfig{}, fmt.Errorf("load guardrail rules: %w", err)
		} else if len(rules) > 0 {
			inputGuardrails, outputGuardrails, errs := compileToolGuardrailsFromRules(rules)
			if len(errs) > 0 {
				return Agent{}, RunConfig{}, fmt.Errorf("compile guardrail rules: %w", errors.Join(errs...))
			}
			// Copy before appending: runCfg shares slice headers with
			// l.opts.RunConfig, and appending in place could write into a
			// host-owned backing array shared across loops or Run calls.
			runCfg.ToolInputGuardrails = append(append([]ToolInputGuardrail(nil), runCfg.ToolInputGuardrails...), inputGuardrails...)
			runCfg.ToolOutputGuardrails = append(append([]ToolOutputGuardrail(nil), runCfg.ToolOutputGuardrails...), outputGuardrails...)
		}
		if snapshot, err := l.opts.ConfigSource.ModeSnapshot(ctx); err != nil {
			return Agent{}, RunConfig{}, fmt.Errorf("load mode snapshot: %w", err)
		} else if snapshot != nil {
			// A read-only mode clamps tool access regardless of what the
			// permission mode granted (mirrors runtime/builder enforcement).
			if NormalizeToolAccessLevel(ToolAccessLevel(snapshot.ToolAccess)) == ToolAccessLevelReadOnly {
				runCfg.ToolAccessLevel = ToolAccessLevelReadOnly
			}
			if snapshot.Constraints != nil {
				if runCfg.MaxTurns == 0 && snapshot.Constraints.MaxTurns > 0 {
					runCfg.MaxTurns = snapshot.Constraints.MaxTurns
				}
				if runCfg.SubAgentMaxTurns == 0 && snapshot.Constraints.SubAgentMaxTurns > 0 {
					runCfg.SubAgentMaxTurns = snapshot.Constraints.SubAgentMaxTurns
				}
			}
		}
	}

	if l.opts.SessionStore != nil {
		state, err := l.opts.SessionStore.WorkingState(ctx)
		if err != nil {
			return Agent{}, RunConfig{}, fmt.Errorf("load working state: %w", err)
		}
		if state.LastAssistantSummary != "" || state.CurrentStep != "" {
			runCfg.WorkingStateContext = BuildWorkingStateContext(state)
		}
	}

	if l.opts.PlatformToolFactory != nil {
		tools, err := l.opts.PlatformToolFactory.BuildTools(ctx, agent.Tools)
		if err != nil {
			return Agent{}, RunConfig{}, fmt.Errorf("build platform tools: %w", err)
		}
		agent.Tools = tools
	}
	return agent, runCfg, nil
}

func (l *ChatLoop) loadInputItems(ctx context.Context) ([]RunItem, error) {
	var inputItems []RunItem
	if l.opts.ConfigSource != nil {
		history, err := l.opts.ConfigSource.HandoffHistory(ctx)
		if err != nil {
			return nil, fmt.Errorf("load handoff history: %w", err)
		}
		inputItems = append(inputItems, history...)
	}
	if l.opts.SessionStore != nil {
		limit := l.opts.MessageLimit
		if limit <= 0 {
			limit = 50
		}
		// Drain the store page by page so messages beyond one page are not
		// silently dropped; the advancing cursor is kept on the loop so a
		// later Run does not re-feed already consumed messages.
		for {
			messages, next, err := l.opts.SessionStore.LoadMessages(ctx, l.opts.Cursor, limit)
			if err != nil {
				return nil, fmt.Errorf("load session messages: %w", err)
			}
			for _, msg := range messages {
				if strings.TrimSpace(msg.Content) == "" && len(msg.Images) == 0 {
					continue
				}
				inputItems = append(inputItems, RunItem{
					Type:    RunItemMessage,
					Message: &MessageOutput{Text: msg.Content, Images: msg.Images},
				})
			}
			cursorAdvanced := next != l.opts.Cursor
			l.opts.Cursor = next
			if len(messages) < limit || !cursorAdvanced {
				break
			}
		}
	}
	return inputItems, nil
}

func compileToolGuardrailsFromRules(rules []GuardrailRule) ([]ToolInputGuardrail, []ToolOutputGuardrail, []error) {
	var inputGuardrails []ToolInputGuardrail
	var outputGuardrails []ToolOutputGuardrail
	var errs []error

	for _, rule := range rules {
		rule := rule
		re, err := regexp.Compile(rule.Regex)
		if err != nil {
			errs = append(errs, fmt.Errorf("invalid regex in guardrail rule %q: %w", rule.Name, err))
			continue
		}

		action, actionErr := normalizeGuardrailRuleAction(rule)
		if actionErr != nil {
			errs = append(errs, actionErr)
			continue
		}
		rule.Action = action

		switch rule.Type {
		case "tool-input":
			inputGuardrails = append(inputGuardrails, ToolInputGuardrail{
				Name: fmt.Sprintf("config:%s", rule.Name),
				Fn: func(_ *RunContext, _ *Agent, tool Tool, input json.RawMessage) (*GuardrailResult, error) {
					if rule.ToolPattern != "" && !matchToolPattern(tool.Name(), rule.ToolPattern) {
						return &GuardrailResult{}, nil
					}
					if re.Match(input) {
						return guardrailResultForRule(rule, tool.Name(), false), nil
					}
					return &GuardrailResult{}, nil
				},
			})
		case "tool-output":
			outputGuardrails = append(outputGuardrails, ToolOutputGuardrail{
				Name: fmt.Sprintf("config:%s", rule.Name),
				Fn: func(_ *RunContext, _ *Agent, tool Tool, result ToolResult) (*GuardrailResult, error) {
					if rule.ToolPattern != "" && !matchToolPattern(tool.Name(), rule.ToolPattern) {
						return &GuardrailResult{}, nil
					}
					if re.MatchString(result.Content) {
						return guardrailResultForRule(rule, tool.Name(), true), nil
					}
					return &GuardrailResult{}, nil
				},
			})
		default:
			errs = append(errs, fmt.Errorf("unknown guardrail rule type %q for rule %q", rule.Type, rule.Name))
		}
	}

	return inputGuardrails, outputGuardrails, errs
}

func guardrailResultForRule(rule GuardrailRule, toolName string, output bool) *GuardrailResult {
	msg := strings.TrimSpace(rule.Message)
	if msg == "" {
		if output {
			msg = fmt.Sprintf("Guardrail %q triggered on tool %q output", rule.Name, toolName)
		} else {
			msg = fmt.Sprintf("Guardrail %q triggered on tool %q", rule.Name, toolName)
		}
	}

	switch rule.Action {
	case "warn":
		log.Printf("WARN: guardrail %q triggered: %s", rule.Name, msg)
		return &GuardrailResult{Output: msg}
	case "log":
		log.Printf("INFO: guardrail %q triggered: %s", rule.Name, msg)
		return &GuardrailResult{}
	default:
		// "block" and any unvalidated action fail closed.
		return &GuardrailResult{Output: msg, TripwireTriggered: true}
	}
}

// normalizeGuardrailRuleAction validates a rule's action. An empty action
// defaults to "block" (fail closed) and unknown values are rejected so a typo
// like "deny" cannot silently disable a rule.
func normalizeGuardrailRuleAction(rule GuardrailRule) (string, error) {
	action := strings.ToLower(strings.TrimSpace(rule.Action))
	switch action {
	case "":
		return "block", nil
	case "block", "warn", "log":
		return action, nil
	default:
		return "", fmt.Errorf("unknown action %q in guardrail rule %q (valid: block, warn, log)", rule.Action, rule.Name)
	}
}

// matchToolPattern matches a tool name against a glob-style pattern where
// each "*" matches any (possibly empty) substring. Patterns like "*sql*" and
// "mcp_*_write" are handled correctly instead of silently matching nothing.
func matchToolPattern(name, pattern string) bool {
	segments := strings.Split(pattern, "*")
	if len(segments) == 1 {
		return name == pattern
	}
	if !strings.HasPrefix(name, segments[0]) {
		return false
	}
	rest := name[len(segments[0]):]
	last := segments[len(segments)-1]
	for _, seg := range segments[1 : len(segments)-1] {
		if seg == "" {
			continue
		}
		idx := strings.Index(rest, seg)
		if idx < 0 {
			return false
		}
		rest = rest[idx+len(seg):]
	}
	return strings.HasSuffix(rest, last)
}

func (l *ChatLoop) finalize(ctx context.Context, result *RunResult) (*RunResult, error) {
	if l.opts.TraceStore != nil {
		if err := l.opts.TraceStore.Finalize(ctx, result); err != nil {
			return result, fmt.Errorf("finalize trace: %w", err)
		}
	}
	if l.opts.RunStatusSink != nil {
		if err := l.opts.RunStatusSink.PublishFinalResult(ctx, result); err != nil {
			return result, fmt.Errorf("publish final result: %w", err)
		}
	}
	return result, nil
}

func (l *ChatLoop) resolveToolApproval(ctx context.Context, agent *Agent, cfg RunConfig, pending *Interruption) ([]RunItem, []ToolGuardrailResult, []ToolGuardrailResult, bool, error) {
	if pending == nil {
		return nil, nil, nil, false, nil
	}
	approved, reason, err := l.opts.ApprovalGate.ApproveTool(ctx, ToolApprovalRequest{
		ToolName: pending.ToolName,
		Input:    append([]byte(nil), pending.ToolInput...),
		Reason:   "tool approval required",
	})
	if err != nil {
		return nil, nil, nil, false, fmt.Errorf("approve tool %q: %w", pending.ToolName, err)
	}
	items := []RunItem{{
		Type: RunItemToolApproval,
		ToolApproval: &ToolApprovalData{
			ToolName: pending.ToolName,
			Input:    cloneRawMessage(pending.ToolInput),
			CallID:   pending.ToolCallID,
			Approved: approved,
		},
	}}
	if !approved {
		content := strings.TrimSpace(reason)
		if content == "" {
			content = "tool call denied by host approval gate"
		}
		items = append(items, RunItem{
			Type: RunItemToolOutput,
			ToolOutput: &ToolOutputData{
				CallID:  pending.ToolCallID,
				Content: content,
				IsError: true,
			},
		})
		return items, nil, nil, false, nil
	}
	approvedCtx := ctx
	if len(pending.ParentContext) > 0 {
		parentContext, restoreErr := RestoreRunItems(pending.ParentContext, func(name string) *Agent {
			if name == agent.Name {
				return agent
			}
			// Preserve assistant provenance for history produced by an earlier
			// agent even when it is not reachable from the current agent.
			return &Agent{Name: name}
		})
		if restoreErr != nil {
			return items, nil, nil, false, fmt.Errorf("restore parent context for approved tool %q: %w", pending.ToolName, restoreErr)
		}
		approvedCtx = WithParentRunItems(ctx, parentContext)
	}
	item, inputResults, outputResults, shouldPause, err := l.opts.Runner.ExecuteApprovedTool(approvedCtx, agent, ToolCallData{
		ID:    pending.ToolCallID,
		Name:  pending.ToolName,
		Input: cloneRawMessage(pending.ToolInput),
	}, cfg)
	if item.ToolOutput != nil {
		items = append(items, item)
	}
	return items, inputResults, outputResults, shouldPause, err
}

// denyPendingInterruptions synthesizes denied approval + error output pairs
// for pending tool calls that cannot be approved (no ApprovalGate). Without
// the paired outputs, persisted history would end with dangling tool_use
// items that providers reject on replay.
func denyPendingInterruptions(pending []*Interruption, reason string) []RunItem {
	var items []RunItem
	for _, p := range pending {
		if p == nil {
			continue
		}
		items = append(items,
			RunItem{
				Type: RunItemToolApproval,
				ToolApproval: &ToolApprovalData{
					ToolName: p.ToolName,
					Input:    cloneRawMessage(p.ToolInput),
					CallID:   p.ToolCallID,
					Approved: false,
				},
			},
			RunItem{
				Type: RunItemToolOutput,
				ToolOutput: &ToolOutputData{
					CallID:  p.ToolCallID,
					Content: reason,
					IsError: true,
				},
			},
		)
	}
	return items
}

func combineLoopResult(result *RunResult, newItems []RunItem, responses []ModelResponse, toolInputResults, toolOutputResults []ToolGuardrailResult, usage Usage) *RunResult {
	if result == nil {
		return nil
	}
	combined := *result
	combined.NewItems = append([]RunItem(nil), newItems...)
	combined.RawResponses = append([]ModelResponse(nil), responses...)
	combined.ToolInputGuardrailResults = append([]ToolGuardrailResult(nil), toolInputResults...)
	combined.ToolOutputGuardrailResults = append([]ToolGuardrailResult(nil), toolOutputResults...)
	combined.Usage = usage
	return &combined
}

func cloneRawMessage(raw json.RawMessage) json.RawMessage {
	if raw == nil {
		return nil
	}
	out := make([]byte, len(raw))
	copy(out, raw)
	return out
}

func toolPolicyFromPermissionMode(mode PermissionMode) *ToolPolicy {
	switch normalizePermissionMode(mode) {
	case PermissionModeDangerFullAccess:
		return nil
	default:
		return &ToolPolicy{ApprovalRequired: true}
	}
}

func toolAccessLevelFromPermissionMode(mode PermissionMode) ToolAccessLevel {
	if normalizePermissionMode(mode) == PermissionModeReadOnly {
		return ToolAccessLevelReadOnly
	}
	return ToolAccessLevelFull
}

func normalizePermissionMode(mode PermissionMode) PermissionMode {
	switch strings.ToLower(strings.TrimSpace(string(mode))) {
	case string(PermissionModeReadOnly):
		return PermissionModeReadOnly
	case string(PermissionModeDangerFullAccess):
		return PermissionModeDangerFullAccess
	case string(PermissionModeWorkspaceWrite), "":
		return PermissionModeWorkspaceWrite
	default:
		// Fail closed: an unrecognized non-empty mode (e.g. a typo like
		// "workspace-wrte") must not silently grant write access. This
		// mirrors internal/agent/policy.NormalizePermissionMode.
		return PermissionModeReadOnly
	}
}

package agentsdk

// Regression test for the 2026-07 audit: a turn with several parallel
// approval-needing tool calls must resolve ALL of them before resuming —
// leaving one pending produces an unpaired tool_use the provider rejects.

import (
	"context"
	"encoding/json"
	"sync"
	"testing"
)

type recordingGate struct {
	mu    sync.Mutex
	names []string
}

func (g *recordingGate) ApproveTool(_ context.Context, req ToolApprovalRequest) (bool, string, error) {
	g.mu.Lock()
	defer g.mu.Unlock()
	g.names = append(g.names, req.ToolName)
	return true, "", nil
}

func TestChatLoopResolvesAllParallelToolApprovals(t *testing.T) {
	model := &scriptedChatModel{responses: []*ModelResponse{
		{Items: []RunItem{
			{Type: RunItemToolCall, ToolCall: &ToolCallData{ID: "c1", Name: "mutate_a", Input: json.RawMessage(`{}`)}},
			{Type: RunItemToolCall, ToolCall: &ToolCallData{ID: "c2", Name: "mutate_b", Input: json.RawMessage(`{}`)}},
		}},
		{Items: []RunItem{{Type: RunItemMessage, Message: &MessageOutput{Text: "both done"}}}},
	}}

	var executed []string
	var mu sync.Mutex
	makeTool := func(name string) *FunctionTool {
		return &FunctionTool{
			ToolName: name,
			Schema:   json.RawMessage(`{"type":"object"}`),
			Fn: func(context.Context, json.RawMessage) (string, error) {
				mu.Lock()
				executed = append(executed, name)
				mu.Unlock()
				return "ok", nil
			},
		}
	}

	gate := &recordingGate{}
	result, err := NewChatLoop(ChatLoopOptions{
		Runner:       NewRunnerWithModel(model),
		Agent:        &Agent{Name: "loop", Model: "demo", Tools: []Tool{makeTool("mutate_a"), makeTool("mutate_b")}},
		RunConfig:    RunConfig{MaxTurns: 3, ToolPolicy: &ToolPolicy{ApprovalRequired: true}},
		ApprovalGate: gate,
	}).Run(context.Background())
	if err != nil {
		t.Fatal(err)
	}
	if result.FinalText() != "both done" {
		t.Fatalf("FinalText() = %q", result.FinalText())
	}
	if len(gate.names) != 2 {
		t.Fatalf("approval gate consulted %d times (%v), want 2", len(gate.names), gate.names)
	}
	if len(executed) != 2 {
		t.Fatalf("executed tools = %v, want both", executed)
	}

	// Every tool_use in the resume history must be paired with an output.
	outputs := map[string]bool{}
	for _, item := range result.NewItems {
		if item.Type == RunItemToolOutput && item.ToolOutput != nil {
			outputs[item.ToolOutput.CallID] = true
		}
	}
	for _, id := range []string{"c1", "c2"} {
		if !outputs[id] {
			t.Fatalf("tool call %s has no output in history; next model call would be rejected. items=%+v", id, result.NewItems)
		}
	}
}

