	if result.FinalText() != "guardrail handled" {
		t.Fatalf("FinalText() = %q, want guardrail handled", result.FinalText())
	}
	if result == nil || len(result.NewItems) < 3 || !containsToolOutput(result.NewItems, "tool input guardrail") {
