package durable

import (
	"fmt"
	"os"
	"sync"
	"syscall"
)

func withFileLock(path string, fn func() error) error {
	value, _ := filesystemLocks.LoadOrStore(path, &sync.Mutex{})
	mutex := value.(*sync.Mutex)
	mutex.Lock()
	defer mutex.Unlock()
	file, err := os.OpenFile(path, os.O_CREATE|os.O_RDWR, 0o600)
	if err != nil {
		return fmt.Errorf("durable: open lock: %w", err)
	}
	defer file.Close()
	if err := file.Chmod(0o600); err != nil {
		return fmt.Errorf("durable: secure lock: %w", err)
	}
	if err := syscall.Flock(int(file.Fd()), syscall.LOCK_EX); err != nil {
		return fmt.Errorf("durable: lock: %w", err)
	}
	defer syscall.Flock(int(file.Fd()), syscall.LOCK_UN)
	return fn()
}

package durable

import (
	"encoding/json"
	"fmt"
	"time"
)

// Document is the versioned JSON interchange and backup format for one run.
type Document struct {
	SchemaVersion int         `json:"schema_version"`
	Snapshot      RunSnapshot `json:"snapshot"`
	Events        []Event     `json:"events"`
}

// EncodeDocument serializes a current-version durable document.
func EncodeDocument(document Document) ([]byte, error) {
	document.SchemaVersion = SchemaVersion
	document.Snapshot.SchemaVersion = SchemaVersion
	return json.Marshal(document)
}

// DecodeDocument decodes a durable document and migrates older supported versions.
func DecodeDocument(data []byte) (Document, error) {
	var header struct {
		SchemaVersion int `json:"schema_version"`
	}
	if err := json.Unmarshal(data, &header); err != nil {
		return Document{}, fmt.Errorf("durable: decode document: %w", err)
	}
	switch header.SchemaVersion {
	case SchemaVersion:
		var document Document
		if err := json.Unmarshal(data, &document); err != nil {
			return Document{}, fmt.Errorf("durable: decode v2 document: %w", err)
		}
		document.Snapshot.SchemaVersion = SchemaVersion
		return document, nil
	case 1:
		return migrateV1(data)
	default:
		return Document{}, fmt.Errorf("durable: unsupported schema version %d", header.SchemaVersion)
	}
}

// V1Document models the simulated v1 format retained solely for migration tests and imports.
type V1Document struct {
	SchemaVersion int       `json:"schema_version"`
	TenantID      TenantID  `json:"tenant_id"`
	RunID         RunID     `json:"run_id"`
	Revision      uint64    `json:"revision"`
	EventSequence uint64    `json:"event_sequence"`
	Status        RunStatus `json:"status"`
	Cancelled     bool      `json:"cancelled,omitempty"`
	BudgetTokens  int64     `json:"budget_tokens,omitempty"`
	CreatedAt     time.Time `json:"created_at"`
	UpdatedAt     time.Time `json:"updated_at"`
	Events        []Event   `json:"events,omitempty"`
}

func migrateV1(data []byte) (Document, error) {
	var old V1Document
	if err := json.Unmarshal(data, &old); err != nil {
		return Document{}, fmt.Errorf("durable: decode v1 document: %w", err)
	}
	snapshot := RunSnapshot{
		SchemaVersion: SchemaVersion, TenantID: old.TenantID, RunID: old.RunID,
		Revision: old.Revision, EventSequence: old.EventSequence, Status: old.Status,
		CreatedAt: old.CreatedAt.UTC(), UpdatedAt: old.UpdatedAt.UTC(),
		CumulativeBudget: BudgetCounters{InputTokens: old.BudgetTokens},
	}
	if snapshot.Status == "" {
		snapshot.Status = RunPending
	}
	if old.Cancelled {
		snapshot.Cancellation = &Cancellation{RequestedAt: old.UpdatedAt.UTC()}
	}
	if snapshot.EventSequence == 0 {
		snapshot.EventSequence = uint64(len(old.Events))
	}
	for i := range old.Events {
		if old.Events[i].TenantID == "" {
			old.Events[i].TenantID = old.TenantID
		}
		if old.Events[i].RunID == "" {
			old.Events[i].RunID = old.RunID
		}
		if old.Events[i].Sequence == 0 {
			old.Events[i].Sequence = uint64(i + 1)
		}
	}
	return Document{SchemaVersion: SchemaVersion, Snapshot: snapshot, Events: old.Events}, nil
}

package durable

import (
	"context"
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
	"time"
)

// PostgresOptions configures persistence-boundary transformations for PostgresStore.
type PostgresOptions struct {
	Redactor  Redactor
	Encryptor Encryptor
}

// PostgresStore is a RunStore backed by caller-owned PostgreSQL connections.
// Call Init before using a newly provisioned database.
type PostgresStore struct {
	db        *sql.DB
	redactor  Redactor
	encryptor Encryptor
}

// NewPostgresStore constructs a PostgreSQL store using db; it never closes the
// caller-provided handle. Options are optional to keep unprotected setup concise.
func NewPostgresStore(db *sql.DB, options ...PostgresOptions) (*PostgresStore, error) {
	if db == nil {
		return nil, errors.New("durable: PostgreSQL DB is required")
	}
	var opts PostgresOptions
	if len(options) > 0 {
		opts = options[0]
	}
	return &PostgresStore{db: db, redactor: opts.Redactor, encryptor: opts.Encryptor}, nil
}

// NewPostgreSQLStore is the spelling-equivalent constructor for PostgresStore.
func NewPostgreSQLStore(db *sql.DB, options ...PostgresOptions) (*PostgresStore, error) {
	return NewPostgresStore(db, options...)
}

// Init creates the tables and indexes required by PostgresStore.
func (s *PostgresStore) Init(ctx context.Context) error {
	statements := []string{
		`CREATE TABLE IF NOT EXISTS durable_runs (
			tenant_id TEXT NOT NULL,
			run_id TEXT NOT NULL,
			revision BIGINT NOT NULL,
			event_sequence BIGINT NOT NULL,
			snapshot BYTEA NOT NULL,
			retain_until TIMESTAMPTZ NULL,
			created_at TIMESTAMPTZ NOT NULL,
			updated_at TIMESTAMPTZ NOT NULL,
			lease_owner TEXT NULL,
			lease_token TEXT NULL,
			lease_until TIMESTAMPTZ NULL,
			PRIMARY KEY (tenant_id, run_id)
		)`,
		`CREATE TABLE IF NOT EXISTS durable_events (
			tenant_id TEXT NOT NULL,
			run_id TEXT NOT NULL,
			sequence BIGINT NOT NULL,
			body BYTEA NOT NULL,
			PRIMARY KEY (tenant_id, run_id, sequence),
			FOREIGN KEY (tenant_id, run_id) REFERENCES durable_runs (tenant_id, run_id) ON DELETE CASCADE
		)`,
		`CREATE INDEX IF NOT EXISTS durable_runs_retention_idx ON durable_runs (retain_until) WHERE retain_until IS NOT NULL`,
	}
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return fmt.Errorf("durable: begin schema init: %w", err)
	}
	defer tx.Rollback()
	for _, statement := range statements {
		if _, err := tx.ExecContext(ctx, statement); err != nil {
			return fmt.Errorf("durable: initialize schema: %w", err)
		}
	}
	if err := tx.Commit(); err != nil {
		return fmt.Errorf("durable: commit schema init: %w", err)
	}
	return nil
}

// Create persists the first snapshot of a run.
func (s *PostgresStore) Create(ctx context.Context, snapshot RunSnapshot) error {
	if err := validateSnapshot(snapshot); err != nil {
		return err
	}
	if snapshot.CreatedAt.IsZero() {
		snapshot.CreatedAt = time.Now().UTC()
	}
	if snapshot.UpdatedAt.IsZero() {
		snapshot.UpdatedAt = snapshot.CreatedAt
	}
	snapshot.SchemaVersion = SchemaVersion
	snapshot = redactSnapshot(snapshot, s.redactor)
	body, err := s.encode(ctx, snapshot)
	if err != nil {
		return err
	}
	result, err := s.db.ExecContext(ctx, `INSERT INTO durable_runs
		(tenant_id, run_id, revision, event_sequence, snapshot, retain_until, created_at, updated_at)
		VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
		ON CONFLICT (tenant_id, run_id) DO NOTHING`,
		snapshot.TenantID, snapshot.RunID, snapshot.Revision, snapshot.EventSequence, body, snapshot.RetainUntil, snapshot.CreatedAt, snapshot.UpdatedAt)
	if err != nil {
		return fmt.Errorf("durable: create run: %w", err)
	}
	affected, err := result.RowsAffected()
	if err != nil {
		return fmt.Errorf("durable: inspect create: %w", err)
	}
	if affected != 1 {
		return ErrAlreadyExists
	}
	return nil
}

// Load returns a detached compact snapshot and its immutable event stream.
func (s *PostgresStore) Load(ctx context.Context, tenantID TenantID, runID RunID) (RunSnapshot, []Event, error) {
	var body []byte
	if err := s.db.QueryRowContext(ctx, `SELECT snapshot FROM durable_runs WHERE tenant_id = $1 AND run_id = $2`, tenantID, runID).Scan(&body); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return RunSnapshot{}, nil, ErrNotFound
		}
		return RunSnapshot{}, nil, fmt.Errorf("durable: load run: %w", err)
	}
	var snapshot RunSnapshot
	if err := s.decode(ctx, body, &snapshot); err != nil {
		return RunSnapshot{}, nil, err
	}
	rows, err := s.db.QueryContext(ctx, `SELECT body FROM durable_events WHERE tenant_id = $1 AND run_id = $2 AND sequence <= $3 ORDER BY sequence`, tenantID, runID, snapshot.EventSequence)
	if err != nil {
		return RunSnapshot{}, nil, fmt.Errorf("durable: load events: %w", err)
	}
	defer rows.Close()
	var events []Event
	for rows.Next() {
		var eventBody []byte
		if err := rows.Scan(&eventBody); err != nil {
			return RunSnapshot{}, nil, fmt.Errorf("durable: scan event: %w", err)
		}
		var event Event
		if err := s.decode(ctx, eventBody, &event); err != nil {
			return RunSnapshot{}, nil, err
		}
		events = append(events, event)
	}
	if err := rows.Err(); err != nil {
		return RunSnapshot{}, nil, fmt.Errorf("durable: read events: %w", err)
	}
	return snapshot, events, nil
}

// Append atomically locks the run row, compares revision, inserts immutable
// events, and writes the resulting compact snapshot.
func (s *PostgresStore) Append(ctx context.Context, lease Lease, expectedRevision uint64, events []Event, snapshot RunSnapshot) (RunSnapshot, error) {
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return RunSnapshot{}, fmt.Errorf("durable: begin append: %w", err)
	}
	defer tx.Rollback()
	var revision, sequence uint64
	var leaseToken sql.NullString
	var leaseUntil sql.NullTime
	if err := tx.QueryRowContext(ctx, `SELECT revision, event_sequence, lease_token, lease_until FROM durable_runs WHERE tenant_id = $1 AND run_id = $2 FOR UPDATE`, lease.TenantID, lease.RunID).Scan(&revision, &sequence, &leaseToken, &leaseUntil); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return RunSnapshot{}, ErrNotFound
		}
		return RunSnapshot{}, fmt.Errorf("durable: lock run: %w", err)
	}
	if !leaseToken.Valid || LeaseToken(leaseToken.String) != lease.Token || !leaseUntil.Valid || !leaseUntil.Time.After(time.Now().UTC()) {
		return RunSnapshot{}, ErrLeaseLost
	}
	if revision != expectedRevision {
		return RunSnapshot{}, ErrConflict
	}
	updated, clean, err := prepareAppend(lease.TenantID, lease.RunID, revision, sequence, events, snapshot, s.redactor)
	if err != nil {
		return RunSnapshot{}, err
	}
	for _, event := range clean {
		body, encodeErr := s.encode(ctx, event)
		if encodeErr != nil {
			return RunSnapshot{}, encodeErr
		}
		if _, insertErr := tx.ExecContext(ctx, `INSERT INTO durable_events (tenant_id, run_id, sequence, body) VALUES ($1, $2, $3, $4)`, lease.TenantID, lease.RunID, event.Sequence, body); insertErr != nil {
			return RunSnapshot{}, fmt.Errorf("durable: append event: %w", insertErr)
		}
	}
	body, err := s.encode(ctx, updated)
	if err != nil {
		return RunSnapshot{}, err
	}
	result, err := tx.ExecContext(ctx, `UPDATE durable_runs SET revision = $1, event_sequence = $2, snapshot = $3, retain_until = $4, updated_at = $5 WHERE tenant_id = $6 AND run_id = $7 AND revision = $8`, updated.Revision, updated.EventSequence, body, updated.RetainUntil, updated.UpdatedAt, lease.TenantID, lease.RunID, revision)
	if err != nil {
		return RunSnapshot{}, fmt.Errorf("durable: update snapshot: %w", err)
	}
	affected, err := result.RowsAffected()
	if err != nil {
		return RunSnapshot{}, fmt.Errorf("durable: inspect append: %w", err)
	}
	if affected != 1 {
		return RunSnapshot{}, ErrConflict
	}
	if err := tx.Commit(); err != nil {
		return RunSnapshot{}, fmt.Errorf("durable: commit append: %w", err)
	}
	return updated, nil
}

// AcquireLease grants exclusive ownership using a row-level lock.
func (s *PostgresStore) AcquireLease(ctx context.Context, tenantID TenantID, runID RunID, owner string, ttl time.Duration) (Lease, error) {
	if owner == "" || ttl <= 0 {
		return Lease{}, errors.New("durable: lease owner and positive TTL are required")
	}
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return Lease{}, fmt.Errorf("durable: begin lease: %w", err)
	}
	defer tx.Rollback()
	var token, currentOwner sql.NullString
	var until sql.NullTime
	if err := tx.QueryRowContext(ctx, `SELECT lease_owner, lease_token, lease_until FROM durable_runs WHERE tenant_id = $1 AND run_id = $2 FOR UPDATE`, tenantID, runID).Scan(&currentOwner, &token, &until); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return Lease{}, ErrNotFound
		}
		return Lease{}, fmt.Errorf("durable: lock lease: %w", err)
	}
	now := time.Now().UTC()
	if until.Valid && until.Time.After(now) {
		return Lease{}, ErrLeaseHeld
	}
	lease := Lease{TenantID: tenantID, RunID: runID, Owner: owner, Token: NewLeaseToken(), ExpiresAt: now.Add(ttl)}
	if _, err := tx.ExecContext(ctx, `UPDATE durable_runs SET lease_owner = $1, lease_token = $2, lease_until = $3 WHERE tenant_id = $4 AND run_id = $5`, lease.Owner, lease.Token, lease.ExpiresAt, tenantID, runID); err != nil {
		return Lease{}, fmt.Errorf("durable: write lease: %w", err)
	}
	if err := tx.Commit(); err != nil {
		return Lease{}, fmt.Errorf("durable: commit lease: %w", err)
	}
	return lease, nil
}

// RenewLease extends the currently fenced lease.
func (s *PostgresStore) RenewLease(ctx context.Context, lease Lease, ttl time.Duration) (Lease, error) {
	if ttl <= 0 {
		return Lease{}, errors.New("durable: positive lease TTL is required")
	}
	now := time.Now().UTC()
	renewed := lease
	renewed.ExpiresAt = now.Add(ttl)
	result, err := s.db.ExecContext(ctx, `UPDATE durable_runs SET lease_until = $1 WHERE tenant_id = $2 AND run_id = $3 AND lease_token = $4 AND lease_until > $5`, renewed.ExpiresAt, lease.TenantID, lease.RunID, lease.Token, now)
	if err != nil {
		return Lease{}, fmt.Errorf("durable: renew lease: %w", err)
	}
	affected, err := result.RowsAffected()
	if err != nil {
		return Lease{}, err
	}
	if affected != 1 {
		return Lease{}, ErrLeaseLost
	}
	return renewed, nil
}

// ReleaseLease releases a lease only for its current fencing token.
func (s *PostgresStore) ReleaseLease(ctx context.Context, lease Lease) error {
	result, err := s.db.ExecContext(ctx, `UPDATE durable_runs SET lease_owner = NULL, lease_token = NULL, lease_until = NULL WHERE tenant_id = $1 AND run_id = $2 AND lease_token = $3`, lease.TenantID, lease.RunID, lease.Token)
	if err != nil {
		return fmt.Errorf("durable: release lease: %w", err)
	}
	affected, err := result.RowsAffected()
	if err != nil {
		return err
	}
	if affected != 1 {
		return ErrLeaseLost
	}
	return nil
}

// DeleteRun permanently deletes one run and cascades its immutable events.
func (s *PostgresStore) DeleteRun(ctx context.Context, tenantID TenantID, runID RunID) error {
	result, err := s.db.ExecContext(ctx, `DELETE FROM durable_runs WHERE tenant_id = $1 AND run_id = $2`, tenantID, runID)
	if err != nil {
		return fmt.Errorf("durable: delete run: %w", err)
	}
	affected, err := result.RowsAffected()
	if err != nil {
		return err
	}
	if affected != 1 {
		return ErrNotFound
	}
	return nil
}

// DeleteTenant permanently deletes all runs belonging to tenantID.
func (s *PostgresStore) DeleteTenant(ctx context.Context, tenantID TenantID) error {
	_, err := s.db.ExecContext(ctx, `DELETE FROM durable_runs WHERE tenant_id = $1`, tenantID)
	if err != nil {
		return fmt.Errorf("durable: delete tenant: %w", err)
	}
	return nil
}

// ApplyRetention permanently removes runs whose explicit deadline has elapsed.
func (s *PostgresStore) ApplyRetention(ctx context.Context, policy RetentionPolicy) (int, error) {
	now := policy.Now.UTC()
	if now.IsZero() {
		now = time.Now().UTC()
	}
	result, err := s.db.ExecContext(ctx, `DELETE FROM durable_runs WHERE retain_until IS NOT NULL AND retain_until <= $1`, now)
	if err != nil {
		return 0, fmt.Errorf("durable: apply retention: %w", err)
	}
	affected, err := result.RowsAffected()
	if err != nil {
		return 0, err
	}
	return int(affected), nil
}

func (s *PostgresStore) encode(ctx context.Context, value any) ([]byte, error) {
	body, err := json.Marshal(value)
	if err != nil {
		return nil, fmt.Errorf("durable: encode value: %w", err)
	}
	if s.encryptor == nil {
		return body, nil
	}
	ciphertext, err := s.encryptor.Encrypt(ctx, body)
	if err != nil {
		return nil, fmt.Errorf("durable: encrypt value: %w", err)
	}
	body, err = json.Marshal(encryptedRecord{Encrypted: true, Data: ciphertext})
	if err != nil {
		return nil, fmt.Errorf("durable: encode encrypted value: %w", err)
	}
	return body, nil
}

func (s *PostgresStore) decode(ctx context.Context, body []byte, value any) error {
	var envelope encryptedRecord
	if err := json.Unmarshal(body, &envelope); err != nil {
		return fmt.Errorf("durable: decode value: %w", err)
	}
	if envelope.Encrypted {
		if s.encryptor == nil {
			return errors.New("durable: encrypted value requires an encryptor")
		}
		var err error
		body, err = s.encryptor.Decrypt(ctx, envelope.Data)
		if err != nil {
			return fmt.Errorf("durable: decrypt value: %w", err)
		}
	}
	if err := json.Unmarshal(body, value); err != nil {
		return fmt.Errorf("durable: decode value: %w", err)
	}
	return nil
}

var _ RunStore = (*PostgresStore)(nil)

package durable

import (
	"context"
	"errors"
	"fmt"
	"time"
)

var (
	// ErrNotFound reports an absent tenant or run.
	ErrNotFound = errors.New("durable: run not found")
	// ErrAlreadyExists reports an attempt to create an existing run.
	ErrAlreadyExists = errors.New("durable: run already exists")
	// ErrConflict reports a compare-and-swap version mismatch.
	ErrConflict = errors.New("durable: revision conflict")
	// ErrLeaseHeld reports a lease owned by another unexpired worker.
	ErrLeaseHeld = errors.New("durable: lease held")
	// ErrLeaseLost reports an expired or fenced lease token.
	ErrLeaseLost = errors.New("durable: lease lost")
)

// RetentionPolicy controls expiration of runs. Runs without RetainUntil are retained.
type RetentionPolicy struct{ Now time.Time }

// RunStore is a cross-process durable execution store. Append atomically writes
// immutable events and their resulting compact snapshot when expected revision matches.
type RunStore interface {
	Create(context.Context, RunSnapshot) error
	Load(context.Context, TenantID, RunID) (RunSnapshot, []Event, error)
	Append(context.Context, Lease, uint64, []Event, RunSnapshot) (RunSnapshot, error)
	AcquireLease(context.Context, TenantID, RunID, string, time.Duration) (Lease, error)
	RenewLease(context.Context, Lease, time.Duration) (Lease, error)
	ReleaseLease(context.Context, Lease) error
	DeleteRun(context.Context, TenantID, RunID) error
	DeleteTenant(context.Context, TenantID) error
	ApplyRetention(context.Context, RetentionPolicy) (int, error)
}

func validateSnapshot(snapshot RunSnapshot) error {
	if snapshot.TenantID == "" || snapshot.RunID == "" {
		return errors.New("durable: snapshot requires tenant and run IDs")
	}
	if snapshot.SchemaVersion != 0 && snapshot.SchemaVersion != SchemaVersion {
		return fmt.Errorf("durable: snapshot schema version %d", snapshot.SchemaVersion)
	}
	return nil
}

func prepareAppend(tenantID TenantID, runID RunID, revision, sequence uint64, events []Event, snapshot RunSnapshot, redactor Redactor) (RunSnapshot, []Event, error) {
	if err := validateSnapshot(snapshot); err != nil {
		return RunSnapshot{}, nil, err
	}
	if snapshot.TenantID != tenantID || snapshot.RunID != runID {
		return RunSnapshot{}, nil, errors.New("durable: snapshot key does not match append key")
	}
	if snapshot.Revision != revision+1 {
		return RunSnapshot{}, nil, fmt.Errorf("durable: snapshot revision must be %d", revision+1)
	}
	clean := make([]Event, len(events))
	for i, event := range events {
		if event.ID == "" {
			event.ID = NewEventID()
		}
		if event.At.IsZero() {
			event.At = snapshot.UpdatedAt.UTC()
		}
		if event.TenantID != "" && event.TenantID != tenantID || event.RunID != "" && event.RunID != runID {
			return RunSnapshot{}, nil, errors.New("durable: event key does not match append key")
		}
		event.TenantID, event.RunID, event.Sequence = tenantID, runID, sequence+uint64(i)+1
		if redactor != nil && len(event.Payload) != 0 {
			event.Payload = redactor.Redact(event.Classification, event.Payload)
		}
		clean[i] = event
	}
	snapshot.SchemaVersion = SchemaVersion
	snapshot.EventSequence = sequence + uint64(len(clean))
	if snapshot.UpdatedAt.IsZero() {
		snapshot.UpdatedAt = time.Now().UTC()
	}
	return redactSnapshot(snapshot, redactor), clean, nil
}

func redactSnapshot(snapshot RunSnapshot, redactor Redactor) RunSnapshot {
	if redactor == nil {
		return snapshot
	}
	if len(snapshot.State) != 0 {
		snapshot.State = redactor.Redact(snapshot.Classification, snapshot.State)
	}
	for i := range snapshot.Steps {
		if len(snapshot.Steps[i].Data) != 0 {
			snapshot.Steps[i].Data = redactor.Redact(snapshot.Classification, snapshot.Steps[i].Data)
		}
	}
	for i := range snapshot.ToolCalls {
		classification := snapshot.ToolCalls[i].Classification
		if classification == "" {
			classification = snapshot.Classification
		}
		if len(snapshot.ToolCalls[i].Input) != 0 {
			snapshot.ToolCalls[i].Input = redactor.Redact(classification, snapshot.ToolCalls[i].Input)
		}
		if len(snapshot.ToolCalls[i].Output) != 0 {
			snapshot.ToolCalls[i].Output = redactor.Redact(classification, snapshot.ToolCalls[i].Output)
		}
	}
	for i := range snapshot.Effects {
		classification := snapshot.Effects[i].DataClassification
		if classification == "" {
			classification = snapshot.Classification
		}
		if len(snapshot.Effects[i].Outcome) != 0 {
			snapshot.Effects[i].Outcome = redactor.Redact(classification, snapshot.Effects[i].Outcome)
		}
	}
	return snapshot
}

package durable

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"time"

	"github.com/google/uuid"
)

// SchemaVersion is the current durable JSON document format.
const SchemaVersion = 2

// Typed identifiers prevent accidentally mixing durable resource keys.
type (
	TenantID   string
	RunID      string
	AttemptID  string
	StepID     string
	ToolCallID string
	ApprovalID string
	ChildRunID string
	EffectID   string
	EventID    string
	LeaseToken string
)

func newID(prefix string) string { return prefix + "_" + uuid.NewString() }

// NewTenantID creates a stable tenant identifier suitable for a durable store.
func NewTenantID() TenantID { return TenantID(newID("ten")) }

// NewRunID creates a new run identifier.
func NewRunID() RunID { return RunID(newID("run")) }

// NewAttemptID creates a new attempt identifier.
func NewAttemptID() AttemptID { return AttemptID(newID("att")) }

// NewStepID creates a new step identifier.
func NewStepID() StepID { return StepID(newID("step")) }

// NewToolCallID creates a new tool-call identifier.
func NewToolCallID() ToolCallID { return ToolCallID(newID("tool")) }

// NewApprovalID creates a new approval identifier.
func NewApprovalID() ApprovalID { return ApprovalID(newID("approval")) }

// NewChildRunID creates a new child-run identifier.
func NewChildRunID() ChildRunID { return ChildRunID(newID("child")) }

// NewEffectID creates a new external-effect identifier.
func NewEffectID() EffectID { return EffectID(newID("effect")) }

// NewEventID creates a new immutable event identifier.
func NewEventID() EventID { return EventID(newID("event")) }

// DataClassification communicates how persisted data must be handled.
type DataClassification string

const (
	DataPublic    DataClassification = "public"
	DataInternal  DataClassification = "internal"
	DataSensitive DataClassification = "sensitive"
	DataSecret    DataClassification = "secret"
)

// Redactor transforms data before it crosses a persistence boundary.
type Redactor interface {
	Redact(classification DataClassification, value json.RawMessage) json.RawMessage
}

// Encryptor protects complete persisted records. Key management remains with
// the caller; stores never retain encryption keys.
type Encryptor interface {
	Encrypt(ctx context.Context, plaintext []byte) ([]byte, error)
	Decrypt(ctx context.Context, ciphertext []byte) ([]byte, error)
}

// RunStatus is the durable lifecycle of a run.
type RunStatus string

const (
	RunPending   RunStatus = "pending"
	RunRunning   RunStatus = "running"
	RunSucceeded RunStatus = "succeeded"
	RunFailed    RunStatus = "failed"
	RunCancelled RunStatus = "cancelled"
)

// Attempt records one model or execution attempt.
type Attempt struct {
	ID        AttemptID `json:"id"`
	StartedAt time.Time `json:"started_at"`
	EndedAt   time.Time `json:"ended_at,omitempty"`
	Outcome   string    `json:"outcome,omitempty"`
}

// Step records a resumable run boundary.
type Step struct {
	ID        StepID          `json:"id"`
	Kind      string          `json:"kind"`
	Status    string          `json:"status"`
	Data      json.RawMessage `json:"data,omitempty"`
	StartedAt time.Time       `json:"started_at"`
	EndedAt   time.Time       `json:"ended_at,omitempty"`
}

// ToolCall records a durable tool invocation boundary.
type ToolCall struct {
	ID             ToolCallID         `json:"id"`
	Name           string             `json:"name"`
	Status         string             `json:"status"`
	Classification DataClassification `json:"classification,omitempty"`
	Input          json.RawMessage    `json:"input,omitempty"`
	Output         json.RawMessage    `json:"output,omitempty"`
	StartedAt      time.Time          `json:"started_at"`
	EndedAt        time.Time          `json:"ended_at,omitempty"`
}

// Approval records an approval request and its resolution.
type Approval struct {
	ID          ApprovalID `json:"id"`
	Status      string     `json:"status"`
	RequestedAt time.Time  `json:"requested_at"`
	ResolvedAt  time.Time  `json:"resolved_at,omitempty"`
	ResolvedBy  string     `json:"resolved_by,omitempty"`
}

// ChildRun records a spawned run that must be resumed or reconciled explicitly.
type ChildRun struct {
	ID        ChildRunID `json:"id"`
	RunID     RunID      `json:"run_id"`
	Status    RunStatus  `json:"status"`
	StartedAt time.Time  `json:"started_at"`
	EndedAt   time.Time  `json:"ended_at,omitempty"`
}

// Cancellation persists a cancellation request independently of process life.
type Cancellation struct {
	RequestedAt    time.Time `json:"requested_at,omitempty"`
	RequestedBy    string    `json:"requested_by,omitempty"`
	Reason         string    `json:"reason,omitempty"`
	AcknowledgedAt time.Time `json:"acknowledged_at,omitempty"`
}

// BudgetCounters are cumulative values, never per-process deltas.
type BudgetCounters struct {
	InputTokens  int64 `json:"input_tokens,omitempty"`
	OutputTokens int64 `json:"output_tokens,omitempty"`
	ToolCalls    int64 `json:"tool_calls,omitempty"`
	CostMicros   int64 `json:"cost_micros,omitempty"`
	WallTimeMS   int64 `json:"wall_time_ms,omitempty"`
}

// EffectClassification determines whether an uncertain external effect can be replayed.
type EffectClassification string

const (
	EffectIdempotent    EffectClassification = "idempotent"
	EffectDeduplicated  EffectClassification = "deduplicated"
	EffectNonReplayable EffectClassification = "non_replayable"
)

// EffectState describes the durable external-effect protocol.
type EffectState string

const (
	EffectPrepared       EffectState = "prepared"
	EffectDispatched     EffectState = "dispatched"
	EffectSucceeded      EffectState = "succeeded"
	EffectFailed         EffectState = "failed"
	EffectOutcomeUnknown EffectState = "outcome_unknown"
)

// Effect persists intent and outcome around an external side effect.
type Effect struct {
	ID                 EffectID             `json:"id"`
	Classification     EffectClassification `json:"classification"`
	DataClassification DataClassification   `json:"data_classification,omitempty"`
	State              EffectState          `json:"state"`
	IdempotencyKey     string               `json:"idempotency_key,omitempty"`
	PreparedAt         time.Time            `json:"prepared_at"`
	UpdatedAt          time.Time            `json:"updated_at"`
	Outcome            json.RawMessage      `json:"outcome,omitempty"`
}

// NewEffect prepares an effect with an idempotency key stable across restarts.
func NewEffect(runID RunID, classification EffectClassification, now time.Time) Effect {
	id := NewEffectID()
	return Effect{ID: id, Classification: classification, State: EffectPrepared, IdempotencyKey: IdempotencyKey(runID, id), PreparedAt: now.UTC(), UpdatedAt: now.UTC()}
}

// IdempotencyKey derives a stable opaque key for a run-effect pair.
func IdempotencyKey(runID RunID, effectID EffectID) string {
	sum := sha256.Sum256([]byte(string(runID) + ":" + string(effectID)))
	return "ga_" + hex.EncodeToString(sum[:])
}

// RecoveryAction tells a resumer what it may safely do with an interrupted effect.
type RecoveryAction string

const (
	RecoveryNone      RecoveryAction = "none"
	RecoveryRetry     RecoveryAction = "retry"
	RecoveryReconcile RecoveryAction = "reconcile"
	RecoveryOperator  RecoveryAction = "operator_resolution"
)

// RecoveryDecision is deliberately conservative: unknown non-replayable
// effects require an operator and are never automatically retried.
type RecoveryDecision struct {
	Action         RecoveryAction `json:"action"`
	Automatic      bool           `json:"automatic"`
	IdempotencyKey string         `json:"idempotency_key,omitempty"`
}

// MarkInterruptedEffect converts an ambiguous dispatched effect to the
// explicit outcome-unknown state before recovery policy is evaluated.
func MarkInterruptedEffect(effect *Effect, now time.Time) error {
	if effect == nil {
		return errors.New("durable: nil effect")
	}
	if effect.State != EffectDispatched {
		return nil
	}
	return TransitionEffect(effect, EffectOutcomeUnknown, now)
}

// RecoverEffect returns the only safe recovery action for an effect.
func RecoverEffect(effect Effect) RecoveryDecision {
	decision := RecoveryDecision{Action: RecoveryNone, IdempotencyKey: effect.IdempotencyKey}
	switch effect.State {
	case EffectPrepared:
		decision.Action, decision.Automatic = RecoveryRetry, true
	case EffectDispatched:
		if effect.Classification == EffectNonReplayable {
			decision.Action = RecoveryReconcile
		} else {
			decision.Action, decision.Automatic = RecoveryRetry, true
		}
	case EffectOutcomeUnknown:
		if effect.Classification == EffectNonReplayable {
			decision.Action = RecoveryOperator
		} else {
			decision.Action, decision.Automatic = RecoveryRetry, true
		}
	}
	return decision
}

// TransitionEffect validates a durable external-effect state transition.
func TransitionEffect(effect *Effect, next EffectState, now time.Time) error {
	if effect == nil {
		return errors.New("durable: nil effect")
	}
	valid := (effect.State == EffectPrepared && (next == EffectDispatched || next == EffectFailed)) ||
		(effect.State == EffectDispatched && (next == EffectSucceeded || next == EffectFailed || next == EffectOutcomeUnknown)) ||
		(effect.State == EffectOutcomeUnknown && (next == EffectSucceeded || next == EffectFailed))
	if !valid {
		return fmt.Errorf("durable: invalid effect transition %q -> %q", effect.State, next)
	}
	effect.State, effect.UpdatedAt = next, now.UTC()
	return nil
}

// Event is immutable once appended. Sequence is assigned by the store.
type Event struct {
	ID             EventID            `json:"id"`
	TenantID       TenantID           `json:"tenant_id"`
	RunID          RunID              `json:"run_id"`
	Sequence       uint64             `json:"sequence"`
	At             time.Time          `json:"at"`
	Type           string             `json:"type"`
	Classification DataClassification `json:"classification,omitempty"`
	Payload        json.RawMessage    `json:"payload,omitempty"`
}

// RunSnapshot is a compact continuation point. State holds runner-specific
// continuation data while the typed fields expose durable scheduling boundaries.
type RunSnapshot struct {
	SchemaVersion    int                `json:"schema_version"`
	TenantID         TenantID           `json:"tenant_id"`
	RunID            RunID              `json:"run_id"`
	Revision         uint64             `json:"revision"`
	EventSequence    uint64             `json:"event_sequence"`
	Status           RunStatus          `json:"status"`
	Classification   DataClassification `json:"classification,omitempty"`
	State            json.RawMessage    `json:"state,omitempty"`
	Attempts         []Attempt          `json:"attempts,omitempty"`
	Steps            []Step             `json:"steps,omitempty"`
	ToolCalls        []ToolCall         `json:"tool_calls,omitempty"`
	Approvals        []Approval         `json:"approvals,omitempty"`
	ChildRuns        []ChildRun         `json:"child_runs,omitempty"`
	Effects          []Effect           `json:"effects,omitempty"`
	Cancellation     *Cancellation      `json:"cancellation,omitempty"`
	CumulativeBudget BudgetCounters     `json:"cumulative_budget"`
	CreatedAt        time.Time          `json:"created_at"`
	UpdatedAt        time.Time          `json:"updated_at"`
	RetainUntil      *time.Time         `json:"retain_until,omitempty"`
}

// NewRunSnapshot creates the first compact continuation for a run.
func NewRunSnapshot(tenantID TenantID, runID RunID, now time.Time) RunSnapshot {
	return RunSnapshot{SchemaVersion: SchemaVersion, TenantID: tenantID, RunID: runID, Status: RunPending, CreatedAt: now.UTC(), UpdatedAt: now.UTC()}
}

// Lease grants one worker temporary ownership of a run.
type Lease struct {
	TenantID  TenantID   `json:"tenant_id"`
	RunID     RunID      `json:"run_id"`
	Owner     string     `json:"owner"`
	Token     LeaseToken `json:"token"`
	ExpiresAt time.Time  `json:"expires_at"`
}

// NewLeaseToken creates an opaque lease fencing token.
func NewLeaseToken() LeaseToken { return LeaseToken(newID("lease")) }

package agentsdk

import (
	"context"
	"errors"
	"testing"
	"time"

	"github.com/gratefulagents/sdk/pkg/agentsdk/durable"
)

type renewalObservingStore struct {
	durable.RunStore
	renewed chan struct{}
}

func (s *renewalObservingStore) RenewLease(ctx context.Context, lease durable.Lease, ttl time.Duration) (durable.Lease, error) {
	renewed, err := s.RunStore.RenewLease(ctx, lease, ttl)
	if err == nil {
		select {
		case s.renewed <- struct{}{}:
		default:
		}
	}
	return renewed, err
}

func TestStoredRunRenewsLeaseDuringLongBoundary(t *testing.T) {
	ctx := context.Background()
	filesystem, err := durable.NewFilesystemStore(t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	store := &renewalObservingStore{RunStore: filesystem, renewed: make(chan struct{}, 8)}
	run, err := OpenStoredRun(ctx, store, StoredRunOptions{TenantID: "tenant_a", RunID: "run_a", Owner: "worker_a", LeaseTTL: 60 * time.Millisecond})
	if err != nil {
		t.Fatal(err)
	}
	defer run.Close(ctx)
	for i := 0; i < 3; i++ {
		select {
		case <-store.renewed:
		case <-time.After(10 * time.Second):
			// Generous bound: renewals normally arrive every few tens of
			// milliseconds, but loaded CI runners can stall goroutine
			// scheduling well past a second.
			t.Fatal("lease heartbeat did not renew")
		}
	}
	other, err := OpenStoredRun(ctx, store, StoredRunOptions{TenantID: "tenant_a", RunID: "run_a", Owner: "worker_b", LeaseTTL: time.Second})
	if other != nil || !errors.Is(err, durable.ErrLeaseHeld) {
		t.Fatalf("other=%v err=%v", other, err)
	}
}

package agentsdk

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"sync"
	"time"

	"github.com/gratefulagents/sdk/pkg/agentsdk/durable"
)

// StoredRunOptions identifies and secures one durable execution. TenantID is
// required. Empty RunID creates a new stable run identity; empty Owner uses a
// process-scoped owner label. LeaseTTL defaults to 30 seconds.
type StoredRunOptions struct {
	TenantID       durable.TenantID
	RunID          durable.RunID
	Owner          string
	LeaseTTL       time.Duration
	Classification durable.DataClassification
	RetainUntil    *time.Time
}

// StoredRun binds Runner checkpoints to a RunStore lease and CAS revision.
// Close releases ownership; callers should always defer it.
type StoredRun struct {
	mu        sync.Mutex
	store     durable.RunStore
	snapshot  durable.RunSnapshot
	lease     durable.Lease
	leaseTTL  time.Duration
	resume    *DurableCheckpoint
	base      durable.BudgetCounters
	leaseErr  error
	stopLease chan struct{}
	leaseDone chan struct{}
	closeOnce sync.Once
}

// OpenStoredRun creates or resumes a run and acquires its fencing lease. A
// second worker cannot own the same run until that lease is released or expires.
func OpenStoredRun(ctx context.Context, store durable.RunStore, opts StoredRunOptions) (*StoredRun, error) {
	if store == nil {
		return nil, errors.New("agentsdk: durable run store is nil")
	}
	if opts.TenantID == "" {
		return nil, errors.New("agentsdk: durable tenant ID is required")
	}
	if opts.RunID == "" {
		opts.RunID = durable.NewRunID()
	}
	if opts.Owner == "" {
		opts.Owner = fmt.Sprintf("pid-%d", os.Getpid())
	}
	if opts.LeaseTTL <= 0 {
		opts.LeaseTTL = 30 * time.Second
	}

	snapshot, _, err := store.Load(ctx, opts.TenantID, opts.RunID)
	if errors.Is(err, durable.ErrNotFound) {
		now := time.Now().UTC()
		snapshot = durable.NewRunSnapshot(opts.TenantID, opts.RunID, now)
		snapshot.Classification = opts.Classification
		snapshot.RetainUntil = opts.RetainUntil
		if err := store.Create(ctx, snapshot); err != nil {
			return nil, fmt.Errorf("agentsdk: create durable run: %w", err)
		}
	} else if err != nil {
		return nil, fmt.Errorf("agentsdk: load durable run: %w", err)
	}
	lease, err := store.AcquireLease(ctx, opts.TenantID, opts.RunID, opts.Owner, opts.LeaseTTL)
	if err != nil {
		return nil, fmt.Errorf("agentsdk: acquire durable run: %w", err)
	}
	s := &StoredRun{
		store: store, snapshot: snapshot, lease: lease, leaseTTL: opts.LeaseTTL,
		base: snapshot.CumulativeBudget, stopLease: make(chan struct{}), leaseDone: make(chan struct{}),
	}
	if len(snapshot.State) != 0 {
		var cp DurableCheckpoint
		if err := json.Unmarshal(snapshot.State, &cp); err != nil {
			_ = store.ReleaseLease(ctx, lease)
			return nil, fmt.Errorf("agentsdk: decode durable continuation: %w", err)
		}
		s.resume = &cp
	}
	go s.renewLeaseLoop()
	return s, nil
}

func (s *StoredRun) renewLeaseLoop() {
	defer close(s.leaseDone)
	interval := s.leaseTTL / 3
	if interval <= 0 {
		interval = time.Millisecond
	}
	ticker := time.NewTicker(interval)
	defer ticker.Stop()
	for {
		select {
		case <-s.stopLease:
			return
		case <-ticker.C:
			ctx, cancel := context.WithTimeout(context.Background(), interval)
			s.mu.Lock()
			if s.lease.Token == "" {
				s.mu.Unlock()
				cancel()
				return
			}
			renewed, err := s.store.RenewLease(ctx, s.lease, s.leaseTTL)
			if err == nil {
				s.lease = renewed
			}
			s.leaseErr = err
			s.mu.Unlock()
			cancel()
		}
	}
}

// ID returns the stable durable run ID.
func (s *StoredRun) ID() durable.RunID { s.mu.Lock(); defer s.mu.Unlock(); return s.snapshot.RunID }

// RunConfig returns optional Runner durability configuration. Existing callers
// may continue using RunConfig without calling this API or configuring a store.
func (s *StoredRun) RunConfig() *DurableRunConfig {
	s.mu.Lock()
	defer s.mu.Unlock()
	// Each Runner.Run reports usage from zero. Freeze the already committed
	// cumulative counters as this attempt's base so later attempts in the same
	// process can never reset or double-count them.
	s.base = s.snapshot.CumulativeBudget
	var resume *DurableCheckpoint
	if s.resume != nil {
		cp := *s.resume
		resume = &cp
	}
	return &DurableRunConfig{RunID: string(s.snapshot.RunID), AttemptID: string(durable.NewAttemptID()), Resume: resume, Checkpoint: s.checkpoint}
}

func (s *StoredRun) checkpoint(ctx context.Context, cp DurableCheckpoint) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if errors.Is(s.leaseErr, durable.ErrLeaseLost) {
		return fmt.Errorf("renew ownership: %w", s.leaseErr)
	}
	renewed, err := s.store.RenewLease(ctx, s.lease, s.leaseTTL)
	if err != nil {
		return fmt.Errorf("renew ownership: %w", err)
	}
	s.lease = renewed
	payload, err := json.Marshal(cp)
	if err != nil {
		return fmt.Errorf("encode checkpoint: %w", err)
	}
	next := s.snapshot
	next.Revision++
	next.State = payload
	next.Status = durable.RunRunning
	if cp.Boundary == DurableBoundaryRunCompleted {
		next.Status = durable.RunSucceeded
	} else if cp.Boundary == DurableBoundaryRunCancelled {
		next.Status = durable.RunCancelled
		next.Cancellation = &durable.Cancellation{RequestedAt: cp.CreatedAt, Reason: "runner context cancelled"}
	}
	next.UpdatedAt = cp.CreatedAt
	next.CumulativeBudget = durable.BudgetCounters{
		InputTokens:  s.base.InputTokens + cp.Usage.InputTokens,
		OutputTokens: s.base.OutputTokens + cp.Usage.OutputTokens,
		ToolCalls:    s.base.ToolCalls,
		CostMicros:   s.base.CostMicros,
		WallTimeMS:   s.base.WallTimeMS,
	}
	next.Attempts = []durable.Attempt{{ID: durable.AttemptID(cp.AttemptID), StartedAt: cp.CreatedAt}}
	next.Steps = []durable.Step{{ID: durable.StepID(cp.StepID), Kind: string(cp.Boundary), Status: "committed", StartedAt: cp.CreatedAt, EndedAt: cp.CreatedAt}}
	next.Approvals = nil
	for _, interruption := range cp.Interruptions {
		if interruption != nil {
			next.Approvals = append(next.Approvals, durable.Approval{ID: durable.ApprovalID(interruption.ToolCallID), Status: "pending", RequestedAt: cp.CreatedAt})
		}
	}
	event := durable.Event{Type: "run." + string(cp.Boundary), At: cp.CreatedAt, Classification: next.Classification, Payload: payload}
	updated, err := s.store.Append(ctx, s.lease, s.snapshot.Revision, []durable.Event{event}, next)
	if err != nil {
		return fmt.Errorf("commit checkpoint: %w", err)
	}
	s.snapshot = updated
	s.resume = &cp
	return nil
}

// Close releases this worker's fenced ownership. The persisted continuation is
// unaffected and can immediately be acquired by another process.
func (s *StoredRun) Close(ctx context.Context) error {
	s.closeOnce.Do(func() { close(s.stopLease) })
	<-s.leaseDone
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.lease.Token == "" {
		return nil
	}
	err := s.store.ReleaseLease(ctx, s.lease)
	if err == nil {
		s.lease = durable.Lease{}
	}
	return err
}

package agentsdk

import (
	"context"
	"errors"
	"testing"
	"time"

	"github.com/gratefulagents/sdk/pkg/agentsdk/durable"
)

func TestStoredRunLeaseCheckpointAndResume(t *testing.T) {
	ctx := context.Background()
	store, err := durable.NewFilesystemStore(t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	opts := StoredRunOptions{TenantID: "tenant_a", RunID: "run_a", Owner: "worker_a", LeaseTTL: time.Minute}
	first, err := OpenStoredRun(ctx, store, opts)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := OpenStoredRun(ctx, store, StoredRunOptions{TenantID: "tenant_a", RunID: "run_a", Owner: "worker_b", LeaseTTL: time.Minute}); !errors.Is(err, durable.ErrLeaseHeld) {
		t.Fatalf("second owner error = %v", err)
	}
	cfg := first.RunConfig()
	now := time.Now().UTC()
	cp := DurableCheckpoint{SchemaVersion: DurableCheckpointSchemaVersion, RunID: string(first.ID()), AttemptID: cfg.AttemptID, StepID: "step_a", Sequence: 1, Boundary: DurableBoundaryToolCompleted, AgentName: "worker", Usage: Usage{InputTokens: 11, OutputTokens: 7}, CreatedAt: now}
	if err := cfg.Checkpoint(ctx, cp); err != nil {
		t.Fatal(err)
	}
	if err := first.Close(ctx); err != nil {
		t.Fatal(err)
	}

	resumed, err := OpenStoredRun(ctx, store, StoredRunOptions{TenantID: "tenant_a", RunID: "run_a", Owner: "worker_b", LeaseTTL: time.Minute})
	if err != nil {
		t.Fatal(err)
	}
	defer resumed.Close(ctx)
	resumeCfg := resumed.RunConfig()
	if resumeCfg.Resume == nil || resumeCfg.Resume.StepID != "step_a" || resumeCfg.Resume.Boundary != DurableBoundaryToolCompleted {
		t.Fatalf("resume checkpoint = %+v", resumeCfg.Resume)
	}
	second := DurableCheckpoint{SchemaVersion: DurableCheckpointSchemaVersion, RunID: "run_a", AttemptID: resumeCfg.AttemptID, StepID: "step_b", Sequence: 2, Boundary: DurableBoundaryPaused, Usage: Usage{InputTokens: 5, OutputTokens: 2}, CreatedAt: now.Add(time.Second)}
	if err := resumeCfg.Checkpoint(ctx, second); err != nil {
		t.Fatal(err)
	}
	snapshot, events, err := store.Load(ctx, "tenant_a", "run_a")
	if err != nil {
		t.Fatal(err)
	}
	if snapshot.Revision != 2 || snapshot.CumulativeBudget.InputTokens != 16 || snapshot.CumulativeBudget.OutputTokens != 9 || len(events) != 2 {
		t.Fatalf("snapshot=%+v events=%+v", snapshot, events)
	}
}

package events

import (
	"bufio"
	"bytes"
	"io"
	"strings"
	"sync"

	"github.com/gratefulagents/sdk/pkg/agentsdk"
)

// Kind identifies an SDK runtime event emitted to a host adapter.
type Kind string

const (
	KindStatus    Kind = "status"
	KindDelta     Kind = "delta"
	KindItem      Kind = "item"
	KindTrace     Kind = "trace"
	KindLog       Kind = "log"
	KindDone      Kind = "done"
	KindError     Kind = "error"
	KindChildTool Kind = "child_tool"
	KindSubAgent  Kind = "subagent"
	KindPhase     Kind = "phase"
)

// Event is the typed SDK event shape hosts can render or persist.
type Event struct {
	Kind     Kind
	Text     string
	Item     *agentsdk.RunItem
	Result   *agentsdk.RunResult
	Err      error
	History  []agentsdk.RunItem
	Pending  *agentsdk.Interruption
	Snapshot agentsdk.ProgressSnapshot
	Child    *agentsdk.ChildToolEvent
	SubAgent *agentsdk.SubAgentStreamEvent
}

// Sink consumes typed runtime events.
type Sink interface {
	Emit(Event)
}

// SinkFunc adapts a function to Sink.
type SinkFunc func(Event)

func (f SinkFunc) Emit(ev Event) {
	if f != nil {
		f(ev)
	}
}

// LineWriter turns JSONL content events into typed SDK events.
//
// Hosts can attach this to SessionEventStream and render typed events instead
// of reparsing event JSON themselves.
type LineWriter struct {
	mu     sync.Mutex
	buffer bytes.Buffer
	sink   Sink
}

func NewLineWriter(sink Sink) *LineWriter {
	return &LineWriter{sink: sink}
}

func (w *LineWriter) Write(p []byte) (int, error) {
	w.mu.Lock()
	defer w.mu.Unlock()

	n, _ := w.buffer.Write(p)
	scanner := bufio.NewScanner(bytes.NewReader(w.buffer.Bytes()))
	scanner.Buffer(make([]byte, 0, 64*1024), 16*1024*1024)

	var lines []string
	for scanner.Scan() {
		lines = append(lines, scanner.Text())
	}
	// If a single line exceeds the scanner's max token size, Scan stops early
	// with an error and leaves the oversized content unconsumed. Surface it as
	// one (truncated) line rather than silently dropping output.
	if err := scanner.Err(); err != nil {
		lines = append(lines, w.buffer.String())
		w.buffer.Reset()
		for _, line := range lines {
			if strings.TrimSpace(line) == "" || w.sink == nil {
				continue
			}
			w.sink.Emit(Event{Kind: KindLog, Text: agentsdk.CompactContentEventLine(line)})
		}
		return n, nil
	}
	if len(p) > 0 && p[len(p)-1] != '\n' {
		w.buffer.Reset()
		if len(lines) > 0 {
			last := lines[len(lines)-1]
			lines = lines[:len(lines)-1]
			w.buffer.WriteString(last)
		}
	} else {
		w.buffer.Reset()
	}

	for _, line := range lines {
		if strings.TrimSpace(line) == "" || w.sink == nil {
			continue
		}
		if ev, ok := agentsdk.ParseContentEventLine(line); ok {
			if subagent, ok := agentsdk.SubAgentStreamEventFromContentEvent(ev); ok {
				w.sink.Emit(Event{Kind: KindSubAgent, SubAgent: subagent})
				continue
			}
			if child, ok := agentsdk.ChildToolEventFromContentEvent(ev); ok {
				w.sink.Emit(Event{Kind: KindChildTool, Child: child})
				continue
			}
		}
		w.sink.Emit(Event{Kind: KindLog, Text: agentsdk.CompactContentEventLine(line)})
	}
	return n, nil
}

var _ io.Writer = (*LineWriter)(nil)

