package guardrails

import (
	"encoding/json"
	"fmt"
	"regexp"
	"strings"

	"github.com/gratefulagents/sdk/pkg/agentsdk"
	"github.com/gratefulagents/sdk/pkg/agentsdk/tools/shell"
)

// secretSignature describes a single high-confidence credential pattern.
// Patterns are intentionally tight: they target well-known credential prefixes
// and shapes so we minimise false positives on prose, code comments, and
// unrelated identifiers. All expressions are RE2-compatible (no backtracking).
type secretSignature struct {
	name    string
	pattern *regexp.Regexp
}

// secretSignatures is the canonical set of credential detectors used by both
// the input and output secret-leak guardrails. Each entry is justified inline.
//
// Coverage targets (see eval/audit-fixtures/secret_obfuscation.txt):
//   - AWS long-term and STS keys (AKIA / ASIA)
//   - GitHub PATs and server/user/refresh tokens (ghp_/ghs_/ghu_/ghr_)
//   - OpenAI project keys (sk-proj-*)
//   - Anthropic API keys (sk-ant-*)
//   - Slack bot/user/app tokens (xoxb-/xoxp-/xoxa-/xoxr-/xoxs-)
//   - npm automation tokens (npm_*)
//   - JSON Web Tokens (three base64url segments separated by dots)
//   - PEM-encoded private keys (RSA, EC, DSA, OPENSSH, generic PKCS#8)
//   - HTTP Authorization Bearer headers
//   - GCP service-account JSON markers
var secretSignatures = []secretSignature{
	// AWS access key IDs always start with AKIA (long-term) or ASIA (STS
	// temporary). The body is exactly 16 uppercase alphanumerics.
	{"AWS access key", regexp.MustCompile(`\b(?:AKIA|ASIA)[0-9A-Z]{16}\b`)},

	// GitHub tokens use a fixed prefix plus an opaque body. Real tokens are
	// >= 36 chars in the body; we accept 30+ to tolerate future length changes
	// without admitting short non-token strings like "ghp_short".
	{"GitHub token", regexp.MustCompile(`\bgh[psuro]_[A-Za-z0-9]{30,255}\b`)},

	// GitHub fine-grained personal access tokens use the github_pat_ prefix
	// with a long base62 body (82+ chars in production; accept 36+).
	{"GitHub fine-grained PAT", regexp.MustCompile(`\bgithub_pat_[A-Za-z0-9_]{36,255}\b`)},

	// OpenAI project-scoped keys. The body uses base64url-ish chars.
	{"OpenAI project key", regexp.MustCompile(`\bsk-proj-[A-Za-z0-9_\-]{20,}\b`)},

	// OpenAI legacy/org keys: "sk-" followed by a long opaque body. The 40+
	// minimum keeps prose and short identifiers (and the more specific
	// sk-proj-/sk-ant- forms, matched above) from false-positiving.
	{"OpenAI API key", regexp.MustCompile(`\bsk-[A-Za-z0-9_\-]{40,}\b`)},

	// Anthropic API keys, optionally including the api03 (or similar) version
	// segment seen in current production keys.
	{"Anthropic API key", regexp.MustCompile(`\bsk-ant-(?:api\d{2}-)?[A-Za-z0-9_\-]{20,}\b`)},

	// Slack tokens: bot (xoxb), user (xoxp), app (xoxa), refresh (xoxr),
	// session (xoxs). Body is dash-separated ids and an opaque suffix.
	{"Slack token", regexp.MustCompile(`\bxox[baprs]-[A-Za-z0-9-]{10,}\b`)},

	// npm automation/CLI tokens are prefixed npm_ followed by an opaque body
	// of >= 30 chars (real tokens are 36).
	{"npm token", regexp.MustCompile(`\bnpm_[A-Za-z0-9]{30,}\b`)},

	// JWTs are exactly three base64url segments joined by dots. We require
	// the header to start with "eyJ" (the base64 of '{"') to keep false
	// positives away from arbitrary dotted identifiers.
	{"JWT", regexp.MustCompile(`\beyJ[A-Za-z0-9_\-]{8,}\.eyJ[A-Za-z0-9_\-]{8,}\.[A-Za-z0-9_\-+/=.]{4,}`)},

	// PEM headers covering RSA, EC, DSA, OPENSSH, encrypted, and unlabeled
	// PKCS#8 ("-----BEGIN PRIVATE KEY-----") private keys.
	{"private key", regexp.MustCompile(`-----BEGIN (?:RSA |EC |DSA |OPENSSH |PGP |ENCRYPTED )?PRIVATE KEY-----`)},

	// HTTP Authorization: Bearer headers. Require >= 16 opaque chars after
	// "Bearer " so prose like "the bearer of this letter" does not match.
	{"Authorization Bearer header", regexp.MustCompile(`(?i)Authorization\s*:\s*Bearer\s+[A-Za-z0-9._\-+/=]{16,}`)},

	// Standalone "Bearer <token>" with a longer minimum length (>= 24) to
	// further suppress matches on common English uses of the word "Bearer".
	{"Bearer token", regexp.MustCompile(`\bBearer\s+[A-Za-z0-9._\-+/=]{24,}\b`)},

	// GCP service-account JSON keys carry the literal "type":"service_account"
	// marker. Tolerate optional whitespace around the colon.
	{"GCP service-account key", regexp.MustCompile(`"type"\s*:\s*"service_account"`)},

	// Generic credential assignment in source/config (kept from prior version).
	{"generic credential assignment", regexp.MustCompile(`(?i)(api[_-]?key|secret[_-]?key|password)\s*[:=]\s*["'][^"']{8,}["']`)},
}

// BuiltinToolInputGuardrails returns guardrails that are always active.
func BuiltinToolInputGuardrails() []agentsdk.ToolInputGuardrail {
	return []agentsdk.ToolInputGuardrail{
		{
			Name: "block-destructive-commands",
			Fn: func(_ *agentsdk.RunContext, _ *agentsdk.Agent, tool agentsdk.Tool, input json.RawMessage) (*agentsdk.GuardrailResult, error) {
				// Keep this policy active even when the OS sandbox enforces the
				// filesystem boundary. It is defense in depth, rejects malformed
				// shell input, and protects custom shell-like tools whose executor
				// cannot be inferred from the process-wide default configuration.
				toolLower := strings.ToLower(tool.Name())
				if !strings.Contains(toolLower, "bash") &&
					!strings.Contains(toolLower, "shell") &&
					!strings.Contains(toolLower, "exec") {
					return &agentsdk.GuardrailResult{}, nil
				}

				var params struct {
					Command string `json:"command"`
					Cmd     string `json:"cmd"`
				}
				// Fail closed: a shell-like tool whose input cannot be parsed
				// cannot be classified, so it must not pass the guardrail.
				if err := json.Unmarshal(input, &params); err != nil {
					return &agentsdk.GuardrailResult{
						Output:            fmt.Sprintf("Blocked: cannot parse shell tool input for destructive-command check: %v", err),
						TripwireTriggered: true,
					}, nil
				}
				cmd := params.Command
				if cmd == "" {
					cmd = params.Cmd
				}
				if cmd == "" {
					return &agentsdk.GuardrailResult{}, nil
				}

				// Tokenizer-backed classification (shared with the bash tools)
				// normalizes quoting, escapes, $IFS, ANSI-C $'...', command
				// substitution, wrappers (sudo/env/bash -c), and chaining
				// before matching, so naive evasions of a substring denylist
				// (e.g. `rm -fr /`, `\rm -rf /`, `sudo rm -rf /`) are caught.
				if blocked, reason := shell.ClassifyDestructiveCommand(cmd); blocked {
					return &agentsdk.GuardrailResult{
						Output:            fmt.Sprintf("Blocked destructive command: %s", reason),
						TripwireTriggered: true,
					}, nil
				}
				return &agentsdk.GuardrailResult{}, nil
			},
		},
		{
			Name: "detect-secret-leak",
			Fn: func(_ *agentsdk.RunContext, _ *agentsdk.Agent, _ agentsdk.Tool, input json.RawMessage) (*agentsdk.GuardrailResult, error) {
				inputStr := string(input)
				for _, sp := range secretSignatures {
					if sp.pattern.MatchString(inputStr) {
						return &agentsdk.GuardrailResult{
							Output:            fmt.Sprintf("Potential %s detected in tool input", sp.name),
							TripwireTriggered: true,
						}, nil
					}
				}
				return &agentsdk.GuardrailResult{}, nil
			},
		},
	}
}

// pemEndMarker closes a PEM private-key block opened by the "private key"
// signature, which only matches the BEGIN header.
var pemEndMarker = regexp.MustCompile(`-----END (?:RSA |EC |DSA |OPENSSH |PGP |ENCRYPTED )?PRIVATE KEY-----`)

// partialSecretSignatures names the signatures whose match is only a marker
// or fragment of a larger credential block: the companion material (e.g. the
// AWS secret access key paired with an AKIA/ASIA key ID, or the private-key
// fields of a GCP service-account JSON) has no independently detectable shape.
// Redacting just the matched fragment would pass the undetected companion
// secrets through, so these signatures keep the hard tripwire and block the
// whole output. Guarded by TestPartialSecretSignatureNamesExist against drift.
var partialSecretSignatures = map[string]bool{
	"AWS access key":          true,
	"GCP service-account key": true,
}

// RedactSecrets replaces every canonical secret-signature match in content
// with a [REDACTED:<name>] marker. It returns the redacted content, the names
// of the signatures that matched (in signature order), and the total match
// count. This is the canonical SDK secret detector; other packages that
// persist model or tool content (for example the trace store) should reuse it
// instead of maintaining a parallel pattern list.
func RedactSecrets(content string) (string, []string, int) {
	return redactSecrets(content)
}

// redactSecrets replaces every secret-signature match in content with a
// [REDACTED:<name>] marker. It returns the redacted content, the names of the
// signatures that matched (in signature order), and the total match count.
func redactSecrets(content string) (string, []string, int) {
	var names []string
	total := 0
	for _, sig := range secretSignatures {
		var n int
		if sig.name == "private key" {
			content, n = redactPrivateKeyBlocks(content, sig.pattern)
		} else if n = len(sig.pattern.FindAllStringIndex(content, -1)); n > 0 {
			content = sig.pattern.ReplaceAllString(content, "[REDACTED:"+sig.name+"]")
		}
		if n > 0 {
			names = append(names, sig.name)
			total += n
		}
	}
	return content, names, total
}

// redactPrivateKeyBlocks redacts from each PEM BEGIN header through the
// matching END marker inclusive (or to the end of content if unterminated) so
// the key body never survives redaction.
func redactPrivateKeyBlocks(content string, begin *regexp.Regexp) (string, int) {
	var b strings.Builder
	n := 0
	for {
		loc := begin.FindStringIndex(content)
		if loc == nil {
			b.WriteString(content)
			return b.String(), n
		}
		n++
		b.WriteString(content[:loc[0]])
		b.WriteString("[REDACTED:private key]")
		rest := content[loc[1]:]
		end := pemEndMarker.FindStringIndex(rest)
		if end == nil {
			return b.String(), n
		}
		content = rest[end[1]:]
	}
}

// BuiltinToolOutputGuardrails returns output guardrails that are always active.
func BuiltinToolOutputGuardrails() []agentsdk.ToolOutputGuardrail {
	return []agentsdk.ToolOutputGuardrail{
		{
			Name: "detect-secret-in-output",
			Fn: func(_ *agentsdk.RunContext, _ *agentsdk.Agent, _ agentsdk.Tool, result agentsdk.ToolResult) (*agentsdk.GuardrailResult, error) {
				// Marker/fragment signatures first: their companion secrets
				// cannot be detected independently, so partial redaction
				// would leak them. Fail closed on the whole output.
				for _, sp := range secretSignatures {
					if partialSecretSignatures[sp.name] && sp.pattern.MatchString(result.Content) {
						return &agentsdk.GuardrailResult{
							Output:            fmt.Sprintf("Potential %s detected in tool output — output blocked: this marker usually travels with companion credentials (e.g. paired secret keys) that cannot be detected independently, so nothing was passed through. If you need the surrounding content, re-read a narrower range that excludes the credential block.", sp.name),
							TripwireTriggered: true,
						}, nil
					}
				}
				// Redact matched secrets in place instead of tripping the
				// tripwire: most hits are source code or fixtures that merely
				// mention secret-like patterns, and nuking the whole output
				// makes those tool calls unusable.
				redacted, names, total := redactSecrets(result.Content)
				if total == 0 {
					return &agentsdk.GuardrailResult{}, nil
				}
				notice := fmt.Sprintf("[guardrail detect-secret-in-output: redacted %d potential secret(s): %s. If these are placeholders or test fixtures the surrounding content is still usable; do not try to reconstruct redacted values.]", total, strings.Join(names, ", "))
				return &agentsdk.GuardrailResult{
					Output:             notice,
					ContentReplaced:    true,
					ReplacementContent: redacted + "\n\n" + notice,
				}, nil
			},
		},
	}
}

package guardrails

import (
	"bufio"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/gratefulagents/sdk/pkg/agentsdk"
)

// stubTool is a no-op Tool implementation used only to satisfy the guardrail
// signature in unit tests.
var stubTool agentsdk.Tool = &agentsdk.FunctionTool{ToolName: "stub"}

// loadCorpusLines reads the corpus, returning non-empty lines.
func loadCorpusLines(t *testing.T) []string {
	t.Helper()
	// Test runs from pkg/agentsdk/guardrails/; corpus lives at repo-root/eval/audit-fixtures/.
	path := filepath.Join("..", "..", "..", "eval", "audit-fixtures", "secret_obfuscation.txt")
	f, err := os.Open(path)
	if err != nil {
		t.Fatalf("open corpus: %v", err)
	}
	defer f.Close()
	var lines []string
	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		raw := scanner.Text()
		// Corpus lines are formatted as "<n>. <secret>"; strip the index prefix.
		if i := strings.Index(raw, ". "); i >= 0 && i <= 4 {
			raw = raw[i+2:]
		}
		raw = strings.TrimSpace(raw)
		if raw == "" {
			continue
		}
		lines = append(lines, raw)
	}
	if err := scanner.Err(); err != nil {
		t.Fatalf("scan corpus: %v", err)
	}
	return lines
}

// runOutputGuardrails returns true if any built-in tool-output guardrail
// detects a secret (by tripping or redacting) in the supplied content.
func runOutputGuardrails(t *testing.T, content string) (bool, string) {
	t.Helper()
	for _, gr := range BuiltinToolOutputGuardrails() {
		res, err := gr.Fn(nil, nil, stubTool, agentsdk.ToolResult{Content: content})
		if err != nil {
			t.Fatalf("guardrail %q error: %v", gr.Name, err)
		}
		if res != nil && (res.TripwireTriggered || res.ContentReplaced) {
			return true, gr.Name
		}
	}
	return false, ""
}

// TestSecretOutputGuardrail_CorpusAllDetected asserts that every line in the
// secret_obfuscation corpus trips the secret-output guardrail. This is the
// corpus-driven regression test for C5.
func TestSecretOutputGuardrail_CorpusAllDetected(t *testing.T) {
	lines := loadCorpusLines(t)
	if len(lines) == 0 {
		t.Fatal("corpus is empty")
	}
	var missed []string
	for _, line := range lines {
		tripped, _ := runOutputGuardrails(t, line)
		if !tripped {
			missed = append(missed, line)
		}
	}
	if len(missed) > 0 {
		t.Fatalf("secret-output guardrail missed %d/%d corpus lines:\n  - %s",
			len(missed), len(lines), strings.Join(missed, "\n  - "))
	}
}

// TestSecretOutputGuardrail_NegativeCorpus ensures benign English text and
// near-miss strings do NOT trigger the guardrail.
func TestSecretOutputGuardrail_NegativeCorpus(t *testing.T) {
	negatives := []string{
		"This documentation describes how AWS access keys are formatted.",
		"The ghp_ prefix is used by GitHub for personal access tokens.",
		"Authorization for the bearer of this letter is granted by the council.",
		"Please bear with us while we investigate the issue.",
		"Set api_key in your config file before running the program.",
		"sk-ate boards are popular among teenagers in California.",
		"The npm registry hosts JavaScript packages such as lodash and react.",
		"Bearer bonds were once a common financial instrument.",
	}
	for _, neg := range negatives {
		tripped, name := runOutputGuardrails(t, neg)
		if tripped {
			t.Errorf("false positive: guardrail %q tripped on benign text: %q", name, neg)
		}
	}
}

// TestSecretOutputGuardrail_RedactsGitHubToken verifies that a matched token
// is masked in place, surrounding text survives, the notice is appended, and
// the tripwire does not trip.
func TestSecretOutputGuardrail_RedactsGitHubToken(t *testing.T) {
	token := "ghp" + "_" + strings.Repeat("a1B2", 9)
	content := "config before\ntoken=" + token + "\nconfig after"
	gr := BuiltinToolOutputGuardrails()[0]
	res, err := gr.Fn(nil, nil, stubTool, agentsdk.ToolResult{Content: content})
	if err != nil {
		t.Fatalf("guardrail error: %v", err)
	}
	if res.TripwireTriggered {
		t.Fatal("tripwire triggered, want redaction only")
	}
	if !res.ContentReplaced {
		t.Fatal("ContentReplaced = false, want true")
	}
	if strings.Contains(res.ReplacementContent, token) {
		t.Fatalf("token survived redaction: %q", res.ReplacementContent)
	}
	if !strings.Contains(res.ReplacementContent, "token=[REDACTED:GitHub token]") {
		t.Fatalf("missing redaction marker: %q", res.ReplacementContent)
	}
	if !strings.Contains(res.ReplacementContent, "config before") || !strings.Contains(res.ReplacementContent, "config after") {
		t.Fatalf("surrounding text not preserved: %q", res.ReplacementContent)
	}
	if !strings.Contains(res.ReplacementContent, "[guardrail detect-secret-in-output: redacted 1 potential secret(s): GitHub token.") {
		t.Fatalf("missing notice: %q", res.ReplacementContent)
	}
}

// TestSecretOutputGuardrail_RedactsPEMBlockFully verifies that the whole PEM
// block from BEGIN through END is removed, not just the header.
func TestSecretOutputGuardrail_RedactsPEMBlockFully(t *testing.T) {
	const keyBody = "MIIEpAIBAAKCAQEAfakekeymaterial"
	pem := "-----BEGIN RSA PRIVATE " + "KEY-----\n" + keyBody + "\n-----END RSA PRIVATE " + "KEY-----"
	content := "before\n" + pem + "\nafter"
	gr := BuiltinToolOutputGuardrails()[0]
	res, err := gr.Fn(nil, nil, stubTool, agentsdk.ToolResult{Content: content})
	if err != nil {
		t.Fatalf("guardrail error: %v", err)
	}
	if res.TripwireTriggered {
		t.Fatal("tripwire triggered, want redaction only")
	}
	if !res.ContentReplaced {
		t.Fatal("ContentReplaced = false, want true")
	}
	if strings.Contains(res.ReplacementContent, keyBody) || strings.Contains(res.ReplacementContent, "-----END") {
		t.Fatalf("PEM body or END marker survived redaction: %q", res.ReplacementContent)
	}
	if !strings.Contains(res.ReplacementContent, "before\n[REDACTED:private key]\nafter") {
		t.Fatalf("expected block replaced by marker with context intact: %q", res.ReplacementContent)
	}
	if !strings.Contains(res.ReplacementContent, "private key. If these are placeholders") {
		t.Fatalf("missing notice: %q", res.ReplacementContent)
	}
}

// TestSecretOutputGuardrail_UnterminatedPEMRedactedToEnd verifies that a PEM
// block without an END marker is redacted through the end of the content.
func TestSecretOutputGuardrail_UnterminatedPEMRedactedToEnd(t *testing.T) {
	const keyBody = "MIIEpAIBAAKCAQEAfakekeymaterial"
	content := "before\n-----BEGIN OPENSSH PRIVATE " + "KEY-----\n" + keyBody
	gr := BuiltinToolOutputGuardrails()[0]
	res, err := gr.Fn(nil, nil, stubTool, agentsdk.ToolResult{Content: content})
	if err != nil {
		t.Fatalf("guardrail error: %v", err)
	}
	if !res.ContentReplaced || strings.Contains(res.ReplacementContent, keyBody) {
		t.Fatalf("key body survived redaction: %+v", res)
	}
}

func TestSecretOutputGuardrail_BlocksPairedAWSCredentialBlock(t *testing.T) {
	// Built by concatenation so this test file never contains a contiguous
	// signature match itself.
	keyID := "AKIA" + "IOSFODNN7EXAMPLE"
	secretKey := "wJalrXUtnFEMI/K7MDENG/bPxRfiCY" + "EXAMPLEKEY"
	content := "AWS_ACCESS_KEY_ID=" + keyID + "\nAWS_SECRET_ACCESS_KEY=" + secretKey + "\n"
	gr := BuiltinToolOutputGuardrails()[0]
	res, err := gr.Fn(nil, nil, stubTool, agentsdk.ToolResult{Content: content})
	if err != nil {
		t.Fatalf("guardrail error: %v", err)
	}
	if !res.TripwireTriggered {
		t.Fatal("tripwire not triggered, want whole output blocked for paired credentials")
	}
	if res.ContentReplaced {
		t.Fatal("ContentReplaced = true, want hard block without partial redaction")
	}
	out, _ := res.Output.(string)
	if !strings.Contains(out, "AWS access key") {
		t.Fatalf("Output = %q, want signature name", out)
	}
	if strings.Contains(out, secretKey) || strings.Contains(out, keyID) {
		t.Fatalf("Output leaked credential material: %q", out)
	}
}

