func TestSourceLoadsCRDShapedModeAndRoles(t *testing.T) {
	root := t.TempDir()
	if err := os.MkdirAll(filepath.Join(root, "modes"), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.MkdirAll(filepath.Join(root, "agents"), 0o755); err != nil {
		t.Fatal(err)
	}
	modeYAML := `apiVersion: platform.gratefulagents.dev/v1alpha1
kind: ModeTemplate
metadata:
  name: feature-builder
spec:
  name: feature-builder
  version: v1
  displayName: Feature Builder
  description: Build a feature.
  category: direct
  autonomous: false
  toolAccess: read-only
  modelRouting:
    defaultModel: openai/gpt-5.5
    fallbackModels:
      - anthropic/claude-sonnet-4-6
    reasoningLevel: xhigh
    textVerbosity: low
    roleOverrides:
      planner:
        model: openai/gpt-5.4
        fallbackModels:
          - copilot/gpt-4.1
        reasoningLevel: high
  constraints:
    maxTurns: 120
    subAgentMaxTurns: 30
    maxConcurrentSubAgents: 3
  instructions: |
    Follow the feature workflow.
`
	if err := os.WriteFile(filepath.Join(root, "modes", "feature-builder.yaml"), []byte(modeYAML), 0o644); err != nil {
		t.Fatal(err)
	}
	role := `---
name: planner
description: Writes the plan.
tool_access: analysis
model_override: openai/gpt-5.3-codex
---
Plan carefully.
`
	if err := os.WriteFile(filepath.Join(root, "agents", "planner.md"), []byte(role), 0o644); err != nil {
		t.Fatal(err)
	}

	src := New(root, t.TempDir(), WithActiveMode("feature-builder"))
	ctx := context.Background()
	modes, err := src.ListModes(ctx)
	if err != nil {
		t.Fatalf("ListModes: %v", err)
	}
	if len(modes) != 3 {
		t.Fatalf("modes = %d, want file mode plus builtin chat/plan: %+v", len(modes), modes)
	}
	byName := map[string]bool{}
	for _, m := range modes {
		byName[m.Name] = true
	}
	if !byName["feature-builder"] || !byName["chat"] || !byName["plan"] {
		t.Fatalf("modes missing expected names: %+v", modes)
	}
	snapshot, err := src.ModeSnapshot(ctx)
	if err != nil {
		t.Fatalf("ModeSnapshot: %v", err)
	}
	if snapshot == nil || snapshot.ModelRouting == nil || snapshot.ModelRouting.RoleOverrides["planner"].ReasoningLevel != "high" {
		t.Fatalf("snapshot routing = %+v", snapshot)
	}
	if len(snapshot.ModelRouting.FallbackModels) != 1 || snapshot.ModelRouting.FallbackModels[0] != "anthropic/claude-sonnet-4-6" {
		t.Fatalf("snapshot default fallbacks = %#v", snapshot.ModelRouting.FallbackModels)
	}
	if got := snapshot.ModelRouting.RoleOverrides["planner"].FallbackModels; len(got) != 1 || got[0] != "copilot/gpt-4.1" {
		t.Fatalf("planner fallbacks = %#v", got)
	}
	if snapshot.Constraints == nil || snapshot.Constraints.MaxTurns != 120 {
		t.Fatalf("snapshot constraints = %+v", snapshot)
	}
	if snapshot.ToolAccess != "read-only" {
		t.Fatalf("snapshot tool access = %q, want read-only", snapshot.ToolAccess)
	}
	mode, err := src.PermissionMode(ctx)
	if err != nil {
		t.Fatalf("PermissionMode: %v", err)
	}
	if mode != agentsdk.PermissionModeReadOnly {
		t.Fatalf("PermissionMode = %q, want read-only", mode)
	}
	directive, err := src.ModeDirective(ctx)
	if err != nil {
		t.Fatalf("ModeDirective: %v", err)
	}
	for _, want := range []string{"Mode: Feature Builder", "Tool access: read-only", "Bash is restricted to statically-authorized commands", "no command substitution $(...) or backticks", "Follow the feature workflow."} {
		if !strings.Contains(directive, want) {
			t.Fatalf("directive missing %q:\n%s", want, directive)
		}
	}
	catalog, err := src.RoleCatalog(ctx)
	if err != nil {
		t.Fatalf("RoleCatalog: %v", err)
	}
	if len(catalog) != 1 || catalog[0].Name != "planner" || catalog[0].ToolAccess != "read-only" || catalog[0].ModelOverride == "" {
		t.Fatalf("catalog = %+v", catalog)
	}
}

func TestBuiltinChatAndPlanModes(t *testing.T) {
	root := t.TempDir() // no modes/ directory at all
	src := New(root, t.TempDir())
	ctx := context.Background()

	chat, err := src.GetMode(ctx, "chat")
	if err != nil {
		t.Fatalf("GetMode(chat): %v", err)
	}
	if chat.Name != "chat" || chat.ToolAccess != "" {
		t.Fatalf("builtin chat = %+v", chat)
	}

	plan, err := src.GetMode(ctx, "plan")
	if err != nil {
		t.Fatalf("GetMode(plan): %v", err)
	}
	if plan.Name != "plan" || plan.ToolAccess != "read-only" || plan.Instructions == "" {
		t.Fatalf("builtin plan = %+v", plan)
	}

	planSrc := New(root, t.TempDir(), WithActiveMode("plan"))
	mode, err := planSrc.PermissionMode(ctx)
	if err != nil {
		t.Fatalf("PermissionMode: %v", err)
	}
	if mode != agentsdk.PermissionModeReadOnly {
		t.Fatalf("plan PermissionMode = %q, want read-only", mode)
	}
}

func TestModeFileOverridesBuiltin(t *testing.T) {
	root := t.TempDir()
	if err := os.MkdirAll(filepath.Join(root, "modes"), 0o755); err != nil {
		t.Fatal(err)
	}
	custom := `name: chat
displayName: Custom Chat
instructions: |
  Custom chat instructions.
`
	if err := os.WriteFile(filepath.Join(root, "modes", "chat.yaml"), []byte(custom), 0o644); err != nil {
		t.Fatal(err)
	}
	src := New(root, t.TempDir())
	ctx := context.Background()
	chat, err := src.GetMode(ctx, "chat")
	if err != nil {
		t.Fatalf("GetMode(chat): %v", err)
	}
	if chat.DisplayName != "Custom Chat" {
		t.Fatalf("file should override builtin chat: %+v", chat)
	}
	modes, err := src.ListModes(ctx)
	if err != nil {
		t.Fatalf("ListModes: %v", err)
	}
	count := 0
	for _, m := range modes {
		if strings.EqualFold(m.Name, "chat") {
			count++
		}
	}
	if count != 1 {
		t.Fatalf("chat listed %d times, want 1: %+v", count, modes)
	}
}

func TestGetModeRejectsPathTraversalName(t *testing.T) {
	root := t.TempDir()
	if err := os.MkdirAll(filepath.Join(root, "modes"), 0o755); err != nil {
		t.Fatal(err)
	}
	outside := filepath.Join(root, "secret.yaml")
	if err := os.WriteFile(outside, []byte("name: secret\ninstructions: nope\n"), 0o644); err != nil {
		t.Fatal(err)
	}

	_, err := New(root, t.TempDir()).GetMode(context.Background(), "../secret")
	if err == nil || !strings.Contains(err.Error(), "must be a single file name") {
		t.Fatalf("GetMode() error = %v, want traversal rejection", err)
	}
}

package mcp

import (
	"encoding/json"
	"fmt"
	"strings"

	"github.com/gratefulagents/sdk/pkg/agentsdk"
)

// BreakGlassRequest is the SDK-native shape for requesting temporary MCP access.
type BreakGlassRequest struct {
	Server string
	Tool   string
	Reason string
}

// BreakGlassPolicy describes host-neutral MCP break-glass display rules.
type BreakGlassPolicy struct {
	RequireAuditReason bool
}

func BreakGlassActions() json.RawMessage {
	return agentsdk.MarshalQuickActions(
		agentsdk.QuickAction{ID: "approve", Label: "Approve", Style: "primary"},
		agentsdk.QuickAction{ID: "reject", Label: "Reject", Style: "destructive"},
	)
}

func BuildBreakGlassQuestion(request BreakGlassRequest, cfg BreakGlassPolicy) string {
	target := FormatBreakGlassTarget(request.Server, request.Tool)
	var b strings.Builder
	b.WriteString(fmt.Sprintf("Approve temporary MCP access to %s?", target))
	if strings.TrimSpace(request.Reason) != "" {
		b.WriteString("\n\nReason: " + strings.TrimSpace(request.Reason))
	}
	if cfg.RequireAuditReason {
		b.WriteString("\n\nThis policy requires an audit reason.")
	}
	return b.String()
}

func FormatBreakGlassTarget(server, tool string) string {
	server = strings.TrimSpace(server)
	tool = strings.TrimSpace(tool)
	if tool != "" {
		return fmt.Sprintf("server %q tool %q", server, tool)
	}
	return fmt.Sprintf("server %q", server)
}

func SummarizeBreakGlassTarget(verb, server, tool string) string {
	return fmt.Sprintf("%s MCP access for %s", strings.TrimSpace(verb), FormatBreakGlassTarget(server, tool))
}

func BlockedToolMessage(server, tool string, breakGlassEnabled bool) string {
	msg := fmt.Sprintf("MCP tool %q on server %q is blocked by policy.", strings.TrimSpace(tool), strings.TrimSpace(server))
	if breakGlassEnabled {
		msg += " Use RequestMCPBreakGlass with a reason if this access is needed."
	}
	return msg
}

func BlockedServerMessage(server string, breakGlassEnabled bool) string {
	msg := fmt.Sprintf("MCP server %q is blocked by policy.", strings.TrimSpace(server))
	if breakGlassEnabled {
		msg += " Use RequestMCPBreakGlass with a reason if this access is needed."
	}
	return msg
}

package mcp

import (
	"strings"
	"testing"
)

func TestBreakGlassQuestionAndActions(t *testing.T) {
	question := BuildBreakGlassQuestion(BreakGlassRequest{
		Server: "github",
		Tool:   "create_issue",
		Reason: "Need to file the tracked issue",
	}, BreakGlassPolicy{RequireAuditReason: true})
	if !strings.Contains(question, `server "github" tool "create_issue"`) {
		t.Fatalf("question = %q", question)
	}
	if !strings.Contains(question, "Need to file the tracked issue") {
		t.Fatalf("question missing reason: %q", question)
	}
	if !strings.Contains(question, "audit reason") {
		t.Fatalf("question missing audit hint: %q", question)
	}

	actions := string(BreakGlassActions())
	if !strings.Contains(actions, `"id":"approve"`) || !strings.Contains(actions, `"id":"reject"`) {
		t.Fatalf("actions = %s", actions)
	}
}

func TestBlockedMessages(t *testing.T) {
	toolMessage := BlockedToolMessage("github", "create_issue", true)
	if !strings.Contains(toolMessage, "RequestMCPBreakGlass") {
		t.Fatalf("toolMessage = %q", toolMessage)
	}
	serverMessage := BlockedServerMessage("github", false)
	if strings.Contains(serverMessage, "RequestMCPBreakGlass") {
		t.Fatalf("serverMessage = %q", serverMessage)
	}
}

package mcp

import (
	"context"
	"encoding/json"
	"fmt"
	"strings"

	"github.com/gratefulagents/sdk/pkg/agentsdk"
)

// BreakGlassRequestResult is the host-neutral result returned by a
// BreakGlassSink after it persists or rejects a request.
type BreakGlassRequestResult struct {
	Content     string
	IsError     bool
	ShouldPause bool
}

// BreakGlassSink persists a break-glass request in the host platform and, when
// appropriate, asks the host UI to collect approval.
type BreakGlassSink interface {
	RequestMCPBreakGlass(ctx context.Context, request BreakGlassRequest) (BreakGlassRequestResult, error)
}

// RequestBreakGlassTool is the SDK-owned shell for MCP break-glass requests.
// Hosts provide only the persistence/approval sink.
type RequestBreakGlassTool struct {
	Sink BreakGlassSink
}

func (t *RequestBreakGlassTool) Name() string { return "RequestMCPBreakGlass" }

func (t *RequestBreakGlassTool) Description() string {
	return "Request temporary MCP server or tool access when policy blocks it. This pauses the run and asks a human to approve or deny the request."
}

func (t *RequestBreakGlassTool) InputSchema() json.RawMessage {
	return json.RawMessage(`{
		"type":"object",
		"properties":{
			"server":{"type":"string","description":"Connected MCP server name that needs temporary access"},
			"tool":{"type":"string","description":"Optional tool name on that server. Leave empty to request the entire server."},
			"reason":{"type":"string","description":"Short audit reason for why the access is needed"}
		},
		"required":["server"]
	}`)
}

func (t *RequestBreakGlassTool) IsReadOnly() bool                      { return false }
func (t *RequestBreakGlassTool) IsEnabled(_ *agentsdk.RunContext) bool { return true }
func (t *RequestBreakGlassTool) NeedsApproval() bool                   { return false }
func (t *RequestBreakGlassTool) TimeoutSeconds() int                   { return 0 }

func (t *RequestBreakGlassTool) Execute(ctx context.Context, input json.RawMessage, _ string) (agentsdk.ToolResult, error) {
	var in struct {
		Server string `json:"server"`
		Tool   string `json:"tool"`
		Reason string `json:"reason"`
	}
	if err := json.Unmarshal(input, &in); err != nil {
		return agentsdk.ToolResult{Content: fmt.Sprintf("Invalid input: %v", err), IsError: true}, nil
	}

	request := BreakGlassRequest{
		Server: strings.TrimSpace(in.Server),
		Tool:   strings.TrimSpace(in.Tool),
		Reason: strings.TrimSpace(in.Reason),
	}
	if request.Server == "" {
		return agentsdk.ToolResult{Content: "server is required", IsError: true}, nil
	}
	if t.Sink == nil {
		return agentsdk.ToolResult{Content: "MCP break-glass sink is not configured", IsError: true}, nil
	}

	result, err := t.Sink.RequestMCPBreakGlass(ctx, request)
	if err != nil {
		return agentsdk.ToolResult{Content: err.Error(), IsError: true}, nil
	}
	return agentsdk.ToolResult{
		Content:     result.Content,
		IsError:     result.IsError,
		ShouldPause: result.ShouldPause,
	}, nil
}

// BreakGlassCatalog contains the connected MCP servers/tools that can be
// requested through a break-glass workflow.
type BreakGlassCatalog struct {
	servers map[string]struct{}
	tools   map[string]map[string]struct{}
}

func NewBreakGlassCatalog(descriptors []ToolDescriptor, servers []string) BreakGlassCatalog {
	catalog := BreakGlassCatalog{
		servers: make(map[string]struct{}),
		tools:   make(map[string]map[string]struct{}),
	}
	for _, server := range servers {
		if trimmed := strings.TrimSpace(server); trimmed != "" {
			catalog.servers[trimmed] = struct{}{}
		}
	}
	for _, desc := range descriptors {
		server := strings.TrimSpace(desc.ServerName)
		tool := strings.TrimSpace(desc.ToolName)
		if server == "" {
			continue
		}
		catalog.servers[server] = struct{}{}
		if tool == "" {
			continue
		}
		if _, ok := catalog.tools[server]; !ok {
			catalog.tools[server] = make(map[string]struct{})
		}
		catalog.tools[server][tool] = struct{}{}
	}
	return catalog
}

func (c BreakGlassCatalog) Validate(server, tool string) error {
	server = strings.TrimSpace(server)
	tool = strings.TrimSpace(tool)
	if server == "" {
		return fmt.Errorf("server is required")
	}
	if _, ok := c.servers[server]; !ok {
		return fmt.Errorf("unknown MCP server %q", server)
	}
	if tool == "" {
		return nil
	}
	tools, ok := c.tools[server]
	if !ok {
		return fmt.Errorf("server %q does not expose tools that can be requested individually", server)
	}
	if _, ok := tools[tool]; !ok {
		return fmt.Errorf("unknown MCP tool %q on server %q", tool, server)
	}
	return nil
}

package mcp

import (
	"context"
	"testing"
)

func TestRequestBreakGlassToolDelegatesToSink(t *testing.T) {
	sink := &recordingBreakGlassSink{}
	tool := &RequestBreakGlassTool{Sink: sink}

	result, err := tool.Execute(context.Background(), []byte(`{"server":" files ","tool":" read ","reason":" inspect docs "}`), "")
	if err != nil {
		t.Fatal(err)
	}
	if result.IsError || !result.ShouldPause {
		t.Fatalf("result = %+v, want pause success", result)
	}
	if sink.request.Server != "files" || sink.request.Tool != "read" || sink.request.Reason != "inspect docs" {
		t.Fatalf("request = %+v", sink.request)
	}
}

func TestRequestBreakGlassToolValidatesServer(t *testing.T) {
	result, err := (&RequestBreakGlassTool{}).Execute(context.Background(), []byte(`{"reason":"missing"}`), "")
	if err != nil {
		t.Fatal(err)
	}
	if !result.IsError || result.Content != "server is required" {
		t.Fatalf("result = %+v, want server error", result)
	}
}

func TestBreakGlassCatalogValidate(t *testing.T) {
	catalog := NewBreakGlassCatalog(
		[]ToolDescriptor{{ServerName: "files", ToolName: "read"}},
		[]string{"shell"},
	)
	if err := catalog.Validate("files", "read"); err != nil {
		t.Fatalf("Validate(files/read) error = %v", err)
	}
	if err := catalog.Validate("shell", ""); err != nil {
		t.Fatalf("Validate(shell) error = %v", err)
	}
	if err := catalog.Validate("missing", ""); err == nil {
		t.Fatal("Validate(missing) error = nil, want error")
	}
	if err := catalog.Validate("files", "write"); err == nil {
		t.Fatal("Validate(files/write) error = nil, want error")
	}
}

type recordingBreakGlassSink struct {
	request BreakGlassRequest
}

func (s *recordingBreakGlassSink) RequestMCPBreakGlass(_ context.Context, request BreakGlassRequest) (BreakGlassRequestResult, error) {
	s.request = request
	return BreakGlassRequestResult{Content: "queued", ShouldPause: true}, nil
}

package mcp

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
)

const (
	// ConfigFileName is the per-repo MCP server configuration file.
	ConfigFileName          = ".mcp.json"
	TransportStdio          = "stdio"
	TransportStreamableHTTP = "streamable-http"
	TransportLegacySSE      = "sse"
)

// Config represents .mcp.json.
type Config struct {
	MCPServers map[string]ServerConfig `json:"mcpServers"`
}

// ServerConfig represents a single MCP server config. Type defaults to
// "stdio". Remote transports are disabled unless the host explicitly enables
// the server with WithRemoteServers; repository configuration alone cannot
// grant network access.
type ServerConfig struct {
	Type    string            `json:"type,omitempty"`
	Command string            `json:"command,omitempty"`
	Args    []string          `json:"args,omitempty"`
	Env     map[string]string `json:"env,omitempty"`
	// URL is required for streamable-http and legacy-sse transports. Embedded
	// credentials, fragments, and query strings are rejected so secrets cannot
	// leak through diagnostics or redirect targets.
	URL string `json:"url,omitempty"`
	// Enabled can explicitly disable a configured server without removing it
	// from .mcp.json. Nil preserves compatibility and treats the server as
	// enabled when the runtime MCP feature itself is enabled.
	Enabled *bool `json:"enabled,omitempty"`
	// AllowEnv is the explicit opt-in list of env names that may pass through
	// the credential denylist (see FilterCredentialEnv). Names listed here are
	// trusted to be set via cfg.Env even if they look like credentials.
	AllowEnv          []string `json:"allowEnv,omitempty"`
	TrustReadOnlyHint bool     `json:"trustReadOnlyHint,omitempty"`
	// AllowedTools, when non-empty, exposes only the listed raw MCP tool names
	// for this server. Empty preserves compatibility and exposes all server
	// tools once MCP is enabled by the runtime.
	AllowedTools []string `json:"allowedTools,omitempty"`
}

// ConfigPathForWorkDir returns the .mcp.json path for a workspace.
func ConfigPathForWorkDir(workDir string) string {
	if workDir == "" {
		return ConfigFileName
	}
	return filepath.Join(workDir, ConfigFileName)
}

// LoadConfig loads and parses .mcp.json.
//
// The returned exists flag is false when the file is not present.
func LoadConfig(path string) (cfg Config, exists bool, err error) {
	data, readErr := os.ReadFile(path)
	if readErr != nil {
		if errors.Is(readErr, os.ErrNotExist) {
			return Config{}, false, nil
		}
		return Config{}, false, fmt.Errorf("read %s: %w", path, readErr)
	}

	if err := json.Unmarshal(data, &cfg); err != nil {
		return Config{}, true, fmt.Errorf("parse %s: %w", path, err)
	}

	if cfg.MCPServers == nil {
		cfg.MCPServers = map[string]ServerConfig{}
	}
	return cfg, true, nil
}

