func TestLoadConfigSnapshot_PinsPathAndContent(t *testing.T) {
	t.Parallel()

	dir := t.TempDir()
	path := filepath.Join(dir, ".mcp.json")
	if err := os.WriteFile(path, []byte(`{"mcpServers":{"a":{"command":"/bin/true"}}}`), 0o644); err != nil {
		t.Fatalf("write: %v", err)
	}

	snap, err := LoadConfigSnapshot(path)
	if err != nil {
		t.Fatalf("LoadConfigSnapshot: %v", err)
	}
	if snap.AbsPath == "" || !filepath.IsAbs(snap.AbsPath) {
		t.Fatalf("AbsPath not pinned: %q", snap.AbsPath)
	}
	if len(snap.ContentSHA256) == 0 {
		t.Fatalf("ContentSHA256 empty")
	}
	if _, ok := snap.Config.MCPServers["a"]; !ok {
		t.Fatalf("config not loaded: %#v", snap.Config)
	}
}

func TestVerifyUnchanged_DetectsModification(t *testing.T) {
	t.Parallel()

	dir := t.TempDir()
	path := filepath.Join(dir, ".mcp.json")
	if err := os.WriteFile(path, []byte(`{"mcpServers":{}}`), 0o644); err != nil {
		t.Fatalf("write: %v", err)
	}
	snap, err := LoadConfigSnapshot(path)
	if err != nil {
		t.Fatalf("LoadConfigSnapshot: %v", err)
	}

	// Mutate the file (simulating an in-run swap) and verify reload is refused.
	if err := os.WriteFile(path, []byte(`{"mcpServers":{"evil":{"command":"/bin/true"}}}`), 0o644); err != nil {
		t.Fatalf("rewrite: %v", err)
	}
	if err := snap.VerifyUnchanged(); err == nil {
		t.Fatalf("VerifyUnchanged expected error after mutation, got nil")
	} else if !strings.Contains(err.Error(), "modified") {
		t.Fatalf("error should mention modification: %v", err)
	}
}

func TestLoadConfigSnapshot_FlagsAgentWritablePath(t *testing.T) {
	t.Parallel()

	dir := t.TempDir() // simulated agent workspace
	path := filepath.Join(dir, ".mcp.json")
	if err := os.WriteFile(path, []byte(`{"mcpServers":{}}`), 0o644); err != nil {
		t.Fatalf("write: %v", err)
	}

	snap, err := LoadConfigSnapshotInWorkspace(path, dir)
	if err != nil {
		t.Fatalf("LoadConfigSnapshotInWorkspace: %v", err)
	}
	if !snap.AgentWritable {
		t.Fatalf("expected AgentWritable=true for path inside workspace")
	}
}

package mcp

import (
	"fmt"
	"strings"
	"sync"
	"time"
)

// stderrTailCap bounds how much of an MCP child's stderr is retained per
// server for diagnostics.
const stderrTailCap = 4096

// stderrTail keeps the last stderrTailCap bytes an MCP child writes to
// stderr, so startup failures surface the real reason (a crash's panic or
// traceback) instead of a bare "EOF". Safe for concurrent use: os/exec
// writes from its pipe-copy goroutine while error paths read the tail.
type stderrTail struct {
	mu  sync.Mutex
	buf []byte
	max int
}

func newStderrTail(capacity int) *stderrTail { return &stderrTail{max: capacity} }

func (t *stderrTail) Write(p []byte) (int, error) {
	t.mu.Lock()
	defer t.mu.Unlock()
	t.buf = append(t.buf, p...)
	if len(t.buf) > t.max {
		t.buf = append(t.buf[:0], t.buf[len(t.buf)-t.max:]...)
	}
	return len(p), nil
}

// Tail returns the captured stderr, trimmed; "" when nothing was written.
func (t *stderrTail) Tail() string {
	if t == nil {
		return ""
	}
	t.mu.Lock()
	defer t.mu.Unlock()
	return strings.TrimSpace(string(t.buf))
}

// tailAfterGrace waits briefly for the exec pipe-copy goroutine to flush a
// crashed child's final stderr before reading the tail. Best-effort: returns
// as soon as anything is captured or the grace period lapses.
func (t *stderrTail) tailAfterGrace(grace time.Duration) string {
	if t == nil {
		return ""
	}
	deadline := time.Now().Add(grace)
	for {
		if s := t.Tail(); s != "" || !time.Now().Before(deadline) {
			return s
		}
		time.Sleep(10 * time.Millisecond)
	}
}

// errWithStderr annotates err with the child's captured stderr tail, if any.
func errWithStderr(err error, tail string) error {
	if err == nil || tail == "" {
		return err
	}
	return fmt.Errorf("%w; server stderr: %s", err, tail)
}

package mcp

import (
	"context"
	"os"
	"os/exec"
	"strings"
	"testing"

	"github.com/gratefulagents/sdk/pkg/agentsdk/sandbox"
)

// directExecutor runs commands without a sandbox so tests can exercise real
// child processes deterministically. It mirrors the real executors' use of
// exec.CommandContext so context-lifetime regressions reproduce.
type directExecutor struct{}

func (directExecutor) Build(ctx context.Context, req sandbox.Request) (*exec.Cmd, error) {
	cmd := exec.CommandContext(ctx, req.Argv[0], req.Argv[1:]...)
	cmd.Dir = req.WorkDir
	cmd.Env = os.Environ()
	for k, v := range req.Env {
		cmd.Env = append(cmd.Env, k+"="+v)
	}
	return cmd, nil
}

func (directExecutor) Run(context.Context, sandbox.Request) (sandbox.Result, error) {
	return sandbox.Result{}, nil
}

func TestStderrTailKeepsBoundedTail(t *testing.T) {
	t.Parallel()

	tail := newStderrTail(8)
	if _, err := tail.Write([]byte("abcdefgh")); err != nil {
		t.Fatal(err)
	}
	if _, err := tail.Write([]byte("XYZ")); err != nil {
		t.Fatal(err)
	}
	if got := tail.Tail(); got != "defghXYZ" {
		t.Fatalf("Tail() = %q, want trailing 8 bytes %q", got, "defghXYZ")
	}
	var nilTail *stderrTail
	if nilTail.Tail() != "" {
		t.Fatal("nil tail must read empty")
	}
}

func TestErrWithStderr(t *testing.T) {
	t.Parallel()

	if errWithStderr(nil, "x") != nil {
		t.Fatal("nil error must stay nil")
	}
	base := context.DeadlineExceeded
	if got := errWithStderr(base, ""); got != base {
		t.Fatal("empty tail must not wrap")
	}
	got := errWithStderr(base, "boom")
	if !strings.Contains(got.Error(), "server stderr: boom") {
		t.Fatalf("annotated error = %v", got)
	}
}

// TestConnectStdioServerReportsChildStderr is the regression test for blind
// "initialize: EOF" failures: a child that dies at startup must surface what
// it wrote to stderr in the connect error.
func TestConnectStdioServerReportsChildStderr(t *testing.T) {
	t.Parallel()

	opts := resolveManagerOptions(t.TempDir(), WithCommandExecutor(directExecutor{}))
	cfg := ServerConfig{Command: "sh", Args: []string{"-c", "echo boom-traceback >&2; exit 3"}}
	_, err := connectStdioServer(context.Background(), t.TempDir(), "crashy", cfg, opts)
	if err == nil {
		t.Fatal("expected connect error for crashing child")
	}
	if !strings.Contains(err.Error(), "boom-traceback") {
		t.Fatalf("connect error missing child stderr: %v", err)
	}
}

package mcp

import (
	"context"
	"encoding/json"
	"fmt"
	"mime"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"time"

	"github.com/gratefulagents/sdk/pkg/agentsdk"
	mcpsdk "github.com/modelcontextprotocol/go-sdk/mcp"
)

var invalidBlobNameChars = regexp.MustCompile(`[^a-zA-Z0-9._-]+`)

const (
	maxMCPTextBytes      = 256 * 1024
	maxMCPBlobBytes      = 10 * 1024 * 1024
	maxBlobPrefixLength  = 96
	mcpTruncationMessage = "\n[truncated MCP text output]"
)

// ToolManager is the MCP manager surface needed by SDK MCP tools.
type ToolManager interface {
	ToolDescriptors() []ToolDescriptor
	ConnectedServerNames() []string
	HasResources() bool
	CallTool(ctx context.Context, qualifiedName string, args map[string]any) (*mcpsdk.CallToolResult, error)
	ListResources(ctx context.Context, serverName string) ([]ResourceDescriptor, error)
	ReadResource(ctx context.Context, serverName, uri string) (*mcpsdk.ReadResourceResult, error)
}

// BuildTools converts connected MCP descriptors into SDK tools.
func BuildTools(manager ToolManager) []agentsdk.Tool {
	if manager == nil {
		return nil
	}

	tools := make([]agentsdk.Tool, 0, len(manager.ToolDescriptors())+2)
	for _, desc := range manager.ToolDescriptors() {
		tools = append(tools, &DynamicTool{
			Manager:    manager,
			Descriptor: desc,
		})
	}
	if manager.HasResources() {
		tools = append(tools, &ListResourcesTool{Manager: manager}, &ReadResourceTool{Manager: manager})
	}
	return tools
}

// DynamicTool exposes one MCP descriptor as an SDK tool.
type DynamicTool struct {
	Manager    ToolManager
	Descriptor ToolDescriptor
}

func (t *DynamicTool) Name() string { return t.Descriptor.QualifiedName }

func (t *DynamicTool) Description() string {
	return SanitizeMCPToolDescription(t.Descriptor.ServerName, t.Descriptor.ToolName, t.Descriptor.Description)
}

func (t *DynamicTool) InputSchema() json.RawMessage {
	if len(t.Descriptor.InputSchema) == 0 {
		return json.RawMessage(`{"type":"object","additionalProperties":true}`)
	}
	return t.Descriptor.InputSchema
}

func (t *DynamicTool) IsReadOnly() bool { return t.Descriptor.ReadOnly }

func (t *DynamicTool) IsEnabled(ctx *agentsdk.RunContext) bool {
	return t.IsReadOnly() || agentsdk.MutatingToolEnabled(ctx, t.Name())
}

func (t *DynamicTool) NeedsApproval() bool { return false }

func (t *DynamicTool) TimeoutSeconds() int { return 0 }

func (t *DynamicTool) Execute(ctx context.Context, input json.RawMessage, workDir string) (agentsdk.ToolResult, error) {
	args := map[string]any{}
	if len(input) > 0 {
		if err := json.Unmarshal(input, &args); err != nil {
			return agentsdk.ToolResult{Content: fmt.Sprintf("Invalid input: %v", err), IsError: true}, nil
		}
	}

	callResult, err := t.Manager.CallTool(ctx, t.Descriptor.QualifiedName, args)
	if err != nil {
		return agentsdk.ToolResult{Content: fmt.Sprintf("MCP tool error: %v", err), IsError: true}, nil
	}

	content, err := FormatCallToolResult(workDir, t.Descriptor, callResult)
	if err != nil {
		return agentsdk.ToolResult{Content: fmt.Sprintf("MCP output formatting error: %v", err), IsError: true}, nil
	}
	if strings.TrimSpace(content) == "" {
		content = "(no output)"
	}
	return agentsdk.ToolResult{Content: content, IsError: callResult != nil && callResult.IsError}, nil
}

// ListResourcesTool lists resources available from connected MCP servers.
type ListResourcesTool struct {
	Manager ToolManager
}

func (t *ListResourcesTool) Name() string { return "ListMcpResourcesTool" }

func (t *ListResourcesTool) Description() string {
	return "List resources from connected MCP servers. Optionally filter by server name."
}

func (t *ListResourcesTool) InputSchema() json.RawMessage {
	return json.RawMessage(`{
		"type":"object",
		"properties":{
			"server":{
				"type":"string",
				"description":"Optional MCP server name to filter resources by"
			}
		}
	}`)
}

func (t *ListResourcesTool) IsReadOnly() bool { return true }

func (t *ListResourcesTool) IsEnabled(_ *agentsdk.RunContext) bool { return true }

func (t *ListResourcesTool) NeedsApproval() bool { return false }

func (t *ListResourcesTool) TimeoutSeconds() int { return 0 }

func (t *ListResourcesTool) Execute(ctx context.Context, input json.RawMessage, _ string) (agentsdk.ToolResult, error) {
	var in struct {
		Server string `json:"server"`
	}
	if len(input) > 0 {
		if err := json.Unmarshal(input, &in); err != nil {
			return agentsdk.ToolResult{Content: fmt.Sprintf("Invalid input: %v", err), IsError: true}, nil
		}
	}

	resources, err := t.Manager.ListResources(ctx, strings.TrimSpace(in.Server))
	if err != nil {
		return agentsdk.ToolResult{Content: fmt.Sprintf("MCP resource error: %v", err), IsError: true}, nil
	}
	if len(resources) == 0 {
		return agentsdk.ToolResult{Content: "No resources found. MCP servers may still provide tools without resources."}, nil
	}

	data, err := json.Marshal(resources)
	if err != nil {
		return agentsdk.ToolResult{Content: fmt.Sprintf("MCP resource formatting error: %v", err), IsError: true}, nil
	}
	return agentsdk.ToolResult{Content: string(data)}, nil
}

// ReadResourceTool reads a specific resource from an MCP server.
type ReadResourceTool struct {
	Manager ToolManager
}

func (t *ReadResourceTool) Name() string { return "ReadMcpResourceTool" }

func (t *ReadResourceTool) Description() string {
	return "Read a specific MCP resource by server name and URI."
}

func (t *ReadResourceTool) InputSchema() json.RawMessage {
	return json.RawMessage(`{
		"type":"object",
		"properties":{
			"server":{"type":"string","description":"MCP server name"},
			"uri":{"type":"string","description":"Resource URI"}
		},
		"required":["server","uri"]
	}`)
}

func (t *ReadResourceTool) IsReadOnly() bool { return true }

func (t *ReadResourceTool) IsEnabled(_ *agentsdk.RunContext) bool { return true }

func (t *ReadResourceTool) NeedsApproval() bool { return false }

func (t *ReadResourceTool) TimeoutSeconds() int { return 0 }

func (t *ReadResourceTool) Execute(ctx context.Context, input json.RawMessage, workDir string) (agentsdk.ToolResult, error) {
	var in struct {
		Server string `json:"server"`
		URI    string `json:"uri"`
	}
	if err := json.Unmarshal(input, &in); err != nil {
		return agentsdk.ToolResult{Content: fmt.Sprintf("Invalid input: %v", err), IsError: true}, nil
	}

	in.Server = strings.TrimSpace(in.Server)
	in.URI = strings.TrimSpace(in.URI)
	if in.Server == "" {
		return agentsdk.ToolResult{Content: "server is required", IsError: true}, nil
	}
	if in.URI == "" {
		return agentsdk.ToolResult{Content: "uri is required", IsError: true}, nil
	}

	readResult, err := t.Manager.ReadResource(ctx, in.Server, in.URI)
	if err != nil {
		return agentsdk.ToolResult{Content: fmt.Sprintf("MCP resource error: %v", err), IsError: true}, nil
	}

	content, err := FormatReadResourceResult(workDir, in.Server, readResult)
	if err != nil {
		return agentsdk.ToolResult{Content: fmt.Sprintf("MCP resource formatting error: %v", err), IsError: true}, nil
	}
	return agentsdk.ToolResult{Content: content}, nil
}

type readResourceOutput struct {
	Contents []readResourceContent `json:"contents"`
}

type readResourceContent struct {
	URI        string `json:"uri"`
	MIMEType   string `json:"mimeType,omitempty"`
	Text       string `json:"text,omitempty"`
	BlobSaved  string `json:"blobSavedTo,omitempty"`
	BlobSize   int    `json:"blobSize,omitempty"`
	BinaryHint string `json:"binaryHint,omitempty"`
}

// FormatReadResourceResult renders an MCP read-resource response as model-safe JSON.
func FormatReadResourceResult(workDir, serverName string, result *mcpsdk.ReadResourceResult) (string, error) {
	if result == nil {
		return `{"contents":[]}`, nil
	}

	out := readResourceOutput{
		Contents: make([]readResourceContent, 0, len(result.Contents)),
	}

	for i, content := range result.Contents {
		if content == nil {
			continue
		}
		item := readResourceContent{
			URI:      content.URI,
			MIMEType: content.MIMEType,
		}
		if content.Text != "" {
			item.Text = truncateMCPText(content.Text)
		}
		if len(content.Blob) > 0 {
			path, err := persistBinaryBlob(workDir, serverName, "resource", content.MIMEType, content.Blob, i)
			if err != nil {
				item.Text = fmt.Sprintf("Binary content could not be saved: %v", err)
			} else {
				item.BlobSaved = path
				item.BlobSize = len(content.Blob)
				item.BinaryHint = binarySavedMessage(path, content.MIMEType, len(content.Blob))
				if item.Text == "" {
					item.Text = item.BinaryHint
				}
			}
		}
		out.Contents = append(out.Contents, item)
	}

	data, err := json.Marshal(out)
	if err != nil {
		return "", err
	}
	return string(data), nil
}

// FormatCallToolResult renders an MCP tool call response as model-safe text/JSON.
func FormatCallToolResult(workDir string, desc ToolDescriptor, result *mcpsdk.CallToolResult) (string, error) {
	if result == nil {
		return "", nil
	}

	if len(result.Content) == 1 && result.StructuredContent == nil {
		if text, ok := result.Content[0].(*mcpsdk.TextContent); ok {
			return truncateMCPText(text.Text), nil
		}
	}

	payload := map[string]any{}
	if len(result.Content) > 0 {
		blocks := make([]any, 0, len(result.Content))
		for i, block := range result.Content {
			rendered, err := renderContentBlock(workDir, desc, block, i)
			if err != nil {
				return "", err
			}
			blocks = append(blocks, rendered)
		}
		payload["content"] = blocks
	}
	if result.StructuredContent != nil {
		payload["structuredContent"] = result.StructuredContent
	}
	if len(payload) == 0 {
		return "", nil
	}

	data, err := json.Marshal(payload)
	if err != nil {
		return "", err
	}
	return string(data), nil
}

func renderContentBlock(workDir string, desc ToolDescriptor, block mcpsdk.Content, index int) (any, error) {
	switch content := block.(type) {
	case *mcpsdk.TextContent:
		return map[string]any{
			"type": "text",
			"text": truncateMCPText(content.Text),
		}, nil

	case *mcpsdk.ImageContent:
		path, err := persistBinaryBlob(workDir, desc.ServerName, desc.ToolName, content.MIMEType, content.Data, index)
		if err != nil {
			return map[string]any{
				"type":     "image",
				"mimeType": content.MIMEType,
				"error":    err.Error(),
			}, nil
		}
		return map[string]any{
			"type":        "image",
			"mimeType":    content.MIMEType,
			"blobSavedTo": path,
			"note":        binarySavedMessage(path, content.MIMEType, len(content.Data)),
		}, nil

	case *mcpsdk.AudioContent:
		path, err := persistBinaryBlob(workDir, desc.ServerName, desc.ToolName, content.MIMEType, content.Data, index)
		if err != nil {
			return map[string]any{
				"type":     "audio",
				"mimeType": content.MIMEType,
				"error":    err.Error(),
			}, nil
		}
		return map[string]any{
			"type":        "audio",
			"mimeType":    content.MIMEType,
			"blobSavedTo": path,
			"note":        binarySavedMessage(path, content.MIMEType, len(content.Data)),
		}, nil

	case *mcpsdk.ResourceLink:
		return map[string]any{
			"type":        "resource_link",
			"uri":         content.URI,
			"name":        content.Name,
			"title":       content.Title,
			"description": content.Description,
			"mimeType":    content.MIMEType,
		}, nil

	case *mcpsdk.EmbeddedResource:
		if content.Resource == nil {
			return map[string]any{"type": "resource", "resource": nil}, nil
		}
		resource := map[string]any{
			"type":     "resource",
			"uri":      content.Resource.URI,
			"mimeType": content.Resource.MIMEType,
		}
		if content.Resource.Text != "" {
			resource["text"] = truncateMCPText(content.Resource.Text)
		}
		if len(content.Resource.Blob) > 0 {
			path, err := persistBinaryBlob(workDir, desc.ServerName, desc.ToolName, content.Resource.MIMEType, content.Resource.Blob, index)
			if err != nil {
				resource["error"] = err.Error()
			} else {
				resource["blobSavedTo"] = path
				resource["note"] = binarySavedMessage(path, content.Resource.MIMEType, len(content.Resource.Blob))
			}
		}
		return resource, nil

	default:
		raw, err := block.MarshalJSON()
		if err != nil {
			return map[string]any{"type": "unknown", "error": err.Error()}, nil
		}
		var parsed any
		if err := json.Unmarshal(raw, &parsed); err != nil {
			return string(raw), nil
		}
		return parsed, nil
	}
}

func persistBinaryBlob(workDir, serverName, sourceName, mimeType string, data []byte, index int) (string, error) {
	if len(data) > maxMCPBlobBytes {
		return "", fmt.Errorf("binary content is %d bytes; max allowed is %d bytes", len(data), maxMCPBlobBytes)
	}
	relDir := filepath.Join(".mcp", "blobs")
	if _, err := resolveWorkspaceOutputDir(workDir, relDir); err != nil {
		return "", err
	}
	if err := mkdirAllBeneath(workDir, relDir, 0o700); err != nil {
		return "", fmt.Errorf("create blob dir: %w", err)
	}

	prefix := sanitizeBlobPrefix(serverName + "-" + sourceName)
	if prefix == "" {
		prefix = "mcp"
	}
	ext := fileExtFromMIME(mimeType)
	filename := fmt.Sprintf("%s-%d-%d%s", prefix, time.Now().UnixNano(), index, ext)
	path, err := resolveWorkspaceOutputDir(workDir, filepath.Join(relDir, filename))
	if err != nil {
		return "", err
	}

	if err := createExclusiveBeneath(workDir, filepath.Join(relDir, filename), data, 0o600); err != nil {
		return "", fmt.Errorf("write blob: %w", err)
	}
	return path, nil
}

func resolveWorkspaceOutputDir(workDir, relDir string) (string, error) {
	if strings.TrimSpace(workDir) == "" {
		return "", fmt.Errorf("workspace root is required")
	}
	baseAbs, err := filepath.Abs(workDir)
	if err != nil {
		return "", fmt.Errorf("resolve workspace root: %w", err)
	}
	base, err := filepath.EvalSymlinks(baseAbs)
	if err != nil {
		return "", fmt.Errorf("resolve workspace root symlinks: %w", err)
	}
	target := filepath.Clean(filepath.Join(baseAbs, relDir))
	checked, err := resolveExistingOutputPath(target)
	if err != nil {
		return "", fmt.Errorf("resolve output path symlinks: %w", err)
	}
	rel, err := filepath.Rel(base, checked)
	if err != nil {
		return "", err
	}
	if rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return "", fmt.Errorf("output path %s is outside workspace root %s", relDir, workDir)
	}
	return target, nil
}

func resolveExistingOutputPath(path string) (string, error) {
	clean := filepath.Clean(path)
	if resolved, err := filepath.EvalSymlinks(clean); err == nil {
		return resolved, nil
	} else if !os.IsNotExist(err) {
		return "", err
	}
	for parent := clean; ; parent = filepath.Dir(parent) {
		if _, err := os.Lstat(parent); err == nil {
			resolved, evalErr := filepath.EvalSymlinks(parent)
			if evalErr != nil {
				return "", evalErr
			}
			rel, relErr := filepath.Rel(parent, clean)
			if relErr != nil {
				return "", relErr
			}
			return filepath.Clean(filepath.Join(resolved, rel)), nil
		} else if !os.IsNotExist(err) {
			return "", err
		}
		next := filepath.Dir(parent)
		if next == parent {
			return clean, nil
		}
	}
}

func sanitizeBlobPrefix(s string) string {
	s = invalidBlobNameChars.ReplaceAllString(s, "_")
	s = strings.Trim(s, "_")
	if s == "" {
		return "mcp"
	}
	if len(s) > maxBlobPrefixLength {
		s = strings.TrimRight(s[:maxBlobPrefixLength], "._-")
		if s == "" {
			return "mcp"
		}
	}
	return s
}

func truncateMCPText(s string) string {
	if len(s) <= maxMCPTextBytes {
		return s
	}
	cut := maxMCPTextBytes
	for cut > 0 && (s[cut]&0xc0) == 0x80 {
		cut--
	}
	if cut <= 0 {
		cut = maxMCPTextBytes
	}
	return s[:cut] + mcpTruncationMessage
}

func fileExtFromMIME(mimeType string) string {
	if strings.TrimSpace(mimeType) == "" {
		return ".bin"
	}
	exts, err := mime.ExtensionsByType(mimeType)
	if err != nil || len(exts) == 0 {
		return ".bin"
	}
	return exts[0]
}

func binarySavedMessage(path, mimeType string, size int) string {
	if strings.TrimSpace(mimeType) == "" {
		mimeType = "application/octet-stream"
	}
	return fmt.Sprintf("Binary content saved to %s (%d bytes, %s)", path, size, mimeType)
}

package mcp

import (
	"context"
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"

	mcpsdk "github.com/modelcontextprotocol/go-sdk/mcp"
)

type fakeToolManager struct {
	descriptors []ToolDescriptor
	resources   []ResourceDescriptor
	callResult  *mcpsdk.CallToolResult
	readResult  *mcpsdk.ReadResourceResult
	callArgs    map[string]any
}

func (f *fakeToolManager) ToolDescriptors() []ToolDescriptor {
	return append([]ToolDescriptor(nil), f.descriptors...)
}

func (f *fakeToolManager) ConnectedServerNames() []string { return []string{"files"} }

func (f *fakeToolManager) HasResources() bool { return f.resources != nil || f.readResult != nil }

func (f *fakeToolManager) CallTool(ctx context.Context, qualifiedName string, args map[string]any) (*mcpsdk.CallToolResult, error) {
	f.callArgs = args
	return f.callResult, nil
}

func (f *fakeToolManager) ListResources(ctx context.Context, serverName string) ([]ResourceDescriptor, error) {
	return append([]ResourceDescriptor(nil), f.resources...), nil
}

func (f *fakeToolManager) ReadResource(ctx context.Context, serverName, uri string) (*mcpsdk.ReadResourceResult, error) {
	return f.readResult, nil
}

func TestDynamicToolExecutesAndReturnsSingleTextContent(t *testing.T) {
	t.Parallel()

	manager := &fakeToolManager{
		callResult: &mcpsdk.CallToolResult{
			Content: []mcpsdk.Content{&mcpsdk.TextContent{Text: "created"}},
		},
	}
	tool := &DynamicTool{
		Manager: manager,
		Descriptor: ToolDescriptor{
			QualifiedName: "mcp__github__create_issue",
			ServerName:    "github",
			ToolName:      "create_issue",
		},
	}

	result, err := tool.Execute(context.Background(), json.RawMessage(`{"title":"bug"}`), t.TempDir())
	if err != nil {
		t.Fatalf("Execute() error = %v", err)
	}
	if result.IsError {
		t.Fatalf("IsError = true, want false")
	}
	if result.Content != "created" {
		t.Fatalf("Content = %q, want created", result.Content)
	}
	if manager.callArgs["title"] != "bug" {
		t.Fatalf("call args = %#v, want title", manager.callArgs)
	}
}

func TestNormalizeInputSchemaAddsEmptyPropertiesForObjectTools(t *testing.T) {
	t.Parallel()

	got := normalizeInputSchema(map[string]any{
		"type":                 "object",
		"additionalProperties": false,
	})
	var schema map[string]any
	if err := json.Unmarshal(got, &schema); err != nil {
		t.Fatalf("schema is not JSON: %v", err)
	}
	if schema["type"] != "object" {
		t.Fatalf("type = %v, want object", schema["type"])
	}
	props, ok := schema["properties"].(map[string]any)
	if !ok || len(props) != 0 {
		t.Fatalf("properties = %#v, want empty object", schema["properties"])
	}
	if schema["additionalProperties"] != false {
		t.Fatalf("additionalProperties = %v, want false", schema["additionalProperties"])
	}
}

func TestFormatCallToolResultSavesBinaryContent(t *testing.T) {
	t.Parallel()

	workDir := t.TempDir()
	rendered, err := FormatCallToolResult(workDir, ToolDescriptor{
		ServerName: "files",
		ToolName:   "preview",
	}, &mcpsdk.CallToolResult{
		Content: []mcpsdk.Content{
			&mcpsdk.ImageContent{MIMEType: "image/png", Data: []byte("png-data")},
		},
	})
	if err != nil {
		t.Fatalf("FormatCallToolResult() error = %v", err)
	}
	if !strings.Contains(rendered, `"blobSavedTo"`) {
		t.Fatalf("rendered = %s, want saved blob", rendered)
	}

	var payload struct {
		Content []struct {
			BlobSavedTo string `json:"blobSavedTo"`
		} `json:"content"`
	}
	if err := json.Unmarshal([]byte(rendered), &payload); err != nil {
		t.Fatalf("json.Unmarshal() error = %v", err)
	}
	if len(payload.Content) != 1 || payload.Content[0].BlobSavedTo == "" {
		t.Fatalf("payload = %#v, want saved blob path", payload)
	}
	data, err := os.ReadFile(payload.Content[0].BlobSavedTo)
	if err != nil {
		t.Fatalf("ReadFile(blob) error = %v", err)
	}
	if string(data) != "png-data" {
		t.Fatalf("blob = %q, want png-data", string(data))
	}
	info, err := os.Stat(payload.Content[0].BlobSavedTo)
	if err != nil {
		t.Fatalf("Stat(blob) error = %v", err)
	}
	if mode := info.Mode().Perm(); mode != 0o600 {
		t.Fatalf("blob mode = %o, want 0o600", mode)
	}
	dirInfo, err := os.Stat(filepath.Dir(payload.Content[0].BlobSavedTo))
	if err != nil {
		t.Fatalf("Stat(blob dir) error = %v", err)
	}
	if mode := dirInfo.Mode().Perm(); mode != 0o700 {
		t.Fatalf("blob dir mode = %o, want 0o700", mode)
	}
}

func TestFormatCallToolResultTruncatesLargeText(t *testing.T) {
	t.Parallel()

	rendered, err := FormatCallToolResult(t.TempDir(), ToolDescriptor{
		ServerName: "files",
		ToolName:   "read",
	}, &mcpsdk.CallToolResult{
		Content: []mcpsdk.Content{
			&mcpsdk.TextContent{Text: strings.Repeat("x", maxMCPTextBytes+1)},
		},
	})
	if err != nil {
		t.Fatalf("FormatCallToolResult() error = %v", err)
	}
	if len(rendered) > maxMCPTextBytes+len(mcpTruncationMessage) || !strings.Contains(rendered, mcpTruncationMessage) {
		t.Fatalf("rendered text was not truncated as expected; len=%d", len(rendered))
	}
}

func TestFormatCallToolResultRejectsOversizedBinaryContent(t *testing.T) {
	t.Parallel()

	rendered, err := FormatCallToolResult(t.TempDir(), ToolDescriptor{
		ServerName: "files",
		ToolName:   "preview",
	}, &mcpsdk.CallToolResult{
		Content: []mcpsdk.Content{
			&mcpsdk.ImageContent{MIMEType: "image/png", Data: make([]byte, maxMCPBlobBytes+1)},
		},
	})
	if err != nil {
