package memory

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"strings"
	"time"

	openai "github.com/gratefulagents/sdk/pkg/agentsdk/providers/openai"
)

const (
	defaultEmbeddingTimeout  = 20 * time.Second
	maxEmbeddingResponseBody = 2 * 1024 * 1024
)

// OpenAIEmbedder embeds text through the OpenAI embeddings API.
type OpenAIEmbedder struct {
	baseURL string
	auth    *openai.OpenAIAuthSession
	model   string
	client  *http.Client
}

func NewOpenAIEmbedder(auth *openai.OpenAIAuthSession, baseURL string, model string) *OpenAIEmbedder {
	if model == "" {
		model = "text-embedding-3-small"
	}
	baseURL = strings.TrimSpace(baseURL)
	if baseURL == "" {
		baseURL = "https://api.openai.com/v1"
	}
	baseURL = strings.TrimRight(baseURL, "/")
	return &OpenAIEmbedder{
		baseURL: baseURL,
		auth:    auth,
		model:   model,
		client:  &http.Client{Timeout: defaultEmbeddingTimeout},
	}
}

type embeddingRequest struct {
	Input string `json:"input"`
	Model string `json:"model"`
}

type embeddingResponse struct {
	Data []struct {
		Embedding []float32 `json:"embedding"`
	} `json:"data"`
	Error *struct {
		Message string `json:"message"`
	} `json:"error,omitempty"`
}

func (e *OpenAIEmbedder) Embed(ctx context.Context, text string) ([]float32, error) {
	if e.auth == nil {
		return nil, fmt.Errorf("OpenAI auth session is not configured")
	}
	body, err := json.Marshal(embeddingRequest{Input: text, Model: e.model})
	if err != nil {
		return nil, fmt.Errorf("marshalling request: %w", err)
	}

	req, err := http.NewRequestWithContext(ctx, http.MethodPost, e.baseURL+"/embeddings", bytes.NewReader(body))
	if err != nil {
		return nil, fmt.Errorf("creating request: %w", err)
	}
	req.Header.Set("Content-Type", "application/json")
	headers, err := e.auth.RequestHeaders(ctx)
	if err != nil {
		return nil, fmt.Errorf("building auth headers: %w", err)
	}
	for key, value := range headers {
		req.Header.Set(key, value)
	}

	resp, err := e.client.Do(req)
	if err != nil {
		return nil, fmt.Errorf("calling OpenAI embeddings API: %w", err)
	}
	defer resp.Body.Close()

	respBody, err := io.ReadAll(io.LimitReader(resp.Body, maxEmbeddingResponseBody+1))
	if err != nil {
		return nil, fmt.Errorf("reading response body: %w", err)
	}
	if len(respBody) > maxEmbeddingResponseBody {
		return nil, fmt.Errorf("embedding response exceeds %d bytes", maxEmbeddingResponseBody)
	}

	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("OpenAI API returned status %d: %s", resp.StatusCode, string(respBody))
	}

	var result embeddingResponse
	if err := json.Unmarshal(respBody, &result); err != nil {
		return nil, fmt.Errorf("decoding response: %w", err)
	}
	if result.Error != nil {
		return nil, fmt.Errorf("OpenAI API error: %s", result.Error.Message)
	}
	if len(result.Data) == 0 {
		return nil, fmt.Errorf("no embedding returned")
	}
	return result.Data[0].Embedding, nil
}

// SetHTTPClient overrides the HTTP client, mainly for tests.
func (e *OpenAIEmbedder) SetHTTPClient(client *http.Client) {
	if client != nil {
		e.client = client
	}
}

package memory

import (
	"context"
	"net/http"
	"net/http/httptest"
	"sync/atomic"
	"testing"

	openai "github.com/gratefulagents/sdk/pkg/agentsdk/providers/openai"
)

func TestOpenAIEmbedderRefreshesOldOpaqueOAuthToken(t *testing.T) {
	var refreshCalls atomic.Int32
	var embeddingCalls atomic.Int32
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, req *http.Request) {
		switch req.URL.Path {
		case "/token":
			refreshCalls.Add(1)
			w.Header().Set("Content-Type", "application/json")
			_, _ = w.Write([]byte(`{"access_token":"fresh-access","refresh_token":"fresh-refresh"}`))
		case "/embeddings":
			embeddingCalls.Add(1)
			if got := req.Header.Get("Authorization"); got != "Bearer fresh-access" {
				t.Errorf("Authorization = %q, want refreshed access token", got)
			}
			w.Header().Set("Content-Type", "application/json")
			_, _ = w.Write([]byte(`{"data":[{"embedding":[0.25,0.75]}]}`))
		default:
			http.NotFound(w, req)
		}
	}))
	defer server.Close()

	session, err := openai.NewOAuthAuthSessionFromConfig(openai.OAuthSessionConfig{
		AuthJSON:      []byte(`{"tokens":{"access_token":"opaque-access","refresh_token":"old-refresh","account_id":"acct-1"},"last_refresh":"2000-01-01T00:00:00Z"}`),
		TokenEndpoint: server.URL + "/token",
	})
	if err != nil {
		t.Fatalf("NewOAuthAuthSessionFromConfig() error = %v", err)
	}
	embedder := NewOpenAIEmbedder(session, server.URL, "text-embedding-test")

	vector, err := embedder.Embed(context.Background(), "hello")
	if err != nil {
		t.Fatalf("Embed() error = %v", err)
	}
	if len(vector) != 2 || vector[0] != 0.25 || vector[1] != 0.75 {
		t.Fatalf("embedding = %#v, want [0.25 0.75]", vector)
	}
	if got := refreshCalls.Load(); got != 1 {
		t.Fatalf("refresh calls = %d, want 1", got)
	}
	if got := embeddingCalls.Load(); got != 1 {
		t.Fatalf("embedding calls = %d, want 1", got)
	}
}

package memory

import (
	"context"
	"encoding/json"
	"fmt"
	"math"
	"sort"
	"strings"
	"sync"
	"time"

	"github.com/google/uuid"
)

// Memory represents a single stored memory entry.
type Memory struct {
	ID         uuid.UUID       `json:"id"`
	Namespace  string          `json:"namespace"`
	Content    string          `json:"content"`
	Tags       []string        `json:"tags"`
	SourceRun  string          `json:"source_run"`
	Metadata   json.RawMessage `json:"metadata"`
	Similarity float64         `json:"similarity,omitempty"`
	CreatedAt  time.Time       `json:"created_at"`
}

// Embedder produces vector embeddings from text.
type Embedder interface {
	Embed(ctx context.Context, text string) ([]float32, error)
}

// Store persists and retrieves semantic memories.
type Store interface {
	Store(ctx context.Context, namespace, content string, tags []string, sourceRun string, metadata json.RawMessage) (*Memory, error)
	Search(ctx context.Context, namespace, query string, tags []string, limit int) ([]Memory, error)
	List(ctx context.Context, namespace string, tags []string, limit int) ([]Memory, error)
	Delete(ctx context.Context, namespace string, id uuid.UUID) error
}

// InMemoryStore is a small process-local Store implementation for SDK clients
// that do not need durable storage. Search uses simple substring keyword
// matching, not vector similarity — for true semantic search, plug in a Store
// backed by a vector database.
type InMemoryStore struct {
	mu       sync.RWMutex
	memories []Memory
}

// NewInMemoryStore returns an empty in-memory memory store.
func NewInMemoryStore() *InMemoryStore {
	return &InMemoryStore{}
}

func (s *InMemoryStore) Store(_ context.Context, namespace, content string, tags []string, sourceRun string, metadata json.RawMessage) (*Memory, error) {
	if namespace == "" {
		return nil, fmt.Errorf("namespace is required")
	}
	if content == "" {
		return nil, fmt.Errorf("content is required")
	}
	if tags == nil {
		tags = []string{}
	}
	if metadata == nil {
		metadata = json.RawMessage(`{}`)
	}

	mem := Memory{
		ID:        uuid.New(),
		Namespace: namespace,
		Content:   content,
		Tags:      append([]string(nil), tags...),
		SourceRun: sourceRun,
		Metadata:  append(json.RawMessage(nil), metadata...),
		CreatedAt: time.Now().UTC(),
	}

	s.mu.Lock()
	s.memories = append(s.memories, mem)
	s.mu.Unlock()

	out := cloneMemory(mem)
	return &out, nil
}

func (s *InMemoryStore) Search(_ context.Context, namespace, query string, tags []string, limit int) ([]Memory, error) {
	if namespace == "" {
		return nil, fmt.Errorf("namespace is required")
	}
	if query == "" {
		return nil, fmt.Errorf("query is required")
	}
	if limit <= 0 {
		limit = 10
	}

	query = strings.ToLower(query)
	terms := uniqueNonEmptyTerms(strings.Fields(query))
	out := s.filter(namespace, tags)
	scored := out[:0]
	for _, mem := range out {
		content := strings.ToLower(mem.Content)
		matched := 0
		for _, term := range terms {
			if strings.Contains(content, term) {
				matched++
			}
		}
		// Distinct-term matches are capped below the exact-phrase score so
		// many partial hits can never outrank an exact match.
		mem.Similarity = math.Min(0.9, 0.25*float64(matched))
		if strings.Contains(content, query) {
			mem.Similarity = 1
		}
		if mem.Similarity > 0 {
			scored = append(scored, mem)
		}
	}
	sort.SliceStable(scored, func(i, j int) bool {
		if scored[i].Similarity == scored[j].Similarity {
			return scored[i].CreatedAt.After(scored[j].CreatedAt)
		}
		return scored[i].Similarity > scored[j].Similarity
	})
	return limitMemories(scored, limit), nil
}

func (s *InMemoryStore) List(_ context.Context, namespace string, tags []string, limit int) ([]Memory, error) {
	if namespace == "" {
		return nil, fmt.Errorf("namespace is required")
	}
	if limit <= 0 {
		limit = 50
	}
	out := s.filter(namespace, tags)
	sort.SliceStable(out, func(i, j int) bool {
		return out[i].CreatedAt.After(out[j].CreatedAt)
	})
	return limitMemories(out, limit), nil
}

func (s *InMemoryStore) Delete(_ context.Context, namespace string, id uuid.UUID) error {
	if namespace == "" {
		return fmt.Errorf("namespace is required")
	}

	s.mu.Lock()
	defer s.mu.Unlock()
	for i, mem := range s.memories {
		if mem.Namespace == namespace && mem.ID == id {
			s.memories = append(s.memories[:i], s.memories[i+1:]...)
			return nil
		}
	}
	return fmt.Errorf("memory not found")
}

func (s *InMemoryStore) filter(namespace string, tags []string) []Memory {
	s.mu.RLock()
	defer s.mu.RUnlock()

	out := make([]Memory, 0, len(s.memories))
	for _, mem := range s.memories {
		if mem.Namespace != namespace {
			continue
		}
		if len(tags) > 0 && !hasAnyTag(mem.Tags, tags) {
			continue
		}
		out = append(out, cloneMemory(mem))
	}
	return out
}

func hasAnyTag(actual, wanted []string) bool {
	set := make(map[string]struct{}, len(actual))
	for _, tag := range actual {
		set[tag] = struct{}{}
	}
	for _, tag := range wanted {
		if _, ok := set[tag]; ok {
			return true
		}
	}
	return false
}

func uniqueNonEmptyTerms(terms []string) []string {
	seen := make(map[string]struct{}, len(terms))
	out := terms[:0]
	for _, term := range terms {
		if term == "" {
			continue
		}
		if _, ok := seen[term]; ok {
			continue
		}
		seen[term] = struct{}{}
		out = append(out, term)
	}
	return out
}

func cloneMemory(mem Memory) Memory {
	mem.Tags = append([]string(nil), mem.Tags...)
	mem.Metadata = append(json.RawMessage(nil), mem.Metadata...)
	return mem
}

func limitMemories(memories []Memory, limit int) []Memory {
	if limit > 0 && len(memories) > limit {
		memories = memories[:limit]
	}
	out := make([]Memory, len(memories))
	copy(out, memories)
	return out
}

// NoopEmbedder returns all-zero embeddings and is useful for local examples.
type NoopEmbedder struct {
	Dimension int
}

func (e *NoopEmbedder) Embed(_ context.Context, _ string) ([]float32, error) {
	dim := e.Dimension
	if dim <= 0 {
		dim = 1536
	}
	return make([]float32, dim), nil
}

// VectorLiteral converts a vector to the pgvector literal format.
func VectorLiteral(v []float32) string {
	if len(v) == 0 {
		return "[]"
	}
	parts := make([]string, len(v))
	for i, f := range v {
		parts[i] = fmt.Sprintf("%g", f)
	}
	return "[" + strings.Join(parts, ",") + "]"
}

