func TestInMemoryStoreLifecycle(t *testing.T) {
	store := NewInMemoryStore()
	ctx := context.Background()

	mem, err := store.Store(ctx, "ns", "remember the build command", []string{"build"}, "run-1", nil)
	if err != nil {
		t.Fatalf("Store() error = %v", err)
	}

	found, err := store.Search(ctx, "ns", "build command", nil, 10)
	if err != nil {
		t.Fatalf("Search() error = %v", err)
	}
	if len(found) != 1 || found[0].ID != mem.ID {
		t.Fatalf("Search() = %#v, want stored memory", found)
	}

	listed, err := store.List(ctx, "ns", []string{"build"}, 10)
	if err != nil {
		t.Fatalf("List() error = %v", err)
	}
	if len(listed) != 1 || listed[0].ID != mem.ID {
		t.Fatalf("List() = %#v, want stored memory", listed)
	}

	if err := store.Delete(ctx, "ns", mem.ID); err != nil {
		t.Fatalf("Delete() error = %v", err)
	}
	listed, err = store.List(ctx, "ns", nil, 10)
	if err != nil {
		t.Fatalf("List() after delete error = %v", err)
	}
	if len(listed) != 0 {
		t.Fatalf("List() after delete = %#v, want empty", listed)
	}
}

// Package mode defines the SDK-native mode template shape.
//
// A mode template is a named runtime preset for the parent agent: prompt
// instructions, model routing, run constraints, autonomy, and tool access.
// Specialist sub-agents are configured separately through the role catalog.
package mode

// TemplateSpec is the SDK-native mode template shape.
type TemplateSpec struct {
	Name        string
	Version     string
	DisplayName string
	Description string
	Category    string
	Autonomous  bool
	// ToolAccess constrains the run's tool surface while the mode is active.
	// Recognized values: "" (inherit), "full", "read-only".
	ToolAccess   string
	Instructions string
	ModelRouting *ModelRouting
	Constraints  *Constraints
}

type Constraints struct {
	MaxTurns               int
	SubAgentMaxTurns       int
	MaxConcurrentSubAgents int
	MaxRetries             int
	MaxRuntimeMinutes      int
}

type ModelRouting struct {
	DefaultModel   string
	FallbackModels []string
	ReasoningLevel string
	TextVerbosity  string
	RoleOverrides  map[string]RoleModelRouting
}

type RoleModelRouting struct {
	Model          string
	FallbackModels []string
	ReasoningLevel string
	TextVerbosity  string
}

// Package modelsdev resolves per-model context-window limits from the
// models.dev open catalog (https://models.dev/api.json).
//
// Provider-hosted /models endpoints routinely under-report real limits (e.g.
// GitHub Copilot advertises a 200K prompt cap for claude-fable-5 while the
// deployment accepts 1M-context requests), so models.dev is treated as the
// authoritative source for compaction thresholds. The catalog is fetched
// lazily, cached in memory and on disk with a TTL, and served stale on fetch
// errors so offline runs keep working.
package modelsdev

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"
)

const (
	// CatalogURL is the models.dev catalog endpoint.
	CatalogURL = "https://models.dev/api.json"

	defaultFetchTimeout = 20 * time.Second
	defaultCacheTTL     = 24 * time.Hour
	maxCatalogBytes     = 64 << 20
)

// ModelLimits are the context/output token limits for one model.
type ModelLimits struct {
	ContextTokens int `json:"context"`
	OutputTokens  int `json:"output"`
}

// Catalog is a parsed models.dev catalog: provider ID -> model ID -> limits.
type Catalog map[string]map[string]ModelLimits

// providerAliases maps runtime provider/prefix names to models.dev provider
// IDs. Both sides are matched lower-case. Note: "openai-oauth" (the ChatGPT
// codex backend at chatgpt.com/backend-api/codex) is deliberately absent —
// models.dev has no provider for that deployment and its windows differ from
// the OpenAI API (e.g. 272K vs 400K/1M), so lookups must miss and fall
// through to the codex backend's own /models metadata.
var providerAliases = map[string]string{
	"copilot":         "github-copilot",
	"github-copilot":  "github-copilot",
	"openai":          "openai",
	"anthropic":       "anthropic",
	"anthropic-oauth": "anthropic",
}

// Resolver lazily fetches and caches the models.dev catalog and answers
// per-(provider, model) limit lookups. Safe for concurrent use.
type Resolver struct {
	mu        sync.Mutex
	catalog   Catalog
	fetchedAt time.Time
	client    *http.Client
	cachePath string
	ttl       time.Duration
	url       string
}

// Option configures a Resolver.
type Option func(*Resolver)

// WithCachePath sets the on-disk cache location (default:
// os.UserCacheDir()/gratefulagents/modelsdev.json).
func WithCachePath(path string) Option { return func(r *Resolver) { r.cachePath = path } }

// WithTTL overrides the cache freshness window.
func WithTTL(ttl time.Duration) Option { return func(r *Resolver) { r.ttl = ttl } }

// WithHTTPClient overrides the HTTP client.
func WithHTTPClient(c *http.Client) Option { return func(r *Resolver) { r.client = c } }

// WithURL overrides the catalog URL (tests).
func WithURL(url string) Option { return func(r *Resolver) { r.url = url } }

// NewResolver builds a catalog resolver.
func NewResolver(opts ...Option) *Resolver {
	r := &Resolver{
		client: &http.Client{Timeout: defaultFetchTimeout},
		ttl:    defaultCacheTTL,
		url:    CatalogURL,
	}
	if dir, err := os.UserCacheDir(); err == nil {
		r.cachePath = filepath.Join(dir, "gratefulagents", "modelsdev.json")
	}
	for _, opt := range opts {
		opt(r)
	}
	return r
}

// Lookup returns the limits for a model under a provider. The provider is an
// SDK provider or route prefix name ("copilot", "openai-oauth", ...); the
// model may carry a "prefix/" which is stripped for matching. Model IDs are
// matched case-insensitively, exact first and then with date/version suffix
// tolerance (catalog "claude-fable-5" matches request "claude-fable-5-20260601").
func (r *Resolver) Lookup(ctx context.Context, provider, model string) (ModelLimits, bool) {
	catalog := r.catalogSnapshot(ctx)
	if len(catalog) == 0 {
		return ModelLimits{}, false
	}
	providerID := providerAliases[strings.ToLower(strings.TrimSpace(provider))]
	if providerID == "" {
		providerID = strings.ToLower(strings.TrimSpace(provider))
	}
	models := catalog[providerID]
	if len(models) == 0 {
		return ModelLimits{}, false
	}
	id := normalizeModelID(model)
	if id == "" {
		return ModelLimits{}, false
	}
	if limits, ok := models[id]; ok && limits.ContextTokens > 0 {
		return limits, true
	}
	// Suffix tolerance: longest catalog ID that prefixes the requested ID
	// (or vice versa) wins, so dated snapshots resolve to their base model.
	bestLen := 0
	var best ModelLimits
	for candidate, limits := range models {
		if limits.ContextTokens <= 0 {
			continue
		}
		if strings.HasPrefix(id, candidate) || strings.HasPrefix(candidate, id) {
			if len(candidate) > bestLen {
				bestLen = len(candidate)
				best = limits
			}
		}
	}
	if bestLen > 0 {
		return best, true
	}
	return ModelLimits{}, false
}

// CompactionThresholds derives compaction trigger/target tokens from the
// model's context window: trigger at 90% (10% headroom for the next turn),
// target at 50%.
func (r *Resolver) CompactionThresholds(ctx context.Context, provider, model string) (triggerTokens, targetTokens int, ok bool) {
	limits, found := r.Lookup(ctx, provider, model)
	if !found || limits.ContextTokens <= 0 {
		return 0, 0, false
	}
	return (limits.ContextTokens * 9) / 10, limits.ContextTokens / 2, true
}

// CompactionResolverFunc adapts the resolver to the SDK's
// CompactionModelResolver shape. The model's route prefix (before "/")
// selects the provider; defaultProvider applies to unprefixed models.
func (r *Resolver) CompactionResolverFunc(defaultProvider string) func(ctx context.Context, model string) (int, int, bool) {
	return func(ctx context.Context, model string) (int, int, bool) {
		provider := defaultProvider
		if idx := strings.Index(strings.TrimSpace(model), "/"); idx > 0 {
			provider = strings.TrimSpace(model)[:idx]
		}
		return r.CompactionThresholds(ctx, provider, model)
	}
}

func normalizeModelID(model string) string {
	model = strings.TrimSpace(model)
	if idx := strings.Index(model, "/"); idx >= 0 {
		model = model[idx+1:]
	}
	return strings.ToLower(strings.TrimSpace(model))
}

// catalogSnapshot returns the current catalog, fetching or refreshing it if
// needed. Errors fall back to any previously loaded (memory or disk) copy.
func (r *Resolver) catalogSnapshot(ctx context.Context) Catalog {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.catalog != nil && time.Since(r.fetchedAt) < r.ttl {
		return r.catalog
	}
	if r.catalog == nil {
		if catalog, at, err := r.loadDiskCache(); err == nil {
			r.catalog = catalog
			r.fetchedAt = at
			if time.Since(at) < r.ttl {
				return r.catalog
			}
		}
	}
	catalog, err := r.fetch(ctx)
	if err != nil {
		// Serve stale on error; nil when nothing was ever loaded.
		return r.catalog
	}
	r.catalog = catalog
	r.fetchedAt = time.Now()
	r.saveDiskCache(catalog)
	return r.catalog
}

func (r *Resolver) fetch(ctx context.Context) (Catalog, error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, r.url, nil)
	if err != nil {
		return nil, err
	}
	req.Header.Set("Accept", "application/json")
	resp, err := r.client.Do(req)
	if err != nil {
		return nil, err
	}
	defer func() { _ = resp.Body.Close() }()
	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("models.dev returned status %d", resp.StatusCode)
	}
	body, err := io.ReadAll(io.LimitReader(resp.Body, maxCatalogBytes))
	if err != nil {
		return nil, err
	}
	return ParseCatalog(body)
}

// ParseCatalog parses the models.dev api.json payload into a Catalog.
func ParseCatalog(body []byte) (Catalog, error) {
	var raw map[string]struct {
		Models map[string]struct {
			Limit struct {
				Context int `json:"context"`
				Output  int `json:"output"`
			} `json:"limit"`
		} `json:"models"`
	}
	if err := json.Unmarshal(body, &raw); err != nil {
		return nil, fmt.Errorf("decode models.dev catalog: %w", err)
	}
	catalog := make(Catalog, len(raw))
	for providerID, provider := range raw {
		if len(provider.Models) == 0 {
			continue
		}
		models := make(map[string]ModelLimits, len(provider.Models))
		for modelID, m := range provider.Models {
			id := strings.ToLower(strings.TrimSpace(modelID))
			if id == "" || m.Limit.Context <= 0 {
				continue
			}
			models[id] = ModelLimits{ContextTokens: m.Limit.Context, OutputTokens: m.Limit.Output}
		}
		if len(models) > 0 {
			catalog[strings.ToLower(strings.TrimSpace(providerID))] = models
		}
	}
	if len(catalog) == 0 {
		return nil, fmt.Errorf("models.dev catalog contained no models")
	}
	return catalog, nil
}

type diskCacheEnvelope struct {
	FetchedAt time.Time `json:"fetched_at"`
	Catalog   Catalog   `json:"catalog"`
}

func (r *Resolver) loadDiskCache() (Catalog, time.Time, error) {
	if r.cachePath == "" {
		return nil, time.Time{}, fmt.Errorf("no cache path")
	}
	data, err := os.ReadFile(r.cachePath)
	if err != nil {
		return nil, time.Time{}, err
	}
	var envelope diskCacheEnvelope
	if err := json.Unmarshal(data, &envelope); err != nil {
		return nil, time.Time{}, err
	}
	if len(envelope.Catalog) == 0 {
		return nil, time.Time{}, fmt.Errorf("empty cached catalog")
	}
	return envelope.Catalog, envelope.FetchedAt, nil
}

func (r *Resolver) saveDiskCache(catalog Catalog) {
	if r.cachePath == "" {
		return
	}
	data, err := json.Marshal(diskCacheEnvelope{FetchedAt: time.Now(), Catalog: catalog})
	if err != nil {
		return
	}
	if err := os.MkdirAll(filepath.Dir(r.cachePath), 0o755); err != nil {
		return
	}
	_ = os.WriteFile(r.cachePath, data, 0o644)
}

package modelsdev

import (
	"context"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"sync/atomic"
	"testing"
	"time"
)

const sampleCatalog = `{
  "github-copilot": {
    "models": {
      "claude-fable-5": {"limit": {"context": 1000000, "output": 128000}},
      "gpt-5.3-codex": {"limit": {"context": 400000, "output": 128000}}
    }
  },
  "openai": {
    "models": {
      "gpt-5.3-codex-spark": {"limit": {"context": 128000, "output": 32000}},
      "gpt-5.6-sol": {"limit": {"context": 1050000, "output": 128000}},
      "gpt-5.4": {"limit": {"context": 1050000, "output": 128000}}
    }
  },
  "anthropic": {
    "models": {
      "claude-fable-5": {"limit": {"context": 1000000, "output": 128000}},
      "claude-fable-5-20260601": {"limit": {"context": 1000000, "output": 128000}}
    }
  }
}`

func testResolver(t *testing.T) (*Resolver, *atomic.Int32) {
	t.Helper()
	var hits atomic.Int32
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		hits.Add(1)
		_, _ = w.Write([]byte(sampleCatalog))
	}))
	t.Cleanup(server.Close)
	r := NewResolver(
		WithURL(server.URL),
		WithCachePath(filepath.Join(t.TempDir(), "catalog.json")),
	)
	return r, &hits
}

func TestLookupProviderAliasesAndPrefixes(t *testing.T) {
	r, _ := testResolver(t)
	ctx := context.Background()

	// copilot alias -> github-copilot; prefixed model ID stripped.
	limits, ok := r.Lookup(ctx, "copilot", "copilot/claude-fable-5")
	if !ok || limits.ContextTokens != 1000000 {
		t.Fatalf("copilot fable = %+v ok=%v, want 1M", limits, ok)
	}
	// Same model, different provider, different window.
	limits, ok = r.Lookup(ctx, "openai", "gpt-5.3-codex-spark")
	if !ok || limits.ContextTokens != 128000 {
		t.Fatalf("openai spark = %+v ok=%v, want 128K", limits, ok)
	}
	// The ChatGPT codex backend is not cataloged by models.dev; the lookup
	// must miss so resolvers fall through to the backend's own /models.
	if _, ok := r.Lookup(ctx, "openai-oauth", "gpt-5.3-codex-spark"); ok {
		t.Fatal("openai-oauth must not resolve via models.dev")
	}
	if _, ok := r.Lookup(ctx, "openai-oauth", "gpt-5.6-sol"); ok {
		t.Fatal("openai-oauth gpt-5.6 must not resolve via models.dev")
	}
	// Dated snapshot resolves via suffix tolerance.
	limits, ok = r.Lookup(ctx, "anthropic-oauth", "claude-fable-5-20270101")
	if !ok || limits.ContextTokens != 1000000 {
		t.Fatalf("dated fable = %+v ok=%v, want 1M", limits, ok)
	}
	if _, ok := r.Lookup(ctx, "copilot", "totally-unknown-model"); ok {
		t.Fatal("unknown model must not resolve")
	}
}

func TestCompactionThresholdsDerivation(t *testing.T) {
	r, _ := testResolver(t)
	trigger, target, ok := r.CompactionThresholds(context.Background(), "copilot", "claude-fable-5")
	if !ok || trigger != 900000 || target != 500000 {
		t.Fatalf("fable thresholds = %d/%d ok=%v, want 900000/500000", trigger, target, ok)
	}
}

func TestCompactionResolverFuncUsesModelPrefixAsProvider(t *testing.T) {
	r, _ := testResolver(t)
	resolve := r.CompactionResolverFunc("copilot")

	// Unprefixed -> default provider (copilot -> github-copilot).
	trigger, _, ok := resolve(context.Background(), "gpt-5.3-codex")
	if !ok || trigger != 360000 {
		t.Fatalf("default provider codex trigger = %d ok=%v, want 360000", trigger, ok)
	}
	// Prefix overrides default provider; the openai-oauth codex backend is
	// uncataloged so the resolver reports no result for it.
	if _, _, ok := resolve(context.Background(), "openai-oauth/gpt-5.4"); ok {
		t.Fatal("openai-oauth prefix must not resolve via models.dev")
	}
	// A plain API-provider prefix resolves normally: openai gpt-5.4 is 1.05M.
	trigger, _, ok = resolve(context.Background(), "openai/gpt-5.4")
	if !ok || trigger != 945000 {
		t.Fatalf("openai gpt-5.4 trigger = %d ok=%v, want 945000", trigger, ok)
	}
	trigger, _, ok = resolve(context.Background(), "openai/gpt-5.6-sol")
	if !ok || trigger != 945000 {
		t.Fatalf("openai gpt-5.6 trigger = %d ok=%v, want 945000", trigger, ok)
	}
}

func TestCatalogCachedInMemoryAndOnDisk(t *testing.T) {
	r, hits := testResolver(t)
	ctx := context.Background()
	for i := 0; i < 5; i++ {
		if _, ok := r.Lookup(ctx, "copilot", "claude-fable-5"); !ok {
			t.Fatal("lookup failed")
		}
	}
	if got := hits.Load(); got != 1 {
		t.Fatalf("expected 1 catalog fetch, got %d", got)
	}

	// A fresh resolver pointed at a dead server must serve from disk cache.
	dead := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		http.Error(w, "down", http.StatusInternalServerError)
	}))
	t.Cleanup(dead.Close)
	r2 := NewResolver(WithURL(dead.URL), WithCachePath(r.cachePath), WithTTL(time.Nanosecond))
	if limits, ok := r2.Lookup(ctx, "copilot", "claude-fable-5"); !ok || limits.ContextTokens != 1000000 {
		t.Fatalf("disk-cache fallback = %+v ok=%v", limits, ok)
	}
}

func TestParseCatalogRejectsEmpty(t *testing.T) {
	if _, err := ParseCatalog([]byte(`{}`)); err == nil {
		t.Fatal("empty catalog must error")
	}
	if _, err := ParseCatalog([]byte(`not json`)); err == nil {
		t.Fatal("bad json must error")
	}
}

package otel

import (
	"context"
	"crypto/tls"
	"fmt"
	"log"
	"os"
	"regexp"
	"strings"
	"sync"
	"time"

	agent "github.com/gratefulagents/sdk/pkg/agentsdk"

	gootel "go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/codes"
	"go.opentelemetry.io/otel/exporters/otlp/otlptrace/otlptracegrpc"
	"go.opentelemetry.io/otel/exporters/stdout/stdouttrace"
	"go.opentelemetry.io/otel/sdk/resource"
	sdktrace "go.opentelemetry.io/otel/sdk/trace"
	semconv "go.opentelemetry.io/otel/semconv/v1.26.0"
	oteltrace "go.opentelemetry.io/otel/trace"
	"google.golang.org/grpc/credentials"
)

// OTelTracingProcessor bridges our TracingProcessor interface to the
// OpenTelemetry SDK. It maps Span/agent.SpanData to OTel spans with semantic
// attributes, exporting via any OTLP-compatible backend.
type OTelTracingProcessor struct {
	tracer   oteltrace.Tracer
	provider *sdktrace.TracerProvider

	mu              sync.Mutex
	spans           map[string]oteltrace.Span // our span ID -> OTel span
	ctxs            map[string]context.Context
	rootCtx         context.Context // ctx of the most recent root trace span
	traceID         string          // OTel trace ID (hex) of the root trace
	onTraceIDReady  func(string)
	traceIDNotified bool
}

// NewOTelTracingProcessor creates a processor that exports spans via OTLP
// gRPC to the endpoint in $OTEL_EXPORTER_OTLP_ENDPOINT, falling back to
// stdout pretty-print when the variable is unset (dev mode).
func NewOTelTracingProcessor(ctx context.Context, serviceName string) (*OTelTracingProcessor, error) {
	return NewOTelTracingProcessorWithEndpoint(ctx, serviceName, "")
}

// NewOTelTracingProcessorWithEndpoint creates a processor that exports spans
// to an explicit OTLP gRPC endpoint. The endpoint may be schemeless
// ("host:4317") or carry a scheme per the OTel spec ("http://host:4317");
// https selects TLS. When endpoint is empty it falls back to
// $OTEL_EXPORTER_OTLP_ENDPOINT, then to stdout pretty-print.
func NewOTelTracingProcessorWithEndpoint(ctx context.Context, serviceName, endpoint string) (*OTelTracingProcessor, error) {
	var exporter sdktrace.SpanExporter
	var err error

	if strings.TrimSpace(endpoint) == "" {
		endpoint = os.Getenv("OTEL_EXPORTER_OTLP_ENDPOINT")
	}
	hostPort, secure := normalizeOTLPEndpoint(endpoint)
	if hostPort != "" {
		opts := []otlptracegrpc.Option{otlptracegrpc.WithEndpoint(hostPort)}
		if secure {
			opts = append(opts, otlptracegrpc.WithTLSCredentials(credentials.NewTLS(&tls.Config{})))
		} else {
			opts = append(opts, otlptracegrpc.WithInsecure())
		}
		exporter, err = otlptracegrpc.New(ctx, opts...)
		if err != nil {
			return nil, fmt.Errorf("create OTLP exporter: %w", err)
		}
		log.Printf("OTel tracing: exporting to %s", hostPort)
	} else {
		exporter, err = stdouttrace.New(stdouttrace.WithPrettyPrint())
		if err != nil {
			return nil, fmt.Errorf("create stdout exporter: %w", err)
		}
		log.Printf("OTel tracing: exporting to stdout")
	}

	res := resource.NewWithAttributes(
		semconv.SchemaURL,
		semconv.ServiceNameKey.String(serviceName),
	)

	provider := sdktrace.NewTracerProvider(
		sdktrace.WithBatcher(exporter, sdktrace.WithBatchTimeout(5*time.Second)),
		sdktrace.WithResource(res),
	)
	gootel.SetTracerProvider(provider)

	tracer := provider.Tracer("gratefulagents/agent")

	return &OTelTracingProcessor{
		tracer:   tracer,
		provider: provider,
		spans:    make(map[string]oteltrace.Span),
		ctxs:     make(map[string]context.Context),
	}, nil
}

// normalizeOTLPEndpoint converts an OTLP endpoint value into the host:port
// form the gRPC exporter expects. Accepts schemeless "host:4317" as well as
// scheme'd "http://host:4317" / "https://host:4317" (per the OTel env spec);
// an https scheme selects TLS. Any URL path suffix is dropped.
func normalizeOTLPEndpoint(endpoint string) (hostPort string, secure bool) {
	e := strings.TrimSpace(endpoint)
	if e == "" {
		return "", false
	}
	if i := strings.Index(e, "://"); i >= 0 {
		secure = strings.EqualFold(e[:i], "https")
		e = e[i+3:]
	}
	if i := strings.IndexByte(e, '/'); i >= 0 {
		e = e[:i]
	}
	return e, secure
}

func (o *OTelTracingProcessor) OnTraceStart(trace *agent.Trace) {
	ctx, span := o.tracer.Start(context.Background(), trace.Name,
		oteltrace.WithAttributes(
			attribute.String("trace.id", trace.ID),
		),
	)
	o.mu.Lock()
	o.spans[trace.ID] = span
	o.ctxs[trace.ID] = ctx
	o.rootCtx = ctx
	o.traceID = span.SpanContext().TraceID().String()
	cb := o.onTraceIDReady
	shouldNotify := cb != nil && !o.traceIDNotified
	if shouldNotify {
		o.traceIDNotified = true
	}
	tid := o.traceID
	o.mu.Unlock()

	if shouldNotify {
		cb(tid)
	}
}

// TraceID returns the OTel trace ID (hex string) of the root trace.
// Returns empty string if no trace has been started.
func (o *OTelTracingProcessor) TraceID() string {
	o.mu.Lock()
	defer o.mu.Unlock()
	return o.traceID
}

// SetOnTraceIDReady registers a callback fired once when the first trace
// starts and the OTel trace ID becomes available. This allows writing the
// trace ID to external storage (e.g. CRD) early for live trace viewing.
func (o *OTelTracingProcessor) SetOnTraceIDReady(fn func(traceID string)) {
	o.mu.Lock()
	defer o.mu.Unlock()
	o.onTraceIDReady = fn
}

func (o *OTelTracingProcessor) OnTraceEnd(trace *agent.Trace) {
	o.mu.Lock()
	span, ok := o.spans[trace.ID]
	delete(o.spans, trace.ID)
	// Release every span context retained for parent lookups. rootCtx is kept
	// so any straggler span that starts after the trace ended still joins
	// this trace instead of minting a disconnected one.
	o.ctxs = make(map[string]context.Context)
	o.mu.Unlock()
	if ok {
		span.End()
	}
}

func (o *OTelTracingProcessor) OnSpanStart(s *agent.Span) {
	o.mu.Lock()
	parentCtx, ok := o.ctxs[s.ParentID]
	if !ok {
		// Unknown parent (e.g. a tracker span with no root wired, or a child
		// starting after its trace ended): attach to the most recent trace
		// root so the span stays in the run's waterfall instead of starting
		// a disconnected single-span trace.
		if o.rootCtx != nil {
			parentCtx = o.rootCtx
		} else {
			parentCtx = context.Background()
		}
	}
	o.mu.Unlock()

	spanName, attrs := mapSpanData(s)
	ctx, otelSpan := o.tracer.Start(parentCtx, spanName,
		oteltrace.WithAttributes(attrs...),
		oteltrace.WithAttributes(
			attribute.String("span.id", s.ID),
			attribute.String("span.parent_id", s.ParentID),
		),
	)

	o.mu.Lock()
	o.spans[s.ID] = otelSpan
	o.ctxs[s.ID] = ctx
	o.mu.Unlock()
}

func (o *OTelTracingProcessor) OnSpanEnd(s *agent.Span) {
	o.mu.Lock()
	otelSpan, ok := o.spans[s.ID]
	delete(o.spans, s.ID)
	// Keep o.ctxs[s.ID]: descendants may legitimately start after this span
	// ends (async subagents parented under their spawn tool call). Retained
	// contexts are released when the trace ends.
	o.mu.Unlock()
	if !ok {
		return
	}

	// Span data is typically mutated between start and end (final status,
	// tool output, usage, cost): re-apply the mapped attributes so the
	// exported span carries final values, then add the measured duration.
	_, attrs := mapSpanData(s)
	otelSpan.SetAttributes(attrs...)
	otelSpan.SetAttributes(attribute.Int64("duration_ms", s.DurationMS()))

	if errMsg, isErr := spanErrorStatus(s.Data); isErr {
		otelSpan.SetAttributes(attribute.Bool("error", true))
		otelSpan.SetStatus(codes.Error, truncate(errMsg, 256))
	}

	otelSpan.End()
}

// spanErrorStatus reports whether the span's final data represents a failure
// and returns a human-readable error message for the OTel span status.
func spanErrorStatus(data agent.SpanData) (string, bool) {
	switch d := data.(type) {
	case agent.FunctionSpanData:
		if d.IsError {
			return d.Output, true
		}
	case *agent.FunctionSpanData:
		if d != nil && d.IsError {
			return d.Output, true
		}
	case agent.SubagentSpanData:
		if d.Status == "failed" {
			return d.ResultText, true
		}
	case *agent.SubagentSpanData:
		if d != nil && d.Status == "failed" {
			return d.ResultText, true
		}
	default:
		if gen, ok := spanGenerationData(data); ok && !gen.Success && (gen.Error != "" || gen.Status == "failed") {
			return gen.Error, true
		}
	}
	return "", false
}

// Shutdown flushes pending spans and shuts down the provider.
func (o *OTelTracingProcessor) Shutdown(ctx context.Context) error {
	return o.provider.Shutdown(ctx)
}

func (o *OTelTracingProcessor) Flush() {
	if err := o.provider.ForceFlush(context.Background()); err != nil {
		log.Printf("OTel flush error: %v", err)
	}
}

// mapSpanData converts our agent.SpanData to an OTel span name and attributes.
func mapSpanData(s *agent.Span) (string, []attribute.KeyValue) {
	switch d := s.Data.(type) {
	case agent.AgentSpanData:
		return "agent." + d.AgentName, []attribute.KeyValue{
			attribute.String("agent.name", d.AgentName),
			attribute.String("agent.instructions", redactOTelText(truncate(d.Instructions, 500))),
		}
	case agent.GenerationSpanData:
		return "llm.generation", generationAttributes(d)
	case *agent.GenerationSpanData:
		if d == nil {
			return "llm.generation", nil
		}
		return "llm.generation", generationAttributes(*d)
	case agent.FunctionSpanData:
		return "tool." + d.ToolName, functionAttributes(d)
	case *agent.FunctionSpanData:
		if d == nil {
			return "tool", nil
		}
		return "tool." + d.ToolName, functionAttributes(*d)
	case agent.HandoffSpanData:
		return "handoff", handoffAttributes(d)
	case *agent.HandoffSpanData:
		if d == nil {
			return "handoff", nil
		}
		return "handoff", handoffAttributes(*d)
	case agent.GuardrailSpanData:
		return "guardrail." + d.GuardrailName, []attribute.KeyValue{
			attribute.String("guardrail.name", d.GuardrailName),
			attribute.Bool("guardrail.triggered", d.Triggered),
		}
	case agent.SessionSpanData:
		return "session", []attribute.KeyValue{
			attribute.String("session.model", d.Model),
			attribute.Float64("session.cost_usd", d.CostUSD),
			attribute.Int("session.num_turns", d.NumTurns),
			attribute.Int64("session.duration_ms", d.DurationMS),
			attribute.Int64("session.input_tokens", d.InputTokens),
			attribute.Int64("session.output_tokens", d.OutputTokens),
			attribute.Int64("session.cache_read_tokens", d.CacheReadInputTokens),
			attribute.Int64("session.cache_creation_tokens", d.CacheCreationInputTokens),
			attribute.String("session.stop_reason", d.StopReason),
		}
	case agent.SubagentSpanData:
		attrs := []attribute.KeyValue{
			attribute.String("subagent.task_id", d.TaskID),
			attribute.String("subagent.type", d.Type),
			attribute.String("subagent.description", truncate(d.Description, 200)),
			attribute.String("subagent.model", d.Model),
			attribute.String("subagent.status", d.Status),
			attribute.Float64("subagent.cost_usd", d.CostUSD),
			attribute.Int("subagent.num_turns", d.NumTurns),
			attribute.Int64("subagent.total_tokens", d.TotalTokens),
			attribute.Int64("subagent.input_tokens", d.InputTokens),
			attribute.Int64("subagent.output_tokens", d.OutputTokens),
			attribute.Int64("subagent.cache_read_tokens", d.CacheReadTokens),
			attribute.Int64("subagent.cache_creation_tokens", d.CacheCreateTokens),
			attribute.Int("subagent.tool_count", int(d.ToolCount)),
			attribute.Int64("subagent.duration_ms", d.DurationMS),
			attribute.String("subagent.stop_reason", d.StopReason),
		}
		if d.Isolation != "" {
			attrs = append(attrs, attribute.String("subagent.isolation", d.Isolation))
		}
		return "subagent." + d.Type, attrs
	case agent.RetrySpanData:
		return "api.retry", []attribute.KeyValue{
			attribute.String("retry.error_code", d.ErrorCode),
			attribute.Int64("retry.after_ms", d.RetryAfterMS),
			attribute.Int("retry.attempt", int(d.Attempt)),
			attribute.Int("retry.max_retries", int(d.MaxRetries)),
		}
	case agent.CompactionSpanData:
		return "compaction", []attribute.KeyValue{
			attribute.Int("compaction.tokens_before", d.TokensBefore),
			attribute.Int("compaction.tokens_after", d.TokensAfter),
		}
	default:
		return s.Name, nil
	}
}

func truncate(s string, maxLen int) string {
	if len(s) <= maxLen {
		return s
	}
	return s[:maxLen] + "..."
}

func functionAttributes(d agent.FunctionSpanData) []attribute.KeyValue {
	return []attribute.KeyValue{
		attribute.String("tool.name", d.ToolName),
		attribute.String("tool.input", redactOTelText(truncate(d.Input, 1000))),
		attribute.String("tool.output", redactOTelText(truncate(d.Output, 1000))),
		attribute.Bool("tool.error", d.IsError),
	}
}

func handoffAttributes(d agent.HandoffSpanData) []attribute.KeyValue {
	return []attribute.KeyValue{
		attribute.String("handoff.from", d.FromAgent),
		attribute.String("handoff.to", d.ToAgent),
	}
}

// otelSecretRedactors strips high-confidence credential material from
// free-text span attributes (instructions, tool input/output) before export,
// mirroring the redaction applied by the filesystem trace store.
var otelSecretRedactors = []*regexp.Regexp{
	regexp.MustCompile(`(?i)(bearer\s+)[A-Za-z0-9._\-]+`),
	regexp.MustCompile(`(?i)("(?:access_token|refresh_token|id_token|api_key|authorization|password|secret|token)"\s*:\s*")[^"]+(")`),
	regexp.MustCompile(`\bsk-[A-Za-z0-9_-]+`),
	regexp.MustCompile(`\bgh[pousr]_[A-Za-z0-9_]+\b`),
}

func redactOTelText(s string) string {
	for _, r := range otelSecretRedactors {
		if r.NumSubexp() == 2 {
			s = r.ReplaceAllString(s, "${1}[REDACTED]${2}")
		} else {
			s = r.ReplaceAllString(s, "[REDACTED]")
		}
	}
	return s
}

func spanGenerationData(data agent.SpanData) (agent.GenerationSpanData, bool) {
	switch d := data.(type) {
	case agent.GenerationSpanData:
		return d, true
	case *agent.GenerationSpanData:
		if d == nil {
			return agent.GenerationSpanData{}, false
		}
		return *d, true
	default:
		return agent.GenerationSpanData{}, false
	}
}

func generationAttributes(d agent.GenerationSpanData) []attribute.KeyValue {
	return []attribute.KeyValue{
		attribute.String("gen.requested_model", d.RequestedModel),
		attribute.String("gen.resolved_model", d.ResolvedModel),
		attribute.String("gen.model_provider", d.ModelProvider),
