	"github.com/gratefulagents/sdk/pkg/agentsdk"
)

func TestToolAccessLevelFromPermissionMode(t *testing.T) {
	tests := []struct {
		mode PermissionMode
		want agentsdk.ToolAccessLevel
	}{
		{PermissionModeReadOnly, agentsdk.ToolAccessLevelReadOnly},
		{PermissionModeWorkspaceWrite, agentsdk.ToolAccessLevelFull},
		{PermissionModeDangerFullAccess, agentsdk.ToolAccessLevelFull},
	}
	for _, tt := range tests {
		if got := ToolAccessLevelFromPermissionMode(tt.mode); got != tt.want {
			t.Fatalf("ToolAccessLevelFromPermissionMode(%q) = %q, want %q", tt.mode, got, tt.want)
		}
	}
}

func TestToolPolicyFromPermissionMode(t *testing.T) {
	if got := ToolPolicyFromPermissionMode(PermissionModeDangerFullAccess); got != nil {
		t.Fatalf("danger-full-access policy = %#v, want nil", got)
	}
	if got := ToolPolicyFromPermissionMode(PermissionModeWorkspaceWrite); got == nil || !got.ApprovalRequired {
		t.Fatalf("workspace-write policy = %#v, want approvals required", got)
	}
	if got := ToolPolicyFromPermissionMode(PermissionModeReadOnly); got == nil || !got.ApprovalRequired {
		t.Fatalf("read-only policy = %#v, want approvals required", got)
	}
}

// Package projectstate implements durable, event-sourced project state for
// agents: typed tasks, typed long-term memories, session summaries, and a
// prime-context builder. State is persisted under a state directory as an
// append-only event log (events.jsonl) with derived JSON indexes, so it
// survives process restarts and context compaction.
//
// # Memory model
//
// Memories are typed by Kind (pinned, semantic, episodic, procedural) and
// Scope (project, user, task, file). Store them with UpsertMemory, retrieve
// them with SearchMemories (query required) or ListMemories, and surface a
// compact session-start summary with PrimeContext.
//
// # Hybrid recall
//
// By default SearchMemories ranks memories with a lexical keyword score. When
// a FilesystemStore is configured with an Embedder, recall becomes hybrid: it
// fuses the normalized lexical score with cosine similarity over cached
// embeddings, plus a small pinned boost and recency decay (all tunable via
// HybridConfig). Candidates are filtered by kind and tags but not by keyword,
// so semantically relevant memories surface even when they share no exact
// terms with the query. With no Embedder, recall falls back to the lexical
// path unchanged, so embeddings are fully optional and backward compatible.
//
// Embeddings are computed on write and cached in indexes/embeddings.json,
// keyed by content hash and model so the cache self-invalidates when a
// memory's content or the embedding model changes. Memories written before an
// embedder was configured are backfilled lazily on the next recall. Embedding
// failures never block writes and degrade recall to whatever vectors already
// exist alongside the lexical signal.
//
// # Embedders
//
// OpenAIEmbedder implements Embedder against any OpenAI-compatible
// /v1/embeddings endpoint. Set OpenAIEmbedderOptions.BaseURL to choose the
// provider:
//
//   - OpenAI: "https://api.openai.com/v1" with "text-embedding-3-small".
//   - Local (Ollama): "http://localhost:11434/v1" with e.g. "bge-m3".
//
// OpenRouter currently exposes chat/completions but not a general-purpose
// /v1/embeddings endpoint, so it cannot back embeddings today; use OpenAI or a
// local model for vectors. If OpenRouter adds an embeddings route, point
// BaseURL at it with no code change. To use a different backend entirely,
// implement the Embedder interface.
package projectstate

package projectstate

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"net/http"
	"strings"
	"time"
)

// OpenAIEmbedderOptions configures an OpenAI-compatible embedding client.
//
// Any provider that implements the OpenAI /v1/embeddings contract works,
// including OpenAI itself, a local Ollama server (BaseURL
// "http://localhost:11434/v1"), and other OpenAI-compatible gateways. Point
// BaseURL at the provider you want and supply the matching model and key.
//
// Note on OpenRouter: OpenRouter focuses on chat/completions and does not
// currently expose a general-purpose /v1/embeddings endpoint. Use OpenAI or a
// local model (Ollama) for embeddings, and keep OpenRouter for completions. If
// OpenRouter adds an embeddings route, set BaseURL to it here with no code
// changes.
type OpenAIEmbedderOptions struct {
	// BaseURL is the API root, e.g. "https://api.openai.com/v1". A trailing
	// "/embeddings" is appended automatically. Defaults to the OpenAI API.
	BaseURL string
	// APIKey is sent as a Bearer token. Optional for local servers.
	APIKey string
	// ModelID is the embedding model, e.g. "text-embedding-3-small".
	ModelID string
	// Dimensions optionally requests a reduced embedding size when the model
	// supports it (e.g. OpenAI text-embedding-3-*).
	Dimensions int
	// BatchSize caps how many inputs are sent per request. Defaults to 96.
	BatchSize int
	// HTTPClient overrides the default client (30s timeout).
	HTTPClient *http.Client
	// Headers adds extra request headers (e.g. OpenRouter attribution).
	Headers map[string]string
}

// OpenAIEmbedder is an Embedder backed by an OpenAI-compatible embeddings API.
type OpenAIEmbedder struct {
	baseURL    string
	apiKey     string
	model      string
	dimensions int
	batchSize  int
	headers    map[string]string
	httpClient *http.Client
}

// NewOpenAIEmbedder builds an OpenAI-compatible embedder. It returns an error
// only when no model is provided; networking is validated lazily on first use.
func NewOpenAIEmbedder(opts OpenAIEmbedderOptions) (*OpenAIEmbedder, error) {
	model := strings.TrimSpace(opts.ModelID)
	if model == "" {
		return nil, fmt.Errorf("embedder model is required")
	}
	baseURL := strings.TrimRight(strings.TrimSpace(opts.BaseURL), "/")
	if baseURL == "" {
		baseURL = "https://api.openai.com/v1"
	}
	batch := opts.BatchSize
	if batch <= 0 {
		batch = 96
	}
	client := opts.HTTPClient
	if client == nil {
		client = &http.Client{Timeout: 30 * time.Second}
	}
	return &OpenAIEmbedder{
		baseURL:    baseURL,
		apiKey:     strings.TrimSpace(opts.APIKey),
		model:      model,
		dimensions: opts.Dimensions,
		batchSize:  batch,
		headers:    opts.Headers,
		httpClient: client,
	}, nil
}

// Model implements Embedder.
func (e *OpenAIEmbedder) Model() string { return e.model }

type embeddingsRequest struct {
	Model      string   `json:"model"`
	Input      []string `json:"input"`
	Dimensions int      `json:"dimensions,omitempty"`
}

type embeddingsResponse struct {
	Data []struct {
		Index     int       `json:"index"`
		Embedding []float32 `json:"embedding"`
	} `json:"data"`
	Error *struct {
		Message string `json:"message"`
	} `json:"error"`
}

// Embed implements Embedder, batching inputs to respect provider limits.
func (e *OpenAIEmbedder) Embed(ctx context.Context, texts []string) ([][]float32, error) {
	if len(texts) == 0 {
		return nil, nil
	}
	out := make([][]float32, len(texts))
	for start := 0; start < len(texts); start += e.batchSize {
		end := start + e.batchSize
		if end > len(texts) {
			end = len(texts)
		}
		vecs, err := e.embedBatch(ctx, texts[start:end])
		if err != nil {
			return nil, err
		}
		copy(out[start:end], vecs)
	}
	return out, nil
}

func (e *OpenAIEmbedder) embedBatch(ctx context.Context, batch []string) ([][]float32, error) {
	body, err := json.Marshal(embeddingsRequest{Model: e.model, Input: batch, Dimensions: e.dimensions})
	if err != nil {
		return nil, fmt.Errorf("marshal embeddings request: %w", err)
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, e.baseURL+"/embeddings", bytes.NewReader(body))
	if err != nil {
		return nil, fmt.Errorf("build embeddings request: %w", err)
	}
	req.Header.Set("Content-Type", "application/json")
	if e.apiKey != "" {
		req.Header.Set("Authorization", "Bearer "+e.apiKey)
	}
	for k, v := range e.headers {
		req.Header.Set(k, v)
	}
	resp, err := e.httpClient.Do(req)
	if err != nil {
		return nil, fmt.Errorf("embeddings request: %w", err)
	}
	defer resp.Body.Close()

	var parsed embeddingsResponse
	if err := json.NewDecoder(resp.Body).Decode(&parsed); err != nil {
		return nil, fmt.Errorf("decode embeddings response (status %d): %w", resp.StatusCode, err)
	}
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		if parsed.Error != nil && parsed.Error.Message != "" {
			return nil, fmt.Errorf("embeddings error (status %d): %s", resp.StatusCode, parsed.Error.Message)
		}
		return nil, fmt.Errorf("embeddings error: status %d", resp.StatusCode)
	}
	if len(parsed.Data) != len(batch) {
		return nil, fmt.Errorf("embeddings response count mismatch: got %d want %d", len(parsed.Data), len(batch))
	}
	vecs := make([][]float32, len(batch))
	for _, d := range parsed.Data {
		if d.Index < 0 || d.Index >= len(vecs) {
			return nil, fmt.Errorf("embeddings response index out of range: %d", d.Index)
		}
		vecs[d.Index] = d.Embedding
	}
	return vecs, nil
}

package projectstate

import (
	"context"
	"math"
	"sort"
	"strings"
	"time"
)

// Embedder turns text into dense vectors for semantic memory retrieval. It is
// optional: when a FilesystemStore has no embedder, memory recall falls back to
// the lexical keyword search and behaves exactly as before.
//
// Implementations should be safe for concurrent use and should embed the input
// slice as a batch, returning one vector per input in the same order.
type Embedder interface {
	// Embed returns one vector per input text, in input order.
	Embed(ctx context.Context, texts []string) ([][]float32, error)
	// Model identifies the embedding model. It is persisted alongside cached
	// vectors so the cache can be invalidated when the model changes.
	Model() string
}

// HybridConfig tunes how lexical and semantic signals are fused during recall.
// The zero value is not usable on its own; callers should start from
// DefaultHybridConfig and override individual fields.
type HybridConfig struct {
	// LexicalWeight weights the normalized lexical (keyword) score.
	LexicalWeight float64
	// DenseWeight weights the semantic (cosine similarity) score.
	DenseWeight float64
	// PinnedBoost is added to the score of pinned memories so durable facts
	// surface ahead of incidental matches of equal relevance.
	PinnedBoost float64
	// RecencyWeight weights an exponential recency score in [0,1].
	RecencyWeight float64
	// RecencyHalfLife is the age at which the recency score decays to 0.5.
	RecencyHalfLife time.Duration
	// MinScore drops candidates whose fused score is below this threshold.
	// Keep at 0 to preserve every filtered candidate.
	MinScore float64
}

// DefaultHybridConfig returns balanced defaults: semantic similarity leads,
// keyword overlap supports it, pinned memories get a small boost, and recency
// is a light tie-breaker with a 30 day half-life.
func DefaultHybridConfig() HybridConfig {
	return HybridConfig{
		LexicalWeight:   0.4,
		DenseWeight:     0.6,
		PinnedBoost:     0.15,
		RecencyWeight:   0.1,
		RecencyHalfLife: 30 * 24 * time.Hour,
		MinScore:        0,
	}
}

func (c HybridConfig) normalized() HybridConfig {
	if c.LexicalWeight == 0 && c.DenseWeight == 0 {
		c.LexicalWeight = DefaultHybridConfig().LexicalWeight
		c.DenseWeight = DefaultHybridConfig().DenseWeight
	}
	if c.RecencyHalfLife <= 0 {
		c.RecencyHalfLife = DefaultHybridConfig().RecencyHalfLife
	}
	return c
}

// scoredMemory pairs a memory with its fused relevance score.
type scoredMemory struct {
	memory Memory
	score  float64
}

// rankHybrid fuses lexical and semantic signals into a ranked memory list.
//
// queryVec may be nil (no embedder or embedding failure); in that case only the
// lexical signal contributes, so the function degrades gracefully to keyword
// ranking instead of failing the recall. vectors maps memory ID to its cached
// embedding; memories without a vector simply score 0 on the dense axis.
func rankHybrid(query string, candidates []Memory, queryVec []float32, vectors map[string][]float32, cfg HybridConfig, now time.Time) []Memory {
	cfg = cfg.normalized()
	terms := strings.Fields(strings.ToLower(strings.TrimSpace(query)))

	lexRaw := make([]float64, len(candidates))
	var maxLex float64
	for i, mem := range candidates {
		lexRaw[i] = lexicalScore(mem, terms)
		if lexRaw[i] > maxLex {
			maxLex = lexRaw[i]
		}
	}

	scored := make([]scoredMemory, 0, len(candidates))
	for i, mem := range candidates {
		var lexNorm float64
		if maxLex > 0 {
			lexNorm = lexRaw[i] / maxLex
		}
		var denseNorm float64
		if len(queryVec) > 0 {
			if vec, ok := vectors[mem.ID]; ok && len(vec) > 0 {
				denseNorm = math.Max(0, cosineSimilarity(queryVec, vec))
			}
		}
		// No relevance signal at all: pinned/recency boosts amplify relevance,
		// they must not manufacture it, or recall pads the limit with
		// query-irrelevant memories.
		if lexNorm == 0 && denseNorm == 0 {
			continue
		}
		score := cfg.LexicalWeight*lexNorm + cfg.DenseWeight*denseNorm
		if mem.Kind == MemoryKindPinned {
			score += cfg.PinnedBoost
		}
		if cfg.RecencyWeight > 0 {
			score += cfg.RecencyWeight * recencyScore(mem.UpdatedAt, now, cfg.RecencyHalfLife)
		}
		if score < cfg.MinScore {
			continue
		}
		scored = append(scored, scoredMemory{memory: cloneMemory(mem), score: score})
	}

	sort.SliceStable(scored, func(i, j int) bool {
		if scored[i].score != scored[j].score {
			return scored[i].score > scored[j].score
		}
		return scored[i].memory.UpdatedAt.After(scored[j].memory.UpdatedAt)
	})

	out := make([]Memory, len(scored))
	for i := range scored {
		out[i] = scored[i].memory
	}
	return out
}

// lexicalScore ranks a memory against query terms using term frequency plus a
// coverage bonus for matching distinct terms. It is deliberately simple and
// deterministic so hybrid ranking stays testable without a live embedder.
func lexicalScore(mem Memory, terms []string) float64 {
	if len(terms) == 0 {
		return 0
	}
	haystack := strings.ToLower(strings.Join(append([]string{mem.Content, mem.Kind, mem.Scope}, append(mem.Tags, append(mem.TaskIDs, mem.FilePaths...)...)...), " "))
	if haystack == "" {
		return 0
	}
	var tf float64
	var covered int
	for _, term := range terms {
		if term == "" {
			continue
		}
		if n := strings.Count(haystack, term); n > 0 {
			tf += float64(n)
			covered++
		}
	}
	if covered == 0 {
		return 0
	}
	// Coverage of distinct query terms is weighted more heavily than raw term
	// frequency so a memory matching every term outranks one that merely
	// repeats a single term.
	return tf + 2*float64(covered)
}

// recencyScore returns an exponential decay in (0,1]: 1 at age 0, 0.5 at one
// half-life, approaching 0 for old memories.
func recencyScore(updatedAt, now time.Time, halfLife time.Duration) float64 {
	if updatedAt.IsZero() || halfLife <= 0 {
		return 0
	}
	age := now.Sub(updatedAt)
	if age <= 0 {
		return 1
	}
	return math.Pow(0.5, float64(age)/float64(halfLife))
}

// cosineSimilarity returns the cosine of the angle between two vectors in
// [-1,1]. Mismatched or zero-length vectors yield 0.
func cosineSimilarity(a, b []float32) float64 {
	if len(a) == 0 || len(a) != len(b) {
		return 0
	}
	var dot, na, nb float64
	for i := range a {
		av, bv := float64(a[i]), float64(b[i])
		dot += av * bv
		na += av * av
		nb += bv * bv
	}
	if na == 0 || nb == 0 {
		return 0
	}
	return dot / (math.Sqrt(na) * math.Sqrt(nb))
}

package projectstate

import (
	"context"
	"errors"
	"math"
	"path/filepath"
	"testing"
	"time"
)

// fakeEmbedder maps known phrases to fixed vectors so hybrid ranking is
// deterministic without a live embedding provider. Unknown text gets a
// stable hashed vector that is dissimilar to the seeded ones.
type fakeEmbedder struct {
	model   string
	vectors map[string][]float32
	calls   int
}

func (f *fakeEmbedder) Model() string { return f.model }
func (f *fakeEmbedder) Embed(_ context.Context, texts []string) ([][]float32, error) {
	out := make([][]float32, len(texts))
	for i, t := range texts {
		f.calls++
		if v, ok := f.vectors[t]; ok {
			out[i] = v
			continue
		}
		// Deterministic fallback vector orthogonal-ish to the seeded ones.
		out[i] = []float32{0, 0, 1}
	}
	return out, nil
}

func TestCosineSimilarity(t *testing.T) {
	if got := cosineSimilarity([]float32{1, 0}, []float32{1, 0}); math.Abs(got-1) > 1e-9 {
		t.Fatalf("identical vectors cosine = %v, want 1", got)
	}
	if got := cosineSimilarity([]float32{1, 0}, []float32{0, 1}); math.Abs(got) > 1e-9 {
		t.Fatalf("orthogonal vectors cosine = %v, want 0", got)
	}
	if got := cosineSimilarity([]float32{1, 0}, nil); got != 0 {
		t.Fatalf("mismatched length cosine = %v, want 0", got)
	}
}

func TestRecencyScore(t *testing.T) {
	now := time.Now()
	if got := recencyScore(now, now, time.Hour); math.Abs(got-1) > 1e-9 {
		t.Fatalf("age 0 recency = %v, want 1", got)
	}
	if got := recencyScore(now.Add(-time.Hour), now, time.Hour); math.Abs(got-0.5) > 1e-9 {
		t.Fatalf("one half-life recency = %v, want 0.5", got)
	}
}

// TestHybridSemanticRecall verifies that a query with no lexical overlap still
// retrieves the semantically nearest memory, which pure keyword search misses.
func TestHybridSemanticRecall(t *testing.T) {
	ctx := context.Background()
	emb := &fakeEmbedder{
		model: "fake-1",
		vectors: map[string][]float32{
			"The user prefers the vim editor.":    {1, 0, 0},
			"Deploys run every Friday afternoon.": {0, 1, 0},
			"What is my favorite text editor?":    {0.95, 0.1, 0},
		},
	}
	store, err := NewFilesystemStore(FilesystemOptions{
		StateDir: filepath.Join(t.TempDir(), "state"),
		Actor:    "tester",
		Embedder: emb,
	})
	if err != nil {
		t.Fatal(err)
	}
	if _, err := store.UpsertMemory(ctx, UpsertMemoryInput{Kind: MemoryKindSemantic, Content: "The user prefers the vim editor."}); err != nil {
		t.Fatal(err)
	}
	if _, err := store.UpsertMemory(ctx, UpsertMemoryInput{Kind: MemoryKindSemantic, Content: "Deploys run every Friday afternoon."}); err != nil {
		t.Fatal(err)
	}

	got, err := store.SearchMemories(ctx, MemoryFilter{Query: "What is my favorite text editor?"})
	if err != nil {
		t.Fatal(err)
	}
	if len(got) == 0 {
		t.Fatal("hybrid recall returned no memories")
	}
	if got[0].Content != "The user prefers the vim editor." {
		t.Fatalf("top hybrid result = %q, want the editor memory", got[0].Content)
	}
}

// TestHybridCachesEmbeddings verifies vectors are cached on write and reused on
// recall instead of being recomputed for every memory each search.
func TestHybridCachesEmbeddings(t *testing.T) {
	ctx := context.Background()
	emb := &fakeEmbedder{model: "fake-1", vectors: map[string][]float32{
		"alpha fact": {1, 0, 0},
		"beta fact":  {0, 1, 0},
	}}
	dir := filepath.Join(t.TempDir(), "state")
	store, err := NewFilesystemStore(FilesystemOptions{StateDir: dir, Embedder: emb})
	if err != nil {
		t.Fatal(err)
	}
	if _, err := store.UpsertMemory(ctx, UpsertMemoryInput{Content: "alpha fact"}); err != nil {
		t.Fatal(err)
	}
	if _, err := store.UpsertMemory(ctx, UpsertMemoryInput{Content: "beta fact"}); err != nil {
		t.Fatal(err)
	}
	callsAfterWrite := emb.calls

	if _, err := store.SearchMemories(ctx, MemoryFilter{Query: "alpha fact"}); err != nil {
		t.Fatal(err)
	}
	// The two stored memories were already embedded on write, so recall should
	// only embed the query (one additional call), not re-embed the corpus.
	if delta := emb.calls - callsAfterWrite; delta != 1 {
		t.Fatalf("recall embed calls = %d, want 1 (query only)", delta)
	}
}

// TestLexicalFallbackWithoutEmbedder ensures behavior is unchanged when no
// embedder is configured.
func TestLexicalFallbackWithoutEmbedder(t *testing.T) {
	ctx := context.Background()
	store, err := NewFilesystemStore(FilesystemOptions{StateDir: filepath.Join(t.TempDir(), "state")})
	if err != nil {
		t.Fatal(err)
	}
	if _, err := store.UpsertMemory(ctx, UpsertMemoryInput{Content: "Run focused tests after storage changes."}); err != nil {
		t.Fatal(err)
	}
	if _, err := store.UpsertMemory(ctx, UpsertMemoryInput{Content: "Use append-only project state."}); err != nil {
		t.Fatal(err)
	}
	got, err := store.SearchMemories(ctx, MemoryFilter{Query: "focused"})
	if err != nil {
		t.Fatal(err)
	}
	if len(got) != 1 || got[0].Content != "Run focused tests after storage changes." {
		t.Fatalf("lexical fallback = %+v", got)
	}
	if _, err := store.SearchMemories(ctx, MemoryFilter{Query: ""}); err == nil {
		t.Fatal("empty query should error")
	}
}

// errEmbedder always fails, simulating an unavailable or timed-out provider.
type errEmbedder struct{}

func (errEmbedder) Model() string { return "err-1" }
func (errEmbedder) Embed(context.Context, []string) ([][]float32, error) {
	return nil, errors.New("embedding provider unavailable")
}

// TestQueryEmbeddingFailureFallsBackToLexical verifies that when the query
// embedding cannot be computed, recall falls back to query-relevant lexical
// search instead of returning every memory ranked by recency/pinned boosts.
func TestQueryEmbeddingFailureFallsBackToLexical(t *testing.T) {
	ctx := context.Background()
	store, err := NewFilesystemStore(FilesystemOptions{
		StateDir: filepath.Join(t.TempDir(), "state"),
		Embedder: errEmbedder{},
	})
	if err != nil {
		t.Fatal(err)
	}
	if _, err := store.UpsertMemory(ctx, UpsertMemoryInput{Content: "Run focused tests after storage changes."}); err != nil {
		t.Fatal(err)
	}
	if _, err := store.UpsertMemory(ctx, UpsertMemoryInput{Content: "Use append-only project state."}); err != nil {
		t.Fatal(err)
	}
	got, err := store.SearchMemories(ctx, MemoryFilter{Query: "focused"})
	if err != nil {
		t.Fatal(err)
	}
	if len(got) != 1 || got[0].Content != "Run focused tests after storage changes." {
		t.Fatalf("query-embedding-failure fallback = %+v, want only the lexically matching memory", got)
	}
}

package projectstate

import (
	"crypto/sha256"
	"encoding/hex"
	"time"
)

const embeddingsFileName = "embeddings.json"

// embeddingRecord is a cached vector for one memory. Hash and Model let the
// cache invalidate itself when the memory content or the embedding model
// changes, so vectors never silently go stale.
type embeddingRecord struct {
	Hash   string    `json:"hash"`
	Model  string    `json:"model"`
	Dims   int       `json:"dims"`
	Vector []float32 `json:"vector"`
}

type embeddingCache struct {
	SchemaVersion int                        `json:"schema_version"`
	Model         string                     `json:"model"`
	UpdatedAt     time.Time                  `json:"updated_at"`
	Vectors       map[string]embeddingRecord `json:"vectors"`
}

func hashContent(content string) string {
	sum := sha256.Sum256([]byte(content))
	return hex.EncodeToString(sum[:])
}

func (r embeddingRecord) fresh(content, model string) bool {
	return len(r.Vector) > 0 && r.Model == model && r.Hash == hashContent(content)
}

package projectstate

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"sort"
	"strings"
	"sync"
	"time"
)

// embedWriteTimeout bounds the best-effort embedding call on the memory write
// path so an unreachable provider cannot stall UpsertMemory for the embedder's
// full HTTP timeout.
const embedWriteTimeout = 5 * time.Second

// backend abstracts durable persistence for the projectstate engine. The engine
// keeps all storage-agnostic logic (event sourcing, task/memory/session
// semantics, hybrid recall, priming) and delegates only the read/write of the
// durable event log, derived snapshots, and the embedding cache to a backend.
//
// Two backends are provided: a filesystem backend (append-only events.jsonl plus
// JSON index snapshots) and a SQLite backend (events table; snapshots are a
// no-op because state is always rebuilt from the events table).
type backend interface {
	// loadEvents returns every durable event in ascending seq order. The engine
	// rebuilds the in-memory state by replaying these through applyEvent.
	loadEvents() ([]Event, error)
	// appendEvent durably persists one already seq-assigned event.
	appendEvent(ev Event) error
	// snapshot optionally writes derived index snapshots. May be a no-op.
	snapshot(st *state) error
	// lock serializes access (cross-process where supported) and returns a
	// release function.
	lock(ctx context.Context) (func(), error)
	// readEmbeddings loads the cached vectors keyed by memory id.
	readEmbeddings() (map[string]embeddingRecord, error)
	// upsertEmbeddings merges the given records into the durable vector cache
	// without clobbering records written concurrently by other callers.
	upsertEmbeddings(records map[string]embeddingRecord, model string) error
	// deleteEmbeddings removes cached vectors for the given memory ids.
	deleteEmbeddings(ids []string) error
	// close releases backend resources.
	close() error
}

// engine holds all storage-agnostic projectstate logic shared by every backend.
type engine struct {
	mu        sync.Mutex
	projectID string
	workDir   string
	actor     string
	runID     string
	stateDir  string
	embedder  Embedder
	hybrid    HybridConfig
	backend   backend
}

type state struct {
	project  Project
	tasks    map[string]Task
	memories map[string]Memory
	sessions map[string]SessionSummary
	lastSeq  int64
}

// initialize records the project.initialized event on first use and writes the
// initial snapshot. It is idempotent across opens.
func (s *engine) initialize(ctx context.Context) error {
	return s.withLockedState(ctx, func(st *state) error {
		now := time.Now().UTC()
		if st.project.ProjectID == "" {
			st.project = Project{
				SchemaVersion: SchemaVersion,
				ProjectID:     s.projectID,
				WorkDir:       s.workDir,
				StateDir:      s.stateDir,
				CreatedAt:     now,
				UpdatedAt:     now,
			}
		}
		if st.lastSeq == 0 {
			st.project.UpdatedAt = now
			if err := s.appendEventLocked(st, "project.initialized", st.project, now); err != nil {
				return err
			}
		}
		return s.snapshotLocked(st)
	})
}

func (s *engine) Close() error { return s.backend.close() }

func (s *engine) ProjectID() string { return s.projectID }

func (s *engine) CreateTask(ctx context.Context, in CreateTaskInput) (*Task, error) {
	var out *Task
	err := s.mutate(ctx, "task.created", func(st *state, now time.Time) (any, error) {
		title := strings.TrimSpace(in.Title)
		if title == "" {
			return nil, fmt.Errorf("title is required")
		}
		task := Task{
			ID:          newID("task"),
			Title:       title,
			Description: strings.TrimSpace(in.Description),
			Type:        normalizeTaskType(in.Type),
			Status:      TaskStatusOpen,
			Priority:    normalizePriority(in.Priority),
			Assignee:    strings.TrimSpace(in.Assignee),
			DependsOn:   uniqueNonEmpty(in.DependsOn),
			Labels:      uniqueNonEmpty(in.Labels),
			CreatedAt:   now,
			UpdatedAt:   now,
			SourceRun:   firstNonEmpty(in.SourceRun, s.runID),
			Metadata:    cloneRaw(in.Metadata),
		}
		st.tasks[task.ID] = task
		recomputeBlocks(st)
		out = cloneTaskPtr(task)
		return task, nil
	})
	return out, err
}

func (s *engine) UpdateTask(ctx context.Context, id string, patch TaskPatch) (*Task, error) {
	var out *Task
	err := s.mutate(ctx, "task.updated", func(st *state, now time.Time) (any, error) {
		task, ok := st.tasks[strings.TrimSpace(id)]
		if !ok {
			return nil, fmt.Errorf("task %q not found", id)
		}
		applyPatch(&task, patch, now)
		st.tasks[task.ID] = task
		recomputeBlocks(st)
		out = cloneTaskPtr(task)
		return taskUpdatePayload{ID: task.ID, Patch: patch, Task: task}, nil
	})
	return out, err
}

func (s *engine) ClaimTask(ctx context.Context, id, actor string) (*Task, error) {
	var out *Task
	err := s.mutate(ctx, "task.claimed", func(st *state, now time.Time) (any, error) {
		task, ok := st.tasks[strings.TrimSpace(id)]
		if !ok {
			return nil, fmt.Errorf("task %q not found", id)
		}
		claimant := firstNonEmpty(actor, s.actor)
		if claimant == "" {
			claimant = "agent"
		}
		task.Assignee = claimant
		task.Status = TaskStatusInProgress
		task.UpdatedAt = now
		task.ClosedAt = nil
		st.tasks[task.ID] = task
		recomputeBlocks(st)
		out = cloneTaskPtr(task)
		return taskClaimedPayload{ID: task.ID, Actor: claimant, At: now}, nil
	})
	return out, err
}

func (s *engine) CloseTask(ctx context.Context, id, reason string) (*Task, error) {
	var out *Task
	err := s.mutate(ctx, "task.closed", func(st *state, now time.Time) (any, error) {
		task, ok := st.tasks[strings.TrimSpace(id)]
		if !ok {
			return nil, fmt.Errorf("task %q not found", id)
		}
		task.Status = TaskStatusClosed
		task.UpdatedAt = now
		task.ClosedAt = &now
		if strings.TrimSpace(reason) != "" {
			task.Comments = append(task.Comments, TaskComment{
				ID:        newID("comment"),
				Actor:     s.actor,
				Body:      "Closed: " + strings.TrimSpace(reason),
				CreatedAt: now,
			})
		}
		st.tasks[task.ID] = task
		recomputeBlocks(st)
		out = cloneTaskPtr(task)
		return taskClosedPayload{ID: task.ID, Reason: strings.TrimSpace(reason), At: now, Task: task}, nil
	})
	return out, err
}

func (s *engine) ReadyTasks(ctx context.Context, filter TaskFilter) ([]Task, error) {
	st, err := s.loadState(ctx)
	if err != nil {
		return nil, err
	}
	tasks := make([]Task, 0, len(st.tasks))
	for _, task := range st.tasks {
		if task.Status != TaskStatusOpen {
			continue
		}
		if !matchesLabels(task.Labels, filter.Labels) {
			continue
		}
		actor := firstNonEmpty(filter.Actor, filter.Assignee)
		if filter.Assignee != "" && task.Assignee != "" && task.Assignee != filter.Assignee {
			continue
		}
		if !filter.IncludeAssigned && task.Assignee != "" && task.Assignee != actor {
			continue
		}
		if hasOpenBlocker(st, task) {
			continue
		}
		tasks = append(tasks, cloneTask(task))
	}
	sortTasks(tasks)
	return limitTasks(tasks, filter.Limit), nil
}

func (s *engine) ListTasks(ctx context.Context) ([]Task, error) {
	st, err := s.loadState(ctx)
	if err != nil {
		return nil, err
	}
	tasks := make([]Task, 0, len(st.tasks))
	for _, task := range st.tasks {
		tasks = append(tasks, cloneTask(task))
	}
	sortTasks(tasks)
	return tasks, nil
}

func (s *engine) GetTask(ctx context.Context, id string) (*Task, error) {
	st, err := s.loadState(ctx)
	if err != nil {
		return nil, err
	}
	task, ok := st.tasks[strings.TrimSpace(id)]
	if !ok {
		return nil, fmt.Errorf("task %q not found", id)
	}
	return cloneTaskPtr(task), nil
}

func (s *engine) AddDependency(ctx context.Context, taskID, dependsOnID string) error {
	return s.mutate(ctx, "task.dependency_added", func(st *state, now time.Time) (any, error) {
		taskID = strings.TrimSpace(taskID)
		dependsOnID = strings.TrimSpace(dependsOnID)
		task, ok := st.tasks[taskID]
		if !ok {
			return nil, fmt.Errorf("task %q not found", taskID)
		}
		if _, ok := st.tasks[dependsOnID]; !ok {
			return nil, fmt.Errorf("dependency task %q not found", dependsOnID)
		}
		if taskID == dependsOnID {
			return nil, fmt.Errorf("task cannot depend on itself")
		}
		task.DependsOn = appendUnique(task.DependsOn, dependsOnID)
		task.UpdatedAt = now
		st.tasks[task.ID] = task
		recomputeBlocks(st)
		return dependencyPayload{ID: taskID, DependsOn: dependsOnID, At: now}, nil
	})
}

func (s *engine) RemoveDependency(ctx context.Context, taskID, dependsOnID string) error {
	return s.mutate(ctx, "task.dependency_removed", func(st *state, now time.Time) (any, error) {
		taskID = strings.TrimSpace(taskID)
		dependsOnID = strings.TrimSpace(dependsOnID)
		task, ok := st.tasks[taskID]
		if !ok {
			return nil, fmt.Errorf("task %q not found", taskID)
		}
		task.DependsOn = removeString(task.DependsOn, dependsOnID)
		task.UpdatedAt = now
		st.tasks[task.ID] = task
		recomputeBlocks(st)
		return dependencyPayload{ID: taskID, DependsOn: dependsOnID, At: now}, nil
	})
}

func (s *engine) AddComment(ctx context.Context, taskID, actor, body string) (*TaskComment, error) {
	var out *TaskComment
	err := s.mutate(ctx, "task.comment_added", func(st *state, now time.Time) (any, error) {
		taskID = strings.TrimSpace(taskID)
		task, ok := st.tasks[taskID]
		if !ok {
			return nil, fmt.Errorf("task %q not found", taskID)
		}
		body = strings.TrimSpace(body)
		if body == "" {
			return nil, fmt.Errorf("comment body is required")
		}
		comment := TaskComment{ID: newID("comment"), Actor: firstNonEmpty(actor, s.actor), Body: body, CreatedAt: now}
		task.Comments = append(task.Comments, comment)
		task.UpdatedAt = now
		st.tasks[task.ID] = task
		out = &comment
		return taskCommentPayload{ID: taskID, Comment: comment}, nil
	})
	return out, err
}

func (s *engine) UpsertMemory(ctx context.Context, in UpsertMemoryInput) (*Memory, error) {
	var out *Memory
	err := s.mutate(ctx, "memory.upserted", func(st *state, now time.Time) (any, error) {
		content := strings.TrimSpace(in.Content)
		if content == "" {
			return nil, fmt.Errorf("memory content is required")
		}
		id := strings.TrimSpace(in.ID)
		createdAt := now
		if existing, ok := st.memories[id]; ok {
			createdAt = existing.CreatedAt
		}
		if id == "" {
			id = newID("mem")
		}
		mem := Memory{
			ID:        id,
			Kind:      normalizeMemoryKind(in.Kind),
			Scope:     normalizeMemoryScope(in.Scope),
			Content:   content,
			Tags:      uniqueNonEmpty(in.Tags),
			TaskIDs:   uniqueNonEmpty(in.TaskIDs),
			FilePaths: uniqueNonEmpty(in.FilePaths),
			SourceRun: firstNonEmpty(in.SourceRun, s.runID),
			CreatedAt: createdAt,
			UpdatedAt: now,
			Metadata:  cloneRaw(in.Metadata),
		}
		st.memories[mem.ID] = mem
		out = cloneMemoryPtr(mem)
		return mem, nil
	})
	if err != nil {
		return nil, err
	}
	if out != nil {
		// Best-effort: caching the embedding must never fail the write. A
		// missing vector is backfilled lazily on the next recall. Bound the
		// embedding call so a dead provider cannot stall the write path for
		// the full HTTP client timeout.
		embedCtx, cancel := context.WithTimeout(ctx, embedWriteTimeout)
		if err := s.cacheMemoryEmbedding(embedCtx, out.ID, out.Content); err != nil {
			log.Printf("projectstate: caching embedding for memory %s failed (will backfill on recall): %v", out.ID, err)
		}
		cancel()
	}
	return out, err
}

func (s *engine) SearchMemories(ctx context.Context, filter MemoryFilter) ([]Memory, error) {
	if strings.TrimSpace(filter.Query) == "" {
		return nil, fmt.Errorf("query is required")
	}
	if s.embedder == nil {
		return s.listMemories(ctx, filter, true)
	}
	return s.searchHybrid(ctx, filter)
}

// searchHybrid ranks memories by fusing the lexical keyword signal with cosine
// similarity over cached embeddings. Candidates are filtered by kind and tags
// but not by keyword, so semantically relevant memories surface even when they
// share no exact terms with the query.
func (s *engine) searchHybrid(ctx context.Context, filter MemoryFilter) ([]Memory, error) {
	// Embed the query first. If the embedding provider is unavailable or times
	// out we have no semantic signal, so fall back to the lexical search rather
	// than ranking every kind/tag match by recency and pinned boosts (which
	// would return query-irrelevant memories).
	vecs, embErr := s.embedder.Embed(ctx, []string{filter.Query})
	if embErr != nil || len(vecs) != 1 || len(vecs[0]) == 0 {
		return s.listMemories(ctx, filter, true)
	}
	queryVec := vecs[0]

	st, err := s.loadState(ctx)
	if err != nil {
		return nil, err
	}
	var candidates []Memory
	for _, mem := range st.memories {
		if !matchesAny(mem.Kind, filter.Kinds) || !matchesLabels(mem.Tags, filter.Tags) {
			continue
		}
		candidates = append(candidates, mem)
	}
	if len(candidates) == 0 {
		return nil, nil
	}
	vectors := s.ensureEmbeddings(ctx, candidates)
	ranked := rankHybrid(filter.Query, candidates, queryVec, vectors, s.hybrid, time.Now().UTC())
	if filter.Limit > 0 && len(ranked) > filter.Limit {
		ranked = ranked[:filter.Limit]
	}
	return ranked, nil
}

func (s *engine) ListMemories(ctx context.Context, filter MemoryFilter) ([]Memory, error) {
	return s.listMemories(ctx, filter, false)
}

func (s *engine) DeleteMemory(ctx context.Context, id string) error {
	id = strings.TrimSpace(id)
	err := s.mutate(ctx, "memory.deleted", func(st *state, now time.Time) (any, error) {
		if _, ok := st.memories[id]; !ok {
			return nil, fmt.Errorf("memory %q not found", id)
		}
		delete(st.memories, id)
		return memoryDeletedPayload{ID: id, At: now}, nil
	})
	if err != nil {
		return err
	}
	// Best-effort cache prune; a leftover orphan vector only wastes space.
	_ = s.backend.deleteEmbeddings([]string{id})
	return nil
}

func (s *engine) SaveSessionSummary(ctx context.Context, summary SessionSummary) (*SessionSummary, error) {
	var out *SessionSummary
	err := s.mutate(ctx, "session.summary_saved", func(st *state, now time.Time) (any, error) {
		if strings.TrimSpace(summary.Summary) == "" {
			return nil, fmt.Errorf("session summary is required")
		}
		if strings.TrimSpace(summary.ID) == "" {
			summary.ID = newID("session")
			summary.CreatedAt = now
		}
		if existing, ok := st.sessions[summary.ID]; ok && !existing.CreatedAt.IsZero() {
			summary.CreatedAt = existing.CreatedAt
		}
		summary.RunID = firstNonEmpty(summary.RunID, s.runID)
		summary.UpdatedAt = now
		summary.TaskIDs = uniqueNonEmpty(summary.TaskIDs)
		st.sessions[summary.ID] = summary
		cp := cloneSession(summary)
		out = &cp
		return summary, nil
	})
	return out, err
}

func (s *engine) ListSessionSummaries(ctx context.Context, limit int) ([]SessionSummary, error) {
	st, err := s.loadState(ctx)
	if err != nil {
		return nil, err
	}
	out := make([]SessionSummary, 0, len(st.sessions))
	for _, session := range st.sessions {
		out = append(out, cloneSession(session))
	}
	sort.SliceStable(out, func(i, j int) bool { return out[i].UpdatedAt.After(out[j].UpdatedAt) })
	if limit > 0 && len(out) > limit {
		out = out[:limit]
	}
	return out, nil
}

func (s *engine) listMemories(ctx context.Context, filter MemoryFilter, requireQuery bool) ([]Memory, error) {
	st, err := s.loadState(ctx)
	if err != nil {
		return nil, err
	}
	query := strings.ToLower(strings.TrimSpace(filter.Query))
	if requireQuery && query == "" {
		return nil, fmt.Errorf("query is required")
	}
	var out []Memory
	for _, mem := range st.memories {
		if !matchesAny(mem.Kind, filter.Kinds) || !matchesLabels(mem.Tags, filter.Tags) {
			continue
		}
		if query != "" && !memoryMatchesQuery(mem, query) {
			continue
		}
		out = append(out, cloneMemory(mem))
	}
	sort.SliceStable(out, func(i, j int) bool {
		if out[i].Kind == MemoryKindPinned && out[j].Kind != MemoryKindPinned {
			return true
		}
		if out[i].Kind != MemoryKindPinned && out[j].Kind == MemoryKindPinned {
			return false
		}
		return out[i].UpdatedAt.After(out[j].UpdatedAt)
	})
	if filter.Limit > 0 && len(out) > filter.Limit {
		out = out[:filter.Limit]
	}
	return out, nil
}

func (s *engine) mutate(ctx context.Context, eventType string, fn func(*state, time.Time) (any, error)) error {
	return s.withLockedState(ctx, func(st *state) error {
		now := time.Now().UTC()
		payload, err := fn(st, now)
		if err != nil {
			return err
		}
		st.project.UpdatedAt = now
		if err := s.appendEventLocked(st, eventType, payload, now); err != nil {
			return err
		}
		return s.snapshotLocked(st)
	})
}

func (s *engine) loadState(ctx context.Context) (*state, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	release, err := s.backend.lock(ctx)
	if err != nil {
		return nil, err
	}
	defer release()
	return s.loadStateLocked()
}

func (s *engine) withLockedState(ctx context.Context, fn func(*state) error) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	release, err := s.backend.lock(ctx)
	if err != nil {
		return err
	}
	defer release()
	st, err := s.loadStateLocked()
	if err != nil {
		return err
	}
	if st.project.ProjectID == "" {
		now := time.Now().UTC()
		st.project = Project{SchemaVersion: SchemaVersion, ProjectID: s.projectID, WorkDir: s.workDir, StateDir: s.stateDir, CreatedAt: now, UpdatedAt: now}
	}
	return fn(st)
}

func (s *engine) loadStateLocked() (*state, error) {
	st := &state{
		tasks:    make(map[string]Task),
		memories: make(map[string]Memory),
		sessions: make(map[string]SessionSummary),
	}
	events, err := s.backend.loadEvents()
	if err != nil {
		return nil, err
	}
	for _, ev := range events {
		if ev.Seq > st.lastSeq {
			st.lastSeq = ev.Seq
		}
		if err := applyEvent(st, ev); err != nil {
			return nil, fmt.Errorf("apply event %d %s: %w", ev.Seq, ev.Type, err)
		}
	}
	recomputeBlocks(st)
	return st, nil
}

func (s *engine) appendEventLocked(st *state, eventType string, payload any, now time.Time) error {
	raw, err := json.Marshal(payload)
	if err != nil {
		return fmt.Errorf("marshal event payload: %w", err)
	}
	ev := Event{
		Seq:       st.lastSeq + 1,
		EventID:   newID("evt"),
		ProjectID: s.projectID,
		RunID:     s.runID,
		Actor:     s.actor,
		Time:      now,
		Type:      eventType,
		Payload:   raw,
	}
	if err := s.backend.appendEvent(ev); err != nil {
		return err
	}
	st.lastSeq = ev.Seq
	return nil
}

// snapshotLocked normalizes the project record and asks the backend to persist
// any derived snapshots.
func (s *engine) snapshotLocked(st *state) error {
	now := time.Now().UTC()
	st.project.SchemaVersion = SchemaVersion
	st.project.ProjectID = firstNonEmpty(st.project.ProjectID, s.projectID)
	st.project.WorkDir = firstNonEmpty(st.project.WorkDir, s.workDir)
	st.project.StateDir = s.stateDir
	if st.project.CreatedAt.IsZero() {
		st.project.CreatedAt = now
	}
	if st.project.UpdatedAt.IsZero() {
		st.project.UpdatedAt = now
	}
	return s.backend.snapshot(st)
}

// PrimeContext renders the durable project state into a compact briefing block.
func (s *engine) PrimeContext(ctx context.Context, opts PrimeOptions) (string, error) {
	st, err := s.loadState(ctx)
	if err != nil {
		return "", err
	}
	opts.Actor = firstNonEmpty(opts.Actor, s.actor)
	if opts.ReadyLimit <= 0 {
		opts.ReadyLimit = 8
	}
	if opts.MemoryLimit <= 0 {
		opts.MemoryLimit = 8
	}

	var b strings.Builder
	b.WriteString("## Durable Project State\n")
	if st.project.ProjectID != "" {
		b.WriteString("Project: " + st.project.ProjectID + "\n")
	}
	if st.project.WorkDir != "" {
		b.WriteString("Workspace: " + st.project.WorkDir + "\n")
	}

	active := activeTask(st, opts)
	if active != nil {
		b.WriteString("\n### Active Task\n")
		writeTaskLine(&b, *active)
		if active.Description != "" {
			b.WriteString("  " + oneLine(active.Description, 220) + "\n")
		}
		if len(active.DependsOn) > 0 {
			b.WriteString("  Depends on: " + strings.Join(active.DependsOn, ", ") + "\n")
		}
	}

	ready := readyFromState(st, TaskFilter{Actor: opts.Actor, Limit: opts.ReadyLimit})
	if len(ready) > 0 {
		b.WriteString("\n### Ready Work\n")
		for _, task := range ready {
			writeTaskLine(&b, task)
		}
	}

	blocked := blockedTasks(st, 5)
	if len(blocked) > 0 {
		b.WriteString("\n### Blocked Work\n")
		for _, task := range blocked {
			writeTaskLine(&b, task)
		}
	}

	pinned, recent := memoriesForPrime(st, opts.MemoryLimit)
	if len(pinned) > 0 {
		b.WriteString("\n### Pinned Memories\n")
		for _, mem := range pinned {
			b.WriteString("- " + oneLine(mem.Content, 220) + memorySuffix(mem) + "\n")
		}
	}
	if len(recent) > 0 {
		b.WriteString("\n### Recent Memories\n")
		for _, mem := range recent {
			b.WriteString("- " + oneLine(mem.Content, 180) + memorySuffix(mem) + "\n")
		}
	}

	out := strings.TrimSpace(b.String())
	if out == "## Durable Project State" {
		out += "\nNo durable tasks or memories yet."
	}
	return out, nil
}

func applyEvent(st *state, ev Event) error {
	switch ev.Type {
	case "project.initialized":
		var project Project
		if err := json.Unmarshal(ev.Payload, &project); err != nil {
			return err
		}
		st.project = project
	case "task.created":
		var task Task
		if err := json.Unmarshal(ev.Payload, &task); err != nil {
			return err
		}
		st.tasks[task.ID] = task
	case "task.updated":
		var p taskUpdatePayload
		if err := json.Unmarshal(ev.Payload, &p); err != nil {
			return err
		}
		if p.Task.ID != "" {
			st.tasks[p.Task.ID] = p.Task
		}
	case "task.claimed":
		var p taskClaimedPayload
		if err := json.Unmarshal(ev.Payload, &p); err != nil {
			return err
		}
		task := st.tasks[p.ID]
		task.Assignee = p.Actor
		task.Status = TaskStatusInProgress
		task.UpdatedAt = p.At
		task.ClosedAt = nil
		st.tasks[task.ID] = task
	case "task.closed":
		var p taskClosedPayload
		if err := json.Unmarshal(ev.Payload, &p); err != nil {
			return err
		}
		if p.Task.ID != "" {
			st.tasks[p.Task.ID] = p.Task
			return nil
		}
		task := st.tasks[p.ID]
		task.Status = TaskStatusClosed
		task.UpdatedAt = p.At
		task.ClosedAt = &p.At
		if p.Reason != "" {
			task.Comments = append(task.Comments, TaskComment{ID: newID("comment"), Actor: ev.Actor, Body: "Closed: " + p.Reason, CreatedAt: p.At})
		}
		st.tasks[task.ID] = task
	case "task.comment_added":
		var p taskCommentPayload
		if err := json.Unmarshal(ev.Payload, &p); err != nil {
			return err
		}
		task := st.tasks[p.ID]
		task.Comments = append(task.Comments, p.Comment)
		task.UpdatedAt = p.Comment.CreatedAt
		st.tasks[task.ID] = task
	case "task.dependency_added":
		var p dependencyPayload
		if err := json.Unmarshal(ev.Payload, &p); err != nil {
			return err
		}
		task := st.tasks[p.ID]
		task.DependsOn = appendUnique(task.DependsOn, p.DependsOn)
		task.UpdatedAt = p.At
		st.tasks[task.ID] = task
	case "task.dependency_removed":
		var p dependencyPayload
		if err := json.Unmarshal(ev.Payload, &p); err != nil {
			return err
		}
		task := st.tasks[p.ID]
		task.DependsOn = removeString(task.DependsOn, p.DependsOn)
		task.UpdatedAt = p.At
		st.tasks[task.ID] = task
	case "memory.upserted":
		var mem Memory
		if err := json.Unmarshal(ev.Payload, &mem); err != nil {
			return err
		}
		st.memories[mem.ID] = mem
	case "memory.deleted":
		var p memoryDeletedPayload
		if err := json.Unmarshal(ev.Payload, &p); err != nil {
			return err
		}
		delete(st.memories, p.ID)
	case "session.summary_saved":
		var summary SessionSummary
		if err := json.Unmarshal(ev.Payload, &summary); err != nil {
			return err
		}
		st.sessions[summary.ID] = summary
	default:
		return nil
	}
	return nil
}

type taskUpdatePayload struct {
	ID    string    `json:"id"`
	Patch TaskPatch `json:"patch"`
	Task  Task      `json:"task"`
}

type taskClaimedPayload struct {
	ID    string    `json:"id"`
	Actor string    `json:"actor"`
	At    time.Time `json:"at"`
}

type taskClosedPayload struct {
	ID     string    `json:"id"`
	Reason string    `json:"reason,omitempty"`
	At     time.Time `json:"at"`
	Task   Task      `json:"task,omitempty"`
}

type taskCommentPayload struct {
	ID      string      `json:"id"`
	Comment TaskComment `json:"comment"`
}

type dependencyPayload struct {
	ID        string    `json:"id"`
	DependsOn string    `json:"depends_on"`
	At        time.Time `json:"at"`
}

type memoryDeletedPayload struct {
	ID string    `json:"id"`
	At time.Time `json:"at"`
}

// readEmbeddings loads the cached vectors via the backend.
func (s *engine) readEmbeddings() (map[string]embeddingRecord, error) {
	return s.backend.readEmbeddings()
}

// upsertEmbeddings merges the given records into the durable cache via the
// backend. Callers pass only the records they changed so concurrent writers
// (upsert path vs. recall backfill) cannot clobber each other's vectors.
func (s *engine) upsertEmbeddings(records map[string]embeddingRecord) error {
	if len(records) == 0 {
		return nil
	}
	model := ""
	if s.embedder != nil {
		model = s.embedder.Model()
	}
	return s.backend.upsertEmbeddings(records, model)
}

// cacheMemoryEmbedding embeds a single memory's content and persists it. It is
// best-effort: embedding failures are returned but callers on the write path
// ignore them so storing a memory never fails because the embedder is down.
func (s *engine) cacheMemoryEmbedding(ctx context.Context, id, content string) error {
	if s.embedder == nil || id == "" || content == "" {
		return nil
	}
	records, err := s.readEmbeddings()
	if err != nil {
		return err
	}
	if rec, ok := records[id]; ok && rec.fresh(content, s.embedder.Model()) {
		return nil
	}
	vecs, err := s.embedder.Embed(ctx, []string{content})
	if err != nil {
		return err
	}
	if len(vecs) != 1 || len(vecs[0]) == 0 {
		return nil
	}
	return s.upsertEmbeddings(map[string]embeddingRecord{id: {
		Hash:   hashContent(content),
		Model:  s.embedder.Model(),
		Dims:   len(vecs[0]),
		Vector: vecs[0],
	}})
}

// ensureEmbeddings returns a memoryID -> vector map for the given memories,
// embedding any that are missing or stale and persisting the refreshed cache.
// Backfill failures degrade gracefully: whatever vectors already exist are
// returned so recall can still use them alongside the lexical signal.
func (s *engine) ensureEmbeddings(ctx context.Context, memories []Memory) map[string][]float32 {
	vectors := map[string][]float32{}
	if s.embedder == nil {
		return vectors
	}
	records, err := s.readEmbeddings()
	if err != nil {
		records = map[string]embeddingRecord{}
	}
	model := s.embedder.Model()

	var missingIDs []string
	var missingText []string
	for _, mem := range memories {
		if rec, ok := records[mem.ID]; ok && rec.fresh(mem.Content, model) {
			vectors[mem.ID] = rec.Vector
			continue
		}
		if mem.Content == "" {
			continue
		}
		missingIDs = append(missingIDs, mem.ID)
		missingText = append(missingText, mem.Content)
	}

	if len(missingText) == 0 {
		return vectors
	}
	vecs, err := s.embedder.Embed(ctx, missingText)
	if err != nil || len(vecs) != len(missingText) {
		// Backfill failed; return whatever we already had cached.
		return vectors
	}
	refreshed := make(map[string]embeddingRecord, len(missingIDs))
	for i, id := range missingIDs {
		if len(vecs[i]) == 0 {
			continue
		}
		refreshed[id] = embeddingRecord{
			Hash:   hashContent(missingText[i]),
			Model:  model,
			Dims:   len(vecs[i]),
			Vector: vecs[i],
		}
		vectors[id] = vecs[i]
	}
	if err := s.upsertEmbeddings(refreshed); err != nil {
		log.Printf("projectstate: persisting backfilled embeddings failed: %v", err)
	}
	return vectors
}

package projectstate

import (
	"bufio"
	"bytes"
	"context"
	"crypto/sha1"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"sync"
	"syscall"
	"time"

	"github.com/google/uuid"
)

const (
	eventsFileName = "events.jsonl"
	lockStaleAfter = 30 * time.Minute
)

type FilesystemOptions struct {
	StateDir  string
	ProjectID string
	WorkDir   string
	Actor     string
	RunID     string
	// Embedder enables embeddings-backed hybrid memory recall. When nil,
	// SearchMemories falls back to the lexical keyword search and behaves
	// exactly as before.
	Embedder Embedder
	// Hybrid tunes lexical/semantic fusion. When nil, DefaultHybridConfig is
	// used. Ignored when Embedder is nil.
	Hybrid *HybridConfig
}

// FilesystemStore persists durable project state as an append-only events.jsonl
// log plus JSON index snapshots under a project state directory.
type FilesystemStore struct {
	*engine
	backend *fsBackend
}

type tasksIndex struct {
	SchemaVersion int       `json:"schema_version"`
	UpdatedAt     time.Time `json:"updated_at"`
	Tasks         []Task    `json:"tasks"`
}

type memoriesIndex struct {
	SchemaVersion int       `json:"schema_version"`
	UpdatedAt     time.Time `json:"updated_at"`
	Memories      []Memory  `json:"memories"`
}

type sessionsIndex struct {
	SchemaVersion int              `json:"schema_version"`
	UpdatedAt     time.Time        `json:"updated_at"`
	Sessions      []SessionSummary `json:"sessions"`
}

func NewFilesystemStore(opts FilesystemOptions) (*FilesystemStore, error) {
	workDir := strings.TrimSpace(opts.WorkDir)
	if workDir != "" {
		if abs, err := filepath.Abs(workDir); err == nil {
			workDir = abs
		}
	}
	projectID := sanitizeProjectID(opts.ProjectID)
	if projectID == "" {
		projectID = DeriveProjectID(workDir)
	}
	stateDir := strings.TrimSpace(opts.StateDir)
	var err error
	if stateDir == "" {
		stateDir, err = DefaultStateDir(projectID)
		if err != nil {
			return nil, err
		}
	} else if stateDir, err = filepath.Abs(stateDir); err != nil {
		return nil, fmt.Errorf("resolve project state dir: %w", err)
	}

	be := &fsBackend{stateDir: stateDir, embedder: opts.Embedder}
	hybrid := DefaultHybridConfig()
	if opts.Hybrid != nil {
		hybrid = *opts.Hybrid
	}
	eng := &engine{
		projectID: projectID,
		workDir:   workDir,
		actor:     strings.TrimSpace(opts.Actor),
		runID:     strings.TrimSpace(opts.RunID),
		stateDir:  stateDir,
		embedder:  opts.Embedder,
		hybrid:    hybrid,
		backend:   be,
	}
	store := &FilesystemStore{engine: eng, backend: be}
	if err := be.ensureDirs(); err != nil {
		return nil, err
	}
	if err := eng.initialize(context.Background()); err != nil {
		return nil, err
	}
	return store, nil
}

func (s *FilesystemStore) StateDir() string { return s.engine.stateDir }

func DefaultStateDir(projectID string) (string, error) {
	home, err := os.UserHomeDir()
	if err != nil || strings.TrimSpace(home) == "" {
		return "", fmt.Errorf("resolve home dir: %w", err)
	}
	return filepath.Join(home, ".gratefulagents", "projects", sanitizeProjectID(projectID), "state"), nil
}

func DeriveProjectID(workDir string) string {
	trimmed := strings.TrimSpace(workDir)
	if trimmed == "" {
		trimmed = "project"
	}
	base := filepath.Base(trimmed)
	if base == "." || base == string(filepath.Separator) || strings.TrimSpace(base) == "" {
		base = "project"
	}
	sum := sha1.Sum([]byte(trimmed))
	return sanitizeProjectID(base) + "-" + hex.EncodeToString(sum[:])[:8]
}

// fsBackend implements backend using an append-only events.jsonl log, JSON index
// snapshots, an embeddings.json vector cache, and a file-based advisory lock.
type fsBackend struct {
	stateDir string
	embedder Embedder
	embedMu  sync.Mutex
}

func (b *fsBackend) close() error { return nil }

func (b *fsBackend) lock(ctx context.Context) (func(), error) {
	if err := b.ensureDirs(); err != nil {
		return nil, err
	}
	return b.acquireLock(ctx)
}

func (b *fsBackend) ensureDirs() error {
	for _, dir := range []string{b.stateDir, filepath.Join(b.stateDir, "indexes"), filepath.Join(b.stateDir, "snapshots"), filepath.Join(b.stateDir, "locks")} {
		if err := os.MkdirAll(dir, 0o700); err != nil {
			return fmt.Errorf("create %s: %w", dir, err)
		}
	}
	return nil
}

func (b *fsBackend) acquireLock(ctx context.Context) (func(), error) {
	lockPath := filepath.Join(b.stateDir, "locks", "state.lock")
	token := newID("lock")
	for {
		f, err := os.OpenFile(lockPath, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
		if err == nil {
			_, _ = fmt.Fprintf(f, "pid=%d\ntoken=%s\ntime=%s\n", os.Getpid(), token, time.Now().UTC().Format(time.RFC3339Nano))
			_ = f.Close()
			return func() { releaseProjectStateLock(lockPath, token) }, nil
		}
		if !errors.Is(err, os.ErrExist) {
			return nil, fmt.Errorf("acquire project state lock: %w", err)
		}
		if staleProjectStateLock(lockPath) {
			breakStaleProjectStateLock(lockPath)
			continue
		}
		select {
		case <-ctx.Done():
			return nil, ctx.Err()
		case <-time.After(50 * time.Millisecond):
		}
	}
}

// breakStaleProjectStateLock removes a stale lock by atomically renaming it
// aside first. Removing in place would let two waiters both observe staleness
// and one of them delete the other's freshly created lock; the rename can only
// succeed for one waiter.
func breakStaleProjectStateLock(lockPath string) {
	stale := lockPath + ".stale-" + newID("break")
	if err := os.Rename(lockPath, stale); err == nil {
		_ = os.Remove(stale)
	}
}

// releaseProjectStateLock removes the lock only if it still carries our token,
// so a holder whose stale lock was broken and re-acquired by someone else does
// not delete the new holder's lock.
func releaseProjectStateLock(lockPath, token string) {
	data, err := os.ReadFile(lockPath)
	if err != nil {
		return
	}
	for _, line := range strings.Split(string(data), "\n") {
		if value, ok := strings.CutPrefix(strings.TrimSpace(line), "token="); ok {
			if strings.TrimSpace(value) == token {
				_ = os.Remove(lockPath)
			}
			return
		}
	}
}

func staleProjectStateLock(path string) bool {
	info, err := os.Stat(path)
	if err != nil {
		return false
	}
	if time.Since(info.ModTime()) > lockStaleAfter {
		return true
	}
	pid, ok := projectStateLockPID(path)
	return ok && !projectStateLockProcessAlive(pid)
}

func projectStateLockPID(path string) (int, bool) {
	data, err := os.ReadFile(path)
	if err != nil {
		return 0, false
	}
	for _, line := range strings.Split(string(data), "\n") {
		value, ok := strings.CutPrefix(strings.TrimSpace(line), "pid=")
		if !ok {
			continue
		}
		pid, err := strconv.Atoi(strings.TrimSpace(value))
		return pid, err == nil && pid > 0
	}
	return 0, false
}

func projectStateLockProcessAlive(pid int) bool {
	if pid <= 0 {
		return false
	}
	if pid == os.Getpid() {
		return true
	}
	process, err := os.FindProcess(pid)
	if err != nil {
		return false
	}
	err = process.Signal(syscall.Signal(0))
	return err == nil || errors.Is(err, os.ErrPermission)
}

func (b *fsBackend) loadEvents() ([]Event, error) {
	path := filepath.Join(b.stateDir, eventsFileName)
	f, err := os.Open(path)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, nil
		}
		return nil, fmt.Errorf("open events: %w", err)
	}
	defer f.Close()
	var events []Event
	reader := bufio.NewReaderSize(f, 64*1024)
	// A parse failure on the final line is tolerated as a torn write from a
	// crash mid-append; anything followed by more data is real corruption.
	// A torn tail is truncated away before returning so the next append
	// cannot glue a fresh event onto the malformed bytes (which would lose
	// the new event or brick the store on the following load).
	var (
		tornErr  error
		offset   int64 // bytes consumed so far
		validLen int64 // file length ending at the last parseable line
	)
	for {
		line, readErr := reader.ReadBytes('\n')
		offset += int64(len(line))
		trimmed := bytes.TrimSpace(line)
		if len(trimmed) > 0 {
			if tornErr != nil {
				return nil, tornErr
			}
			var ev Event
			if err := json.Unmarshal(trimmed, &ev); err != nil {
				tornErr = fmt.Errorf("parse event: %w", err)
			} else {
				events = append(events, ev)
				validLen = offset
			}
		} else if tornErr == nil {
			validLen = offset
		}
		if readErr != nil {
			if errors.Is(readErr, io.EOF) {
				break
			}
			return nil, fmt.Errorf("scan events: %w", readErr)
		}
	}
	if tornErr != nil {
		if err := os.Truncate(path, validLen); err != nil {
			return nil, fmt.Errorf("truncate torn event tail: %w", err)
		}
	}
	return events, nil
}

func (b *fsBackend) appendEvent(ev Event) error {
	data, err := json.Marshal(ev)
	if err != nil {
		return fmt.Errorf("marshal event: %w", err)
	}
	path := filepath.Join(b.stateDir, eventsFileName)
	f, err := os.OpenFile(path, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o600)
	if err != nil {
		return fmt.Errorf("open events for append: %w", err)
	}
	defer f.Close()
	if _, err := f.Write(append(data, '\n')); err != nil {
		return fmt.Errorf("append event: %w", err)
	}
	if err := f.Sync(); err != nil {
		return fmt.Errorf("sync events: %w", err)
	}
	return nil
}

func (b *fsBackend) snapshot(st *state) error {
	now := time.Now().UTC()
	tasks := make([]Task, 0, len(st.tasks))
	for _, task := range st.tasks {
		tasks = append(tasks, cloneTask(task))
	}
	sortTasks(tasks)
	memories := make([]Memory, 0, len(st.memories))
	for _, mem := range st.memories {
		memories = append(memories, cloneMemory(mem))
	}
	sort.SliceStable(memories, func(i, j int) bool { return memories[i].UpdatedAt.After(memories[j].UpdatedAt) })
	sessions := make([]SessionSummary, 0, len(st.sessions))
	for _, summary := range st.sessions {
		sessions = append(sessions, cloneSession(summary))
	}
	sort.SliceStable(sessions, func(i, j int) bool { return sessions[i].UpdatedAt.After(sessions[j].UpdatedAt) })

	if err := writeJSONAtomic(filepath.Join(b.stateDir, "indexes", "project.json"), st.project); err != nil {
		return err
	}
	if err := writeJSONAtomic(filepath.Join(b.stateDir, "indexes", "tasks.json"), tasksIndex{SchemaVersion: SchemaVersion, UpdatedAt: now, Tasks: tasks}); err != nil {
		return err
	}
	if err := writeJSONAtomic(filepath.Join(b.stateDir, "indexes", "memories.json"), memoriesIndex{SchemaVersion: SchemaVersion, UpdatedAt: now, Memories: memories}); err != nil {
		return err
	}
	if err := writeJSONAtomic(filepath.Join(b.stateDir, "indexes", "sessions.json"), sessionsIndex{SchemaVersion: SchemaVersion, UpdatedAt: now, Sessions: sessions}); err != nil {
		return err
	}
	return nil
}

// readEmbeddings loads the vector cache from indexes/embeddings.json. A missing
// file yields an empty cache rather than an error.
func (b *fsBackend) readEmbeddings() (map[string]embeddingRecord, error) {
	b.embedMu.Lock()
	defer b.embedMu.Unlock()
	cache, err := b.readEmbeddingCacheLocked()
	if err != nil {
		return nil, err
	}
	return cache.Vectors, nil
}

func (b *fsBackend) readEmbeddingCacheLocked() (embeddingCache, error) {
	path := filepath.Join(b.stateDir, "indexes", embeddingsFileName)
	data, err := os.ReadFile(path)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return embeddingCache{Vectors: map[string]embeddingRecord{}}, nil
		}
		return embeddingCache{}, err
	}
	var cache embeddingCache
	if err := json.Unmarshal(data, &cache); err != nil {
		// A corrupt derived cache should not break recall; rebuild lazily.
		return embeddingCache{Vectors: map[string]embeddingRecord{}}, nil
	}
	if cache.Vectors == nil {
		cache.Vectors = map[string]embeddingRecord{}
	}
	return cache, nil
}

// upsertEmbeddings merges the given records into the cache file. The re-read
// and write happen under embedMu so concurrent cachers in this process cannot
// clobber each other's vectors.
func (b *fsBackend) upsertEmbeddings(records map[string]embeddingRecord, model string) error {
	b.embedMu.Lock()
	defer b.embedMu.Unlock()
	cache, err := b.readEmbeddingCacheLocked()
	if err != nil {
		return err
	}
	for id, rec := range records {
		cache.Vectors[id] = rec
	}
	return b.writeEmbeddingCacheLocked(cache.Vectors, model)
}

// deleteEmbeddings removes cached vectors for the given memory ids.
func (b *fsBackend) deleteEmbeddings(ids []string) error {
	b.embedMu.Lock()
	defer b.embedMu.Unlock()
	cache, err := b.readEmbeddingCacheLocked()
	if err != nil {
		return err
	}
	changed := false
	for _, id := range ids {
		if _, ok := cache.Vectors[id]; ok {
			delete(cache.Vectors, id)
			changed = true
		}
	}
	if !changed {
		return nil
	}
	return b.writeEmbeddingCacheLocked(cache.Vectors, cache.Model)
}

func (b *fsBackend) writeEmbeddingCacheLocked(records map[string]embeddingRecord, model string) error {
	cache := embeddingCache{
		SchemaVersion: SchemaVersion,
		Model:         model,
		UpdatedAt:     time.Now().UTC(),
		Vectors:       records,
	}
	// Compact JSON: the vector cache is machine-only and can reach megabytes.
	data, err := json.Marshal(cache)
	if err != nil {
		return fmt.Errorf("marshal %s: %w", embeddingsFileName, err)
	}
	return writeFileAtomic(filepath.Join(b.stateDir, "indexes", embeddingsFileName), append(data, '\n'))
}

func writeJSONAtomic(path string, value any) error {
	data, err := json.MarshalIndent(value, "", "  ")
	if err != nil {
		return fmt.Errorf("marshal %s: %w", filepath.Base(path), err)
	}
	return writeFileAtomic(path, append(data, '\n'))
}

func writeFileAtomic(path string, data []byte) error {
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return fmt.Errorf("create %s: %w", dir, err)
	}
	tmp, err := os.CreateTemp(dir, ".tmp-*.json")
	if err != nil {
		return fmt.Errorf("create temp %s: %w", path, err)
	}
	tmpName := tmp.Name()
	defer os.Remove(tmpName)
	if _, err := tmp.Write(data); err != nil {
		_ = tmp.Close()
		return fmt.Errorf("write temp %s: %w", path, err)
	}
	if err := tmp.Close(); err != nil {
		return fmt.Errorf("close temp %s: %w", path, err)
	}
	if err := os.Chmod(tmpName, 0o600); err != nil {
		return fmt.Errorf("chmod temp %s: %w", path, err)
	}
	if err := os.Rename(tmpName, path); err != nil {
		return fmt.Errorf("replace %s: %w", path, err)
	}
	return nil
}

func applyPatch(task *Task, patch TaskPatch, now time.Time) {
	if patch.Title != nil {
		task.Title = strings.TrimSpace(*patch.Title)
	}
	if patch.Description != nil {
		task.Description = strings.TrimSpace(*patch.Description)
	}
	if patch.Type != nil {
		task.Type = normalizeTaskType(*patch.Type)
	}
	if patch.Status != nil {
		task.Status = normalizeTaskStatus(*patch.Status)
		if task.Status == TaskStatusClosed {
			task.ClosedAt = &now
		} else {
			task.ClosedAt = nil
		}
	}
	if patch.Priority != nil {
		task.Priority = normalizePriority(*patch.Priority)
	}
	if patch.Assignee != nil {
		task.Assignee = strings.TrimSpace(*patch.Assignee)
	}
	if patch.ReplaceLabels {
		task.Labels = uniqueNonEmpty(patch.Labels)
	}
	if patch.Metadata != nil {
		task.Metadata = cloneRaw(*patch.Metadata)
	}
	task.UpdatedAt = now
}

func hasOpenBlocker(st *state, task Task) bool {
	for _, depID := range task.DependsOn {
		dep, ok := st.tasks[depID]
		if !ok || dep.Status != TaskStatusClosed {
			return true
		}
	}
	return false
}

func recomputeBlocks(st *state) {
	for id, task := range st.tasks {
		task.Blocks = nil
		st.tasks[id] = task
	}
	for id, task := range st.tasks {
		for _, depID := range task.DependsOn {
			dep, ok := st.tasks[depID]
			if !ok {
				continue
			}
			dep.Blocks = appendUnique(dep.Blocks, id)
			st.tasks[depID] = dep
		}
	}
}

func normalizeTaskType(value string) string {
	switch strings.ToLower(strings.TrimSpace(value)) {
	case TaskTypeBug:
		return TaskTypeBug
	case TaskTypeFeature, "feat":
		return TaskTypeFeature
	case TaskTypeChore:
		return TaskTypeChore
	case TaskTypeEpic:
		return TaskTypeEpic
	default:
		return TaskTypeTask
	}
}

func normalizeTaskStatus(value string) string {
	switch strings.ToLower(strings.TrimSpace(value)) {
	case TaskStatusInProgress, "in-progress", "claimed":
		return TaskStatusInProgress
	case TaskStatusBlocked:
		return TaskStatusBlocked
	case TaskStatusClosed, "done", "completed":
		return TaskStatusClosed
	case TaskStatusDeferred:
		return TaskStatusDeferred
	default:
		return TaskStatusOpen
	}
}

func normalizePriority(value int) int {
	if value < 0 {
		return 0
	}
	if value > 4 {
		return 4
	}
	return value
}

func normalizeMemoryKind(value string) string {
	switch strings.ToLower(strings.TrimSpace(value)) {
	case MemoryKindPinned:
		return MemoryKindPinned
	case MemoryKindEpisodic:
		return MemoryKindEpisodic
	case MemoryKindProcedural:
		return MemoryKindProcedural
	default:
		return MemoryKindSemantic
	}
}

func normalizeMemoryScope(value string) string {
	switch strings.ToLower(strings.TrimSpace(value)) {
	case MemoryScopeUser:
		return MemoryScopeUser
	case MemoryScopeTask:
		return MemoryScopeTask
	case MemoryScopeFile:
		return MemoryScopeFile
	default:
		return MemoryScopeProject
	}
}

func sanitizeProjectID(value string) string {
	value = strings.ToLower(strings.TrimSpace(value))
	var b strings.Builder
	lastDash := false
	for _, r := range value {
		ok := (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9')
		if ok {
			b.WriteRune(r)
			lastDash = false
			continue
		}
		if !lastDash {
			b.WriteByte('-')
			lastDash = true
		}
	}
	return strings.Trim(b.String(), "-")
}

func newID(prefix string) string {
	id := strings.ReplaceAll(uuid.NewString(), "-", "")
	return prefix + "_" + id[:12]
}

func sortTasks(tasks []Task) {
	sort.SliceStable(tasks, func(i, j int) bool {
		if tasks[i].Status != tasks[j].Status {
			return tasks[i].Status < tasks[j].Status
		}
		if tasks[i].Priority != tasks[j].Priority {
			return tasks[i].Priority < tasks[j].Priority
		}
		if !tasks[i].UpdatedAt.Equal(tasks[j].UpdatedAt) {
			return tasks[i].UpdatedAt.After(tasks[j].UpdatedAt)
		}
		return tasks[i].ID < tasks[j].ID
	})
}

func limitTasks(tasks []Task, limit int) []Task {
	if limit > 0 && len(tasks) > limit {
		tasks = tasks[:limit]
	}
	out := make([]Task, len(tasks))
	copy(out, tasks)
	return out
}

func memoryMatchesQuery(mem Memory, query string) bool {
	haystack := strings.ToLower(strings.Join(append([]string{mem.Content, mem.Kind, mem.Scope}, append(mem.Tags, append(mem.TaskIDs, mem.FilePaths...)...)...), " "))
	if strings.Contains(haystack, query) {
		return true
	}
	for _, term := range strings.Fields(query) {
		if strings.Contains(haystack, term) {
			return true
		}
	}
	return false
}

func matchesAny(actual string, wanted []string) bool {
	if len(wanted) == 0 {
		return true
	}
	actual = strings.ToLower(strings.TrimSpace(actual))
	for _, want := range wanted {
		if actual == strings.ToLower(strings.TrimSpace(want)) {
			return true
		}
	}
	return false
}

func matchesLabels(actual, wanted []string) bool {
	if len(wanted) == 0 {
		return true
	}
	set := make(map[string]struct{}, len(actual))
	for _, label := range actual {
		set[strings.ToLower(strings.TrimSpace(label))] = struct{}{}
	}
	for _, want := range wanted {
		if _, ok := set[strings.ToLower(strings.TrimSpace(want))]; !ok {
			return false
		}
	}
	return true
}

func appendUnique(values []string, value string) []string {
	value = strings.TrimSpace(value)
	if value == "" {
		return uniqueNonEmpty(values)
	}
	for _, existing := range values {
		if existing == value {
			return uniqueNonEmpty(values)
		}
	}
	return append(uniqueNonEmpty(values), value)
}

func removeString(values []string, value string) []string {
	value = strings.TrimSpace(value)
	out := make([]string, 0, len(values))
	for _, existing := range values {
		if strings.TrimSpace(existing) != "" && existing != value {
			out = append(out, existing)
		}
	}
	return out
}

func uniqueNonEmpty(values []string) []string {
	seen := make(map[string]struct{}, len(values))
	out := make([]string, 0, len(values))
	for _, value := range values {
		value = strings.TrimSpace(value)
		if value == "" {
			continue
		}
		if _, ok := seen[value]; ok {
			continue
		}
		seen[value] = struct{}{}
		out = append(out, value)
	}
	return out
}

func cloneTaskPtr(task Task) *Task {
	out := cloneTask(task)
	return &out
}

func cloneTask(task Task) Task {
	task.DependsOn = append([]string(nil), task.DependsOn...)
	task.Blocks = append([]string(nil), task.Blocks...)
	task.Labels = append([]string(nil), task.Labels...)
	task.Comments = append([]TaskComment(nil), task.Comments...)
	task.Metadata = cloneRaw(task.Metadata)
	if task.ClosedAt != nil {
		closed := *task.ClosedAt
		task.ClosedAt = &closed
	}
	return task
}

func cloneMemoryPtr(mem Memory) *Memory {
	out := cloneMemory(mem)
	return &out
}

func cloneMemory(mem Memory) Memory {
	mem.Tags = append([]string(nil), mem.Tags...)
	mem.TaskIDs = append([]string(nil), mem.TaskIDs...)
	mem.FilePaths = append([]string(nil), mem.FilePaths...)
	mem.Metadata = cloneRaw(mem.Metadata)
	if mem.LastReadAt != nil {
		t := *mem.LastReadAt
		mem.LastReadAt = &t
	}
	return mem
}

func cloneSession(summary SessionSummary) SessionSummary {
	summary.TaskIDs = append([]string(nil), summary.TaskIDs...)
	return summary
}

func cloneRaw(raw json.RawMessage) json.RawMessage {
	if len(raw) == 0 {
		return nil
	}
	return append(json.RawMessage(nil), raw...)
}

func firstNonEmpty(values ...string) string {
	for _, value := range values {
		if strings.TrimSpace(value) != "" {
			return strings.TrimSpace(value)
		}
	}
	return ""
}

package projectstate

import (
	"context"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func TestFilesystemStoreTaskLifecycleAndIndexes(t *testing.T) {
	ctx := context.Background()
	store, err := NewFilesystemStore(FilesystemOptions{
		StateDir:  filepath.Join(t.TempDir(), "state"),
		ProjectID: "test-project",
		WorkDir:   t.TempDir(),
		Actor:     "tester",
	})
	if err != nil {
		t.Fatal(err)
	}

	blocker, err := store.CreateTask(ctx, CreateTaskInput{Title: "Set up schema", Priority: 1})
	if err != nil {
		t.Fatal(err)
	}
	blocked, err := store.CreateTask(ctx, CreateTaskInput{Title: "Use schema", Priority: 2, DependsOn: []string{blocker.ID}})
	if err != nil {
		t.Fatal(err)
	}
	ready, err := store.ReadyTasks(ctx, TaskFilter{})
	if err != nil {
		t.Fatal(err)
	}
	if len(ready) != 1 || ready[0].ID != blocker.ID {
		t.Fatalf("ready = %+v, want only blocker", ready)
	}

	if _, err := store.ClaimTask(ctx, blocker.ID, "tester"); err != nil {
		t.Fatal(err)
	}
	ready, err = store.ReadyTasks(ctx, TaskFilter{Actor: "tester"})
	if err != nil {
		t.Fatal(err)
	}
	if len(ready) != 0 {
		t.Fatalf("ready while blocker in progress = %+v, want none", ready)
	}
	if _, err := store.CloseTask(ctx, blocker.ID, "done"); err != nil {
		t.Fatal(err)
	}
	ready, err = store.ReadyTasks(ctx, TaskFilter{})
	if err != nil {
		t.Fatal(err)
	}
	if len(ready) != 1 || ready[0].ID != blocked.ID {
		t.Fatalf("ready = %+v, want blocked task after blocker closes", ready)
	}

	if _, err := os.Stat(filepath.Join(store.StateDir(), "events.jsonl")); err != nil {
		t.Fatalf("events missing: %v", err)
	}
	if _, err := os.Stat(filepath.Join(store.StateDir(), "indexes", "tasks.json")); err != nil {
		t.Fatalf("tasks index missing: %v", err)
	}

	reopened, err := NewFilesystemStore(FilesystemOptions{StateDir: store.StateDir(), ProjectID: "test-project"})
	if err != nil {
		t.Fatal(err)
	}
	got, err := reopened.GetTask(ctx, blocked.ID)
	if err != nil {
		t.Fatal(err)
	}
	if got.Blocks != nil || got.DependsOn[0] != blocker.ID {
		t.Fatalf("replayed task = %+v", got)
	}
}

func TestFilesystemStoreMemoriesAndPrime(t *testing.T) {
	ctx := context.Background()
	store, err := NewFilesystemStore(FilesystemOptions{
		StateDir:  filepath.Join(t.TempDir(), "state"),
		ProjectID: "test-project",
		Actor:     "tester",
	})
	if err != nil {
		t.Fatal(err)
	}
	task, err := store.CreateTask(ctx, CreateTaskInput{Title: "Implement durable state", Priority: 2})
	if err != nil {
		t.Fatal(err)
	}
	if _, err := store.UpsertMemory(ctx, UpsertMemoryInput{Kind: MemoryKindPinned, Content: "Use append-only project state.", Tags: []string{"state"}}); err != nil {
		t.Fatal(err)
	}
	if _, err := store.UpsertMemory(ctx, UpsertMemoryInput{Kind: MemoryKindProcedural, Content: "Run focused projectstate tests after storage changes.", TaskIDs: []string{task.ID}}); err != nil {
		t.Fatal(err)
	}
	memories, err := store.SearchMemories(ctx, MemoryFilter{Query: "focused"})
	if err != nil {
		t.Fatal(err)
	}
	if len(memories) != 1 || memories[0].Kind != MemoryKindProcedural {
		t.Fatalf("memories = %+v", memories)
	}
	prime, err := store.PrimeContext(ctx, PrimeOptions{Actor: "tester"})
	if err != nil {
		t.Fatal(err)
	}
	for _, want := range []string{"Durable Project State", task.ID, "Use append-only project state."} {
		if !strings.Contains(prime, want) {
			t.Fatalf("prime missing %q:\n%s", want, prime)
		}
	}
}

func TestProjectStateLockWithDeadPIDIsStale(t *testing.T) {
	lockDir := filepath.Join(t.TempDir(), "state", "locks")
	if err := os.MkdirAll(lockDir, 0o700); err != nil {
		t.Fatal(err)
	}
	lockPath := filepath.Join(lockDir, "state.lock")
	if err := os.WriteFile(lockPath, []byte("pid=99999999\ntime=2026-05-09T00:00:00Z\n"), 0o600); err != nil {
		t.Fatal(err)
	}

	if !staleProjectStateLock(lockPath) {
		t.Fatal("dead-pid lock was not considered stale")
	}
}

func TestFilesystemStoreTruncatesTornEventTailBeforeNewWrites(t *testing.T) {
	ctx := context.Background()
	stateDir := filepath.Join(t.TempDir(), "state")
	open := func() *FilesystemStore {
		store, err := NewFilesystemStore(FilesystemOptions{
			StateDir:  stateDir,
			ProjectID: "test-project",
			WorkDir:   t.TempDir(),
			Actor:     "tester",
		})
		if err != nil {
			t.Fatal(err)
		}
		return store
	}

	store := open()
	if _, err := store.CreateTask(ctx, CreateTaskInput{Title: "before crash"}); err != nil {
		t.Fatal(err)
	}

	// Simulate a crash mid-append: a malformed, newline-less final record.
	eventsPath := filepath.Join(stateDir, eventsFileName)
	f, err := os.OpenFile(eventsPath, os.O_APPEND|os.O_WRONLY, 0o600)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := f.WriteString(`{"type":"task_created","pay`); err != nil {
		t.Fatal(err)
	}
	if err := f.Close(); err != nil {
		t.Fatal(err)
	}

	// A fresh store must drop the torn tail, truncate it away, and keep
	// accepting durable writes.
	store = open()
	if _, err := store.CreateTask(ctx, CreateTaskInput{Title: "after crash"}); err != nil {
		t.Fatal(err)
	}

	store = open()
	tasks, err := store.ListTasks(ctx)
	if err != nil {
		t.Fatal(err)
	}
	titles := make([]string, 0, len(tasks))
	for _, task := range tasks {
		titles = append(titles, task.Title)
	}
	if len(tasks) != 2 {
		t.Fatalf("tasks after torn-tail recovery = %v, want [before crash, after crash]", titles)
	}
}

package projectstate

import (
	"fmt"
	"sort"
	"strings"
	"unicode/utf8"
)

func activeTask(st *state, opts PrimeOptions) *Task {
	if opts.ActiveTaskID != "" {
		if task, ok := st.tasks[opts.ActiveTaskID]; ok {
			return cloneTaskPtr(task)
		}
	}
	for _, task := range st.tasks {
		if task.Status == TaskStatusInProgress && (opts.Actor == "" || task.Assignee == opts.Actor) {
			return cloneTaskPtr(task)
		}
	}
	return nil
}

func readyFromState(st *state, filter TaskFilter) []Task {
	var tasks []Task
	for _, task := range st.tasks {
		if task.Status != TaskStatusOpen {
			continue
		}
		if !matchesLabels(task.Labels, filter.Labels) {
			continue
		}
		actor := firstNonEmpty(filter.Actor, filter.Assignee)
		if filter.Assignee != "" && task.Assignee != "" && task.Assignee != filter.Assignee {
			continue
		}
		if !filter.IncludeAssigned && task.Assignee != "" && task.Assignee != actor {
			continue
		}
		if hasOpenBlocker(st, task) {
			continue
		}
		tasks = append(tasks, cloneTask(task))
	}
	sortTasks(tasks)
	return limitTasks(tasks, filter.Limit)
}

func blockedTasks(st *state, limit int) []Task {
	var tasks []Task
	for _, task := range st.tasks {
		if task.Status != TaskStatusOpen && task.Status != TaskStatusBlocked {
			continue
		}
		if hasOpenBlocker(st, task) {
			tasks = append(tasks, cloneTask(task))
		}
	}
	sortTasks(tasks)
	return limitTasks(tasks, limit)
}

func memoriesForPrime(st *state, limit int) (pinned, recent []Memory) {
	for _, mem := range st.memories {
		switch mem.Kind {
		case MemoryKindPinned:
			pinned = append(pinned, cloneMemory(mem))
		default:
			recent = append(recent, cloneMemory(mem))
		}
	}
	sortMemoriesForPrime(pinned)
	sortMemoriesForPrime(recent)
	if limit > 0 {
		if len(pinned) > limit {
			pinned = pinned[:limit]
		}
		remaining := limit - len(pinned)
		if len(recent) > remaining {
			recent = recent[:remaining]
		}
	}
	return pinned, recent
}

func sortMemoriesForPrime(memories []Memory) {
	sort.SliceStable(memories, func(i, j int) bool {
		return memories[i].UpdatedAt.After(memories[j].UpdatedAt)
	})
}

func writeTaskLine(b *strings.Builder, task Task) {
	status := task.Status
	if status == "" {
		status = TaskStatusOpen
	}
	fmt.Fprintf(b, "- %s [P%d %s] %s\n", task.ID, task.Priority, status, oneLine(task.Title, 180))
}

func memorySuffix(mem Memory) string {
	var parts []string
	if mem.Kind != "" {
		parts = append(parts, mem.Kind)
	}
	if len(mem.Tags) > 0 {
		parts = append(parts, strings.Join(mem.Tags, ","))
	}
	if len(parts) == 0 {
		return ""
	}
	return " (" + strings.Join(parts, "; ") + ")"
}

func oneLine(value string, max int) string {
	value = strings.Join(strings.Fields(strings.TrimSpace(value)), " ")
	if max <= 3 || len(value) <= max {
		return value
	}
	cut := max - 3
	for cut > 0 && !utf8.RuneStart(value[cut]) {
		cut--
	}
	return value[:cut] + "..."
}

package projectstate

import (
	"context"
	"database/sql"
	"encoding/binary"
	"fmt"
	"math"
	"net/url"
	"os"
	"path/filepath"
	"strings"
	"time"

	_ "modernc.org/sqlite"
)

// busyTimeoutMS bounds how long a writer waits for the WAL write lock before
// returning SQLITE_BUSY. The engine serializes in-process writers with a mutex,
// so this only matters for separate processes sharing one database file.
const sqliteBusyTimeoutMS = 5000

// SQLiteOptions configures a SQLiteStore. Exactly one of DB or Path supplies the
// database: pass DB to share an already-open handle (for example the assistant's
// shared state.db) or Path to have the store open and own its own file.
type SQLiteOptions struct {
	// DB is an existing database handle to use. When set, the store does not
	// close it and assumes the caller has configured WAL/pragmas. Table names
	// are namespaced (see TablePrefix) so projectstate can coexist with other
	// tables in a shared database.
	DB *sql.DB
	// Path opens (creating if necessary) a dedicated database file. Ignored when
	// DB is set.
	Path string
	// TablePrefix namespaces the store's tables. Defaults to "projectstate_".
	TablePrefix string

	ProjectID string
	WorkDir   string
	Actor     string
	RunID     string
	// Embedder enables embeddings-backed hybrid memory recall. When nil,
	// SearchMemories falls back to lexical keyword search.
	Embedder Embedder
	// Hybrid tunes lexical/semantic fusion. When nil, DefaultHybridConfig is used.
	Hybrid *HybridConfig
}

// SQLiteStore persists durable project state in SQLite. It reuses the same
// event-sourced engine as FilesystemStore: events live in a table and the
// in-memory state is rebuilt by replaying them, so behavior is identical to the
// filesystem store while gaining transactional durability and a shareable DB.
type SQLiteStore struct {
	*engine
	backend *sqliteBackend
}

// NewSQLiteStore opens a SQLite-backed project state store.
func NewSQLiteStore(opts SQLiteOptions) (*SQLiteStore, error) {
	workDir := strings.TrimSpace(opts.WorkDir)
	if workDir != "" {
		if abs, err := filepath.Abs(workDir); err == nil {
			workDir = abs
		}
	}
	projectID := sanitizeProjectID(opts.ProjectID)
	if projectID == "" {
		projectID = DeriveProjectID(workDir)
	}
	prefix := strings.TrimSpace(opts.TablePrefix)
	if prefix == "" {
		prefix = "projectstate_"
	}

	be := &sqliteBackend{
		projectID:   projectID,
		eventsTable: prefix + "events",
		embedTable:  prefix + "embeddings",
	}
	var stateDir string
	if opts.DB != nil {
		be.db = opts.DB
	} else {
		path := strings.TrimSpace(opts.Path)
		if path == "" {
			return nil, fmt.Errorf("projectstate: SQLiteOptions requires DB or Path")
		}
		if abs, err := filepath.Abs(path); err == nil {
			path = abs
		}
		if dir := filepath.Dir(path); dir != "" {
			if err := os.MkdirAll(dir, 0o700); err != nil {
				return nil, fmt.Errorf("create db dir: %w", err)
			}
		}
		db, err := openSQLiteFile(path)
		if err != nil {
			return nil, err
		}
		_ = os.Chmod(path, 0o600)
		be.db = db
		be.ownDB = true
		stateDir = filepath.Dir(path)
	}

	if err := be.migrate(); err != nil {
		if be.ownDB {
			_ = be.db.Close()
		}
		return nil, err
	}

	hybrid := DefaultHybridConfig()
	if opts.Hybrid != nil {
		hybrid = *opts.Hybrid
	}
	eng := &engine{
		projectID: projectID,
		workDir:   workDir,
		actor:     strings.TrimSpace(opts.Actor),
		runID:     strings.TrimSpace(opts.RunID),
		stateDir:  stateDir,
		embedder:  opts.Embedder,
		hybrid:    hybrid,
		backend:   be,
	}
	store := &SQLiteStore{engine: eng, backend: be}
	if err := eng.initialize(context.Background()); err != nil {
		if be.ownDB {
			_ = be.db.Close()
		}
		return nil, err
	}
	return store, nil
}

// DB returns the underlying database handle so callers can share it.
func (s *SQLiteStore) DB() *sql.DB { return s.backend.db }

func openSQLiteFile(path string) (*sql.DB, error) {
	dsn := "file:" + path + "?" + url.Values{
		"_txlock": []string{"immediate"},
		"_pragma": []string{
			fmt.Sprintf("busy_timeout(%d)", sqliteBusyTimeoutMS),
			"journal_mode(WAL)",
			"synchronous(NORMAL)",
			"foreign_keys(on)",
		},
	}.Encode()
	db, err := sql.Open("sqlite", dsn)
	if err != nil {
		return nil, err
	}
	// A single connection serializes writers, avoiding SQLITE_BUSY convoys under
	// WAL. Throughput here is tiny (one agent's durable state).
	db.SetMaxOpenConns(1)
	return db, nil
}

// sqliteBackend implements backend on top of a SQLite database. Events are
// scoped by project_id so multiple projects can share one database file.
type sqliteBackend struct {
	db          *sql.DB
	ownDB       bool
	projectID   string
	eventsTable string
	embedTable  string
}

func (b *sqliteBackend) migrate() error {
	stmts := []string{
		fmt.Sprintf(`CREATE TABLE IF NOT EXISTS %s (
			project_id TEXT NOT NULL,
			seq        INTEGER NOT NULL,
			event_id   TEXT NOT NULL,
			run_id     TEXT,
			actor      TEXT,
			ts         INTEGER NOT NULL,
			type       TEXT NOT NULL,
			payload    BLOB,
			PRIMARY KEY (project_id, seq)
		)`, b.eventsTable),
		fmt.Sprintf(`CREATE TABLE IF NOT EXISTS %s (
			project_id TEXT NOT NULL,
			memory_id  TEXT NOT NULL,
			hash       TEXT NOT NULL,
			model      TEXT NOT NULL,
			dims       INTEGER NOT NULL,
			vector     BLOB NOT NULL,
			PRIMARY KEY (project_id, memory_id)
		)`, b.embedTable),
	}
	tx, err := b.db.Begin()
	if err != nil {
		return err
	}
	defer func() { _ = tx.Rollback() }()
	for _, stmt := range stmts {
		if _, err := tx.Exec(stmt); err != nil {
			return fmt.Errorf("projectstate sqlite migrate: %w", err)
		}
	}
	return tx.Commit()
}

func (b *sqliteBackend) close() error {
	if b.ownDB {
		return b.db.Close()
	}
	return nil
}

// lock is a no-op: the engine serializes in-process access with its mutex and
// SQLite's own locking (busy_timeout + the single write connection) serializes
// across processes.
func (b *sqliteBackend) lock(_ context.Context) (func(), error) {
	return func() {}, nil
}

func (b *sqliteBackend) loadEvents() ([]Event, error) {
	rows, err := b.db.Query(
		fmt.Sprintf(`SELECT seq, event_id, run_id, actor, ts, type, payload FROM %s WHERE project_id = ? ORDER BY seq`, b.eventsTable),
		b.projectID,
	)
	if err != nil {
		return nil, fmt.Errorf("load events: %w", err)
	}
	defer rows.Close()
	var events []Event
	for rows.Next() {
		var (
			ev      Event
			runID   sql.NullString
			actor   sql.NullString
			ts      int64
			payload []byte
		)
		if err := rows.Scan(&ev.Seq, &ev.EventID, &runID, &actor, &ts, &ev.Type, &payload); err != nil {
			return nil, fmt.Errorf("scan event: %w", err)
		}
		ev.ProjectID = b.projectID
		ev.RunID = runID.String
		ev.Actor = actor.String
		ev.Time = time.Unix(0, ts).UTC()
		if len(payload) > 0 {
			ev.Payload = append([]byte(nil), payload...)
		}
		events = append(events, ev)
	}
	return events, rows.Err()
}

func (b *sqliteBackend) appendEvent(ev Event) error {
	// The seq computed by the engine can collide when another process appended
	// events after our state load (lock() is a no-op for SQLite). Assigning
	// seq atomically inside the INSERT keeps concurrent writers from failing
	// on the (project_id, seq) primary key.
	_, err := b.db.Exec(
		fmt.Sprintf(`INSERT INTO %s (project_id, seq, event_id, run_id, actor, ts, type, payload)
			SELECT ?, COALESCE(MAX(seq), 0) + 1, ?, ?, ?, ?, ?, ? FROM %s WHERE project_id = ?`, b.eventsTable, b.eventsTable),
		b.projectID, ev.EventID, nullString(ev.RunID), nullString(ev.Actor), ev.Time.UTC().UnixNano(), ev.Type, []byte(ev.Payload), b.projectID,
	)
	if err != nil {
		return fmt.Errorf("append event: %w", err)
	}
	return nil
}

// snapshot is a no-op: state is always rebuilt from the events table.
func (b *sqliteBackend) snapshot(_ *state) error { return nil }

func (b *sqliteBackend) readEmbeddings() (map[string]embeddingRecord, error) {
	rows, err := b.db.Query(
		fmt.Sprintf(`SELECT memory_id, hash, model, dims, vector FROM %s WHERE project_id = ?`, b.embedTable),
		b.projectID,
	)
	if err != nil {
		return nil, fmt.Errorf("read embeddings: %w", err)
	}
	defer rows.Close()
	out := map[string]embeddingRecord{}
	for rows.Next() {
		var (
			id     string
			rec    embeddingRecord
			vector []byte
		)
		if err := rows.Scan(&id, &rec.Hash, &rec.Model, &rec.Dims, &vector); err != nil {
			return nil, fmt.Errorf("scan embedding: %w", err)
		}
		rec.Vector = decodeVector(vector)
		out[id] = rec
	}
	return out, rows.Err()
}

// upsertEmbeddings merges the given records via per-row upserts so concurrent
// writers (upsert path vs. recall backfill, possibly in other processes) never
// wipe each other's vectors.
func (b *sqliteBackend) upsertEmbeddings(records map[string]embeddingRecord, _ string) error {
	tx, err := b.db.Begin()
	if err != nil {
		return err
	}
	defer func() { _ = tx.Rollback() }()
	stmt, err := tx.Prepare(fmt.Sprintf(
		`INSERT INTO %s (project_id, memory_id, hash, model, dims, vector) VALUES (?, ?, ?, ?, ?, ?)
		ON CONFLICT(project_id, memory_id) DO UPDATE SET hash = excluded.hash, model = excluded.model, dims = excluded.dims, vector = excluded.vector`,
		b.embedTable))
	if err != nil {
		return err
	}
	defer stmt.Close()
	for id, rec := range records {
		if len(rec.Vector) == 0 {
			continue
		}
		if _, err := stmt.Exec(b.projectID, id, rec.Hash, rec.Model, rec.Dims, encodeVector(rec.Vector)); err != nil {
			return fmt.Errorf("upsert embedding: %w", err)
		}
	}
	return tx.Commit()
}

// deleteEmbeddings removes cached vectors for the given memory ids.
func (b *sqliteBackend) deleteEmbeddings(ids []string) error {
	tx, err := b.db.Begin()
	if err != nil {
		return err
	}
	defer func() { _ = tx.Rollback() }()
	stmt, err := tx.Prepare(fmt.Sprintf(`DELETE FROM %s WHERE project_id = ? AND memory_id = ?`, b.embedTable))
	if err != nil {
		return err
	}
	defer stmt.Close()
	for _, id := range ids {
		if _, err := stmt.Exec(b.projectID, id); err != nil {
			return fmt.Errorf("delete embedding: %w", err)
		}
	}
	return tx.Commit()
}

func nullString(value string) any {
	if strings.TrimSpace(value) == "" {
		return nil
	}
	return value
}

// encodeVector packs a float32 slice into a little-endian byte blob.
func encodeVector(vec []float32) []byte {
	out := make([]byte, len(vec)*4)
	for i, v := range vec {
		binary.LittleEndian.PutUint32(out[i*4:], math.Float32bits(v))
	}
	return out
}

// decodeVector unpacks a little-endian byte blob into a float32 slice.
func decodeVector(data []byte) []float32 {
	n := len(data) / 4
	out := make([]float32, n)
	for i := 0; i < n; i++ {
		out[i] = math.Float32frombits(binary.LittleEndian.Uint32(data[i*4:]))
	}
	return out
}

package projectstate

import (
	"context"
	"database/sql"
	"path/filepath"
	"strings"
	"testing"
)

func TestSQLiteStoreTaskLifecycleAndReplay(t *testing.T) {
	ctx := context.Background()
	dbPath := filepath.Join(t.TempDir(), "state.db")
	store, err := NewSQLiteStore(SQLiteOptions{
		Path:      dbPath,
		ProjectID: "test-project",
		WorkDir:   t.TempDir(),
		Actor:     "tester",
	})
	if err != nil {
		t.Fatal(err)
	}

	blocker, err := store.CreateTask(ctx, CreateTaskInput{Title: "Set up schema", Priority: 1})
	if err != nil {
		t.Fatal(err)
	}
	blocked, err := store.CreateTask(ctx, CreateTaskInput{Title: "Use schema", Priority: 2, DependsOn: []string{blocker.ID}})
	if err != nil {
		t.Fatal(err)
	}
	ready, err := store.ReadyTasks(ctx, TaskFilter{})
	if err != nil {
		t.Fatal(err)
	}
	if len(ready) != 1 || ready[0].ID != blocker.ID {
		t.Fatalf("ready = %+v, want only blocker", ready)
	}

	if _, err := store.ClaimTask(ctx, blocker.ID, "tester"); err != nil {
		t.Fatal(err)
	}
	ready, err = store.ReadyTasks(ctx, TaskFilter{Actor: "tester"})
	if err != nil {
		t.Fatal(err)
	}
	if len(ready) != 0 {
		t.Fatalf("ready while blocker in progress = %+v, want none", ready)
	}
	if _, err := store.CloseTask(ctx, blocker.ID, "done"); err != nil {
		t.Fatal(err)
	}
	ready, err = store.ReadyTasks(ctx, TaskFilter{})
	if err != nil {
		t.Fatal(err)
	}
	if len(ready) != 1 || ready[0].ID != blocked.ID {
		t.Fatalf("ready = %+v, want blocked task after blocker closes", ready)
	}
	if err := store.Close(); err != nil {
		t.Fatal(err)
	}

	// Reopen the same file and confirm state replays from the events table.
	reopened, err := NewSQLiteStore(SQLiteOptions{Path: dbPath, ProjectID: "test-project"})
	if err != nil {
		t.Fatal(err)
	}
	defer reopened.Close()
	got, err := reopened.GetTask(ctx, blocked.ID)
	if err != nil {
		t.Fatal(err)
	}
	if got.Blocks != nil || got.DependsOn[0] != blocker.ID {
		t.Fatalf("replayed task = %+v", got)
	}
}

func TestSQLiteStoreMemoriesAndPrime(t *testing.T) {
	ctx := context.Background()
	store, err := NewSQLiteStore(SQLiteOptions{
		Path:      filepath.Join(t.TempDir(), "state.db"),
		ProjectID: "test-project",
		Actor:     "tester",
	})
	if err != nil {
		t.Fatal(err)
	}
	defer store.Close()
	task, err := store.CreateTask(ctx, CreateTaskInput{Title: "Implement durable state", Priority: 2})
	if err != nil {
		t.Fatal(err)
	}
	if _, err := store.UpsertMemory(ctx, UpsertMemoryInput{Kind: MemoryKindPinned, Content: "Use append-only project state.", Tags: []string{"state"}}); err != nil {
		t.Fatal(err)
	}
	if _, err := store.UpsertMemory(ctx, UpsertMemoryInput{Kind: MemoryKindProcedural, Content: "Run focused projectstate tests after storage changes.", TaskIDs: []string{task.ID}}); err != nil {
		t.Fatal(err)
	}
	memories, err := store.SearchMemories(ctx, MemoryFilter{Query: "focused"})
	if err != nil {
		t.Fatal(err)
	}
	if len(memories) != 1 || memories[0].Kind != MemoryKindProcedural {
		t.Fatalf("memories = %+v", memories)
	}
	prime, err := store.PrimeContext(ctx, PrimeOptions{Actor: "tester"})
	if err != nil {
		t.Fatal(err)
	}
	for _, want := range []string{"Durable Project State", task.ID, "Use append-only project state."} {
		if !strings.Contains(prime, want) {
			t.Fatalf("prime missing %q:\n%s", want, prime)
		}
	}
}

// TestSQLiteStoreSharedDB verifies that a caller-provided *sql.DB is used (not
// closed) and that table prefixes keep two projects isolated in one database.
func TestSQLiteStoreSharedDB(t *testing.T) {
	ctx := context.Background()
	db, err := openSQLiteFile(filepath.Join(t.TempDir(), "shared.db"))
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()

	a, err := NewSQLiteStore(SQLiteOptions{DB: db, ProjectID: "proj-a"})
	if err != nil {
		t.Fatal(err)
	}
	b, err := NewSQLiteStore(SQLiteOptions{DB: db, ProjectID: "proj-b"})
	if err != nil {
		t.Fatal(err)
	}
	if _, err := a.CreateTask(ctx, CreateTaskInput{Title: "A task"}); err != nil {
		t.Fatal(err)
	}
	if _, err := b.CreateTask(ctx, CreateTaskInput{Title: "B task"}); err != nil {
		t.Fatal(err)
	}
	aTasks, err := a.ListTasks(ctx)
	if err != nil {
		t.Fatal(err)
	}
	if len(aTasks) != 1 || aTasks[0].Title != "A task" {
		t.Fatalf("project a tasks = %+v, want only its own", aTasks)
	}
	bTasks, err := b.ListTasks(ctx)
	if err != nil {
		t.Fatal(err)
	}
	if len(bTasks) != 1 || bTasks[0].Title != "B task" {
		t.Fatalf("project b tasks = %+v, want only its own", bTasks)
	}

	// Close on a shared-DB store must not close the underlying handle.
	if err := a.Close(); err != nil {
		t.Fatal(err)
	}
	if err := db.PingContext(ctx); err != nil {
		t.Fatalf("shared db closed unexpectedly: %v", err)
	}
	var _ *sql.DB = b.DB()
}

