package providers

// Regression tests for the 2026-07 audit: top-level AuthMode/APIMode must not
// leak into the always-registered OpenAI leg of a multi-provider spec.

import (
	"testing"

	sdkopenai "github.com/gratefulagents/sdk/pkg/agentsdk/providers/openai"
)

func TestAuthModeForOpenAIProviderScopesOAuthToOpenAI(t *testing.T) {
	oauthSession, err := sdkopenai.NewOAuthAuthSessionFromSecretData(
		[]byte(`{"tokens":{"access_token":"oauth-access","refresh_token":"oauth-refresh","account_id":"acct"}}`), "")
	if err != nil {
		t.Fatalf("NewOAuthAuthSessionFromSecretData() error = %v", err)
	}
	cases := []struct {
		name string
		spec ProviderSpec
		want sdkopenai.AuthMode
	}{
		{
			name: "oauth for openai default stays oauth",
			spec: ProviderSpec{Provider: "multi", DefaultProvider: "openai", AuthMode: "oauth"},
			want: sdkopenai.AuthModeOAuth,
		},
		{
			name: "oauth for direct openai provider stays oauth",
			spec: ProviderSpec{Provider: "openai", AuthMode: "oauth"},
			want: sdkopenai.AuthModeOAuth,
		},
		{
			name: "oauth aimed at anthropic default does not leak",
			spec: ProviderSpec{Provider: "multi", DefaultProvider: "anthropic", AuthMode: "oauth"},
			want: sdkopenai.AuthModeAPIKey,
		},
		{
			name: "oauth aimed at anthropic default stays oauth with mounted openai material",
			spec: ProviderSpec{Provider: "multi", DefaultProvider: "anthropic", AuthMode: "oauth", OpenAIOAuthPath: "/var/run/oauth/openai/auth.json"},
			want: sdkopenai.AuthModeOAuth,
		},
		{
			name: "oauth aimed at anthropic default stays oauth with oauth session",
			spec: ProviderSpec{Provider: "multi", DefaultProvider: "anthropic", AuthMode: "oauth", OpenAIAuthSession: oauthSession},
			want: sdkopenai.AuthModeOAuth,
		},
		{
			name: "oauth aimed at anthropic default does not leak with non-oauth session",
			spec: ProviderSpec{Provider: "multi", DefaultProvider: "anthropic", AuthMode: "oauth", OpenAIAuthSession: sdkopenai.NewAPIKeyAuthSession("sk-test")},
			want: sdkopenai.AuthModeAPIKey,
		},
		{
			name: "explicit per-provider api-key beats top-level oauth and mounted material",
			spec: ProviderSpec{Provider: "multi", DefaultProvider: "anthropic", AuthMode: "oauth", OpenAIOAuthPath: "/var/run/oauth/openai/auth.json", ProviderAuthModes: map[string]string{"openai": "api-key"}},
			want: sdkopenai.AuthModeAPIKey,
		},
		{
			name: "explicit per-provider oauth wins without top-level oauth",
			spec: ProviderSpec{Provider: "multi", DefaultProvider: "openai", ProviderAuthModes: map[string]string{"openai": "oauth"}},
			want: sdkopenai.AuthModeOAuth,
		},
		{
			name: "api-key mode passes through",
			spec: ProviderSpec{Provider: "multi", DefaultProvider: "openai", AuthMode: ""},
			want: sdkopenai.AuthModeAPIKey,
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if got := authModeForOpenAIProvider(tc.spec); got != tc.want {
				t.Fatalf("authModeForOpenAIProvider(%+v) = %q, want %q", tc.spec, got, tc.want)
			}
		})
	}
}

func TestAuthModeForAnthropicProviderExplicitOverride(t *testing.T) {
	// Explicit api-key pins the leg even when the top-level mode is oauth for
	// the anthropic default.
	spec := ProviderSpec{Provider: "multi", DefaultProvider: "anthropic", AuthMode: "oauth", ProviderAuthModes: map[string]string{"anthropic": "api-key"}}
	if got := authModeForAnthropicProvider(spec); got != "api-key" {
		t.Fatalf("authModeForAnthropicProvider() = %q, want api-key", got)
	}
	// Explicit oauth pins the leg on a run without a top-level oauth mode.
	spec = ProviderSpec{Provider: "multi", DefaultProvider: "openai", ProviderAuthModes: map[string]string{"anthropic": "oauth"}}
	if got := authModeForAnthropicProvider(spec); got != "oauth" {
		t.Fatalf("authModeForAnthropicProvider() = %q, want oauth", got)
	}
}

func TestMultiProviderAnthropicOAuthDoesNotForceCodexBaseURLOnOpenAI(t *testing.T) {
	spec := ProviderSpec{
		Provider:        "multi",
		DefaultProvider: "anthropic",
		AuthMode:        "oauth",
		ProviderAPIKeys: map[string]string{"openai": "sk-test"},
	}
	provider, err := newOpenAIProviderFromSpec(spec)
	if err != nil {
		t.Fatal(err)
	}
	if provider == nil {
		t.Fatal("nil provider")
	}
	// The regression put the OpenAI leg on the Codex OAuth backend; with the
	// scoping guard, auth mode is api-key so the base URL defaults to
	// api.openai.com. We can't reach into the model easily, so assert via the
	// scoped auth mode used by the builder.
	if got := authModeForOpenAIProvider(spec); got != sdkopenai.AuthModeAPIKey {
		t.Fatalf("openai leg auth mode = %q, want api-key", got)
	}
}

func TestAPIModeForCanonicalOpenAIIsScoped(t *testing.T) {
	// A top-level APIMode aimed at another default provider must not force the
	// canonical openai leg off its default.
	spec := ProviderSpec{
		Provider:        "multi",
		DefaultProvider: "openrouter",
		APIMode:         "chat-completions",
	}
	if got := apiModeForProvider(spec, DefaultProviderOpenAI, ""); got != "" {
		t.Fatalf("apiModeForProvider(openai) = %q, want \"\" (provider default)", got)
	}
	// Explicit per-provider setting still wins.
	spec.ProviderAPIModes = map[string]string{"openai": "responses"}
	if got := apiModeForProvider(spec, DefaultProviderOpenAI, ""); got != "responses" {
		t.Fatalf("apiModeForProvider(openai) with explicit map = %q, want responses", got)
	}
}

package providers

import (
	"os/exec"
	"strings"
	"testing"
)

func TestProviderPackagesDoNotDependOnOperatorPackages(t *testing.T) {
	t.Parallel()

	cmd := exec.Command("go", "list", "-deps", "-f", "{{.ImportPath}}", "./...")
	out, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("go list SDK provider deps: %v\n%s", err, out)
	}

	forbidden := []string{
		"github.com/gratefulagents/sdk/api/",
		"github.com/gratefulagents/sdk/internal/controller/",
		"github.com/gratefulagents/sdk/internal/agentplatform",
		"github.com/gratefulagents/sdk/internal/store/",
		"github.com/gratefulagents/sdk/internal/tools",
		"github.com/aws/",
		"go.opentelemetry.io/",
		"k8s.io/",
		"sigs.k8s.io/",
	}
	for _, dep := range strings.Fields(string(out)) {
		for _, prefix := range forbidden {
			if strings.HasPrefix(dep, prefix) {
				t.Fatalf("SDK provider dependency %q crosses forbidden operator boundary %q", dep, prefix)
			}
		}
	}
}

