func TestSanitizeLogBodyRedactsSensitiveKeysAndPlaintextTokens(t *testing.T) {
	bodies := []string{
		`{"diagnostic":"invalid grant","password_hint":"pw","authorization":"Bearer bearer-secret","cookie_value":"session","public_key":"key-value","message":"failed for sk-plaintext"}`,
		`invalid grant: refresh_token=refresh-plain client_secret: client-plain authorization=Basic basic-plain cookie="cookie-plain"`,
	}
	for _, body := range bodies {
		got := SanitizeLogBody(body)
		for _, secret := range []string{"pw", "bearer-secret", "session", "key-value", "sk-plaintext", "refresh-plain", "client-plain", "basic-plain", "cookie-plain"} {
			if strings.Contains(got, secret) {
				t.Fatalf("SanitizeLogBody leaked %q in %q", secret, got)
			}
		}
		if !strings.Contains(got, "invalid grant") {
			t.Fatalf("SanitizeLogBody removed diagnostic: %q", got)
		}
	}
}

func jsonResponse(status int, body string) *http.Response {
	return &http.Response{
		StatusCode: status,
		Header:     http.Header{"Content-Type": []string{"application/json"}},
		Body:       io.NopCloser(strings.NewReader(body)),
	}
}

package oauth

import (
	"context"
	"errors"
	"fmt"
	"os"
	"strings"
	"sync"
	"time"
)

// AnthropicTokenSourceLead is the in-process refresh window for
// AnthropicFileTokenSource. It is deliberately much shorter than
// AnthropicRefreshLead: when a central refresher (e.g. the platform operator)
// owns rotation, the mounted file is normally updated long before this window,
// so the in-process refresh only fires when central rotation failed or does
// not exist (standalone SDK use). Keeping the window small avoids racing the
// central refresher for the single-use refresh token.
const AnthropicTokenSourceLead = 2 * time.Minute

// AnthropicFileTokenSource resolves Anthropic OAuth access tokens per request
// from an auth JSON file (Claude Code .credentials.json or the SDK's flat
// shape). It re-reads the file when it changes — picking up tokens rotated by
// an external refresher, such as a Kubernetes Secret mount — and, as a last
// resort, self-refreshes near expiry using the refresh token, writing the
// result back best-effort (read-only mounts keep the refreshed token in
// memory only).
//
// It implements the anthropic client's TokenSource contract:
// Token(ctx) (string, error) and Invalidate().
type AnthropicFileTokenSource struct {
	path string
	cfg  RefreshConfig
	lead time.Duration

	mu          sync.Mutex
	auth        AnthropicAuth
	loaded      bool
	fileModTime time.Time
	fileSize    int64
	// badToken is an access token rejected by the API (Invalidate); it forces
	// a re-read and, if the file still holds the same token, a refresh.
	badToken string
}

// NewAnthropicFileTokenSource creates a token source backed by the auth JSON
// file at path. cfg controls the refresh HTTP client and endpoint overrides;
// zero values use the production Anthropic OAuth defaults.
func NewAnthropicFileTokenSource(path string, cfg RefreshConfig) *AnthropicFileTokenSource {
	return &AnthropicFileTokenSource{
		path: strings.TrimSpace(path),
		cfg:  cfg,
		lead: AnthropicTokenSourceLead,
	}
}

// WithRefreshLead overrides the near-expiry window that triggers an
// in-process refresh. Returns the receiver for chaining.
func (s *AnthropicFileTokenSource) WithRefreshLead(lead time.Duration) *AnthropicFileTokenSource {
	if lead > 0 {
		s.lead = lead
	}
	return s
}

// Token returns a current access token, re-reading the backing file when it
// changed and refreshing via the OAuth token endpoint when the token is
// missing, rejected, or near expiry.
func (s *AnthropicFileTokenSource) Token(ctx context.Context) (string, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	now := refreshNow(s.cfg)
	s.reloadIfChangedLocked()

	token := strings.TrimSpace(s.auth.AccessToken)
	stale := token == "" || (s.badToken != "" && token == s.badToken) || s.nearExpiryLocked(now)
	if stale && strings.TrimSpace(s.auth.RefreshToken) != "" {
		if err := s.refreshLocked(ctx); err != nil {
			// Grace: a not-yet-expired token may still be accepted even when
			// the refresh endpoint is flaky; only fail hard when the token is
			// unusable (missing, rejected, or past expiry).
			if token == "" || token == s.badToken || s.expiredLocked(now) {
				return "", err
			}
		}
	}

	token = strings.TrimSpace(s.auth.AccessToken)
	if token == "" {
		return "", errors.New("anthropic oauth material is missing access token")
	}
	return token, nil
}

// Invalidate marks the current access token as rejected so the next Token
// call re-reads the file and refreshes if the file still holds the same
// credential. Called by the API client after a 401.
func (s *AnthropicFileTokenSource) Invalidate() {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.badToken = strings.TrimSpace(s.auth.AccessToken)
	// Force a re-read: an external refresher may already have rotated the file.
	s.loaded = false
	s.fileModTime = time.Time{}
	s.fileSize = 0
}

// reloadIfChangedLocked re-reads the backing file when it is unread or its
// stat signature changed. Read failures keep the in-memory credential, which
// still works for read-only or racy mounts.
func (s *AnthropicFileTokenSource) reloadIfChangedLocked() {
	if s.path == "" {
		return
	}
	info, statErr := os.Stat(s.path)
	if statErr == nil && s.loaded && info.ModTime().Equal(s.fileModTime) && info.Size() == s.fileSize {
		return
	}
	raw, err := os.ReadFile(s.path)
	if err != nil {
		return
	}
	auth, err := ParseAnthropicAuthJSON(raw)
	if err != nil {
		return
	}
	s.auth = auth
	s.loaded = true
	// Cache the signature captured *before* the read: if the file rotated
	// between stat and read, the stale signature forces a harmless re-read on
	// the next call, whereas re-stating here could pair the new file's
	// signature with the old contents and suppress reloads until Invalidate.
	if statErr == nil {
		s.fileModTime = info.ModTime()
		s.fileSize = info.Size()
	} else {
		s.fileModTime = time.Time{}
		s.fileSize = 0
	}
	// A rotated file supersedes any previous rejection.
	if strings.TrimSpace(auth.AccessToken) != s.badToken {
		s.badToken = ""
	}
}

func (s *AnthropicFileTokenSource) nearExpiryLocked(now time.Time) bool {
	if s.auth.ExpiresAt.IsZero() {
		return false
	}
	return !s.auth.ExpiresAt.After(now.Add(s.lead))
}

func (s *AnthropicFileTokenSource) expiredLocked(now time.Time) bool {
	if s.auth.ExpiresAt.IsZero() {
		return false
	}
	return !s.auth.ExpiresAt.After(now)
}

// refreshLocked exchanges the refresh token and adopts + persists the result.
// It runs on a context detached from the request: refresh tokens are
// single-use, so aborting the exchange mid-flight (request cancelled) could
// consume the token without capturing its replacement.
func (s *AnthropicFileTokenSource) refreshLocked(ctx context.Context) error {
	refreshCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), 30*time.Second)
	defer cancel()
	updated, err := RefreshAnthropicTokens(refreshCtx, s.auth, s.cfg)
	if err != nil {
		return fmt.Errorf("refresh anthropic oauth token: %w", err)
	}
	auth, err := ParseAnthropicAuthJSON(updated)
	if err != nil {
		return fmt.Errorf("parse refreshed anthropic oauth material: %w", err)
	}
	s.auth = auth
	s.badToken = ""
	s.writeBackLocked(updated)
	return nil
}

// writeBackLocked persists refreshed material so restarts and sibling
// processes see it. Failures are expected on read-only mounts and ignored;
// the refreshed token stays usable in memory.
func (s *AnthropicFileTokenSource) writeBackLocked(raw []byte) {
	if s.path == "" {
		return
	}
	if err := os.WriteFile(s.path, raw, 0o600); err != nil {
		return
	}
	if info, err := os.Stat(s.path); err == nil {
		s.fileModTime = info.ModTime()
		s.fileSize = info.Size()
	}
}

package oauth

import (
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"testing"
	"time"
)

func writeAuthFile(t *testing.T, dir string, auth AnthropicAuth) string {
	t.Helper()
	raw, err := MarshalAnthropicAuthJSON(auth)
	if err != nil {
		t.Fatalf("marshal auth: %v", err)
	}
	path := filepath.Join(dir, "auth.json")
	if err := os.WriteFile(path, raw, 0o600); err != nil {
		t.Fatalf("write auth file: %v", err)
	}
	return path
}

func TestAnthropicFileTokenSource_ReturnsFileToken(t *testing.T) {
	path := writeAuthFile(t, t.TempDir(), AnthropicAuth{
		AccessToken:  "tok-1",
		RefreshToken: "refresh-1",
		ExpiresAt:    time.Now().Add(4 * time.Hour),
	})
	src := NewAnthropicFileTokenSource(path, RefreshConfig{})
	got, err := src.Token(context.Background())
	if err != nil {
		t.Fatalf("Token() error = %v", err)
	}
	if got != "tok-1" {
		t.Fatalf("Token() = %q, want tok-1", got)
	}
}

func TestAnthropicFileTokenSource_PicksUpExternalRotation(t *testing.T) {
	dir := t.TempDir()
	path := writeAuthFile(t, dir, AnthropicAuth{
		AccessToken:  "tok-old",
		RefreshToken: "refresh-1",
		ExpiresAt:    time.Now().Add(4 * time.Hour),
	})
	src := NewAnthropicFileTokenSource(path, RefreshConfig{})
	if got, _ := src.Token(context.Background()); got != "tok-old" {
		t.Fatalf("first Token() = %q, want tok-old", got)
	}

	// Simulate the central refresher rotating the mounted secret.
	raw, _ := MarshalAnthropicAuthJSON(AnthropicAuth{
		AccessToken:  "tok-new",
		RefreshToken: "refresh-2",
		ExpiresAt:    time.Now().Add(8 * time.Hour),
	})
	// Ensure the mtime signature changes even on coarse filesystems.
	if err := os.WriteFile(path, raw, 0o600); err != nil {
		t.Fatalf("rotate auth file: %v", err)
	}
	future := time.Now().Add(2 * time.Second)
	_ = os.Chtimes(path, future, future)

	got, err := src.Token(context.Background())
	if err != nil {
		t.Fatalf("Token() after rotation error = %v", err)
	}
	if got != "tok-new" {
		t.Fatalf("Token() after rotation = %q, want tok-new", got)
	}
}

func TestAnthropicFileTokenSource_SelfRefreshNearExpiry(t *testing.T) {
	var refreshCalls int
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		refreshCalls++
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]any{
			"access_token":  "tok-refreshed",
			"refresh_token": "refresh-2",
			"expires_in":    28800,
		})
	}))
	defer srv.Close()

	dir := t.TempDir()
	path := writeAuthFile(t, dir, AnthropicAuth{
		AccessToken:  "tok-stale",
		RefreshToken: "refresh-1",
		ExpiresAt:    time.Now().Add(30 * time.Second), // inside the 2-minute lead
	})
	src := NewAnthropicFileTokenSource(path, RefreshConfig{AnthropicTokenURL: srv.URL})

	got, err := src.Token(context.Background())
	if err != nil {
		t.Fatalf("Token() error = %v", err)
	}
	if got != "tok-refreshed" {
		t.Fatalf("Token() = %q, want tok-refreshed", got)
	}
	if refreshCalls != 1 {
		t.Fatalf("refresh calls = %d, want 1", refreshCalls)
	}

	// Refreshed material must be written back for restarts/siblings.
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read back auth file: %v", err)
	}
	auth, err := ParseAnthropicAuthJSON(raw)
	if err != nil {
		t.Fatalf("parse written-back auth: %v", err)
	}
	if auth.AccessToken != "tok-refreshed" || auth.RefreshToken != "refresh-2" {
		t.Fatalf("written-back auth = %+v, want refreshed tokens", auth)
	}

	// Cached: a second call must not refresh again.
	if got, _ := src.Token(context.Background()); got != "tok-refreshed" {
		t.Fatalf("second Token() = %q, want tok-refreshed", got)
	}
	if refreshCalls != 1 {
		t.Fatalf("refresh calls after second Token = %d, want 1", refreshCalls)
	}
}

func TestAnthropicFileTokenSource_RefreshFailureGrace(t *testing.T) {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusInternalServerError)
		_, _ = w.Write([]byte(`{"error":"boom"}`))
	}))
	defer srv.Close()

	path := writeAuthFile(t, t.TempDir(), AnthropicAuth{
		AccessToken:  "tok-still-valid",
		RefreshToken: "refresh-1",
		ExpiresAt:    time.Now().Add(90 * time.Second), // near expiry but not expired
	})
	src := NewAnthropicFileTokenSource(path, RefreshConfig{AnthropicTokenURL: srv.URL})

	got, err := src.Token(context.Background())
	if err != nil {
		t.Fatalf("Token() error = %v, want grace success", err)
	}
	if got != "tok-still-valid" {
		t.Fatalf("Token() = %q, want tok-still-valid", got)
	}
}

func TestAnthropicFileTokenSource_RefreshFailureExpiredFails(t *testing.T) {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusUnauthorized)
		_, _ = w.Write([]byte(`{"error":"refresh_token_expired"}`))
	}))
	defer srv.Close()

	path := writeAuthFile(t, t.TempDir(), AnthropicAuth{
		AccessToken:  "tok-expired",
		RefreshToken: "refresh-1",
		ExpiresAt:    time.Now().Add(-time.Minute),
	})
	src := NewAnthropicFileTokenSource(path, RefreshConfig{AnthropicTokenURL: srv.URL})

	if _, err := src.Token(context.Background()); err == nil {
		t.Fatalf("Token() error = nil, want refresh failure for expired token")
	}
}

func TestAnthropicFileTokenSource_InvalidateForcesRefresh(t *testing.T) {
	var refreshCalls int
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		refreshCalls++
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]any{
			"access_token":  "tok-after-401",
			"refresh_token": "refresh-2",
			"expires_in":    28800,
		})
	}))
	defer srv.Close()

	path := writeAuthFile(t, t.TempDir(), AnthropicAuth{
		AccessToken:  "tok-rejected",
		RefreshToken: "refresh-1",
		ExpiresAt:    time.Now().Add(4 * time.Hour), // looks valid, but the API rejected it
	})
	src := NewAnthropicFileTokenSource(path, RefreshConfig{AnthropicTokenURL: srv.URL})

	if got, _ := src.Token(context.Background()); got != "tok-rejected" {
		t.Fatalf("first Token() = %q, want tok-rejected", got)
	}
	src.Invalidate()
	got, err := src.Token(context.Background())
	if err != nil {
		t.Fatalf("Token() after Invalidate error = %v", err)
	}
	if got != "tok-after-401" {
		t.Fatalf("Token() after Invalidate = %q, want tok-after-401", got)
	}
	if refreshCalls != 1 {
		t.Fatalf("refresh calls = %d, want 1", refreshCalls)
	}
}

package openai

import (
	"context"
	"fmt"
	"log"
	"os"
	"strings"
	"sync"
	"time"

	"github.com/gratefulagents/sdk/pkg/agentsdk"
)

// CompactionMetadataResolver fetches provider model metadata once and uses it
// to derive SDK compaction defaults for OpenAI-compatible models. A failed
// fetch (e.g. a cancelled first caller or a transient network error) is
// retried after a cooldown instead of being cached for the process lifetime.
type CompactionMetadataResolver struct {
	baseURL string
	session *AuthSession

	fetchMu     sync.Mutex
	fetched     bool
	byID        map[string]ModelMetadata
	lastErr     error
	lastAttempt time.Time

	mu     sync.Mutex
	logged map[string]struct{}
}

// compactionMetadataRetryCooldown throttles re-fetch attempts after a failed
// model-metadata fetch.
const compactionMetadataRetryCooldown = 30 * time.Second

func NewCompactionMetadataResolver(baseURL string, session ...*AuthSession) *CompactionMetadataResolver {
	var authSession *AuthSession
	if len(session) > 0 {
		authSession = session[0]
	}
	return &CompactionMetadataResolver{
		baseURL: strings.TrimSpace(baseURL),
		session: authSession,
		logged:  make(map[string]struct{}),
	}
}

func (r *CompactionMetadataResolver) Lookup(ctx context.Context, model string) (ModelMetadata, bool) {
	if r == nil {
		return ModelMetadata{}, false
	}
	byID, err := r.metadataByID(ctx)
	if err != nil {
		r.LogOnce("fetch-error", "WARN: failed to fetch OpenAI model metadata for compaction: %v", err)
		return ModelMetadata{}, false
	}

	for _, key := range modelMetadataLookupKeys(model) {
		if meta, ok := byID[key]; ok {
			return meta, true
		}
	}
	r.LogOnce("missing:"+strings.ToLower(strings.TrimSpace(model)), "WARN: provider model metadata did not include %q; using conservative compaction defaults", model)
	return ModelMetadata{}, false
}

// metadataByID returns the cached metadata map, fetching it on first use and
// re-attempting failed fetches after compactionMetadataRetryCooldown.
func (r *CompactionMetadataResolver) metadataByID(ctx context.Context) (map[string]ModelMetadata, error) {
	r.fetchMu.Lock()
	defer r.fetchMu.Unlock()
	if r.fetched {
		return r.byID, r.lastErr
	}
	if r.session == nil {
		// No credentials will ever appear on this resolver; don't retry.
		r.fetched = true
		r.lastErr = fmt.Errorf("OpenAI auth session is required")
		return nil, r.lastErr
	}
	if r.lastErr != nil && time.Since(r.lastAttempt) < compactionMetadataRetryCooldown {
		return nil, r.lastErr
	}
	r.lastAttempt = time.Now()
	byID, err := FetchModelMetadataByID(ctx, r.baseURL, r.session)
	if err != nil {
		r.lastErr = err
		return nil, err
	}
	r.byID = byID
	r.lastErr = nil
	r.fetched = true
	return r.byID, nil
}

func (r *CompactionMetadataResolver) LogOnce(key, format string, args ...any) {
	if r == nil {
		return
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	if _, ok := r.logged[key]; ok {
		return
	}
	r.logged[key] = struct{}{}
	log.Printf(format, args...)
}

func modelMetadataLookupKeys(model string) []string {
	model = strings.ToLower(strings.TrimSpace(model))
	if model == "" {
		return nil
	}
	keys := []string{model}
	_, unprefixed := agentsdk.ParseModelPrefix(model)
	unprefixed = strings.ToLower(strings.TrimSpace(unprefixed))
	if unprefixed != "" && unprefixed != model {
		keys = append(keys, unprefixed)
	}
	return keys
}

func CompactionDefaultsFromModelMetadata(meta ModelMetadata) (triggerTokens, targetTokens int, ok bool) {
	contextWindow := meta.ResolvedContextWindow()
	triggerTokens = meta.AutoCompactTokenLimit
	if contextWindow > 0 {
		contextLimit := (contextWindow * 9) / 10
		if triggerTokens <= 0 || triggerTokens > contextLimit {
			triggerTokens = contextLimit
		}
		targetTokens = contextWindow / 2
	} else if triggerTokens > 0 {
		targetTokens = triggerTokens / 2
	}
	if triggerTokens <= 0 {
		return 0, 0, false
	}
	if targetTokens <= 0 || targetTokens >= triggerTokens {
		targetTokens = triggerTokens / 2
	}
	return triggerTokens, targetTokens, true
}

// CompactionConfigFromMetadata builds a compaction config using provider model
// metadata. It returns ok=false when metadata is unavailable or incomplete.
// Authentication uses OPENAI_API_KEY when set; prefer
// CompactionConfigFromMetadataWithAuthSession to supply explicit credentials.
func CompactionConfigFromMetadata(ctx context.Context, baseURL, model string) (agentsdk.CompactionConfig, bool) {
	resolver := NewCompactionMetadataResolver(baseURL, NewAPIKeyAuthSession(os.Getenv("OPENAI_API_KEY")))
	return compactionConfigFromResolver(ctx, resolver, model)
}

// CompactionConfigFromMetadataWithAuthSession builds a compaction config using
// provider model metadata fetched with an explicit auth session.
func CompactionConfigFromMetadataWithAuthSession(ctx context.Context, baseURL, model string, session *AuthSession) (agentsdk.CompactionConfig, bool) {
	resolver := NewCompactionMetadataResolver(baseURL, session)
	return compactionConfigFromResolver(ctx, resolver, model)
}

func compactionConfigFromResolver(ctx context.Context, resolver *CompactionMetadataResolver, model string) (agentsdk.CompactionConfig, bool) {
	meta, ok := resolver.Lookup(ctx, model)
	if !ok {
		return agentsdk.CompactionConfig{}, false
	}
	trigger, target, ok := CompactionDefaultsFromModelMetadata(meta)
	if !ok {
		return agentsdk.CompactionConfig{}, false
	}
	cfg := agentsdk.DefaultCompactionConfig()
	cfg.TriggerTokens = trigger
	cfg.TargetTokens = target
	return cfg, true
}

package openai

import (
	"strings"
	"testing"

	"github.com/gratefulagents/sdk/pkg/agentsdk"
)

// Compaction blobs stamped as Anthropic-origin are not decryptable by OpenAI
// and must be skipped instead of 400-ing the request after a provider switch.
func TestItemsToAnthropicMessagesSkipsAnthropicCompactionBlobs(t *testing.T) {
	items := []agentsdk.RunItem{
		{Type: agentsdk.RunItemMessage, Message: &agentsdk.MessageOutput{Text: "task"}},
		{Type: agentsdk.RunItemCompaction, Compaction: &agentsdk.CompactionData{
			ID: "cmp_anthropic", EncryptedContent: "anthropic-blob", CreatedBy: "anthropic",
		}},
		{Type: agentsdk.RunItemCompaction, Compaction: &agentsdk.CompactionData{
			ID: "cmp_openai", EncryptedContent: "openai-blob", CreatedBy: "openai",
		}},
		{Type: agentsdk.RunItemCompaction, Compaction: &agentsdk.CompactionData{
			ID: "cmp_legacy", EncryptedContent: "unstamped-blob",
		}},
	}
	msgs := itemsToAnthropicMessages(items)

	var kept []string
	for _, msg := range msgs {
		for _, block := range msg.Content {
			if block.Type == "compaction" {
				kept = append(kept, block.EncryptedContent)
			}
		}
	}
	if len(kept) != 2 {
		t.Fatalf("kept %d compaction blocks (%v), want 2 (openai + legacy unstamped)", len(kept), kept)
	}
	for _, enc := range kept {
		if enc == "anthropic-blob" {
			t.Fatalf("foreign Anthropic blob was forwarded to OpenAI: %v", kept)
		}
	}
}

// Anthropic compaction blocks carry a plaintext summary alongside the
// encrypted blob; after a switch to OpenAI that summary must survive as an
// assistant text message instead of vanishing with the skipped blob.
func TestItemsToAnthropicMessagesDownConvertsAnthropicBlobSummary(t *testing.T) {
	items := []agentsdk.RunItem{
		{Type: agentsdk.RunItemCompaction, Compaction: &agentsdk.CompactionData{
			ID: "cmp_anthropic", EncryptedContent: "anthropic-blob", CreatedBy: "anthropic",
			Content: "user asked for X; agent finished steps A and B",
		}},
		{Type: agentsdk.RunItemCompaction, Compaction: &agentsdk.CompactionData{
			ID: "cmp_anthropic_opaque", EncryptedContent: "anthropic-blob-2", CreatedBy: "anthropic",
		}},
	}
	msgs := itemsToAnthropicMessages(items)

	var texts []string
	for _, msg := range msgs {
		for _, block := range msg.Content {
			switch block.Type {
			case "compaction":
				t.Fatalf("foreign blob forwarded: %+v", block)
			case "text":
				texts = append(texts, block.Text)
			}
		}
	}
	if len(texts) != 1 {
		t.Fatalf("got %d text blocks (%v), want 1 down-converted summary (opaque blob has nothing to keep)", len(texts), texts)
	}
	if !strings.Contains(texts[0], "steps A and B") || !strings.Contains(texts[0], "[CONTEXT SUMMARY") {
		t.Fatalf("down-converted summary = %q", texts[0])
	}
}

