package sandbox

import (
	"context"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
	"syscall"
	"testing"
	"time"

	"github.com/gratefulagents/sdk/pkg/agentsdk/policy"
)

// TestMain doubles as a helper-process entry point for
// TestRunBuiltCommandKillsDaemonizedChildOnTimeout. Two phases:
//   - SANDBOX_TEST_DAEMONIZE_MARKER set: spawn a grandchild via exec, then sleep
//     long. The grandchild inherits the leader's process group. The parent
//     (this process) is the leader spawned by the test.
//   - SANDBOX_TEST_DAEMONIZE_GRANDCHILD set: record pid then sleep long.
func TestMain(m *testing.M) {
	if marker := os.Getenv("SANDBOX_TEST_DAEMONIZE_GRANDCHILD"); marker != "" {
		_ = os.WriteFile(marker, []byte(strconv.Itoa(os.Getpid())), 0o644)
		time.Sleep(30 * time.Second)
		os.Exit(0)
	}
	if marker := os.Getenv("SANDBOX_TEST_DAEMONIZE_MARKER"); marker != "" {
		runDaemonizeHelper(marker)
		return
	}
	os.Exit(m.Run())
}

func runDaemonizeHelper(marker string) {
	exe, err := os.Executable()
	if err != nil {
		os.Exit(3)
	}
	cmd := exec.Command(exe)
	cmd.Env = []string{"SANDBOX_TEST_DAEMONIZE_GRANDCHILD=" + marker}
	devnull, _ := os.OpenFile(os.DevNull, os.O_RDWR, 0)
	if devnull != nil {
		cmd.Stdin = devnull
		cmd.Stdout = devnull
		cmd.Stderr = devnull
	}
	if err := cmd.Start(); err != nil {
		os.Exit(4)
	}
	// Do not wait; let the grandchild run independently in the same process group.
	time.Sleep(30 * time.Second)
	os.Exit(0)
}

func TestRunBuiltCommandKillsDaemonizedChildOnTimeout(t *testing.T) {
	tmp := t.TempDir()
	marker := filepath.Join(tmp, "child.pid")

	exe, err := os.Executable()
	if err != nil {
		t.Skipf("os.Executable unavailable in this sandbox: %v", err)
	}

	_, err = LocalExecutor{Config: Config{ExtraEnv: map[string]string{"SANDBOX_TEST_DAEMONIZE_MARKER": marker}}}.Run(context.Background(), Request{
		Argv:           []string{exe},
		WorkDir:        tmp,
		PermissionMode: policy.PermissionModeDangerFullAccess,
		Timeout:        500 * time.Millisecond,
	})
	if err != nil {
		t.Fatalf("Run() error = %v", err)
	}

	pidDeadline := time.Now().Add(2 * time.Second)
	var pidStr string
	for time.Now().Before(pidDeadline) {
		b, readErr := os.ReadFile(marker)
		if readErr == nil && len(strings.TrimSpace(string(b))) > 0 {
			pidStr = strings.TrimSpace(string(b))
			break
		}
		time.Sleep(20 * time.Millisecond)
	}
	if pidStr == "" {
		t.Fatal("grandchild never recorded its pid")
	}
	pid, convErr := strconv.Atoi(pidStr)
	if convErr != nil {
		t.Fatalf("parse pid %q: %v", pidStr, convErr)
	}

	// Process must be reaped within timeout (500ms) + grace (~3s) + slack.
	deadline := time.Now().Add(6 * time.Second)
	for time.Now().Before(deadline) {
		if err := syscall.Kill(pid, 0); err != nil {
			return
		}
		time.Sleep(50 * time.Millisecond)
	}
	_ = syscall.Kill(pid, syscall.SIGKILL)
	t.Fatalf("grandchild pid=%d survived past timeout+grace; process group not killed", pid)
}

package agentsdk

import "github.com/gratefulagents/sdk/internal/agent"

// SubAgentSchedulerConfig configures the SDK async sub-agent scheduler.
type SubAgentSchedulerConfig struct {
	MaxConcurrent           int
	Runner                  *Runner
	Agents                  map[string]*Agent
	Tracker                 *RunProgress
	EventStream             *EventStream
	EventWriter             *EventStream
	WorkDir                 string
	ToolOutputDir           string
	ToolAccessLevel         ToolAccessLevel
	ToolPolicy              *ToolPolicy
	CompactionConfig        CompactionConfig
	CompactionModelResolver CompactionModelResolver
	MaxTurns                int
	Checkpoint              func(SubAgentSchedulerCheckpoint) error
}

// NewSubAgentScheduler creates a scheduler for async sub-agent tasks.
func NewSubAgentScheduler(cfg SubAgentSchedulerConfig) *SubAgentScheduler {
	eventStream := cfg.EventStream
	if eventStream == nil {
		eventStream = cfg.EventWriter
	}
	return agent.NewSubAgentRegistry(agent.SubAgentRegistryConfig{
		MaxConcurrent:           cfg.MaxConcurrent,
		Runner:                  cfg.Runner,
		Agents:                  cfg.Agents,
		Tracker:                 cfg.Tracker,
		EventStream:             eventStream,
		WorkDir:                 cfg.WorkDir,
		ToolOutputDir:           cfg.ToolOutputDir,
		ToolAccessLevel:         cfg.ToolAccessLevel,
		ToolPolicy:              cfg.ToolPolicy,
		CompactionConfig:        cfg.CompactionConfig,
		CompactionModelResolver: cfg.CompactionModelResolver,
		MaxTurns:                cfg.MaxTurns,
		Checkpoint:              cfg.Checkpoint,
	})
}

// ConfigureSubAgentScheduler refreshes host/runtime wiring for an existing
// scheduler while preserving already tracked async tasks.
//
// Security-relevant fields are sticky: an empty ToolAccessLevel and nil
// ToolPolicy/Tracker/EventStream(s) keep the scheduler's current values, so a
// partial config can never silently escalate future sub-agents to full access
// or disable approvals, progress tracking, or event emission.
func ConfigureSubAgentScheduler(s *SubAgentScheduler, cfg SubAgentSchedulerConfig) {
	if s == nil {
		return
	}
	eventStream := cfg.EventStream
	if eventStream == nil {
		eventStream = cfg.EventWriter
	}
	s.Configure(agent.SubAgentRegistryConfig{
		MaxConcurrent:           cfg.MaxConcurrent,
		Runner:                  cfg.Runner,
		Agents:                  cfg.Agents,
		Tracker:                 cfg.Tracker,
		EventStream:             eventStream,
		WorkDir:                 cfg.WorkDir,
		ToolOutputDir:           cfg.ToolOutputDir,
		ToolAccessLevel:         cfg.ToolAccessLevel,
		ToolPolicy:              cfg.ToolPolicy,
		CompactionConfig:        cfg.CompactionConfig,
		CompactionModelResolver: cfg.CompactionModelResolver,
		MaxTurns:                cfg.MaxTurns,
		Checkpoint:              cfg.Checkpoint,
	})
}

package agentsdk

import (
	"encoding/json"
	"io"
	"strings"
)

// SessionEventStreamOptions configures NewSessionEventStream.
type SessionEventStreamOptions struct {
	Logger       *AgentLogger
	EnableLogger bool
	LogLevel     LogLevel
	Session      int32
	Phase        string

	SystemInit *SessionSystemInit
}

type SessionSystemInit struct {
	Model          string
	PermissionMode string
	Cwd            string
	MaxTurns       int
	Tools          []string
	MCPServers     []string
}

// NewSessionEventStream creates an EventStream with common session metadata
// already wired and optionally emits system_init.
func NewSessionEventStream(w io.Writer, opts SessionEventStreamOptions) *EventStream {
	es := NewEventStream(w)
	if opts.Logger != nil {
		es.SetLogger(opts.Logger)
	} else if opts.EnableLogger {
		es.SetLogger(NewAgentLogger(opts.LogLevel))
	}
	if opts.Session != 0 {
		es.SetSession(opts.Session)
	}
	if opts.Phase != "" {
		es.SetPhase(opts.Phase)
	}
	if opts.SystemInit != nil {
		es.EmitSystemInit(
			opts.SystemInit.Model,
			opts.SystemInit.PermissionMode,
			opts.SystemInit.Cwd,
			opts.SystemInit.MaxTurns,
			opts.SystemInit.Tools,
			opts.SystemInit.MCPServers,
		)
	}
	return es
}

// ChildToolEvent is the typed SDK view of a child/sub-agent tool event emitted
// through the session event stream.
type ChildToolEvent struct {
	ParentCallID string
	CallID       string
	AgentName    string
	Tool         string
	Phase        string
	InputRaw     string
	Output       string
	IsError      bool
	DurationMS   int64
}

// ParseContentEventLine parses one JSONL content-event line.
func ParseContentEventLine(line string) (ContentEvent, bool) {
	if strings.TrimSpace(line) == "" {
		return ContentEvent{}, false
	}
	var ev ContentEvent
	if err := json.Unmarshal([]byte(line), &ev); err != nil {
		return ContentEvent{}, false
	}
	if ev.Type == "" {
		return ContentEvent{}, false
	}
	return ev, true
}

// ChildToolEventFromContentEvent extracts child tool start/end data from a
// session event. The event is considered a child tool event when it carries a
// parent call id.
func ChildToolEventFromContentEvent(ev ContentEvent) (*ChildToolEvent, bool) {
	if ev.ParentCallID == "" {
		return nil, false
	}
	switch ev.Type {
	case "tool_start":
		return &ChildToolEvent{
			ParentCallID: ev.ParentCallID,
			CallID:       ev.ToolUseID,
			AgentName:    ev.AgentName,
			Tool:         ev.Tool,
			Phase:        "start",
			InputRaw:     ev.InputRaw,
		}, true
	case "tool_end":
		return &ChildToolEvent{
			ParentCallID: ev.ParentCallID,
			CallID:       ev.ToolUseID,
			AgentName:    ev.AgentName,
			Tool:         ev.Tool,
			Phase:        "end",
			Output:       ev.Output,
			IsError:      ev.IsError,
			DurationMS:   ev.ToolDurationMS,
		}, true
	default:
		return nil, false
	}
}

// CompactContentEvent returns a short, human-readable rendering of a content
// event for debug logs.
func CompactContentEvent(ev ContentEvent) string {
	parts := []string{ev.Type}
	if ev.AgentName != "" {
		parts = append(parts, "agent="+ev.AgentName)
	}
	if ev.Tool != "" {
		parts = append(parts, "tool="+ev.Tool)
	}
	if ev.Status != "" {
		parts = append(parts, "status="+ev.Status)
	}
	if ev.IsError {
		parts = append(parts, "error=true")
	}
	if ev.FailureKind != "" {
		parts = append(parts, "failure="+ev.FailureKind)
	}
	if ev.Reason != "" {
		parts = append(parts, firstContentEventLine(ev.Reason))
	}
	if ev.Message != "" {
		parts = append(parts, firstContentEventLine(ev.Message))
	}
	if ev.IsError && ev.Output != "" {
		parts = append(parts, firstContentEventLine(ev.Output))
	}
	return strings.Join(parts, " ")
}

// CompactContentEventLine parses and compacts a JSONL event line. Non-event
// lines fall back to their first line.
func CompactContentEventLine(line string) string {
	if ev, ok := ParseContentEventLine(line); ok {
		return CompactContentEvent(ev)
	}
	return firstContentEventLine(line)
}

func firstContentEventLine(s string) string {
	s = strings.TrimSpace(s)
	if i := strings.IndexByte(s, '\n'); i >= 0 {
		return s[:i]
	}
	return s
}

