			"slow-model": slow,
		}}),
		Agents: map[string]*Agent{
			"fast-worker": {Name: "fast-worker", Model: "fast-model"},
			"slow-worker": {Name: "slow-worker", Model: "slow-model"},
		},
	})
	spawnTool := &subagentTool{registry: registry, defaultAgent: "fast-worker"}
	waitTool := &subagentWaitTool{registry: registry}

	fastID := spawnBackgroundSubagentTask(t, spawnTool, `{"message":"quick","agent_name":"fast-worker","mode":"background"}`)
	slowID := spawnBackgroundSubagentTask(t, spawnTool, `{"message":"long","agent_name":"slow-worker","mode":"background"}`)
	for name, started := range map[string]chan struct{}{"fast": fast.started, "slow": slow.started} {
		select {
		case <-started:
		case <-time.After(time.Second):
			t.Fatalf("timed out waiting for %s child to start", name)
		}
	}

	close(fast.release)
	result, err := waitTool.Execute(context.Background(), json.RawMessage(`{"wait_for":"any"}`), "")
	if err != nil {
		t.Fatal(err)
	}
	resp := decodeSubagentWaitResponse(t, result)
	if !resp.WaitComplete {
		t.Fatalf("wait_for=any should complete on first result: %s", result.Content)
	}
	if len(resp.Finished) != 1 || resp.Finished[0].TaskID != fastID {
		t.Fatalf("finished = %+v, want only fast task %s", resp.Finished, fastID)
	}
	if len(resp.StillActive) != 1 || resp.StillActive[0].TaskID != slowID {
		t.Fatalf("still_active = %+v, want slow task %s", resp.StillActive, slowID)
	}

	// The fast result was delivered above: a second any-wait must keep
	// blocking on the slow task instead of returning the same result again.
	result, err = waitTool.Execute(context.Background(), json.RawMessage(`{"wait_for":"any","timeout_ms":100}`), "")
	if err != nil {
		t.Fatal(err)
	}
	resp = decodeSubagentWaitResponse(t, result)
	if resp.WaitComplete || !resp.TimedOut {
		t.Fatalf("second any-wait must block until a new result: %s", result.Content)
	}
	if len(resp.Finished) != 0 {
		t.Fatalf("second any-wait re-delivered results: %+v", resp.Finished)
	}

	// Same with explicit task_ids that reuse the already-delivered fast id:
	// the stale result must be reported under previously_delivered without its
	// payload, never under finished.
	result, err = waitTool.Execute(context.Background(), json.RawMessage(`{"wait_for":"any","task_ids":["`+fastID+`","`+slowID+`"],"timeout_ms":100}`), "")
	if err != nil {
		t.Fatal(err)
	}
	resp = decodeSubagentWaitResponse(t, result)
	if resp.WaitComplete || !resp.TimedOut {
		t.Fatalf("explicit-ids any-wait must block until a new result: %s", result.Content)
	}
	if len(resp.Finished) != 0 {
		t.Fatalf("explicit-ids any-wait re-delivered stale results as finished: %+v", resp.Finished)
	}
	if len(resp.PreviouslyDelivered) != 1 || resp.PreviouslyDelivered[0].TaskID != fastID {
		t.Fatalf("previously_delivered = %+v, want fast task %s", resp.PreviouslyDelivered, fastID)
	}
	if resp.PreviouslyDelivered[0].Result != "" {
		t.Fatalf("previously_delivered must omit the stale result payload: %+v", resp.PreviouslyDelivered)
	}
	// The omission must advertise the recovery path for parents that lost the
	// original delivery to context compaction.
	if !strings.Contains(resp.Note, `subagent_status detail="results"`) {
		t.Fatalf("note = %q, want re-fetch hint", resp.Note)
	}

	close(slow.release)
	result, err = waitTool.Execute(context.Background(), json.RawMessage(`{"wait_for":"any","task_ids":["`+fastID+`","`+slowID+`"]}`), "")
	if err != nil {
		t.Fatal(err)
	}
	resp = decodeSubagentWaitResponse(t, result)
	if !resp.WaitComplete || len(resp.Finished) != 1 || resp.Finished[0].TaskID != slowID {
		t.Fatalf("third any-wait = %s, want slow task result", result.Content)
	}
	if resp.Finished[0].Result != "blocked child done" {
		t.Fatalf("third any-wait finished = %+v, want slow task payload", resp.Finished)
	}
	if len(resp.PreviouslyDelivered) != 1 || resp.PreviouslyDelivered[0].TaskID != fastID || resp.PreviouslyDelivered[0].Result != "" {
		t.Fatalf("third any-wait previously_delivered = %+v, want payload-free fast task", resp.PreviouslyDelivered)
	}
	if registry.HasPendingFinalJoinTasks() {
		t.Fatal("all results should be marked delivered")
	}
}

func TestSubagentWaitNoTasksInvalidInputAndUndelivered(t *testing.T) {
	model := &subagentToolMockModel{
		responses: []*ModelResponse{
			{Items: []RunItem{{Type: RunItemMessage, Message: &MessageOutput{Text: "done fast"}}}},
		},
	}
	registry := NewSubAgentScheduler(SubAgentSchedulerConfig{
		Runner: NewRunnerWithModel(model),
		Agents: map[string]*Agent{"worker": {Name: "worker"}},
	})
	spawnTool := &subagentTool{registry: registry, defaultAgent: "worker"}
	waitTool := &subagentWaitTool{registry: registry}

	result, err := waitTool.Execute(context.Background(), json.RawMessage(`{}`), "")
	if err != nil {
		t.Fatal(err)
	}
	resp := decodeSubagentWaitResponse(t, result)
	if result.IsError || !resp.WaitComplete || !strings.Contains(resp.Note, "no active sub-agent tasks") {
		t.Fatalf("empty registry wait = %s", result.Content)
	}

	result, err = waitTool.Execute(context.Background(), json.RawMessage(`{"task_ids":["nope"]}`), "")
	if err != nil {
		t.Fatal(err)
	}
	if !result.IsError || !strings.Contains(result.Content, "not found") {
		t.Fatalf("unknown task id = %+v, want error", result)
	}

	result, err = waitTool.Execute(context.Background(), json.RawMessage(`{"wait_for":"bogus"}`), "")
	if err != nil {
		t.Fatal(err)
	}
	if !result.IsError || !strings.Contains(result.Content, "invalid wait_for") {
		t.Fatalf("invalid wait_for = %+v, want error", result)
	}

	// A task that finished before the wait call: its undelivered result is
	// returned immediately even though nothing is active anymore.
	taskID := spawnBackgroundSubagentTask(t, spawnTool, `{"message":"do it","mode":"background"}`)
	if _, err := registry.WaitForTask(context.Background(), taskID, 2000); err != nil {
		t.Fatal(err)
	}
	result, err = waitTool.Execute(context.Background(), json.RawMessage(`{}`), "")
	if err != nil {
		t.Fatal(err)
	}
	resp = decodeSubagentWaitResponse(t, result)
	if len(resp.Finished) != 1 || resp.Finished[0].TaskID != taskID || resp.Finished[0].Result != "done fast" {
		t.Fatalf("undelivered result wait = %s", result.Content)
	}
	if registry.HasPendingFinalJoinTasks() {
		t.Fatal("returned result should be marked delivered")
	}
}

// A task DAG must inherit the call-level agent_name. Regression test for a bug
// where executeBatch ignored params.AgentName and silently fell back to the
// configured default agent, so callers asking for a specialist got the default.
func TestSubagentToolBatchInheritsCallLevelAgentName(t *testing.T) {
	registry := NewSubAgentScheduler(SubAgentSchedulerConfig{
		Runner: NewRunnerWithModel(&subagentToolMockModel{}),
		Agents: map[string]*Agent{
			"worker":  {Name: "worker"},
			"explore": {Name: "explore"},
			"critic":  {Name: "critic"},
		},
	})
	tool := &subagentTool{registry: registry, defaultAgent: "worker"}

	result, err := tool.Execute(context.Background(), json.RawMessage(`{
		"agent_name": "explore",
		"mode": "background",
		"tasks": [
			{"key": "a", "message": "inherit call-level agent"},
			{"key": "b", "message": "task-level agent wins", "agent_name": "critic"}
		]
	}`), "")
	if err != nil {
		t.Fatal(err)
	}
	if result.IsError {
		t.Fatalf("batch spawn failed: %+v", result)
	}
	var resp struct {
		Tasks []struct {
			Key   string `json:"key"`
			Agent string `json:"agent"`
		} `json:"tasks"`
	}
	if err := json.Unmarshal([]byte(result.Content), &resp); err != nil {
		t.Fatalf("unmarshal %s: %v", result.Content, err)
	}
	got := map[string]string{}
	for _, task := range resp.Tasks {
		got[task.Key] = task.Agent
	}
	if got["a"] != "explore" {
		t.Errorf("task a agent = %q, want %q (call-level agent_name must be inherited)", got["a"], "explore")
	}
	if got["b"] != "critic" {
		t.Errorf("task b agent = %q, want %q (task-level agent_name must win)", got["b"], "critic")
	}
}

// Call-level tool_access must apply to every task in a DAG, and a task must
// never be able to widen it. Regression test for a silent privilege escalation
// where executeBatch ignored params.ToolAccess entirely.
func TestBatchDefaultsToolAccessResolution(t *testing.T) {
	for _, tc := range []struct {
		name      string
		callLevel string
		taskLevel string
		want      ToolAccessLevel
	}{
		{"call-level read-only is inherited", "read-only", "", ToolAccessLevelReadOnly},
		{"task-level read-only still applies", "", "read-only", ToolAccessLevelReadOnly},
		{"task cannot widen call-level read-only", "read-only", "full", ToolAccessLevelReadOnly},
		{"both full stays unrestricted", "full", "full", ""},
		{"unset stays unrestricted", "", "", ""},
	} {
		t.Run(tc.name, func(t *testing.T) {
			defaults := batchDefaults{toolAccess: tc.callLevel}
			got := defaults.toolAccessFor(subagentBatchTaskInput{ToolAccess: tc.taskLevel})
			if got != tc.want {
				t.Errorf("toolAccessFor(call=%q, task=%q) = %q, want %q", tc.callLevel, tc.taskLevel, got, tc.want)
			}
		})
	}
}

package browser

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"

	"github.com/gratefulagents/sdk/pkg/agentsdk"
	"github.com/gratefulagents/sdk/pkg/agentsdk/policy"
	"github.com/gratefulagents/sdk/pkg/agentsdk/sandbox"
	"github.com/gratefulagents/sdk/pkg/agentsdk/tools/internal/pathutil"
	"github.com/gratefulagents/sdk/pkg/agentsdk/tools/web"
)

// Tool provides headless browser automation for agents.
type Tool struct {
	readOnly                bool
	AllowPrivateNetworkURLs bool
	Executor                sandbox.Executor
	// ScreenshotDir is the host-managed directory used for implicit screenshot
	// outputs. Empty uses the operating system's temporary directory.
	ScreenshotDir string
}

type input struct {
	Action     string `json:"action"`
	URL        string `json:"url"`
	Selector   string `json:"selector"`
	Text       string `json:"text"`
	Script     string `json:"script"`
	OutputPath string `json:"output_path"`
	Width      int    `json:"width"`
	Height     int    `json:"height"`
}

const (
	defaultViewportWidth     = 1280
	defaultViewportHeight    = 720
	defaultScreenshotDirName = "agentsdk-browser"
	minViewportSize          = 100
	maxViewportSize          = 4096
)

// DefaultScreenshotDir returns the dedicated OS-temporary directory used for
// implicit screenshots when the host does not configure one.
func DefaultScreenshotDir() string {
	return filepath.Join(os.TempDir(), defaultScreenshotDirName)
}

func (t *Tool) Name() string { return "Browser" }

func (t *Tool) Description() string {
	if t.readOnly {
		return "Headless browser automation for read-only navigation and page text extraction. Screenshot capture requires workspace-write access."
	}
	return "Headless browser automation. Supports screenshot capture and navigation via headless Chromium. For full interactive automation (click, type, evaluate), configure the Playwright MCP server."
}

func (t *Tool) InputSchema() json.RawMessage {
	if t.readOnly {
		return json.RawMessage(`{
			"type": "object",
			"properties": {
				"action": {
					"type": "string",
					"enum": ["navigate", "get_text"],
					"description": "Browser action: navigate (load URL and return title), get_text (extract page text)"
				},
				"url": {
					"type": "string",
					"description": "URL to navigate to"
				},
				"width": {
					"type": "integer",
					"description": "Viewport width in pixels (default: 1280)"
				},
				"height": {
					"type": "integer",
					"description": "Viewport height in pixels (default: 720)"
				}
			},
			"required": ["action", "url"]
		}`)
	}
	return json.RawMessage(`{
		"type": "object",
		"properties": {
			"action": {
				"type": "string",
				"enum": ["screenshot", "navigate", "get_text"],
				"description": "Browser action: screenshot (capture page), navigate (load URL and return title), get_text (extract page text)"
			},
			"url": {
				"type": "string",
				"description": "URL to navigate to"
			},
			"output_path": {
				"type": "string",
				"description": "Workspace-relative file path for screenshot output. Omit to use the ephemeral screenshot directory."
			},
			"width": {
				"type": "integer",
				"description": "Viewport width in pixels (default: 1280)"
			},
			"height": {
				"type": "integer",
				"description": "Viewport height in pixels (default: 720)"
			}
		},
		"required": ["action", "url"]
	}`)
}

func (t *Tool) IsReadOnly() bool { return t.readOnly }

func (t *Tool) IsEnabled(_ *agentsdk.RunContext) bool { return true }

func (t *Tool) NeedsApproval() bool { return false }

func (t *Tool) TimeoutSeconds() int { return 0 }

func (t *Tool) ToolForAccess(level agentsdk.ToolAccessLevel) agentsdk.Tool {
	if agentsdk.NormalizeToolAccessLevel(level) == agentsdk.ToolAccessLevelReadOnly {
		return &Tool{
			readOnly:                true,
			AllowPrivateNetworkURLs: t.AllowPrivateNetworkURLs,
			Executor:                t.Executor,
			ScreenshotDir:           t.ScreenshotDir,
		}
	}
	return t
}

func (t *Tool) Execute(ctx context.Context, raw json.RawMessage, workDir string) (agentsdk.ToolResult, error) {
	var in input
	if err := json.Unmarshal(raw, &in); err != nil {
		return agentsdk.ToolResult{Content: fmt.Sprintf("Invalid input: %v", err), IsError: true}, nil
	}
	if in.URL == "" {
		return agentsdk.ToolResult{Content: "url is required", IsError: true}, nil
	}
	if !t.AllowPrivateNetworkURLs {
		return agentsdk.ToolResult{
			Content: "Browser public-only networking cannot safely contain redirects, DNS changes, or page subresources. Use WebFetch, or explicitly set AllowPrivateNetworkURLs=true to allow unrestricted/private browser networking.",
			IsError: true,
		}, nil
	}
	parsedURL, err := web.ValidateHTTPURL(ctx, in.URL, web.URLSecurityOptions{
		AllowPrivateNetworkURLs: t.AllowPrivateNetworkURLs,
	})
	if err != nil {
		return agentsdk.ToolResult{Content: err.Error(), IsError: true}, nil
	}
	in.URL = parsedURL.String()
	if t.readOnly && in.Action == "screenshot" {
		return agentsdk.ToolResult{Content: "screenshot requires workspace-write access", IsError: true}, nil
	}

	width, height, err := normalizeViewport(in.Width, in.Height)
	if err != nil {
		return agentsdk.ToolResult{Content: err.Error(), IsError: true}, nil
	}
	switch in.Action {
	case "screenshot", "navigate", "get_text":
	default:
		return agentsdk.ToolResult{
			Content: fmt.Sprintf("Unknown action %q. Supported: screenshot, navigate, get_text. For click/type/evaluate, use the Playwright MCP server.", in.Action),
			IsError: true,
		}, nil
	}

	chromeBin := findChromeBinary()
	if chromeBin == "" {
		return agentsdk.ToolResult{
			Content: "No Chromium/Chrome binary found. Install Chromium or configure the Playwright MCP server for browser automation.",
			IsError: true,
		}, nil
	}

	switch in.Action {
	case "screenshot":
		return t.screenshot(ctx, chromeBin, in, workDir, width, height)
	case "navigate":
		return t.navigate(ctx, chromeBin, in, workDir, width, height)
	default:
		return t.getText(ctx, chromeBin, in, workDir, width, height)
	}
}

func normalizeViewport(width, height int) (int, int, error) {
	if width == 0 {
		width = defaultViewportWidth
	}
	if height == 0 {
		height = defaultViewportHeight
	}
	if width < minViewportSize || width > maxViewportSize {
		return 0, 0, fmt.Errorf("width must be between %d and %d pixels", minViewportSize, maxViewportSize)
	}
	if height < minViewportSize || height > maxViewportSize {
		return 0, 0, fmt.Errorf("height must be between %d and %d pixels", minViewportSize, maxViewportSize)
	}
	return width, height, nil
}

func (t *Tool) screenshot(ctx context.Context, chromeBin string, in input, workDir string, width, height int) (agentsdk.ToolResult, error) {
	if strings.TrimSpace(workDir) == "" {
		return agentsdk.ToolResult{Content: "workDir is required for screenshots", IsError: true}, nil
	}
	outputRoot := workDir
	outPath := in.OutputPath
	implicitOutput := outPath == ""
	if implicitOutput {
		outputRoot = strings.TrimSpace(t.ScreenshotDir)
		if outputRoot == "" {
			outputRoot = DefaultScreenshotDir()
		}
		if err := os.MkdirAll(outputRoot, 0o700); err != nil {
			return agentsdk.ToolResult{Content: fmt.Sprintf("Failed to create ephemeral screenshot directory: %v", err), IsError: true}, nil
		}
		var err error
		outPath, err = pathutil.ResolveWorkspace(outputRoot, fmt.Sprintf("agentsdk-browser-screenshot-%d.png", time.Now().UnixNano()))
		if err != nil {
			return agentsdk.ToolResult{Content: fmt.Sprintf("Failed to resolve ephemeral screenshot path: %v", err), IsError: true}, nil
		}
	} else {
		var err error
		outPath, err = pathutil.ResolveWorkspace(workDir, outPath)
		if err != nil {
			return agentsdk.ToolResult{Content: fmt.Sprintf("Failed to resolve output path: %v", err), IsError: true}, nil
		}
		if err := pathutil.MkdirAllInWorkspace(workDir, filepath.Dir(outPath), 0o700); err != nil {
			return agentsdk.ToolResult{Content: fmt.Sprintf("Failed to create output directory: %v", err), IsError: true}, nil
		}
	}
	tmpDir, err := os.MkdirTemp("", "agentsdk-browser-*")
	if err != nil {
		return agentsdk.ToolResult{Content: fmt.Sprintf("Failed to create private screenshot directory: %v", err), IsError: true}, nil
	}
	defer os.RemoveAll(tmpDir)
	tmpPath := filepath.Join(tmpDir, "screenshot.png")

	ctx, cancel := context.WithTimeout(ctx, 30*time.Second)
	defer cancel()

	args := []string{
		"--headless",
		"--disable-gpu",
		"--disable-dev-shm-usage",
		"--no-sandbox",
		fmt.Sprintf("--screenshot=%s", tmpPath),
		fmt.Sprintf("--window-size=%d,%d", width, height),
		"--hide-scrollbars",
		in.URL,
	}

	execResult, err := t.executor().Run(ctx, sandbox.Request{
		Argv:           append([]string{chromeBin}, args...),
		WorkDir:        workDir,
		PermissionMode: policy.PermissionModeWorkspaceWrite,
		Timeout:        30 * time.Second,
		AllowNetwork:   true,
		WritablePaths:  []string{tmpDir},
	})
	if err != nil || execResult.ExitCode != 0 || execResult.TimedOut {
		return agentsdk.ToolResult{Content: fmt.Sprintf("Screenshot failed: %v\n%s", err, execResult.Output), IsError: true}, nil
	}
	data, err := os.ReadFile(tmpPath)
	if err != nil {
		return agentsdk.ToolResult{Content: fmt.Sprintf("Failed to read temporary screenshot file: %v", err), IsError: true}, nil
	}
	if err := pathutil.AtomicWriteFilePreservingModeInWorkspace(outputRoot, outPath, data, 0o600); err != nil {
		return agentsdk.ToolResult{Content: fmt.Sprintf("Failed to save screenshot: %v", err), IsError: true}, nil
	}

	displayPath := outPath
	if !implicitOutput {
		basePath, _ := pathutil.ResolveWorkspace(workDir, ".")
		if relPath, err := filepath.Rel(basePath, outPath); err == nil && relPath != "" {
			displayPath = relPath
		}
	}
	return agentsdk.ToolResult{Content: fmt.Sprintf("Screenshot saved to %s (%dx%d)", displayPath, width, height)}, nil
}

func (t *Tool) navigate(ctx context.Context, chromeBin string, in input, workDir string, width, height int) (agentsdk.ToolResult, error) {
	ctx, cancel := context.WithTimeout(ctx, 30*time.Second)
	defer cancel()

	args := []string{
		"--headless",
		"--disable-gpu",
		"--disable-dev-shm-usage",
		"--no-sandbox",
		"--dump-dom",
		fmt.Sprintf("--window-size=%d,%d", width, height),
		in.URL,
	}

	execResult, err := t.executor().Run(ctx, sandbox.Request{
		Argv:           append([]string{chromeBin}, args...),
		WorkDir:        workDir,
		PermissionMode: policy.PermissionModeReadOnly,
		Timeout:        30 * time.Second,
		AllowNetwork:   true,
	})
	if err != nil || execResult.ExitCode != 0 || execResult.TimedOut {
		return agentsdk.ToolResult{Content: fmt.Sprintf("Navigation failed: %v\n%s", err, execResult.Output), IsError: true}, nil
	}

	title := extractHTMLTitle(execResult.Output)
	if title == "" {
		title = "(no title)"
	}
	return agentsdk.ToolResult{Content: fmt.Sprintf("Navigated to %s\nTitle: %s", in.URL, title)}, nil
}

func (t *Tool) getText(ctx context.Context, chromeBin string, in input, workDir string, width, height int) (agentsdk.ToolResult, error) {
	ctx, cancel := context.WithTimeout(ctx, 30*time.Second)
	defer cancel()

	args := []string{
		"--headless",
		"--disable-gpu",
		"--disable-dev-shm-usage",
		"--no-sandbox",
		"--dump-dom",
		fmt.Sprintf("--window-size=%d,%d", width, height),
		in.URL,
	}

	execResult, err := t.executor().Run(ctx, sandbox.Request{
		Argv:           append([]string{chromeBin}, args...),
		WorkDir:        workDir,
		PermissionMode: policy.PermissionModeReadOnly,
		Timeout:        30 * time.Second,
		AllowNetwork:   true,
	})
	if err != nil || execResult.ExitCode != 0 || execResult.TimedOut {
		return agentsdk.ToolResult{Content: fmt.Sprintf("Failed to get page text: %v\n%s", err, execResult.Output), IsError: true}, nil
	}

	text := web.HTMLToText(execResult.Output)
	if len(text) > 50000 {
		text = text[:50000] + "\n\n--- Content truncated at 50000 characters ---"
	}
	return agentsdk.ToolResult{Content: text}, nil
}

func (t *Tool) executor() sandbox.Executor {
	if t.Executor != nil {
		return t.Executor
	}
	config := sandbox.ConfigFromEnv()
	config.Mode = "required"
	return sandbox.DefaultWithConfig(config)
}

func findChromeBinary() string {
	candidates := []string{
		"chromium",
		"chromium-browser",
		"google-chrome",
		"google-chrome-stable",
		"/usr/bin/chromium",
		"/usr/bin/chromium-browser",
		"/usr/bin/google-chrome",
		"/usr/bin/google-chrome-stable",
		"/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",
		"/Applications/Chromium.app/Contents/MacOS/Chromium",
	}
	for _, c := range candidates {
		if path, err := exec.LookPath(c); err == nil {
			return path
		}
	}
	return ""
}

func extractHTMLTitle(rawHTML string) string {
	lower := strings.ToLower(rawHTML)
	start := strings.Index(lower, "<title")
	if start < 0 {
		return ""
	}
	tagEnd := strings.Index(lower[start:], ">")
	if tagEnd < 0 {
		return ""
	}
	contentStart := start + tagEnd + 1
	end := strings.Index(lower[contentStart:], "</title>")
	if end < 0 {
		return ""
	}
	return strings.TrimSpace(rawHTML[contentStart : contentStart+end])
}

package browser

