func TestBuildEditDiffAppendAtEOFWithoutTrailingNewline(t *testing.T) {
	content := "a\nb"
	got := buildEditDiff(content, "b", "b\nc", false)
	want := strings.Join([]string{
		"@@ -1,2 +1,3 @@",
		" a",
		"-b",
		"+b",
		"+c",
	}, "\n")
