	maxPatchBytes          = 1 * 1024 * 1024
	maxPatchedFileBytes    = 5 * 1024 * 1024
	maxPatchFiles          = 128
	maxPatchAggregateBytes = 64 * 1024 * 1024
	maxPatchPathBytes      = 512
	maxPatchOutputBytes    = 8 * 1024
	maxPatchResultBytes    = 64 * 1024
	maxOpenAIPatchHunks    = 256
