type patchFile struct {
	oldPath        string
	newPath        string
	oldPathLiteral bool
	newPathLiteral bool
	sawOldHeader   bool
	sawNewHeader   bool
	sawRenameFrom  bool
	sawRenameTo    bool
	oldMode        *os.FileMode
	newMode        *os.FileMode
