				"type": "array",
				"items": { "type": "string" },
				"description": "Labels to apply to the issue (e.g. [\"meta-harness\", \"enhancement\"])."
			},
			"assignees": {
				"type": "array",
				"items": { "type": "string" },
				"description": "GitHub usernames to assign to the issue."
			},
