func (t *CreateIssueTool) IsReadOnly() bool { return false }
func (t *CreateIssueTool) IsEnabled(ctx *agentsdk.RunContext) bool {
	return agentsdk.MutatingToolEnabled(ctx, t.Name())
}
func (t *CreateIssueTool) NeedsApproval() bool { return false }
func (t *CreateIssueTool) TimeoutSeconds() int { return 0 }

type createIssueInput struct {
	Title     string   `json:"title"`
	Body      string   `json:"body"`
	Labels    []string `json:"labels"`
	Assignees []string `json:"assignees"`
	RepoPath  string   `json:"repo_path"`
}

type createIssueOutput struct {
	IssueURL string `json:"issue_url"`
	Status   string `json:"status"`
	Error    string `json:"error,omitempty"`
}

func (t *CreateIssueTool) Execute(ctx context.Context, input json.RawMessage, workDir string) (agentsdk.ToolResult, error) {
	var in createIssueInput
	if err := json.Unmarshal(input, &in); err != nil {
		return issueError("Invalid input: " + err.Error())
	}
	if strings.TrimSpace(in.Title) == "" {
		return issueError("title is required")
	}
	repoDir, err := resolveRepositoryWorkDir(workDir, in.RepoPath)
	if err != nil {
		return issueError("repo_path rejected: " + err.Error())
	}

	labels := normalizeLabels(in.Labels)
	runner := t.runner()
	if len(labels) > 0 {
		labelOut, err := runner.RunGH(ctx, repoDir, "label", "list", "--limit", "1000", "--json", "name")
		if err != nil {
			return issueError(fmt.Sprintf("gh label list failed: %s\n%s", err, labelOut))
		}
		var existing []struct {
			Name string `json:"name"`
		}
		if err := json.Unmarshal([]byte(labelOut), &existing); err != nil {
			return issueError("gh label list returned invalid output: " + err.Error())
		}
		existingLabels := make(map[string]struct{}, len(existing))
		for _, label := range existing {
			existingLabels[strings.ToLower(label.Name)] = struct{}{}
		}
		for _, label := range labels {
			if _, ok := existingLabels[strings.ToLower(label)]; ok {
				continue
			}
			createOut, err := runner.RunGH(ctx, repoDir, "label", "create", "--color", "BFD4F2", "--", label)
			if err != nil && !strings.Contains(strings.ToLower(createOut), "already exists") {
				return issueError(fmt.Sprintf("gh label create failed: %s\n%s", err, createOut))
			}
			existingLabels[strings.ToLower(label)] = struct{}{}
		}
	}

	args := []string{"issue", "create", "--title", in.Title}
	if in.Body != "" {
		args = append(args, "--body", in.Body)
	}
	for _, label := range labels {
		args = append(args, "--label", label)
	}
	for _, assignee := range in.Assignees {
		args = append(args, "--assignee", assignee)
	}

	out, err := runner.RunGH(ctx, repoDir, args...)
	if err != nil {
		return issueError(fmt.Sprintf("gh issue create failed: %s\n%s", err, out))
	}

	issueURL := strings.TrimSpace(out)
	if issueURL == "" {
		return issueError("gh issue create returned empty output")
	}
	if !strings.HasPrefix(issueURL, "https://") {
		return issueError("gh issue create returned unexpected output: " + issueURL)
	}
	t.recordIssue(ctx, issueURL)
	return issueSuccess(issueURL)
}

func normalizeLabels(labels []string) []string {
	seen := make(map[string]struct{}, len(labels))
	var normalized []string
	for _, label := range labels {
		label = strings.TrimSpace(label)
		if label == "" {
			continue
		}
		key := strings.ToLower(label)
		if _, ok := seen[key]; ok {
			continue
		}
		seen[key] = struct{}{}
		normalized = append(normalized, label)
	}
	return normalized
}

func (t *CreateIssueTool) runner() CommandRunner {
	if t.Runner != nil {
		return t.Runner
	}
	return execCommandRunner{}
}

func (t *CreateIssueTool) recordIssue(ctx context.Context, url string) {
	if t.Sink == nil {
		return
	}
	if err := t.Sink.RecordIssueURL(ctx, url); err != nil {
		log.Printf("WARN: failed to record issue URL: %v", err)
	}
}

func issueSuccess(issueURL string) (agentsdk.ToolResult, error) {
	return issueSuccessWithStatus(issueURL, "Issue created successfully")
}

func issueSuccessWithStatus(issueURL, status string) (agentsdk.ToolResult, error) {
	out := createIssueOutput{IssueURL: issueURL, Status: status}
	b, _ := json.Marshal(out)
	return agentsdk.ToolResult{Content: string(b)}, nil
}

func issueError(msg string) (agentsdk.ToolResult, error) {
	out := createIssueOutput{Status: "error", Error: msg}
	b, _ := json.Marshal(out)
	return agentsdk.ToolResult{Content: string(b), IsError: true}, nil
}

package git

import (
	"context"
	"encoding/json"
	"errors"
	"reflect"
	"strings"
	"testing"
)

func TestCreatePullRequestToolRunsGitHubFlowAndRecordsURL(t *testing.T) {
	runner := &fakeRunner{
		gitOut: map[string]string{
			"rev-parse --abbrev-ref HEAD": "agent/work\n",
			"status --porcelain":          " M changed.go\n?? new.go\n",
		},
		ghOut: map[string]string{
			"pr create --head agent/work --title Add feature --body  --base main --draft": "",
			"pr view --json url -q .url": "https://github.com/acme/repo/pull/7\n",
		},
	}
	sink := &fakeSink{}
	tool := NewCreatePullRequestTool(runner, sink)
	input := mustJSON(t, map[string]any{
		"title":       "Add feature",
		"base_branch": "main",
		"draft":       true,
	})

	result, err := tool.Execute(context.Background(), input, "/repo")
	if err != nil {
		t.Fatalf("Execute() error = %v", err)
	}
	if result.IsError {
		t.Fatalf("Execute() returned error result: %s", result.Content)
	}
	if sink.prURL != "https://github.com/acme/repo/pull/7" {
		t.Fatalf("recorded PR URL = %q", sink.prURL)
	}
	wantGit := []string{
		"rev-parse --abbrev-ref HEAD",
		"symbolic-ref --short refs/remotes/origin/HEAD",
		"status --porcelain",
