func TestManagerCloseTerminatesSessions(t *testing.T) {
	workspace := t.TempDir()
	if err := os.WriteFile(filepath.Join(workspace, "sample.txt"), []byte("hello\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	manager := NewManager(fakeConfig())
	if _, err := manager.Execute(context.Background(), workspace, Request{Operation: "hover", FilePath: "sample.txt", LanguageID: "plain", Line: 1, Character: 1}); err != nil {
		t.Fatalf("Execute() error = %v", err)
	}
	if err := manager.Close(); err != nil {
		t.Fatalf("Close() error = %v", err)
	}
	if _, err := manager.Execute(context.Background(), workspace, Request{Operation: "hover", FilePath: "sample.txt", LanguageID: "plain", Line: 1, Character: 1}); err == nil {
		t.Fatal("Execute() after Close() succeeded")
	}
}

type recordingExecutor struct {
	request sandbox.Request
}

func (e *recordingExecutor) Build(_ context.Context, request sandbox.Request) (*exec.Cmd, error) {
	e.request = request
	return nil, fmt.Errorf("stop after recording")
}

func (e *recordingExecutor) Run(context.Context, sandbox.Request) (sandbox.Result, error) {
	return sandbox.Result{}, fmt.Errorf("unexpected Run call")
}

func TestToolCloseIsTerminal(t *testing.T) {
	tool := NewTool(fakeConfig())
	if err := tool.Close(); err != nil {
		t.Fatal(err)
	}
	result, err := tool.Execute(context.Background(), json.RawMessage(`{"operation":"workspaceSymbol","query":"item"}`), t.TempDir())
	if err != nil {
		t.Fatal(err)
	}
	if !result.IsError || !strings.Contains(result.Content, "closed") {
		t.Fatalf("Execute() after Close = %#v", result)
	}
}

func TestZeroCommandPreservesReadOnlySandboxExecutor(t *testing.T) {
	executor := &recordingExecutor{}
	manager := NewManager(Config{Executor: executor})
	_, err := manager.Execute(context.Background(), t.TempDir(), Request{Operation: "workspaceSymbol", Query: "item"})
	if err == nil {
		t.Fatal("Execute() unexpectedly succeeded")
	}
	if len(executor.request.Argv) == 0 || executor.request.Argv[0] != "gopls" {
		t.Fatalf("sandbox argv = %v, want default gopls", executor.request.Argv)
	}
	if executor.request.PermissionMode != policy.PermissionModeReadOnly {
		t.Fatalf("sandbox permission mode = %q, want read-only", executor.request.PermissionMode)
	}
}

func fakeConfig() Config {
	return Config{
		Command:               os.Args[0],
		Args:                  []string{"-test.run=^TestFakeLSPServer$", "--"},
		Env:                   []string{"AGENTSDK_FAKE_LSP_SERVER=1", "AGENTSDK_FAKE_LSP_CONFIG=present"},
		LanguageID:            "plain",
		FilePatterns:          []string{"*.txt"},
		StartupTimeout:        time.Second,
		RequestTimeout:        time.Second,
		MaxMessageBytes:       64 << 10,
		MaxOutputBytes:        64 << 10,
		MaxStderrBytes:        64 << 10,
		MaxMessages:           20,
		AllowUnsafeUnconfined: true,
	}
}

func serveFakeLSP(in *os.File, out *os.File) error {
	if os.Getenv("AGENTSDK_FAKE_LSP_CONFIG") != "present" {
		return fmt.Errorf("configured environment was not passed to LSP server")
	}
	reader := bufio.NewReader(in)
	message, err := readRPCMessage(reader, 64<<10)
	if err != nil {
		return err
	}
	if message.Method != "initialize" {
		return fmt.Errorf("first method = %q, want initialize", message.Method)
	}
	var initialize struct {
		RootURI string `json:"rootUri"`
	}
	if err := json.Unmarshal(message.Params, &initialize); err != nil {
		return err
	}
	if err := writeRPCMessage(out, rpcMessage{JSONRPC: "2.0", ID: message.ID, Result: json.RawMessage(`{"capabilities":{"diagnosticProvider":true}}`)}); err != nil {
		return err
	}
	message, err = readRPCMessage(reader, 64<<10)
	if err != nil {
		return err
	}
	if message.Method != "initialized" {
		return fmt.Errorf("second method = %q, want initialized", message.Method)
	}

	for {
		message, err = readRPCMessage(reader, 64<<10)
		if err != nil {
			return nil
		}
		if message.Method == "textDocument/didOpen" {
			continue
		}
		if len(message.ID) == 0 {
			continue
		}
		response, err := fakeResponse(message, initialize.RootURI)
		if err != nil {
			response = rpcMessage{JSONRPC: "2.0", ID: message.ID, Error: &rpcError{Code: -32602, Message: err.Error()}}
		}
		if err := writeRPCMessage(out, response); err != nil {
			return err
		}
	}
}

func fakeResponse(message rpcMessage, rootURI string) (rpcMessage, error) {
	if message.Method == "textDocument/definition" {
		var params struct {
			Position struct {
				Line      int `json:"line"`
				Character int `json:"character"`
			} `json:"position"`
		}
		if err := json.Unmarshal(message.Params, &params); err != nil {
			return rpcMessage{}, err
		}
		if params.Position.Line != 0 || (params.Position.Character != 0 && params.Position.Character != 3) {
			return rpcMessage{}, fmt.Errorf("position = %#v, want one-based input mapped to a UTF-16 position", params.Position)
		}
	}

	inside := rootURI + "/sample.txt"
	outside := "file:///outside.txt"
	locationResult := json.RawMessage(fmt.Sprintf(`[{"uri":%q,"range":{"start":{"line":0,"character":0},"end":{"line":0,"character":1}}},{"uri":%q,"range":{"start":{"line":0,"character":0},"end":{"line":0,"character":1}}}]`, outside, inside))
	response := rpcMessage{JSONRPC: "2.0", ID: message.ID, Result: locationResult}
	switch message.Method {
	case "textDocument/definition", "textDocument/references", "textDocument/implementation", "textDocument/typeDefinition":
		return response, nil
	case "textDocument/hover":
		response.Result = json.RawMessage(`{"contents":{"kind":"markdown","value":"hover docs"},"range":{"start":{"line":0,"character":0},"end":{"line":0,"character":1}}}`)
		return response, nil
	case "textDocument/documentSymbol":
		response.Result = json.RawMessage(`[{"name":"Sample","kind":12,"detail":"detail","range":{"start":{"line":0,"character":0},"end":{"line":0,"character":6}},"selectionRange":{"start":{"line":0,"character":0},"end":{"line":0,"character":6}}}]`)
		return response, nil
	case "workspace/symbol":
		response.Result = json.RawMessage(fmt.Sprintf(`[{"name":"outside","kind":12,"location":{"uri":%q,"range":{"start":{"line":0,"character":0},"end":{"line":0,"character":1}}}},{"name":"inside","kind":12,"location":{"uri":%q,"range":{"start":{"line":0,"character":0},"end":{"line":0,"character":1}}}}]`, outside, inside))
		return response, nil
	case "textDocument/diagnostic":
		response.Result = json.RawMessage(`{"kind":"full","items":[{"range":{"start":{"line":0,"character":0},"end":{"line":0,"character":1}},"severity":2,"code":"fake","source":"fake","message":"diagnostic"}]}`)
		return response, nil
	default:
		return rpcMessage{}, fmt.Errorf("unexpected request method %q", message.Method)
	}
}

package lsp

import (
	"bufio"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"sync"
	"time"

	"github.com/gratefulagents/sdk/pkg/agentsdk/policy"
	"github.com/gratefulagents/sdk/pkg/agentsdk/sandbox"
)

const (
	defaultStartupTimeout = 10 * time.Second
	defaultRequestTimeout = 15 * time.Second
	defaultMaxMessageSize = 1 << 20
	defaultMaxOutputSize  = 1 << 20
	defaultMaxStderrSize  = 64 << 10
	defaultMaxMessages    = 16
)

// Config configures one stdio Language Server Protocol server. A host can
// create one Tool or Manager per server and select the appropriate language
// server with LanguageID and FilePatterns.
type Config struct {
	// ID uniquely identifies this server when Config.AdditionalServers or a
	// Discoverer supplies more than one candidate.
	ID      string
	Command string
	Args    []string
	Env     []string

	// Executor confines the language-server process. Registry/runtime wiring
	// always supplies the configured SDK command sandbox in read-only mode.
	// Standalone callers should also provide an enforcing executor.
	Executor sandbox.Executor
	// AllowUnsafeUnconfined permits direct execution without the SDK command
	// sandbox. It is intended only for explicitly trusted standalone test/host
	// processes; registry/runtime wiring never enables it.
	AllowUnsafeUnconfined bool

	LanguageID   string
	FilePatterns []string

	StartupTimeout  time.Duration
	RequestTimeout  time.Duration
	MaxMessageBytes int
	MaxOutputBytes  int
	MaxStderrBytes  int
	MaxMessages     int

	// AdditionalServers and Discoverer let one LSP tool route across language
	// servers. Discovery is host-owned; the SDK never hard-codes installations.
	AdditionalServers []Config
	Discoverer        ServerDiscoverer
}

// ServerDiscoverer returns trusted host-configured server candidates for a
// request. Returned commands are still launched through the read-only sandbox.
type ServerDiscoverer interface {
	DiscoverLSPServers(context.Context, string, Request) ([]Config, error)
}

func (c Config) normalized() Config {
	if strings.TrimSpace(c.Command) == "" {
		c.Command = "gopls"
		if c.LanguageID == "" {
			c.LanguageID = "go"
		}
		if len(c.FilePatterns) == 0 {
			c.FilePatterns = []string{"*.go"}
		}
	}
	if c.StartupTimeout <= 0 {
		c.StartupTimeout = defaultStartupTimeout
	}
	if c.RequestTimeout <= 0 {
		c.RequestTimeout = defaultRequestTimeout
	}
	if c.MaxMessageBytes <= 0 {
		c.MaxMessageBytes = defaultMaxMessageSize
	}
	if c.MaxOutputBytes <= 0 {
		c.MaxOutputBytes = defaultMaxOutputSize
	}
	if c.MaxStderrBytes <= 0 {
		c.MaxStderrBytes = defaultMaxStderrSize
	}
	if c.MaxMessages <= 0 {
		c.MaxMessages = defaultMaxMessages
	}
	return c
}

// Request is a read-only LSP operation. Line is one-based and Character is a
// one-based UTF-16 code-unit position, matching the stable result contract.
type Request struct {
	Operation  string
	FilePath   string
	LanguageID string
	Line       int
	Character  int
	Query      string
}

// Position is a one-based source position whose Character is measured in
// UTF-16 code units, so result positions can be passed back into requests.
type Position struct {
	Line      int `json:"line"`
	Character int `json:"character"`
}

// Range identifies a one-based source range in a workspace file.
type Range struct {
	Start Position `json:"start"`
	End   Position `json:"end"`
}

// Location is a workspace-confined source location.
type Location struct {
	FilePath string `json:"filePath"`
	Range    Range  `json:"range"`
}

// Hover is the stable representation of textDocument/hover output.
type Hover struct {
	Contents string `json:"contents"`
	Range    *Range `json:"range,omitempty"`
}

// Symbol is a workspace-confined document or workspace symbol.
type Symbol struct {
	Name           string    `json:"name"`
	Kind           int       `json:"kind"`
	Detail         string    `json:"detail,omitempty"`
	Range          *Range    `json:"range,omitempty"`
	Location       *Location `json:"location,omitempty"`
	SelectionRange *Range    `json:"selectionRange,omitempty"`
	Children       []Symbol  `json:"children,omitempty"`
}

// Diagnostic is a workspace-confined diagnostic returned by the language server.
type Diagnostic struct {
	FilePath string `json:"filePath"`
	Range    Range  `json:"range"`
	Severity int    `json:"severity,omitempty"`
	Code     string `json:"code,omitempty"`
	Source   string `json:"source,omitempty"`
	Message  string `json:"message"`
}

// Result is the stable structured output for all read-only LSP operations.
type Result struct {
	Operation   string       `json:"operation"`
	Locations   []Location   `json:"locations,omitempty"`
	Hover       *Hover       `json:"hover,omitempty"`
	Symbols     []Symbol     `json:"symbols,omitempty"`
	Diagnostics []Diagnostic `json:"diagnostics,omitempty"`
}

// Manager owns workspace-scoped stdio LSP sessions. Close terminates every
// child process and releases all pipes.
type Manager struct {
	config Config

	mu       sync.Mutex
	sessions map[string]*session
	closed   bool
}

// NewManager creates a generic stdio LSP manager. A zero Config deliberately
// retains the previous gopls behavior for callers migrating from Tool{}.
func NewManager(config Config) *Manager {
	return &Manager{config: config.normalized(), sessions: make(map[string]*session)}
}

// Execute performs one read-only LSP request in a session scoped to workDir.
func (m *Manager) Execute(ctx context.Context, workDir string, request Request) (Result, error) {
	workspace, err := canonicalWorkspace(workDir)
	if err != nil {
		return Result{}, err
	}
	operation, err := normalizeOperation(request.Operation)
	if err != nil {
		return Result{}, err
	}
	if err := matchesConfig(m.config, workspace, request); err != nil {
		return Result{}, err
	}
	if requiresDocument(operation) && request.FilePath == "" {
		return Result{}, fmt.Errorf("filePath is required for %s", request.Operation)
	}

	m.mu.Lock()
	if m.closed {
		m.mu.Unlock()
		return Result{}, errors.New("LSP manager is closed")
	}
	s := m.sessions[workspace]
	if s != nil && s.isClosed() {
		delete(m.sessions, workspace)
		s = nil
	}
	if s == nil {
		s, err = startSession(ctx, m.config, workspace)
		if err == nil {
			m.sessions[workspace] = s
		}
	}
	m.mu.Unlock()
	if err != nil {
		return Result{}, err
	}

	requestCtx, cancel := context.WithTimeout(ctx, m.config.RequestTimeout)
	defer cancel()
	return executeRequest(requestCtx, s, m.config, workspace, request)
}

// Close terminates all language server processes. It is safe to call more than once.
func (m *Manager) Close() error {
	m.mu.Lock()
	if m.closed {
		m.mu.Unlock()
		return nil
	}
	m.closed = true
	sessions := make([]*session, 0, len(m.sessions))
	for _, s := range m.sessions {
		sessions = append(sessions, s)
	}
	m.sessions = nil
	m.mu.Unlock()

	var errs []error
	for _, s := range sessions {
		if err := s.close(); err != nil {
			errs = append(errs, err)
		}
	}
	return errors.Join(errs...)
}

type boundedBuffer struct {
	mu     sync.Mutex
	buf    []byte
	limit  int
	capped bool
}

func newBoundedBuffer(limit int) *boundedBuffer { return &boundedBuffer{limit: limit} }

func (b *boundedBuffer) Write(p []byte) (int, error) {
	b.mu.Lock()
	defer b.mu.Unlock()
	if len(b.buf) >= b.limit {
		b.capped = true
		return len(p), nil
	}
	remaining := b.limit - len(b.buf)
	if len(p) > remaining {
		b.buf = append(b.buf, p[:remaining]...)
		b.capped = true
		return len(p), nil
	}
	b.buf = append(b.buf, p...)
	return len(p), nil
}

func (b *boundedBuffer) String() string {
	b.mu.Lock()
	defer b.mu.Unlock()
	out := string(b.buf)
	if b.capped {
		out += "\n[stderr truncated]"
	}
	return out
}

type inbound struct {
	message rpcMessage
	err     error
}

type openedDocument struct {
	text    string
	version int
}

type session struct {
	config    Config
	workspace string
	cmd       *exec.Cmd
	stdin     io.WriteCloser
	stdout    io.ReadCloser
	stderr    *boundedBuffer
	cancel    context.CancelFunc

	messages chan inbound
	waitDone chan struct{}
	waitMu   sync.Mutex
	waitErr  error

	operationMu        sync.Mutex
	requestMu          sync.Mutex
	writeMu            sync.Mutex
	nextID             int
	opened             map[string]openedDocument
	diagnosticsMu      sync.Mutex
	diagnostics        map[string][]Diagnostic
	diagnosticVersions map[string]int
	diagnosticWake     chan struct{}
	pullDiagnostics    bool
	stateMu            sync.Mutex
	closed             bool
	closeOnce          sync.Once
}

func startSession(ctx context.Context, config Config, workspace string) (*session, error) {
	startupCtx, cancelStartup := context.WithTimeout(ctx, config.StartupTimeout)
	defer cancelStartup()

	processCtx, cancelProcess := context.WithCancel(context.Background())
	var (
		cmd *exec.Cmd
		err error
	)
	if config.Executor != nil {
		env := make(map[string]string, len(config.Env))
		for _, assignment := range config.Env {
			name, value, ok := strings.Cut(assignment, "=")
			if ok && name != "" {
				env[name] = value
			}
		}
		argv := append([]string{config.Command}, config.Args...)
		cmd, err = config.Executor.Build(processCtx, sandbox.Request{
			Argv: argv, WorkDir: workspace,
			PermissionMode: policy.PermissionModeReadOnly,
			Env:            env,
		})
		if err != nil {
			cancelProcess()
			return nil, fmt.Errorf("building confined LSP server command %q: %w", config.Command, err)
		}
	} else {
		if !config.AllowUnsafeUnconfined {
			cancelProcess()
			return nil, fmt.Errorf("LSP server %q requires a read-only sandbox executor", config.Command)
		}
		cmd = exec.CommandContext(processCtx, config.Command, config.Args...)
		cmd.Dir = workspace
		cmd.Env = append(os.Environ(), config.Env...)
	}
	configureProcess(cmd)
	stdin, err := cmd.StdinPipe()
	if err != nil {
		cancelProcess()
		return nil, fmt.Errorf("creating LSP stdin: %w", err)
	}
	stdout, err := cmd.StdoutPipe()
	if err != nil {
		cancelProcess()
		return nil, fmt.Errorf("creating LSP stdout: %w", err)
	}
	stderr := newBoundedBuffer(config.MaxStderrBytes)
	cmd.Stderr = stderr
	if err := cmd.Start(); err != nil {
		cancelProcess()
		return nil, fmt.Errorf("starting LSP server %q: %w", config.Command, err)
	}

	s := &session{
		config:             config,
		workspace:          workspace,
		cmd:                cmd,
		stdin:              stdin,
		stdout:             stdout,
		stderr:             stderr,
		cancel:             cancelProcess,
		messages:           make(chan inbound, config.MaxMessages),
		opened:             make(map[string]openedDocument),
		diagnostics:        make(map[string][]Diagnostic),
		diagnosticVersions: make(map[string]int),
		diagnosticWake:     make(chan struct{}, 1),
		waitDone:           make(chan struct{}),
	}
	go s.readLoop()

	params := map[string]any{
		"processId": nil,
		"rootUri":   fileURI(workspace),
		"workspaceFolders": []map[string]string{{
			"uri":  fileURI(workspace),
			"name": filepath.Base(workspace),
		}},
		"capabilities": map[string]any{
			"general": map[string]any{"positionEncodings": []string{"utf-16"}},
			"textDocument": map[string]any{
				"documentSymbol": map[string]any{"hierarchicalDocumentSymbolSupport": true},
			},
		},
	}
	initializeResult, err := s.call(startupCtx, 1, "initialize", params)
	if err != nil {
		stderrText := s.stderr.String()
		_ = s.close()
		if stderrText != "" {
			return nil, fmt.Errorf("initializing LSP server: %w: %s", err, stderrText)
		}
		return nil, fmt.Errorf("initializing LSP server: %w", err)
	}
	var initialized struct {
		Capabilities struct {
			PositionEncoding   string          `json:"positionEncoding"`
			DiagnosticProvider json.RawMessage `json:"diagnosticProvider"`
		} `json:"capabilities"`
	}
	if err := json.Unmarshal(initializeResult, &initialized); err != nil {
		_ = s.close()
		return nil, fmt.Errorf("decoding LSP initialize result: %w", err)
	}
	if encoding := strings.ToLower(initialized.Capabilities.PositionEncoding); encoding != "" && encoding != "utf-16" {
		_ = s.close()
		return nil, fmt.Errorf("LSP server selected unsupported position encoding %q", encoding)
	}
	diagnosticCapability := strings.TrimSpace(string(initialized.Capabilities.DiagnosticProvider))
	s.pullDiagnostics = diagnosticCapability != "" && diagnosticCapability != "null" && diagnosticCapability != "false"
	if err := s.notify(startupCtx, "initialized", map[string]any{}); err != nil {
		_ = s.close()
		return nil, fmt.Errorf("sending LSP initialized notification: %w", err)
	}
	return s, nil
}

func (s *session) readLoop() {
	defer func() {
		s.stateMu.Lock()
		s.closed = true
		s.stateMu.Unlock()
		s.waitMu.Lock()
		s.waitErr = s.cmd.Wait()
		s.waitMu.Unlock()
		close(s.waitDone)
	}()

	reader := bufio.NewReader(s.stdout)
	for {
		message, err := readRPCMessage(reader, s.config.MaxMessageBytes)
		if err != nil {
			select {
			case s.messages <- inbound{err: err}:
			default:
			}
			s.terminate()
			return
		}
		if message.Method != "" {
			handleCtx, cancel := context.WithTimeout(context.Background(), s.config.RequestTimeout)
			_ = s.handleServerMessage(handleCtx, message)
			cancel()
			continue
		}
		select {
		case s.messages <- inbound{message: message}:
		default:
			s.terminate()
			return
		}
	}
}

func (s *session) isClosed() bool {
	s.stateMu.Lock()
	defer s.stateMu.Unlock()
	return s.closed
}

func (s *session) call(ctx context.Context, _ int, method string, params any) (json.RawMessage, error) {
	s.requestMu.Lock()
	defer s.requestMu.Unlock()
	if s.isClosed() {
		return nil, errors.New("LSP session is closed")
	}
	s.nextID++
	id := s.nextID
	if err := s.write(ctx, rpcOutboundMessage{JSONRPC: "2.0", ID: json.RawMessage(strconvAppendInt(id)), Method: method, Params: params}); err != nil {
		return nil, fmt.Errorf("writing LSP %s request: %w", method, err)
	}
	for count := 0; ; count++ {
		if count >= s.config.MaxMessages {
			s.terminate()
			return nil, fmt.Errorf("LSP server sent more than %d messages while handling %s", s.config.MaxMessages, method)
		}
		select {
		case incoming := <-s.messages:
			if incoming.err != nil {
				return nil, fmt.Errorf("reading LSP %s response: %w", method, incoming.err)
			}
			if incoming.message.Method != "" {
				if err := s.handleServerMessage(ctx, incoming.message); err != nil {
					return nil, err
				}
				continue
			}
			if !sameID(incoming.message.ID, id) {
				continue
			}
			if incoming.message.Error != nil {
				return nil, fmt.Errorf("LSP %s failed (%d): %s", method, incoming.message.Error.Code, incoming.message.Error.Message)
			}
			return incoming.message.Result, nil
		case <-ctx.Done():
			s.terminate()
			return nil, fmt.Errorf("LSP %s timed out: %w", method, ctx.Err())
		case <-s.waitDone:
			return nil, fmt.Errorf("LSP server exited while handling %s: %w", method, s.processErr())
		}
	}
}

func (s *session) handleServerMessage(ctx context.Context, message rpcMessage) error {
	if message.Method == "textDocument/publishDiagnostics" && len(message.ID) == 0 {
		var params struct {
			URI         string          `json:"uri"`
			Version     *int            `json:"version"`
			Diagnostics json.RawMessage `json:"diagnostics"`
		}
		if err := json.Unmarshal(message.Params, &params); err != nil {
			return fmt.Errorf("decoding published diagnostics: %w", err)
		}
		path, ok := confinedURI(s.workspace, params.URI)
		if !ok {
			return nil
		}
		diagnostics, err := parseDiagnostics(params.Diagnostics)
		if err != nil {
			return fmt.Errorf("decoding published diagnostics: %w", err)
		}
		for index := range diagnostics {
			diagnostics[index].FilePath = path
		}
		s.diagnosticsMu.Lock()
		s.diagnostics[path] = diagnostics
		if params.Version != nil {
			s.diagnosticVersions[path] = *params.Version
		} else {
			delete(s.diagnosticVersions, path)
		}
		s.diagnosticsMu.Unlock()
		select {
		case s.diagnosticWake <- struct{}{}:
		default:
		}
		return nil
	}
	if len(message.ID) == 0 {
		return nil
	}
	response := rpcOutboundMessage{JSONRPC: "2.0", ID: message.ID}
	switch message.Method {
	case "workspace/applyEdit":
		response.Result = map[string]any{"applied": false, "failureReason": "client is read-only"}
	case "workspace/configuration":
		response.Result = []any{}
	default:
		response.Error = &rpcError{Code: -32601, Message: "client does not support server request " + message.Method}
	}
	return s.write(ctx, response)
}

func (s *session) notify(ctx context.Context, method string, params any) error {
	s.requestMu.Lock()
	defer s.requestMu.Unlock()
	if s.isClosed() {
		return errors.New("LSP session is closed")
	}
	return s.write(ctx, rpcOutboundMessage{JSONRPC: "2.0", Method: method, Params: params})
}

func (s *session) write(ctx context.Context, message rpcOutboundMessage) error {
	s.writeMu.Lock()
	defer s.writeMu.Unlock()
	done := make(chan error, 1)
	go func() {
		done <- writeBoundedRPCMessage(s.stdin, message, s.config.MaxMessageBytes)
	}()
	select {
	case err := <-done:
		if err != nil {
			s.terminate()
		}
		return err
	case <-ctx.Done():
		s.terminate()
		<-done
		return ctx.Err()
	case <-s.waitDone:
		return fmt.Errorf("LSP server exited: %w", s.processErr())
	}
}

func (s *session) terminate() {
	s.closeOnce.Do(func() {
		s.stateMu.Lock()
		s.closed = true
		s.stateMu.Unlock()
		_ = s.stdin.Close()
		_ = s.stdout.Close()
		terminateProcess(s.cmd)
		s.cancel()
	})
}

func (s *session) close() error {
	s.terminate()
	select {
	case <-s.waitDone:
	case <-time.After(time.Second):
		return errors.New("timed out waiting for LSP server to exit")
	}
	return nil
}

func (s *session) processErr() error {
	s.waitMu.Lock()
	defer s.waitMu.Unlock()
	return s.waitErr
}

func strconvAppendInt(value int) []byte {
	return []byte(fmt.Sprintf("%d", value))
}

func sameID(raw json.RawMessage, want int) bool {
	var got int
	return json.Unmarshal(raw, &got) == nil && got == want
}

//go:build !unix

package lsp

import "os/exec"

func configureProcess(_ *exec.Cmd) {}

func terminateProcess(cmd *exec.Cmd) {
	if cmd != nil && cmd.Process != nil {
		_ = cmd.Process.Kill()
	}
}

//go:build unix

package lsp

import (
	"os/exec"
	"syscall"
)

func configureProcess(cmd *exec.Cmd) {
	if cmd.SysProcAttr == nil {
		cmd.SysProcAttr = &syscall.SysProcAttr{}
	}
	cmd.SysProcAttr.Setpgid = true
}

func terminateProcess(cmd *exec.Cmd) {
	if cmd == nil || cmd.Process == nil {
		return
	}
	if err := syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL); err != nil {
		_ = cmd.Process.Kill()
	}
}

package lsp

import (
	"bufio"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"strconv"
	"strings"
)

const maxLSPHeaderBytes = 8 << 10

type rpcMessage struct {
	JSONRPC string          `json:"jsonrpc"`
	ID      json.RawMessage `json:"id,omitempty"`
	Method  string          `json:"method,omitempty"`
	Params  json.RawMessage `json:"params,omitempty"`
	Result  json.RawMessage `json:"result,omitempty"`
	Error   *rpcError       `json:"error,omitempty"`
}

type rpcError struct {
	Code    int             `json:"code"`
	Message string          `json:"message"`
	Data    json.RawMessage `json:"data,omitempty"`
}

type rpcOutboundMessage struct {
	JSONRPC string          `json:"jsonrpc"`
	ID      json.RawMessage `json:"id,omitempty"`
	Method  string          `json:"method,omitempty"`
	Params  any             `json:"params,omitempty"`
	Result  any             `json:"result,omitempty"`
	Error   *rpcError       `json:"error,omitempty"`
}

func writeRPCMessage(w io.Writer, message any) error {
	return writeBoundedRPCMessage(w, message, 0)
}

func writeBoundedRPCMessage(w io.Writer, message any, maxBytes int) error {
	body, err := json.Marshal(message)
	if err != nil {
		return err
	}
	if maxBytes > 0 && len(body) > maxBytes {
		return fmt.Errorf("outbound LSP message exceeds %d bytes", maxBytes)
	}
	if _, err := fmt.Fprintf(w, "Content-Length: %d\r\n\r\n", len(body)); err != nil {
		return err
	}
	_, err = w.Write(body)
	return err
}

func readRPCMessage(r *bufio.Reader, maxMessageBytes int) (rpcMessage, error) {
	var contentLength = -1
	headerBytes := 0
	for {
		line, err := readLSPHeaderLine(r, maxLSPHeaderBytes-headerBytes)
		if err != nil {
			return rpcMessage{}, err
		}
		headerBytes += len(line)
		line = strings.TrimRight(line, "\r\n")
		if line == "" {
			break
		}
		name, value, ok := strings.Cut(line, ":")
		if !ok {
			return rpcMessage{}, fmt.Errorf("invalid LSP message header %q", line)
		}
		if strings.EqualFold(strings.TrimSpace(name), "Content-Length") {
			length, err := strconv.Atoi(strings.TrimSpace(value))
			if err != nil || length < 0 {
				return rpcMessage{}, fmt.Errorf("invalid LSP Content-Length %q", value)
			}
			contentLength = length
		}
	}
	if contentLength < 0 {
		return rpcMessage{}, fmt.Errorf("LSP message has no Content-Length")
	}
	if contentLength > maxMessageBytes {
		return rpcMessage{}, fmt.Errorf("LSP message exceeds %d bytes", maxMessageBytes)
	}
	body := make([]byte, contentLength)
	if _, err := io.ReadFull(r, body); err != nil {
		return rpcMessage{}, err
	}
	var message rpcMessage
	if err := json.Unmarshal(body, &message); err != nil {
		return rpcMessage{}, fmt.Errorf("decoding LSP message: %w", err)
	}
	return message, nil
}

func readLSPHeaderLine(r *bufio.Reader, limit int) (string, error) {
	var line []byte
	for {
		fragment, err := r.ReadSlice('\n')
		if len(line)+len(fragment) > limit {
			return "", fmt.Errorf("LSP message header exceeds %d bytes", maxLSPHeaderBytes)
		}
		line = append(line, fragment...)
		if err == nil {
			return string(line), nil
		}
		if errors.Is(err, bufio.ErrBufferFull) {
			continue
		}
		return "", err
	}
}

package lsp

import (
	"encoding/json"
	"fmt"
	"net/url"
	"path/filepath"
	"strings"

	"github.com/gratefulagents/sdk/pkg/agentsdk/tools/internal/pathutil"
)

type lspPosition struct {
	Line      int `json:"line"`
	Character int `json:"character"`
}

type lspRange struct {
	Start lspPosition `json:"start"`
	End   lspPosition `json:"end"`
}

type lspLocation struct {
	URI   string   `json:"uri"`
	Range lspRange `json:"range"`
}

type lspLocationLink struct {
	TargetURI            string   `json:"targetUri"`
	TargetRange          lspRange `json:"targetRange"`
	TargetSelectionRange lspRange `json:"targetSelectionRange"`
}

func parseResult(operation string, raw json.RawMessage, workspace string) (Result, error) {
	result := Result{Operation: operation}
	switch operation {
	case "definition", "references", "implementation", "typeDefinition":
		locations, err := parseLocations(raw, workspace)
		if err != nil {
			return Result{}, err
		}
		result.Locations = locations
	case "hover":
		hover, err := parseHover(raw)
		if err != nil {
			return Result{}, err
		}
		result.Hover = hover
	case "documentSymbol", "workspaceSymbol":
		symbols, err := parseSymbols(raw, workspace, operation == "workspaceSymbol")
		if err != nil {
			return Result{}, err
		}
		result.Symbols = symbols
	case "diagnostics":
		diagnostics, err := parseDiagnostics(raw)
		if err != nil {
			return Result{}, err
		}
		result.Diagnostics = diagnostics
	}
	return result, nil
}

func parseLocations(raw json.RawMessage, workspace string) ([]Location, error) {
	if string(raw) == "null" {
		return []Location{}, nil
	}
	var many []json.RawMessage
	if err := json.Unmarshal(raw, &many); err == nil {
		locations := make([]Location, 0, len(many))
		for _, item := range many {
			location, ok, err := parseLocation(item, workspace)
			if err != nil {
				return nil, err
			}
			if ok {
				locations = append(locations, location)
			}
		}
		return locations, nil
	}
	location, ok, err := parseLocation(raw, workspace)
	if err != nil {
		return nil, err
	}
	if !ok {
		return []Location{}, nil
	}
	return []Location{location}, nil
}

func parseLocation(raw json.RawMessage, workspace string) (Location, bool, error) {
	var direct lspLocation
	if err := json.Unmarshal(raw, &direct); err != nil {
		return Location{}, false, err
	}
	if direct.URI != "" {
		path, ok := confinedURI(workspace, direct.URI)
		if !ok {
			return Location{}, false, nil
		}
		return Location{FilePath: path, Range: stableRange(direct.Range)}, true, nil
	}
	var link lspLocationLink
	if err := json.Unmarshal(raw, &link); err != nil {
		return Location{}, false, err
	}
	path, ok := confinedURI(workspace, link.TargetURI)
	if !ok {
		return Location{}, false, nil
	}
	return Location{FilePath: path, Range: stableRange(link.TargetSelectionRange)}, true, nil
}

func confinedURI(workspace, rawURI string) (string, bool) {
	uri, err := url.Parse(rawURI)
	if err != nil || uri.Scheme != "file" || uri.Host != "" || uri.RawQuery != "" || uri.Fragment != "" {
		return "", false
	}
	path := filepath.FromSlash(uri.Path)
	if !filepath.IsAbs(path) {
		return "", false
	}
	resolved, err := pathutil.ResolveWorkspace(workspace, path)
	if err != nil {
		return "", false
	}
	return resolved, true
}

func stableRange(r lspRange) Range {
	return Range{
		Start: Position{Line: r.Start.Line + 1, Character: r.Start.Character + 1},
		End:   Position{Line: r.End.Line + 1, Character: r.End.Character + 1},
	}
}

func parseHover(raw json.RawMessage) (*Hover, error) {
	if string(raw) == "null" {
		return nil, nil
	}
	var value struct {
		Contents json.RawMessage `json:"contents"`
		Range    *lspRange       `json:"range"`
	}
	if err := json.Unmarshal(raw, &value); err != nil {
		return nil, err
	}
	contents, err := hoverContents(value.Contents)
	if err != nil {
		return nil, err
	}
	hover := &Hover{Contents: contents}
	if value.Range != nil {
		resultRange := stableRange(*value.Range)
		hover.Range = &resultRange
	}
	return hover, nil
}

func hoverContents(raw json.RawMessage) (string, error) {
	return hoverContentsDepth(raw, 0)
}

func hoverContentsDepth(raw json.RawMessage, depth int) (string, error) {
	if depth > 32 {
		return "", fmt.Errorf("LSP hover content nesting exceeds 32 levels")
	}
	var text string
	if err := json.Unmarshal(raw, &text); err == nil {
		return text, nil
	}
	var markup struct {
		Value string `json:"value"`
	}
	if err := json.Unmarshal(raw, &markup); err == nil && markup.Value != "" {
		return markup.Value, nil
	}
	var values []json.RawMessage
	if err := json.Unmarshal(raw, &values); err != nil {
		return "", err
	}
	parts := make([]string, 0, len(values))
	for _, value := range values {
		part, err := hoverContentsDepth(value, depth+1)
		if err != nil {
			return "", err
		}
		if part != "" {
			parts = append(parts, part)
		}
	}
	return strings.Join(parts, "\n\n"), nil
}

func parseSymbols(raw json.RawMessage, workspace string, workspaceSymbols bool) ([]Symbol, error) {
	nodes := 0
	return parseSymbolsDepth(raw, workspace, workspaceSymbols, 0, &nodes)
}

func parseSymbolsDepth(raw json.RawMessage, workspace string, workspaceSymbols bool, depth int, nodes *int) ([]Symbol, error) {
	if depth > 64 {
		return nil, fmt.Errorf("LSP symbol nesting exceeds 64 levels")
	}
	if string(raw) == "null" {
		return []Symbol{}, nil
	}
	var items []json.RawMessage
	if err := json.Unmarshal(raw, &items); err != nil {
		return nil, err
	}
	*nodes += len(items)
	if *nodes > 10000 {
		return nil, fmt.Errorf("LSP symbol result exceeds 10000 nodes")
	}
	symbols := make([]Symbol, 0, len(items))
	for _, item := range items {
		var information struct {
			Name     string          `json:"name"`
			Kind     int             `json:"kind"`
			Detail   string          `json:"containerName"`
			Location json.RawMessage `json:"location"`
		}
		if err := json.Unmarshal(item, &information); err != nil {
			return nil, err
		}
		if workspaceSymbols || len(information.Location) != 0 {
			if len(information.Location) == 0 {
				return nil, fmt.Errorf("symbol %q has no location", information.Name)
			}
			location, ok, err := parseLocation(information.Location, workspace)
			if err != nil {
				return nil, err
			}
			if !ok {
				continue
			}
			symbols = append(symbols, Symbol{Name: information.Name, Kind: information.Kind, Detail: information.Detail, Location: &location})
			continue
		}
		var document struct {
			Name           string            `json:"name"`
			Detail         string            `json:"detail"`
			Kind           int               `json:"kind"`
			Range          *lspRange         `json:"range"`
			SelectionRange *lspRange         `json:"selectionRange"`
			Children       []json.RawMessage `json:"children"`
		}
		if err := json.Unmarshal(item, &document); err != nil {
			return nil, err
		}
		if document.Range == nil || document.SelectionRange == nil {
			return nil, fmt.Errorf("document symbol %q has no range", document.Name)
		}
		symbolRange := stableRange(*document.Range)
		selectionRange := stableRange(*document.SelectionRange)
		symbol := Symbol{Name: document.Name, Kind: document.Kind, Detail: document.Detail, Range: &symbolRange, SelectionRange: &selectionRange}
		for _, child := range document.Children {
			children, err := parseSymbolsDepth(json.RawMessage("["+string(child)+"]"), workspace, false, depth+1, nodes)
			if err != nil {
				return nil, err
			}
			symbol.Children = append(symbol.Children, children...)
		}
		symbols = append(symbols, symbol)
	}
	return symbols, nil
}

func parseDiagnostics(raw json.RawMessage) ([]Diagnostic, error) {
	if string(raw) == "null" {
		return []Diagnostic{}, nil
	}
	items := raw
	if strings.HasPrefix(strings.TrimSpace(string(raw)), "{") {
		var report struct {
			Items json.RawMessage `json:"items"`
		}
		if err := json.Unmarshal(raw, &report); err != nil {
			return nil, err
		}
		if len(report.Items) != 0 {
			items = report.Items
		}
	}
	var values []struct {
		Range    lspRange        `json:"range"`
		Severity int             `json:"severity"`
		Code     json.RawMessage `json:"code"`
		Source   string          `json:"source"`
		Message  string          `json:"message"`
	}
	if err := json.Unmarshal(items, &values); err != nil {
		return nil, err
	}
	diagnostics := make([]Diagnostic, 0, len(values))
	for _, value := range values {
		diagnostic := Diagnostic{
			Range:    stableRange(value.Range),
			Severity: value.Severity,
			Source:   value.Source,
			Message:  value.Message,
		}
		if len(value.Code) != 0 && string(value.Code) != "null" {
			if err := json.Unmarshal(value.Code, &diagnostic.Code); err != nil {
				var number json.Number
				if err := json.Unmarshal(value.Code, &number); err == nil {
					diagnostic.Code = number.String()
				}
			}
		}
		diagnostics = append(diagnostics, diagnostic)
	}
	return diagnostics, nil
}

package memory

import (
	"context"
	"encoding/json"
	"fmt"
	"strings"

	"github.com/google/uuid"

	"github.com/gratefulagents/sdk/pkg/agentsdk"
	sdkmemory "github.com/gratefulagents/sdk/pkg/agentsdk/memory"
)

// Tool exposes the semantic memory system to agents.
type Tool struct {
	store     sdkmemory.Store
	namespace string
	sourceRun string
	repoURL   string
}

// New creates a memory tool scoped to a namespace and source run.
func New(store sdkmemory.Store, namespace, sourceRun, repoURL string) *Tool {
	return &Tool{store: store, namespace: namespace, sourceRun: sourceRun, repoURL: repoURL}
}

func (t *Tool) Name() string { return "Memory" }

func (t *Tool) Description() string {
	return "Store and retrieve persistent semantic memories across agent runs. Actions: store (save a memory), search (find similar memories), list (browse memories), delete (remove a memory)."
}

func (t *Tool) InputSchema() json.RawMessage {
	return json.RawMessage(`{
		"type": "object",
		"properties": {
			"action": {
				"type": "string",
				"enum": ["store", "search", "list", "delete"],
				"description": "The action to perform"
			},
			"content": {
				"type": "string",
				"description": "Memory content to store, or search query text"
			},
			"tags": {
				"type": "array",
				"items": {"type": "string"},
				"description": "Tags for categorization or filtering"
			},
			"id": {
				"type": "string",
				"description": "Memory ID (required for delete)"
			},
			"limit": {
				"type": "integer",
				"description": "Max results to return (default 10 for search, 50 for list)"
			}
		},
		"required": ["action"]
	}`)
}

func (t *Tool) IsReadOnly() bool { return false }

func (t *Tool) IsEnabled(ctx *agentsdk.RunContext) bool {
	return agentsdk.MutatingToolEnabled(ctx, t.Name())
}

func (t *Tool) NeedsApproval() bool { return false }

func (t *Tool) TimeoutSeconds() int { return 0 }

type input struct {
	Action  string   `json:"action"`
	Content string   `json:"content"`
	Tags    []string `json:"tags"`
	ID      string   `json:"id"`
	Limit   int      `json:"limit"`
}

func (t *Tool) Execute(ctx context.Context, raw json.RawMessage, _ string) (agentsdk.ToolResult, error) {
	var in input
	if err := json.Unmarshal(raw, &in); err != nil {
		return agentsdk.ToolResult{Content: fmt.Sprintf("Invalid input: %v", err), IsError: true}, nil
	}
	if t.store == nil {
		return agentsdk.ToolResult{Content: "memory store is not configured", IsError: true}, nil
	}

	switch in.Action {
	case "store":
		return t.executeStore(ctx, in)
	case "search":
		return t.executeSearch(ctx, in)
	case "list":
		return t.executeList(ctx, in)
	case "delete":
		return t.executeDelete(ctx, in)
	default:
		return agentsdk.ToolResult{Content: fmt.Sprintf("Unknown action: %q. Use store, search, list, or delete.", in.Action), IsError: true}, nil
	}
}

func (t *Tool) executeStore(ctx context.Context, in input) (agentsdk.ToolResult, error) {
	if in.Content == "" {
		return agentsdk.ToolResult{Content: "content is required for store action", IsError: true}, nil
	}

	metadata := json.RawMessage(`{}`)
	if t.repoURL != "" {
		// Marshalling a map[string]string with a single ASCII key cannot fail,
		// so we ignore the error and fall back to the empty-object literal.
		metadata, _ = json.Marshal(map[string]string{"repo": t.repoURL})
	}

	mem, err := t.store.Store(ctx, t.namespace, in.Content, in.Tags, t.sourceRun, metadata)
	if err != nil {
		return agentsdk.ToolResult{Content: fmt.Sprintf("Failed to store memory: %v", err), IsError: true}, nil
	}
	out, _ := json.Marshal(mem)
	return agentsdk.ToolResult{Content: string(out)}, nil
}

func (t *Tool) executeSearch(ctx context.Context, in input) (agentsdk.ToolResult, error) {
	if in.Content == "" {
		return agentsdk.ToolResult{Content: "content is required for search action (used as query)", IsError: true}, nil
	}

	memories, err := t.store.Search(ctx, t.namespace, in.Content, in.Tags, in.Limit)
	if err != nil {
		return agentsdk.ToolResult{Content: fmt.Sprintf("Failed to search memories: %v", err), IsError: true}, nil
	}
	if len(memories) == 0 {
		return agentsdk.ToolResult{Content: "No matching memories found."}, nil
	}
	out, _ := json.Marshal(memories)
	return agentsdk.ToolResult{Content: string(out)}, nil
}

func (t *Tool) executeList(ctx context.Context, in input) (agentsdk.ToolResult, error) {
	memories, err := t.store.List(ctx, t.namespace, in.Tags, in.Limit)
	if err != nil {
		return agentsdk.ToolResult{Content: fmt.Sprintf("Failed to list memories: %v", err), IsError: true}, nil
	}
	if len(memories) == 0 {
		return agentsdk.ToolResult{Content: "No memories found."}, nil
	}
	out, _ := json.Marshal(memories)
	return agentsdk.ToolResult{Content: string(out)}, nil
}

func (t *Tool) executeDelete(ctx context.Context, in input) (agentsdk.ToolResult, error) {
	if in.ID == "" {
		return agentsdk.ToolResult{Content: "id is required for delete action", IsError: true}, nil
	}

	id, err := uuid.Parse(strings.TrimSpace(in.ID))
	if err != nil {
		return agentsdk.ToolResult{Content: fmt.Sprintf("Invalid memory ID: %v", err), IsError: true}, nil
	}
	if err := t.store.Delete(ctx, t.namespace, id); err != nil {
		return agentsdk.ToolResult{Content: fmt.Sprintf("Failed to delete memory: %v", err), IsError: true}, nil
	}
	return agentsdk.ToolResult{Content: fmt.Sprintf("Memory %s deleted.", id)}, nil
}

package projectstatetools

import (
	"context"
	"encoding/json"
	"fmt"
	"strings"

	"github.com/gratefulagents/sdk/pkg/agentsdk"
	"github.com/gratefulagents/sdk/pkg/agentsdk/projectstate"
)

func Tools(store projectstate.Store, actor string) []agentsdk.Tool {
	if store == nil {
		return nil
	}
	base := baseTool{store: store, actor: strings.TrimSpace(actor)}
	return []agentsdk.Tool{
		&taskCreateTool{baseTool: base},
		&taskReadyTool{baseTool: base},
		&taskShowTool{baseTool: base},
		&taskUpdateTool{baseTool: base},
		&taskClaimTool{baseTool: base},
		&taskCloseTool{baseTool: base},
		&taskCommentTool{baseTool: base},
		&taskLinkTool{baseTool: base},
		&memoryRememberTool{baseTool: base},
		&memoryRecallTool{baseTool: base},
		&memoryListTool{baseTool: base},
		&memoryUpdateTool{baseTool: base},
		&memoryDeleteTool{baseTool: base},
		&memoryStatsTool{baseTool: base},
		&primeContextTool{baseTool: base},
	}
}

type baseTool struct {
	store projectstate.Store
	actor string
}

func (t baseTool) IsEnabled(*agentsdk.RunContext) bool { return t.store != nil }
func (t baseTool) NeedsApproval() bool                 { return false }
func (t baseTool) TimeoutSeconds() int                 { return 0 }

type taskCreateTool struct{ baseTool }

func (t *taskCreateTool) Name() string { return "task_create" }
func (t *taskCreateTool) Description() string {
	return "Create a durable project task in the filesystem event log. Use for work that should survive sessions and context compaction."
}
func (t *taskCreateTool) IsReadOnly() bool { return false }
func (t *taskCreateTool) InputSchema() json.RawMessage {
	return json.RawMessage(`{
		"type": "object",
		"properties": {
			"title": {"type": "string"},
			"description": {"type": "string"},
			"type": {"type": "string", "enum": ["task", "bug", "feature", "chore", "epic"]},
			"priority": {"type": "integer", "minimum": 0, "maximum": 4},
			"assignee": {"type": "string"},
			"depends_on": {"type": "array", "items": {"type": "string"}},
			"labels": {"type": "array", "items": {"type": "string"}}
		},
		"required": ["title"]
	}`)
}
func (t *taskCreateTool) Execute(ctx context.Context, raw json.RawMessage, _ string) (agentsdk.ToolResult, error) {
	var in struct {
		Title       string   `json:"title"`
		Description string   `json:"description"`
		Type        string   `json:"type"`
		Priority    *int     `json:"priority"`
		Assignee    string   `json:"assignee"`
		DependsOn   []string `json:"depends_on"`
		Labels      []string `json:"labels"`
	}
	if err := json.Unmarshal(raw, &in); err != nil {
		return errorResult("Invalid input: %v", err), nil
	}
	priority := 2
	if in.Priority != nil {
		priority = *in.Priority
	}
	task, err := t.store.CreateTask(ctx, projectstate.CreateTaskInput{
		Title:       in.Title,
		Description: in.Description,
		Type:        in.Type,
		Priority:    priority,
		Assignee:    in.Assignee,
		DependsOn:   in.DependsOn,
		Labels:      in.Labels,
	})
	return jsonToolResult(task, err), nil
}

type taskReadyTool struct{ baseTool }

func (t *taskReadyTool) Name() string { return "task_ready" }
func (t *taskReadyTool) Description() string {
	return "List ready durable project tasks: open tasks with no open blockers."
}
func (t *taskReadyTool) IsReadOnly() bool { return true }
func (t *taskReadyTool) InputSchema() json.RawMessage {
	return json.RawMessage(`{
		"type": "object",
		"properties": {
			"limit": {"type": "integer"},
			"assignee": {"type": "string"},
			"labels": {"type": "array", "items": {"type": "string"}},
			"include_assigned": {"type": "boolean"}
		}
	}`)
}
func (t *taskReadyTool) Execute(ctx context.Context, raw json.RawMessage, _ string) (agentsdk.ToolResult, error) {
	var in struct {
		Limit           int      `json:"limit"`
		Assignee        string   `json:"assignee"`
		Labels          []string `json:"labels"`
		IncludeAssigned bool     `json:"include_assigned"`
	}
	if err := json.Unmarshal(raw, &in); err != nil {
		return errorResult("Invalid input: %v", err), nil
	}
	tasks, err := t.store.ReadyTasks(ctx, projectstate.TaskFilter{Actor: t.actor, Assignee: in.Assignee, Labels: in.Labels, Limit: in.Limit, IncludeAssigned: in.IncludeAssigned})
	return jsonToolResult(tasks, err), nil
}

type taskShowTool struct{ baseTool }

func (t *taskShowTool) Name() string { return "task_show" }
func (t *taskShowTool) Description() string {
	return "Show one durable project task with comments and dependencies."
}
func (t *taskShowTool) IsReadOnly() bool { return true }
func (t *taskShowTool) InputSchema() json.RawMessage {
	return json.RawMessage(`{"type":"object","properties":{"id":{"type":"string"}},"required":["id"]}`)
}
func (t *taskShowTool) Execute(ctx context.Context, raw json.RawMessage, _ string) (agentsdk.ToolResult, error) {
	var in struct {
		ID string `json:"id"`
	}
	if err := json.Unmarshal(raw, &in); err != nil {
		return errorResult("Invalid input: %v", err), nil
	}
	task, err := t.store.GetTask(ctx, in.ID)
	return jsonToolResult(task, err), nil
