func WithAllowedMutatingTools(names ...string) RegistryOption {
	return func(r *Registry) {
		if r.allowMutating == nil {
			r.allowMutating = make(map[string]struct{}, len(names))
		}
		for _, name := range names {
			if name != "" {
				r.allowMutating[name] = struct{}{}
			}
		}
	}
}

// NewRegistry creates a registry with the default SDK tool set.
func NewRegistry(workDir string, opts ...RegistryOption) *Registry {
	r := &Registry{
		tools:           make(map[string]agentsdk.Tool),
		workDir:         workDir,
		permissionMode:  policy.PermissionModeWorkspaceWrite,
		gitRemoteWrites: policy.GitRemoteWritesEnabled,
	}
	for _, opt := range opts {
		opt(r)
	}
	config := sandbox.ConfigFromEnv()
	if r.commandSandboxConfig != nil {
		config = *r.commandSandboxConfig
	}
	config.WorkspaceRoot = workDir
	r.commandSandboxConfig = &config
	if r.lspTool == nil {
		r.lspTool = &lsp.Tool{}
	}
	r.lspTool.Config.Executor = r.bashExecutor()
	r.lspTool.Config.AllowUnsafeUnconfined = false

	var allTools []agentsdk.Tool
	if r.permissionMode == policy.PermissionModeWorkspaceWrite {
		allTools = []agentsdk.Tool{
			&search.ListFilesTool{},
			&search.ReadFileTool{},
			&search.GlobTool{},
			&search.GrepTool{},
			r.lspTool,
			&shell.WorkspaceWriteBashTool{BashTool: shell.BashTool{
				Executor:        r.bashExecutor(),
				GitRemoteWrites: r.gitRemoteWrites,
			}},
			&fs.WorkspaceWriteFileTool{},
			&fs.WorkspaceEditTool{},
			&fs.ApplyPatchTool{},
			&fs.MoveTool{},
			&fs.DeleteTool{},
		}
	} else {
		allTools = []agentsdk.Tool{
			&search.ListFilesTool{},
			&search.ReadFileTool{},
			&search.GlobTool{},
			&search.GrepTool{},
			r.lspTool,
		}
		if !r.permissionMode.AllowsWriteTools() {
			allTools = append(allTools, &shell.ReadOnlyBashTool{BashTool: shell.BashTool{
				Executor:        r.bashExecutor(),
				GitRemoteWrites: r.gitRemoteWrites,
			}})
		} else {
			allTools = append(allTools,
				&shell.BashTool{Executor: r.bashExecutor(), GitRemoteWrites: r.gitRemoteWrites},
				&fs.FileWriteTool{},
				&fs.FileEditTool{},
				&fs.ApplyPatchTool{},
				&fs.MoveTool{},
				&fs.DeleteTool{},
			)
		}
	}
	if !r.disableWeb {
		allTools = append(allTools, &web.FetchTool{AllowPrivateNetworkURLs: r.allowPrivateNetworkURLs})
	}
	if r.signals {
		allTools = append(allTools, &signal.AskUserQuestionTool{}, &signal.PresentPlanTool{})
	}
	for _, tool := range allTools {
		r.Register(tool)
	}
	if r.asyncShell && r.permissionMode.AllowsWriteTools() {
		manager := shell.NewAsyncManager(r.bashExecutor())
		r.asyncShellManager = manager
		r.Register(&shell.BashStartTool{Manager: manager, Mode: r.permissionMode, GitRemoteWrites: r.gitRemoteWrites})
		r.Register(&shell.BashPollTool{Manager: manager})
		r.Register(&shell.BashKillTool{Manager: manager})
	}
	if r.interactiveTerminal &&
		r.permissionMode == policy.PermissionModeDangerFullAccess &&
		r.gitRemoteWrites == policy.GitRemoteWritesEnabled {
		manager := shell.NewTerminalManager(r.bashExecutor())
		r.terminalManager = manager
		r.Register(&shell.TerminalTool{Manager: manager, Mode: r.permissionMode, GitRemoteWrites: r.gitRemoteWrites})
	}
	if r.thinkTool {
		r.Register(&signal.ThinkTool{})
	}
	// Chromium cannot bind public-only URL validation to redirects, DNS, and
	// subresources. Register Browser only behind the explicit unrestricted
	// networking opt-in; WebFetch remains the destination-confined default.
	effectiveBrowserScreenshotDir := ""
	if r.browser && r.allowPrivateNetworkURLs {
		effectiveBrowserScreenshotDir = r.browserScreenshotDir
		if effectiveBrowserScreenshotDir == "" {
			effectiveBrowserScreenshotDir = browser.DefaultScreenshotDir()
		}
		r.Register(&browser.Tool{
			AllowPrivateNetworkURLs: true,
			Executor:                r.bashExecutor(),
			ScreenshotDir:           effectiveBrowserScreenshotDir,
		})
	}
	if r.visionTool != nil {
		r.visionTool.AllowPrivateNetworkURLs = r.allowPrivateNetworkURLs
		if effectiveBrowserScreenshotDir != "" {
			r.visionTool.AllowedImageDirs = append(r.visionTool.AllowedImageDirs, effectiveBrowserScreenshotDir)
		}
		r.Register(r.visionTool)
	}
	if r.memoryTool != nil {
		r.Register(r.memoryTool)
	}
	if r.attachRepositoryTool != nil {
		r.Register(r.attachRepositoryTool)
	}
	if r.pullRequestTool != nil {
		r.Register(r.pullRequestTool)
	}
	if r.issueTool != nil {
		r.Register(r.issueTool)
	}
	return r
}

func (r *Registry) bashExecutor() sandbox.Executor {
	if r == nil || r.commandSandboxConfig == nil {
		return nil
	}
	return sandbox.DefaultWithConfig(*r.commandSandboxConfig)
}

// WorkDir returns the workspace root the registry was constructed with.
// Tools that need a workspace at construction time (rather than per-Execute)
// can read this value via the registry.
func (r *Registry) WorkDir() string {
	if r == nil {
		return ""
	}
	return r.workDir
}

// Register adds a tool to the registry.
func (r *Registry) Register(tool agentsdk.Tool) {
	if tool == nil {
		return
	}
	if r.gitRemoteWrites == policy.GitRemoteWritesDisabled && WritesGitRemote(tool) {
		return
	}
	if !r.permissionMode.AllowsWriteTools() {
		if adapter, ok := tool.(agentsdk.ToolAccessAdapter); ok {
			if adapted := adapter.ToolForAccess(agentsdk.ToolAccessLevelReadOnly); adapted != nil {
				tool = adapted
			}
		}
	}
	if !tool.IsReadOnly() && !isRegistryControlFlowTool(tool.Name()) && !r.permissionMode.AllowsWriteTools() {
		if _, ok := r.allowMutating[tool.Name()]; !ok {
			return
		}
	}
	r.tools[tool.Name()] = tool
}

// WritesGitRemote reports whether a tool declares or is known to have Git
// remote side effects.
func WritesGitRemote(tool agentsdk.Tool) bool {
	if capable, ok := tool.(agentsdk.GitRemoteWriteTool); ok && capable.WritesGitRemote() {
		return true
	}
	switch tool.Name() {
	case "git_push", "create_pull_request", "Terminal":
		return true
	}
	return false
}

func isRegistryControlFlowTool(name string) bool {
	switch name {
	case "finish", "save_plan", "get_plan", "RequestMCPBreakGlass":
		return true
	}
	return false
}

func (r *Registry) Get(name string) agentsdk.Tool {
	return r.tools[name]
}

func (r *Registry) Tools() []agentsdk.Tool {
	out := make([]agentsdk.Tool, 0, len(r.tools))
	for _, tool := range r.tools {
		out = append(out, tool)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Name() < out[j].Name() })
	return out
}

func (r *Registry) Closers() []io.Closer {
	if r == nil {
		return nil
	}
	var closers []io.Closer
	if r.lspTool != nil {
		closers = append(closers, r.lspTool)
	}
	if r.asyncShellManager != nil {
		closers = append(closers, r.asyncShellManager)
	}
	if r.terminalManager != nil {
		closers = append(closers, r.terminalManager)
	}
	return closers
}

func (r *Registry) Names() []string {
	names := make([]string, 0, len(r.tools))
	for name := range r.tools {
		names = append(names, name)
	}
	sort.Strings(names)
	return names
}

func (r *Registry) ToolSummaries() string {
	skipTools := map[string]bool{
		"bash": true, "read": true, "write": true, "edit": true,
		"list_directory": true,
	}
	type entry struct {
		name string
		desc string
	}
	var entries []entry
	for name, tool := range r.tools {
		if skipTools[strings.ToLower(name)] {
			continue
		}
		desc := tool.Description()
		if desc == "" {
			continue
		}
		if len(desc) > 200 {
			desc = desc[:197] + "..."
		}
		entries = append(entries, entry{name, desc})
	}
	sort.Slice(entries, func(i, j int) bool { return entries[i].name < entries[j].name })
	lines := make([]string, 0, len(entries))
	for _, e := range entries {
		lines = append(lines, "- **"+e.name+"**: "+e.desc)
	}
	return strings.Join(lines, "\n")
}

func (r *Registry) PermissionMode() policy.PermissionMode {
	if r == nil {
		return policy.PermissionModeWorkspaceWrite
	}
	return policy.NormalizePermissionMode(string(r.permissionMode))
}

