// commandBlocked applies the tool-layer command policy for the given mode.
// The destructive-command classifier is defense in depth for hosts without an
// enforcing OS sandbox: when the executor reports filesystem enforcement, the
// classifier is skipped and only git policy (remote-side effects the sandbox
// cannot contain) applies.
func (t *BashTool) commandBlocked(mode policy.PermissionMode, command string) (bool, string) {
	executor := t.Executor
	if executor == nil {
		executor = sandbox.Default()
	}
	fsEnforced := sandbox.ExecutorEnforcesFilesystem(executor, mode)
	if policy.NormalizeGitRemoteWrites(t.GitRemoteWrites) == policy.GitRemoteWritesDisabled && !fsEnforced {
		return true, "Command blocked: GitRemoteWrites=disabled requires an enforcing command sandbox " +
			"so Git credentials remain unavailable to subprocesses"
	}
	return isCommandBlockedForGitRemoteWrites(mode, t.GitRemoteWrites, command, fsEnforced)
}

// IsCommandBlockedForMode is the public entry point for the Bash tools'
// command guard. Restricted modes reject dynamic shell syntax that cannot be
// authorized statically, then apply destructive and remote-side-effect policy.
//
// NOTE on policy boundaries: this tool-layer denylist is defense in depth for
// hosts running commands without an enforcing OS sandbox. When the platform
// subprocess sandbox enforces the filesystem boundary (see
// pkg/agentsdk/sandbox), the bash tools skip the destructive classifier and
// apply only git policy, which guards remote-side effects the sandbox cannot
// contain.
func IsCommandBlockedForMode(mode policy.PermissionMode, command string) (bool, string) {
	return isCommandBlockedForMode(mode, command, false)
}

func isCommandBlockedForMode(mode policy.PermissionMode, command string, fsEnforced bool) (bool, string) {
	return isCommandBlockedForGitRemoteWrites(mode, policy.GitRemoteWritesEnabled, command, fsEnforced)
}

func isCommandBlockedForGitRemoteWrites(
	mode policy.PermissionMode,
	gitRemoteWrites policy.GitRemoteWrites,
	command string,
	fsEnforced bool,
) (bool, string) {
	readOnly, workspaceWrite := modeIsRestricted(mode)
	dynamicReason := restrictedShellSyntaxReason(command)

	// Dynamic shell syntax is safe for workspace-local effects when an OS
	// sandbox enforces the filesystem boundary. Keep it fail-closed in read-only
	// mode and on advisory/non-enforcing workspace-write hosts.
	if dynamicReason != "" && (readOnly || workspaceWrite && !fsEnforced) {
		return true, fmt.Sprintf("Command blocked in %s mode: %s — write the command with only literal arguments, or split it into separate Bash calls", mode, dynamicReason)
	}

	// Even with filesystem confinement, network side effects cannot be contained.
	// The protected-branch check below can only validate literal ref arguments,
	// so reject git pushes whose refs may be produced dynamically at runtime.
	if dynamicReason != "" && workspaceWrite {
		for _, argv := range gitInvocations(command) {
			if gitSubcommand(argv) == "push" {
				return true, fmt.Sprintf("Command blocked in %s mode: dynamic git push arguments cannot be authorized statically", mode)
			}
		}
	}

	// Universal destructive-command checks (apply when not danger-full-access
	// and no OS sandbox enforces the filesystem boundary).
	if (readOnly || workspaceWrite) && !fsEnforced {
		if blocked, reason := classifyDestructive(command); blocked {
			return true, fmt.Sprintf("Command blocked in %s mode: %s", mode, reason)
		}
	}

	// Git policy.
	for _, argv := range gitInvocations(command) {
		remoteWritesDisabled := policy.NormalizeGitRemoteWrites(gitRemoteWrites) == policy.GitRemoteWritesDisabled
		if remoteWritesDisabled && (gitSubcommand(argv) == "push" || gitAliasExpandsToPush(argv)) {
			return true, "Command blocked: git push is disabled by the GitRemoteWrites policy"
		}
		if readOnly {
			if blocked, sub := isReadOnlyGitDenied(argv); blocked {
				return true, fmt.Sprintf("Command blocked in %s mode: git %s is not allowed%s", mode, sub, gitDenialHint(sub))
			}
		}
		if workspaceWrite {
			if blocked, sub := isWorkspaceWriteGitDenied(argv); blocked {
				return true, fmt.Sprintf("Command blocked in %s mode: git %s is not allowed%s", mode, sub, gitDenialHint(sub))
			}
		}
		if (readOnly || workspaceWrite) && pushTargetsProtectedBranch(argv) {
			return true, fmt.Sprintf("Command blocked in %s mode: push to main/master is not allowed", mode)
		}
	}

	// GitHub CLI policy: restricted modes may not shell out to gh at all.
	// GitHub side effects (pushes, PRs, reviews, issues) must go through the
	// built-in GitHub tools, which enforce guardrails — protected-branch push
	// refusal, artifact recording, required commit trailers — that raw gh
	// invocations would bypass.
	if readOnly || workspaceWrite {
		if len(ghInvocations(command)) > 0 {
			return true, fmt.Sprintf("Command blocked in %s mode: the gh CLI is not allowed; use the built-in GitHub tools (create_pull_request, get_pull_request, list_review_threads, submit_pull_request_review, create_github_issue, ...) instead", mode)
		}
	}

	return false, ""
}

func gitDenialHint(sub string) string {
	if sub == "remote" {
		return " — remote configuration is platform-managed; use git_status or the built-in git/GitHub tools instead"
	}
	return " — this session cannot mutate the repository"
}

// IsPushToProtectedBranch detects git push commands that target main or
// master, including via shell wrappers and command substitution.
func restrictedShellSyntaxReason(command string) string {
	inSingle := false
	inDouble := false
	escaped := false
	for i := 0; i < len(command); i++ {
		c := command[i]
		if escaped {
			escaped = false
			continue
		}
		if c == '\\' && !inSingle {
			escaped = true
			continue
		}
		if c == '\'' && !inDouble {
			inSingle = !inSingle
			continue
		}
		if inSingle {
			continue
		}
		if c == '"' {
			inDouble = !inDouble
			continue
		}
		if c == '`' {
			return "backtick substitution cannot be authorized statically"
		}
		if c == '$' && i+1 < len(command) {
			next := command[i+1]
			if next == '\'' {
				return "ANSI-C shell quoting cannot be authorized statically"
			}
			if next == '(' || next == '{' || next == '_' || next >= 'A' && next <= 'Z' || next >= 'a' && next <= 'z' || next >= '0' && next <= '9' || strings.ContainsRune("@*#?$!-", rune(next)) {
				return "shell substitution cannot be authorized statically"
			}
		}
		if !inDouble && i+1 < len(command) && (c == '<' || c == '>') && command[i+1] == '(' {
			return "process substitution cannot be authorized statically"
		}
		if !inDouble && c == '<' && i+1 < len(command) && command[i+1] == '<' {
			return "heredocs and here-strings cannot be authorized statically"
		}
	}

	for _, pl := range parseStatements(tokenize(command)) {
		for _, cmd := range pl.commands {
			if reason := restrictedAssignmentReason(cmd.argv); reason != "" {
				return reason
			}
			argv := stripPrefixWrappers(cmd.argv)
			if len(argv) == 0 {
				continue
			}
			if strings.ToLower(basename(argv[0])) == "builtin" {
				argv = argv[1:]
				if len(argv) == 0 {
					continue
				}
			}
			head := strings.ToLower(basename(argv[0]))
			switch head {
			case "eval", "source", ".", "alias":
				return head + " cannot be authorized statically"
			case "function":
				return "function definitions cannot be authorized statically"
			}
			if strings.HasSuffix(argv[0], "()") {
				return "function definitions cannot be authorized statically"
			}
		}
	}
	return ""
}

func restrictedAssignmentReason(argv []string) string {
	for _, word := range argv {
		if !isShellAssignmentWord(word) {
			continue
		}
		name, _, _ := strings.Cut(word, "=")
		return fmt.Sprintf("shell assignment %s cannot be authorized statically", name)
	}
	return ""
}

func IsPushToProtectedBranch(cmd string) bool {
	for _, argv := range gitInvocations(cmd) {
		if pushTargetsProtectedBranch(argv) {
			return true
		}
	}
	return false
}

func isProtectedRef(ref string) bool {
	ref = strings.TrimPrefix(ref, "+")
	if ref == "main" || ref == "master" || ref == "refs/heads/main" || ref == "refs/heads/master" {
		return true
	}
	if strings.HasPrefix(ref, "main:") || strings.HasPrefix(ref, "master:") {
		return true
	}
	return strings.HasSuffix(ref, ":main") ||
		strings.HasSuffix(ref, ":master") ||
		strings.HasSuffix(ref, ":refs/heads/main") ||
		strings.HasSuffix(ref, ":refs/heads/master")
}

