		t.Fatal("read-only Bash request enabled network")
	}
}

type captureExecutor struct {
	request  sandbox.Request
	enforces bool
}

func (e *captureExecutor) Build(_ context.Context, req sandbox.Request) (*exec.Cmd, error) {
	e.request = req
	return exec.Command("true"), nil
}

func (e *captureExecutor) Run(ctx context.Context, req sandbox.Request) (sandbox.Result, error) {
	e.request = req
	return sandbox.Result{}, nil
}

func (e *captureExecutor) EnforcesFilesystem(policy.PermissionMode) bool { return e.enforces }

func TestBashStartWorkspaceWriteEnablesNetwork(t *testing.T) {
	t.Parallel()

	executor := &captureExecutor{enforces: true}
	manager := NewAsyncManager(executor)
	t.Cleanup(func() { _ = manager.Close() })
	if _, err := manager.start(context.Background(), asyncStartInput{Command: "true"}, t.TempDir(), policy.PermissionModeWorkspaceWrite); err != nil {
		t.Fatal(err)
	}
	if !executor.request.AllowNetwork {
		t.Fatal("workspace-write BashStart request did not enable network")
	}
}

func TestCommandBlockedSkipsDestructiveClassifierWhenSandboxEnforces(t *testing.T) {
	t.Parallel()

	// With an enforcing OS sandbox the filesystem classifier is redundant and
	// must not block; git policy still applies because the sandbox cannot
	// contain remote-side effects.
	if blocked, reason := isCommandBlockedForMode(policy.PermissionModeWorkspaceWrite, "rm -rf /", true); blocked {
		t.Fatalf("destructive classifier ran despite enforcing sandbox: %q", reason)
	}
	if blocked, _ := isCommandBlockedForMode(policy.PermissionModeWorkspaceWrite, "git push origin main", true); !blocked {
		t.Fatal("git protected-branch policy must apply even under an enforcing sandbox")
	}
	if blocked, _ := isCommandBlockedForMode(policy.PermissionModeReadOnly, "git commit -m x", true); !blocked {
		t.Fatal("read-only git policy must apply even under an enforcing sandbox")
	}
}

package shell

import (
	"io"
	"os/exec"
	"sync"
)

const boundedOmissionMarker = "\n[output truncated: middle omitted]\n"

// boundedWriter accumulates output up to cap bytes. Once the cap is exceeded it
// keeps the beginning and the latest tail of the stream while continuing to
// accept writes. It always reports n == len(p), so verbose commands are not
// killed just because the tool response reached its display cap.
type boundedWriter struct {
	mu     sync.Mutex
	buf    []byte
	head   []byte
	tail   []byte
	cap    int
	total  int64
	capped bool
}

func newBoundedWriter(cap int) *boundedWriter {
	return &boundedWriter{cap: cap}
}

func (b *boundedWriter) Write(p []byte) (int, error) {
	b.mu.Lock()
	defer b.mu.Unlock()

	if b.cap <= 0 {
		b.total += int64(len(p))
		b.capped = true
		return len(p), nil
	}
	b.total += int64(len(p))
	if !b.capped && len(b.buf)+len(p) <= b.cap {
		b.buf = append(b.buf, p...)
		return len(p), nil
	}
	if !b.capped {
		combined := make([]byte, 0, len(b.buf)+len(p))
		combined = append(combined, b.buf...)
		combined = append(combined, p...)
		b.buf = nil
		b.capped = true
		b.head, b.tail = splitHeadTail(combined, b.cap)
		return len(p), nil
	}
	_, tailLimit := boundedHeadTailLimits(b.cap)
	b.tail = appendTail(b.tail, p, tailLimit)
	return len(p), nil
}

func (b *boundedWriter) Bytes() []byte {
	b.mu.Lock()
	defer b.mu.Unlock()
	if b.capped {
		out := make([]byte, 0, len(b.head)+len(boundedOmissionMarker)+len(b.tail))
		out = append(out, b.head...)
		out = append(out, boundedOmissionMarker...)
		out = append(out, b.tail...)
		return out
	}
	out := make([]byte, len(b.buf))
	copy(out, b.buf)
	return out
}

func (b *boundedWriter) Capped() bool {
	b.mu.Lock()
	defer b.mu.Unlock()
	return b.capped
}

func (b *boundedWriter) TotalBytes() int64 {
	b.mu.Lock()
	defer b.mu.Unlock()
	return b.total
}

// TailSince returns the bytes written after the given absolute stream offset,
// the new offset (current total), and whether part of the requested range was
// already discarded by the cap. Used for incremental polling so repeated polls
// do not re-send output the model has already seen.
func (b *boundedWriter) TailSince(offset int64) (out []byte, newOffset int64, gap bool) {
	b.mu.Lock()
	defer b.mu.Unlock()
	if offset < 0 {
		offset = 0
	}
	if offset >= b.total {
		return nil, b.total, false
	}
	newBytes := b.total - offset
	if !b.capped {
		start := int64(len(b.buf)) - newBytes
		if start < 0 {
			start = 0
		}
		return append([]byte(nil), b.buf[start:]...), b.total, false
	}
	tail := b.tail
	if newBytes < int64(len(tail)) {
		return append([]byte(nil), tail[int64(len(tail))-newBytes:]...), b.total, false
	}
	// More new bytes arrived than the cap retains: return what we have and
	// flag the gap.
	return append([]byte(nil), tail...), b.total, true
}

func boundedHeadTailLimits(cap int) (int, int) {
	if cap <= 1 {
		return cap, 0
	}
	head := cap / 2
	return head, cap - head
}

func splitHeadTail(data []byte, cap int) ([]byte, []byte) {
	headLimit, tailLimit := boundedHeadTailLimits(cap)
	head := append([]byte(nil), data[:minInt(len(data), headLimit)]...)
	var tail []byte
	if tailLimit > 0 {
		start := len(data) - tailLimit
		if start < 0 {
			start = 0
		}
		tail = append([]byte(nil), data[start:]...)
	}
	return head, tail
}

func appendTail(tail, p []byte, limit int) []byte {
	if limit <= 0 {
		return nil
	}
	tail = append(tail, p...)
	if len(tail) <= limit {
		return tail
	}
	out := make([]byte, limit)
	copy(out, tail[len(tail)-limit:])
	return out
}

func minInt(a, b int) int {
	if a < b {
		return a
	}
	return b
}

// attachBoundedPipes wires cmd's stdout and stderr to the same bounded
// writer. It must be called before Start.
func attachBoundedPipes(cmd *exec.Cmd, w io.Writer) {
	cmd.Stdout = w
	cmd.Stderr = w
}

package shell

import (
	"fmt"
	"strings"

	"github.com/gratefulagents/sdk/pkg/agentsdk/policy"
)

// command represents one program invocation inside a pipeline (no |/;/&& yet).
type command struct {
	argv       []string
	hasCmdSub  bool
	headCmdSub bool // the head token (argv[0]) is produced by a substitution
	cmdSubs    []string
	redirects  []redirect
}

type redirect struct {
	op     string // ">", ">>", "<", "<<", "<<<"
	target string
}

// pipeline is one or more commands joined by `|`.
type pipeline struct {
	commands []command
}

// parseStatements groups tokens into pipelines separated by ;, &&, ||, &.
func parseStatements(tokens []token) []pipeline {
	var pipelines []pipeline
	var pl pipeline
	var cmd command
	flushCmd := func() {
		if len(cmd.argv) > 0 || cmd.hasCmdSub || len(cmd.redirects) > 0 {
			pl.commands = append(pl.commands, cmd)
		}
		cmd = command{}
	}
	flushPipeline := func() {
		flushCmd()
		if len(pl.commands) > 0 {
			pipelines = append(pipelines, pl)
		}
		pl = pipeline{}
	}
	i := 0
	for i < len(tokens) {
		t := tokens[i]
		if !t.IsOperator {
			if len(cmd.argv) == 0 && t.HasCmdSub {
				cmd.headCmdSub = true
			}
			cmd.argv = append(cmd.argv, t.Value)
			if t.HasCmdSub {
				cmd.hasCmdSub = true
				cmd.cmdSubs = append(cmd.cmdSubs, t.CmdSubBodies...)
			}
			i++
			continue
		}
		switch t.Value {
		case ";", "&&", "||", "&", "\n":
			flushPipeline()
		case "|":
			flushCmd()
		case ">", ">>", "<", "<<", "<<<":
			target := ""
			if i+1 < len(tokens) && !tokens[i+1].IsOperator {
				target = tokens[i+1].Value
				i++
			}
			cmd.redirects = append(cmd.redirects, redirect{op: t.Value, target: target})
		}
		i++
	}
	flushPipeline()
	return pipelines
}

// ClassifyDestructiveCommand reports whether cmdLine is judged destructive by
// the shared denylist classifier, and why. It is the exported entry point for
// callers outside the bash tools (e.g. the built-in destructive-command
// guardrail) that need tokenizer-backed classification without the per-mode
// git policy applied by IsCommandBlockedForMode.
func ClassifyDestructiveCommand(cmdLine string) (bool, string) {
	return classifyDestructive(cmdLine)
}

// classifyDestructive returns (true, reason) if the command is judged
// destructive by any of our heuristics. It always operates on decoded tokens
// produced by the tokenizer, so quoting/escaping/$IFS bypasses are normalized
// before matching.
func classifyDestructive(cmdLine string) (bool, string) {
	tokens := tokenize(cmdLine)
	for _, pl := range parseStatements(tokens) {
		if blocked, reason := classifyPipeline(pl); blocked {
			return true, reason
		}
	}
	return false, ""
}

func classifyPipeline(pl pipeline) (bool, string) {
	for idx, cmd := range pl.commands {
		if blocked, reason := classifyCommand(cmd); blocked {
			return true, reason
		}
		// Pipe target receiving stdin for a shell interpreter (curl|sh).
		if idx > 0 && len(cmd.argv) > 0 && isShellInterpreter(cmd.argv[0]) {
			return true, fmt.Sprintf("piping into %q is not allowed", cmd.argv[0])
		}
	}
	return false, ""
}

func classifyCommand(cmd command) (bool, string) {
	for _, sub := range cmd.cmdSubs {
		if blocked, reason := classifyDestructive(sub); blocked {
			return true, "command substitution: " + reason
		}
	}
	for _, rd := range cmd.redirects {
		if isForbiddenWritePath(rd.target) && (rd.op == ">" || rd.op == ">>") {
			return true, fmt.Sprintf("redirect to protected path %q is not allowed", rd.target)
		}
	}
	if len(cmd.argv) == 0 {
		return false, ""
	}
	// Strip transparent prefixes: sudo, doas, env (when no var=val args),
	// command, exec. They do not change the destructiveness of the inner
	// invocation.
	argv := stripPrefixWrappers(cmd.argv)
	if len(argv) == 0 {
		return false, ""
	}
	cmd.argv = argv
	head := cmd.argv[0]
	base := strings.ToLower(basename(head))

	// Command substitution can inject flags/targets that the static destructive
	// checks below cannot see (e.g. `rm $(echo -rf) /` expands to `rm -rf /`).
	// Block it only when the head is a statically-checked destructive binary, a
	// shell interpreter, or itself produced by a substitution (so the command is
	// unknowable). Benign uses like `wc -l $(find ...)` are allowed; destructive
	// commands inside the substitution are still caught by the cmdSubs recursion
	// above.
	if cmd.hasCmdSub {
		if base == "" || cmd.headCmdSub || isCmdSubEvasionRisk(base) {
			return true, "command substitution in a file-mutating command is not allowed"
		}
	}

	// Recurse into shells / eval invoked with -c "...".
	if base == "eval" {
		joined := strings.Join(cmd.argv[1:], " ")
		if blocked, reason := classifyDestructive(joined); blocked {
			return true, "eval: " + reason
		}
		return false, ""
	}
	if isShellInterpreter(head) {
		for i := 1; i < len(cmd.argv); i++ {
			if cmd.argv[i] == "-c" && i+1 < len(cmd.argv) {
				if blocked, reason := classifyDestructive(cmd.argv[i+1]); blocked {
					return true, fmt.Sprintf("%s -c: %s", base, reason)
				}
			}
		}
		// `bash <<<'rm -rf /'` and `bash << EOF\nrm -rf /\nEOF` feed the
		// here-doc/here-string content as commands to the spawned shell.
		for _, rd := range cmd.redirects {
			if rd.op == "<<<" || rd.op == "<<" {
				if blocked, reason := classifyDestructive(rd.target); blocked {
					return true, fmt.Sprintf("%s <<<: %s", base, reason)
				}
			}
		}
	}

	// rm with recursive flag pointing at root.
	if base == "rm" {
		if isRecursiveRootRemove(cmd.argv[1:]) {
			return true, "recursive removal of root paths is not allowed"
		}
	}

	// chmod -R / -Rf at root.
	if base == "chmod" || base == "chown" {
		if hasFlag(cmd.argv[1:], "R", "recursive") && containsRootTarget(cmd.argv[1:]) {
			return true, fmt.Sprintf("%s recursive at root is not allowed", base)
		}
	}

	// dd writing to a block device.
	if base == "dd" {
		for _, a := range cmd.argv[1:] {
			if strings.HasPrefix(a, "of=") {
				dest := strings.TrimPrefix(a, "of=")
				if strings.HasPrefix(dest, "/dev/") {
					return true, "dd to block device is not allowed"
				}
			}
		}
	}

	// mkfs / mkfs.* always destructive.
	if strings.HasPrefix(base, "mkfs") {
		return true, fmt.Sprintf("%s is not allowed", base)
	}

	// tee writing to /etc, /dev, /sys, /proc.
	if base == "tee" {
		for _, a := range cmd.argv[1:] {
			if strings.HasPrefix(a, "-") {
				continue
			}
			if isForbiddenWritePath(a) {
				return true, fmt.Sprintf("tee to protected path %q is not allowed", a)
			}
		}
	}

	// Fork bomb: `:(){ :|:& };:` — head token decodes to ":()" or ":(){".
	if strings.HasPrefix(head, ":()") {
		return true, "fork bomb pattern is not allowed"
	}

	// Interpreters with -c that touch system files.
	if base == "python" || base == "python3" || base == "perl" || base == "ruby" || base == "node" {
		for i := 1; i < len(cmd.argv); i++ {
			if cmd.argv[i] == "-c" && i+1 < len(cmd.argv) {
				body := cmd.argv[i+1]
				if mentionsForbiddenSystemFile(body) {
					return true, fmt.Sprintf("%s -c writing to system files is not allowed", base)
				}
			}
		}
	}

	return false, ""
}

func isRecursiveRootRemove(args []string) bool {
	recursive := false
	hasForce := false
	for _, a := range args {
		if a == "" || a == "--" {
			continue
		}
		if strings.HasPrefix(a, "--") {
			if a == "--recursive" {
				recursive = true
			}
			if a == "--force" {
				hasForce = true
			}
			continue
		}
		if strings.HasPrefix(a, "-") {
			for _, c := range a[1:] {
				switch c {
				case 'r', 'R':
					recursive = true
				case 'f':
					hasForce = true
				}
			}
			continue
		}
	}
	_ = hasForce
	if !recursive {
		return false
	}
	for _, a := range args {
		if strings.HasPrefix(a, "-") {
			continue
		}
		if a == "/" || a == "/*" || strings.HasPrefix(a, "/*") {
			return true
		}
		// /, /etc, /usr, /home, ... all dangerous when recursive.
		if isProtectedRootDir(a) {
			return true
		}
	}
	return false
}

func containsRootTarget(args []string) bool {
	for _, a := range args {
		if a == "/" || a == "/*" || strings.HasPrefix(a, "/*") {
			return true
		}
	}
	return false
}

func isProtectedRootDir(p string) bool {
	clean := strings.TrimRight(p, "/")
	if clean == "" {
		return p == "/"
	}
	switch clean {
	case "/etc", "/usr", "/bin", "/sbin", "/lib", "/lib64", "/var",
		"/boot", "/root", "/home", "/opt", "/dev", "/proc", "/sys":
		return true
	}
	return false
}

func hasFlag(args []string, short, long string) bool {
	for _, a := range args {
		if strings.HasPrefix(a, "--") {
			if a == "--"+long {
				return true
			}
			continue
		}
		if strings.HasPrefix(a, "-") && short != "" {
			if strings.ContainsRune(a[1:], rune(short[0])) {
				return true
			}
		}
	}
	return false
}

func basename(p string) string {
	if i := strings.LastIndex(p, "/"); i >= 0 {
		return p[i+1:]
	}
	return p
}

// wrapperOperandOpts lists, per transparent prefix wrapper, the options that
// consume the FOLLOWING token as an operand (e.g. `env -u NAME`, `sudo -u
// user`, `nice -n 10`). Without this, the operand would be mistaken for the
// command head and invocations of interest (git, gh, destructive commands)
// hidden behind the wrapper would escape classification.
var wrapperOperandOpts = map[string]map[string]bool{
	"sudo": {
		"-u": true, "--user": true, "-g": true, "--group": true,
		"-h": true, "--host": true, "-p": true, "--prompt": true,
		"-C": true, "--close-from": true, "-D": true, "--chdir": true,
		"-R": true, "--chroot": true, "-r": true, "--role": true,
		"-t": true, "--type": true, "-T": true, "--command-timeout": true,
		"-U": true, "--other-user": true,
	},
	"doas":    {"-C": true, "-u": true},
	"env":     {"-u": true, "--unset": true, "-C": true, "--chdir": true},
	"nice":    {"-n": true, "--adjustment": true},
	"ionice":  {"-c": true, "--class": true, "-n": true, "--classdata": true, "-p": true, "--pid": true},
	"stdbuf":  {"-i": true, "--input": true, "-o": true, "--output": true, "-e": true, "--error": true},
	"exec":    {"-a": true},
	"timeout": {"-k": true, "--kill-after": true, "-s": true, "--signal": true},
	"command": {},
	"nohup":   {},
	"setsid":  {},
}

// stripPrefixWrappers removes leading shell assignments and transparent
// wrappers (sudo, doas, command, exec, env, nice, nohup, ionice, stdbuf,
// timeout, setsid) so that the underlying program is what gets classified.
// Assignment stripping runs again after each wrapper because both forms are
// valid shell syntax: FOO=bar env git ... and env FOO=bar git ....
func stripPrefixWrappers(argv []string) []string {
	for len(argv) > 0 {
		argv = stripLeadingShellAssignments(argv)
		if len(argv) == 0 {
			return nil
		}
		head := basename(argv[0])
		operandOpts, isWrapper := wrapperOperandOpts[head]
		if !isWrapper {
			return argv
		}
		// env accepts VAR=value assignments; sudo/doas accept VAR=value that
		// is clearly not a path.
		allowAssignments := head == "env" || head == "sudo" || head == "doas"
		i := 1
		spliced := false
		for i < len(argv) {
			a := argv[i]
			if strings.HasPrefix(a, "-") {
				name, value, hasEq := strings.Cut(a, "=")
				// env -S/--split-string embeds the real command in its
				// operand; splice its fields back in so the head is visible.
				if head == "env" && (name == "-S" || name == "--split-string") {
					operand := value
					rest := argv[min(i+1, len(argv)):]
					if !hasEq && len(rest) > 0 {
						operand, rest = rest[0], rest[1:]
					}
					argv = append(strings.Fields(operand), rest...)
					spliced = true
					break
				}
				if !hasEq && operandOpts[name] {
					i = min(i+2, len(argv))
					continue
				}
				i++
				continue
			}
			if allowAssignments && strings.Contains(a, "=") &&
				(head == "env" || !strings.Contains(a, "/")) {
				i++
				continue
			}
			break
		}
		if spliced {
			continue
		}
		// timeout's first positional is the duration, not the command.
		if head == "timeout" && i < len(argv) {
			i++
		}
		argv = argv[i:]
	}
	return argv
}

func stripLeadingShellAssignments(argv []string) []string {
	for len(argv) > 0 && isShellAssignmentWord(argv[0]) {
		argv = argv[1:]
	}
	return argv
}

func isShellAssignmentWord(word string) bool {
	name, _, ok := strings.Cut(word, "=")
	if !ok || name == "" || !isShellNameStart(name[0]) {
		return false
	}
	for i := 1; i < len(name); i++ {
		if !isShellNameContinue(name[i]) {
			return false
		}
	}
	return true
}

func isShellNameStart(c byte) bool {
	return c == '_' || c >= 'A' && c <= 'Z' || c >= 'a' && c <= 'z'
}

func isShellNameContinue(c byte) bool {
	return isShellNameStart(c) || c >= '0' && c <= '9'
}

func isShellInterpreter(arg string) bool {
	switch basename(arg) {
	case "sh", "bash", "zsh", "ksh", "dash", "ash":
		return true
	}
	return false
}

// isCmdSubEvasionRisk reports whether a command head is one whose static
// destructive checks (recursive rm, chmod/chown -R at root, dd to device,
// mkfs, tee to protected paths) could be defeated by hiding flags or targets
// inside a command substitution (e.g. `rm $(echo -rf) /`). Command substitution
// is blocked for these heads; for all other commands it is permitted because
// the substitution cannot turn a non-destructive program destructive, and any
// destructive command inside the substitution is caught by recursion.
func isCmdSubEvasionRisk(base string) bool {
	switch base {
	case "rm", "rmdir", "chmod", "chown", "chgrp", "dd", "tee", "shred", "truncate":
		return true
	}
	if strings.HasPrefix(base, "mkfs") {
		return true
	}
	return isShellInterpreter(base)
}

func isForbiddenWritePath(p string) bool {
	if p == "" {
		return false
	}
	// Standard safe pseudo-device files are always valid redirect/tee targets
	// (e.g. "2>/dev/null", ">/dev/stderr"). Writing to them discards data or
	// routes it to an existing stream; it is never destructive. Without this,
	// the universally-common "2>/dev/null" idiom is blocked, which forces agents
	// to rewrite/retry exploration commands and wastes tool calls.
	if isSafeDeviceFile(p) {
		return false
	}
	if strings.HasPrefix(p, "/etc/") || p == "/etc" {
		return true
	}
	if strings.HasPrefix(p, "/dev/") || p == "/dev" {
		return true
	}
	if strings.HasPrefix(p, "/sys/") || p == "/sys" {
		return true
	}
	if strings.HasPrefix(p, "/proc/") || p == "/proc" {
		return true
	}
	if strings.HasPrefix(p, "/boot/") || p == "/boot" {
		return true
	}
	return false
}

// isSafeDeviceFile reports whether p is a standard pseudo-device that is always
// safe to use as a redirect/tee target. /dev/fd/N and /dev/std* route to the
// process's own streams; /dev/null and /dev/zero discard writes.
func isSafeDeviceFile(p string) bool {
	switch p {
	case "/dev/null", "/dev/zero", "/dev/full", "/dev/tty",
		"/dev/stdin", "/dev/stdout", "/dev/stderr",
		"/dev/random", "/dev/urandom":
		return true
	}
	return strings.HasPrefix(p, "/dev/fd/")
}

func mentionsForbiddenSystemFile(s string) bool {
	for _, marker := range []string{"/etc/passwd", "/etc/shadow", "/etc/hosts", "/etc/sudoers"} {
		if strings.Contains(s, marker) {
			return true
		}
	}
	return false
}

// invocationsOf returns all argv slices in cmdLine whose head matches
// isBinary, recursing into shell -c strings, eval arguments, heredoc/
// herestring bodies, and command substitutions. Shared by the git and gh
// command policies.
func invocationsOf(cmdLine string, isBinary func(string) bool) [][]string {
	var out [][]string
	pipelines := parseStatements(tokenize(cmdLine))
	for _, pl := range pipelines {
		for _, cmd := range pl.commands {
			argv := stripPrefixWrappers(cmd.argv)
			if len(argv) == 0 {
				continue
			}
			head := argv[0]
			if isBinary(head) {
				out = append(out, argv)
				continue
			}
			// Recurse into bash -c "...", sh -c '...', eval ...
			if isShellInterpreter(head) {
				for i := 1; i < len(argv); i++ {
					if argv[i] == "-c" && i+1 < len(argv) {
						out = append(out, invocationsOf(argv[i+1], isBinary)...)
					}
				}
				for _, rd := range cmd.redirects {
					if rd.op == "<<<" || rd.op == "<<" {
						out = append(out, invocationsOf(rd.target, isBinary)...)
					}
				}
			}
			if basename(head) == "eval" {
				out = append(out, invocationsOf(strings.Join(argv[1:], " "), isBinary)...)
			}
			// Recurse into command substitutions.
			for _, sub := range cmd.cmdSubs {
				out = append(out, invocationsOf(sub, isBinary)...)
			}
		}
	}
	return out
}

// gitInvocations returns all argv slices in cmdLine that look like a git
// invocation, with leading `git`-equivalent token at index 0. Used by
// IsPushToProtectedBranch and the read-only-mode git denylist.
func gitInvocations(cmdLine string) [][]string {
	out := invocationsOf(cmdLine, isGitBinary)
	pipelines := parseStatements(tokenize(cmdLine))
	// Synthesize: `git;push origin main` and similar patterns where a bare
	// `git` token is followed by a separate statement whose head is a known
	// git subcommand. Real bash would not interpret these as `git push`, but
	// we treat the obfuscation defensively.
	for i := 0; i+1 < len(pipelines); i++ {
		left := pipelines[i]
		right := pipelines[i+1]
		if len(left.commands) == 0 || len(right.commands) == 0 {
			continue
		}
		lc := stripPrefixWrappers(left.commands[len(left.commands)-1].argv)
		rc := stripPrefixWrappers(right.commands[0].argv)
		if len(lc) != 1 || !isGitBinary(lc[0]) {
			continue
		}
		if len(rc) == 0 || !isLikelyGitSubcommand(rc[0]) {
			continue
		}
		synth := append([]string{"git"}, rc...)
		out = append(out, synth)
	}
	return out
}

// isLikelyGitSubcommand returns true for the subset of git subcommands that
// our policies care about. Used only for obfuscation-pattern synthesis.
func isLikelyGitSubcommand(s string) bool {
	switch s {
	case "push", "commit", "reset", "remote", "merge", "rebase",
		"cherry-pick", "add", "rm", "clean", "tag", "branch", "stash",
		"fetch", "pull", "checkout", "switch", "status", "log", "diff":
		return true
	}
	return false
}

func isGitBinary(token string) bool {
	if token == "git" {
		return true
	}
	return basename(token) == "git"
}

// ghInvocations returns all argv slices in cmdLine that invoke the GitHub CLI
// (gh), including through shell wrappers, eval, and command substitution.
// Used by the restricted-mode gh policy: GitHub side effects must go through
// the host's built-in GitHub tools, which enforce guardrails that raw gh
// invocations bypass.
func ghInvocations(cmdLine string) [][]string {
	return invocationsOf(cmdLine, isGHBinary)
}

func isGHBinary(token string) bool {
	if token == "gh" {
		return true
	}
	return basename(token) == "gh"
}

// gitSubcommand returns the subcommand name (e.g. "push") for a git argv, or
// "" if the argv has no subcommand. Skips global flags and `-c key=value` /
// `-C dir` option pairs.
func gitSubcommand(argv []string) string {
	for i := 1; i < len(argv); i++ {
		a := argv[i]
		if a == "-c" || a == "-C" {
			i++
			continue
		}
		if strings.HasPrefix(a, "-") {
			continue
		}
		return a
	}
	return ""
}

func gitAliasExpandsToPush(argv []string) bool {
	subcommand := gitSubcommand(argv)
	if subcommand == "" {
		return false
	}
	aliasKey := "alias." + subcommand
	for i := 1; i+1 < len(argv); i++ {
		if argv[i] != "-c" {
			continue
		}
		key, expansion, ok := strings.Cut(argv[i+1], "=")
		if !ok || !strings.EqualFold(strings.TrimSpace(key), aliasKey) {
			continue
		}
		expansion = strings.TrimSpace(expansion)
		if shellExpansion, found := strings.CutPrefix(expansion, "!"); found {
			expansion = strings.TrimSpace(shellExpansion)
		}
		fields := strings.Fields(expansion)
		directPush := len(fields) > 0 && (fields[0] == "push" || fields[0] == "git-push")
		shellPush := len(fields) > 1 && fields[0] == "git" && fields[1] == "push"
		if directPush || shellPush {
			return true
		}
	}
	return false
}

func gitSubcommandArgs(argv []string) []string {
	for i := 1; i < len(argv); i++ {
		a := argv[i]
		if a == "-c" || a == "-C" {
			i++
			continue
		}
		if strings.HasPrefix(a, "-") {
			continue
		}
		return argv[i+1:]
	}
	return nil
}

// isReadOnlyGitDenied returns (true, subcommand) if the git invocation should
// be blocked under read-only mode.
func isReadOnlyGitDenied(argv []string) (bool, string) {
	sub := gitSubcommand(argv)
	switch sub {
	case "push", "commit", "reset", "remote", "merge", "rebase",
		"cherry-pick", "add", "rm", "clean", "tag", "branch", "stash":
		return true, sub
	}
	return false, ""
}

// isWorkspaceWriteGitDenied returns (true, subcommand) if the git invocation
// should be blocked under workspace-write mode (currently just `git remote`).
func isWorkspaceWriteGitDenied(argv []string) (bool, string) {
	sub := gitSubcommand(argv)
	if sub == "remote" {
		return true, sub
	}
	return false, ""
}

// pushTargetsProtectedBranch returns true if a `git push` argv targets main /
// master.
func pushTargetsProtectedBranch(argv []string) bool {
	if gitSubcommand(argv) != "push" {
		return false
	}
	for _, a := range gitSubcommandArgs(argv) {
		if a == "" || strings.HasPrefix(a, "-") {
			continue
		}
		if isProtectedRef(a) {
			return true
		}
	}
	return false
}

// modeIsRestricted is a small helper for the public guard.
func modeIsRestricted(mode policy.PermissionMode) (readOnly, workspaceWrite bool) {
	switch policy.NormalizePermissionMode(string(mode)) {
	case policy.PermissionModeReadOnly:
		return true, false
	case policy.PermissionModeWorkspaceWrite:
		return false, true
	}
	return false, false
}

