package shell

import (
	"context"
	"encoding/json"
	"strings"
	"testing"
	"time"

	"github.com/gratefulagents/sdk/pkg/agentsdk/policy"
	"github.com/gratefulagents/sdk/pkg/agentsdk/sandbox"
)

func newTestTerminalTool(t *testing.T) (*TerminalTool, string) {
	t.Helper()
	mgr := NewTerminalManager(sandbox.Default())
	t.Cleanup(func() { _ = mgr.Close() })
	return &TerminalTool{Manager: mgr}, t.TempDir()
}

func execTerminal(t *testing.T, tool *TerminalTool, workDir, input string) terminalSnapshot {
	t.Helper()
	res, err := tool.Execute(context.Background(), json.RawMessage(input), workDir)
	if err != nil {
		t.Fatal(err)
	}
	if res.IsError {
		t.Fatalf("tool error: %s", res.Content)
	}
	var snap terminalSnapshot
	if err := json.Unmarshal([]byte(res.Content), &snap); err != nil {
		t.Fatalf("unmarshal %q: %v", res.Content, err)
	}
	return snap
}

func TestTerminalToolInteractiveSession(t *testing.T) {
	tool, workDir := newTestTerminalTool(t)

	snap := execTerminal(t, tool, workDir, `{"op":"start","wait_ms":500}`)
	if snap.SessionID == "" || snap.Status != "running" {
		t.Fatalf("unexpected start snapshot: %+v", snap)
	}
	sid := snap.SessionID

	// Run a command and observe its output.
	snap = execTerminal(t, tool, workDir, `{"op":"send","session_id":"`+sid+`","keystrokes":"echo terminal-$((20+22)) TERM=$TERM\n","wait_ms":1500}`)
	if !strings.Contains(snap.Output, "terminal-42") || !strings.Contains(snap.Output, "TERM=xterm-256color") {
		t.Fatalf("expected command output and terminal environment, got: %q", snap.Output)
	}

	// Incremental read: no repeat of prior output.
	snap = execTerminal(t, tool, workDir, `{"op":"read","session_id":"`+sid+`"}`)
	if strings.Contains(snap.Output, "terminal-42") {
		t.Fatalf("read should not repeat consumed output, got: %q", snap.Output)
	}

	// Interactive program: cat reads stdin until C-d.
	execTerminal(t, tool, workDir, `{"op":"send","session_id":"`+sid+`","keystrokes":"cat\n","wait_ms":300}`)
	snap = execTerminal(t, tool, workDir, `{"op":"send","session_id":"`+sid+`","keystrokes":"interactive-echo\n","wait_ms":500}`)
	if !strings.Contains(snap.Output, "interactive-echo") {
		t.Fatalf("expected cat echo, got: %q", snap.Output)
	}
	execTerminal(t, tool, workDir, `{"op":"send","session_id":"`+sid+`","keystrokes":"C-d","wait_ms":300}`)
	// Shell should be responsive again.
	snap = execTerminal(t, tool, workDir, `{"op":"send","session_id":"`+sid+`","keystrokes":"echo back-$((1+1))\n","wait_ms":1500}`)
	if !strings.Contains(snap.Output, "back-2") {
		t.Fatalf("shell not responsive after C-d: %q", snap.Output)
	}

	// C-c interrupts a foreground process.
	execTerminal(t, tool, workDir, `{"op":"send","session_id":"`+sid+`","keystrokes":"sleep 30\n","wait_ms":200}`)
	execTerminal(t, tool, workDir, `{"op":"send","session_id":"`+sid+`","keystrokes":"C-c","wait_ms":300}`)
	snap = execTerminal(t, tool, workDir, `{"op":"send","session_id":"`+sid+`","keystrokes":"echo alive\n","wait_ms":1500}`)
	if !strings.Contains(snap.Output, "alive") {
		t.Fatalf("shell not responsive after C-c: %q", snap.Output)
	}

	// Kill terminates the session.
	snap = execTerminal(t, tool, workDir, `{"op":"kill","session_id":"`+sid+`"}`)
	if snap.Status != "exited" {
		t.Fatalf("expected exited after kill, got %s", snap.Status)
	}
}

func TestTerminalToolRejectsRestrictedModes(t *testing.T) {
	for _, mode := range []policy.PermissionMode{policy.PermissionModeReadOnly, policy.PermissionModeWorkspaceWrite} {
		tool := &TerminalTool{Manager: NewTerminalManager(sandbox.Default()), Mode: mode}
		res, err := tool.Execute(context.Background(), json.RawMessage(`{"op":"list"}`), t.TempDir())
		if err != nil || !res.IsError || !strings.Contains(res.Content, "danger-full-access") {
			t.Fatalf("mode %s result = %+v err=%v, want runtime refusal", mode, res, err)
		}
	}
}

func TestTerminalToolRejectsDisabledGitRemoteWrites(t *testing.T) {
	tool := &TerminalTool{GitRemoteWrites: policy.GitRemoteWritesDisabled}
	res, err := tool.Execute(context.Background(), json.RawMessage(`{"op":"list"}`), t.TempDir())
	if err != nil || !res.IsError || !strings.Contains(res.Content, "GitRemoteWrites") {
		t.Fatalf("result = %+v err=%v, want GitRemoteWrites refusal", res, err)
	}
}

func TestTerminalToolUnknownSessionAndOps(t *testing.T) {
	tool, workDir := newTestTerminalTool(t)
	res, err := tool.Execute(context.Background(), json.RawMessage(`{"op":"send","session_id":"nope","keystrokes":"x"}`), workDir)
	if err != nil || !res.IsError {
		t.Fatalf("expected error result for unknown session, got %+v err=%v", res, err)
	}
	res, err = tool.Execute(context.Background(), json.RawMessage(`{"op":"resize"}`), workDir)
	if err != nil || !res.IsError || !strings.Contains(res.Content, "invalid op") {
		t.Fatalf("expected invalid op error, got %+v err=%v", res, err)
	}
}

func TestLimitTerminalOutputHeadTail(t *testing.T) {
	long := strings.Repeat("h", 8000) + "MID" + strings.Repeat("t", 8000)
	out := limitTerminalOutput(long, 10000)
	if len(out) > 11000 {
		t.Fatalf("output too long: %d", len(out))
	}
	if !strings.HasPrefix(out, "hhh") || !strings.HasSuffix(out, "ttt") {
		t.Fatal("head/tail not preserved")
	}
	if !strings.Contains(out, "interior bytes omitted") {
		t.Fatal("missing omission marker")
	}
	if got := limitTerminalOutput("short", 10000); got != "short" {
		t.Fatalf("short output should be unchanged: %q", got)
	}
}

func TestTerminalScrollbackWindowDiscardsOldOutput(t *testing.T) {
	s := &terminalSession{done: make(chan struct{}), startedAt: time.Now()}
	// Simulate the read loop sliding the window before any read happened:
	// the unread cursor (0) falls behind the window start.
	s.mu.Lock()
	s.stream = make([]byte, terminalWindowBytes)
	s.streamStart = 1000
	s.mu.Unlock()
	_, dropped := s.consumeNewOutput()
	if !dropped {
		t.Fatal("expected dropped flag when read offset fell behind window start")
	}
	// Cursor is caught up now; next read reports nothing dropped.
	if _, dropped := s.consumeNewOutput(); dropped {
		t.Fatal("dropped flag should reset once the cursor caught up")
	}
}

func TestBashPollIncrementalOutput(t *testing.T) {
	mgr := NewAsyncManager(sandbox.Default())
	t.Cleanup(func() { _ = mgr.Close() })
	start := &BashStartTool{Manager: mgr}
	poll := &BashPollTool{Manager: mgr}
	workDir := t.TempDir()

	res, err := start.Execute(context.Background(), json.RawMessage(`{"command":"echo first; sleep 1; echo second"}`), workDir)
	if err != nil || res.IsError {
		t.Fatalf("start failed: %+v err=%v", res, err)
	}
	id := strings.TrimPrefix(res.Content, "started background bash job ")

	// First poll sees "first".
	res, err = poll.Execute(context.Background(), json.RawMessage(`{"id":"`+id+`","wait_ms":500}`), workDir)
	if err != nil || res.IsError {
		t.Fatalf("poll failed: %+v err=%v", res, err)
	}
	if !strings.Contains(res.Content, "first") {
		t.Fatalf("first poll missing output: %s", res.Content)
	}

	// Second poll (after completion) sees only "second", not "first".
	res, err = poll.Execute(context.Background(), json.RawMessage(`{"id":"`+id+`","wait_ms":3000}`), workDir)
	if err != nil || res.IsError {
		t.Fatalf("poll failed: %+v err=%v", res, err)
	}
	if strings.Contains(res.Content, "first") {
		t.Fatalf("incremental poll repeated old output: %s", res.Content)
	}
	if !strings.Contains(res.Content, "second") {
		t.Fatalf("incremental poll missing new output: %s", res.Content)
	}

	// Full output still available with incremental=false.
	res, err = poll.Execute(context.Background(), json.RawMessage(`{"id":"`+id+`","incremental":false}`), workDir)
	if err != nil || res.IsError {
		t.Fatalf("poll failed: %+v err=%v", res, err)
	}
	if !strings.Contains(res.Content, "first") || !strings.Contains(res.Content, "second") {
		t.Fatalf("full poll missing output: %s", res.Content)
	}
}

//go:build unix

package shell

import (
	"os"
	"os/exec"

	"github.com/creack/pty"
)

// startTerminalPTY starts cmd attached to a new PTY with the given window size.
// pty sets Setsid (new session = new process group), so killProcessTree's
// group kill works without configurePlatformProcAttrs (Setpgid would conflict
// with Setsid at fork time).
func startTerminalPTY(cmd *exec.Cmd, rows, cols int) (*os.File, error) {
	return pty.StartWithSize(cmd, &pty.Winsize{Rows: uint16(rows), Cols: uint16(cols)})
}

package shell

import (
	"strings"
)

// Token is one lexical unit produced by tokenize. Operator tokens (";", "|",
// "||", "&", "&&", ">", ">>", "<", "<<", "<<<") have IsOperator set; word
// tokens carry their decoded Value (quotes/escapes resolved, $IFS expanded to
// a space, unknown $VAR expanded to empty string).
//
// HasCmdSub is true when the original word contained a $(...) or backtick
// command substitution. CmdSubBodies holds the inner text of each substitution
// for recursive scanning.
type token struct {
	Value        string
	IsOperator   bool
	HasCmdSub    bool
	CmdSubBodies []string
}

// tokenize lexes a POSIX-ish shell command into tokens. It is intentionally
// scoped to what the destructive-command classifier needs: quoting/escaping,
// $IFS expansion, ANSI-C $'...' decoding, and recognition of command
// substitution and the common control operators. It does not implement full
// shell semantics (no aliases, no parameter expansion edge cases, etc.).
func tokenize(input string) []token {
	var out []token
	var cur strings.Builder
	curHasCmdSub := false
	var curBodies []string
	inWord := false

	flush := func() {
		if !inWord {
			return
		}
		out = append(out, token{Value: cur.String(), HasCmdSub: curHasCmdSub, CmdSubBodies: curBodies})
		cur.Reset()
		curHasCmdSub = false
		curBodies = nil
		inWord = false
	}
	startWord := func() {
		inWord = true
	}
	pushOp := func(op string) {
		flush()
		out = append(out, token{Value: op, IsOperator: true})
	}

	r := []rune(input)
	i := 0
	for i < len(r) {
		c := r[i]
		switch {
		case c == ' ' || c == '\t' || c == '\n' || c == '\r':
			flush()
			i++
		case c == '\\' && i+1 < len(r):
			startWord()
			cur.WriteRune(r[i+1])
			i += 2
		case c == '\'':
			// Single quotes: literal until next '.
			startWord()
			j := i + 1
			for j < len(r) && r[j] != '\'' {
				cur.WriteRune(r[j])
				j++
			}
			if j < len(r) {
				j++
			}
			i = j
		case c == '"':
			// Double quotes: backslash escapes only \ " $ ` and newline; $VAR
			// and $() are still expanded.
			startWord()
			j := i + 1
			for j < len(r) {
				if r[j] == '"' {
					j++
					break
				}
				if r[j] == '\\' && j+1 < len(r) {
					next := r[j+1]
					if next == '\\' || next == '"' || next == '$' || next == '`' || next == '\n' {
						cur.WriteRune(next)
						j += 2
						continue
					}
				}
				if r[j] == '$' && j+1 < len(r) {
					consumed, body, isSub := decodeDollar(r, j)
					if consumed > 0 {
						if isSub {
							curHasCmdSub = true
							curBodies = append(curBodies, body)
						} else {
							cur.WriteString(body)
						}
						j += consumed
						continue
					}
				}
				if r[j] == '`' {
					j++
					var sub strings.Builder
					for j < len(r) && r[j] != '`' {
						if r[j] == '\\' && j+1 < len(r) {
							sub.WriteRune(r[j+1])
							j += 2
							continue
						}
						sub.WriteRune(r[j])
						j++
					}
					if j < len(r) {
						j++
					}
					curHasCmdSub = true
					curBodies = append(curBodies, sub.String())
					continue
				}
				cur.WriteRune(r[j])
				j++
			}
			i = j
		case c == '$':
			// $'...' ANSI-C, $(...) sub, ${VAR}, $VAR.
			consumed, body, isSub := decodeDollar(r, i)
			if consumed == 0 {
				startWord()
				cur.WriteRune(c)
				i++
				continue
			}
			if isSub {
				startWord()
				curHasCmdSub = true
				curBodies = append(curBodies, body)
			} else if body == " " && !inWord {
				// A bare $IFS expansion at a token boundary is whitespace.
				// inWord starts false here; just skip.
			} else if body == " " {
				// $IFS inside a word splits the word.
				flush()
			} else {
				startWord()
				cur.WriteString(body)
			}
			i += consumed
		case c == '`':
			startWord()
			j := i + 1
			var sub strings.Builder
			for j < len(r) && r[j] != '`' {
				if r[j] == '\\' && j+1 < len(r) {
					sub.WriteRune(r[j+1])
					j += 2
					continue
				}
				sub.WriteRune(r[j])
				j++
			}
			if j < len(r) {
				j++
			}
			curHasCmdSub = true
			curBodies = append(curBodies, sub.String())
			i = j
		case c == ';':
			pushOp(";")
			i++
		case c == '|':
			if i+1 < len(r) && r[i+1] == '|' {
				pushOp("||")
				i += 2
			} else {
				pushOp("|")
				i++
			}
		case c == '&':
			if i+1 < len(r) && r[i+1] == '&' {
				pushOp("&&")
				i += 2
			} else {
				pushOp("&")
				i++
			}
		case c == '>':
			if i+1 < len(r) && r[i+1] == '>' {
				pushOp(">>")
				i += 2
			} else {
				pushOp(">")
				i++
			}
		case c == '<':
			if i+2 < len(r) && r[i+1] == '<' && r[i+2] == '<' {
				pushOp("<<<")
				i += 3
			} else if i+1 < len(r) && r[i+1] == '<' {
				pushOp("<<")
				i += 2
			} else {
				pushOp("<")
				i++
			}
		default:
			startWord()
			cur.WriteRune(c)
			i++
		}
	}
	flush()
	return out
}

// decodeDollar handles a `$`-introduced sequence starting at r[i]. It returns
// (consumed runes, decoded body, isCommandSubstitution). consumed==0 means no
// match; caller should treat the `$` as a literal.
func decodeDollar(r []rune, i int) (int, string, bool) {
	if i >= len(r) || r[i] != '$' {
		return 0, "", false
	}
	if i+1 >= len(r) {
		return 0, "", false
	}
	next := r[i+1]
	switch {
	case next == '\'':
		// $'...' ANSI-C quoted string.
		j := i + 2
		var b strings.Builder
		for j < len(r) && r[j] != '\'' {
			if r[j] == '\\' && j+1 < len(r) {
				ch, n := decodeAnsiCEscape(r, j+1)
				b.WriteString(ch)
				j += 1 + n
				continue
			}
			b.WriteRune(r[j])
			j++
		}
		if j < len(r) {
			j++
		}
		return j - i, b.String(), false
	case next == '(':
		// $(...) command substitution; track nested parens.
		depth := 1
		j := i + 2
		var b strings.Builder
		for j < len(r) && depth > 0 {
			switch r[j] {
			case '(':
				depth++
				b.WriteRune(r[j])
			case ')':
				depth--
				if depth == 0 {
					j++
					return j - i, b.String(), true
				}
				b.WriteRune(r[j])
			case '\\':
				if j+1 < len(r) {
					b.WriteRune(r[j+1])
					j += 2
					continue
				}
				b.WriteRune(r[j])
			default:
				b.WriteRune(r[j])
			}
			j++
		}
		return j - i, b.String(), true
	case next == '{':
		// ${VAR}.
		j := i + 2
		var name strings.Builder
		for j < len(r) && r[j] != '}' {
			name.WriteRune(r[j])
			j++
		}
		if j < len(r) {
			j++
		}
		return j - i, expandVar(name.String()), false
	case isVarStart(next):
		j := i + 2
		for j < len(r) && isVarCont(r[j]) {
			j++
		}
		name := string(r[i+1 : j])
		return j - i, expandVar(name), false
	}
	return 0, "", false
}

func decodeAnsiCEscape(r []rune, i int) (string, int) {
	if i >= len(r) {
		return "\\", 0
	}
	c := r[i]
	switch c {
	case 'a':
		return "\a", 1
	case 'b':
		return "\b", 1
	case 'e', 'E':
		return "\x1b", 1
	case 'f':
		return "\f", 1
	case 'n':
		return "\n", 1
	case 'r':
		return "\r", 1
	case 't':
		return "\t", 1
	case 'v':
		return "\v", 1
	case '\\':
		return "\\", 1
	case '\'':
		return "'", 1
	case '"':
		return `"`, 1
	case '?':
		return "?", 1
	case 'x':
		j := i + 1
		hex := ""
		for j < len(r) && len(hex) < 2 && isHex(r[j]) {
			hex += string(r[j])
			j++
		}
		if hex == "" {
			return "x", 1
		}
		var v int
		for _, h := range hex {
			v = v*16 + hexVal(h)
		}
		return string(rune(v)), j - i
	case '0', '1', '2', '3', '4', '5', '6', '7':
		j := i
		oct := ""
		for j < len(r) && len(oct) < 3 && r[j] >= '0' && r[j] <= '7' {
			oct += string(r[j])
			j++
		}
		var v int
		for _, o := range oct {
			v = v*8 + int(o-'0')
		}
		return string(rune(v)), j - i
	}
	return string(c), 1
}

func isHex(c rune) bool {
	return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
}

func hexVal(c rune) int {
	switch {
	case c >= '0' && c <= '9':
		return int(c - '0')
	case c >= 'a' && c <= 'f':
		return int(c-'a') + 10
	case c >= 'A' && c <= 'F':
		return int(c-'A') + 10
	}
	return 0
}

func isVarStart(c rune) bool {
	return c == '_' || (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z')
}

func isVarCont(c rune) bool {
	return isVarStart(c) || (c >= '0' && c <= '9')
}

// expandVar resolves a small set of variables that affect destructive-command
// classification. IFS expands to a single space (its default whitespace
// behavior) so word splitting still works. Everything else expands to the
// empty string — we are not a real shell.
func expandVar(name string) string {
	if name == "IFS" {
		return " "
	}
	return ""
}

