package skills

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"

	"github.com/gratefulagents/sdk/pkg/agentsdk/mcp"
	"github.com/gratefulagents/sdk/pkg/agentsdk/tools/internal/pathutil"
)

// Installer manages skill installation in workspaces via .mcp.json.
type Installer struct {
	registry *Registry
}

// NewInstaller creates an installer backed by the given registry.
func NewInstaller(registry *Registry) *Installer {
	return &Installer{registry: registry}
}

// Skill returns the catalog entry for name from the installer's registry.
func (inst *Installer) Skill(name string) (*SkillEntry, bool) {
	if inst == nil || inst.registry == nil {
		return nil, false
	}
	return inst.registry.Get(name)
}

// Install adds the named skill's MCP server config to the workspace's .mcp.json.
//
// The entry's allowEnv is seeded from the skill's requiresEnvVars so that
// credential-looking variables the server genuinely needs pass the SDK's
// credential env filter once the host supplies them (via the entry's env map
// or a host-level secret mechanism). If an entry with the same name already
// exists, its hardening fields (allowEnv, allowedTools, enabled, env) are
// preserved and merged rather than silently clobbered.
func (inst *Installer) Install(workDir, skillName string) error {
	if inst == nil || inst.registry == nil {
		return fmt.Errorf("skill installer registry is not configured")
	}
	skill, ok := inst.registry.Get(skillName)
	if !ok {
		return fmt.Errorf("skill %q not found in registry", skillName)
	}

	cfgPath, err := mcpConfigPath(workDir)
	if err != nil {
		return err
	}
	cfg, err := loadMCPConfig(cfgPath)
	if err != nil {
		return fmt.Errorf("loading .mcp.json: %w", err)
	}

	entry := mcp.ServerConfig{
		Type:     skill.MCPConfig.Type,
		Command:  skill.MCPConfig.Command,
		Args:     skill.MCPConfig.Args,
		Env:      cloneStringMap(skill.MCPConfig.Env),
		AllowEnv: append([]string(nil), skill.RequiresEnvVars...),
	}
	if existing, ok := cfg.MCPServers[skill.Name]; ok {
		// Reinstall/update: keep user- or platform-applied hardening.
		entry.AllowEnv = mergeUnique(existing.AllowEnv, entry.AllowEnv)
		entry.AllowedTools = existing.AllowedTools
		entry.Enabled = existing.Enabled
		for k, v := range existing.Env {
			if entry.Env == nil {
				entry.Env = make(map[string]string)
			}
			if _, exists := entry.Env[k]; !exists {
				entry.Env[k] = v
			}
		}
	}
	cfg.MCPServers[skill.Name] = entry

	return saveMCPConfig(cfgPath, cfg)
}

func cloneStringMap(in map[string]string) map[string]string {
	if len(in) == 0 {
		return nil
	}
	out := make(map[string]string, len(in))
	for k, v := range in {
		out[k] = v
	}
	return out
}

func mergeUnique(lists ...[]string) []string {
	seen := make(map[string]bool)
	var out []string
	for _, list := range lists {
		for _, v := range list {
			if v == "" || seen[v] {
				continue
			}
			seen[v] = true
			out = append(out, v)
		}
	}
	return out
}

// Uninstall removes the named skill's MCP server config from .mcp.json.
func (inst *Installer) Uninstall(workDir, skillName string) error {
	if inst == nil || inst.registry == nil {
		return fmt.Errorf("skill installer registry is not configured")
	}
	cfgPath, err := mcpConfigPath(workDir)
	if err != nil {
		return err
	}
	cfg, err := loadMCPConfig(cfgPath)
	if err != nil {
		return fmt.Errorf("loading .mcp.json: %w", err)
	}

	if _, exists := cfg.MCPServers[skillName]; !exists {
		return fmt.Errorf("skill %q is not installed", skillName)
	}

	delete(cfg.MCPServers, skillName)

	if len(cfg.MCPServers) == 0 {
		return os.Remove(cfgPath)
	}
	return saveMCPConfig(cfgPath, cfg)
}

// ListInstalled returns the names of skills currently configured in .mcp.json.
func (inst *Installer) ListInstalled(workDir string) ([]string, error) {
	if inst == nil || inst.registry == nil {
		return nil, fmt.Errorf("skill installer registry is not configured")
	}
	cfgPath, err := mcpConfigPath(workDir)
	if err != nil {
		return nil, err
	}
	cfg, err := loadMCPConfig(cfgPath)
	if err != nil {
		return nil, err
	}

	names := make([]string, 0, len(cfg.MCPServers))
	for name := range cfg.MCPServers {
		names = append(names, name)
	}
	return names, nil
}

func mcpConfigPath(workDir string) (string, error) {
	return pathutil.ResolveWorkspace(workDir, ".mcp.json")
}

func loadMCPConfig(path string) (*mcp.Config, error) {
	cfg, exists, err := mcp.LoadConfig(path)
	if err != nil {
		return nil, err
	}
	if !exists {
		cfg.MCPServers = make(map[string]mcp.ServerConfig)
	}
	return &cfg, nil
}

func saveMCPConfig(path string, cfg *mcp.Config) error {
	data, err := json.MarshalIndent(cfg, "", "  ")
	if err != nil {
		return fmt.Errorf("marshaling config: %w", err)
	}
	data = append(data, '\n')
	perm := os.FileMode(0o600)
	f, err := pathutil.OpenInWorkspace(filepath.Dir(path), filepath.Base(path), os.O_RDONLY, 0)
	if err == nil {
		info, statErr := f.Stat()
		_ = f.Close()
		if statErr != nil {
			return fmt.Errorf("stat config: %w", statErr)
		}
		perm = info.Mode().Perm() & 0o600
	} else if !os.IsNotExist(err) {
		return fmt.Errorf("open config: %w", err)
	}
	if err := pathutil.AtomicWriteFileInWorkspace(filepath.Dir(path), filepath.Base(path), data, perm); err != nil {
		return fmt.Errorf("saving config: %w", err)
	}
	return nil
}

package skills

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"strings"
)

//go:embed default_catalog.json
var defaultCatalogJSON []byte

// SkillEntry represents a single skill in the catalog.
type SkillEntry struct {
	Name            string          `json:"name"`
	Description     string          `json:"description"`
	Category        string          `json:"category"`
	Version         string          `json:"version"`
	Source          SkillSource     `json:"source"`
	MCPConfig       MCPServerConfig `json:"mcpConfig"`
	Tags            []string        `json:"tags,omitempty"`
	Verified        bool            `json:"verified"`
	RequiresEnvVars []string        `json:"requiresEnvVars,omitempty"`
}

// SkillSource identifies where a skill package comes from.
type SkillSource struct {
	Repository string `json:"repository,omitempty"`
	Ref        string `json:"ref,omitempty"`
	URL        string `json:"url,omitempty"`
}

// MCPServerConfig defines how to run an MCP server.
type MCPServerConfig struct {
	Type    string            `json:"type"`
	Command string            `json:"command"`
	Args    []string          `json:"args,omitempty"`
	Env     map[string]string `json:"env,omitempty"`
}

// Registry manages the skill catalog for discovery and installation.
type Registry struct {
	skills []SkillEntry
}

// NewRegistry creates a registry loaded with the default embedded catalog.
func NewRegistry() (*Registry, error) {
	entries, err := LoadDefaultCatalog()
	if err != nil {
		return nil, fmt.Errorf("loading default catalog: %w", err)
	}
	return &Registry{skills: entries}, nil
}

// NewRegistryFromEntries creates a registry from provided entries.
func NewRegistryFromEntries(entries []SkillEntry) *Registry {
	return &Registry{skills: entries}
}

// LoadDefaultCatalog parses the embedded default skill catalog.
func LoadDefaultCatalog() ([]SkillEntry, error) {
	var catalog struct {
		Skills []SkillEntry `json:"skills"`
	}
	if err := json.Unmarshal(defaultCatalogJSON, &catalog); err != nil {
		return nil, fmt.Errorf("parsing catalog: %w", err)
	}
	return catalog.Skills, nil
}

// FilterOption configures skill filtering.
type FilterOption func(*filterConfig)

type filterConfig struct {
	category string
	tags     []string
	verified *bool
}

// WithCategory filters skills by category.
func WithCategory(cat string) FilterOption {
	return func(c *filterConfig) { c.category = cat }
}

// WithTags filters skills that have any of the given tags.
func WithTags(tags ...string) FilterOption {
	return func(c *filterConfig) { c.tags = tags }
}

// WithVerifiedOnly filters to only verified skills.
func WithVerifiedOnly() FilterOption {
	return func(c *filterConfig) { v := true; c.verified = &v }
}

// List returns all skills, optionally filtered.
func (r *Registry) List(opts ...FilterOption) []SkillEntry {
	cfg := &filterConfig{}
	for _, opt := range opts {
		opt(cfg)
	}

	var result []SkillEntry
	for _, s := range r.skills {
		if cfg.category != "" && !strings.EqualFold(s.Category, cfg.category) {
			continue
		}
		if cfg.verified != nil && *cfg.verified && !s.Verified {
			continue
		}
		if len(cfg.tags) > 0 && !hasAnyTag(s.Tags, cfg.tags) {
			continue
		}
		result = append(result, s)
	}
	return result
}

// Get returns a skill by name, or nil if not found.
func (r *Registry) Get(name string) (*SkillEntry, bool) {
	for _, s := range r.skills {
		if s.Name == name {
			return &s, true
		}
	}
	return nil, false
}

// Search finds skills matching a query string against name, description, and tags.
func (r *Registry) Search(query string) []SkillEntry {
	q := strings.ToLower(query)
	var results []SkillEntry
	for _, s := range r.skills {
		if strings.Contains(strings.ToLower(s.Name), q) ||
			strings.Contains(strings.ToLower(s.Description), q) ||
			containsTag(s.Tags, q) {
			results = append(results, s)
		}
	}
	return results
}

// Categories returns all unique categories in the catalog.
func (r *Registry) Categories() []string {
	seen := make(map[string]bool)
	var cats []string
	for _, s := range r.skills {
		if s.Category != "" && !seen[s.Category] {
			seen[s.Category] = true
			cats = append(cats, s.Category)
		}
	}
	return cats
}

func hasAnyTag(skillTags, filterTags []string) bool {
	for _, ft := range filterTags {
		for _, st := range skillTags {
			if strings.EqualFold(st, ft) {
				return true
			}
		}
	}
	return false
}

func containsTag(tags []string, query string) bool {
	for _, t := range tags {
		if strings.Contains(strings.ToLower(t), query) {
			return true
		}
	}
	return false
}

package skills

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"sort"
	"strings"

	"github.com/gratefulagents/sdk/pkg/agentsdk"
)

// Tools returns the skill search, install, and list-installed tools.
func Tools(registry *Registry, installer *Installer, workDir string) []agentsdk.Tool {
	return []agentsdk.Tool{
		&SearchTool{Registry: registry},
		&InstallTool{Installer: installer, WorkDir: workDir},
		&ListInstalledTool{Installer: installer, WorkDir: workDir},
	}
}

// SearchTool searches the skill catalog by query, category, or tag.
type SearchTool struct {
	Registry *Registry
}

func (t *SearchTool) Name() string { return "skill_search" }
func (t *SearchTool) Description() string {
	return "Search the skill catalog for MCP tools that can be installed. Use this to discover available integrations (search, browser, GitHub, Slack, etc)."
}
func (t *SearchTool) IsReadOnly() bool { return true }
func (t *SearchTool) IsEnabled(_ *agentsdk.RunContext) bool {
	return true
}
func (t *SearchTool) NeedsApproval() bool { return false }
func (t *SearchTool) TimeoutSeconds() int { return 0 }
func (t *SearchTool) InputSchema() json.RawMessage {
	return json.RawMessage(`{
		"type": "object",
		"properties": {
			"query": {"type": "string", "description": "Search query (matches name, description, tags)"},
			"category": {"type": "string", "description": "Filter by category (e.g. search, browser, developer-tools, communication, data)"}
		}
	}`)
}

func (t *SearchTool) Execute(_ context.Context, input json.RawMessage, _ string) (agentsdk.ToolResult, error) {
	if t.Registry == nil {
		return agentsdk.ToolResult{Content: "skill_search requires a configured registry", IsError: true}, nil
	}
	var in struct {
		Query    string `json:"query"`
		Category string `json:"category"`
	}
	if len(input) > 0 {
		if err := json.Unmarshal(input, &in); err != nil {
			return agentsdk.ToolResult{Content: fmt.Sprintf("Invalid input: %v", err), IsError: true}, nil
		}
	}

	var skills []SkillEntry
	if in.Query != "" {
		skills = t.Registry.Search(in.Query)
	} else {
		var opts []FilterOption
		if in.Category != "" {
			opts = append(opts, WithCategory(in.Category))
		}
		skills = t.Registry.List(opts...)
	}

	if len(skills) == 0 {
		return agentsdk.ToolResult{Content: "No skills found matching your criteria."}, nil
	}

	var sb strings.Builder
	sb.WriteString(fmt.Sprintf("Found %d skill(s):\n\n", len(skills)))
	for _, skill := range skills {
		verified := ""
		if skill.Verified {
			verified = " ✓"
		}
		sb.WriteString(fmt.Sprintf("• **%s** (v%s, %s%s)\n  %s\n  Tags: %s\n",
			skill.Name, skill.Version, skill.Category, verified, skill.Description, strings.Join(skill.Tags, ", ")))
		if len(skill.RequiresEnvVars) > 0 {
			sb.WriteString(fmt.Sprintf("  Requires env: %s\n", describeEnvVars(skill.RequiresEnvVars)))
		}
		sb.WriteString("\n")
	}
	return agentsdk.ToolResult{Content: sb.String()}, nil
}

// describeEnvVars annotates each required env var with whether it is
// currently present in the agent's environment, so callers can tell up front
// whether an installed skill will be able to authenticate.
func describeEnvVars(names []string) string {
	parts := make([]string, 0, len(names))
	for _, name := range names {
		if v, ok := os.LookupEnv(name); ok && strings.TrimSpace(v) != "" {
			parts = append(parts, name+" (set)")
		} else {
			parts = append(parts, name+" (NOT set)")
		}
	}
	return strings.Join(parts, ", ")
}

// InstallTool installs a skill from the catalog into the workspace's .mcp.json.
type InstallTool struct {
	Installer *Installer
	WorkDir   string
}

func (t *InstallTool) Name() string { return "skill_install" }
func (t *InstallTool) Description() string {
	return "Install a skill from the catalog into the workspace. This writes the MCP server config to .mcp.json. MCP configs are loaded at session start, so the new server's tools become available after the agent restarts (they are NOT available in the current session)."
}
func (t *InstallTool) IsReadOnly() bool { return false }
func (t *InstallTool) IsEnabled(ctx *agentsdk.RunContext) bool {
	return agentsdk.MutatingToolEnabled(ctx, t.Name())
}
func (t *InstallTool) NeedsApproval() bool { return false }
func (t *InstallTool) TimeoutSeconds() int { return 0 }
func (t *InstallTool) InputSchema() json.RawMessage {
	return json.RawMessage(`{
		"type": "object",
		"properties": {
			"name": {"type": "string", "description": "Skill name to install (e.g. search-duckduckgo, browser-playwright)"}
		},
		"required": ["name"]
	}`)
}

func (t *InstallTool) Execute(_ context.Context, input json.RawMessage, workDir string) (agentsdk.ToolResult, error) {
	if t.Installer == nil {
		return agentsdk.ToolResult{Content: "skill_install requires a configured installer", IsError: true}, nil
	}
	var in struct {
		Name string `json:"name"`
	}
	if err := json.Unmarshal(input, &in); err != nil {
		return agentsdk.ToolResult{Content: fmt.Sprintf("Invalid input: %v", err), IsError: true}, nil
	}

	dir := workDir
	if dir == "" {
		dir = t.WorkDir
	}

	if err := t.Installer.Install(dir, in.Name); err != nil {
		return agentsdk.ToolResult{Content: fmt.Sprintf("Failed to install skill %q: %v", in.Name, err), IsError: true}, nil
	}

	var sb strings.Builder
	sb.WriteString(fmt.Sprintf("Skill %q installed: its MCP server config was added to .mcp.json.", in.Name))
	sb.WriteString(" MCP configs are loaded at session start, so its tools become available after the agent restarts — they are NOT available in this session.")
	if skill, ok := t.Installer.Skill(in.Name); ok {
		if missing := missingEnvVars(skill.RequiresEnvVars); len(missing) > 0 {
			sb.WriteString(fmt.Sprintf("\n\nWARNING: required environment variable(s) not set: %s. The server will likely fail to authenticate until they are provided (e.g. via the host's secret mechanism or the entry's env map in .mcp.json; they are already listed in the entry's allowEnv).",
				strings.Join(missing, ", ")))
		}
	}
	return agentsdk.ToolResult{Content: sb.String()}, nil
}

// missingEnvVars returns the subset of names absent or empty in the agent's
// environment.
func missingEnvVars(names []string) []string {
	var missing []string
	for _, name := range names {
		if v, ok := os.LookupEnv(name); !ok || strings.TrimSpace(v) == "" {
			missing = append(missing, name)
		}
	}
	return missing
}

// ListInstalledTool lists skills currently installed in the workspace.
type ListInstalledTool struct {
	Installer *Installer
	WorkDir   string
}

func (t *ListInstalledTool) Name() string { return "skill_list_installed" }
func (t *ListInstalledTool) Description() string {
	return "List skills currently installed in the workspace's .mcp.json."
}
func (t *ListInstalledTool) IsReadOnly() bool { return true }
func (t *ListInstalledTool) IsEnabled(_ *agentsdk.RunContext) bool {
	return true
}
func (t *ListInstalledTool) NeedsApproval() bool { return false }
func (t *ListInstalledTool) TimeoutSeconds() int { return 0 }
func (t *ListInstalledTool) InputSchema() json.RawMessage {
	return json.RawMessage(`{"type": "object", "properties": {}}`)
}

func (t *ListInstalledTool) Execute(_ context.Context, _ json.RawMessage, workDir string) (agentsdk.ToolResult, error) {
	if t.Installer == nil {
		return agentsdk.ToolResult{Content: "skill_list_installed requires a configured installer", IsError: true}, nil
	}
	dir := workDir
	if dir == "" {
		dir = t.WorkDir
	}

	names, err := t.Installer.ListInstalled(dir)
	if err != nil {
		return agentsdk.ToolResult{Content: fmt.Sprintf("Failed to list installed skills: %v", err), IsError: true}, nil
	}

	if len(names) == 0 {
		return agentsdk.ToolResult{Content: "No skills currently installed in .mcp.json."}, nil
	}

	sort.Strings(names)
	var skills, others []string
	for _, name := range names {
		if _, ok := t.Installer.Skill(name); ok {
			skills = append(skills, name)
		} else {
			others = append(others, name)
		}
	}

	var lines []string
	if len(skills) > 0 {
		lines = append(lines, fmt.Sprintf("Installed skills: %s", strings.Join(skills, ", ")))
	} else {
		lines = append(lines, "No skills from the catalog are installed in .mcp.json.")
	}
	if len(others) > 0 {
		lines = append(lines, fmt.Sprintf("Other MCP servers in .mcp.json (not from the skill catalog): %s", strings.Join(others, ", ")))
	}
	return agentsdk.ToolResult{Content: strings.Join(lines, "\n")}, nil
}

